def _inject_dual_nav_css():
    """좌측 듀얼 내비게이션(ERP 아이콘 레일 + 세일즈 메뉴) 및 블루 사이드바 스타일.
    - 사이드바 폭을 넓혀 2컬럼(아이콘 레일 + 메뉴)이 안정적으로 들어가게 함
    - 아이콘 레일 버튼: 이모지 중심 정렬, 컴팩트
    - 세일즈 메뉴 라디오: 풀폭 메뉴 항목처럼 표시"""
    st.markdown(
        """
        <style>
        /* ══════════════════════════════════════
           사이드바 전체 = 블루 (ERP 레일 배경)
           세일즈 메뉴 패널만 흰색 오버레이
           ══════════════════════════════════════ */
        section[data-testid="stSidebar"] > div:first-child,
        section[data-testid="stSidebar"] [data-testid="stSidebarContent"] {
            background: #1565C0 !important;
        }
        section[data-testid="stSidebar"] {
            border-right: 2px solid #0D47A1 !important;
        }
        /* 사이드바 상단 로고 영역도 블루 배경 유지 */
        section[data-testid="stSidebar"] [data-testid="stSidebarUserContent"] {
            background: #1565C0 !important;
        }
        @media (min-width: 768px) {
            section[data-testid="stSidebar"] {
                min-width: 22rem !important;
                width: 22rem !important;
            }
        }

        /* ── 컬럼 레이아웃: 레일 폭 고정, 간격 없음 ── */
        section[data-testid="stSidebar"] [data-testid="stHorizontalBlock"] {
            gap: 0 !important;
            align-items: stretch !important;
        }

        /* ── ERP 아이콘 레일 컬럼 (첫 번째) ── */
        section[data-testid="stSidebar"] [data-testid="stHorizontalBlock"] > div:first-child {
            flex: 0 0 3.2rem !important;
            max-width: 3.2rem !important;
            min-width: 3.2rem !important;
            background: transparent !important;  /* 사이드바 블루를 그대로 사용 */
            padding: 0 0.2rem !important;
            overflow: visible !important;
        }

        /* ERP 타이틀 텍스트 */
        .erp-rail-title {
            font-size: 0.65rem; font-weight: 800; color: #FFFFFF !important;
            text-align: center; letter-spacing: 0.04em; margin: 4px 0 6px 0;
            white-space: nowrap; overflow: visible;
            text-shadow: 0 1px 2px rgba(0,0,0,0.25);
        }

        /* ERP 레일 아이콘 버튼: 투명 배경 + 흰색 아이콘 */
        section[data-testid="stSidebar"] [data-testid="stHorizontalBlock"] > div:first-child .stButton > button {
            padding: 0.4rem 0 !important;
            font-size: 1.1rem !important;
            line-height: 1.1 !important;
            border: 1px solid rgba(255,255,255,0.25) !important;
            background: rgba(255,255,255,0.08) !important;
            border-radius: 10px !important;
            min-width: 0 !important;
            width: 100% !important;
            color: #FFFFFF !important;
            filter: brightness(1.1);
        }
        section[data-testid="stSidebar"] [data-testid="stHorizontalBlock"] > div:first-child .stButton > button:hover {
            background: rgba(255,255,255,0.22) !important;
            border-color: rgba(255,255,255,0.6) !important;
        }

        /* ── 세일즈 메뉴 컬럼 (두 번째): 흰색 패널 ── */
        section[data-testid="stSidebar"] [data-testid="stHorizontalBlock"] > div:last-child {
            background: #FFFFFF !important;
            border-radius: 12px 12px 0 0 !important;
            padding: 0.5rem 0.5rem 1rem 0.5rem !important;
            flex: 1 1 0 !important;
            box-shadow: -2px 0 8px rgba(13,71,161,0.12) !important;
        }

        /* 세일즈 메뉴 타이틀 */
        .sales-nav-title {
            font-size: 0.68rem; font-weight: 700; color: #0D47A1;
            letter-spacing: 0.02em; margin: 2px 0 6px 2px;
        }

        /* 라디오 메뉴 */
        section[data-testid="stSidebar"] [role="radiogroup"] { gap: 1px !important; }
        section[data-testid="stSidebar"] [role="radiogroup"] > label {
            padding: 5px 8px !important;
            border-radius: 6px !important;
            margin: 0 !important;
            width: 100% !important;
            transition: background 0.12s ease;
            color: #1A2A44 !important;
        }
        section[data-testid="stSidebar"] [role="radiogroup"] > label:hover {
            background: #E3F2FD !important;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )


def _render_nav_favorites(uname: str, labels: list, idx_key: str, radio_key: str) -> None:
    """세일즈 메뉴 상단 즐겨찾기 바로가기 (사용자 지정, 세로 배치).
    ⭐ 레일 버튼이 fav_edit_mode_* 플래그를 켜면 편집 UI 표시.
    저장소는 기존 app_user_preferences.fav_menus 재사용."""
    edit_key = f"fav_edit_mode_{idx_key}"
    favs = [f for f in _get_user_fav_menus(uname) if f in labels]

    if favs and not st.session_state.get(edit_key):
        for i, label in enumerate(favs):
            if st.button(f"⭐ {label}", key=f"navfav_{idx_key}_{i}", width="stretch"):
                st.session_state[idx_key] = labels.index(label)
                st.session_state[radio_key] = label
                st.session_state.pop("active_admin_page", None)
                st.rerun()

    if st.session_state.get(edit_key):
        with st.container(border=True):
            st.caption("⭐ 자주 쓰는 메뉴 선택 (최대 5개)")
            new_favs = st.multiselect(
                "즐겨찾기", labels, default=favs, max_selections=5,
                key=f"favms_{idx_key}", label_visibility="collapsed",
            )
            b1, b2 = st.columns(2)
            if b1.button("💾 저장", key=f"favsave_{idx_key}", type="primary", width="stretch"):
                ok, err = _save_user_fav_menus(uname, new_favs)
                if ok:
                    st.session_state[edit_key] = False
                    st.toast("즐겨찾기가 저장되었습니다.", icon="⭐")
                    st.rerun()
                elif "app_user_preferences" in str(err) or "does not exist" in str(err) or "PGRST" in str(err):
                    st.error("app_user_preferences 테이블이 없습니다. SUPABASE_USER_PREFERENCES.sql 을 실행해 주세요.")
                else:
                    st.error(f"저장 실패: {err}")
            if b2.button("취소", key=f"favcancel_{idx_key}", width="stretch"):
                st.session_state[edit_key] = False
                st.rerun()


def _render_erp_icon_rail(role: str) -> None:
    """좌측 첫 번째 패널: ERP·관리자 섹션 아이콘 레일 (세로 아이콘 버튼).
    클릭 시 active_admin_page 를 설정하여 해당 화면으로 라우팅."""
    st.markdown("<div class='erp-rail-title'>ERP</div>", unsafe_allow_html=True)

    def _go(page: str):
        st.session_state["active_admin_page"] = page
        st.session_state.pop("mm_queried", None)
        st.rerun()

    if st.button("🏠", key="rail_home", help="홈 (대시보드)", width="stretch"):
        st.session_state.pop("active_admin_page", None)
        st.session_state["main_tab_idx"] = 0
        st.session_state["superadmin_menu_idx"] = 0
        for _k in ("nav_radio_main_tab_idx", "nav_radio_superadmin_menu_idx"):
            st.session_state.pop(_k, None)
        st.rerun()
    if st.button("🗓️", key="rail_erp", help="근태 관리", width="stretch"):
        _go("erp_attendance")
    if st.button("📧", key="rail_mail", help="메일 관리", width="stretch"):
        _go("gmail_manager")
    if st.button("📁", key="rail_doc", help="자료실", width="stretch"):
        _go("document_library")
    if st.button("📋", key="rail_board", help="사내업무/게시판", width="stretch"):
        _go("internal_board")
    if role in ("store_admin", "superadmin"):
        if st.button("💬", key="rail_msg", help="메시지 발송", width="stretch"):
            _go("send_message")
        if st.button("📢", key="rail_voc", help="고객의 소리(VOC)", width="stretch"):
            _go("voc_dashboard")
        if st.button("📈", key="rail_hr", help="인력 효율 분석", width="stretch"):
            _go("employee_analytics")
        if st.button("🚨", key="rail_paymon", help="결제 변경/취소 모니터링", width="stretch"):
            _go("payment_monitor")
        if st.button("💳", key="rail_margin", help="마진 모니터링", width="stretch"):
            _go("margin_monitor")
        if st.button("🏷️", key="rail_taxonomy", help="품목 분류 관리 (Gemini)", width="stretch"):
            _go("product_taxonomy")
        if st.button("🗑️", key="rail_del", help="주문 삭제 요청 관리", width="stretch"):
            _go("delete_requests")
        if st.button("⚙️", key="rail_settings", help="관리자 설정", width="stretch"):
            _go("admin_settings")
    if role == "superadmin":
        if st.button("👥", key="rail_emp", help="직원 관리", width="stretch"):
            _go("employee_management")
    # 즐겨찾기 편집 토글 (세일즈 메뉴 상단 즐겨찾기 바 편집 모드 on)
    _fav_idx_key = "superadmin_menu_idx" if role == "superadmin" else "main_tab_idx"
    if st.button("⭐", key="rail_fav", help="자주 쓰는 메뉴 설정", width="stretch"):
        _ek = f"fav_edit_mode_{_fav_idx_key}"
        st.session_state[_ek] = not st.session_state.get(_ek, False)
        st.rerun()
    if st.button("🚪", key="rail_logout", help="로그아웃", width="stretch"):
        try:
            client, _ = get_supabase_client()
            if client:
                client.auth.sign_out()
        except Exception:
            pass
        for key in list(st.session_state.keys()):
            del st.session_state[key]
        # 세션만 지우면 로그인 화면 JS가 localStorage 의 emons_auth 로
        # ?auth= 를 다시 붙여 즉시 재로그인한다. logout=1 을 남겨
        # localStorage 삭제 + 자동복구 차단이 다음 렌더에서 실행되게 한다.
        try:
            st.query_params.from_dict({"logout": "1"})
        except Exception:
            try:
                st.query_params.clear()
                st.query_params["logout"] = "1"
            except Exception:
                pass
        st.rerun()


def _render_primary_nav(user: dict, role: str) -> None:
    """좌측 두 번째 패널: 세일즈(또는 최고관리자) 메뉴 + 매장 정보 + 알림."""
    # 매장 선택 (다매장, superadmin 제외)
    allowed_stores = user.get("allowed_stores") or []
    if role != "superadmin" and len(allowed_stores) > 1:
        options = [s[2] for s in allowed_stores]
        current_sid = user.get("store_id")
        current_idx = next((i for i, s in enumerate(allowed_stores) if s[0] == current_sid), 0)
        sel_idx = st.selectbox(
            "매장 선택", range(len(options)),
            format_func=lambda i: options[i], index=current_idx, key="sidebar_store_sel",
        )
        if sel_idx != current_idx:
            st.session_state.current_user["store_id"] = allowed_stores[sel_idx][0]
            st.session_state.current_user["db_filename"] = allowed_stores[sel_idx][1]
            st.session_state.current_db = allowed_stores[sel_idx][1]
            st.rerun()

    store_display = get_store_display_name(user)
    _display_name = (
        (user.get("name") or "").strip()
        or _resolve_app_user_display_name(
            user_id=user.get("id"),
            username=user.get("username"),
        )
        or user.get("username", "")
    )
    st.markdown(
        f"<div style='padding:0.2rem 0 0.3rem 0;'>"
        f"<p style='margin:0; font-size:1.0rem; font-weight:700; color:#0D47A1;'>{html.escape(store_display)}</p>"
        f"<p style='margin:0.1rem 0 0 0; font-size:0.78rem; color:#5F6368;'>👤 {html.escape(_display_name)}</p>"
        f"</div>",
        unsafe_allow_html=True,
    )

    # 🔔 인앱 알림 배지 — 클릭 시 해당 업무(결제변경 검증 등)로 이동
    try:
        import task_board as _tb_noti  # noqa: WPS433
        _noti_uname = user.get("username") or ""
        _noti_cnt = _tb_noti.count_unread_notifications(_noti_uname) if _noti_uname else 0
        if _noti_cnt > 0:
            st.markdown(
                f"<div style='background:#ef4444; color:white; border-radius:8px;"
                f" padding:5px 10px; font-weight:700; font-size:0.85rem;"
                f" text-align:center; margin-bottom:5px;'>🔔 미확인 알림 {_noti_cnt}건</div>",
                unsafe_allow_html=True,
            )
            st.caption("알림을 누르면 해당 업무 상세로 이동합니다.")
            _recent_notis = _tb_noti.load_my_notifications_cached(_noti_uname, unread_only=True, limit=3)
            for _noti in _recent_notis:
                _nid = _noti.get("id")
                _tid = _noti.get("task_id")
                _msg = str(_noti.get("message") or "").strip() or "(내용 없음)"
                _label = _msg if len(_msg) <= 72 else (_msg[:69] + "…")
                if _tid:
                    if st.button(
                        f"🔵 {_label}",
                        key=f"sidebar_noti_open_{_nid}",
                        help="클릭하면 사내업무에서 해당 건을 엽니다.",
                        width="stretch",
                    ):
                        _navigate_to_internal_task(int(_tid), noti_id=int(_nid) if _nid else None)
                        st.rerun()
                else:
                    st.markdown(
                        f"<div style='background:#fef2f2; border-left:3px solid #ef4444;"
                        f" padding:4px 8px; border-radius:4px; margin-bottom:3px;"
                        f" font-size:0.75rem;'>🔵 {html.escape(_msg)}</div>",
                        unsafe_allow_html=True,
                    )
            if st.button("✅ 모두 읽음 처리", key="sidebar_noti_read_all", width="stretch"):
                _tb_noti.mark_all_read(_noti_uname)
                st.rerun()
    except Exception:
        pass

    st.divider()

    if role == "superadmin":
        labels = _SUPERADMIN_MENUS
        idx_key = "superadmin_menu_idx"
    else:
        labels = _get_sales_tab_labels(role)
        idx_key = "main_tab_idx"

    if idx_key not in st.session_state:
        st.session_state[idx_key] = 0
    if st.session_state[idx_key] >= len(labels):
        st.session_state[idx_key] = 0

    radio_key = f"nav_radio_{idx_key}"
    _uname = user.get("username") or ""

    # 즐겨찾기 바로가기 (사용자 지정)
    _render_nav_favorites(_uname, labels, idx_key, radio_key)

    st.markdown("<div class='sales-nav-title'>📋 메뉴</div>", unsafe_allow_html=True)

    # 라디오 위젯 초기값을 현재 인덱스와 동기화
    _cur_idx = st.session_state[idx_key]
    if radio_key not in st.session_state:
        st.session_state[radio_key] = labels[_cur_idx]
    elif st.session_state[radio_key] not in labels:
        st.session_state[radio_key] = labels[_cur_idx]

    def _on_nav_change():
        # 세일즈 메뉴 선택 시, 열려있던 ERP/관리자 화면 라우팅 해제
        st.session_state.pop("active_admin_page", None)

    sel = st.radio(
        "메뉴", labels, key=radio_key,
        label_visibility="collapsed", on_change=_on_nav_change,
    )
    st.session_state[idx_key] = labels.index(sel)

    # 일반 직원 전용: 비밀번호 변경 (관리자 설정이 없으므로 여기 제공)
    if role == "user":
        with st.expander("🔐 비밀번호 변경"):
            _sb_new_pw = st.text_input("새 비밀번호", type="password", key="sidebar_new_pw_input")
            _sb_pw_confirm = st.text_input("새 비밀번호 확인", type="password", key="sidebar_new_pw_confirm")
            if st.button("비밀번호 변경", key="sidebar_change_pw_btn"):
                if not _sb_new_pw:
                    st.error("새 비밀번호를 입력해 주세요.")
                elif len(_sb_new_pw) < 6:
                    st.error("비밀번호는 6자 이상이어야 합니다.")
                elif _sb_new_pw != _sb_pw_confirm:
                    st.error("새 비밀번호가 일치하지 않습니다.")
                else:
                    _sb_auth_cli, _sb_auth_err = get_supabase_client_with_auth_session()
                    if _sb_auth_err:
                        st.error(f"⚠️ {_sb_auth_err}")
                    else:
                        try:
                            _sb_auth_cli.auth.update_user({"password": _sb_new_pw})
                            flash("비밀번호가 변경되었습니다. 다음 로그인부터 새 비밀번호를 사용하세요.")
                            st.rerun()
                        except Exception as _sb_e:
                            st.error(f"비밀번호 변경에 실패했습니다: {str(_sb_e)}")


def _render_left_dual_nav(user: dict, role: str) -> None:
    """좌측 듀얼 사이드바 렌더: [로고] + [ERP 아이콘 레일 | 세일즈 메뉴]."""
    with st.sidebar:
        raw_logo_html = _common_logo_html(
            _resolve_logo_path(), fallback_id="emons-logo-fallback-sidebar",
        )
        # 로고 클릭 → ?home=1 로 이동해 세일즈 대시보드 홈 복귀.
        # st.markdown 은 inline onclick(문자열 이벤트 핸들러)을 실행하지 않으므로
        # 서버에서 기존 쿼리 파라미터(auth 세션 토큰 등)를 보존한 <a href> 링크로 렌더링.
        try:
            _home_qp = dict(st.query_params)
        except Exception:
            _home_qp = {}
        _home_qp["home"] = "1"
        _home_href = "?" + urllib.parse.urlencode(_home_qp, doseq=True)
        clickable_logo_html = (
            f'<a href="{html.escape(_home_href)}" target="_self" title="세일즈 대시보드 홈으로"'
            f' style="text-decoration:none; display:block; cursor:pointer;">'
            f'{raw_logo_html}</a>'
        )
        st.markdown(clickable_logo_html, unsafe_allow_html=True)
        c_rail, c_nav = st.columns([1, 2.8], gap="small")  # CSS로 gap=0 처리됨
        with c_rail:
            _render_erp_icon_rail(role)
        with c_nav:
            _render_primary_nav(user, role)


# ========== Supabase 연결 (st.secrets 기반) ==========
# Customers·Sales는 Supabase 테이블 사용. id(기본키) 기준으로만 단일 행 조회/수정하여 중복·오조회 방지.
def _sales_tenant_column() -> str | None:
    """Sales 테이블 테넌트 구분 컬럼명. secrets에 sales_tenant_column이 있고 비어있지 않을 때만 사용. 없거나 비면 None(테넌트 컬럼 미사용)."""
    try:
        val = (st.secrets.get("supabase") or {}).get("sales_tenant_column")
        if val is None or str(val).strip() == "":
            return None
        return str(val).strip()
    except Exception:
        return None


def _customers_tenant_column() -> str | None:
    """Customers 테이블 테넌트 구분 컬럼명. secrets에 customers_tenant_column이 있고 비어있지 않을 때만 사용. 없거나 비면 None(컬럼 미사용)."""
    try:
        val = (st.secrets.get("supabase") or {}).get("customers_tenant_column")
        if val is None or str(val).strip() == "":
            return None
        return str(val).strip()
    except Exception:
        return None


def _reassert_supabase_client_key(client, key: str) -> None:
    """
    supabase-py 는 client.auth.sign_in_with_password() 가 성공하면 내부적으로
    SIGNED_IN 이벤트를 발생시켜, 공유 클라이언트의 기본 Authorization 헤더를
    (service_role/anon 키가 아니라) 방금 로그인한 사용자 자신의 access_token 으로
    자동 교체해버린다 (supabase/_sync/client.py `_listen_to_auth_events`).
    get_supabase_client() 은 이 클라이언트를 앱 전역에서 재사용하므로, 로그인 직후
    이어지는 app_users 조회 등이 의도치 않게 낮은 권한(authenticated 롤)으로 나가
    RLS/권한 오류가 발생할 수 있다. 매 호출 시 postgrest 요청 인증을 원래 키로
    재적용해 이 오염을 원상복구한다.
    """
    try:
        client.postgrest.auth(key)
    except Exception:
        pass


def get_supabase_client():
    """
    Supabase 클라이언트 반환 (Singleton). 동일 URL/Key면 한 번만 생성 후 재사용.
    반환: (client, None) 또는 (None, error_message).
    """
    global _supabase_client_cache
    if _create_supabase_client is None:
        return None, "Supabase 라이브러리가 설치되지 않았습니다. pip install supabase 를 실행해 주세요."
    try:
        secrets = st.secrets.get("supabase") or {}
        url = (secrets.get("url") or "").strip()
        # service_role 키가 있으면 우선 사용 (RLS 우회) — 없으면 anon 키 사용
        key = (
            secrets.get("service_role_key")
            or secrets.get("service_role")
            or secrets.get("key")
            or secrets.get("anon_key")
            or ""
        ).strip()
        if not url or not key:
            return None, "Supabase URL 또는 Key가 설정되지 않았습니다. .streamlit/secrets.toml에 [supabase] url, key를 추가해 주세요."
        # 캐시된 클라이언트가 있고 URL/Key가 동일하면 재사용 (연결 중복 생성 방지)
        if _supabase_client_cache is not None:
            _client, _url, _key = _supabase_client_cache
            if _url == url and _key == key:
                _reassert_supabase_client_key(_client, key)
                return _client, None
        client = _create_supabase_client(url, key)
        _supabase_client_cache = (client, url, key)
        return client, None
    except Exception as e:
        err_msg = str(e)
        if not err_msg or err_msg.strip() == "":
            err_msg = "연결 오류가 발생했습니다."
        return None, f"Supabase 연결에 실패했습니다: {err_msg}"


def _get_supabase_key_source_diag() -> str:
    """현재 st.secrets 가 실제로 어떤 키(service_role_key 등)를 쓰고 있는지 진단 문자열.
    로그인 실패 시 '배포 secrets 반영 여부'를 화면에서 바로 확인하기 위한 용도."""
    try:
        secrets = st.secrets.get("supabase") or {}
    except Exception:
        return "secrets 읽기 실패"
    for _name in ("service_role_key", "service_role", "key", "anon_key"):
        _v = (secrets.get(_name) or "").strip()
        if _v:
            return f"{_name}(len={len(_v)}, prefix={_v[:8]}...)"
    return "키 없음(secrets [supabase] 섹션 비어있음)"


def get_supabase_client_or_warn():
    """Supabase 클라이언트 반환 (내부적으로 Singleton 재사용). 실패 시 화면에 경고를 띄우고 None 반환."""
    client, err = get_supabase_client()
    if err:
        st.error(f"⚠️ {err}")
        return None
    return client


def get_supabase_client_with_auth_session():
    """
    로그인된 사용자의 Supabase 세션을 복원한 클라이언트 반환.
    비밀번호 변경(update_user) 등 인증이 필요한 API 호출 시 사용.
    반환: (client, None) 또는 (None, error_message).
    """
    client, err = get_supabase_client()
    if err or client is None:
        return None, err or "Supabase 클라이언트를 사용할 수 없습니다."
    sess = st.session_state.get("supabase_session")
    if isinstance(sess, dict) and sess.get("access_token") and sess.get("refresh_token"):
        try:
            client.auth.set_session(sess["access_token"], sess["refresh_token"])
        except Exception as e:
            return None, f"세션 복원 실패: {str(e)}"
    return client, None


def get_supabase_admin_client():
    """
    Supabase Admin API용 클라이언트 (service_role_key) — Singleton.
    직원 계정 생성 등 관리자 전용 작업 시 사용. 동일 설정이면 한 번만 생성 후 재사용.
    반환: (client, None) 또는 (None, error_message).
    """
    global _supabase_admin_client_cache
    if _create_supabase_client is None:
        return None, "Supabase 라이브러리가 설치되지 않았습니다."
    try:
        secrets = st.secrets.get("supabase") or {}
        url = (secrets.get("url") or "").strip()
        if not url:
            return None, "Supabase URL이 설정되지 않았습니다."
        key = (secrets.get("service_role_key") or os.environ.get("SUPABASE_SERVICE_ROLE_KEY") or "").strip()
        if not key:
            return None, "직원 계정 생성을 위해 Supabase service_role_key가 필요합니다. .streamlit/secrets.toml에 [supabase] service_role_key를 추가하거나, 환경변수 SUPABASE_SERVICE_ROLE_KEY를 설정해 주세요."
        if _supabase_admin_client_cache is not None:
            _client, _url, _key = _supabase_admin_client_cache
            if _url == url and _key == key:
                return _client, None
        client = _create_supabase_client(url, key)
        _supabase_admin_client_cache = (client, url, key)
        return client, None
    except Exception as e:
        err_msg = str(e).strip() or "연결 오류가 발생했습니다."
        return None, f"Supabase Admin 연결 실패: {err_msg}"


def _supabase_auth_uid_by_email(admin_client, email: str):
    """
    Supabase Auth에서 이메일로 사용자 UUID 조회. list_users는 기본 50명만 반환하므로 페이지네이션으로 전체 검색.
    반환: auth.users.id (UUID 문자열) 또는 None.
    """
    if not admin_client or not email or not str(email).strip():
        return None
    target = str(email).strip().lower()
    page = 1
    # Supabase Auth list_users 기본/안정 페이지 크기(환경별 인자 무시 대비)
    per_page = 50
    while True:
        try:
            r = admin_client.auth.admin.list_users(per_page=per_page, page=page)
        except TypeError:
            try:
                r = admin_client.auth.admin.list_users({"per_page": per_page, "page": page})
            except Exception:
                r = admin_client.auth.admin.list_users()
        # 일부 SDK 환경에서는 list_users가 list를 직접 반환함
        if isinstance(r, list):
            users = r
        else:
            users_raw = getattr(r, "users", None)
            if users_raw is None:
                users_raw = getattr(r, "data", None)
            # SDK 버전에 따라 data가 모델 객체일 수 있으므로 model_dump를 폭넓게 시도
            if users_raw is None and hasattr(r, "model_dump"):
                try:
                    users_raw = r.model_dump()
                except Exception:
                    users_raw = None
            if users_raw is not None and hasattr(users_raw, "model_dump"):
                try:
                    users_raw = users_raw.model_dump()
                except Exception:
                    pass
            # SDK/버전별 응답 형태를 모두 흡수해 users(list)로 정규화
            users = []
            if isinstance(users_raw, list):
                users = users_raw
            elif isinstance(users_raw, dict):
                if isinstance(users_raw.get("users"), list):
                    users = users_raw.get("users") or []
                elif isinstance(users_raw.get("data"), list):
                    users = users_raw.get("data") or []
                elif isinstance(users_raw.get("data"), dict) and isinstance((users_raw.get("data") or {}).get("users"), list):
                    users = (users_raw.get("data") or {}).get("users") or []
            elif hasattr(users_raw, "users"):
                maybe_users = getattr(users_raw, "users", None)
                if isinstance(maybe_users, list):
                    users = maybe_users
            elif hasattr(users_raw, "data"):
                maybe_data = getattr(users_raw, "data", None)
                if isinstance(maybe_data, list):
                    users = maybe_data
                elif hasattr(maybe_data, "users") and isinstance(getattr(maybe_data, "users", None), list):
                    users = getattr(maybe_data, "users")
        for u in (users or []):
            em = getattr(u, "email", None) if hasattr(u, "email") else (u.get("email") if isinstance(u, dict) else None)
            if em and str(em).strip().lower() == target:
                uid = getattr(u, "id", None) if hasattr(u, "id") else (u.get("id") if isinstance(u, dict) else None)
                return uid
        if not users or len(users) < per_page:
            break
        page += 1
        if page > 100:
            break
    return None


# ---------- Supabase 직원/매장 테이블 (app_users, app_user_stores, app_stores) ----------
# 테이블이 없으면 ensure_supabase_app_tables()로 자동 생성 시도(database_url 있을 때) 또는 SQL Editor에서 SUPABASE_APP_TABLES.sql 실행.
# 아래 매장/직원 목록 등은 @st.cache_data(ttl=600)로 10분 캐시. 매장·직원 추가/수정/삭제 후 반드시 clear_data_cache() 호출하면 즉시 갱신됨.

def _supabase_app_tables_available():
    """Supabase에 app_users 테이블이 있는지 확인. 세션당 1회만 HTTP 쿼리 후 결과를 세션 캐시."""
    _cache_key = "_supa_app_tables_avail"
    if _cache_key in st.session_state:
        return st.session_state[_cache_key]
    client, err = get_supabase_client()
    if err or not client:
        st.session_state["_login_diag_error"] = f"Supabase 클라이언트 생성 실패: {err}"
        return False
    try:
        client.table("app_users").select("id").limit(1).execute()
        st.session_state[_cache_key] = True
        return True
    except Exception as e:
        st.session_state[_cache_key] = False
        st.session_state["_login_diag_error"] = (
            f"app_users 테이블 접근 실패: {type(e).__name__}: {e} "
            f"[사용된 키: {_get_supabase_key_source_diag()}]"
        )
        return False


def _supabase_run_sql_file(db_url: str, sql_path: str) -> bool:
    """psycopg2로 SQL 파일을 Supabase에 실행. 성공 시 True."""
    try:
        import psycopg2
    except ImportError:
        return False
    if not os.path.isfile(sql_path):
        return False
    try:
        with open(sql_path, "r", encoding="utf-8") as f:
            raw = f.read()
    except Exception:
        return False
    lines = []
    for line in raw.splitlines():
        s = line.strip()
        if s.startswith("--") or not s:
            continue
        lines.append(line)
    raw_clean = "\n".join(lines)
    statements = []
    for part in raw_clean.split(";"):
        s = part.strip()
        if s and not s.upper().startswith("--"):
            statements.append(s + ";")
    if not statements:
        return False
    conn = None
    try:
        conn = psycopg2.connect(db_url)
        conn.autocommit = True
        cur = conn.cursor()
        for stmt in statements:
            stmt = stmt.strip()
            if not stmt or stmt == ";":
                continue
            try:
                cur.execute(stmt)
            except Exception as e:
                err_msg = str(e).lower()
                if "already exists" not in err_msg and "duplicate" not in err_msg:
                    try:
                        cur.close()
                        conn.close()
                    except Exception:
                        pass
                    return False
        cur.close()
        return True
    except Exception:
        return False
    finally:
        if conn and not conn.closed:
            try:
                conn.close()
            except Exception:
                pass


def _supabase_run_app_tables_sql():
    """
    Supabase DB에 app_stores, app_users, app_user_stores, app_edit_requests 테이블이 없으면 생성.
    st.secrets의 supabase.database_url (Postgres 연결 문자열)이 있으면 psycopg2로 DDL 실행.
    성공 시 True, 실패 또는 URL 없음 시 False.
    """
    secrets = (st.secrets.get("supabase") or {}) if "secrets" in dir(st) else {}
    if not secrets:
        try:
            import streamlit as _st
            secrets = _st.secrets.get("supabase") or {}
        except Exception:
            pass
    db_url = (secrets.get("database_url") or secrets.get("db_url") or "").strip()
    if not db_url:
        return False
    sql_files = [
        "SUPABASE_APP_TABLES.sql",
        "SUPABASE_APP_STORES_IS_ACTIVE.sql",
        "SUPABASE_APP_EDIT_REQUESTS.sql",
        "SUPABASE_APP_ERP_ATTENDANCE.sql",
        "SUPABASE_APP_USERS_HIREDATE.sql",
        "SUPABASE_APP_EMPLOYEE_SALARIES.sql",
        "SUPABASE_APP_USERS_PHONE.sql",
        "SUPABASE_APP_TASKS.sql",
        "SUPABASE_APP_PAYMENT_CHANGE_REQUESTS.sql",
        "SUPABASE_APP_TASKS_CATEGORY.sql",
        "SUPABASE_APP_TASKS_TAGS.sql",
        "SUPABASE_APP_TASKS_SCOPE.sql",
        "SUPABASE_APP_POSTS.sql",
        "SUPABASE_APP_BANK_ACCOUNTS.sql",
        "SUPABASE_APP_DEPOSITS.sql",
        "SUPABASE_APP_WORK_ADJ_LONG_SERVICE.sql",
        "SUPABASE_APP_WORK_ADJ_EARLY_LEAVE.sql",
        "SUPABASE_APP_ATTENDANCE_CLEANUP.sql",
    ]
    ok = False
    for fname in sql_files:
        fpath = os.path.join(BASE_DIR, fname)
        if os.path.isfile(fpath):
            _supabase_run_sql_file(db_url, fpath)
            ok = True
    return ok


def ensure_supabase_app_tables():
    """
    Supabase에 직원/매장용 테이블(app_users, app_user_stores, app_stores)이 있는지 확인.
    없으면 database_url로 자동 생성 시도. 성공 시 True, 아니면 False.
    """
    if _supabase_app_tables_available():
        ensure_supabase_task_tables()
        return True
    if _supabase_run_app_tables_sql():
        ok = _supabase_app_tables_available()
        ensure_supabase_task_tables()
        return ok
    return False


def _supabase_task_tables_available() -> bool:
    """app_tasks 테이블 존재 여부 (사내 업무판)."""
    _cache_key = "_supa_task_tables_avail"
    if _cache_key in st.session_state:
        return bool(st.session_state[_cache_key])
    client, err = get_supabase_client()
    if err or not client:
        return False
    try:
        client.table("app_tasks").select("id").limit(1).execute()
        st.session_state[_cache_key] = True
        return True
    except Exception:
        st.session_state[_cache_key] = False
        return False


def _supabase_run_task_tables_sql() -> bool:
    """사내 업무판 전용 DDL (phone 컬럼 + app_tasks 등)."""
    secrets = (st.secrets.get("supabase") or {}) if "secrets" in dir(st) else {}
    if not secrets:
        try:
            import streamlit as _st
            secrets = _st.secrets.get("supabase") or {}
        except Exception:
            pass
    db_url = (secrets.get("database_url") or secrets.get("db_url") or "").strip()
    if not db_url:
        return False
    ok = False
    for fname in ("SUPABASE_APP_USERS_PHONE.sql", "SUPABASE_APP_TASKS.sql",
                  "SUPABASE_APP_PAYMENT_CHANGE_REQUESTS.sql",
                  "SUPABASE_APP_TASKS_CATEGORY.sql",
                  "SUPABASE_APP_TASKS_TAGS.sql",
                  "SUPABASE_APP_TASKS_SCOPE.sql",
                  "SUPABASE_APP_POSTS.sql",
                  "SUPABASE_APP_BANK_ACCOUNTS.sql",
                  "SUPABASE_APP_DEPOSITS.sql",
                  "SUPABASE_APP_WORK_ADJ_LONG_SERVICE.sql"):
        fpath = os.path.join(BASE_DIR, fname)
        if os.path.isfile(fpath) and _supabase_run_sql_file(db_url, fpath):
            ok = True
    return ok


def ensure_supabase_task_tables() -> bool:
    """사내 업무판 테이블이 없으면 자동 생성 시도."""
    _cache_key = "_supa_task_tables_avail"
    if _supabase_task_tables_available():
        return True
    if _cache_key in st.session_state:
        del st.session_state[_cache_key]
    if _supabase_run_task_tables_sql():
        if _cache_key in st.session_state:
            del st.session_state[_cache_key]
        return _supabase_task_tables_available()
    return False


