@st.cache_data(ttl=3600)
def _get_supabase_stores_list_raw():
    """Supabase app_stores 원본 목록 캐시 (내부용, 활성/폐점 모두 포함).
    is_active 컬럼이 없는 구 스키마에서도 동작하도록 폴백 처리.
    매장 추가/수정 후 clear_data_cache() 호출 시 갱신."""
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        r = client.table("app_stores").select("id, store_name, db_filename, is_active, closed_at").order("id").execute()
        rows = (r.data or []) if hasattr(r, "data") else []
    except Exception:
        # is_active/closed_at 컬럼이 아직 없는 경우 폴백 (SUPABASE_APP_STORES_IS_ACTIVE.sql 미실행)
        try:
            r = client.table("app_stores").select("id, store_name, db_filename").order("id").execute()
            rows = (r.data or []) if hasattr(r, "data") else []
        except Exception:
            return []
    # is_active 기본값 True (구 스키마 호환)
    for row in rows:
        if "is_active" not in row or row.get("is_active") is None:
            row["is_active"] = True
    return rows


def _get_supabase_stores_list(include_inactive: bool = False):
    """Supabase app_stores 목록. 기본은 활성 매장만 반환 (is_active=True).
    include_inactive=True 시 폐점 매장도 포함 (슈퍼관리자 매장 관리 UI 전용).
    """
    rows = _get_supabase_stores_list_raw()
    if include_inactive:
        return list(rows)
    return [r for r in rows if bool(r.get("is_active", True))]


def get_supabase_stores_dataframe_cached(include_inactive: bool = False):
    """
    Supabase app_stores 매장 목록을 DataFrame으로 반환.
    기본은 활성 매장만 반환. include_inactive=True 시 폐점 매장도 포함.
    반환: DataFrame 컬럼 id, store_name, db_filename, is_active, closed_at (빈 DataFrame일 수 있음).
    """
    data = _get_supabase_stores_list(include_inactive=include_inactive)
    if not data:
        return pd.DataFrame(columns=["id", "store_name", "db_filename", "is_active", "closed_at"])
    df = pd.DataFrame(data)
    if "is_active" not in df.columns:
        df["is_active"] = True
    if "closed_at" not in df.columns:
        df["closed_at"] = None
    if "id" in df.columns:
        df = df.sort_values("id", ignore_index=True)
    return df


def _get_supabase_app_user_by_email(email: str):
    """
    Supabase app_users에서 이메일로 사용자 조회.
    반환: (id, username, role, store_id, db_filename) 또는 None.
    """
    if not email or not str(email).strip():
        return None
    client, err = get_supabase_client()
    if err or not client:
        st.session_state["_login_diag_error"] = f"Supabase 클라이언트 생성 실패: {err}"
        return None
    try:
        st.session_state.pop("_login_diag_error", None)
        email_clean = str(email).strip().lower()
        r = client.table("app_users").select("id, username, role, store_id").eq("email", email_clean).execute()
        rows = (r.data or []) if hasattr(r, "data") else []
        if not rows:
            return None
        row = rows[0]
        uid, username, role, store_id = row.get("id"), row.get("username"), row.get("role"), row.get("store_id")
        db_filename = ""
        first_sid = store_id
        if not first_sid:
            us = client.table("app_user_stores").select("store_id").eq("user_id", uid).limit(1).execute()
            if us.data and us.data[0].get("store_id"):
                first_sid = us.data[0]["store_id"]
        if first_sid:
            s = client.table("app_stores").select("db_filename").eq("id", first_sid).maybe_single().execute()
            if s.data and s.data.get("db_filename"):
                db_filename = s.data["db_filename"]
        return (uid, username, role, store_id, db_filename)
    except Exception as e:
        st.session_state["_login_diag_error"] = (
            f"app_users 조회 실패: {type(e).__name__}: {e} "
            f"[사용된 키: {_get_supabase_key_source_diag()}]"
        )
        return None


@st.cache_data(ttl=1800)
def _get_supabase_user_allowed_stores(user_id: int):
    """접근 가능 매장 목록 캐시 (30분). 로그인 사용자별로 캐시되며, 배정 변경 시 clear_data_cache()로 갱신."""
    if not user_id:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        us = client.table("app_user_stores").select("store_id").eq("user_id", user_id).execute()
        store_ids = [x["store_id"] for x in (us.data or [])]
        if not store_ids:
            row = client.table("app_users").select("store_id").eq("id", user_id).maybe_single().execute()
            if row.data and row.data.get("store_id"):
                store_ids = [row.data["store_id"]]
        if not store_ids:
            return []
        out = []
        for sid in store_ids:
            s = client.table("app_stores").select("id, db_filename, store_name").eq("id", sid).maybe_single().execute()
            if s.data:
                out.append((s.data["id"], s.data["db_filename"], s.data["store_name"]))
        return sorted(out, key=lambda x: (x[2] or "", x[0]))
    except Exception:
        return []


@st.cache_data(ttl=3600)
def _get_supabase_store_by_db_filename(db_filename: str):
    """db_filename → store id 조회. @st.cache_data 1시간 캐시. 매장 변경 시 clear_data_cache()로 갱신."""
    if not db_filename:
        return None
    client, err = get_supabase_client()
    if err or not client:
        return None
    try:
        r = client.table("app_stores").select("id").eq("db_filename", db_filename).maybe_single().execute()
        return r.data.get("id") if r.data else None
    except Exception:
        return None


def _ensure_supabase_superadmin_email(email_clean: str):
    """app_users에서 username=superadmin인 행에 email 설정 (billymind@gmail.com 복구용)."""
    client, err = get_supabase_client()
    if err or not client:
        return
    try:
        client.table("app_users").update({"email": email_clean}).eq("username", "superadmin").execute()
    except Exception:
        pass


@st.cache_data(ttl=600)
def _get_supabase_store_assigned_employee_names(db_filename: str) -> list:
    store_id = _get_supabase_store_by_db_filename(db_filename)
    if not store_id:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        us = client.table("app_user_stores").select("user_id").eq("store_id", store_id).execute()
        user_ids = [x["user_id"] for x in (us.data or [])]
        if not user_ids:
            u = client.table("app_users").select("id").eq("store_id", store_id).execute()
            user_ids = [x["id"] for x in (u.data or [])]
        if not user_ids:
            return []

        r = client.table("app_users").select("name, username").in_("id", user_ids).execute()
        out = []
        for user_data in (r.data or []):
            nm = str(user_data.get("name") or "").strip()
            un = str(user_data.get("username") or "").strip()
            display = nm or _email_local_part(un) or un or None
            if display and display not in out:
                out.append(display)
        return out
    except Exception:
        return []


@st.cache_data(ttl=3600)
def _get_supabase_users_list():
    """Supabase app_users 전체 목록 캐시 (10분). 직원 추가/수정 후 clear_data_cache() 호출 시 갱신.
    select('*')로 실제 존재하는 모든 컬럼을 가져오므로, 마이그레이션 진행 상태와 무관하게
    있는 컬럼(phone 등)은 항상 결과에 포함된다."""
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        r = client.table("app_users").select("*").order("username").execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception:
        # 최후 폴백: 핵심 컬럼만
        try:
            r = client.table("app_users").select("id, username, email, role, name, store_id").order("username").execute()
            return (r.data or []) if hasattr(r, "data") else []
        except Exception:
            return []


def _get_app_user_display_name_map():
    """
    이메일/username → 표시명(name 우선, 없으면 username) 매핑. To-Do 작성자 등 표기용.
    캐시된 _get_supabase_users_list() 활용으로 매번 쿼리하지 않음.
    """
    users = _get_supabase_users_list()
    out = {}
    for u in users:
        name = (str(u.get("name") or "").strip() or str(u.get("username") or "").strip()) or ""
        if name:
            if u.get("email"):
                out[str(u["email"]).strip().lower()] = name
            if u.get("username"):
                out[str(u["username"]).strip()] = name
                out[str(u["username"]).strip().lower()] = name
    return out


@st.cache_data(ttl=3600)
def _get_supabase_user_store_ids(user_id: int):
    """한 직원의 배정 매장 id 목록 (Supabase app_user_stores). 1시간 캐시.
    매장/직원 배정 변경 시 clear_data_cache()로 갱신."""
    if not user_id:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        r = client.table("app_user_stores").select("store_id").eq("user_id", user_id).execute()
        return [x["store_id"] for x in (r.data or [])]
    except Exception:
        return []


@st.cache_data(ttl=3600)
def _get_supabase_employee_list_with_stores():
    """직원 명부 + 배정매장 문자열 캐시 (10분). 직원/매장 변경 시 clear_data_cache()로 갱신."""
    users = _get_supabase_users_list()
    if not users:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return [{"id": u["id"], "email": u.get("email"), "username": u.get("username"), "name": u.get("name"), "role": u.get("role"), "배정매장": ""} for u in users]
    store_names_by_id = {}
    try:
        stores_r = client.table("app_stores").select("id, store_name").execute()
        for s in (stores_r.data or []):
            store_names_by_id[s["id"]] = s.get("store_name") or ""
    except Exception:
        pass
    out = []
    for u in users:
        uid = u.get("id")
        store_ids = _get_supabase_user_store_ids(uid)
        names = [store_names_by_id.get(sid, "") for sid in store_ids if sid]
        배정매장 = ", ".join(n for n in names if n)
        if not 배정매장 and u.get("store_id"):
            배정매장 = store_names_by_id.get(u["store_id"], "") or ""
        # 기본 매장: app_users.store_id 기준
        primary_sid = u.get("store_id")
        기본매장 = store_names_by_id.get(primary_sid, "") if primary_sid else ""
        out.append({
            "id": uid,
            "email": u.get("email"),
            "username": u.get("username"),
            "name": u.get("name"),
            "role": u.get("role"),
            "phone": u.get("phone") or "",
            "배정매장": 배정매장,
            "기본매장": 기본매장,
        })
    return out


def _supabase_insert_app_user(username: str, email: str, role: str, store_id, name: str, phone: str | None = None):
    """app_users에 한 행 삽입 (비밀번호는 Supabase Auth에서 관리하므로 placeholder 저장). 반환: (user_id, None) 또는 (None, error_msg)."""
    client, err = get_supabase_client()
    if err or not client:
        return None, (err or "Supabase 연결 불가")
    try:
        pw_placeholder = hashlib.sha256("supabase_managed".encode()).hexdigest()
        email_clean = (email or "").strip().lower() or None
        row = {
            "username": (username or "").strip(),
            "password": pw_placeholder,
            "email": email_clean,
            "role": (role or "user").strip(),
            "store_id": int(store_id) if store_id is not None else None,
            "name": (name or "").strip() or None,
            "phone": (phone or "").strip() or None,
        }

        def _insert(_row: dict):
            return client.table("app_users").insert(_row).execute()

        try:
            r = _insert(row)
        except Exception as ie:
            # phone 컬럼이 없는 경우(PGRST204) phone 제외 후 재시도
            iemsg = str(ie)
            if "PGRST204" in iemsg or "schema cache" in iemsg.lower() or "could not find" in iemsg.lower():
                row.pop("phone", None)
                r = _insert(row)
            else:
                raise
        data = (r.data if hasattr(r, "data") else None)
        if data is not None and len(data) > 0:
            row_data = data[0] if isinstance(data, list) else data
            uid = row_data.get("id") if isinstance(row_data, dict) else None
            if uid is not None:
                return int(uid), None
        if email_clean:
            existing = client.table("app_users").select("id").eq("email", email_clean).maybe_single().execute()
            if existing.data and existing.data.get("id") is not None:
                return int(existing.data["id"]), None
        return None, "insert 후 id를 가져오지 못했습니다."
    except Exception as e:
        return None, str(e)


def _supabase_update_app_user(user_id: int, name: str, role: str, store_id, store_ids: list,
                              phone: str | None = None, kakao_notify_enabled: bool | None = None) -> list[str]:
    """app_users 한 행 수정 + app_user_stores 교체.
    반환: 저장되지 않은 컬럼 이름 목록(예: ['phone']). 컬럼 누락(PGRST204) 시 해당 컬럼 제외 후 재시도.
    그 외 오류는 예외로 던짐."""
    client, err = get_supabase_client()
    if err or not client:
        raise RuntimeError(err or "Supabase 연결 불가")
    patch: dict = {
        "name": (name or "").strip() or None,
        "role": role,
        "store_id": store_id,
    }
    if phone is not None:
        patch["phone"] = (phone or "").strip() or None
    if kakao_notify_enabled is not None:
        patch["kakao_notify_enabled"] = bool(kakao_notify_enabled)
    skipped: list[str] = []
    try:
        client.table("app_users").update(patch).eq("id", user_id).execute()
    except Exception as e:
        emsg = str(e)
        if "PGRST204" in emsg or "schema cache" in emsg.lower() or "could not find" in emsg.lower():
            base_cols = {"name", "role", "store_id"}
            safe_patch = {k: v for k, v in patch.items() if k in base_cols}
            skipped = [k for k in patch.keys() if k not in base_cols]
            client.table("app_users").update(safe_patch).eq("id", user_id).execute()
        else:
            raise
    client.table("app_user_stores").delete().eq("user_id", user_id).execute()
    for sid in (store_ids or []):
        client.table("app_user_stores").insert({"user_id": user_id, "store_id": sid}).execute()
    return skipped


def _supabase_delete_app_user(user_id: int):
    """app_user_stores 삭제 후 app_users 삭제. 에러 시 예외."""
    client, err = get_supabase_client()
    if err or not client:
        raise RuntimeError(err or "Supabase 연결 불가")
    client.table("app_user_stores").delete().eq("user_id", user_id).execute()
    client.table("app_users").delete().eq("id", user_id).execute()


def _supabase_get_app_user_by_email(email: str):
    """이메일로 app_users 한 행 조회. 없으면 None."""
    if not email or not str(email).strip():
        return None
    client, err = get_supabase_client()
    if err or not client:
        return None
    try:
        r = client.table("app_users").select("id, username, email, role, store_id, name").eq("email", str(email).strip().lower()).maybe_single().execute()
        return r.data if r.data else None
    except Exception:
        return None


def _get_customer_name_supabase(db_filename: str, customer_id: int) -> str:
    """Supabase app_customers 테이블에서 id(기본키)·store_name 기준으로 고객명 조회."""
    client, err = get_supabase_client()
    if err or not customer_id:
        return ""
    store_name = _get_current_store_name_for_customers(db_filename)
    if not store_name:
        return ""
    try:
        q = client.table("app_customers").select("name").eq("id", int(customer_id)).eq("store_name", store_name)
        r = q.maybe_single().execute()
        row = r.data[0] if isinstance(r.data, list) and r.data else (r.data if isinstance(r.data, dict) else None)
        if row and row.get("name"):
            return (row["name"] or "").strip()
    except Exception:
        pass
    return ""


def _get_customers_by_ids_supabase(db_filename: str, customer_ids: list) -> dict:
    """Supabase app_customers에서 id 목록·store_name으로 고객 조회. 반환: { id: { name, phone1, phone2, address }, ... }"""
    if not customer_ids:
        return {}
    client, err = get_supabase_client()
    if err:
        return {}
    store_name = _get_current_store_name_for_customers(db_filename)
    if not store_name:
        return {}
    try:
        q = client.table("app_customers").select("id, name, phone1, phone2, address").eq("store_name", store_name).in_("id", customer_ids)
        r = q.execute()
        return {row["id"]: row for row in (r.data or [])}
    except Exception:
        return {}



def _format_number_comma(s):
    """숫자만 추출 후 천 단위 콤마 포맷 (화면 표시용)."""
    if s is None or s == "":
        return ""
    digits = re.sub(r"\D", "", str(s))
    if not digits:
        return ""
    return f"{int(digits):,}"


def _format_signed_number_comma(s):
    """선행 + / - 는 유지하고 숫자 부분만 천 단위 콤마 (증감액 입력용)."""
    if s is None:
        return ""
    raw = str(s).strip()
    if raw == "":
        return ""
    sign = ""
    body = raw
    if body[0] in "+-":
        sign = body[0]
        body = body[1:].strip()
    digits = re.sub(r"\D", "", body)
    if not digits:
        return sign
    return sign + f"{int(digits):,}"


def _parse_comma_to_int(s):
    """콤마 포함 문자열을 정수로 변환 (DB 저장·잔금 계산용)."""
    if s is None or s == "":
        return 0
    return int(re.sub(r"\D", "", str(s)) or 0)


def _fmt_num(x):
    """글로벌 숫자 포맷: 금액/숫자에 천 단위 콤마 적용 (화면 출력용)."""
    if x is None or (isinstance(x, float) and pd.isna(x)):
        return ""
    try:
        v = float(x)
        if v != int(v):
            return f"{v:,.1f}"
        return f"{int(v):,}"
    except (TypeError, ValueError):
        return str(x)


def _format_df_display(df, num_columns):
    """DataFrame의 지정 컬럼을 천 단위 콤마 문자열로 변환한 복사본 반환 (st.dataframe 표시용)."""
    out = df.copy()
    for col in num_columns:
        if col not in out.columns:
            continue
        out[col] = out[col].apply(_fmt_num)
    return out


def _style_overdue_unpaid_rows(df: pd.DataFrame, overdue_mask):
    """배송일이 지났고 잔금이 남은 행을 빨간 경고 배경으로 표시."""
    if overdue_mask is None or not isinstance(overdue_mask, pd.Series):
        overdue_mask = pd.Series(False, index=df.index)
    else:
        overdue_mask = overdue_mask.reindex(df.index).fillna(False).astype(bool)

    def _hl(row):
        if bool(overdue_mask.loc[row.name]):
            return ["background-color: #ffe6e6; color: #b30000; font-weight: 600;"] * len(row)
        return [""] * len(row)

    return df.style.apply(_hl, axis=1)


def _format_phone_hyphen(s):
    """숫자만 입력된 전화번호를 010-1234-5678 형식으로 포맷."""
    if s is None or s == "":
        return ""
    digits = re.sub(r"\D", "", str(s))
    if not digits:
        return ""
    n = len(digits)
    if n <= 3:
        return digits
    if n <= 7:
        return f"{digits[:3]}-{digits[3:]}"
    if digits.startswith("02") and n == 9:
        return f"{digits[:2]}-{digits[2:6]}-{digits[6:]}"
    return f"{digits[:3]}-{digits[3:7]}-{digits[7:11]}"


# 결제 수단·카드사·수수료율 (가구 매장 결제 로직)
PAYMENT_METHOD_OPTIONS = ["신용카드", "메인페이", "체크카드", "지역화폐", "계좌이체", "온누리", "현금(수금)", "온누리지류"]
# 신용카드·체크카드 공용 카드사 목록
CARD_COMPANY_OPTIONS = [
    "신한카드", "KB국민카드", "우리카드", "NH농협카드", "하나카드",
    "카카오뱅크", "토스뱅크", "케이뱅크",
    "삼성카드", "현대카드", "롯데카드", "BC카드", "기타",
]
# 체크카드 선택 시 카드사 표시 대상 수단 (신용카드·체크카드 동일 목록 사용)
_CARD_WITH_COMPANY = ("신용카드", "체크카드")


def _payment_fee_amount(payment_method: str, amount: int) -> float:
    """결제 수단별 수수료: 신용카드·메인페이 2.5%, 체크카드 1.5%, 그 외(현금·이체 등) 0%."""
    if not payment_method or amount <= 0:
        return 0.0
    if payment_method in ("신용카드", "메인페이"):
        return round(float(amount) * 0.025, 0)
    if payment_method == "체크카드":
        return round(float(amount) * 0.015, 0)
    return 0.0


def _compute_net_margin_rate(selling_price: float, cost: float, total_fee: float) -> float:
    """실질 마진율(%) = (판매가 - 원가 - 수수료) / 판매가 * 100. 판매가 0이면 0 반환."""
    if not selling_price or selling_price <= 0:
        return 0.0
    net_profit = selling_price - cost - total_fee
    return round((net_profit / selling_price) * 100.0, 1)


def _kpi_employee_names_cell_is_blank(val: object) -> bool:
    """sales/주문의 employee_names 셀이 비었거나 NaN·문자열 'nan' 등인지 (KPI 집계 시 결측으로 취급)."""
    if val is None:
        return True
    if isinstance(val, float) and pd.isna(val):
        return True
    if pd.isna(val):
        return True
    s = str(val).strip()
    if not s:
        return True
    if s.lower() in ("nan", "none", "null", "<na>", "nat"):
        return True
    return False


def _kpi_parse_employee_list(raw: object) -> list[str]:
    """employee_names 필드를 콤마 분리 직원 목록으로 파싱. NaN·'nan' 문자열 등은 빈 목록."""
    if _kpi_employee_names_cell_is_blank(raw):
        return []
    parts = [p.strip() for p in str(raw).split(",") if p.strip()]
    return [p for p in parts if p.lower() not in ("nan", "none", "null", "<na>")]


def _kpi_sanitize_employee_label(raw: object) -> str:
    """주문 employee_names에서 KPI용 단일 문자열(보완용). 비었으면 ''."""
    emps = _kpi_parse_employee_list(raw)
    return ",".join(emps) if emps else ""


# ─────────────────────────────────────────────────────────────────────
# 직원 KPI 가중치 (매장별/전체통합 × 연월 단위) — Supabase app_employee_kpi_weights
# 설정이 없으면 기본값 70/15/5/10 사용. 과거 월은 그 월에 저장된 값을 그대로 사용.
# ─────────────────────────────────────────────────────────────────────

DEFAULT_KPI_WEIGHTS = {"revenue": 70.0, "margin": 15.0, "display": 5.0, "cash": 10.0}
KPI_WEIGHTS_ALL_SCOPE = "__all__"


def _kpi_weights_ym(year: int, month: int) -> str:
    return f"{int(year):04d}-{int(month):02d}"


def _kpi_weights_from_row(row: dict | None) -> dict:
    """DB row → 가중치 dict. 결측 필드는 기본값으로 폴백."""
    if not row:
        return dict(DEFAULT_KPI_WEIGHTS)
    def _f(k, dv):
        v = row.get(k)
        try:
            return float(v) if v is not None else float(dv)
        except (TypeError, ValueError):
            return float(dv)
    return {
        "revenue": _f("w_revenue", DEFAULT_KPI_WEIGHTS["revenue"]),
        "margin":  _f("w_margin",  DEFAULT_KPI_WEIGHTS["margin"]),
        "display": _f("w_display", DEFAULT_KPI_WEIGHTS["display"]),
        "cash":    _f("w_cash",    DEFAULT_KPI_WEIGHTS["cash"]),
    }


@st.cache_data(ttl=120)
def _load_kpi_weights_cached(scope_key: str, year_month: str) -> dict:
    """(scope, YYYY-MM) 가중치를 캐시로 조회. 없으면 기본값. 저장/삭제 후 clear() 필수."""
    if not scope_key or not year_month:
        return dict(DEFAULT_KPI_WEIGHTS)
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return dict(DEFAULT_KPI_WEIGHTS)
        r = (
            sc.table("app_employee_kpi_weights")
            .select("w_revenue, w_margin, w_display, w_cash")
            .eq("db_filename", scope_key)
            .eq("year_month", year_month)
            .limit(1)
            .execute()
        )
        rows = r.data or []
        if not rows:
            return dict(DEFAULT_KPI_WEIGHTS)
        return _kpi_weights_from_row(rows[0])
    except Exception:
        return dict(DEFAULT_KPI_WEIGHTS)


def load_kpi_weights(db_filename: str | None, year: int, month: int, *, all_stores: bool = False) -> dict:
    """앱 코드에서 호출하는 공개 헬퍼. all_stores=True면 __all__ 스코프.
    개별 매장은 db_filename 필수. 잘못된 인자는 기본값 반환."""
    ym = _kpi_weights_ym(year, month)
    scope = KPI_WEIGHTS_ALL_SCOPE if all_stores else (db_filename or "")
    if not scope:
        return dict(DEFAULT_KPI_WEIGHTS)
    return _load_kpi_weights_cached(scope, ym)


def save_kpi_weights(
    scope_key: str,
    year: int,
    month: int,
    weights: dict,
    updated_by: str | None,
) -> tuple[bool, str | None]:
    """(scope, YYYY-MM) upsert. 합=100 검증."""
    if not scope_key:
        return False, "스코프가 지정되지 않았습니다."
    try:
        w = {
            "w_revenue": float(weights.get("revenue", 0)),
            "w_margin":  float(weights.get("margin", 0)),
            "w_display": float(weights.get("display", 0)),
            "w_cash":    float(weights.get("cash", 0)),
        }
    except (TypeError, ValueError):
        return False, "가중치는 숫자여야 합니다."
    total = w["w_revenue"] + w["w_margin"] + w["w_display"] + w["w_cash"]
    if abs(total - 100.0) > 0.01:
        return False, f"가중치 합이 100이 아닙니다. (현재 합: {total:g})"
    if any(v < 0 for v in w.values()):
        return False, "가중치는 0 이상이어야 합니다."
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return False, err or "Supabase 연결 불가"
        payload = {
            "db_filename": scope_key,
            "year_month": _kpi_weights_ym(year, month),
            **w,
            "updated_by": (updated_by or "").strip() or None,
            "updated_at": datetime.now(tz=KST).isoformat(),
        }
        sc.table("app_employee_kpi_weights").upsert(
            payload, on_conflict="db_filename,year_month"
        ).execute()
        _load_kpi_weights_cached.clear()
        return True, None
    except Exception as e:
        return False, str(e)


def delete_kpi_weights(scope_key: str, year: int, month: int) -> tuple[bool, str | None]:
    """(scope, YYYY-MM) 삭제 → 기본값(70/15/5/10) 폴백."""
    if not scope_key:
        return False, "스코프가 지정되지 않았습니다."
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return False, err or "Supabase 연결 불가"
        sc.table("app_employee_kpi_weights").delete()\
            .eq("db_filename", scope_key)\
            .eq("year_month", _kpi_weights_ym(year, month))\
            .execute()
        _load_kpi_weights_cached.clear()
        return True, None
    except Exception as e:
        return False, str(e)


def list_kpi_weights(scope_key: str, limit: int = 24) -> list[dict]:
    """스코프의 최근 저장 목록(최신 연월 순). 관리자 설정 UI에서 표시용."""
    if not scope_key:
        return []
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return []
        r = (
            sc.table("app_employee_kpi_weights")
            .select("year_month, w_revenue, w_margin, w_display, w_cash, updated_by, updated_at")
            .eq("db_filename", scope_key)
            .order("year_month", desc=True)
            .limit(int(limit))
            .execute()
        )
        return r.data or []
    except Exception:
        return []


def _kpi_score_col_names(w: dict) -> dict:
    """가중치 dict → 표시용 점수 컬럼명. 소수는 첫자리, 정수는 정수로."""
    def _fmt(v: float) -> str:
        v = float(v or 0)
        return f"{v:g}"
    return {
        "revenue": f"매출 점수({_fmt(w['revenue'])})",
        "margin":  f"마진 점수({_fmt(w['margin'])})",
        "display": f"전시품 점수({_fmt(w['display'])})",
        "cash":    f"현금수금 점수({_fmt(w['cash'])})",
    }


def _apply_kpi_score_columns(emp_df: "pd.DataFrame", w: dict) -> tuple["pd.DataFrame", dict]:
    """emp_df(revenue/margin/display_sales/kpi_receipt 합계 열 보유)에 점수·종합 열 추가.
    반환: (emp_df, {'revenue': 컬럼명, 'margin': ..., 'display': ..., 'cash': ..., 'total': '종합 점수'})"""
    if emp_df is None or emp_df.empty:
        return emp_df, {**_kpi_score_col_names(w), "total": "종합 점수"}
    total_revenue = float(emp_df["revenue"].sum() or 0)
    total_margin = float(emp_df["margin"].sum() or 0)
    total_display = float(emp_df["display_sales"].sum() or 0)
    total_cash = float(emp_df["kpi_receipt"].sum() or 0)
    cols = _kpi_score_col_names(w)
    emp_df[cols["revenue"]] = (
        (emp_df["revenue"] / total_revenue * float(w["revenue"])) if total_revenue else 0.0
    )
    emp_df[cols["margin"]] = (
        (emp_df["margin"] / total_margin * float(w["margin"])) if total_margin else 0.0
    )
    emp_df[cols["display"]] = (
        (emp_df["display_sales"] / total_display * float(w["display"])) if total_display else 0.0
    )
    emp_df[cols["cash"]] = (
        (emp_df["kpi_receipt"] / total_cash * float(w["cash"])) if total_cash else 0.0
    )
    for _k in ("revenue", "margin", "display", "cash"):
        emp_df[cols[_k]] = pd.to_numeric(emp_df[cols[_k]], errors="coerce").fillna(0.0).round(1)
    emp_df["종합 점수"] = (
        emp_df[cols["revenue"]] + emp_df[cols["margin"]]
        + emp_df[cols["display"]] + emp_df[cols["cash"]]
    ).round(1)
    return emp_df, {**cols, "total": "종합 점수"}


def _kpi_weights_caption(w: dict) -> str:
    """캡션에 사용할 종합 점수 공식 문자열."""
    def _fmt(v: float) -> str:
        return f"{float(v or 0):g}"
    return (
        f"매출 {_fmt(w['revenue'])} + 마진 {_fmt(w['margin'])} "
        f"+ 전시품 {_fmt(w['display'])} + 현금수금 {_fmt(w['cash'])}"
    )


# ─────────────────────────────────────────────────────────────────────
# 외부 결제내역 대사 (온누리 디지털 / 울산페이 등) — Supabase app_external_pay_*
# 관리자가 가맹점 포털에서 받은 파일을 업로드 → 파싱 → ERP 결제와 매칭.
# 재업로드 시 fingerprint UNIQUE 로 중복 적재 방지. row_id UNIQUE 로 재매칭 방지.
# ─────────────────────────────────────────────────────────────────────

EXT_PAY_DEFAULT_VERIFY_FROM = date(2026, 8, 1)


def _ext_pay_load_settings(db_filename: str) -> date:
    """매장 검증 시작일 조회. 미저장이면 EXT_PAY_DEFAULT_VERIFY_FROM(2026-08-01)."""
    if not db_filename:
        return EXT_PAY_DEFAULT_VERIFY_FROM
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return EXT_PAY_DEFAULT_VERIFY_FROM
        r = (
            sc.table("app_external_pay_settings")
            .select("verify_from_date")
            .eq("db_filename", db_filename)
            .limit(1)
            .execute()
        )
        rows = r.data or []
        if not rows:
            return EXT_PAY_DEFAULT_VERIFY_FROM
        raw = rows[0].get("verify_from_date")
        if not raw:
            return EXT_PAY_DEFAULT_VERIFY_FROM
        return datetime.fromisoformat(str(raw)[:10]).date()
    except Exception:
        return EXT_PAY_DEFAULT_VERIFY_FROM


def _ext_pay_save_settings(db_filename: str, verify_from: date, updated_by: str | None) -> tuple[bool, str | None]:
    """검증 시작일 upsert."""
    if not db_filename:
        return False, "매장이 지정되지 않았습니다."
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return False, err or "Supabase 연결 불가"
        payload = {
            "db_filename": db_filename,
            "verify_from_date": verify_from.isoformat(),
            "updated_by": (updated_by or "").strip() or None,
            "updated_at": datetime.now(tz=KST).isoformat(),
        }
        sc.table("app_external_pay_settings").upsert(
            payload, on_conflict="db_filename"
        ).execute()
        return True, None
    except Exception as e:
        return False, str(e)


def _ext_pay_safe_raw(raw) -> dict | None:
    """raw_json 을 JSON 직렬화 가능한 dict 로 정규화. 실패 시 None."""
    if not raw:
        return None
    try:
        import json as _json
        return _json.loads(_json.dumps(raw, default=str, ensure_ascii=False))
    except Exception:
        return None


def _ext_pay_select_paged(sc, table: str, columns: str, apply_filters, order_col: str = "id") -> list:
    """PostgREST 1000행 상한을 넘어 페이지네이션으로 전체 조회."""
    page = 1000
    all_rows: list = []
    offset = 0
    while True:
        q = apply_filters(sc.table(table).select(columns))
        q = q.order(order_col).range(offset, offset + page - 1)
        r = q.execute()
        rows = r.data or []
        all_rows.extend(rows)
        if len(rows) < page:
            break
        offset += page
    return all_rows


def _ext_pay_list_batches(db_filename: str, limit: int = 20) -> list[dict]:
    """매장 업로드 이력. 출처·업로더 무관 — 다른 관리자도 동일하게 조회."""
    if not db_filename:
        return []
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return []
        r = (
            sc.table("app_external_pay_batches")
            .select("id, source, file_name, parsed_count, inserted_count, skipped_count, uploaded_by, uploaded_at")
            .eq("db_filename", db_filename)
            .order("uploaded_at", desc=True)
            .limit(int(limit))
            .execute()
        )
        return r.data or []
    except Exception:
        return []


def _ext_pay_count_rows(db_filename: str, source: str | None = None) -> int:
    """저장된 공식 행 수. 날짜 필터 없이 저장 여부 확인용."""
    if not db_filename:
        return 0
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return 0
        q = sc.table("app_external_pay_rows").select("id", count="exact").eq("db_filename", db_filename)
        if source:
            q = q.eq("source", source)
        r = q.limit(1).execute()
        if getattr(r, "count", None) is not None:
            return int(r.count)
        return len(r.data or [])
    except Exception:
        return 0


_ONNURI_HEADER_ALIASES = {
    "tx_date":       ("거래일자", "거래일", "결제일자", "결제일", "일자"),
    "tx_time":       ("거래시간", "결제시간", "시간"),
    "phone":         ("구매자전화번호", "구매자 전화번호", "휴대폰번호", "전화번호", "구매자연락처"),
    "amount":        ("결제금액(원)", "결제금액", "금액", "거래금액", "판매금액"),
    "tx_status":     ("거래상태", "결제상태", "상태"),
    "settle_status": ("정산상태", "정산 상태"),
    "buyer_name":    ("구매자명", "구매자", "이름"),
    "approval_code": ("승인번호", "거래번호", "결제번호"),
}


def _ext_pay_norm_header(h: str) -> str:
    return re.sub(r"\s+", "", str(h or "")).strip()


_ULSANPAY_HEADER_ALIASES = {
    "tx_date":       ("거래일시", "거래일자", "거래일", "결제일자", "결제일"),
    "tx_time":       ("거래일시", "거래시간", "결제시간", "시간"),
    # 금액은 반드시 '결제금액'(오타 '결재금액' 허용). '거래금액'은 쓰지 않음.
    "amount":        ("결제금액", "결재금액"),
    "approval_code": (
        "승인번호", "승인 번호", "승인번호(6자리)", "승인코드",
        "승인no", "승인No", "Approval",
    ),
    "tx_status":     ("거래상태", "결제상태", "상태", "구분"),
}


def _ext_pay_map_columns(df_columns, aliases: dict | None = None) -> dict[str, str]:
    """실제 컬럼명을 canonical key로 매핑. 못 찾으면 해당 key 없음."""
    alias_map = aliases or _ONNURI_HEADER_ALIASES
    normalized = { _ext_pay_norm_header(c): c for c in df_columns }
    out: dict[str, str] = {}
    for key, names in alias_map.items():
        for a in names:
            hit = normalized.get(_ext_pay_norm_header(a))
            if hit is not None:
                out[key] = hit
                break
    return out


def _ext_pay_digits_only(s) -> str:
    if s is None:
        return ""
    return re.sub(r"\D", "", str(s))


def _ext_pay_parse_amount(v) -> int | None:
    """금액 문자열/숫자 → 정수. '12,300원' 등 허용."""
    if v is None:
        return None
    if isinstance(v, (int,)):
        return int(v)
    if isinstance(v, float):
        if v != v:  # NaN
            return None
        return int(round(v))
    s = str(v).strip()
    if not s:
        return None
    s2 = re.sub(r"[^\d\-]", "", s)
    if not s2 or s2 in ("-",):
        return None
    try:
        return int(s2)
    except (TypeError, ValueError):
        return None


def _ext_pay_parse_date(v) -> str | None:
    """다양한 포맷 → 'YYYY-MM-DD'."""
    if v is None:
        return None
    if isinstance(v, (datetime, date)):
        d = v.date() if isinstance(v, datetime) else v
        return d.isoformat()
    s = str(v).strip()
    if not s:
        return None
    s2 = re.sub(r"[./]", "-", s)
    s2 = s2.split(" ")[0]
    try:
        return datetime.fromisoformat(s2[:10]).date().isoformat()
    except ValueError:
        try:
            return datetime.strptime(s2[:10], "%Y-%m-%d").date().isoformat()
        except ValueError:
            return None


def _ext_pay_parse_time(v) -> str | None:
    """다양한 포맷 → 'HH:MM:SS'."""
    if v is None:
        return None
    if isinstance(v, dt_time):
        return v.strftime("%H:%M:%S")
    if isinstance(v, datetime):
        return v.strftime("%H:%M:%S")
    s = str(v).strip()
    if not s:
        return None
    # 날짜+시간이 함께 온 경우 뒤쪽 시간만 사용
    m = re.search(r"(\d{1,2}):(\d{2})(?::(\d{2}))?", s)
    if not m:
        return None
    hh = int(m.group(1))
    mm = int(m.group(2))
    ss = int(m.group(3) or 0)
    if not (0 <= hh < 24 and 0 <= mm < 60 and 0 <= ss < 60):
        return None
    return f"{hh:02d}:{mm:02d}:{ss:02d}"


def _ext_pay_fingerprint(source: str, db_filename: str, tx_date: str, tx_time: str | None,
                         phone_last4: str | None, amount: int, tx_status: str | None,
                         approval_code: str | None = None) -> str:
    """공식 파일 1행의 지문.
    온누리: `source|db|date|time|phone_last4|amount|tx_status`
    울산페이: 뒤에 `|approval_code` 를 붙여 승인번호 6자리로 구분."""
    parts = [
        (source or "").strip(),
        (db_filename or "").strip(),
        (tx_date or "").strip(),
        (tx_time or "").strip(),
        (phone_last4 or "").strip(),
        str(int(amount)) if amount is not None else "",
        (tx_status or "").strip(),
    ]
    if (source or "").strip() == "ulsanpay":
        parts.append(_ext_pay_norm_approval6(approval_code))
    return "|".join(parts)


def _ext_pay_parse_onnuri_file(uploaded_file) -> tuple[list[dict], str | None]:
    """온누리 파일(xlsx/csv) → 정규화된 행 리스트. 반환: (rows, error_or_None).
    각 행: {tx_date, tx_time, phone_last4, amount, tx_status, settle_status, buyer_name_masked, approval_code, raw}."""
    if uploaded_file is None:
        return [], "파일이 없습니다."
    fname = getattr(uploaded_file, "name", "") or ""
    ext = fname.lower().rsplit(".", 1)[-1] if "." in fname else ""
    try:
        if ext == "csv":
            try:
                df = pd.read_csv(uploaded_file, dtype=str)
            except UnicodeDecodeError:
                try:
                    uploaded_file.seek(0)
                except Exception:
                    pass
                df = pd.read_csv(uploaded_file, dtype=str, encoding="cp949")
        else:
            df = pd.read_excel(uploaded_file, dtype=str)
    except Exception as e:
        return [], f"파일 읽기 실패: {e}"
    if df is None or df.empty:
        return [], "파일에 데이터가 없습니다."

    # 상단 가맹점명/사업자번호 행 스킵 → 거래일자·구매자전화번호 헤더 승격
    df = _ext_pay_promote_header_row(df, {"거래일자", "결제일자", "거래일", "구매자전화번호", "결제금액(원)", "결제금액"})

    colmap = _ext_pay_map_columns(df.columns)
    required = ("tx_date", "amount", "phone")
    if not all(k in colmap for k in required):
        return [], (
            "필수 컬럼(거래일자, 구매자전화번호, 결제금액)을 찾을 수 없습니다. "
            f"감지된 컬럼: {list(df.columns)}"
        )

    out: list[dict] = []
    for _, row in df.iterrows():
        tx_date = _ext_pay_parse_date(row.get(colmap["tx_date"])) if "tx_date" in colmap else None
        if not tx_date:
            continue
        amt = _ext_pay_parse_amount(row.get(colmap["amount"])) if "amount" in colmap else None
        if amt is None:
            continue
        tx_time = _ext_pay_parse_time(row.get(colmap["tx_time"])) if "tx_time" in colmap else None
        phone_last4 = None
        if "phone" in colmap:
            digits = _ext_pay_digits_only(row.get(colmap["phone"]))
            if digits:
                phone_last4 = digits[-4:]
        tx_status = str(row.get(colmap["tx_status"]) or "").strip() if "tx_status" in colmap else ""
        settle_status = str(row.get(colmap["settle_status"]) or "").strip() if "settle_status" in colmap else ""
        buyer = str(row.get(colmap["buyer_name"]) or "").strip() if "buyer_name" in colmap else ""
        appr = str(row.get(colmap["approval_code"]) or "").strip() if "approval_code" in colmap else ""
        raw = {k: (None if pd.isna(v) else str(v)) for k, v in row.items() if v is not None}
        out.append({
            "tx_date": tx_date,
            "tx_time": tx_time,
            "phone_last4": phone_last4,
            "amount": int(amt),
            "tx_status": tx_status or None,
            "settle_status": settle_status or None,
            "buyer_name_masked": buyer or None,
            "approval_code": appr or None,
            "raw": raw,
        })
    return out, None


def _ext_pay_read_uploaded_df(uploaded_file) -> tuple["pd.DataFrame | None", str | None]:
    """xlsx/csv 로드. 반환: (df, error_or_None)."""
    if uploaded_file is None:
        return None, "파일이 없습니다."
    fname = getattr(uploaded_file, "name", "") or ""
    ext = fname.lower().rsplit(".", 1)[-1] if "." in fname else ""
    try:
        if ext == "csv":
            try:
                df = pd.read_csv(uploaded_file, dtype=str)
            except UnicodeDecodeError:
                try:
                    uploaded_file.seek(0)
                except Exception:
                    pass
                df = pd.read_csv(uploaded_file, dtype=str, encoding="cp949")
        else:
            df = pd.read_excel(uploaded_file, dtype=str)
    except Exception as e:
        return None, f"파일 읽기 실패: {e}"
    if df is None or df.empty:
        return None, "파일에 데이터가 없습니다."
    return df, None


def _ext_pay_promote_header_row(df: "pd.DataFrame", header_tokens: set[str]) -> "pd.DataFrame":
    """상단 매장정보 행을 건너뛰고, header_tokens 가 있는 행을 컬럼으로 승격."""
    tokens = {_ext_pay_norm_header(t) for t in header_tokens}

    def _norm_list(vals) -> list[str]:
        return [_ext_pay_norm_header(v) for v in vals]

    if any(_ext_pay_norm_header(c) in tokens for c in df.columns):
        return df
    for i in range(min(len(df), 20)):
        row_vals = _norm_list(df.iloc[i].tolist())
        if any(v in tokens for v in row_vals):
            new_cols = df.iloc[i].tolist()
            df = df.iloc[i + 1:].reset_index(drop=True)
            df.columns = new_cols
            break
    return df


def _ext_pay_parse_ulsanpay_file(uploaded_file) -> tuple[list[dict], str | None]:
    """울산페이 거래내역서 → 정규화 행.
    금액: 결제금액(오타 결재금액 허용). 식별자: 승인번호 6자리.
    거래일시(YYYY/MM/DD HH:MM:SS)에서 날짜·시간을 분리."""
    df, err = _ext_pay_read_uploaded_df(uploaded_file)
    if err:
        return [], err
    df = _ext_pay_promote_header_row(df, {"거래일시", "승인번호", "결제금액", "결재금액"})
    colmap = _ext_pay_map_columns(df.columns, _ULSANPAY_HEADER_ALIASES)
    if "tx_date" not in colmap or "amount" not in colmap or "approval_code" not in colmap:
        return [], (
            "필수 컬럼(거래일시, 승인번호, 결제금액)을 찾을 수 없습니다. "
            f"감지된 컬럼: {list(df.columns)}"
        )

    out: list[dict] = []
    for _, row in df.iterrows():
        raw_dt = row.get(colmap["tx_date"])
        tx_date = _ext_pay_parse_date(raw_dt)
        if not tx_date:
            continue
        tx_time = _ext_pay_parse_time(raw_dt)
        if not tx_time and "tx_time" in colmap:
            tx_time = _ext_pay_parse_time(row.get(colmap["tx_time"]))
        amt = _ext_pay_parse_amount(row.get(colmap["amount"]))
        if amt is None:
            continue
        appr = _ext_pay_norm_approval6(row.get(colmap["approval_code"]))
        if not appr:
            continue
        tx_status = str(row.get(colmap["tx_status"]) or "").strip() if "tx_status" in colmap else ""
        raw = {k: (None if pd.isna(v) else str(v)) for k, v in row.items() if v is not None}
        out.append({
            "tx_date": tx_date,
            "tx_time": tx_time,
            "phone_last4": None,
            "amount": int(amt),
            "tx_status": tx_status or None,
            "settle_status": None,
            "buyer_name_masked": None,
            "approval_code": appr,
            "raw": raw,
        })
    return out, None


def _ext_pay_is_cancel_status(status: str | None) -> bool:
    if not status:
        return False
    return "취소" in str(status)


def _ext_pay_norm_approval6(v) -> str:
    """울산페이 승인번호 6자리. 앞자리 0 유지. 5자리 이하는 왼쪽에 0을 채움.
    float 43927.0 이 '439270'으로 깨지지 않게 정수부만 사용."""
    if v is None:
        return ""
    if isinstance(v, float):
        if v != v:
            return ""
        digits = re.sub(r"\D", "", str(int(round(v))))
    elif isinstance(v, int):
        digits = re.sub(r"\D", "", str(v))
    else:
        s = str(v).replace("\u00a0", " ").replace("\u3000", " ")
        s = s.strip().strip("'\"`")
        s = re.sub(r"\s+", "", s)
        if re.fullmatch(r"\d+\.0+", s):
            s = s.split(".", 1)[0]
        digits = re.sub(r"\D", "", s)
    if not digits:
        return ""
    if len(digits) > 6:
        return digits[-6:]
    return digits.zfill(6)


def _ext_pay_approval_alts(v) -> list[str]:
    """승인번호 비교 후보. Excel 숫자 43927.0 → 자릿수 '439270' 오인을 포함."""
    ap = _ext_pay_norm_approval6(v)
    if not ap:
        return []
    out = [ap]
    if len(ap) == 6 and ap.endswith("0") and not ap.startswith("0"):
        alt = ap[:5].zfill(6)
        if alt not in out:
            out.append(alt)
    if len(ap) == 6 and ap.startswith("0") and not ap.endswith("0"):
        alt = ap[1:] + "0"
        if alt not in out:
            out.append(alt)
    return out


def _ext_pay_approvals_equal(a, b) -> bool:
    sa, sb = set(_ext_pay_approval_alts(a)), set(_ext_pay_approval_alts(b))
    return bool(sa and sb and (sa & sb))


def _ext_pay_pair_cancel_offsets(items: list[dict]) -> list[tuple[dict, dict]]:
    """동일 승인번호·동일 절대금액의 (ERP취소된 공식결제, 공식취소) 쌍.
    items 키: approval, abs_amount, result_code, is_official_cancel, order_has_neg.
    """
    groups: dict[tuple[str, int], dict[str, list]] = {}
    for it in items:
        ap = str(it.get("approval") or "").strip()
        if not ap:
            continue
        try:
            abs_amt = int(it.get("abs_amount") or 0)
        except (TypeError, ValueError):
            continue
        if abs_amt <= 0:
            continue
        g = groups.setdefault((ap, abs_amt), {"paid": [], "cancel": []})
        code = it.get("result_code") or ""
        if it.get("is_official_cancel") and code in ("official_canceled", "official_only", "미매칭"):
            g["cancel"].append(it)
        elif not it.get("is_official_cancel"):
            if code == "erp_canceled_official_paid" or (
                code == "matched_ok" and it.get("order_has_neg")
            ):
                g["paid"].append(it)
    pairs: list[tuple[dict, dict]] = []
    for g in groups.values():
        n = min(len(g["paid"]), len(g["cancel"]))
        for i in range(n):
            pairs.append((g["paid"][i], g["cancel"][i]))
    return pairs


def _ext_pay_offset_ulsan_cancels(sc, db_filename: str) -> int:
    """저장된 울산페이 매칭에서 동일 승인번호 취소 상계. 갱신 행 수 반환."""
    if not sc or not db_filename:
        return 0
    try:
        def _filt_rows(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        rows = _ext_pay_select_paged(
            sc, "app_external_pay_rows",
            "id, tx_date, amount, tx_status, approval_code",
            _filt_rows, order_col="id",
        )
        def _filt_m(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        matches = _ext_pay_select_paged(
            sc, "app_external_pay_matches",
            "id, row_id, payment_id, order_id, customer_id, result_code, note",
            _filt_m, order_col="id",
        )
    except Exception:
        return 0
    m_by_row = {int(m["row_id"]): m for m in matches if m.get("row_id") is not None}
    items: list[dict] = []
    order_ids: list[int] = []
    for r in rows:
        try:
            rid = int(r["id"])
        except (TypeError, ValueError, KeyError):
            continue
        m = m_by_row.get(rid)
        if not m:
            continue
        try:
            amt = int(r.get("amount") or 0)
        except (TypeError, ValueError):
            amt = 0
        oid = m.get("order_id")
        try:
            oid_int = int(oid) if oid is not None else None
        except (TypeError, ValueError):
            oid_int = None
        items.append({
            "row_id": rid,
            "approval": _ext_pay_norm_approval6(r.get("approval_code")),
            "abs_amount": abs(amt),
            "result_code": m.get("result_code") or "",
            "is_official_cancel": _ext_pay_is_cancel_status(r.get("tx_status")) or amt < 0,
            "order_id": oid_int,
            "payment_id": m.get("payment_id"),
            "customer_id": m.get("customer_id"),
            "tx_date": str(r.get("tx_date") or "")[:10],
            "order_has_neg": False,
        })
        if oid_int is not None:
            order_ids.append(oid_int)
    neg_by_order: dict[int, dict] = {}
    uniq_oids = sorted(set(order_ids))
    for chunk in (uniq_oids[i : i + 200] for i in range(0, len(uniq_oids), 200)):
        try:
            pr = (
                sc.table("app_payments")
                .select("id, order_id, amount, payment_date, payment_method, card_company")
                .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                .in_("order_id", chunk)
                .lt("amount", 0)
                .execute()
            )
            for p in pr.data or []:
                if "지역화폐" not in str(p.get("payment_method") or ""):
                    continue
                try:
                    oid = int(p["order_id"])
                except (TypeError, ValueError, KeyError):
                    continue
                if oid not in neg_by_order:
                    neg_by_order[oid] = p
        except Exception:
            continue
    for it in items:
        if it["order_id"] is not None and it["order_id"] in neg_by_order:
            it["order_has_neg"] = True
    pairs = _ext_pay_pair_cancel_offsets(items)
    updated = 0
    for paid, cancel in pairs:
        note = f"동일 승인번호 취소 상계 (공식취소일 {cancel.get('tx_date') or ''})"
        try:
            sc.table("app_external_pay_matches").update({
                "result_code": "matched_ok",
                "note": note,
            }).eq("db_filename", db_filename).eq("row_id", int(paid["row_id"])).execute()
            updated += 1
        except Exception:
            continue
        cancel_payload = {"result_code": "matched_ok", "note": note}
        if paid.get("order_id") is not None:
            cancel_payload["order_id"] = paid["order_id"]
            if paid.get("customer_id") is not None:
                cancel_payload["customer_id"] = paid["customer_id"]
        neg = neg_by_order.get(paid["order_id"]) if paid.get("order_id") is not None else None
        if neg and neg.get("id") is not None:
            try:
                cancel_payload["payment_id"] = int(neg["id"])
            except (TypeError, ValueError):
                pass
        elif paid.get("payment_id") is not None:
            cancel_payload["payment_id"] = paid["payment_id"]
        try:
            sc.table("app_external_pay_matches").update(cancel_payload).eq(
                "db_filename", db_filename
            ).eq("row_id", int(cancel["row_id"])).execute()
            updated += 1
        except Exception:
            continue
    return updated


def _ext_pay_rematch_ulsan_zeropad(sc, db_filename: str) -> int:
    """앞자리 0 정규화 후 official_only를 ERP와 다시 매칭. 갱신 행 수 반환."""
    if not sc or not db_filename:
        return 0
    try:
        def _filt_rows(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        rows = _ext_pay_select_paged(
            sc, "app_external_pay_rows",
            "id, amount, tx_status, approval_code",
            _filt_rows, order_col="id",
        )
        def _filt_m(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        matches = _ext_pay_select_paged(
            sc, "app_external_pay_matches",
            "row_id, payment_id, result_code",
            _filt_m, order_col="id",
        )
        def _filt_p(q):
            return q.eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
        pays_all = _ext_pay_select_paged(
            sc, "app_payments",
            "id, order_id, amount, payment_method, card_company",
            _filt_p, order_col="id",
        )
        pays = [p for p in pays_all if "지역화폐" in str(p.get("payment_method") or "")]
    except Exception:
        return 0
    m_by_row = {int(m["row_id"]): m for m in matches if m.get("row_id") is not None}
    used = {int(m["payment_id"]) for m in matches if m.get("payment_id") is not None}
    retry_rows = []
    for r in rows:
        m = m_by_row.get(int(r["id"]))
        if m and (m.get("result_code") or "") not in ("official_only", "미매칭"):
            continue
        retry_rows.append(r)
    if not retry_rows:
        return 0
    idx: dict[tuple[str, int], list[dict]] = {}
    for p in pays:
        try:
            pid = int(p["id"])
        except (TypeError, ValueError, KeyError):
            continue
        if pid in used:
            continue
        try:
            amt = abs(int(p.get("amount") or 0))
        except (TypeError, ValueError):
            continue
        if amt <= 0:
            continue
        for alt in _ext_pay_approval_alts(p.get("card_company")):
            idx.setdefault((alt, amt), []).append(p)
    updated = 0
    for r in retry_rows:
        try:
            amt = abs(int(r.get("amount") or 0))
        except (TypeError, ValueError):
            continue
        if amt <= 0:
            continue
        seen_c: set[int] = set()
        cands: list[dict] = []
        for alt in _ext_pay_approval_alts(r.get("approval_code")):
            for p in idx.get((alt, amt), []):
                try:
                    _pid = int(p["id"])
                except (TypeError, ValueError, KeyError):
                    continue
                if _pid in seen_c:
                    continue
                seen_c.add(_pid)
                cands.append(p)
        if len(cands) != 1:
            continue
        pay = cands[0]
        try:
            pid = int(pay["id"])
            oid = int(pay["order_id"]) if pay.get("order_id") is not None else None
        except (TypeError, ValueError, KeyError):
            continue
        payload = {
            "result_code": "matched_ok",
            "note": "승인번호 앞자리 0 정규화 재매칭",
            "payment_id": pid,
        }
        if oid is not None:
            payload["order_id"] = oid
            try:
                _or = (
                    sc.table("app_orders")
                    .select("customer_id")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .eq("id", oid)
                    .limit(1)
                    .execute()
                )
                if _or.data and _or.data[0].get("customer_id") is not None:
                    payload["customer_id"] = _or.data[0]["customer_id"]
            except Exception:
                pass
        try:
            rid = int(r["id"])
            m = m_by_row.get(rid)
            if m:
                sc.table("app_external_pay_matches").update(payload).eq(
                    "db_filename", db_filename
                ).eq("row_id", rid).execute()
            else:
                sc.table("app_external_pay_matches").insert({
                    "db_filename": db_filename,
                    "source": "ulsanpay",
                    "row_id": rid,
                    **payload,
                    "matched_by": "zeropad",
                }).execute()
            canon = _ext_pay_norm_approval6(pay.get("card_company"))
            stored = _ext_pay_norm_approval6(r.get("approval_code"))
            if canon and stored and canon != stored and _ext_pay_approvals_equal(canon, stored):
                try:
                    sc.table("app_external_pay_rows").update({
                        "approval_code": canon,
                    }).eq("id", rid).eq("db_filename", db_filename).execute()
                except Exception:
                    pass
            updated += 1
            used.add(pid)
            for k, lst in list(idx.items()):
                idx[k] = [x for x in lst if int(x["id"]) != pid]
        except Exception:
            continue
    return updated


def _ext_pay_relink_amount_and_near_date(
    sc, db_filename: str, source: str, erp_from: date | None = None,
) -> int:
    """기존 official_only·미매칭 공식 행을 금액·근사일자로 재연결."""
    if not sc or not db_filename or source not in ("ulsanpay", "onnuri"):
        return 0
    try:
        def _filt_rows(q):
            return q.eq("db_filename", db_filename).eq("source", source)
        rows = _ext_pay_select_paged(
            sc, "app_external_pay_rows",
            "id, tx_date, amount, tx_status, approval_code, phone_last4",
            _filt_rows, order_col="id",
        )
        def _filt_m(q):
            return q.eq("db_filename", db_filename).eq("source", source)
        matches = _ext_pay_select_paged(
            sc, "app_external_pay_matches",
            "row_id, payment_id, result_code, note",
            _filt_m, order_col="id",
        )
    except Exception:
        return 0
    m_by_row = {int(m["row_id"]): m for m in matches if m.get("row_id") is not None}
    used = {int(m["payment_id"]) for m in matches if m.get("payment_id") is not None}
    from_candidates = [_ext_pay_load_settings(db_filename), EXT_PAY_DEFAULT_VERIFY_FROM]
    if erp_from is not None:
        from_candidates.append(erp_from)
    leftover = _ext_pay_unmatched_erp_pays(
        sc, db_filename, source, min(from_candidates), used,
    )
    updated = 0
    for r in rows:
        try:
            rid = int(r["id"])
        except (TypeError, ValueError, KeyError):
            continue
        m = m_by_row.get(rid)
        if m and (m.get("result_code") or "") not in ("official_only", "미매칭"):
            continue
        if _ext_pay_is_cancel_status(r.get("tx_status")):
            continue
        try:
            oamt = abs(int(r.get("amount") or 0))
        except (TypeError, ValueError):
            continue
        file_date = str(r.get("tx_date") or "")[:10]
        hit = None
        code = None
        notes: list[str] = []
        if source == "ulsanpay":
            ap = _ext_pay_norm_approval6(r.get("approval_code"))
            if not ap:
                continue
            alts = [
                p for p in leftover
                if _ext_pay_approvals_equal(p.get("approval_code"), ap)
            ]
            same_amt = [p for p in alts if abs(int(p.get("amount") or 0)) == oamt]
            diff_amt = [p for p in alts if abs(int(p.get("amount") or 0)) != oamt]
            if same_amt:
                fd = _ext_pay_as_date(file_date)

                def _gap(p):
                    ed = _ext_pay_as_date(p.get("payment_date"))
                    if fd is None or ed is None:
                        return 99
                    return abs((fd - ed).days)

                hit = sorted(same_amt, key=lambda p: (_gap(p), int(p.get("payment_id") or 0)))[0]
                code = "matched_ok"
                _dn = _ext_pay_date_gap_note(file_date, hit.get("payment_date"))
                if _dn:
                    notes.append(_dn)
            elif len(diff_amt) == 1:
                hit = diff_amt[0]
                code = "amount_mismatch"
                notes.append("공식파일에 있으나 금액 다름")
                _dn = _ext_pay_date_gap_note(file_date, hit.get("payment_date"))
                if _dn:
                    notes.append(_dn)
        else:
            last4 = str(r.get("phone_last4") or "")
            if not last4:
                continue
            near = []
            for p in leftover:
                if (p.get("phone_last4") or "") != last4:
                    continue
                if abs(int(p.get("amount") or 0)) != oamt:
                    continue
                _dn = _ext_pay_date_gap_note(file_date, p.get("payment_date"))
                gap_d = _ext_pay_as_date(file_date)
                gap_e = _ext_pay_as_date(p.get("payment_date"))
                if gap_d is None or gap_e is None:
                    continue
                gap = abs((gap_d - gap_e).days)
                if 1 <= gap <= 2:
                    near.append((p, _dn))
            diff_amt = [
                p for p in leftover
                if (p.get("phone_last4") or "") == last4
                and str(p.get("payment_date") or "")[:10] == file_date
                and abs(int(p.get("amount") or 0)) != oamt
            ]
            if len(near) == 1:
                hit, _dn = near[0]
                code = "matched_ok"
                if _dn:
                    notes.append(_dn)
            elif len(diff_amt) == 1:
                hit = diff_amt[0]
                code = "amount_mismatch"
                notes.append("공식파일에 있으나 금액 다름")
        if hit is None or code is None:
            continue
        payload = {
            "result_code": code,
            "note": " · ".join(notes) or None,
            "payment_id": hit.get("payment_id"),
            "order_id": hit.get("order_id"),
            "customer_id": hit.get("customer_id"),
        }
        try:
            if m:
                sc.table("app_external_pay_matches").update(payload).eq(
                    "db_filename", db_filename
                ).eq("row_id", rid).execute()
            else:
                sc.table("app_external_pay_matches").insert({
                    "db_filename": db_filename,
                    "source": source,
                    "row_id": rid,
                    **payload,
                    "matched_by": "relink",
                }).execute()
            updated += 1
            if hit.get("payment_id") is not None:
                used.add(int(hit["payment_id"]))
                leftover = [p for p in leftover if p.get("payment_id") != hit.get("payment_id")]
        except Exception:
            continue
    return updated


def _ext_pay_source_from_method(method: str | None) -> str | None:
    m = str(method or "")
    if "지역화폐" in m:
        return "ulsanpay"
    if "온누리" in m and "지류" not in m:
        return "onnuri"
    return None


def _ext_pay_as_date(v) -> date | None:
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    s = str(v).strip()[:10]
    if not s:
        return None
    try:
        return date.fromisoformat(s)
    except ValueError:
        return None


def _ext_pay_date_gap_note(file_date, erp_date) -> str | None:
    """결제일 차이 메모. 1~2일은 근사 매칭, 그 이상은 일자 불일치."""
    d1 = _ext_pay_as_date(file_date)
    d2 = _ext_pay_as_date(erp_date)
    if d1 is None or d2 is None or d1 == d2:
        return None
    gap = abs((d1 - d2).days)
    if 1 <= gap <= 2:
        return f"결제일 {gap}일 차이 공식 {d1.isoformat()} / ERP {d2.isoformat()}"
    return f"일자 불일치 공식 {d1.isoformat()} / ERP {d2.isoformat()}"


def _ext_pay_match_fields_changed(old_pay: dict | None, updates: dict) -> bool:
    if not updates:
        return False
    keys = ("amount", "payment_method", "card_company", "onnuri_approval_code", "payment_date")
    for k in keys:
        if k not in updates:
            continue
        ov, nv = (old_pay or {}).get(k), updates.get(k)
        if k == "amount":
            try:
                if int(round(float(ov or 0))) != int(round(float(nv or 0))):
                    return True
            except (TypeError, ValueError):
                return True
        elif k == "payment_date":
            if _ext_pay_as_date(ov) != _ext_pay_as_date(nv):
                return True
        elif str(ov or "").strip() != str(nv or "").strip():
            return True
    return False


def _ext_pay_rematch_after_payment_change(
    db_filename: str,
    *,
    payment_id: int | None,
    old_pay: dict | None,
    new_pay: dict | None,
    matched_by: str = "payment_change",
) -> None:
    """결제 금액·수단·승인번호 변경 후 관련 공식 행 매칭을 해제하고 재매칭."""
    if not db_filename:
        return
    sources = set()
    for p in (old_pay, new_pay):
        src = _ext_pay_source_from_method((p or {}).get("payment_method"))
        if src:
            sources.add(src)
    if not sources:
        return
    sc, err = get_supabase_client()
    if err or not sc:
        return
    try:
        verify_from = _ext_pay_load_settings(db_filename)
        extra_dates: list[date] = []
        for p in (old_pay, new_pay):
            d = _ext_pay_as_date((p or {}).get("payment_date"))
            if d is not None:
                extra_dates.append(d)
        for source in sources:
            _ext_pay_release_and_rematch_source(
                sc, db_filename, source, payment_id, old_pay, new_pay,
                verify_from, extra_dates, matched_by,
            )
    except Exception as e:
        try:
            st.session_state["_ext_pay_rematch_error"] = str(e)
        except Exception:
            pass


def _ext_pay_release_and_rematch_source(
    sc, db_filename: str, source: str, payment_id: int | None,
    old_pay: dict | None, new_pay: dict | None,
    verify_from: date, extra_dates: list[date], matched_by: str,
) -> None:
    def _filt_rows(q):
        return q.eq("db_filename", db_filename).eq("source", source)
    rows = _ext_pay_select_paged(
        sc, "app_external_pay_rows",
        "id, tx_date, amount, approval_code, phone_last4",
        _filt_rows, order_col="id",
    )
    def _filt_m(q):
        return q.eq("db_filename", db_filename).eq("source", source)
    matches = _ext_pay_select_paged(
        sc, "app_external_pay_matches",
        "row_id, payment_id, result_code",
        _filt_m, order_col="id",
    )
    release_ids: set[int] = set()
    if payment_id is not None:
        for m in matches:
            try:
                if m.get("payment_id") is not None and int(m["payment_id"]) == int(payment_id):
                    release_ids.add(int(m["row_id"]))
            except (TypeError, ValueError, KeyError):
                continue
    if source == "ulsanpay":
        approvals: set[str] = set()
        for r in rows:
            try:
                rid = int(r["id"])
            except (TypeError, ValueError, KeyError):
                continue
            if rid in release_ids:
                ap = _ext_pay_norm_approval6(r.get("approval_code"))
                if ap:
                    approvals.add(ap)
        for p in (old_pay, new_pay):
            if _ext_pay_source_from_method((p or {}).get("payment_method")) != "ulsanpay":
                continue
            ap = _ext_pay_norm_approval6((p or {}).get("card_company"))
            if ap:
                approvals.add(ap)
        for r in rows:
            ap = _ext_pay_norm_approval6(r.get("approval_code"))
            if ap and ap in approvals:
                try:
                    release_ids.add(int(r["id"]))
                except (TypeError, ValueError, KeyError):
                    continue
    else:
        keys: set[tuple[str, str, int]] = set()
        for r in rows:
            try:
                rid = int(r["id"])
            except (TypeError, ValueError, KeyError):
                continue
            if rid in release_ids:
                try:
                    keys.add((
                        str(r.get("tx_date") or "")[:10],
                        str(r.get("phone_last4") or ""),
                        abs(int(r.get("amount") or 0)),
                    ))
                except (TypeError, ValueError):
                    continue
        for p in (old_pay, new_pay):
            if _ext_pay_source_from_method((p or {}).get("payment_method")) != "onnuri":
                continue
            last4 = _onnuri_last4_from_code((p or {}).get("onnuri_approval_code"))
            try:
                amt = abs(int(round(float((p or {}).get("amount") or 0))))
            except (TypeError, ValueError):
                amt = 0
            pdt = str((p or {}).get("payment_date") or "")[:10]
            if last4 and amt > 0 and pdt:
                keys.add((pdt, last4, amt))
        for r in rows:
            try:
                key = (
                    str(r.get("tx_date") or "")[:10],
                    str(r.get("phone_last4") or ""),
                    abs(int(r.get("amount") or 0)),
                )
            except (TypeError, ValueError):
                continue
            if key in keys:
                try:
                    release_ids.add(int(r["id"]))
                except (TypeError, ValueError, KeyError):
                    continue
    if release_ids:
        for chunk in (list(release_ids)[i : i + 100] for i in range(0, len(release_ids), 100)):
            try:
                sc.table("app_external_pay_matches").delete().eq(
                    "db_filename", db_filename
                ).eq("source", source).in_("row_id", chunk).execute()
            except Exception:
                continue
        for r in rows:
            try:
                rid = int(r["id"])
            except (TypeError, ValueError, KeyError):
                continue
            if rid not in release_ids:
                continue
            d = _ext_pay_as_date(r.get("tx_date"))
            if d is not None:
                extra_dates.append(d)
    vf = verify_from
    if extra_dates:
        vf = min([verify_from, *extra_dates])
    if source == "ulsanpay":
        _ext_pay_match_ulsanpay(db_filename, vf, matched_by)
    else:
        _ext_pay_match_onnuri(db_filename, vf, matched_by)


def _ext_pay_insert_batch_and_rows(
    db_filename: str, source: str, file_name: str, rows: list[dict],
    verify_from: date, uploaded_by: str | None,
) -> tuple[int, int, int, str | None]:
    """배치·행 저장. verify_from 이전은 skip. fingerprint 중복도 skip. 반환: (inserted, skipped_before_date, skipped_duplicate, error_or_None)."""
    sc, err = get_supabase_client()
    if err or not sc:
        return 0, 0, 0, err or "Supabase 연결 불가"
    parsed_count = len(rows)
    filtered: list[dict] = []
    before_date = 0
    for r in rows:
        try:
            if datetime.fromisoformat(r["tx_date"]).date() < verify_from:
                before_date += 1
                continue
        except Exception:
            before_date += 1
            continue
        filtered.append(r)

    inserted = 0
    duplicates = 0
    first_row_err: str | None = None
    batch_id: int | None = None
    try:
        br = sc.table("app_external_pay_batches").insert({
            "db_filename": db_filename,
            "source": source,
            "file_name": file_name or None,
            "parsed_count": int(parsed_count),
            "uploaded_by": (uploaded_by or "").strip() or None,
        }).execute()
        if br.data and len(br.data) > 0 and br.data[0].get("id") is not None:
            batch_id = int(br.data[0]["id"])
    except Exception as e:
        return 0, before_date, 0, f"배치 저장 실패: {e}"

    for r in filtered:
        fp = _ext_pay_fingerprint(
            source, db_filename, r["tx_date"], r.get("tx_time"),
            r.get("phone_last4"), int(r["amount"]), r.get("tx_status"),
            approval_code=r.get("approval_code"),
        )
        payload = {
            "batch_id": batch_id,
            "db_filename": db_filename,
            "source": source,
            "tx_date": r["tx_date"],
            "tx_time": r.get("tx_time"),
            "phone_last4": r.get("phone_last4"),
            "amount": int(r["amount"]),
            "tx_status": r.get("tx_status"),
            "settle_status": r.get("settle_status"),
            "buyer_name_masked": r.get("buyer_name_masked"),
            "approval_code": r.get("approval_code"),
            "raw_json": _ext_pay_safe_raw(r.get("raw")),
            "fingerprint": fp,
        }
        try:
            sc.table("app_external_pay_rows").insert(payload).execute()
            inserted += 1
        except Exception as e:
            msg = str(e).lower()
            if "duplicate" in msg or "unique" in msg or "23505" in msg or "conflict" in msg:
                duplicates += 1
                continue
            if first_row_err is None:
                first_row_err = str(e)
            continue

    try:
        if batch_id is not None:
            sc.table("app_external_pay_batches").update({
                "inserted_count": inserted,
                "skipped_count": duplicates + before_date,
            }).eq("id", batch_id).execute()
    except Exception:
        pass
    if inserted == 0 and filtered and first_row_err:
        return inserted, before_date, duplicates, f"행 저장 실패: {first_row_err}"
    return inserted, before_date, duplicates, None


def _ext_pay_match_onnuri(db_filename: str, verify_from: date, matched_by: str | None) -> tuple[dict, str | None]:
    """공식 온누리 행 ↔ ERP 결제 자동 매칭. UNIQUE(row_id)로 재매칭 방지.
    반환: (counts_by_result, error_or_None)."""
    sc, err = get_supabase_client()
    if err or not sc:
        return {}, err or "Supabase 연결 불가"

    # 공식 행: 아직 매칭 안 된 것만
    try:
        rr = (
            sc.table("app_external_pay_rows")
            .select("id, tx_date, tx_time, phone_last4, amount, tx_status, settle_status")
            .eq("db_filename", db_filename)
            .eq("source", "onnuri")
            .gte("tx_date", verify_from.isoformat())
            .order("tx_date")
            .execute()
        )
        rows = rr.data or []
    except Exception as e:
        return {}, f"공식 행 조회 실패: {e}"
    if not rows:
        return {}, None

    try:
        mr = (
            sc.table("app_external_pay_matches")
            .select("row_id")
            .eq("db_filename", db_filename)
            .eq("source", "onnuri")
            .execute()
        )
        matched_ids = {int(m["row_id"]) for m in (mr.data or []) if m.get("row_id") is not None}
    except Exception:
        matched_ids = set()
    todo = [r for r in rows if int(r["id"]) not in matched_ids]
    if not todo:
        return {}, None

    # ERP 후보: 온누리(전자) 결제, 신규고객 매출, verify_from 이후, 아직 매칭 안 된 것
    try:
        pr = (
            sc.table("app_payments")
            .select("id, order_id, payment_date, amount, payment_method, onnuri_approval_code")
            .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
            .gte("payment_date", verify_from.isoformat())
            .execute()
        )
        pays_all = pr.data or []
    except Exception as e:
        return {}, f"ERP 결제 조회 실패: {e}"

    def _is_onnuri_e(m: str | None) -> bool:
        if not m:
            return False
        s = str(m)
        return ("온누리" in s) and ("지류" not in s)

    pays = [p for p in pays_all if _is_onnuri_e(p.get("payment_method"))]
    order_ids = sorted({int(p["order_id"]) for p in pays if p.get("order_id") is not None})
    orders_map: dict[int, dict] = {}
    if order_ids:
        try:
            for chunk in (order_ids[i : i + 200] for i in range(0, len(order_ids), 200)):
                _or = (
                    sc.table("app_orders")
                    .select("id, customer_id, order_date, entry_source")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .in_("id", chunk)
                    .execute()
                )
                for row in _or.data or []:
                    orders_map[int(row["id"])] = row
        except Exception as e:
            return {}, f"주문 조회 실패: {e}"

    # 이미 매칭된 payment_id 제외
    try:
        mp = (
            sc.table("app_external_pay_matches")
            .select("payment_id")
            .eq("db_filename", db_filename)
            .eq("source", "onnuri")
            .execute()
        )
        used_payment_ids = {int(m["payment_id"]) for m in (mp.data or []) if m.get("payment_id") is not None}
    except Exception:
        used_payment_ids = set()

    # 신규고객 판정: entry_source='new_customer_sale' 또는 verify_from 이전 매출이 없는 고객
    # 후보 좁힘: 우선 entry_source가 명시된 건. entry_source가 비었으면 아래 헬퍼로 확인.
    def _is_new_customer_sale(order_row: dict) -> bool:
        if not order_row:
            return False
        src = (order_row.get("entry_source") or "").strip()
        if src == "new_customer_sale":
            return True
        # 스탬프가 없는 과거 주문: verify_from 이후이면서 그 고객의 첫 주문이면 신규고객 매출로 간주
        cid = order_row.get("customer_id")
        if not cid:
            return False
        try:
            _r = (
                sc.table("app_orders")
                .select("id, order_date")
                .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                .eq("customer_id", int(cid))
                .order("order_date")
                .limit(1)
                .execute()
            )
            first = (_r.data or [{}])[0]
            first_id = first.get("id")
            return first_id is not None and int(first_id) == int(order_row["id"])
        except Exception:
            return False

    # 필터: 신규고객 매출 + 이미 매칭 안 됨
    candidate_pays: list[dict] = []
    for p in pays:
        try:
            pid = int(p["id"])
        except (TypeError, ValueError):
            continue
        if pid in used_payment_ids:
            continue
        o = orders_map.get(int(p["order_id"])) if p.get("order_id") is not None else None
        if not o:
            continue
        if not _is_new_customer_sale(o):
            continue
        candidate_pays.append({**p, "_order": o})

    # 고객 phone1 조회 → phone_last4
    cust_ids = sorted({int(p["_order"]["customer_id"]) for p in candidate_pays if p["_order"].get("customer_id") is not None})
    cust_map: dict[int, dict] = _get_customers_by_ids_supabase(db_filename, cust_ids) if cust_ids else {}

    # ERP 취소 판정 힌트: 같은 order_id에 같은 수단(온누리)의 음수 결제가 있으면 취소 흔적
    neg_orders = {int(p["order_id"]) for p in pays if p.get("order_id") is not None and (p.get("amount") or 0) < 0}

    def _phone_last4_for(pay: dict) -> str | None:
        # 1) 신규매출 입력 시 저장한 전화번호 뒤 4자리 (onnuri_approval_code 재사용)
        stored = _onnuri_last4_from_code(pay.get("onnuri_approval_code"))
        if stored:
            return stored
        # 2) 스탬프 이전 건: 고객 phone1 폴백
        oid = pay["_order"].get("customer_id")
        if oid is None:
            return None
        c = cust_map.get(int(oid)) or {}
        digits = _ext_pay_digits_only(c.get("phone1"))
        return digits[-4:] if digits else None

    # 매칭 인덱스: (tx_date, phone_last4, amount) → [pay, ...]
    idx: dict[tuple, list[dict]] = {}
    for p in candidate_pays:
        last4 = _phone_last4_for(p)
        key = (str(p.get("payment_date") or "")[:10], last4 or "", int(p.get("amount") or 0))
        idx.setdefault(key, []).append(p)

    counts: dict[str, int] = {}
    inserts: list[dict] = []

    for r in todo:
        row_id = int(r["id"])
        tx_date = str(r.get("tx_date") or "")[:10]
        last4 = (r.get("phone_last4") or "")
        amt = int(r.get("amount") or 0)
        is_cancel = _ext_pay_is_cancel_status(r.get("tx_status"))

        # 온누리는 취소도 양수 금액으로 오는 경우가 많음 → 절대값 기준 매칭 후 취소 여부로 분기
        pos_key = (tx_date, last4, amt)
        candidates = list(idx.get(pos_key, []))
        date_note = None
        if not candidates and last4 and not _ext_pay_is_cancel_status(r.get("tx_status")):
            _fd = _ext_pay_as_date(tx_date)
            near: list[dict] = []
            if _fd is not None:
                for _delta in (1, -1, 2, -2):
                    _nd = (_fd + timedelta(days=_delta)).isoformat()
                    near.extend(idx.get((_nd, last4, amt), []))
            _seen_n: set[int] = set()
            _uniq_n: list[dict] = []
            for _p in near:
                try:
                    _pid = int(_p["id"])
                except (TypeError, ValueError, KeyError):
                    continue
                if _pid in _seen_n:
                    continue
                _seen_n.add(_pid)
                _uniq_n.append(_p)
            if len(_uniq_n) == 1:
                candidates = _uniq_n
                date_note = _ext_pay_date_gap_note(tx_date, _uniq_n[0].get("payment_date"))

        result_code = None
        matched_pay: dict | None = None
        note_parts: list[str] = []
        if date_note:
            note_parts.append(date_note)

        if len(candidates) == 0:
            if is_cancel:
                result_code = "official_canceled"
                note_parts.append("공식 취소·ERP에 대응 결제 없음")
            else:
                amt_alts: list[dict] = []
                if last4:
                    for _p in candidate_pays:
                        try:
                            _pid = int(_p["id"])
                        except (TypeError, ValueError, KeyError):
                            continue
                        if _pid in used_payment_ids:
                            continue
                        if _phone_last4_for(_p) != last4:
                            continue
                        if str(_p.get("payment_date") or "")[:10] != tx_date:
                            continue
                        try:
                            _pa = int(_p.get("amount") or 0)
                        except (TypeError, ValueError):
                            continue
                        if abs(_pa) != abs(amt):
                            amt_alts.append(_p)
                if len(amt_alts) == 1:
                    matched_pay = amt_alts[0]
                    result_code = "amount_mismatch"
                    note_parts.append("공식파일에 있으나 금액 다름")
                else:
                    result_code = "official_only"
        elif len(candidates) == 1:
            matched_pay = candidates[0]
            if is_cancel:
                if int(matched_pay["order_id"]) in neg_orders:
                    result_code = "matched_ok"
                    note_parts.append("공식 취소 · ERP도 취소 흔적")
                else:
                    result_code = "official_canceled"
                    note_parts.append("공식 취소인데 ERP는 잔존")
            else:
                if int(matched_pay["order_id"]) in neg_orders:
                    result_code = "erp_canceled_official_paid"
                    note_parts.append("공식 결제완료 · ERP는 취소 흔적")
                else:
                    result_code = "matched_ok"
        else:
            # 거래시간이 저장된 건은 공식 파일 시각으로 확정
            _want_t = _onnuri_parse_time_input(r.get("tx_time"))
            _timed = [
                _p for _p in candidates
                if _want_t and _onnuri_time_from_code(_p.get("onnuri_approval_code")) == _want_t
            ]
            if len(_timed) == 1:
                matched_pay = _timed[0]
                if is_cancel:
                    if int(matched_pay["order_id"]) in neg_orders:
                        result_code = "matched_ok"
                        note_parts.append("공식 취소 · ERP도 취소 흔적")
                    else:
                        result_code = "official_canceled"
                        note_parts.append("공식 취소인데 ERP는 잔존")
                else:
                    if int(matched_pay["order_id"]) in neg_orders:
                        result_code = "erp_canceled_official_paid"
                        note_parts.append("공식 결제완료 · ERP는 취소 흔적")
                    else:
                        result_code = "matched_ok"
                        note_parts.append("거래시간으로 구분")
            elif is_cancel:
                result_code = "ambiguous"
                note_parts.append("다중 후보·취소·시간으로 구분 불가")
            else:
                matched_pay = sorted(candidates, key=lambda x: int(x["id"]))[0]
                result_code = "ambiguous"
                note_parts.append(f"다중 후보 {len(candidates)}건 · 임시로 최소 id 매칭")

        pay_id = int(matched_pay["id"]) if matched_pay else None
        order_id = int(matched_pay["order_id"]) if matched_pay and matched_pay.get("order_id") is not None else None
        cust_id = None
        if matched_pay:
            _o = matched_pay["_order"] or {}
            cust_id = int(_o["customer_id"]) if _o.get("customer_id") is not None else None

        inserts.append({
            "db_filename": db_filename,
            "source": "onnuri",
            "row_id": row_id,
            "payment_id": pay_id,
            "order_id": order_id,
            "customer_id": cust_id,
            "result_code": result_code,
            "note": " · ".join(note_parts) or None,
            "matched_by": (matched_by or "").strip() or None,
        })
        counts[result_code] = counts.get(result_code, 0) + 1
        if pay_id is not None:
            used_payment_ids.add(pay_id)
            # 인덱스에서 이 결제 제거 (재사용 방지)
            for k, lst in list(idx.items()):
                idx[k] = [x for x in lst if int(x["id"]) != pay_id]

    # ERP-only 감지: 남은 candidate_pays 중 매칭에 쓰이지 않은 것
    leftover_pays = [p for p in candidate_pays if int(p["id"]) not in used_payment_ids]
    # leftover_pays 는 별도 테이블 저장 대상이 아니지만 결과 표에는 필요 → 임시 로우 없이 카운트만 유지.
    counts["erp_only"] = counts.get("erp_only", 0) + len(leftover_pays)

    for chunk in (inserts[i : i + 200] for i in range(0, len(inserts), 200)):
        try:
            sc.table("app_external_pay_matches").insert(chunk).execute()
        except Exception:
            # UNIQUE(row_id) 위반 등: 개별 재시도
            for one in chunk:
                try:
                    sc.table("app_external_pay_matches").insert(one).execute()
                except Exception:
                    continue

    _ext_pay_relink_amount_and_near_date(sc, db_filename, "onnuri")
    return counts, None


def _ext_pay_match_ulsanpay(db_filename: str, verify_from: date, matched_by: str | None) -> tuple[dict, str | None]:
    """공식 울산페이 행 ↔ ERP 지역화폐 결제. 키: 승인번호 6자리 + 결제금액.
    ERP 승인번호는 app_payments.card_company 에 저장됨."""
    sc, err = get_supabase_client()
    if err or not sc:
        return {}, err or "Supabase 연결 불가"

    try:
        def _filt_rows(q):
            return (
                q.eq("db_filename", db_filename)
                .eq("source", "ulsanpay")
                .gte("tx_date", verify_from.isoformat())
            )
        rows = _ext_pay_select_paged(
            sc, "app_external_pay_rows",
            "id, tx_date, tx_time, amount, tx_status, approval_code",
            _filt_rows, order_col="id",
        )
    except Exception as e:
        return {}, f"공식 행 조회 실패: {e}"
    if not rows:
        return {}, None

    try:
        def _filt_m(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        mr = _ext_pay_select_paged(
            sc, "app_external_pay_matches", "row_id", _filt_m, order_col="id",
        )
        matched_ids = {int(m["row_id"]) for m in mr if m.get("row_id") is not None}
    except Exception:
        matched_ids = set()
    todo = [r for r in rows if int(r["id"]) not in matched_ids]
    if not todo:
        return {}, None

    try:
        def _filt_p(q):
            return (
                q.eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                .gte("payment_date", verify_from.isoformat())
            )
        pays_all = _ext_pay_select_paged(
            sc, "app_payments",
            "id, order_id, payment_date, amount, payment_method, card_company",
            _filt_p, order_col="id",
        )
    except Exception as e:
        return {}, f"ERP 결제 조회 실패: {e}"

    def _is_ulsan(m: str | None) -> bool:
        return bool(m) and "지역화폐" in str(m)

    pays = [p for p in pays_all if _is_ulsan(p.get("payment_method"))]
    order_ids = sorted({int(p["order_id"]) for p in pays if p.get("order_id") is not None})
    orders_map: dict[int, dict] = {}
    if order_ids:
        try:
            for chunk in (order_ids[i : i + 200] for i in range(0, len(order_ids), 200)):
                _or = (
                    sc.table("app_orders")
                    .select("id, customer_id, order_date, entry_source")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .in_("id", chunk)
                    .execute()
                )
                for row in _or.data or []:
                    orders_map[int(row["id"])] = row
        except Exception as e:
            return {}, f"주문 조회 실패: {e}"

    try:
        def _filt_mp(q):
            return q.eq("db_filename", db_filename).eq("source", "ulsanpay")
        mp = _ext_pay_select_paged(
            sc, "app_external_pay_matches", "payment_id", _filt_mp, order_col="id",
        )
        used_payment_ids = {int(m["payment_id"]) for m in mp if m.get("payment_id") is not None}
    except Exception:
        used_payment_ids = set()

    def _is_new_customer_sale(order_row: dict) -> bool:
        if not order_row:
            return False
        src = (order_row.get("entry_source") or "").strip()
        if src == "new_customer_sale":
            return True
        cid = order_row.get("customer_id")
        if not cid:
            return False
        try:
            _r = (
                sc.table("app_orders")
                .select("id, order_date")
                .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                .eq("customer_id", int(cid))
                .order("order_date")
                .limit(1)
                .execute()
            )
            first = (_r.data or [{}])[0]
            first_id = first.get("id")
            return first_id is not None and int(first_id) == int(order_row["id"])
        except Exception:
            return False

    candidate_pays: list[dict] = []
    for p in pays:
        try:
            pid = int(p["id"])
        except (TypeError, ValueError):
            continue
        if pid in used_payment_ids:
            continue
        o = orders_map.get(int(p["order_id"])) if p.get("order_id") is not None else None
        if not o or not _is_new_customer_sale(o):
            continue
        candidate_pays.append({**p, "_order": o})

    neg_orders = {int(p["order_id"]) for p in pays if p.get("order_id") is not None and (p.get("amount") or 0) < 0}

    # 키: (승인번호6, 절대금액) — Excel float 오인 후보도 함께 인덱싱
    idx: dict[tuple, list[dict]] = {}
    for p in candidate_pays:
        try:
            amt_k = abs(int(p.get("amount") or 0))
        except (TypeError, ValueError):
            continue
        for alt in _ext_pay_approval_alts(p.get("card_company")):
            idx.setdefault((alt, amt_k), []).append(p)

    counts: dict[str, int] = {}
    inserts: list[dict] = []

    for r in todo:
        row_id = int(r["id"])
        appr = _ext_pay_norm_approval6(r.get("approval_code"))
        amt = int(r.get("amount") or 0)
        is_cancel = _ext_pay_is_cancel_status(r.get("tx_status")) or amt < 0
        match_amt = abs(amt)
        seen_c: set[int] = set()
        candidates: list[dict] = []
        for alt in _ext_pay_approval_alts(r.get("approval_code")):
            for p in idx.get((alt, match_amt), []):
                try:
                    _id = int(p["id"])
                except (TypeError, ValueError, KeyError):
                    continue
                if _id in seen_c:
                    continue
                seen_c.add(_id)
                candidates.append(p)

        result_code = None
        matched_pay: dict | None = None
        note_parts: list[str] = []

        if not appr:
            result_code = "official_only"
            note_parts.append("승인번호 없음")
        elif len(candidates) == 0:
            if is_cancel:
                result_code = "official_canceled"
                note_parts.append("공식 취소·ERP에 대응 결제 없음")
            else:
                amt_alts = []
                if appr:
                    for _p in candidate_pays:
                        try:
                            _pid = int(_p["id"])
                        except (TypeError, ValueError, KeyError):
                            continue
                        if _pid in used_payment_ids:
                            continue
                        if not _ext_pay_approvals_equal(_p.get("card_company"), appr):
                            continue
                        try:
                            _pa = abs(int(_p.get("amount") or 0))
                        except (TypeError, ValueError):
                            continue
                        if _pa != match_amt and _pa > 0:
                            amt_alts.append(_p)
                if len(amt_alts) == 1:
                    matched_pay = amt_alts[0]
                    result_code = "amount_mismatch"
                    note_parts.append("공식파일에 있으나 금액 다름")
                    _dn = _ext_pay_date_gap_note(r.get("tx_date"), matched_pay.get("payment_date"))
                    if _dn:
                        note_parts.append(_dn)
                else:
                    result_code = "official_only"
        elif len(candidates) == 1:
            matched_pay = candidates[0]
            erp_date = str(matched_pay.get("payment_date") or "")[:10]
            file_date = str(r.get("tx_date") or "")[:10]
            _dn = _ext_pay_date_gap_note(file_date, erp_date)
            if _dn:
                note_parts.append(_dn)
            if is_cancel:
                if int(matched_pay["order_id"]) in neg_orders:
                    result_code = "matched_ok"
                    note_parts.append("공식 취소 · ERP도 취소 흔적")
                else:
                    result_code = "official_canceled"
                    note_parts.append("공식 취소인데 ERP는 잔존")
            else:
                if int(matched_pay["order_id"]) in neg_orders:
                    result_code = "erp_canceled_official_paid"
                    note_parts.append("공식 결제완료 · ERP는 취소 흔적")
                else:
                    result_code = "matched_ok"
        else:
            matched_pay = sorted(candidates, key=lambda x: int(x["id"]))[0]
            result_code = "ambiguous"
            note_parts.append(f"동일 승인번호·금액 후보 {len(candidates)}건")

        pay_id = int(matched_pay["id"]) if matched_pay else None
        order_id = int(matched_pay["order_id"]) if matched_pay and matched_pay.get("order_id") is not None else None
        cust_id = None
        if matched_pay:
            _o = matched_pay["_order"] or {}
            cust_id = int(_o["customer_id"]) if _o.get("customer_id") is not None else None

        inserts.append({
            "db_filename": db_filename,
            "source": "ulsanpay",
            "row_id": row_id,
            "payment_id": pay_id,
            "order_id": order_id,
            "customer_id": cust_id,
            "result_code": result_code,
            "note": " · ".join(note_parts) or None,
            "matched_by": (matched_by or "").strip() or None,
        })
        counts[result_code] = counts.get(result_code, 0) + 1
        if pay_id is not None:
            used_payment_ids.add(pay_id)
            for k, lst in list(idx.items()):
                idx[k] = [x for x in lst if int(x["id"]) != pay_id]

    leftover_pays = [p for p in candidate_pays if int(p["id"]) not in used_payment_ids]
    counts["erp_only"] = counts.get("erp_only", 0) + len(leftover_pays)

    for chunk in (inserts[i : i + 200] for i in range(0, len(inserts), 200)):
        try:
            sc.table("app_external_pay_matches").insert(chunk).execute()
        except Exception:
            for one in chunk:
                try:
                    sc.table("app_external_pay_matches").insert(one).execute()
                except Exception:
                    continue

    _ext_pay_offset_ulsan_cancels(sc, db_filename)
    _ext_pay_rematch_ulsan_zeropad(sc, db_filename)
    _ext_pay_relink_amount_and_near_date(sc, db_filename, "ulsanpay")
    return counts, None


def _ext_pay_new_customer_order_ids(sc, db_filename: str, order_rows: list[dict]) -> set[int]:
    """entry_source=new_customer_sale 이거나 해당 고객의 첫 주문이면 신규고객 매출."""
    out: set[int] = set()
    need: list[dict] = []
    for o in order_rows:
        try:
            oid = int(o["id"])
        except (TypeError, ValueError, KeyError):
            continue
        if (o.get("entry_source") or "").strip() == "new_customer_sale":
            out.add(oid)
        else:
            need.append(o)
    cust_ids = []
    for o in need:
        if o.get("customer_id") is None:
            continue
        try:
            cust_ids.append(int(o["customer_id"]))
        except (TypeError, ValueError):
            continue
    first_by_cust: dict[int, int] = {}
    uniq = sorted(set(cust_ids))
    for chunk in (uniq[i : i + 100] for i in range(0, len(uniq), 100)):
        try:
            def _filt(q, _chunk=chunk):
                return q.eq(ORDERS_PAYMENTS_TENANT_COL, db_filename).in_("customer_id", _chunk)
            all_o = _ext_pay_select_paged(
                sc, "app_orders", "id, customer_id, order_date", _filt, order_col="id",
            )
        except Exception:
            all_o = []
        for row in all_o:
            try:
                cid = int(row["customer_id"])
                oid = int(row["id"])
            except (TypeError, ValueError, KeyError):
                continue
            key = (str(row.get("order_date") or ""), oid)
            prev = first_by_cust.get(cid)
            if prev is None or key < (str(prev[1]), prev[0]):
                first_by_cust[cid] = (oid, str(row.get("order_date") or ""))
    first_by_cust = {cid: pair[0] for cid, pair in first_by_cust.items()}
    for o in need:
        try:
            cid = int(o["customer_id"])
            oid = int(o["id"])
        except (TypeError, ValueError, KeyError):
            continue
        if first_by_cust.get(cid) == oid:
            out.add(oid)
    return out


def _ext_pay_unmatched_erp_pays(
    sc, db_filename: str, source: str, erp_from: date, used_payment_ids: set[int],
) -> list[dict]:
    """공식 파일에 매칭되지 않은 신규고객 ERP 결제 (erp_only)."""
    try:
        def _filt(q):
            q = q.eq(ORDERS_PAYMENTS_TENANT_COL, db_filename).gt("amount", 0)
            if erp_from is not None:
                q = q.gte("payment_date", erp_from.isoformat())
            return q
        pays = _ext_pay_select_paged(
            sc, "app_payments",
            "id, order_id, payment_date, amount, payment_method, card_company, onnuri_approval_code",
            _filt, order_col="id",
        )
    except Exception:
        return []

    def _keep(p: dict) -> bool:
        meth = str(p.get("payment_method") or "")
        if source == "ulsanpay":
            return "지역화폐" in meth
        return ("온누리" in meth) and ("지류" not in meth)

    leftover = []
    for p in pays:
        try:
            pid = int(p["id"])
        except (TypeError, ValueError):
            continue
        if pid in used_payment_ids:
            continue
        if not _keep(p):
            continue
        leftover.append(p)
    if not leftover:
        return []

    order_ids = []
    for p in leftover:
        if p.get("order_id") is None:
            continue
        try:
            order_ids.append(int(p["order_id"]))
        except (TypeError, ValueError):
            continue
    orders_map: dict[int, dict] = {}
    uniq_oids = sorted(set(order_ids))
    for chunk in (uniq_oids[i : i + 200] for i in range(0, len(uniq_oids), 200)):
        try:
            r = (
                sc.table("app_orders")
                .select("id, customer_id, order_date, entry_source")
                .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                .in_("id", chunk)
                .execute()
            )
            for row in r.data or []:
                orders_map[int(row["id"])] = row
        except Exception:
            continue
    new_oids = _ext_pay_new_customer_order_ids(sc, db_filename, list(orders_map.values()))

    out: list[dict] = []
    for p in leftover:
        try:
            oid = int(p["order_id"]) if p.get("order_id") is not None else None
        except (TypeError, ValueError):
            oid = None
        if oid is None or oid not in new_oids:
            continue
        o = orders_map.get(oid) or {}
        try:
            cid = int(o["customer_id"]) if o.get("customer_id") is not None else None
        except (TypeError, ValueError):
            cid = None
        try:
            amt = int(p.get("amount") or 0)
        except (TypeError, ValueError):
            amt = 0
        if source == "ulsanpay":
            approval = _ext_pay_norm_approval6(p.get("card_company"))
            phone4 = ""
        else:
            approval = ""
            phone4 = _onnuri_last4_from_code(p.get("onnuri_approval_code"))
        out.append({
            "payment_id": int(p["id"]),
            "order_id": oid,
            "customer_id": cid,
            "payment_date": str(p.get("payment_date") or "")[:10],
            "amount": amt,
            "approval_code": approval,
            "phone_last4": phone4,
        })
    return out


def _ext_pay_list_matches_df(
    db_filename: str, source: str, verify_from: date | None, erp_from: date | None = None,
) -> "pd.DataFrame":
    """관리자 UI 표시용: 공식 행 + 매칭 결과 + ERP-only 행 DataFrame.
    verify_from 이 None 이면 공식 행은 날짜 필터 없이 해당 매장·출처 전체.
    erp_from 은 ERP-only 조회 시작일(미지정 시 verify_from 또는 기본 시작일)."""
    sc, err = get_supabase_client()
    if err or not sc:
        return pd.DataFrame()
    erp_only_from = erp_from or verify_from or EXT_PAY_DEFAULT_VERIFY_FROM
    if source == "ulsanpay":
        _ext_pay_offset_ulsan_cancels(sc, db_filename)
        _ext_pay_rematch_ulsan_zeropad(sc, db_filename)
    _ext_pay_relink_amount_and_near_date(sc, db_filename, source, erp_from=erp_only_from)
    try:
        def _filt_rows(q):
            q = q.eq("db_filename", db_filename).eq("source", source)
            if verify_from is not None:
                q = q.gte("tx_date", verify_from.isoformat())
            return q
        rows = _ext_pay_select_paged(
            sc, "app_external_pay_rows",
            "id, tx_date, tx_time, phone_last4, amount, tx_status, settle_status, buyer_name_masked, approval_code",
            _filt_rows, order_col="id",
        )
        rows.sort(key=lambda r: (str(r.get("tx_date") or ""), str(r.get("tx_time") or ""), int(r.get("id") or 0)))
    except Exception:
        rows = []
    try:
        def _filt_m(q):
            return q.eq("db_filename", db_filename).eq("source", source)
        matches = _ext_pay_select_paged(
            sc, "app_external_pay_matches",
            "row_id, payment_id, order_id, customer_id, result_code, note",
            _filt_m, order_col="id",
        )
        m_by_row = {int(m["row_id"]): m for m in matches if m.get("row_id") is not None}
    except Exception:
        m_by_row = {}

    cust_ids: list[int] = []
    order_ids: list[int] = []
    payment_ids: list[int] = []
    for m in m_by_row.values():
        cid = m.get("customer_id")
        if cid is not None:
            try:
                cust_ids.append(int(cid))
            except (TypeError, ValueError):
                pass
        oid = m.get("order_id")
        if oid is not None:
            try:
                order_ids.append(int(oid))
            except (TypeError, ValueError):
                pass
        pid = m.get("payment_id")
        if pid is not None:
            try:
                payment_ids.append(int(pid))
            except (TypeError, ValueError):
                pass

    erp_only_pays = _ext_pay_unmatched_erp_pays(
        sc, db_filename, source, erp_only_from, set(payment_ids),
    )
    for p in erp_only_pays:
        cid = p.get("customer_id")
        if cid is not None:
            try:
                cust_ids.append(int(cid))
            except (TypeError, ValueError):
                pass
        oid = p.get("order_id")
        if oid is not None:
            try:
                order_ids.append(int(oid))
            except (TypeError, ValueError):
                pass

    cust_map: dict = {}
    uniq_cids = sorted(set(cust_ids))
    for i in range(0, len(uniq_cids), 100):
        cust_map.update(_get_customers_by_ids_supabase(db_filename, uniq_cids[i : i + 100]))
    emp_map = _fetch_order_employee_names_map_by_ids(db_filename, order_ids)

    pay_amt_by_id: dict[int, int] = {}
    pay_date_by_id: dict[int, str] = {}
    pay_ap_by_id: dict[int, str] = {}
    pays_by_approval: dict[str, list[tuple[int, str]]] = {}
    uniq_pids = sorted(set(payment_ids))
    if uniq_pids:
        try:
            for chunk in (uniq_pids[i : i + 200] for i in range(0, len(uniq_pids), 200)):
                pr = (
                    sc.table("app_payments")
                    .select("id, amount, payment_date, card_company, payment_method")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .in_("id", chunk)
                    .execute()
                )
                for p in pr.data or []:
                    try:
                        pid = int(p["id"])
                    except (TypeError, ValueError):
                        continue
                    try:
                        pay_amt_by_id[pid] = int(p.get("amount") or 0)
                    except (TypeError, ValueError):
                        pay_amt_by_id[pid] = 0
                    pay_date_by_id[pid] = str(p.get("payment_date") or "")[:10]
                    pay_ap_by_id[pid] = _ext_pay_norm_approval6(p.get("card_company"))
        except Exception:
            pay_amt_by_id = {}
            pay_date_by_id = {}
            pay_ap_by_id = {}

    # 동일 승인번호 후보(ambiguous) — 해당 승인번호의 ERP 금액·일자를 모두 모아 표시
    amb_approvals = []
    if source == "ulsanpay":
        for r in rows:
            m = m_by_row.get(int(r["id"])) or {}
            if (m.get("result_code") or "") != "ambiguous":
                continue
            ap = _ext_pay_norm_approval6(r.get("approval_code"))
            if ap:
                amb_approvals.append(ap)
    amb_approvals = sorted(set(amb_approvals))
    if amb_approvals:
        try:
            for chunk in (amb_approvals[i : i + 100] for i in range(0, len(amb_approvals), 100)):
                pr = (
                    sc.table("app_payments")
                    .select("id, amount, payment_date, card_company, payment_method")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .in_("card_company", chunk)
                    .execute()
                )
                for p in pr.data or []:
                    if "지역화폐" not in str(p.get("payment_method") or ""):
                        continue
                    ap = _ext_pay_norm_approval6(p.get("card_company"))
                    if not ap:
                        continue
                    try:
                        amt = int(p.get("amount") or 0)
                    except (TypeError, ValueError):
                        amt = 0
                    pdt = str(p.get("payment_date") or "")[:10]
                    pays_by_approval.setdefault(ap, []).append((amt, pdt))
        except Exception:
            pays_by_approval = {}

    data: list[dict] = []
    for r in rows:
        m = m_by_row.get(int(r["id"])) or {}
        cid = m.get("customer_id")
        try:
            cid_int = int(cid) if cid is not None else None
        except (TypeError, ValueError):
            cid_int = None
        try:
            oid_int = int(m["order_id"]) if m.get("order_id") is not None else None
        except (TypeError, ValueError):
            oid_int = None
        try:
            pid_int = int(m["payment_id"]) if m.get("payment_id") is not None else None
        except (TypeError, ValueError):
            pid_int = None
        cust = cust_map.get(cid_int) or {}
        official_amt = int(r.get("amount") or 0)
        ap = _ext_pay_norm_approval6(r.get("approval_code"))
        erp_pairs = pays_by_approval.get(ap) if (m.get("result_code") == "ambiguous" and ap) else None
        if erp_pairs:
            erp_amt_disp = " / ".join(f"{a:,}" for a, _ in erp_pairs)
            erp_date_disp = " / ".join(d for _, d in erp_pairs if d)
        elif pid_int is not None:
            erp_amt_disp = f"{pay_amt_by_id[pid_int]:,}" if pid_int in pay_amt_by_id else ""
            erp_date_disp = pay_date_by_id.get(pid_int) or ""
        else:
            erp_amt_disp = ""
            erp_date_disp = ""
        erp_ap = pay_ap_by_id.get(pid_int, "") if pid_int is not None else ""
        data.append({
            "공식일자": str(r.get("tx_date") or "")[:10],
            "ERP일자": erp_date_disp,
            "뒤4": r.get("phone_last4") or "",
            "승인번호": ap or (r.get("approval_code") or ""),
            "공식금액": f"{official_amt:,}",
            "ERP금액": erp_amt_disp,
            "공식상태": r.get("tx_status") or "",
            "정산": r.get("settle_status") or "",
            "구매자": r.get("buyer_name_masked") or "",
            "결과": m.get("result_code") or "미매칭",
            "고객명": cust.get("name") or "",
            "고객전화": cust.get("phone1") or "",
            "담당매니저": (emp_map.get(oid_int) or "").strip() if oid_int is not None else "",
            "메모": m.get("note") or "",
            "_fabricated": (not ap) and bool(erp_ap),
        })
    official_aps: set[str] = set()
    for r in rows:
        official_aps.update(_ext_pay_approval_alts(r.get("approval_code")))
    for p in erp_only_pays:
        try:
            cid_int = int(p["customer_id"]) if p.get("customer_id") is not None else None
        except (TypeError, ValueError):
            cid_int = None
        try:
            oid_int = int(p["order_id"]) if p.get("order_id") is not None else None
        except (TypeError, ValueError):
            oid_int = None
        cust = cust_map.get(cid_int) or {}
        amt = int(p.get("amount") or 0)
        erp_ap = _ext_pay_norm_approval6(p.get("approval_code") or p.get("phone_last4"))
        erp_alts = set(_ext_pay_approval_alts(erp_ap))
        if source == "ulsanpay" and erp_alts and (erp_alts & official_aps):
            continue
        data.append({
            "공식일자": "",
            "ERP일자": p.get("payment_date") or "",
            "뒤4": p.get("phone_last4") or "",
            "승인번호": _ext_pay_norm_approval6(p.get("approval_code")) or (p.get("approval_code") or ""),
            "공식금액": "",
            "ERP금액": f"{amt:,}",
            "공식상태": "",
            "정산": "",
            "구매자": "",
            "결과": "erp_only",
            "고객명": cust.get("name") or "",
            "고객전화": cust.get("phone1") or "",
            "담당매니저": (emp_map.get(oid_int) or "").strip() if oid_int is not None else "",
            "메모": "공식 파일에 없음 · 가공 번호 의심",
            "_fabricated": bool(erp_ap),
        })
    return pd.DataFrame(data)


def _fetch_order_employee_names_map_by_ids(db_filename: str, order_ids: list) -> dict[int, str]:
    """order_id → 주문 테이블의 최신 employee_names (Supabase app_orders 또는 SQLite Orders)."""
    out: dict[int, str] = {}
    if not db_filename or not order_ids:
        return out
    try:
        oids = sorted({int(x) for x in order_ids})
    except (TypeError, ValueError):
        return out
    if not oids:
        return out
    if _supabase_orders_payments_available():
        sc, err = get_supabase_client()
        if err or not sc:
            return out
        try:
            for chunk in (oids[i : i + 100] for i in range(0, len(oids), 100)):
                resp = (
                    sc.table("app_orders")
                    .select("id, employee_names")
                    .eq(ORDERS_PAYMENTS_TENANT_COL, db_filename)
                    .in_("id", chunk)
                    .execute()
                )
                for row in resp.data or []:
                    out[int(row["id"])] = str(row.get("employee_names") or "")
        except Exception:
            return out
        return out
    conn = get_tenant_conn(db_filename)
    if not conn:
        return out
    try:
        for chunk in (oids[i : i + 200] for i in range(0, len(oids), 200)):
            ph = ",".join("?" * len(chunk))
            cur = conn.execute(f"SELECT id, employee_names FROM Orders WHERE id IN ({ph})", chunk)
            for row in cur.fetchall():
                out[int(row[0])] = str(row[1] or "")
    except Exception:
        pass
    finally:
        conn.close()
    return out


def _overlay_sales_df_employee_names_from_live_orders(sal_df: "pd.DataFrame") -> None:
    """in-place: `_db_fn`·`order_id`가 있으면 주문 테이블 최신 담당 직원으로 `employee_names`를 덮어써 1/n·표시가 주문 수정과 일치."""
    if sal_df is None or sal_df.empty:
        return
    if "order_id" not in sal_df.columns or "employee_names" not in sal_df.columns or "_db_fn" not in sal_df.columns:
        return
    sal_df["employee_names"] = sal_df["employee_names"].astype(object)
    for db_fn in sal_df["_db_fn"].dropna().unique():
        db_s = str(db_fn)
        m = sal_df["_db_fn"] == db_fn
        oids = sal_df.loc[m, "order_id"].dropna().astype(int).unique().tolist()
        if not oids:
            continue
        emp_map = _fetch_order_employee_names_map_by_ids(db_s, oids)
        if not emp_map:
            continue

        def _resolve(oid: object, cur: object) -> object:
            if pd.isna(oid):
                return cur
            try:
                oi = int(oid)
            except (TypeError, ValueError):
                return cur
            ov = emp_map.get(oi)
            if ov is not None and str(ov).strip():
                return str(ov).strip()
            return cur

        sub = sal_df.loc[m, ["order_id", "employee_names"]]
        sal_df.loc[m, "employee_names"] = [_resolve(a, b) for a, b in zip(sub["order_id"], sub["employee_names"])]


