def _render_admin_fraud_alerts(db_filename: str):
    """로그인 직후 1회만 호출: 관리자(store_admin·superadmin)에게 부정행위 의심 경보 표시.
    일반 직원 알림(_render_login_notifications)과 완전히 분리된 독립 레이어.
    """
    if st.session_state.get("_admin_fraud_alert_shown"):
        return
    st.session_state["_admin_fraud_alert_shown"] = True

    username = _current_username()
    if not username or username == "unknown":
        return

    alerts = _fetch_admin_fraud_alerts(db_filename, username)
    if not alerts:
        return

    alert_ids = [a["id"] for a in alerts if "id" in a]
    _mark_notifications_read(alert_ids)

    level_icon = {
        "CRITICAL": "🚨",
        "WARNING":  "⚠️",
        "INFO":     "ℹ️",
    }
    type_label = {
        "high_amount_change": "판매금액 대폭 변경",
        "negative_margin":    "마진율 음수 감지",
        "payment_cancel":     "결제 취소",
        "off_hours_edit":     "영업 외 시간 수정",
        "self_sales_assign":  "본인 직접 배분 의심",
    }

    with st.container(border=True):
        st.markdown(f"### 🔍 관리자 경보 {len(alerts)}건")
        st.caption("아래 항목은 부정행위 의심 패턴이 감지된 주문입니다. 페이지를 이동하면 사라집니다.")
        for a in alerts:
            created = str(a.get("created_at", ""))[:16].replace("T", " ")
            actor = a.get("requested_by", "알 수 없음")
            payload_raw = a.get("payload", "")
            order_id = a.get("entity_id", "-")
            reason_text = a.get("reason", "")
            # payload 파싱: "[CRITICAL][high_amount_change] 내용"
            level_str = "WARNING"
            type_str = ""
            content_str = payload_raw
            try:
                if payload_raw.startswith("[") and "][" in payload_raw:
                    end1 = payload_raw.index("]")
                    level_str = payload_raw[1:end1]
                    rest = payload_raw[end1 + 1:]
                    if rest.startswith("["):
                        end2 = rest.index("]")
                        type_str = rest[1:end2]
                        content_str = rest[end2 + 2:]
            except Exception:
                pass
            icon = level_icon.get(level_str, "⚠️")
            type_display = type_label.get(type_str, type_str)
            if level_str == "CRITICAL":
                st.error(
                    f"{icon} **[{type_display}]** — 주문 #{order_id}  \n"
                    f"담당자: `{actor}` | 일시: {created}  \n"
                    f"사유: {reason_text or '(없음)'}  \n"
                    f"{content_str}"
                )
            elif level_str == "WARNING":
                st.warning(
                    f"{icon} **[{type_display}]** — 주문 #{order_id}  \n"
                    f"담당자: `{actor}` | 일시: {created}  \n"
                    f"사유: {reason_text or '(없음)'}  \n"
                    f"{content_str}"
                )
            else:
                st.info(
                    f"{icon} **[{type_display}]** — 주문 #{order_id}  \n"
                    f"담당자: `{actor}` | 일시: {created}  \n"
                    f"사유: {reason_text or '(없음)'}  \n"
                    f"{content_str}"
                )
        st.divider()


# ────────────────────────────────────────────────────────────────────────────
# 주문 삭제 요청 시스템 (직원 → 관리자 2단계 승인)
# ────────────────────────────────────────────────────────────────────────────

def _insert_delete_request(db_filename: str, order_id: int, reason: str, requested_by_username: str):
    """직원이 요청한 주문 삭제를 app_edit_requests에 기록 (notif_type='delete_request').
    해당 매장의 store_admin + superadmin 모두에게 알림을 보낸다.
    """
    if not _supabase_orders_payments_available() or not db_filename:
        return False, "Supabase 연결 오류"
    admin_usernames = _get_admin_usernames_for_store(db_filename)
    if not admin_usernames:
        return False, "관리자를 찾을 수 없습니다"
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return False, str(err)
        tenant_name = _get_store_name_by_db(db_filename) or db_filename
        for admin_uname in admin_usernames:
            sc.table("app_edit_requests").insert({
                "db_filename": db_filename,
                "tenant_name": tenant_name,
                "entity_type": "Order",
                "entity_id": int(order_id),
                "requested_by": requested_by_username or "",
                "target_username": admin_uname,
                "notif_type": "delete_request",
                "payload": f"주문 #{order_id} 삭제 요청",
                "reason": reason.strip(),
                "status": "pending",
            }).execute()
        return True, None
    except Exception as e:
        return False, str(e)


@st.cache_data(ttl=60)
def _fetch_pending_delete_requests(db_filename: str, target_username: str = "") -> list:
    """해당 매장의 미처리 삭제 요청 목록 조회 (관리자용). 60초 캐시 — 사이드바 표시용으로 잦은 메뉴 이동 시 HTTP 절약.
    target_username을 캐시 키에 포함시켜 다중 사용자 환경에서도 안전.
    삭제 요청 처리/생성 시 clear_data_cache()로 즉시 갱신."""
    if not _supabase_orders_payments_available() or not db_filename:
        return []
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return []
        username = (target_username or "").strip() or _current_username()
        r = (
            sc.table("app_edit_requests")
            .select("id, created_at, entity_id, requested_by, reason, status")
            .eq("db_filename", db_filename)
            .eq("notif_type", "delete_request")
            .eq("target_username", username)
            .eq("status", "pending")
            .order("created_at", desc=True)
            .limit(100)
            .execute()
        )
        return r.data or []
    except Exception:
        return []


def _fetch_recent_resolved_delete_requests(db_filename: str) -> list:
    """최근 처리 완료된 삭제 요청 목록 조회 (승인·반려 포함, 최근 20건).
    reviewed_at 컬럼이 없는 환경에서는 created_at 기준으로 정렬 fallback.
    """
    if not _supabase_orders_payments_available() or not db_filename:
        return []
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return []
        username = _current_username()
        # reviewed_at 포함 시도
        try:
            r = (
                sc.table("app_edit_requests")
                .select("id, created_at, reviewed_at, entity_id, requested_by, reason, status, reviewed_by, payload")
                .eq("db_filename", db_filename)
                .eq("notif_type", "delete_request")
                .eq("target_username", username)
                .in_("status", ["approved", "rejected"])
                .order("reviewed_at", desc=True)
                .limit(20)
                .execute()
            )
        except Exception:
            # reviewed_at / reviewed_by 컬럼 없는 경우 created_at 기준 fallback
            r = (
                sc.table("app_edit_requests")
                .select("id, created_at, entity_id, requested_by, reason, status, payload")
                .eq("db_filename", db_filename)
                .eq("notif_type", "delete_request")
                .eq("target_username", username)
                .in_("status", ["approved", "rejected"])
                .order("created_at", desc=True)
                .limit(20)
                .execute()
            )
        return r.data or []
    except Exception:
        return []


def _resolve_delete_request(request_id: int, action: str, reviewed_by: str, reject_reason: str = "", order_id: int | None = None, db_filename: str | None = None):
    """삭제 요청을 승인(approved) 또는 반려(rejected) 처리.
    action: 'approved' | 'rejected'
    order_id + db_filename 을 함께 넘기면 동일 주문의 다른 관리자 레코드도 일괄 처리.
    테이블 스키마에 없는 컬럼은 자동으로 제외하며 최소한 status만 업데이트.
    """
    def _try_update_with_fallback(sc, base_filter_fn, reject_reason: str):
        """reviewed_at → reviewed_by → status+reason → status 순으로 단계별 fallback."""
        base = {"status": action}
        if reject_reason:
            base["reason"] = reject_reason

        candidates = [
            {**base, "reviewed_by": reviewed_by, "reviewed_at": datetime.now(tz=KST).isoformat()},
            {**base, "reviewed_by": reviewed_by},
            base,
            {"status": action},
        ]
        last_err = None
        for payload in candidates:
            try:
                base_filter_fn(sc.table("app_edit_requests").update(payload)).execute()
                return True, None
            except Exception as e:
                last_err = e
                continue
        return False, str(last_err)

    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return False, str(err)

        # 1) 특정 레코드 업데이트
        ok, upd_err = _try_update_with_fallback(
            sc,
            lambda q: q.eq("id", request_id),
            reject_reason,
        )
        if not ok:
            return False, upd_err

        # 2) 같은 주문의 다른 관리자 레코드도 일괄 처리 (중복 표시 방지)
        if order_id is not None and db_filename:
            try:
                _try_update_with_fallback(
                    sc,
                    lambda q: q.eq("db_filename", db_filename).eq("entity_id", int(order_id)).eq("notif_type", "delete_request").eq("status", "pending"),
                    reject_reason,
                )
            except Exception:
                pass
        return True, None
    except Exception as e:
        return False, str(e)


def _snapshot_order_for_delete(db_filename: str, order_id: int) -> dict:
    """삭제 전 주문 상세 정보를 dict로 수집하여 반환. 삭제 후 payload에 보관용."""
    snap = {"order_id": order_id}
    try:
        if not _supabase_orders_payments_available() or not order_id:
            return snap
        order_detail = _get_order_supabase(db_filename, int(order_id))
        if not order_detail:
            return snap
        cid = order_detail.get("customer_id")
        cust_name = _get_customer_name_supabase(db_filename, int(cid)) if cid else "-"
        paid, _ = _sum_payments_by_order_supabase(db_filename, int(order_id))
        total_amount = float(order_detail.get("total_amount") or 0)
        snap.update({
            "customer_name": cust_name or "-",
            "order_date": str(order_detail.get("order_date") or "-")[:10],
            "delivery_date": str(order_detail.get("delivery_date") or "-")[:10],
            "category": str(order_detail.get("category") or "-"),
            "total_amount": int(total_amount),
            "paid_amount": int(paid),
            "balance": int(total_amount - paid),
            "employee_names": str(order_detail.get("employee_names") or "-"),
        })
    except Exception:
        pass
    return snap


def _save_order_snapshot_to_payload(db_filename: str, order_id: int, snapshot: dict):
    """app_edit_requests의 payload 컬럼에 스냅샷 JSON 저장 (삭제 승인 이후 상세 조회용)."""
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return
        import json as _json
        payload_json = _json.dumps(snapshot, ensure_ascii=False)
        (
            sc.table("app_edit_requests")
            .update({"payload": payload_json})
            .eq("db_filename", db_filename)
            .eq("entity_id", int(order_id))
            .eq("notif_type", "delete_request")
            .execute()
        )
    except Exception:
        pass


def _approve_delete_order(db_filename: str, order_id: int) -> tuple:
    """주문 및 연관 결제 데이터를 실제로 삭제한다 (관리자 승인 후 호출).
    반환: (성공여부: bool, 오류메시지: str | None)
    """
    try:
        if _supabase_orders_payments_available():
            sc, err = get_supabase_client()
            if err or not sc:
                return False, str(err)
            sc.table("app_payments").delete().eq("order_id", int(order_id)).eq("db_filename", db_filename).execute()
            try:
                sc.table("sales").delete().eq("order_id", int(order_id)).execute()
            except Exception:
                pass
            sc.table("app_orders").delete().eq("id", int(order_id)).eq("db_filename", db_filename).execute()
        else:
            conn = get_tenant_conn(db_filename)
            try:
                conn.execute("DELETE FROM Payments WHERE order_id = ?", (int(order_id),))
                conn.execute("DELETE FROM Orders WHERE id = ?", (int(order_id),))
                conn.commit()
            finally:
                conn.close()
        clear_data_cache()
        return True, None
    except Exception as e:
        return False, str(e)


def _render_admin_delete_requests(db_filename: str):
    """관리자 전용: 직원이 보낸 주문 삭제 요청 목록을 표시하고 승인/반려 처리."""
    st.header("🗑️ 주문 삭제 요청 관리")
    st.caption("직원이 보낸 주문 삭제 요청을 검토하고 승인 또는 반려합니다. 승인 시 주문과 결제 데이터가 영구 삭제됩니다.")

    reviewed_by = _current_username()

    # ── 대기 중인 요청 ──
    requests_list = _fetch_pending_delete_requests(db_filename, reviewed_by)

    if not requests_list:
        st.info("현재 처리 대기 중인 삭제 요청이 없습니다.")
    else:
        st.markdown(f"**⏳ 대기 중인 삭제 요청: {len(requests_list)}건**")
        for req in requests_list:
            req_id = req.get("id")
            order_id = req.get("entity_id")
            requester = req.get("requested_by", "알 수 없음")
            reason = req.get("reason", "")
            created = str(req.get("created_at", ""))[:16].replace("T", " ")

            # ── 주문 상세 정보 조회 ──
            order_detail = None
            cust_name = "-"
            order_date_str = "-"
            delivery_date_str = "-"
            category_str = "-"
            total_amount_str = "-"
            paid_str = "-"
            balance_str = "-"
            employee_str = "-"
            try:
                if _supabase_orders_payments_available() and order_id:
                    order_detail = _get_order_supabase(db_filename, int(order_id))
                    if order_detail:
                        cid = order_detail.get("customer_id")
                        if cid:
                            cust_name = _get_customer_name_supabase(db_filename, int(cid)) or "-"
                        order_date_str = str(order_detail.get("order_date") or "-")[:10]
                        delivery_date_str = str(order_detail.get("delivery_date") or "-")[:10]
                        category_str = str(order_detail.get("category") or "-")
                        total_amount = float(order_detail.get("total_amount") or 0)
                        total_amount_str = f"{int(total_amount):,}원"
                        employee_str = str(order_detail.get("employee_names") or "-")
                        paid, _ = _sum_payments_by_order_supabase(db_filename, int(order_id))
                        balance = total_amount - paid
                        paid_str = f"{int(paid):,}원"
                        balance_str = f"{int(balance):,}원"
            except Exception:
                pass

            with st.container(border=True):
                col_info, col_btns = st.columns([3, 2])
                with col_info:
                    st.markdown(f"**주문 #{order_id}** 삭제 요청")
                    st.caption(f"요청자: `{requester}` | 요청일시: {created}")
                    # 주문 상세 정보
                    info_col1, info_col2 = st.columns(2)
                    with info_col1:
                        st.write(f"👤 **고객명:** {cust_name}")
                        st.write(f"📅 **계약일:** {order_date_str}")
                        st.write(f"🚚 **배송일:** {delivery_date_str}")
                    with info_col2:
                        st.write(f"🛋️ **품목:** {category_str}")
                        st.write(f"💰 **계약금액:** {total_amount_str}")
                        st.write(f"💳 **결제액:** {paid_str} | 잔금: {balance_str}")
                    st.write(f"👥 **담당직원:** {employee_str}")
                    st.error(f"🗑️ **삭제 사유:** {reason or '(사유 없음)'}")
                with col_btns:
                    approve_key = f"del_approve_{req_id}"
                    reject_key = f"del_reject_{req_id}"
                    reject_reason_key = f"del_reject_reason_{req_id}"

                    if st.button("✅ 승인 (삭제 실행)", key=approve_key, type="primary"):
                        # 삭제 전 주문 스냅샷 저장 (삭제 후 내역 조회용)
                        _snap = _snapshot_order_for_delete(db_filename, order_id)
                        _save_order_snapshot_to_payload(db_filename, order_id, _snap)
                        ok, del_err = _approve_delete_order(db_filename, order_id)
                        if ok:
                            res_ok, res_err = _resolve_delete_request(req_id, "approved", reviewed_by, order_id=order_id, db_filename=db_filename)
                            if not res_ok:
                                st.warning(f"주문은 삭제되었으나 요청 상태 갱신 실패: {res_err}")
                            st.session_state[f"_del_done_{req_id}"] = order_id
                            st.toast(f"✅ 주문 #{order_id} 삭제 완료", icon="✅")
                            st.rerun()
                        else:
                            st.error(f"삭제 실패: {del_err}")
                            st.stop()

                    reject_reason_val = st.text_input("반려 사유 (선택)", key=reject_reason_key, placeholder="반려 이유를 입력하세요")
                    if st.button("❌ 반려", key=reject_key):
                        ok, rej_err = _resolve_delete_request(req_id, "rejected", reviewed_by, reject_reason_val, order_id=order_id, db_filename=db_filename)
                        if ok:
                            st.toast(f"주문 #{order_id} 삭제 요청이 반려되었습니다.", icon="❌")
                            st.session_state[f"_del_rejected_{req_id}"] = order_id
                            st.rerun()
                        else:
                            st.error(f"반려 처리 실패: {rej_err}")

    st.divider()

    # ── 최근 처리 완료 내역 ──
    st.markdown("#### 📋 최근 처리 완료 내역")
    resolved_list = _fetch_recent_resolved_delete_requests(db_filename)
    if not resolved_list:
        st.caption("최근 처리된 삭제 요청이 없습니다.")
    else:
        import json as _json

        # Excel 다운로드용 데이터 수집
        _dl_rows = []

        for res in resolved_list:
            r_order_id = res.get("entity_id")
            r_requester = res.get("requested_by", "알 수 없음")
            r_reason = res.get("reason", "")
            r_status = res.get("status", "")
            r_reviewed_by = res.get("reviewed_by", "")
            r_reviewed_at = str(res.get("reviewed_at") or "")[:16].replace("T", " ")
            r_created = str(res.get("created_at", ""))[:16].replace("T", " ")

            # payload에서 스냅샷 파싱 (jsonb→dict 또는 text→str 모두 처리)
            snap = {}
            try:
                raw_payload = res.get("payload")
                if isinstance(raw_payload, dict):
                    snap = raw_payload  # Supabase jsonb 타입: 이미 dict로 반환됨
                elif isinstance(raw_payload, str) and raw_payload.strip().startswith("{"):
                    snap = _json.loads(raw_payload)
            except Exception:
                snap = {}

            r_cust    = snap.get("customer_name", "-")
            r_date    = snap.get("order_date", "-")
            r_del     = snap.get("delivery_date", "-")
            r_cat     = snap.get("category", "-")
            r_total   = snap.get("total_amount")
            r_paid    = snap.get("paid_amount")
            r_bal     = snap.get("balance")
            r_emp     = snap.get("employee_names", "-")

            r_total_str = f"{int(r_total):,}원" if r_total is not None else "-"
            r_paid_str  = f"{int(r_paid):,}원"  if r_paid  is not None else "-"
            r_bal_str   = f"{int(r_bal):,}원"   if r_bal   is not None else "-"

            badge_icon = "✅" if r_status == "approved" else "❌"
            badge_label = "삭제 완료" if r_status == "approved" else "반려됨"

            with st.expander(
                f"{badge_icon} **주문 #{r_order_id}** [{badge_label}]  "
                f"ㅤ고객: {r_cust}ㅤ|ㅤ계약금액: {r_total_str}ㅤ|ㅤ처리일: {r_reviewed_at}",
                expanded=False,
            ):
                d_col1, d_col2 = st.columns(2)
                with d_col1:
                    st.write(f"👤 **고객명:** {r_cust}")
                    st.write(f"📅 **계약일:** {r_date}")
                    st.write(f"🚚 **배송일:** {r_del}")
                    st.write(f"🛋️ **품목:** {r_cat}")
                with d_col2:
                    st.write(f"💰 **계약금액:** {r_total_str}")
                    st.write(f"💳 **결제액:** {r_paid_str}  /  잔금: {r_bal_str}")
                    st.write(f"👥 **담당직원:** {r_emp}")
                st.divider()
                st.write(f"🗑️ **삭제 사유:** {r_reason or '(없음)'}")
                st.write(f"📋 **요청자:** `{r_requester}` | 요청일시: {r_created}")
                st.write(f"✍️ **처리자:** `{r_reviewed_by}` | 처리일시: {r_reviewed_at}")

            _dl_rows.append({
                "주문번호":    r_order_id,
                "처리결과":    badge_label,
                "고객명":      r_cust,
                "계약일":      r_date,
                "배송일":      r_del,
                "품목":        r_cat,
                "계약금액(원)": r_total if r_total is not None else "",
                "결제액(원)":   r_paid  if r_paid  is not None else "",
                "잔금(원)":     r_bal   if r_bal   is not None else "",
                "담당직원":    r_emp,
                "삭제사유":    r_reason or "",
                "요청자":      r_requester,
                "요청일시":    r_created,
                "처리자":      r_reviewed_by,
                "처리일시":    r_reviewed_at,
            })

        # ── Excel 다운로드 버튼 ──
        if _dl_rows:
            try:
                import io as _io
                _df_dl = pd.DataFrame(_dl_rows)
                _buf = _io.BytesIO()
                with pd.ExcelWriter(_buf, engine="openpyxl") as _ew:
                    _df_dl.to_excel(_ew, index=False, sheet_name="삭제처리내역")
                st.download_button(
                    label="📥 삭제 처리 내역 Excel 다운로드",
                    data=_buf.getvalue(),
                    file_name=f"삭제처리내역_{datetime.now(tz=KST).strftime('%Y%m%d_%H%M')}.xlsx",
                    mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    key="del_history_download_btn",
                )
            except Exception as _ex:
                st.caption(f"다운로드 준비 실패: {_ex}")

    if st.button("🔄 새로고침", key="del_req_refresh_btn"):
        st.rerun()


def _save_payment_receipt(conn: sqlite3.Connection, payment_id: int, uploaded_file):
    """온누리 등 결제 영수증 파일을 RECEIPT_DIR에 저장하고 PaymentReceipts에 경로 기록."""
    if uploaded_file is None:
        return
    try:
        raw_name = uploaded_file.name
    except Exception:
        raw_name = "receipt"
    name_root, ext = os.path.splitext(raw_name)
    if not ext:
        ext = ".bin"
    safe_ext = ext.lower()
    filename = f"{int(payment_id)}_{int(time.time())}{safe_ext}"
    file_path = os.path.join(RECEIPT_DIR, filename)
    try:
        with open(file_path, "wb") as f:
            f.write(uploaded_file.getbuffer())
    except Exception:
        return
    conn.execute(
        """
        INSERT INTO PaymentReceipts (payment_id, file_path, original_name, uploaded_by, uploaded_at)
        VALUES (?, ?, ?, ?, ?)
        """,
        (
            int(payment_id),
            file_path,
            raw_name,
            _current_username(),
            datetime.now(tz=KST).isoformat(),
        ),
    )


def _insert_payment_history(
    conn,
    sale_id: int,
    customer_name: str,
    action_type: str,
    old_payment_data,
    new_payment_data,
    reason: str,
    receipt_image_path: str | None = None,
    db_filename: str | None = None,
) -> None:
    """결제 변경 이력 1건 기록. Supabase(app_payment_history) 우선, SQLite conn 있으면 병행 저장.
    반환값: 오류 문자열(실패) 또는 None(성공)"""
    import math

    def _safe_json(obj):
        """NaN/Inf/pd.NA 등 JSON 직렬화 불가 값을 None으로 치환하는 재귀 변환."""
        if obj is None:
            return None
        if isinstance(obj, float) and (math.isnan(obj) or math.isinf(obj)):
            return None
        try:
            import pandas as _pd
            if obj is _pd.NA or obj is _pd.NaT:
                return None
        except Exception:
            pass
        if isinstance(obj, dict):
            return {k: _safe_json(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple)):
            return [_safe_json(v) for v in obj]
        return obj

    now_iso = datetime.now(tz=KST).isoformat()
    changed_by = _current_username() or "unknown"
    supa_error: str | None = None
    safe_old = _safe_json(old_payment_data or {})
    safe_new = _safe_json(new_payment_data or {})
    # ── Supabase 저장 ──
    if _supabase_orders_payments_available() and db_filename:
        try:
            sc, err = get_supabase_client()
            if err or not sc:
                supa_error = f"Supabase 클라이언트 오류: {err}"
            else:
                result = sc.table("app_payment_history").insert({
                    "db_filename": db_filename,
                    "sale_id": int(sale_id),
                    "customer_name": customer_name or "",
                    "action_type": action_type,
                    "old_payment_data": safe_old,
                    "new_payment_data": safe_new,
                    "reason": reason.strip(),
                    "changed_by": changed_by,
                    "changed_at": now_iso,
                    "receipt_image_path": receipt_image_path or None,
                }).execute()
                if hasattr(result, "error") and result.error:
                    supa_error = str(result.error)
        except Exception as _e:
            supa_error = str(_e)
    # ── 오류를 session_state에 누적 저장 (모니터링 페이지에서 표시) ──
    if supa_error:
        _errs = st.session_state.get("_ph_insert_errors", [])
        _errs.append(f"[{action_type}] {supa_error}")
        st.session_state["_ph_insert_errors"] = _errs[-5:]  # 최대 5건 보관
    # ── SQLite 저장 (로컬 환경 또는 병행) ──
    if conn:
        try:
            conn.execute(
                """
                INSERT INTO PaymentHistory (
                    sale_id, customer_name, action_type,
                    old_payment_data, new_payment_data,
                    reason, changed_by, changed_at, receipt_image_path
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    int(sale_id),
                    customer_name or "",
                    action_type,
                    json.dumps(safe_old, ensure_ascii=False),
                    json.dumps(safe_new, ensure_ascii=False),
                    reason.strip(),
                    changed_by,
                    now_iso,
                    receipt_image_path or None,
                ),
            )
        except Exception as _sqlite_e:
            if supa_error is None and not _supabase_orders_payments_available():
                supa_error = f"SQLite 저장 오류: {_sqlite_e}"
    return supa_error


def _render_order_cost_verify(db_filename: str, order_id: int):
    """선택 주문의 원가·매출액·마진 검증 패널. 변경 이력 뷰 상단에 표시."""
    import math

    # 주문 데이터 조회
    order_row = None
    payments_df = pd.DataFrame()
    if _supabase_orders_payments_available():
        try:
            sc, err = get_supabase_client()
            if sc and not err:
                r_o = sc.table("app_orders").select(
                    "id, order_date, category, employee_names, total_amount, cost_price, "
                    "display_sales_amount, display_cost_amount, actual_margin, balance_status"
                ).eq("id", int(order_id)).execute()
                if r_o.data:
                    order_row = r_o.data[0]
                r_p = sc.table("app_payments").select(
                    "payment_date, amount, payment_method, card_company, fee_amount"
                ).eq("db_filename", db_filename).eq("order_id", int(order_id)).order("payment_date").execute()
                if r_p.data:
                    payments_df = pd.DataFrame(r_p.data)
        except Exception:
            pass
    else:
        conn = get_tenant_conn(db_filename)
        if conn:
            try:
                order_row = conn.execute(
                    "SELECT id, order_date, category, employee_names, total_amount, cost_price, "
                    "display_sales_amount, display_cost_amount, actual_margin, balance_status "
                    "FROM Orders WHERE id=?", (int(order_id),)
                ).fetchone()
                if order_row:
                    cols = ["id","order_date","category","employee_names","total_amount","cost_price",
                            "display_sales_amount","display_cost_amount","actual_margin","balance_status"]
                    order_row = dict(zip(cols, order_row))
                p_rows = conn.execute(
                    "SELECT payment_date, amount, payment_method, card_company, fee_amount "
                    "FROM Payments WHERE order_id=? ORDER BY payment_date", (int(order_id),)
                ).fetchall()
                if p_rows:
                    payments_df = pd.DataFrame(p_rows, columns=["payment_date","amount","payment_method","card_company","fee_amount"])
            except Exception:
                pass
            finally:
                conn.close()

    if not order_row:
        st.warning("주문 데이터를 불러올 수 없습니다.")
        return

    st.markdown("#### 🔍 원가·매출액·마진 검증")

    total_amt   = float(order_row.get("total_amount") or 0)
    cost_price  = float(order_row.get("cost_price") or 0)
    disp_sale   = float(order_row.get("display_sales_amount") or 0)
    disp_cost   = float(order_row.get("display_cost_amount") or 0)
    stored_mg   = float(order_row.get("actual_margin") or 0)

    basic_mg    = total_amt - cost_price - disp_cost
    sum_fee     = float(payments_df["fee_amount"].fillna(0).sum()) if not payments_df.empty else 0.0
    recalc_mg   = basic_mg - sum_fee
    margin_rate = (recalc_mg / total_amt * 100) if total_amt else 0.0
    cost_rate   = ((cost_price + disp_cost) / total_amt * 100) if total_amt else 0.0

    # ── 요약 지표 4개 ──
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("판매금액", f"{total_amt:,.0f}원")
    c2.metric("원가 합계", f"{cost_price + disp_cost:,.0f}원", f"원가율 {cost_rate:.1f}%")
    c3.metric("수수료 합계", f"{sum_fee:,.0f}원")
    c4.metric("재계산 마진", f"{recalc_mg:,.0f}원", f"마진율 {margin_rate:.1f}%")

    # ── 상세 계산 과정 ──
    with st.expander("📐 계산 상세 보기", expanded=False):
        st.markdown(f"""
| 항목 | 금액 |
|---|---|
| 판매금액 (total_amount) | **{total_amt:,.0f}원** |
| 일반 원가 (cost_price) | {cost_price:,.0f}원 |
| 전시 원가 (display_cost_amount) | {disp_cost:,.0f}원 |
| 전시 판매가 (display_sales_amount) | {disp_sale:,.0f}원 |
| **기본 마진** (판매금액 − 원가 − 전시원가) | **{basic_mg:,.0f}원** |
| 결제 수수료 합계 | −{sum_fee:,.0f}원 |
| **재계산 actual_margin** | **{recalc_mg:,.0f}원** |
| DB 저장 actual_margin | {stored_mg:,.0f}원 {'✅' if abs(recalc_mg - stored_mg) < 1 else '⚠️ 불일치'} |
""")

    # ── 결제 내역 ──
    if not payments_df.empty:
        with st.expander(f"💳 결제 내역 ({len(payments_df)}건)", expanded=False):
            disp_p = payments_df.copy()
            disp_p["amount"] = disp_p["amount"].apply(lambda x: f"{float(x or 0):,.0f}원")
            disp_p["fee_amount"] = disp_p["fee_amount"].apply(lambda x: f"{float(x or 0):,.0f}원")
            disp_p = disp_p.rename(columns={
                "payment_date": "결제일", "amount": "결제금액",
                "payment_method": "결제수단", "card_company": "카드사", "fee_amount": "수수료"
            })
            st.dataframe(disp_p, width="stretch")
    else:
        st.caption("등록된 결제 내역이 없습니다.")

    # ── 이상 감지 경고 ──
    warnings = []
    if cost_price == 0 and disp_cost == 0:
        warnings.append("원가(cost_price)와 전시원가가 모두 0원입니다. 원가가 미입력된 것으로 보입니다.")
    if total_amt > 0 and margin_rate > 60:
        warnings.append(f"마진율이 {margin_rate:.1f}%로 비정상적으로 높습니다. 원가 입력을 확인하세요.")
    if total_amt > 0 and margin_rate < -5:
        warnings.append(f"마진율이 {margin_rate:.1f}%로 음수입니다. 판매금액 또는 원가 입력을 확인하세요.")
    if abs(recalc_mg - stored_mg) >= 1:
        warnings.append(f"저장된 마진({stored_mg:,.0f}원)과 재계산 마진({recalc_mg:,.0f}원)이 일치하지 않습니다. 결제 재계산이 필요할 수 있습니다.")

    if warnings:
        for w in warnings:
            st.warning(f"⚠️ {w}")
    else:
        st.success("✅ 원가·마진 검증 이상 없음")

    if _supabase_orders_payments_available():
        try:
            sc2, err2 = get_supabase_client()
            if sc2 and not err2:
                _ir = (
                    sc2.table("app_order_items")
                    .select("line_cost")
                    .eq("order_id", int(order_id))
                    .execute()
                )
                _hq = sum(float(x.get("line_cost") or 0) for x in (_ir.data or []))
                if _hq > 0:
                    _seller = cost_price + disp_cost
                    _gap = _seller - _hq
                    st.caption(
                        f"입력원가 {_seller:,.0f}원 · 본사원가 {_hq:,.0f}원 · 원가차이 {_gap:,.0f}원"
                    )
                    if _seller == 0:
                        st.warning("원가 미입력 — 본사 원장 원가만 있습니다.")
                    elif abs(_gap) >= 10000 or (abs(_gap) / max(_hq, _seller, 1)) >= 0.05:
                        st.error(f"원가 불일치 (입력 {_seller:,.0f} / 본사 {_hq:,.0f})")
        except Exception:
            pass


def _render_order_line_items(db_filename: str, order_id: int) -> None:
    """주문에 연결된 라인 아이템(app_order_items) 을 읽기 전용 테이블로 표시.

    매입 원장 임포트로 저장된 품명·품번·수량·출고가·부가세 상세를 보여준다.
    테이블/데이터가 없으면 조용히 아무 것도 표시하지 않음.
    """
    try:
        sc, err = get_supabase_client()
        if err or not sc:
            return
        r = sc.table("app_order_items").select(
            "product_code, product_name, quantity, unit_cost, line_cost, vat, line_total, ship_number, item_note, order_kind"
        ).eq("order_id", int(order_id)).order("id").execute()
        rows = (r.data or []) if hasattr(r, "data") else []
    except Exception:
        # 테이블 미존재 등: 조용히 스킵 (SUPABASE_APP_ORDER_ITEMS.sql 미실행 환경)
        return
    if not rows:
        return
    _df = pd.DataFrame(rows).rename(columns={
        "product_code": "품번",
        "product_name": "품명",
        "quantity": "수량",
        "unit_cost": "출고가",
        "line_cost": "주문금액",
        "vat": "부가세",
        "line_total": "합계",
        "ship_number": "출고번호",
        "item_note": "품목비고",
        "order_kind": "구분",
    })
    _sum_qty = int(_df["수량"].sum()) if "수량" in _df else 0
    _sum_cost = int(_df["주문금액"].sum()) if "주문금액" in _df else 0
    _sum_total = int(_df["합계"].sum()) if "합계" in _df else 0
    st.markdown(f"##### 📦 매입 원장 라인 아이템 ({len(_df)}건 · 수량 합 {_sum_qty:,} · 매입금액 합 {_sum_cost:,}원 · 합계 {_sum_total:,}원)")
    st.dataframe(_df, width="stretch", hide_index=True)


def _render_order_audit_trail(db_filename: str, order_id: int):
    """주문(Order) 기준 변경 이력(AuditLogs) + 관련 결제 영수증 표시 공통 UI.
    Supabase 환경: app_edit_requests 테이블에서 이력 조회. SQLite 환경: AuditLogs 테이블 사용."""
    # ── 원가·매출액 검증 패널 ──
    _render_order_cost_verify(db_filename, order_id)
    st.divider()
    # ── 매입 원장 라인 아이템 (있는 경우만) ──
    _render_order_line_items(db_filename, order_id)
    logs = pd.DataFrame()
    # ── Supabase 경로 ──
    if _supabase_orders_payments_available():
        import re as _re
        all_events: list[dict] = []

        # 1. app_edit_requests: 직원명/필드 변경 명시적 이력
        try:
            sc, err = get_supabase_client()
            if sc and not err:
                r = sc.table("app_edit_requests").select(
                    "created_at, requested_by, payload, reason, status, reviewed_by, reviewed_at"
                ).eq("db_filename", db_filename).eq("entity_id", int(order_id)).eq("entity_type", "Order").order("created_at", desc=True).execute()
                for x in (r.data or []):
                    all_events.append({
                        "source": "edit_request",
                        "created_at": (x.get("created_at") or "")[:16],
                        "actor": x.get("requested_by") or "-",
                        "payload": str(x.get("payload") or ""),
                        "reason": x.get("reason") or "-",
                        "status": x.get("status") or "-",
                        "reviewed_by": x.get("reviewed_by") or "-",
                        "amount": None,
                        "note_display": None,
                    })
        except Exception:
            pass

        # 2. sales 테이블: 매출 등록/변경 이력 (금액 변경 차액 포함)
        # order_id는 전역 고유값이므로 테넌트 필터 없이 조회 (db_filename=NULL 레코드도 포함)
        try:
            sc2, err2 = get_supabase_client()
            if sc2 and not err2:
                sq = sc2.table("sales").select(
                    "transaction_date, amount, note, employee_names"
                ).eq("order_id", int(order_id)).order("transaction_date", desc=True)
                rs = sq.execute()
                for x in (rs.data or []):
                    note_raw = str(x.get("note") or "")
                    note_display = note_raw.split("|__dm:")[0].strip() if "|__dm:" in note_raw else note_raw
                    amt = float(x.get("amount") or 0)
                    all_events.append({
                        "source": "sales",
                        "created_at": str(x.get("transaction_date") or "")[:10],
                        "actor": str(x.get("employee_names") or "-"),
                        "payload": note_raw,
                        "reason": note_display or "-",
                        "status": "confirmed",
                        "reviewed_by": "-",
                        "amount": amt,
                        "note_display": note_display,
                    })
        except Exception:
            pass

        # 3. 통합 정렬 (최신순)
        all_events.sort(key=lambda e: e["created_at"], reverse=True)

        if not all_events:
            st.info("변경 이력이 없습니다.")
        else:
            # 현재 주문 원가 정보 (before/after 마진 계산용)
            _order_cost_info: dict = {}
            try:
                sc3, _ = get_supabase_client()
                if sc3:
                    _oc = sc3.table("app_orders").select(
                        "cost_price, display_cost_amount, display_sales_amount"
                    ).eq("id", int(order_id)).execute()
                    if _oc.data:
                        _order_cost_info = _oc.data[0]
            except Exception:
                pass
            _cost_price = float(_order_cost_info.get("cost_price") or 0)
            _disp_cost  = float(_order_cost_info.get("display_cost_amount") or 0)

            # ── sales 이벤트 누적합 사전 계산 (Before/After 판매금액 표시용) ──
            _sales_running = 0.0
            for _e in sorted(all_events, key=lambda x: x["created_at"]):
                if _e["source"] == "sales":
                    _e["_sales_before"] = _sales_running
                    _sales_running += float(_e["amount"] or 0)
                    _e["_sales_after"] = _sales_running

            st.caption(f"총 {len(all_events)}건의 이력이 있습니다.")
            for evt in all_events:
                if evt["source"] == "sales":
                    amt = evt["amount"] or 0
                    amt_str = f"{amt:+,.0f}원" if amt != 0 else ""
                    _s_label = "💰 매출 등록" if amt >= 0 else "📉 매출 차감(변경)"
                    s_before = evt.get("_sales_before", 0)
                    s_after  = evt.get("_sales_after", 0)
                    # 원가는 현재 DB 기준 (변경이력 없으면 동일값)
                    _total_cost = _cost_price + _disp_cost
                    _margin_before = s_before - _total_cost
                    _margin_after  = s_after  - _total_cost
                    _rate_before = (_margin_before / s_before * 100) if s_before else 0
                    _rate_after  = (_margin_after  / s_after  * 100) if s_after  else 0
                    with st.expander(f"{evt['created_at']} — {evt['actor']} | {_s_label} {amt_str}"):
                        st.write(f"**내용:** {evt['note_display'] or '-'}")
                        st.write(f"**담당직원:** {evt['actor']}")
                        # ── 매출·원가·마진 Before / After 테이블 ──
                        st.markdown("**📊 매출·원가·마진 변동**")
                        _c1, _c2 = st.columns(2)
                        with _c1:
                            st.markdown("**변경 전**")
                            st.markdown(
                                f"| 항목 | 금액 |\n|---|---|\n"
                                f"| 판매금액 | {s_before:,.0f}원 |\n"
                                f"| 원가 합계 | {_total_cost:,.0f}원 |\n"
                                f"| **마진** | **{_margin_before:,.0f}원** |\n"
                                f"| 마진율 | {_rate_before:.1f}% |"
                            )
                        with _c2:
                            st.markdown("**변경 후**")
                            st.markdown(
                                f"| 항목 | 금액 |\n|---|---|\n"
                                f"| 판매금액 | {s_after:,.0f}원 |\n"
                                f"| 원가 합계 | {_total_cost:,.0f}원 |\n"
                                f"| **마진** | **{_margin_after:,.0f}원** |\n"
                                f"| 마진율 | {_rate_after:.1f}% |"
                            )
                        _dm_delta = _margin_after - _margin_before
                        _dm_color = "red" if _dm_delta < 0 else "green"
                        st.markdown(f"**판매금액 변화:** {amt:+,.0f}원  |  **마진 변화:** :{_dm_color}[{_dm_delta:+,.0f}원]")
                        # KPI 마진 영향: 마진 변화 전체를 표시 (직원이 체감하는 실질 영향과 동일)
                        if "|__dm:" in evt["payload"]:
                            _dm_kpi_color = "red" if _dm_delta < 0 else "green"
                            st.caption(f"※ KPI 마진 영향: :{_dm_kpi_color}[{_dm_delta:+,.0f}원]")
                else:
                    # app_edit_requests 이력
                    _payload = evt["payload"]
                    _ptype = ""
                    if "[high_amount_change]" in _payload:
                        _ptype = "high_amount_change"
                    elif "[payment_cancel]" in _payload:
                        _ptype = "payment_cancel"
                    _status_icon = "✅" if evt["status"] == "approved" else ("❌" if evt["status"] == "rejected" else "⏳")
                    _type_label = {
                        "high_amount_change": "📉 판매금액 변경",
                        "payment_cancel": "💳 결제 취소",
                    }.get(_ptype, "📋 필드 변경")
                    with st.expander(f"{evt['created_at']} — {evt['actor']} | {_type_label} [{_status_icon} {evt['status']}]"):
                        st.write(f"**사유:** {evt['reason']}")
                        st.write(f"**검토자:** {evt['reviewed_by']}")
                        # ── payload 파싱: "필드: X원 → Y원" 형식 항목 테이블 표시 ──
                        _field_rows = []
                        for _seg in _payload.split("|"):
                            _seg = _seg.strip()
                            if "→" in _seg and ":" in _seg:
                                _fname, _fval = _seg.split(":", 1)
                                _fname = _fname.strip()
                                _parts = _fval.split("→")
                                if len(_parts) == 2:
                                    _field_rows.append((_fname, _parts[0].strip(), _parts[1].strip()))
                        if _field_rows:
                            st.markdown("**📋 변경 항목**")
                            _tbl = "| 항목 | 변경 전 | 변경 후 |\n|---|---|---|\n"
                            _tbl += "\n".join(f"| {r[0]} | {r[1]} | {r[2]} |" for r in _field_rows)
                            st.markdown(_tbl)
                            # 원가·판매금액 변경이 포함된 경우 마진 before/after 추가 계산
                            _sale_row = next((r for r in _field_rows if "판매금액" in r[0]), None)
                            _cost_row = next((r for r in _field_rows if "원가" in r[0] and "전시" not in r[0]), None)
                            _dcost_row = next((r for r in _field_rows if "전시품원가" in r[0]), None)
                            if _sale_row or _cost_row or _dcost_row:
                                def _parse_amt(s):
                                    try:
                                        return float(s.replace(",", "").replace("원", "").strip())
                                    except Exception:
                                        return None
                                _sale_b = _parse_amt(_sale_row[1]) if _sale_row else _cost_price + _disp_cost + (_cost_price if not _cost_row else 0)
                                _sale_a = _parse_amt(_sale_row[2]) if _sale_row else None
                                _cost_b = _parse_amt(_cost_row[1]) if _cost_row else _cost_price
                                _cost_a = _parse_amt(_cost_row[2]) if _cost_row else _cost_price
                                _dc_b   = _parse_amt(_dcost_row[1]) if _dcost_row else _disp_cost
                                _dc_a   = _parse_amt(_dcost_row[2]) if _dcost_row else _disp_cost
                                if _sale_b is not None and _sale_a is not None and _cost_b is not None and _cost_a is not None:
                                    _mg_b = _sale_b - _cost_b - _dc_b
                                    _mg_a = _sale_a - _cost_a - _dc_a
                                    _rate_b2 = (_mg_b / _sale_b * 100) if _sale_b else 0
                                    _rate_a2 = (_mg_a / _sale_a * 100) if _sale_a else 0
                                    st.markdown("**📊 마진 Before / After**")
                                    _cx1, _cx2 = st.columns(2)
                                    with _cx1:
                                        st.markdown(f"**변경 전**\n\n마진 **{_mg_b:,.0f}원** ({_rate_b2:.1f}%)")
                                    with _cx2:
                                        st.markdown(f"**변경 후**\n\n마진 **{_mg_a:,.0f}원** ({_rate_a2:.1f}%)")
                                    _dmc = "red" if (_mg_a - _mg_b) < 0 else "green"
                                    st.markdown(f"**마진 변화:** :{_dmc}[{_mg_a - _mg_b:+,.0f}원]")
                        else:
                            st.caption(f"변경 내용: {_payload}")
                        # 구형 high_amount_change 포맷 처리 (X원 → Y원 패턴)
                        if _ptype == "high_amount_change" and not _field_rows:
                            _m = _re.search(r"([\d,]+)원\s*→\s*([\d,]+)원", _payload)
                            if _m:
                                _old_total = float(_m.group(1).replace(",", ""))
                                _new_total = float(_m.group(2).replace(",", ""))
                                _old_margin = _old_total - _cost_price - _disp_cost
                                _new_margin = _new_total - _cost_price - _disp_cost
                                _old_rate = (_old_margin / _old_total * 100) if _old_total else 0
                                _new_rate = (_new_margin / _new_total * 100) if _new_total else 0
                                _delta_margin = _new_margin - _old_margin
                                st.markdown("**📊 원가·마진 Before / After 검증**")
                                _ca, _cb = st.columns(2)
                                with _ca:
                                    st.markdown("**변경 전**")
                                    st.markdown(f"| 항목 | 금액 |\n|---|---|\n| 판매금액 | {_old_total:,.0f}원 |\n| 원가 합계 | {_cost_price + _disp_cost:,.0f}원 |\n| **마진** | **{_old_margin:,.0f}원** |\n| 마진율 | {_old_rate:.1f}% |")
                                with _cb:
                                    st.markdown("**변경 후**")
                                    st.markdown(f"| 항목 | 금액 |\n|---|---|\n| 판매금액 | {_new_total:,.0f}원 |\n| 원가 합계 | {_cost_price + _disp_cost:,.0f}원 |\n| **마진** | **{_new_margin:,.0f}원** |\n| 마진율 | {_new_rate:.1f}% |")
                                _dm_color = "red" if _delta_margin < 0 else "green"
                                st.markdown(f"**마진 변화:** :{_dm_color}[{_delta_margin:+,.0f}원]  |  판매금액 변화: {_new_total - _old_total:+,.0f}원")
        return
    # ── SQLite 경로 ──
    conn = get_tenant_conn(db_filename)
    if not conn:
        st.info("이력 정보를 불러올 수 없습니다.")
        return
    try:
        logs = pd.read_sql(
            """
            SELECT created_at, actor_username, field_name, old_value, new_value, reason
            FROM AuditLogs
            WHERE entity_type = 'Order' AND entity_id = ?
            ORDER BY created_at DESC
            """,
            conn,
            params=(int(order_id),),
        )
    except Exception:
        logs = pd.DataFrame()
    # SQLite 경로 원가 정보 (before/after 마진 계산용)
    _sq_cost_price = 0.0
    _sq_disp_cost  = 0.0
    try:
        _sq_conn = get_tenant_conn(db_filename)
        if _sq_conn:
            _sq_r = _sq_conn.execute(
                "SELECT cost_price, display_cost_amount FROM Orders WHERE id=?", (int(order_id),)
            ).fetchone()
            if _sq_r:
                _sq_cost_price = float(_sq_r[0] or 0)
                _sq_disp_cost  = float(_sq_r[1] or 0)
            _sq_conn.close()
    except Exception:
        pass

    if len(logs) == 0:
        st.info("변경 이력이 없습니다.")
    else:
        import re as _re2
        for _, row in logs.iterrows():
            with st.expander(f"{row['created_at']} — {row['actor_username']} / {row['field_name']}"):
                st.write(f"필드: **{row['field_name']}**")
                st.write(f"변경 전: `{row['old_value']}`")
                st.write(f"변경 후: `{row['new_value']}`")
                st.write(f"사유: {row['reason']}")
                # total_amount 필드 변경 시 before/after 마진 검증
                if str(row.get("field_name") or "").strip() == "total_amount":
                    try:
                        _sq_old = float(str(row.get("old_value") or "0").replace(",", ""))
                        _sq_new = float(str(row.get("new_value") or "0").replace(",", ""))
                        _sq_old_mg = _sq_old - _sq_cost_price - _sq_disp_cost
                        _sq_new_mg = _sq_new - _sq_cost_price - _sq_disp_cost
                        _sq_old_rate = (_sq_old_mg / _sq_old * 100) if _sq_old else 0
                        _sq_new_rate = (_sq_new_mg / _sq_new * 100) if _sq_new else 0
                        st.markdown("**📊 원가·마진 Before / After 검증**")
                        _sc1, _sc2 = st.columns(2)
                        with _sc1:
                            st.markdown(f"**변경 전:** 판매 {_sq_old:,.0f}원 / 마진 {_sq_old_mg:,.0f}원 ({_sq_old_rate:.1f}%)")
                        with _sc2:
                            st.markdown(f"**변경 후:** 판매 {_sq_new:,.0f}원 / 마진 {_sq_new_mg:,.0f}원 ({_sq_new_rate:.1f}%)")
                        st.markdown(f"마진 변화: **{_sq_new_mg - _sq_old_mg:+,.0f}원**")
                    except Exception:
                        pass
    # 관련 결제 영수증 조회 (SQLite 전용)
    try:
        receipts = pd.read_sql(
            """
            SELECT pr.id, pr.file_path, pr.original_name, pr.uploaded_by, pr.uploaded_at, p.id AS payment_id, p.amount, p.payment_date
            FROM PaymentReceipts pr
            JOIN Payments p ON p.id = pr.payment_id
            WHERE p.order_id = ?
            ORDER BY pr.uploaded_at DESC
            """,
            conn,
            params=(int(order_id),),
        )
    except Exception:
        receipts = pd.DataFrame()
    finally:
        conn.close()
    if len(receipts) > 0:
        st.subheader("관련 결제 영수증")
        for _, r in receipts.iterrows():
            with st.expander(f"영수증 #{r['id']} — 결제ID {r['payment_id']} / {r['amount']:,.0f}원 / {r['uploaded_at']}"):
                st.write(f"업로더: {r['uploaded_by']}")
                st.write(f"원본 파일명: {r['original_name']}")
                if os.path.exists(r["file_path"]):
                    st.image(r["file_path"], caption=r["original_name"], use_column_width=True)


def render_margin_monitor():
    """마진 모니터링: 정상 마진율(20%) 대비 ±3% 초과 이탈 주문 표시. store_admin·superadmin 전용."""
    _user = st.session_state.get("current_user") or {}
    role = _user.get("role", "")
    if role not in ("store_admin", "superadmin"):
        st.error("접근 권한이 없습니다.")
        return

    # 이상 마진 기준: 17% 이하 또는 23% 이상
    MARGIN_LOW = 17.0
    MARGIN_HIGH = 23.0

    st.header("📊 마진 모니터링")
    st.caption(
        f"정상 마진율 기준 **{MARGIN_LOW}% 초과 ~ {MARGIN_HIGH}% 미만** 범위를 벗어난 주문을 표시합니다.  \n"
        "마진율 = (판매가 − 일반원가 − **전시원가**) ÷ 판매가 × 100 (원가 기준, 수수료 별도)"
    )

    # ── 기간 선택 ──
    today = _today_kst()
    from calendar import monthrange
    month_start = today.replace(day=1)
    month_end = date(today.year, today.month, monthrange(today.year, today.month)[1])

    col_s, col_e = st.columns(2)
    with col_s:
        start_d = st.date_input("조회 시작일", value=month_start, key="mm_start")
    with col_e:
        end_d = st.date_input("조회 종료일", value=today, key="mm_end")

    # ── 매장 선택 (superadmin) / 단일 매장 (store_admin) ──
    sc, _ = get_supabase_client()
    if not sc:
        st.error("Supabase 연결에 실패했습니다.")
        return

    target_stores: list[dict] = []
    if role == "superadmin":
        stores_df = get_supabase_stores_dataframe_cached()
        store_opts = ["전체 매장"] + stores_df["store_name"].tolist()
        sel_store = st.selectbox("매장 선택", store_opts, key="mm_store_sel")
        if sel_store == "전체 매장":
            target_stores = stores_df[["store_name", "db_filename"]].to_dict("records")
        else:
            row = stores_df[stores_df["store_name"] == sel_store].iloc[0]
            target_stores = [{"store_name": row["store_name"], "db_filename": row["db_filename"]}]
    else:
        db_fn = st.session_state.get("current_db")
        store_name = _get_store_name_by_db(db_fn) or db_fn
        target_stores = [{"store_name": store_name, "db_filename": db_fn}]

    if st.button("🔍 조회", key="mm_search_btn", type="primary"):
        st.session_state["mm_queried"] = True

    if not st.session_state.get("mm_queried"):
        st.info("조회 버튼을 눌러 이상 마진 주문을 확인하세요.")
        return

    # ── 데이터 조회 ──
    all_rows = []
    for s in target_stores:
        db_fn = s["db_filename"]
        store_nm = s["store_name"]
        orders = _load_orders_supabase(
            db_fn,
            "id, order_date, employee_names, total_amount, cost_price, display_sales_amount, display_cost_amount, actual_margin, customer_id",
            limit=None,
            start_date=start_d.isoformat(),
            end_date=end_d.isoformat(),
        )
        if orders is None or orders.empty:
            continue
        orders["_store"] = store_nm
        # 고객명 조회 후 merge
        customers_df = load_customers_cached(db_fn, limit=None, col_list="id, name")
        if not customers_df.empty and "customer_id" in orders.columns:
            orders["customer_id"] = pd.to_numeric(orders["customer_id"], errors="coerce")
            customers_df["id"] = pd.to_numeric(customers_df["id"], errors="coerce")
            orders = orders.merge(customers_df[["id", "name"]], left_on="customer_id", right_on="id", how="left")
            orders = orders.rename(columns={"name": "고객명"})
            orders = orders.drop(columns=["id_y"], errors="ignore").rename(columns={"id_x": "id"})
        else:
            orders["고객명"] = ""
        all_rows.append(orders)

    if not all_rows:
        st.success("✅ 선택 기간에 주문 데이터가 없습니다.")
        return

    df = pd.concat(all_rows, ignore_index=True)
    for _c in ["total_amount", "cost_price", "display_cost_amount", "display_sales_amount", "actual_margin"]:
        df[_c] = pd.to_numeric(df[_c], errors="coerce").fillna(0)

    # 판매가 0이면 제외
    df = df[df["total_amount"] > 0].copy()

    # ── 마진율 재계산 (전시품 원가 명시적 포함, 수수료 제외 원가 기준) ──
    # 전시품 판매가(display_sales_amount)는 total_amount에 이미 합산되어 있음
    # 전시품 원가(display_cost_amount)를 명시적으로 차감하여 재계산
    df["재계산_마진액"] = df["total_amount"] - df["cost_price"] - df["display_cost_amount"]
    df["마진율(%)"] = (df["재계산_마진액"] / df["total_amount"] * 100).round(1)
    # DB actual_margin 기준 마진율 (수수료 포함 실질마진, 참고용)
    df["실질마진율(수수료포함,%)"] = (df["actual_margin"] / df["total_amount"] * 100).round(1)

    # ── 이상 마진 필터: 17% 이하(<=) 또는 23% 이상(>=) ──
    abnormal = df[
        (df["마진율(%)"] <= MARGIN_LOW) |
        (df["마진율(%)"] >= MARGIN_HIGH)
    ].copy()

    if abnormal.empty:
        st.success(f"✅ 선택 기간에 이상 마진 주문이 없습니다. (기준: {MARGIN_LOW}% 이하 또는 {MARGIN_HIGH}% 이상)")
        return

    # 이상 유형 분류
    def _margin_flag(rate):
        if rate < 0:
            return "🔴 음수 마진"
        elif rate <= MARGIN_LOW:
            return "🟠 마진 낮음 (17% 이하)"
        else:
            return "🟡 마진 높음 (23% 이상)"

    abnormal["이상 유형"] = abnormal["마진율(%)"].apply(_margin_flag)

    # 표시 컬럼 구성
    disp = abnormal.rename(columns={
        "_store": "매장명",
        "id": "주문ID",
        "order_date": "주문일",
        "employee_names": "담당직원",
        "total_amount": "판매금액",
        "cost_price": "일반원가",
        "display_sales_amount": "전시판매가",
        "display_cost_amount": "전시원가",
        "재계산_마진액": "마진액(원가기준)",
        "actual_margin": "실질마진액(수수료포함)",
    })
    show_cols = ["매장명", "주문ID", "주문일", "고객명", "담당직원",
                 "판매금액", "일반원가", "전시판매가", "전시원가",
                 "마진액(원가기준)", "마진율(%)", "실질마진율(수수료포함,%)", "이상 유형"]
    if role != "superadmin":
        show_cols = [c for c in show_cols if c != "매장명"]
    disp = disp[[c for c in show_cols if c in disp.columns]].sort_values("마진율(%)")

    # 유형별 건수 요약
    low_cnt = (abnormal["마진율(%)"] <= MARGIN_LOW).sum()
    high_cnt = (abnormal["마진율(%)"] >= MARGIN_HIGH).sum()
    st.error(
        f"⚠️ 이상 마진 주문 **{len(disp)}건** 발견  \n"
        f"🟠 마진 낮음(17% 이하): **{low_cnt}건** | 🟡 마진 높음(23% 이상): **{high_cnt}건**"
    )

    # 통화 포맷
    disp_fmt = disp.copy()
    for col in ["판매금액", "일반원가", "전시판매가", "전시원가", "마진액(원가기준)", "실질마진액(수수료포함)"]:
        if col in disp_fmt.columns:
            disp_fmt[col] = disp_fmt[col].apply(lambda x: f"{int(x):,}원")
    disp_fmt["마진율(%)"] = disp_fmt["마진율(%)"].apply(lambda x: f"{x:.1f}%")
    if "실질마진율(수수료포함,%)" in disp_fmt.columns:
        disp_fmt["실질마진율(수수료포함,%)"] = disp_fmt["실질마진율(수수료포함,%)"].apply(lambda x: f"{x:.1f}%")
    st.dataframe(disp_fmt, width="stretch")
    st.caption(
        "※ **마진율(%)** = (판매금액 − 일반원가 − 전시원가) ÷ 판매금액 × 100 (원가 기준, 수수료 미포함)  \n"
        "※ **실질마진율** = actual_margin ÷ 판매금액 × 100 (수수료 차감 후 실질 마진, 참고용)"
    )

    # 엑셀 다운로드
    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as writer:
        disp.to_excel(writer, sheet_name="이상마진주문", index=False)
    buf.seek(0)
    st.download_button(
        "📥 이상 마진 주문 엑셀 다운로드",
        data=buf.getvalue(),
        file_name=f"이상마진모니터링_{start_d.isoformat()}_{end_d.isoformat()}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        key="mm_dl_btn",
    )


def render_payment_history_monitor():
    """매장 관리자/최고 관리자용 결제 변경/취소 모니터링 화면. Supabase app_payment_history 우선."""
    db_filename = st.session_state.get("current_db")
    if not db_filename:
        st.warning("매장에 로그인한 후 이용하세요.")
        return

    st.header("🚨 결제 변경/취소 모니터링")

    # ── 진단 패널 ──
    _has_ph_errors = bool(st.session_state.get("_ph_insert_errors"))
    with st.expander("🔧 Supabase 테이블 진단 (문제 발생 시 확인)", expanded=_has_ph_errors):
        _diag_supa = _supabase_orders_payments_available()
        st.write(f"**Supabase 연결 상태:** {'✅ 정상' if _diag_supa else '❌ 연결 실패'}")
        st.write(f"**현재 매장 DB:** `{db_filename}`")
        if _diag_supa:
            try:
                _sc, _ = get_supabase_client()
                _test_r = _sc.table("app_payment_history").select("id").eq("db_filename", db_filename).limit(1).execute()
                st.success(f"✅ app_payment_history 테이블 정상 접근 가능 (전체 행 확인 중...)")
                _cnt_r = _sc.table("app_payment_history").select("id", count="exact").eq("db_filename", db_filename).execute()
                _total = _cnt_r.count if hasattr(_cnt_r, "count") else len(_cnt_r.data or [])
                st.info(f"현재 매장 이력 총 {_total}건 저장됨")
            except Exception as _diag_e:
                st.error(f"❌ app_payment_history 접근 오류: {_diag_e}")
                st.warning("Supabase 대시보드 → SQL Editor에서 아래 SQL을 실행해 테이블을 재생성하세요.")
                st.code("""DROP TABLE IF EXISTS app_payment_history;
CREATE TABLE app_payment_history (
    id                  BIGSERIAL PRIMARY KEY,
    db_filename         TEXT NOT NULL,
    sale_id             BIGINT NOT NULL,
    customer_name       TEXT,
    action_type         TEXT NOT NULL,
    old_payment_data    JSONB,
    new_payment_data    JSONB,
    reason              TEXT NOT NULL,
    changed_by          TEXT NOT NULL,
    changed_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    receipt_image_path  TEXT
);
CREATE INDEX idx_aph_db ON app_payment_history (db_filename);
CREATE INDEX idx_aph_sale ON app_payment_history (sale_id);
ALTER TABLE app_payment_history ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "allow_all_app_payment_history" ON app_payment_history;
CREATE POLICY "allow_all_app_payment_history" ON app_payment_history FOR ALL USING (true) WITH CHECK (true);""", language="sql")
        # 저장된 오류 메시지 표시
        _ph_errors_diag = st.session_state.get("_ph_insert_errors", [])
        if _ph_errors_diag:
            st.error(f"마지막 저장 오류: {_ph_errors_diag}")
            if st.button("오류 기록 초기화"):
                st.session_state["_ph_insert_errors"] = []
                st.rerun()

    # 저장 오류 팝업 (최근 저장 시 오류가 있었으면 상단에 표시 — pop하지 않고 유지하여 재진입 시에도 보임)
    _ph_errors = st.session_state.get("_ph_insert_errors", [])
    if _ph_errors:
        st.error(f"🚨 결제 이력 Supabase 저장 오류 {len(_ph_errors)}건 발생! 아래 '진단' 패널을 확인하세요.")
        for _err_msg in _ph_errors:
            st.warning(f"저장 실패: {_err_msg}")

    col1, col2, col3, col4 = st.columns(4)
    with col1:
        search_name = st.text_input("고객명 검색", key="ph_search_name")
    with col2:
        start_date = st.date_input("시작일", value=_today_kst() - timedelta(days=7), key="ph_start")
    with col3:
        end_date = st.date_input("종료일", value=_today_kst(), key="ph_end")
    with col4:
        action_filter = st.multiselect(
            "작업 유형",
            [
                "잔금결제",
                "결제취소",
                "재결제",
                "결제변경",
                "판매금액변경",  # 계약(판매) 금액 변경
                "계약변경",      # 기존 기록 호환용
                "금액변경",      # 구 버전 호환용
            ],
            default=[],
        )
    user_filter = st.text_input("작업자(직원 ID) 필터", key="ph_user_filter")

    df = pd.DataFrame()

    # ── Supabase 조회 (DB 레벨에서 날짜 범위 필터링) ──
    if _supabase_orders_payments_available():
        try:
            sc, err = get_supabase_client()
            if sc and not err:
                # Supabase TIMESTAMPTZ는 UTC 기준 — KST(UTC+9) 기준으로 하루 여유를 둬서 조회
                _start_iso = start_date.isoformat() + "T00:00:00"
                _end_iso   = end_date.isoformat()   + "T23:59:59"
                q = (
                    sc.table("app_payment_history")
                    .select("id, sale_id, customer_name, action_type, old_payment_data, new_payment_data, reason, changed_by, changed_at")
                    .eq("db_filename", db_filename)
                    .gte("changed_at", _start_iso)
                    .lte("changed_at", _end_iso)
                    .order("changed_at", desc=True)
                    .limit(2000)
                )
                r = q.execute()
                rows = r.data or []
                if rows:
                    df = pd.DataFrame(rows)
                    df = df.rename(columns={"id": "log_id"})
                    st.caption(f"📋 Supabase에서 {len(df):,}건 조회됨")
                else:
                    # 날짜 범위 내 데이터 없음 — 전체 건수도 확인
                    _total_r = sc.table("app_payment_history").select("id", count="exact").eq("db_filename", db_filename).execute()
                    _total = _total_r.count if hasattr(_total_r, "count") else len(_total_r.data or [])
                    if _total == 0:
                        st.warning("⚠️ app_payment_history 테이블에 데이터가 없습니다. 결제 변경/취소 작업이 발생하면 자동으로 기록됩니다.")
                    else:
                        st.info(f"선택한 날짜 범위({start_date} ~ {end_date})에 해당하는 이력이 없습니다. (전체 {_total:,}건 존재)")
        except Exception as e:
            st.error(f"Supabase 조회 오류: {e}")
            st.info("Supabase 연결에 문제가 있습니다. 아래 진단 패널을 확인하세요.")
    else:
        # ── SQLite 조회 (로컬) ──
        conn = get_tenant_conn(db_filename)
        if not conn:
            st.error("매장 DB를 찾을 수 없습니다.")
            return
        try:
            df = pd.read_sql(
                """
                SELECT ph.log_id, ph.sale_id, ph.customer_name,
                       ph.action_type, ph.old_payment_data, ph.new_payment_data,
                       ph.reason, ph.changed_by, ph.changed_at
                FROM PaymentHistory ph
                ORDER BY ph.changed_at DESC
                """,
                conn,
            )
        except Exception:
            df = pd.DataFrame()
        finally:
            conn.close()

    if df.empty:
        return

    df["changed_at_dt"] = pd.to_datetime(df["changed_at"], errors="coerce", utc=True)
    mask = pd.Series(True, index=df.index)

    if search_name:
        mask &= df["customer_name"].fillna("").str.contains(search_name.strip(), case=False)
    if action_filter:
        mask &= df["action_type"].isin(action_filter)
    if user_filter:
        mask &= df["changed_by"].fillna("").str.contains(user_filter.strip(), case=False)

    df_f = df.loc[mask].copy()
    # UTC → KST(+9) 변환 후 표시
    df_f["changed_at"] = (
        df_f["changed_at_dt"]
        .dt.tz_convert("Asia/Seoul")
        .dt.strftime("%Y-%m-%d %H:%M")
        .fillna(df_f["changed_at"].astype(str))
    )
    df_f = df_f.drop(columns=["changed_at_dt"])

    # username → 실명 변환
    _umap = {}
    try:
        _umap = _get_app_user_display_name_map()
    except Exception:
        pass
    df_f["입력자"] = df_f["changed_by"].apply(lambda v: _umap.get(str(v or "").strip()) or _umap.get(str(v or "").strip().lower()) or str(v or "-"))

    st.caption(f"총 {len(df_f):,}건 조회됨 (날짜 범위: {start_date} ~ {end_date})")

    def _highlight_cancel(row):
        if row.get("action_type") == "결제취소":
            return ["background-color: #ffe6e6; color: #b30000;"] * len(row)
        return ["" for _ in row]

    display_cols = [c for c in ["log_id", "changed_at", "customer_name", "action_type", "reason", "입력자", "sale_id"] if c in df_f.columns]
    st.dataframe(df_f[display_cols].style.apply(_highlight_cancel, axis=1), width='stretch')

    # 상세 내역 (old/new payment data) expander
    with st.expander("📋 결제 변경 상세 내역"):
        for _, row in df_f.head(50).iterrows():
            label = f"{row.get('changed_at', '')} | {row.get('customer_name', '-')} | {row.get('action_type', '')}"
            with st.expander(label):
                c_l, c_r = st.columns(2)
                with c_l:
                    st.markdown("**변경 전**")
                    old_data = row.get("old_payment_data") or {}
                    if isinstance(old_data, str):
                        try:
                            old_data = json.loads(old_data)
                        except Exception:
                            pass
                    st.json(old_data)
                with c_r:
                    st.markdown("**변경 후**")
                    new_data = row.get("new_payment_data") or {}
                    if isinstance(new_data, str):
                        try:
                            new_data = json.loads(new_data)
                        except Exception:
                            pass
                    st.json(new_data)
                st.caption(f"사유: {row.get('reason', '-')} | 작업자: {row.get('changed_by', '-')}")


def _create_auth_token(user_info: dict) -> str:
    """유저 정보 + 로그인 시간을 서명된 토큰으로. 브라우저 localStorage/URL 전달용."""
    now = time.time()
    payload = {
        "user_id": user_info.get("id"),
        "username": user_info.get("username"),
        "role": user_info.get("role"),
        "store_id": user_info.get("store_id"),
        "db_filename": user_info.get("db_filename"),
        "logged_at": now,
        "exp": now + AUTH_EXPIRY_DAYS * 24 * 3600,
    }
    payload_b64 = base64.urlsafe_b64encode(json.dumps(payload, sort_keys=True).encode()).decode()
    sig = hmac.new(_get_auth_secret().encode(), payload_b64.encode(), hashlib.sha256).hexdigest()
    return f"{payload_b64}.{sig}"


def _verify_auth_token(token: str) -> dict | None:
    """토큰 검증 + 로그인 후 AUTH_SESSION_SECONDS(=30일) 이내인지 확인. 통과 시 유저 정보 dict, 아니면 None."""
    if not token or "." not in token:
        return None
    try:
        payload_b64, sig = token.rsplit(".", 1)
        expected = hmac.new(_get_auth_secret().encode(), payload_b64.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected, sig):
            return None
        pad = 4 - len(payload_b64) % 4
        if pad != 4:
            payload_b64 += "=" * pad
        raw = base64.urlsafe_b64decode(payload_b64)
        payload = json.loads(raw.decode())
        if payload.get("exp", 0) < time.time():
            return None
        # 로그인한 지 AUTH_SESSION_SECONDS(=30일) 초과 시 세션 만료
        logged_at = payload.get("logged_at", 0)
        if (time.time() - logged_at) > AUTH_SESSION_SECONDS:
            return None
        return {
            "id": payload["user_id"],
            "username": payload["username"],
            "role": payload["role"],
            "store_id": payload.get("store_id"),
            "db_filename": payload.get("db_filename"),
        }
    except Exception:
        return None


def _try_restore_from_query_params():
    """URL의 auth가 있으면 검증(30일 이내) 후 세션 복구. 복구 시 True."""
    try:
        q = st.query_params
    except Exception:
        return False
    auth = q.get("auth")
    if not auth:
        return False
    user = _verify_auth_token(auth)
    if not user:
        return False
    # allowed_stores는 JWT 토큰에 포함되지 않으므로 DB에서 다시 조회
    if user.get("role") != "superadmin":
        try:
            user["allowed_stores"] = get_user_allowed_stores(user["id"])
        except Exception:
            user["allowed_stores"] = []
    else:
        user["allowed_stores"] = []
    user["name"] = _resolve_app_user_display_name(
        user_id=user.get("id"),
        username=user.get("username"),
    )
    st.session_state.logged_in = True
    st.session_state.current_user = user
    st.session_state.current_db = user.get("db_filename") if user.get("role") != "superadmin" else None
    return True


def _handle_channel_talk_magic_link():
    """채널톡 매직링크(?menu=new_sales&phone=01012345678) 진입 시 처리.
    - 매출등록 메뉴 인덱스(2)로 자동 이동
    - 검색창에 전화번호 자동 입력 및 검색 결과 prefill
    - 1회만 처리 (session_state 플래그로 중복 처리 방지)
    """
    if st.session_state.get("_ct_magic_link_handled"):
        return
    try:
        q = st.query_params
    except Exception:
        return
    menu = (q.get("menu") or "").strip()
    phone = (q.get("phone") or "").strip()
    if menu != "new_sales" or not phone:
        return

    st.session_state["_ct_magic_link_handled"] = True
    st.session_state["main_tab_idx"] = 2
    st.session_state["new_sales_cust_search"] = phone

    try:
        sc, _err = get_supabase_client()
        db_filename = st.session_state.get("current_db") or (
            (st.session_state.get("current_user") or {}).get("db_filename")
        )
        store_name = _get_current_store_name_for_customers(db_filename) if db_filename else None
        if sc and store_name:
            q_safe = re.sub(r"[*,]", "", phone.strip())
            if q_safe:
                or_filter = f"phone1.ilike.*{q_safe}*,phone2.ilike.*{q_safe}*"
                r = (
                    sc.table("app_customers")
                    .select("id, name, phone1, phone2, address")
                    .eq("store_name", store_name)
                    .or_(or_filter)
                    .order("id", desc=True)
                    .limit(50)
                    .execute()
                )
                st.session_state["_cust_search_results"] = r.data or []
            else:
                st.session_state["_cust_search_results"] = []
    except Exception:
        st.session_state["_cust_search_results"] = []


def _inject_js_url_auth_save_and_replace_state():
    """[비활성] components.html iframe sandbox 제약으로 부모 navigation/URL 변경이 차단되므로,
    URL에서 ?auth= 를 제거하지 않고 그대로 유지한다. F5 시 URL의 ?auth= 로 자동 복구."""
    return


def _inject_js_localStorage_redirect_with_auth():
    """[비활성] components.html iframe sandbox 제약으로 부모 navigation이 SecurityError로 차단됨.
    토큰 자동 복구는 URL ?auth= 파라미터 유지 방식으로 처리한다."""
    return


def _inject_js_clear_auth_on_logout():
    """유일한 삭제 경로 1: 유저가 로그아웃 버튼을 클릭했을 때만 호출됨.
    components.html(iframe) 안에서 window.parent로 부모 접근."""
    components.html(
        """
        <script>
        (function(){
            try {
                var w = window.parent;
                w.localStorage.removeItem("emons_auth");
                w.sessionStorage.removeItem("emons_auth");
                console.log("[momo-auth] 토큰 삭제됨: 원인=로그아웃 버튼 클릭");
                var u = new URL(w.location.href);
                u.searchParams.delete("logout");
                u.searchParams.delete("auth");
                w.history.replaceState({}, "", u.toString());
            } catch(e) { console.warn("[momo-auth] logout 실패:", e); }
        })();
        </script>
        """,
        height=0,
    )


def _inject_js_save_token(token: str):
    """로그인 성공 직후: 발급된 토큰을 부모 윈도우의 localStorage/sessionStorage에 저장.
    components.html(iframe) 안에서 window.parent로 부모 접근. 즉시 + 500ms 후 재시도로 안정성 강화."""
    if not token:
        return
    safe = json.dumps(str(token))
    components.html(
        f"""
        <script>
        (function(){{
            var token = {safe};
            function _saveToken() {{
                try {{
                    var w = window.parent;
                    w.localStorage.setItem("emons_auth", token);
                    w.sessionStorage.setItem("emons_auth", token);
                    console.log("[momo-auth] 토큰 저장됨 (로그인 성공), 길이:", token.length);
                }} catch(e) {{ console.warn("[momo-auth] 토큰 저장 실패:", e); }}
            }}
            _saveToken();
            setTimeout(_saveToken, 500);
        }})();
        </script>
        """,
        height=0,
    )


def _inject_js_clear_auth_and_remove_auth_param():
    """유일한 삭제 경로 2: 30일 만료 또는 서명 무효일 때만 호출됨.
    components.html(iframe) 안에서 window.parent로 부모 접근."""
    components.html(
        """
        <script>
        (function(){
            try {
                var w = window.parent;
                w.localStorage.removeItem("emons_auth");
                w.sessionStorage.removeItem("emons_auth");
                console.log("[momo-auth] 토큰 삭제됨: 원인=30일 만료 또는 토큰 무효");
                var u = new URL(w.location.href);
                u.searchParams.delete("auth");
                w.history.replaceState({}, "", u.toString());
            } catch(e) { console.warn("[momo-auth] clear 실패:", e); }
        })();
        </script>
        """,
        height=0,
    )


def _maybe_clear_localStorage_on_logout():
    """URL에 logout=1이 있으면 localStorage 정리 스크립트 주입."""
    try:
        if st.query_params.get("logout") == "1":
            _inject_js_clear_auth_on_logout()
    except Exception:
        pass


# ========== 주소 검색 API 연동 (한국 주소) ==========
# 공공데이터 도로명주소 API / Vworld / 카카오 중 API 키 설정 시 사용 가능.
# KAKAO_REST_KEY: st.secrets["KAKAO_REST_KEY"] 또는 환경변수로 설정. 코드 내 하드코딩 금지.


def _get_kakao_rest_key() -> str:
    """카카오 REST API 키를 st.secrets → os.environ 순으로 조회. 없으면 빈 문자열 반환."""
    try:
        val = st.secrets.get("KAKAO_REST_KEY") or ""
        if val and str(val).strip():
            return str(val).strip()
    except Exception:
        pass
    return os.environ.get("KAKAO_REST_KEY", "")

def search_address_public(keyword: str, api_key: str = ""):
    """
    공공데이터포털 도로명주소 API (건축물대장 주소 조회 또는 도로명주소 API).
    API 키는 환경변수 ADDRESS_API_KEY 또는 인자로 전달.
    반환: [{"road_addr", "jibun_addr", "zip_code"}, ...]
    """
    if not keyword or not keyword.strip():
        return []
    key = api_key or os.environ.get("ADDRESS_API_KEY", "")
    if not key:
        return []
    url = "https://www.juso.go.kr/addrlink/addrLinkApi.do"
    params = {
        "confmKey": key,
        "currentPage": "1",
        "countPerPage": "10",
        "keyword": keyword,
        "resultType": "json",
    }
    try:
        r = requests.get(url, params=params, timeout=5)
        data = r.json()
        if data.get("results") and data["results"].get("juso"):
            juso_list = data["results"]["juso"]
            return [
                {
                    "road_addr": j.get("roadAddr", ""),
                    "jibun_addr": j.get("jibunAddr", ""),
                    "zip_code": j.get("zipNo", ""),
                }
                for j in juso_list
            ]
    except Exception:
        pass
    return []


def _kakao_local_error_hint(raw_msg: str) -> str:
    """로컬 API 비활성화 등 카카오 콘솔 설정 오류 시 안내 문구 추가."""
    if not raw_msg:
        return raw_msg
    raw_lower = raw_msg.lower()
    if "open_map_and_local" in raw_lower or ("disabled" in raw_lower and "service" in raw_lower):
        return (
            "카카오 앱에서 [지도/로컬] 서비스가 꺼져 있습니다. "
            "developers.kakao.com → 내 애플리케이션 → 해당 앱 → [앱 설정] → [앱 키] 아래 또는 [제품 설정]에서 "
            "[카카오맵] 또는 [로컬 API] 사용 설정을 [ON]으로 바꿔 주세요."
        )
    return raw_msg


def search_address_kakao(keyword: str, api_key: str = ""):
    """
    카카오 로컬 API - 주소 검색.
    GET https://dapi.kakao.com/v2/local/search/address.json
    헤더: Authorization: KakaoAK {KAKAO_REST_KEY}
    반환: ( [{"address_name": "서울 강남구 ..."}, ...], None ) 또는 ( [], "오류메시지" )
    """
    if not keyword or not keyword.strip():
        return [], None
    key = api_key or _get_kakao_rest_key()
    if not key:
        return [], "KAKAO_REST_KEY가 설정되지 않았습니다. st.secrets 또는 환경변수에 KAKAO_REST_KEY를 추가해 주세요."
    url = "https://dapi.kakao.com/v2/local/search/address.json"
    headers = {"Authorization": f"KakaoAK {key}"}
    params = {"query": keyword.strip()}
    try:
        r = requests.get(url, headers=headers, params=params, timeout=10)
        try:
            data = r.json() if r.content else {}
        except Exception:
            data = {}
        # API 오류 응답 (401, 403 등): 카카오는 code, msg 등 반환
        if r.status_code != 200:
            err_msg = data.get("msg") or data.get("message") or f"API 오류 (HTTP {r.status_code})"
            return [], _kakao_local_error_hint(err_msg)
        if data.get("errorType") or data.get("error"):
            raw = data.get("message") or data.get("msg") or "API 오류"
            return [], _kakao_local_error_hint(raw)
        docs = data.get("documents", [])
        # address_name(전체 주소), road_address.building_name(건물명), address.bname(법정동명) 수집
        result = []
        for d in docs[:15]:
            addr = d.get("address_name")
            if not addr or not isinstance(addr, str):
                continue
            road = d.get("road_address") or {}
            addr_obj = d.get("address") or {}
            building_name = (road.get("building_name") or "").strip() or None
            bname = (addr_obj.get("bname") or "").strip() or None
            result.append({
                "address_name": addr,
                "building_name": building_name,
                "bname": bname,
            })
        return result, None
    except requests.exceptions.RequestException as e:
        return [], f"연결 오류: {str(e)[:80]}"
    except Exception as e:
        return [], f"오류: {str(e)[:80]}"


def search_keyword_kakao(keyword: str, api_key: str = ""):
    """
    카카오 로컬 API - 키워드 검색(장소/건물명).
    GET https://dapi.kakao.com/v2/local/search/keyword.json
    반환: ( [{"place_name", "address_name", "road_address_name", "x", "y", "source": "keyword"}, ...], None ) 또는 ( [], "오류메시지" )
    """
    if not keyword or not str(keyword).strip():
        return [], None
    key = api_key or _get_kakao_rest_key()
    if not key:
        return [], "KAKAO_REST_KEY가 설정되지 않았습니다. st.secrets 또는 환경변수에 KAKAO_REST_KEY를 추가해 주세요."
    url = "https://dapi.kakao.com/v2/local/search/keyword.json"
    headers = {"Authorization": f"KakaoAK {key}"}
    params = {"query": keyword.strip(), "size": 15}
    try:
        r = requests.get(url, headers=headers, params=params, timeout=10)
        try:
            data = r.json() if r.content else {}
        except Exception:
            data = {}
        if r.status_code != 200:
            err_msg = data.get("msg") or data.get("message") or f"API 오류 (HTTP {r.status_code})"
            return [], _kakao_local_error_hint(err_msg)
        if data.get("errorType") or data.get("error"):
            raw = data.get("message") or data.get("msg") or "API 오류"
            return [], _kakao_local_error_hint(raw)
        docs = data.get("documents", [])
        result = []
        for d in docs:
            addr = (d.get("address_name") or d.get("road_address_name") or "").strip()
            place = (d.get("place_name") or "").strip()
            if not addr and not place:
                continue
            x, y = d.get("x"), d.get("y")
            result.append({
                "place_name": place or None,
                "address_name": addr or place,
                "road_address_name": (d.get("road_address_name") or "").strip() or None,
                "x": x,
                "y": y,
                "source": "keyword",
            })
        return result, None
    except requests.exceptions.RequestException as e:
        return [], f"연결 오류: {str(e)[:80]}"
    except Exception as e:
        return [], f"오류: {str(e)[:80]}"


def geocode_address_kakao(address: str):
    """주소 문자열을 카카오 API로 지오코딩하여 (lat, lon) 반환. 실패 시 None."""
    ext = geocode_address_kakao_extended(address)
    return (ext["latitude"], ext["longitude"]) if ext else None


def geocode_address_kakao_extended(address: str) -> dict | None:
    """
    주소 문자열을 카카오 API로 지오코딩하여 좌표 + 지역(시군구/법정동/도로명) + 건물명 반환.
    반환: {
        "latitude", "longitude", "address",
        "sigungu",        # region_2depth_name (예: 남구)
        "bname",          # 법정동명 (예: 삼산동)
        "road_name",      # 도로명 (예: 봉월로)
        "building_name",  # 건물명 (예: 태화강엑슬루타워)
    } 또는 None.
    """
    if not address or not str(address).strip():
        return None
    q = str(address).strip()
    key = _get_kakao_rest_key()
    if not key:
        return None
    url = "https://dapi.kakao.com/v2/local/search/address.json"
    headers = {"Authorization": f"KakaoAK {key}"}
    params = {"query": q}
    try:
        r = requests.get(url, headers=headers, params=params, timeout=5)
        if r.status_code != 200:
            return None
        data = r.json() if r.content else {}
        docs = data.get("documents", [])
        if not docs:
            return None
        d = docs[0]
        x, y = d.get("x"), d.get("y")
        if x is None or y is None:
            return None
        road = d.get("road_address") or {}
        addr_obj = d.get("address") or {}
        # 시군구: 도로명 주소 우선, 없으면 지번 주소
        sigungu = (
            (road.get("region_2depth_name") or addr_obj.get("region_2depth_name") or "").strip()
            or None
        )
        bname = (addr_obj.get("bname") or "").strip() or None
        road_name = (road.get("road_name") or "").strip() or None
        building_name = (road.get("building_name") or "").strip() or None
        addr_name = (d.get("address_name") or q) or ""
        return {
            "latitude": float(y),
            "longitude": float(x),
            "address": addr_name,
            "sigungu": sigungu,
            "bname": bname,
            "road_name": road_name,
            "building_name": building_name,
        }
    except Exception:
        return None


def address_search(keyword: str):
    """
    주소 검색 통합: 환경변수에 따라 공공데이터 또는 카카오 시도.
    API 키가 없으면 빈 리스트 반환 후 수동 입력 유도.
    """
    results = search_address_public(keyword)
    if results:
        return results
    results, _ = search_address_kakao(keyword)
    return results


def _address_search_dialog_impl():
    """주소 검색 모달 본문. 검색 후 선택 시 address_manual에 반영하고 닫힘. st.form으로 엔터키 검색 지원."""
    with st.form("address_search_form", clear_on_submit=False):
        kw = st.text_input("주소 검색어", placeholder="예: 역삼동 123, 테헤란로")
        submitted = st.form_submit_button("검색")
    if submitted:
        if kw and kw.strip():
            results_addr, err_addr = search_address_kakao(kw.strip())
            results_kw, err_kw = search_keyword_kakao(kw.strip())
            combined = []
            seen = set()
            for r in (results_addr or []):
                addr = r.get("address_name") or ""
                if addr and addr not in seen:
                    seen.add(addr)
                    r["source"] = "address"
                    combined.append(r)
            for r in (results_kw or []):
                addr = r.get("address_name") or ""
                if addr and addr not in seen:
                    seen.add(addr)
                    combined.append(r)
            st.session_state._dialog_addr_results = combined
            st.session_state._dialog_addr_error = err_addr if not combined and err_addr else None
        else:
            st.warning("검색어를 입력하세요.")
    if st.session_state.get("_dialog_addr_error"):
        st.error(st.session_state._dialog_addr_error)
    results = st.session_state.get("_dialog_addr_results") or []
    if results:
        options = []
        display_to_address = {}
        for r in results:
            addr = r.get("address_name") or ""
            if r.get("source") == "keyword":
                place = (r.get("place_name") or "").strip()
                disp = f"장소: {place} — {addr}" if place else addr
            else:
                building_name = (r.get("building_name") or "").strip()
                bname = (r.get("bname") or "").strip()
                disp = f"[{building_name}] {addr}" if building_name else (f"[{bname}] {addr}" if bname else addr)
            options.append(disp)
            display_to_address[disp] = addr
        chosen = st.selectbox("검색 결과에서 주소 선택", options, key="dialog_addr_select")
        if st.button("선택 완료", key="dialog_addr_confirm"):
            if chosen:
                st.session_state["address_manual"] = display_to_address.get(chosen, chosen)
            for k in ("_dialog_addr_results", "_dialog_addr_error", "_show_address_dialog"):
                st.session_state.pop(k, None)
            st.rerun()


# st.dialog 데코레이터 (Streamlit 1.33+). 없으면 expander 폴백
if hasattr(st, "dialog"):

    @st.dialog("주소 검색", width="medium")
    def _address_search_dialog():
        _address_search_dialog_impl()
else:

    def _address_search_dialog():
        with st.expander("📍 주소 검색", expanded=True):
            _address_search_dialog_impl()


def _open_dialog(title: str, render_fn, *, width: str = "large",
                 fallback_expander: bool = True, on_dismiss=None) -> None:
    """공통 팝업(모달) 헬퍼 (app.py 내부 호환용 얇은 래퍼).

    구현은 `ui_dialogs.open_dialog` 에 있음. 순환 import 방지를 위해
    실제 로직은 별도 모듈로 분리해 두었다.
    """
    from ui_dialogs import open_dialog as _od  # noqa: WPS433
    _od(title, render_fn, width=width, fallback_expander=fallback_expander,
        on_dismiss=on_dismiss)


# ========== 로그인 페이지 ==========

def _inject_js_login_form_attributes():
    """로그인 폼 input에 id, name, autocomplete 부여. 빈 autocomplete는 'off'로 수정 (유효하지 않은 빈 값 경고 해소)."""
    st.markdown(
        """
        <script>
        (function(){
            function fixAutocomplete() {
                var form = document.querySelector('form[data-testid="stForm"]') || document.querySelector('form');
                if (form) {
                    var inputs = form.querySelectorAll('input:not([type="hidden"])');
                    if (inputs.length >= 2 && !inputs[0].getAttribute('name')) {
                        inputs[0].setAttribute('id', 'emons-username');
                        inputs[0].setAttribute('name', 'username');
                        inputs[0].setAttribute('autocomplete', 'username');
                        inputs[1].setAttribute('id', 'emons-password');
                        inputs[1].setAttribute('name', 'password');
                        inputs[1].setAttribute('autocomplete', 'current-password');
                    }
                }
                document.querySelectorAll('input:not([type="hidden"])').forEach(function(inp) {
                    var ac = inp.getAttribute('autocomplete');
                    if (ac === '' || ac === null) inp.setAttribute('autocomplete', 'off');
                });
            }
            function run() { fixAutocomplete(); setTimeout(fixAutocomplete, 150); }
            if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
            else run();
        })();
        </script>
        """,
        unsafe_allow_html=True,
    )


def render_login():
    ensure_session()
    # 이메일 자동 입력: URL의 email 파라미터 또는 localStorage(아래 스크립트에서 리다이렉트)로 복원
    try:
        default_email = (st.query_params.get("email") or "").strip()
    except Exception:
        default_email = ""
    # 로그인 화면 로고 전용 CSS: @media로 모바일/PC 구분
    st.markdown(
        """
        <style>
        /* 로그인 화면 emons 로고: PC — 적당한 크기로 제한 */
        .emons-login-logo img {
            max-width: 350px !important;
            width: auto !important;
            height: auto !important;
            object-fit: contain;
        }
        @media (max-width: 768px) {
            /* 모바일: 상단 여백으로 잘림 방지, 화면 너비의 60% 크기 */
            .emons-login-logo {
                margin-top: 1.5rem;
                padding-top: 1rem;
                box-sizing: border-box;
            }
            .emons-login-logo img {
                width: 60% !important;
                max-width: 60% !important;
                height: auto !important;
            }
        }
        </style>
        """,
        unsafe_allow_html=True,
    )
    # 로고: 로그인 화면에서도 좌측 상단 고정 (공통 레이아웃), 에러 시 빨간 메시지
    logo_html = (
        '<div class="emons-login-logo">'
        + _common_logo_html(_resolve_logo_path(), fallback_id="emons-logo-fallback-login")
        + "</div>"
    )
    st.markdown(logo_html, unsafe_allow_html=True)
    st.title("momo")
    st.subheader("로그인")
    with st.form("login_form"):
        email = st.text_input("이메일", value=default_email, key="login_email", type="default", placeholder="예: you@example.com")
        password = st.text_input("비밀번호", type="password", key="login_password")
        submitted = st.form_submit_button("로그인")
        if submitted:
            if not (email and str(email).strip()):
                st.error("이메일을 입력해 주세요.")
            elif not password:
                st.error("비밀번호를 입력해 주세요.")
            elif len(password) < 6:
                st.error("비밀번호는 6자 이상이어야 합니다.")
            else:
                client, err = get_supabase_client()
                if err:
                    st.error(f"⚠️ {err}")
                else:
                    try:
                        response = client.auth.sign_in_with_password({
                            "email": str(email).strip(),
                            "password": password,
                        })
                        session = response.session
                        user = response.user
                        if not session or not user:
                            st.error("이메일 또는 비밀번호가 올바르지 않습니다.")
                        else:
                            app_user = get_app_user_by_email(user.email)
                            if not app_user:
                                _diag = st.session_state.pop("_login_diag_error", None)
                                if _diag:
                                    st.error(
                                        "사용자 조회 중 오류가 발생했습니다. 관리자에게 문의하세요.\n\n"
                                        f"진단 정보: {_diag}"
                                    )
                                else:
                                    st.error("이 이메일은 등록된 사용자가 아닙니다. 관리자에게 문의하세요.")
                            else:
                                user_id, uname, role, store_id, db_filename = app_user
                                allowed_stores = get_user_allowed_stores(user_id) if role != "superadmin" else []
                                if allowed_stores:
                                    # 기본 매장(app_users.store_id)이 allowed_stores에 있으면 우선 적용
                                    _matched_store = next((s for s in allowed_stores if s[0] == store_id), None)
                                    if _matched_store:
                                        store_id, db_filename = _matched_store[0], _matched_store[1]
                                    else:
                                        # 기본 매장이 없거나 배정 목록과 불일치하면 첫 매장으로 fallback
                                        store_id, db_filename = allowed_stores[0][0], allowed_stores[0][1]
                                display_name = _resolve_app_user_display_name(
                                    user_id=user_id,
                                    username=uname,
                                    email=str(email).strip(),
                                )
                                st.session_state.logged_in = True
                                st.session_state.current_user = {
                                    "id": user_id, "username": uname, "name": display_name or None, "role": role,
                                    "store_id": store_id, "db_filename": db_filename,
                                    "allowed_stores": allowed_stores,
                                }
                                st.session_state.current_db = db_filename if role != "superadmin" else None
                                st.session_state["supabase_session"] = {
                                    "access_token": session.access_token,
                                    "refresh_token": session.refresh_token,
                                }
                                # 성공 시 다음 접속을 위해 이메일을 브라우저에 저장할 예정(메인 로드 시 스크립트로 저장)
                                st.session_state["_pending_save_login_email"] = str(email).strip()
                                # 자동 로그인 유지용 토큰 생성 (30일).
                                # 핵심: Streamlit components.html iframe의 sandbox 제약으로 JS 기반 navigation이 차단되므로,
                                # localStorage 의존을 포기하고 URL ?auth= 파라미터에 토큰을 직접 유지하여
                                # F5 새로고침 시 URL이 살아남는 것을 이용해 자동 복구한다.
                                _auth_token = _create_auth_token({
                                    "id": user_id,
                                    "username": uname,
                                    "role": role,
                                    "store_id": store_id,
                                    "db_filename": db_filename,
                                })
                                st.session_state["_pending_auth_token"] = _auth_token
                                try:
                                    st.query_params["auth"] = _auth_token
                                except Exception:
                                    pass
                                st.rerun()
                    except Exception as e:
                        # 디버깅용: 어디에서 오류가 나는지 터미널에 전체 스택을 출력
                        traceback.print_exc()
                        err_msg = str(e).strip() or "로그인에 실패했습니다."
                        if "Invalid login" in err_msg or "invalid" in err_msg.lower():
                            st.error("이메일 또는 비밀번호가 올바르지 않습니다.")
                        else:
                            st.error(f"로그인 중 오류가 발생했습니다: {err_msg}")

    st.caption("💡 로그인할 때 사용한 이메일은 이 기기(브라우저)에만 저장되며, 다음 로그인 시 자동으로 채워집니다.")
    st.caption("🔒 한 번 로그인하면 이 브라우저에서 **30일간 자동 로그인**이 유지됩니다 (회사 PC 전용).")

    # 자동 로그인 + 이메일 자동 입력: localStorage 활용
    # 우선순위:
    #   1) localStorage에 emons_auth 토큰이 있고 URL에 ?auth= 없으면 → URL에 토큰 추가 후 redirect (자동 로그인)
    #      (채널톡 매직링크 등 외부 진입 시에도 자동 로그인 보장)
    #   2) URL에 ?auth=가 이미 있으면 → 백엔드가 검증/복구 처리 중이므로 양보
    #   3) localStorage에 이메일이 있고 URL에 ?email= 없으면 → 이메일 prefill 위해 redirect
    components.html(
        """
        <script>
        (function(){
            var EMAIL_KEY = 'emons_login_email';
            var AUTH_KEY = 'emons_auth';
            try {
                var w = window.parent;
                var u = new URL(w.location.href);

                // 로그아웃 직후: 저장된 토큰으로 재로그인하지 않고 삭제만 한다.
                if (u.searchParams.get('logout') === '1') {
                    w.localStorage.removeItem(AUTH_KEY);
                    w.sessionStorage.removeItem(AUTH_KEY);
                    u.searchParams.delete('logout');
                    u.searchParams.delete('auth');
                    w.history.replaceState({}, '', u.toString());
                    console.log('[momo-auth] 토큰 삭제됨: 원인=로그아웃 (로그인화면)');
                    return;
                }

                // 1) 자동 로그인 토큰 복구: localStorage 토큰 → URL ?auth=
                if (!u.searchParams.get('auth')) {
                    var stored_auth = w.localStorage.getItem(AUTH_KEY) || w.sessionStorage.getItem(AUTH_KEY);
                    if (stored_auth) {
                        u.searchParams.set('auth', stored_auth);
                        w.location.replace(u.toString());
                        return;
                    }
                } else {
                    // 이미 처리 중이므로 양보
                    return;
                }

                // 2) 이메일 자동 입력
                if (!u.searchParams.get('email') && w.localStorage.getItem(EMAIL_KEY)) {
                    u.searchParams.set('email', w.localStorage.getItem(EMAIL_KEY));
                    w.location.replace(u.toString());
                    return;
                }
            } catch(e) {}
        })();
        </script>
        """,
        height=0,
    )
    # 로그인 폼 input에 autocomplete 등 속성 최적화 (브라우저 자동 완성 동작)
    _inject_js_login_form_attributes()


# ========== 최고 관리자 (Superadmin) 전용: 공지 조회 ==========

def get_store_display_name(user):
    """로그인 사용자에 따른 사이드바용 매장명. superadmin이면 본사, 아니면 Supabase app_stores에서 조회."""
    if user.get("role") == "superadmin":
        return "🏢 에몬스울산본점"
    store_id = user.get("store_id")
    if not store_id:
        return "🏢 매장"
    client, err = get_supabase_client()
    if err or not client:
        return "🏢 매장"
    try:
        r = client.table("app_stores").select("store_name").eq("id", int(store_id)).maybe_single().execute()
        data = r.data if isinstance(r.data, dict) else (r.data[0] if r.data and len(r.data) else None)
        return f"🏢 {data['store_name']}" if data and data.get("store_name") else "🏢 매장"
    except Exception:
        return "🏢 매장"


def get_latest_active_notice():
    """Notices 테이블에서 is_active=1인 최신 공지 1건 메시지 반환. 없으면 None. (레거시 호환)"""
    conn = get_master_conn()
    try:
        row = conn.execute(
            "SELECT content, message FROM Notices WHERE is_active = 1 ORDER BY created_at DESC LIMIT 1"
        ).fetchone()
        if not row:
            return None
        return (row[0] or row[1] or "").strip() or None
    finally:
        conn.close()


def get_recent_notices(limit: int = 5, viewer_store_ids=None):
    """최근 공지사항 limit건 반환. (id, title, content, external_link, message, created_at).
    1순위 Supabase app_notices (클라우드·로컬 공통 영구 저장). 실패·미생성 시 로컬 SQLite Notices fallback.
    viewer_store_ids: 조회자가 속한 매장 id 목록. None이면 전체 공지 반환(superadmin 등),
    지정 시 '전체매장 공지(store_ids IS NULL)' + '해당 매장 대상 공지'만 반환."""
    # 1) Supabase 우선 조회
    try:
        client, err = get_supabase_client()
        if client and not err:
            def _query(with_store_filter: bool):
                q = (
                    client.table("app_notices")
                    .select("id, title, content, external_link, message, created_at, store_ids")
                    .eq("is_active", True)
                )
                if with_store_filter and viewer_store_ids:
                    _ors = ["store_ids.is.null"] + [f"store_ids.cs.{{{int(sid)}}}" for sid in viewer_store_ids]
                    q = q.or_(",".join(_ors))
                return q.order("created_at", desc=True).limit(int(limit)).execute()
            try:
                r = _query(True)
            except Exception as e:
                if "store_ids" in str(e) or "schema cache" in str(e):
                    # store_ids 컬럼 미생성(마이그레이션 전) — 필터 없이 하위호환 조회
                    r = client.table("app_notices").select(
                        "id, title, content, external_link, message, created_at"
                    ).eq("is_active", True).order("created_at", desc=True).limit(int(limit)).execute()
                else:
                    raise
            rows = r.data or []
            if rows:
                return pd.DataFrame(rows)
            # Supabase 연결은 됐으나 공지 0건 → fallback 시도하지 않고 빈 DF 반환
            return pd.DataFrame(columns=["id", "title", "content", "external_link", "message", "created_at", "store_ids"])
    except Exception:
        # app_notices 테이블 미생성 등: 로컬 fallback
        pass

    # 2) 로컬 SQLite fallback (개발 환경 또는 테이블 미생성 시)
    conn = get_master_conn()
    try:
        df = pd.read_sql(
            """
            SELECT id, title, content, external_link, message, created_at
            FROM Notices
            WHERE is_active = 1
            ORDER BY created_at DESC
            LIMIT ?
            """,
            conn,
            params=(limit,),
        )
        return df
    except Exception:
        return pd.DataFrame()
    finally:
        conn.close()


def _render_recent_notices_section():
    """공지사항 섹션: 최근 3~5건을 expander로 표시, 외부 링크는 새 창에서 열기.
    superadmin은 전체 공지, 그 외에는 전체매장 공지 + 본인 소속 매장 대상 공지만 표시."""
    current_user = st.session_state.get("current_user") or {}
    role = (current_user.get("role") or "user").strip()
    if role == "superadmin":
        viewer_store_ids = None
    else:
        allowed = current_user.get("allowed_stores") or []
        ids = {s[0] for s in allowed}
        if not ids and current_user.get("store_id"):
            ids = {current_user["store_id"]}
        viewer_store_ids = ids or None
    notices = get_recent_notices(5, viewer_store_ids=viewer_store_ids)
    if len(notices) == 0:
        return
    st.subheader("📌 최근 공지사항")
    for _, row in notices.iterrows():
        title = (row.get("title") or "").strip() or "(제목 없음)"
        content = (row.get("content") or row.get("message") or "").strip()
        external_link = (row.get("external_link") or "").strip()
        created = (row.get("created_at") or "")[:10]
        label = f"{title} ({created})"
        with st.expander(label):
            if content:
                st.write(content)
            if external_link:
                st.markdown(
                    f'<a href="{html.escape(external_link)}" target="_blank" rel="noopener noreferrer" '
                    'style="display:inline-block;padding:0.4rem 0.8rem;margin-top:0.5rem;'
                    'background:#1f77b4;color:white;border-radius:0.4rem;text-decoration:none;'
                    'font-weight:500;">🔗 링크 열기 (새 창)</a>',
                    unsafe_allow_html=True,
                )


# ========== 마케팅 인사이트 (Plotly 4종 차트) ==========

def extract_region(address):
    """
    도로명 주소 환경에 맞춘 지역명 추출 (3단계 Fallback).
    1순위: 주소 끝 괄호 안의 '동/읍/면' (예: "... (삼산동)" -> "삼산동")
    2순위: 주요 도로명 '로/길' (예: "... 삼산로 123" -> "삼산로")
    3순위: '구/군' (예: "... 남구 ..." -> "남구")
    """
    if not isinstance(address, str):
        return "기타"
    s = address.strip()
    if not s:
        return "기타"
    # 1순위: 괄호 안의 동/읍/면
    match1 = re.search(r"\(([가-힣]+[동읍면])\)", s)
    if match1:
        return match1.group(1)
    # 2순위: 로/길
    match2 = re.search(r"([가-힣]+[로길])\b", s)
    if match2:
        return match2.group(1)
    # 3순위: 구/군
    match3 = re.search(r"([가-힣]+[구군])\b", s)
    if match3:
        return match3.group(1)
    return "기타 지역"


def _render_marketing_insights_charts(orders: pd.DataFrame, customers: pd.DataFrame, period_label: str = None):
    """orders + customers 로 4종 Plotly 차트 2x2 배치. period_label 있으면 차트 상단에 표시."""
    if orders is None or len(orders) == 0:
        st.info("데이터가 충분하지 않습니다.")
        return
    merged = orders.merge(customers[["id", "address"]], left_on="customer_id", right_on="id", how="left")
    merged["region"] = merged["address"].map(extract_region)
    merged["total_amount"] = merged["total_amount"].fillna(0).astype(float)

    if period_label:
        st.caption(f"📅 {period_label}")
    st.subheader("🎯 데이터 기반 마케팅 분석")
    c1, c2 = st.columns(2)

    with c1:
        region_sales = merged.groupby("region", as_index=False)["total_amount"].sum()
        region_sales = region_sales[region_sales["total_amount"] > 0]
        if len(region_sales) == 0:
            st.info("데이터가 충분하지 않습니다.")
        else:
            region_sales["text"] = region_sales["total_amount"].apply(lambda x: f"{x:,.0f}원")
            fig1 = px.pie(region_sales, values="total_amount", names="region", title="① 지역별 매출 분포 (Pie Chart)")
            fig1.update_traces(textposition="inside", textinfo="percent+label", hovertemplate="%{label}<br>매출: %{value:,.0f}원<br>비중: %{percent}<extra></extra>")
            fig1.update_layout(margin=dict(t=40, b=20, l=20, r=20), height=320)
            st.plotly_chart(fig1, width='stretch')

    _VISIT_REASON_NORMALIZE = {
        "매장외관": "매장외관(지나가다)",
        "재구매": "기존고객(재구매 AS)",
        "소개": "지인/업체소개",
        "광고(SNS 외)": "광고 및 홍보",
    }
    _PURCHASE_REASON_NORMALIZE = {
        "교체(이사없이)": "단순 교체/추가",
        "이사": "일반 이사",
        "공동구매(입주, 가구쇼 등)": "신규 입주",
        "현대임직원할인": "기타(사무용 등)",
    }

    with c2:
        _visit_col = merged["visit_reason"].fillna("미기입").replace(_VISIT_REASON_NORMALIZE)
        visit_counts = _visit_col.value_counts().reset_index()
        visit_counts.columns = ["visit_reason", "count"]
        if len(visit_counts) == 0 or visit_counts["count"].sum() == 0:
            st.info("데이터가 충분하지 않습니다.")
        else:
            visit_counts["text"] = visit_counts["count"].apply(lambda x: f"{x:,}건")
            fig2 = go.Figure(data=[go.Pie(labels=visit_counts["visit_reason"], values=visit_counts["count"], hole=0.5, textinfo="percent+label")])
            fig2.update_traces(hovertemplate="%{label}<br>건수: %{value:,}건<extra></extra>")
            fig2.update_layout(title="② 방문 경로 분석", margin=dict(t=40, b=20, l=20, r=20), height=320, showlegend=True)
            st.plotly_chart(fig2, width='stretch')

    with c1:
        _merged_pr = merged.copy()
        _merged_pr["purchase_reason"] = _merged_pr["purchase_reason"].replace(_PURCHASE_REASON_NORMALIZE)
        purchase_sales = _merged_pr.groupby("purchase_reason", as_index=False)["total_amount"].sum()
        purchase_sales = purchase_sales[purchase_sales["purchase_reason"].notna() & (purchase_sales["purchase_reason"] != "")]
        if len(purchase_sales) == 0:
            st.info("데이터가 충분하지 않습니다.")
        else:
            purchase_sales = purchase_sales.sort_values("total_amount", ascending=True)
            purchase_sales["amt_str"] = purchase_sales["total_amount"].apply(lambda x: f"{x:,.0f}원")
            fig3 = px.bar(purchase_sales, x="total_amount", y="purchase_reason", orientation="h", title="③ 구매 이유별 총 판매 금액")
            fig3.update_traces(hovertemplate="%{y}<br>총액: %{x:,.0f}원<extra></extra>")
            fig3.update_layout(margin=dict(t=40, b=20, l=20, r=20), height=320, xaxis_title="총 판매 금액(원)", yaxis_title="")
            st.plotly_chart(fig3, width='stretch')

    with c2:
        cats = merged["category"].fillna("").str.split(",").explode()
        cats = cats.str.strip()
        cats = cats[cats != ""]
        cat_counts = cats.value_counts().reset_index()
        cat_counts.columns = ["category", "count"]
        if len(cat_counts) == 0:
            st.info("데이터가 충분하지 않습니다.")
        else:
            cat_counts = cat_counts.sort_values("count", ascending=True)
            fig4 = px.bar(cat_counts, x="count", y="category", orientation="h", title="④ 카테고리별 인기 품목(판매 횟수)")
            fig4.update_traces(hovertemplate="%{y}<br>판매 횟수: %{x:,}건<extra></extra>")
            fig4.update_layout(margin=dict(t=40, b=20, l=20, r=20), height=320, xaxis_title="판매 횟수", yaxis_title="")
            st.plotly_chart(fig4, width='stretch')


# 지도 기본 중심/줌 (한국)
_MAP_CENTER = (36.5, 127.5)
_MAP_ZOOM = 7


def _build_map_data_with_geocoding(merged: pd.DataFrame) -> pd.DataFrame:
    """merged(orders+customers)에서 주소 지오코딩 후 latitude, longitude, address, building_name, 고객명, 품목, 금액, 배송일자 포함 DataFrame 반환.
    app_customers에 latitude, longitude가 있으면 우선 사용(지오코딩 스킵).
    카카오 API로 신규 지오코딩 시 app_customers.latitude/longitude에 영속 저장 (세션 재시작 후에도 재호출 없음).
    merged에 _db_fn 또는 _store 컬럼이 있어야 영속 저장이 활성화됨."""
    def _safe_strip_text(v) -> str:
        try:
            if v is None or pd.isna(v):
                return ""
        except Exception:
            if v is None:
                return ""
        return str(v).strip()

    if "address" not in merged.columns or "name" not in merged.columns:
        return pd.DataFrame()
    if "geo_cache" not in st.session_state:
        st.session_state.geo_cache = {}
    cache = st.session_state.geo_cache

    # (store_name, customer_id) → (lat, lon) : 카카오 신규 지오코딩 건만 수집 (영속 저장용)
    pending_geo_saves: dict[tuple, tuple] = {}

    rows = []
    for _, row in merged.iterrows():
        # app_customers에 latitude, longitude가 있으면 활용 (유효한 숫자일 때만)
        lat_val, lon_val = row.get("latitude"), row.get("longitude")
        try:
            if pd.notna(lat_val) and pd.notna(lon_val) and -90 <= float(lat_val) <= 90 and -180 <= float(lon_val) <= 180:
                lat, lon = float(lat_val), float(lon_val)
                addr_display = _safe_strip_text(row.get("address")) or "-"
                rows.append({
                    "latitude": lat, "longitude": lon, "address": addr_display,
                    "building_name": None, "bname": None,
                    "customer_name": row.get("name") or "-", "category": row.get("category") or "-",
                    "total_amount": int(row.get("total_amount") or 0),
                    "delivery_date": str(row.get("delivery_date") or row.get("order_date") or "-")[:10],
                })
                continue
        except (ValueError, TypeError):
            pass
        addr = _safe_strip_text(row.get("address"))
        if not addr:
            continue
        newly_geocoded = False
        if addr in cache:
            ent = cache[addr]
            lat, lon = ent["latitude"], ent["longitude"]
            addr_display = ent.get("address") or addr
            building_name = ent.get("building_name")
            bname = ent.get("bname")
        else:
            ext = geocode_address_kakao_extended(addr)
            if ext is None:
                continue
            lat, lon = ext["latitude"], ext["longitude"]
            addr_display = ext.get("address") or addr
            building_name = ext.get("building_name")
            bname = ext.get("bname")
            cache[addr] = {"latitude": lat, "longitude": lon, "address": addr_display, "building_name": building_name, "bname": bname}
            newly_geocoded = True

        # 신규 지오코딩 건: 영속 저장을 위해 (store_name, customer_id) 수집
        if newly_geocoded:
            cid = row.get("customer_id")
            store_name = row.get("_store") or ""
            if not store_name:
                db_fn = row.get("_db_fn") or ""
                if db_fn:
                    store_name = _get_current_store_name_for_customers(str(db_fn))
            if cid and store_name:
                key = (store_name, int(cid))
                if key not in pending_geo_saves:
                    pending_geo_saves[key] = (lat, lon)

        rows.append({
            "latitude": lat,
            "longitude": lon,
            "address": addr_display,
            "building_name": building_name,
            "bname": bname,
            "customer_name": row.get("name") or "-",
            "category": row.get("category") or "-",
            "total_amount": int(row.get("total_amount") or 0),
            "delivery_date": str(row.get("delivery_date") or row.get("order_date") or "-")[:10],
        })

    # 신규 지오코딩 결과를 app_customers에 영속 저장 (오류는 조용히 무시 — 지도 렌더링 방해 금지)
    if pending_geo_saves:
        try:
            sc, _ = get_supabase_client()
            if sc:
                for (store_name, cid), (lat, lon) in pending_geo_saves.items():
                    sc.table("app_customers").update({"latitude": lat, "longitude": lon}).eq("store_name", store_name).eq("id", cid).execute()
                load_customers_cached.clear()
        except Exception:
            pass

    if not rows:
        return pd.DataFrame(columns=["latitude", "longitude", "address", "building_name", "bname", "customer_name", "category", "total_amount", "delivery_date"])
    return pd.DataFrame(rows)


# 말풍선(팝업) 가독성: 모바일에서 글자 크기·너비 조정 (Folium Popup 내부 스타일)
_MAP_POPUP_STYLE = (
    "font-size:14px;line-height:1.4;max-width:min(280px,85vw);padding:6px 8px;"
    "font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;"
)


def _create_folium_map(df: pd.DataFrame, center: tuple, zoom_start: int, key: str = "") -> "folium.Map | None":
    """DataFrame(latitude, longitude, address, building_name, customer_name, category, total_amount, delivery_date[, order_count])로
    Folium 지도 생성. order_count 컬럼이 있으면 고객 단위 집계 팝업(건수·합계) 표시."""
    if not FOLIUM_AVAILABLE or df.empty:
        return None
    m = folium.Map(location=center, zoom_start=zoom_start, tiles="OpenStreetMap")
    mc = MarkerCluster(name="판매 현황")
    for _, r in df.iterrows():
        lat, lon = r["latitude"], r["longitude"]
        if pd.isna(lat) or pd.isna(lon):
            continue
        building_name = r.get("building_name") or r.get("bname")
        try:
            addr = "" if (r.get("address") is None or pd.isna(r.get("address"))) else str(r.get("address")).strip()
        except Exception:
            addr = str(r.get("address") or "").strip()
        line1 = ""
        if building_name:
            line1 = f"<strong>[{html.escape(str(building_name))}]</strong><br>"
        line_addr = f"<b>주소:</b> {html.escape(addr or '-')}<br>" if addr else ""
        order_count = r.get("order_count")
        if order_count and int(order_count) > 1:
            line_count = f"<b>주문 건수:</b> {int(order_count)}건<br>"
            line_amount = f"<b>총 금액:</b> {int(r.get('total_amount', 0)):,.0f}원<br>"
        else:
            line_count = ""
            line_amount = f"<b>금액:</b> {int(r.get('total_amount', 0)):,.0f}원<br>"
        popup_html = (
            f'<div class="map-popup" style="{_MAP_POPUP_STYLE}">'
            f"{line1}"
            f"{line_addr}"
            f"<b>고객명:</b> {html.escape(str(r.get('customer_name', '-')))}<br>"
            f"<b>품목:</b> {html.escape(str(r.get('category', '-')))}<br>"
            f"{line_count}"
            f"{line_amount}"
            f"<b>최근 배송:</b> {html.escape(str(r.get('delivery_date', '-')))}"
            f"</div>"
        )
        folium.Marker([lat, lon], popup=folium.Popup(popup_html, max_width=320)).add_to(mc)
    mc.add_to(m)
    return m


def _render_regional_sales_map_section(merged: pd.DataFrame, key_prefix: str = "map"):
    """지역별 판매 현황 지도: 단일 연도 / 연도별 비교 모드. merged는 orders+customers 조인된 DataFrame (name, address 포함)."""
    if not FOLIUM_AVAILABLE:
        st.info("지도 기능을 사용하려면 `folium`과 `streamlit-folium` 패키지를 설치해 주세요.")
        return
    merged["order_date"] = pd.to_datetime(merged["order_date"], errors="coerce")
    merged = merged[merged["order_date"].notna()]
    merged["order_year"] = merged["order_date"].dt.year.astype(int)
    years = sorted(merged["order_year"].unique().tolist(), reverse=True)
    if not years:
        st.info("지도에 표시할 판매 데이터가 없습니다.")
        return
    year_options = ["전체"] + [str(y) for y in years]
    mode = st.radio(
        "지도 조회 모드",
        ["단일 연도 보기", "연도별 비교 보기"],
        horizontal=True,
        key=f"{key_prefix}_mode",
    )
    if mode == "단일 연도 보기":
        sel_year = st.selectbox("조회 연도", year_options, key=f"{key_prefix}_single_year")
        if sel_year == "전체":
            df_filtered = merged
        else:
            df_filtered = merged[merged["order_year"] == int(sel_year)]
        if len(df_filtered) == 0:
            st.info(f"{sel_year}년 데이터가 없습니다.")
            return
        map_data = _build_map_data_with_geocoding(df_filtered)
        if map_data.empty or "latitude" not in map_data.columns or "longitude" not in map_data.columns:
            st.info("지도에 표시할 위치 데이터(위도/경도)가 존재하지 않습니다.")
            return
        map_data = map_data.dropna(subset=["latitude", "longitude"])
        if map_data.empty:
            st.info("지오코딩 가능한 주소 데이터가 없습니다. (KAKAO_REST_KEY 확인)")
            return
        m = _create_folium_map(map_data, _MAP_CENTER, _MAP_ZOOM, f"{key_prefix}_single")
        if m:
            st_folium(m, returned_objects=[], width="stretch", key=f"{key_prefix}_map_single")
    else:
        col1, col2 = st.columns(2)
        year1_opts = [str(y) for y in years]
        year2_opts = [str(y) for y in years]
        with col1:
            y1 = st.selectbox("비교 연도 1", year1_opts, key=f"{key_prefix}_y1")
        with col2:
            y2 = st.selectbox("비교 연도 2", year2_opts, key=f"{key_prefix}_y2")
        df1 = merged[merged["order_year"] == int(y1)]
        df2 = merged[merged["order_year"] == int(y2)]
        with col1:
            st.caption(f"📅 {y1}년")
            if len(df1) == 0:
                st.info(f"{y1}년 데이터 없음")
            else:
                md1 = _build_map_data_with_geocoding(df1)
                if md1.empty or "latitude" not in md1.columns or "longitude" not in md1.columns:
                    st.info("지도에 표시할 위치 데이터(위도/경도)가 존재하지 않습니다.")
                else:
                    md1 = md1.dropna(subset=["latitude", "longitude"])
                    if md1.empty:
                        st.info("지오코딩 가능한 주소 없음")
                    else:
                        m1 = _create_folium_map(md1, _MAP_CENTER, _MAP_ZOOM, f"{key_prefix}_m1")
                        if m1:
                            st_folium(m1, returned_objects=[], width="stretch", key=f"{key_prefix}_map_left")
        with col2:
            st.caption(f"📅 {y2}년")
            if len(df2) == 0:
                st.info(f"{y2}년 데이터 없음")
            else:
                md2 = _build_map_data_with_geocoding(df2)
                if md2.empty or "latitude" not in md2.columns or "longitude" not in md2.columns:
                    st.info("지도에 표시할 위치 데이터(위도/경도)가 존재하지 않습니다.")
                else:
                    md2 = md2.dropna(subset=["latitude", "longitude"])
                    if md2.empty:
                        st.info("지오코딩 가능한 주소 없음")
                    else:
                        m2 = _create_folium_map(md2, _MAP_CENTER, _MAP_ZOOM, f"{key_prefix}_m2")
                        if m2:
                            st_folium(m2, returned_objects=[], width="stretch", key=f"{key_prefix}_map_right")


@st.cache_data(ttl=300, show_spinner=False)
def _load_customers_region_cached(db_filename: str) -> pd.DataFrame:
    """app_customers 지역 컬럼(id, sigungu, bname, road_name, building_name) 로드.
    지역 컬럼이 아직 마이그레이션되지 않은 경우 빈 DF 반환. TTL 5분."""
    _empty_cols = ["id", "sigungu", "bname", "road_name", "building_name"]
    client, err = get_supabase_client()
    if err or not client:
        return pd.DataFrame(columns=_empty_cols)
    store_name = _get_current_store_name_for_customers(db_filename)
    if not store_name:
        return pd.DataFrame(columns=_empty_cols)
    try:
        page_size = 1000
        offset = 0
        rows: list[dict] = []
        while True:
            r = (
                client.table("app_customers")
                .select("id, sigungu, bname, road_name, building_name")
                .eq("store_name", store_name)
                .range(offset, offset + page_size - 1)
                .execute()
            )
            batch = r.data or []
            rows.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size
        return pd.DataFrame(rows) if rows else pd.DataFrame(columns=_empty_cols)
    except Exception:
        return pd.DataFrame(columns=_empty_cols)


