@st.cache_data(ttl=120, show_spinner=False)
def _erp_compute_monthly_planned_minutes(employee_name: str, year: int, month: int,
                                         *, fallback_db: str | None = None) -> int:
    """월간 계획 근무시간(분) 합산. 캘린더 상단 표시용. 120s 캐시 (근무 일정 변경 시 _erp_invalidate_fetch_caches 로 무효화).

    - app_shift_schedules 전 매장 합산 (해당 직원 · 해당 월 전체, 오늘 이후 포함).
    - shift_start/shift_end NULL 이면 fallback_db 매장 기본 시각으로 보정.
    - 근로기준법 휴게시간 (_erp_break_min) 차감 후 순근무시간.
    """
    if not (employee_name and year and month):
        return 0
    last_day = calendar.monthrange(int(year), int(month))[1]
    period_start = date(int(year), int(month), 1)
    period_end = date(int(year), int(month), last_day)
    total_min = 0
    try:
        client, err = get_supabase_client()
        if err or not client:
            return 0
        r = client.table("app_shift_schedules")\
            .select("shift_date,shift_start,shift_end,db_filename")\
            .eq("employee_name", employee_name)\
            .gte("shift_date", period_start.isoformat())\
            .lte("shift_date", period_end.isoformat())\
            .execute()
        for sh in (r.data or []):
            ss = _erp_parse_time(sh.get("shift_start"))
            ee = _erp_parse_time(sh.get("shift_end"))
            if not (ss and ee):
                _sd_str = str(sh.get("shift_date") or "")[:10]
                _sh_db = str(sh.get("db_filename") or fallback_db or "")
                if _sd_str and _sh_db:
                    try:
                        ss, ee = _erp_default_times_for_date(_sh_db, date.fromisoformat(_sd_str))
                    except Exception:
                        pass
            if ss and ee:
                raw_m = (ee.hour * 60 + ee.minute) - (ss.hour * 60 + ss.minute)
                if raw_m > 0:
                    total_min += max(0, raw_m - _erp_break_min(raw_m))
    except Exception:
        return total_min
    return total_min


@st.cache_data(ttl=120, show_spinner=False)
def _erp_compute_monthly_remaining(db_filename: str, employee_name: str,
                                   year: int, month: int) -> dict:
    """월 카운터 = 월 목표 - 누적 인정 시간. 반환: target_min, worked_min, remaining_min, percent.
    120s 캐시 (근태/근무일정 변경 시 _erp_invalidate_fetch_caches 로 무효화).

    집계 정책 (yearly_breakdown과 동일 · 캘린더 표시와 일치):
      - app_attendance_logs + app_shift_schedules 모두 포함
      - 전 매장 합산 (db_filename 필터 없음)
      - 오늘까지만 집계 (미래 날짜 제외)
      - 전일 대체 유형(정상·지각·조퇴·연차·반차) logs가 있는 날만 shifts 제외 (중복 방지).
        보조 유형(추가근무·회의·행사·시차·포상시간)은 shifts 에 가산 — 캘린더에 둘 다
        표시되는 것과 동일하게 집계.
      - 4시간 이상 근무 시 점심 60분 차감
    """
    target_h = _erp_get_employee_monthly_target(db_filename, employee_name)
    target_min = int(round(target_h * 60))
    last_day = calendar.monthrange(int(year), int(month))[1]
    period_start = date(int(year), int(month), 1)
    # 오늘까지만 집계 — 미래 날짜는 카운팅 불가
    today_cap = min(date.today(), date(int(year), int(month), last_day))

    worked_min = 0
    log_dates: set[str] = set()

    # 1) attendance_logs (전 매장, status=approved)
    try:
        _cli, _err = get_supabase_client()
        if not _err and _cli:
            _rl = _cli.table("app_attendance_logs").select("*")\
                .eq("employee_name", employee_name)\
                .gte("log_date", period_start.isoformat())\
                .lte("log_date", today_cap.isoformat())\
                .execute()
            for _l in (_rl.data or []):
                if (_l.get("status") or "approved") != "approved":
                    continue
                _ld = str(_l.get("log_date") or "")[:10]
                _wt = _l.get("work_type") or ""
                _ss = _erp_parse_time(_l.get("start_time"))
                _ee = _erp_parse_time(_l.get("end_time"))
                _actual = 0
                if _ss and _ee:
                    _raw = max(0, (_ee.hour * 60 + _ee.minute) - (_ss.hour * 60 + _ss.minute))
                    _actual = max(0, _raw - _erp_break_min(_raw))
                # NULL 시각 보정: standard_start/end + diff_minutes 사용
                if _actual == 0 and _wt in ("정상", "추가근무", "회의", "행사", "지각", "조퇴"):
                    _std_s_l = _erp_parse_time(_l.get("standard_start"))
                    _std_e_l = _erp_parse_time(_l.get("standard_end"))
                    if _std_s_l and _std_e_l:
                        _log_std_r = max(0, (_std_e_l.hour * 60 + _std_e_l.minute)
                                         - (_std_s_l.hour * 60 + _std_s_l.minute))
                        _diff_s = int(_l.get("diff_minutes") or 0)
                        _act_r = max(0, _log_std_r - (_diff_s if _wt in ("지각", "조퇴") else 0))
                        _actual = max(0, _act_r - _erp_break_min(_act_r))
                # 전일 대체 유형만 시프트를 대체 (보조 유형은 시프트에 가산 — 캘린더와 일치)
                if _ld and _wt in ("정상", "지각", "조퇴", "연차", "반차"):
                    log_dates.add(_ld)
                if _wt in ("정상", "추가근무", "회의", "행사", "지각", "조퇴"):
                    worked_min += _actual
                elif _wt == "연차":
                    worked_min += 480
                elif _wt == "반차":
                    worked_min += 240
                elif _wt in ("시차사용", "포상시간"):
                    worked_min += int(_l.get("diff_minutes") or 0)
    except Exception:
        pass

    # 2) shift_schedules (전일 대체 logs가 없는 날만, 전 매장, 오늘까지)
    try:
        _cli2, _err2 = get_supabase_client()
        if not _err2 and _cli2:
            _rs = _cli2.table("app_shift_schedules")\
                .select("shift_date,shift_start,shift_end,db_filename")\
                .eq("employee_name", employee_name)\
                .gte("shift_date", period_start.isoformat())\
                .lte("shift_date", today_cap.isoformat())\
                .execute()
            for _sh in (_rs.data or []):
                _sd = str(_sh.get("shift_date") or "")[:10]
                if not _sd or _sd in log_dates:
                    continue  # 전일 대체 logs(정상·지각·조퇴·연차·반차) 우선 (중복 방지)
                _ss = _erp_parse_time(_sh.get("shift_start"))
                _ee = _erp_parse_time(_sh.get("shift_end"))
                # NULL 시간 폴백: 매장 기본 출퇴근 시각 사용
                if not _ss or not _ee:
                    _sh_db = str(_sh.get("db_filename") or db_filename)
                    try:
                        _ss, _ee = _erp_default_times_for_date(_sh_db, date.fromisoformat(_sd))
                    except Exception:
                        pass
                if _ss and _ee:
                    _raw = (_ee.hour * 60 + _ee.minute) - (_ss.hour * 60 + _ss.minute)
                    _m = max(0, _raw - _erp_break_min(_raw))
                    if _m > 0:
                        worked_min += _m
    except Exception:
        pass

    remaining = target_min - worked_min
    percent = (worked_min / target_min * 100.0) if target_min > 0 else 0.0
    return {
        "target_min": target_min,
        "worked_min": worked_min,
        "remaining_min": remaining,
        "percent": round(percent, 1),
    }


def _erp_build_attendance_audit_rows(employee_name: str, fallback_db: str,
                                     start: date, end: date) -> list:
    """일자별 근무시간 상세 감사 행 (엑셀 다운로드용).

    카운터(_erp_compute_monthly_remaining)와 **완전히 동일한 수식**으로 일자별 인정 시간을
    분해한다. 집계 정책: 전일 대체 유형(정상·지각·조퇴·연차·반차) 로그가 있는 날만
    시프트를 로그로 대체하고, 보조 유형(추가근무·회의·행사·시차·포상시간)은 시프트에
    가산한다 — 캘린더 표시와 동일. '시프트대체(h)' > 0 인 날짜는 전일 대체 로그가
    시프트를 대신해 집계된 날짜다 (의도된 대체)."""
    client, err = get_supabase_client()
    if err or not client:
        return []
    today_d = date.today()
    shifts_by_date: dict = {}
    logs_by_date: dict = {}
    try:
        _rs = client.table("app_shift_schedules")\
            .select("shift_date,shift_start,shift_end,db_filename,work_location_name")\
            .eq("employee_name", employee_name)\
            .gte("shift_date", start.isoformat())\
            .lte("shift_date", end.isoformat())\
            .execute()
        for sh in (_rs.data or []):
            _sd = str(sh.get("shift_date") or "")[:10]
            if _sd:
                shifts_by_date.setdefault(_sd, []).append(sh)
    except Exception:
        pass
    try:
        _rl = client.table("app_attendance_logs").select("*")\
            .eq("employee_name", employee_name)\
            .gte("log_date", start.isoformat())\
            .lte("log_date", end.isoformat())\
            .execute()
        for l in (_rl.data or []):
            _ld = str(l.get("log_date") or "")[:10]
            if _ld:
                logs_by_date.setdefault(_ld, []).append(l)
    except Exception:
        pass

    rows: list = []
    for d_iso in sorted(set(shifts_by_date) | set(logs_by_date)):
        try:
            d_obj = date.fromisoformat(d_iso)
        except Exception:
            continue
        # ── 시프트 인정 분 (휴게 차감, NULL 시각은 매장 기본시각 폴백) ──
        shift_min = 0
        shift_txts: list = []
        for sh in shifts_by_date.get(d_iso, []):
            ss = _erp_parse_time(sh.get("shift_start"))
            ee = _erp_parse_time(sh.get("shift_end"))
            if not ss or not ee:
                try:
                    ss, ee = _erp_default_times_for_date(str(sh.get("db_filename") or fallback_db), d_obj)
                except Exception:
                    ss = ee = None
            if ss and ee:
                _raw = (ee.hour * 60 + ee.minute) - (ss.hour * 60 + ss.minute)
                _m = max(0, _raw - _erp_break_min(_raw)) if _raw > 0 else 0
                shift_min += _m
                shift_txts.append(f"{ss.strftime('%H:%M')}~{ee.strftime('%H:%M')}")
            else:
                shift_txts.append("(시각 미입력)")
        # ── 로그별 인정 분 (카운터와 동일 수식) ─────────────────────
        log_min = 0
        log_txts: list = []
        note_parts: list = []
        has_fullday_log = False  # 전일 대체 유형(정상·지각·조퇴·연차·반차) 승인 로그 존재
        for l in logs_by_date.get(d_iso, []):
            wt = l.get("work_type") or ""
            status = l.get("status") or "approved"
            _ss = _erp_parse_time(l.get("start_time"))
            _ee = _erp_parse_time(l.get("end_time"))
            _dm = int(l.get("diff_minutes") or 0)
            rec = 0
            if wt in ("정상", "추가근무", "회의", "행사", "지각", "조퇴"):
                if _ss and _ee:
                    _raw = max(0, (_ee.hour * 60 + _ee.minute) - (_ss.hour * 60 + _ss.minute))
                    rec = max(0, _raw - _erp_break_min(_raw))
                if rec == 0:
                    _std_s = _erp_parse_time(l.get("standard_start"))
                    _std_e = _erp_parse_time(l.get("standard_end"))
                    if _std_s and _std_e:
                        _std_raw = max(0, (_std_e.hour * 60 + _std_e.minute)
                                       - (_std_s.hour * 60 + _std_s.minute))
                        _act = max(0, _std_raw - (_dm if wt in ("지각", "조퇴") else 0))
                        rec = max(0, _act - _erp_break_min(_act))
            elif wt == "연차":
                rec = 480
            elif wt == "반차":
                rec = 240
            elif wt in ("시차사용", "포상시간"):
                rec = _dm
            else:
                note_parts.append(f"'{wt}' 로그는 카운터 미집계 유형")
            _t = (f"{_ss.strftime('%H:%M')}~{_ee.strftime('%H:%M')}" if (_ss and _ee)
                  else (f"{_dm}분" if _dm else ""))
            _st_tag = "" if status == "approved" else f" [{status}]"
            log_txts.append(f"{wt} {_t}".strip() + _st_tag)
            if status == "approved":
                log_min += rec
                if wt in ("정상", "지각", "조퇴", "연차", "반차"):
                    has_fullday_log = True
            else:
                note_parts.append(f"미승인({status}) 로그는 카운터 미반영")
        # ── 카운터 반영 (전일 대체 유형만 시프트 대체, 보조 유형은 가산) ──
        replaced_shift_min = 0
        if d_obj > today_d:
            counter_min = 0
            src = "미래 (카운터 미집계)"
        elif has_fullday_log:
            counter_min = log_min
            if shift_min > 0:
                src = "로그 대체 (정상·연차 등)"
                replaced_shift_min = shift_min
            else:
                src = "로그"
        elif log_min > 0 and shift_min > 0:
            counter_min = shift_min + log_min
            src = "시프트+로그 가산"
        elif log_min > 0:
            counter_min = log_min
            src = "로그"
        elif shift_min > 0:
            counter_min = shift_min
            src = "시프트"
        else:
            counter_min = 0
            src = "-"
        rows.append({
            "날짜": d_iso,
            "요일": _ERP_DOW_LABELS[d_obj.weekday()],
            "정기시프트": " / ".join(shift_txts),
            "시프트인정(h)": round(shift_min / 60, 2),
            "근태로그": " / ".join(log_txts),
            "로그인정(h)": round(log_min / 60, 2),
            "카운터반영(h)": round(counter_min / 60, 2),
            "반영출처": src,
            "시프트대체(h)": round(replaced_shift_min / 60, 2),
            "비고": "; ".join(sorted(set(note_parts))),
        })
    return rows


def _erp_render_attendance_excel_export(current_db: str, role: str, me_name: str,
                                        all_dbs: list, year: int, month: int) -> None:
    """근무시간 상세 엑셀 다운로드 (카운터 ↔ 캘린더 대사·검증용).

    - 일반 직원: 본인 내역만 다운로드.
    - 관리자(store_admin/superadmin): 직원 다중 선택 (비우면 전체 직원).
    - 기간: 연도 + 월(또는 '전체 (연간)').
    - 시트: '월별 요약'(목표/계획/카운터누적/잔여/누락시프트합), '일자별 상세'."""
    _is_admin = role in ("store_admin", "superadmin")
    with st.expander("📥 근무시간 상세 엑셀 다운로드 (카운터 검증용)", expanded=False):
        st.caption(
            "일자별로 정기 시프트·근태 로그와 카운터에 실제 반영된 시간을 나란히 보여줍니다. "
            "집계 정책: 정상·지각·조퇴·연차·반차 로그가 있는 날은 로그가 시프트를 대체하고 "
            "('시프트대체(h)' 열), 추가근무·회의·행사·시차·포상시간 로그는 시프트에 가산됩니다 — "
            "캘린더 표시와 동일합니다."
        )
        emp_db_map: dict = {}
        for _dbf in all_dbs:
            for _e in _erp_get_employee_names_for_store(_dbf):
                emp_db_map.setdefault(_e, _dbf)
        c1, c2, c3 = st.columns([1, 1, 2])
        with c1:
            _x_year = st.number_input("연도", min_value=2020, max_value=2100,
                                      value=int(year), step=1, key="erp_att_xlsx_year")
        with c2:
            _x_month = st.selectbox("월", ["전체 (연간)"] + list(range(1, 13)),
                                    index=int(month), key="erp_att_xlsx_month")
        with c3:
            if _is_admin:
                _emp_opts = sorted(emp_db_map.keys())
                _x_emps = st.multiselect("직원 선택 (비우면 전체 직원)", _emp_opts,
                                         default=[], key="erp_att_xlsx_emps")
                if not _x_emps:
                    _x_emps = _emp_opts
            else:
                _x_emps = [me_name] if me_name else []
                st.text_input("대상 직원 (본인)", value=me_name or "", disabled=True,
                              key="erp_att_xlsx_me")
        if st.button("📊 엑셀 생성", key="erp_att_xlsx_build", type="primary"):
            if not _x_emps:
                st.warning("대상 직원이 없습니다.")
            else:
                _months = list(range(1, 13)) if _x_month == "전체 (연간)" else [int(_x_month)]
                detail_rows: list = []
                summary_rows: list = []
                _pg = st.progress(0.0, text="근무시간 집계 중…")
                for _i, _emp in enumerate(_x_emps):
                    _edb = emp_db_map.get(_emp, current_db)
                    for _m in _months:
                        _s = date(int(_x_year), _m, 1)
                        _e = date(int(_x_year), _m, calendar.monthrange(int(_x_year), _m)[1])
                        _rows = _erp_build_attendance_audit_rows(_emp, _edb, _s, _e)
                        for _r in _rows:
                            detail_rows.append({"직원": _emp, **_r})
                        _ctr = _erp_compute_monthly_remaining(_edb, _emp, int(_x_year), _m)
                        _pl = _erp_compute_monthly_planned_minutes(_emp, int(_x_year), _m,
                                                                   fallback_db=_edb)
                        _repl_sum = sum(float(_r.get("시프트대체(h)") or 0) for _r in _rows)
                        summary_rows.append({
                            "직원": _emp,
                            "연월": f"{int(_x_year)}-{_m:02d}",
                            "목표(h)": round(_ctr["target_min"] / 60, 2),
                            "계획(h)": round(_pl / 60, 2),
                            "카운터누적(h)": round(_ctr["worked_min"] / 60, 2),
                            "잔여(h)": round(_ctr["remaining_min"] / 60, 2),
                            "시프트대체합(h)": round(_repl_sum, 2),
                        })
                    _pg.progress((_i + 1) / len(_x_emps),
                                 text=f"근무시간 집계 중… ({_i + 1}/{len(_x_emps)})")
                _pg.empty()
                if not detail_rows:
                    st.info("선택한 기간에 근무 데이터가 없습니다.")
                    st.session_state.pop("erp_att_xlsx_data", None)
                else:
                    _df_s = pd.DataFrame(summary_rows)
                    _df_d = pd.DataFrame(detail_rows)
                    _buf = io.BytesIO()
                    with pd.ExcelWriter(_buf, engine="openpyxl") as _wr:
                        _df_s.to_excel(_wr, sheet_name="월별 요약", index=False)
                        _df_d.to_excel(_wr, sheet_name="일자별 상세", index=False)
                    _m_tag = "연간" if _x_month == "전체 (연간)" else f"{int(_x_month):02d}월"
                    _emp_tag = _x_emps[0] if len(_x_emps) == 1 else f"직원{len(_x_emps)}명"
                    _fn = f"근무시간상세_{int(_x_year)}_{_m_tag}_{_emp_tag}.xlsx"
                    st.session_state["erp_att_xlsx_data"] = (_buf.getvalue(), _fn)
                    st.success(f"생성 완료 — 일자별 {len(detail_rows)}행 / 요약 {len(summary_rows)}행")
        _cached = st.session_state.get("erp_att_xlsx_data")
        if _cached:
            st.download_button("📥 엑셀 다운로드", data=_cached[0], file_name=_cached[1],
                               mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                               key="erp_att_xlsx_dl")


@st.cache_data(ttl=60, show_spinner=False)
def _erp_fetch_range_cached(table: str, db_col: str, db_filename: str, date_col: str,
                            start_iso: str, end_iso: str, extra_key: tuple) -> list:
    """범위 조회 캐시 본체."""
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        q = client.table(table).select("*").eq(db_col, db_filename).gte(date_col, start_iso).lte(date_col, end_iso)
        for k, v in extra_key:
            if v is not None:
                q = q.eq(k, v)
        r = q.order(date_col).execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception as e:
        st.caption(f"⚠️ {table} 범위 조회 실패: {e}")
        return []


def _erp_fetch_range(table: str, db_col: str, db_filename: str, date_col: str, start: date, end: date, extra_eq: dict | None = None) -> list:
    """날짜 범위 조회 (start, end 포함, 60초 캐시). extra_eq: 추가 eq 조건.
    쓰기 직후엔 _erp_insert/update/delete_row에서 자동 무효화."""
    extra_key = tuple(sorted((extra_eq or {}).items(), key=lambda x: x[0]))
    return _erp_fetch_range_cached(table, db_col, db_filename, date_col,
                                   start.isoformat(), end.isoformat(), extra_key)


@st.cache_data(ttl=60)
def _erp_fetch_range_multi_cached(table: str, db_col: str, db_filenames_key: tuple,
                                  date_col: str, start_iso: str, end_iso: str,
                                  extra_key: tuple) -> list:
    """여러 매장(db_filename)을 .in_() 로 한 번에 범위 조회하는 배치 캐시 본체.
    매장별 순차 쿼리(N회)를 1회로 줄여 캘린더 콜드 로딩을 단축한다."""
    client, err = get_supabase_client()
    if err or not client or not db_filenames_key:
        return []
    try:
        q = (client.table(table).select("*")
             .in_(db_col, list(db_filenames_key))
             .gte(date_col, start_iso).lte(date_col, end_iso))
        for k, v in extra_key:
            if v is not None:
                q = q.eq(k, v)
        r = q.order(date_col).execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception as e:
        st.caption(f"⚠️ {table} 범위 배치 조회 실패: {e}")
        return []


def _erp_fetch_range_multi(table: str, db_col: str, db_filenames: list, date_col: str,
                           start: date, end: date, extra_eq: dict | None = None) -> list:
    """여러 매장 날짜 범위 배치 조회 (60초 캐시). 각 행에는 db_col 값이 포함되어
    호출부에서 매장 귀속을 그대로 판별할 수 있다."""
    extra_key = tuple(sorted((extra_eq or {}).items(), key=lambda x: x[0]))
    return _erp_fetch_range_multi_cached(table, db_col, tuple(db_filenames), date_col,
                                         start.isoformat(), end.isoformat(), extra_key)


@st.cache_data(ttl=300)
def _erp_fetch_table_multi_cached(table: str, db_col: str, db_filenames_key: tuple,
                                  order: str | None) -> list:
    """여러 매장 단순 조회 배치 캐시 본체 (근무기준 룰 등 저빈도 변경 데이터, 300초)."""
    client, err = get_supabase_client()
    if err or not client or not db_filenames_key:
        return []
    try:
        q = client.table(table).select("*").in_(db_col, list(db_filenames_key))
        if order:
            q = q.order(order)
        r = q.execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception:
        return []


def _erp_fetch_table_multi(table: str, db_col: str, db_filenames: list,
                           order: str | None = None) -> list:
    """여러 매장 단순 조회 배치 (300초 캐시)."""
    return _erp_fetch_table_multi_cached(table, db_col, tuple(db_filenames), order)


@st.cache_data(ttl=120)
def _erp_store_events_multi_cached(db_filenames_key: tuple, ym_key: str) -> list:
    """여러 매장 공용 일정을 한 번에 조회하는 배치 캐시 (120초). ym_key='YYYY-MM'.
    다일정(end_date)이 해당 월에 걸치면 포함. 각 행에 db_filename 포함."""
    if not db_filenames_key or not ym_key:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        y, m = ym_key.split("-")
        start = date(int(y), int(m), 1)
        last_day = calendar.monthrange(int(y), int(m))[1]
        end = date(int(y), int(m), last_day)
        r = (client.table("app_store_events").select("*")
             .in_("db_filename", list(db_filenames_key))
             .lte("event_date", end.isoformat())
             .order("event_date").execute())
        rows = (r.data or []) if hasattr(r, "data") else []
        out = []
        for row in rows:
            ev_start_s = str(row.get("event_date") or "")[:10]
            if not ev_start_s:
                continue
            ev_end_s = str(row.get("end_date") or "")[:10] if row.get("end_date") else ""
            try:
                ev_end_date = date.fromisoformat(ev_end_s) if ev_end_s else date.fromisoformat(ev_start_s)
            except Exception:
                ev_end_date = date.fromisoformat(ev_start_s)
            if ev_end_date >= start:
                out.append(row)
        return out
    except Exception:
        return []


def _erp_store_events_multi(db_filenames: list, ym_key: str) -> list:
    return _erp_store_events_multi_cached(tuple(db_filenames), ym_key)


def _erp_count_active_at(shifts: list, slot_start: dt_time, slot_end: dt_time) -> int:
    """shifts(같은 날짜)에서 [slot_start, slot_end)와 겹치는 인원 수."""
    s0 = slot_start.hour * 60 + slot_start.minute
    e0 = slot_end.hour * 60 + slot_end.minute
    cnt = 0
    for s in shifts:
        st_t = _erp_parse_time(s.get("shift_start"))
        en_t = _erp_parse_time(s.get("shift_end"))
        if not st_t or not en_t:
            continue
        s1 = st_t.hour * 60 + st_t.minute
        e1 = en_t.hour * 60 + en_t.minute
        if s1 < e0 and e1 > s0:
            cnt += 1
    return cnt


def _erp_validate_shifts_against_rules(db_filename: str, planned_shifts_by_date: dict) -> list:
    """planned_shifts_by_date: {date: [{employee_name, shift_start, shift_end}, ...]}
    각 날짜의 요일에 해당하는 최소 인원 규칙을 슬롯 단위로 검사.
    반환: 위반 메시지 리스트 (빈 리스트 = OK)."""
    rules_all = _erp_staffing_rules_cached(db_filename)
    rules_by_dow: dict[int, list] = {}
    for r in rules_all:
        rules_by_dow.setdefault(int(r.get("day_of_week") or 0), []).append(r)
    violations: list[str] = []
    for d, shifts in sorted(planned_shifts_by_date.items()):
        dow = d.weekday()
        rules = rules_by_dow.get(dow, [])
        if not rules:
            continue
        for rule in rules:
            slot_s = _erp_parse_time(rule.get("slot_start"))
            slot_e = _erp_parse_time(rule.get("slot_end"))
            min_n = int(rule.get("min_staff") or 1)
            if not slot_s or not slot_e:
                continue
            cnt = _erp_count_active_at(shifts, slot_s, slot_e)
            if cnt < min_n:
                violations.append(
                    f"{d.isoformat()}({_ERP_DOW_LABELS[dow]}) {rule.get('slot_start')}~{rule.get('slot_end')} "
                    f"구간 {min_n - cnt}명 부족 (배정 {cnt}명 / 최소 {min_n}명)"
                )
    return violations


def _erp_check_cross_store_conflicts(
    emp_name: str,
    current_db: str,
    edits: dict,
) -> list[str]:
    """
    저장 예정 일정(edits)에서 타 매장의 기존 일정과 시간 겹침이 있는지 검사.
    edits: {date_str: (chk, start_time|None, end_time|None)}
    반환: 충돌 메시지 리스트 (빈 리스트 = OK)
    """
    # 체크된 날짜만 추출
    check_dates = [d for d, (chk, _, _) in edits.items() if chk]
    if not check_dates:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []

    aliases = _get_current_user_employee_aliases(emp_name)
    conflicts = []

    try:
        # 모든 매장의 해당 날짜 일정을 한 번에 조회 (db_filename 필터 없이)
        q = (
            client.table("app_shift_schedules")
            .select("db_filename, shift_date, shift_start, shift_end, work_location_name")
            .in_("shift_date", check_dates)
            .in_("employee_name", aliases)
            .execute()
        )
        others = [r for r in (q.data or []) if (r.get("db_filename") or "") != current_db]
    except Exception:
        return []

    for d_str, (chk, t1, t2) in edits.items():
        if not chk or not t1 or not t2:
            continue
        new_s = t1.hour * 60 + t1.minute
        new_e = t2.hour * 60 + t2.minute
        for rec in others:
            if str(rec.get("shift_date") or "")[:10] != d_str:
                continue
            ex_s_t = _erp_parse_time(rec.get("shift_start"))
            ex_e_t = _erp_parse_time(rec.get("shift_end"))
            if not ex_s_t or not ex_e_t:
                continue
            ex_s = ex_s_t.hour * 60 + ex_s_t.minute
            ex_e = ex_e_t.hour * 60 + ex_e_t.minute
            # 겹침 조건: new_s < ex_e AND ex_s < new_e
            if new_s < ex_e and ex_s < new_e:
                loc = rec.get("work_location_name") or rec.get("db_filename") or "타 매장"
                conflicts.append(
                    f"{d_str}: {t1.strftime('%H:%M')}~{t2.strftime('%H:%M')} 가 "
                    f"[{loc}] {str(rec.get('shift_start',''))[:5]}~{str(rec.get('shift_end',''))[:5]} 와 겹칩니다."
                )
    return conflicts



    """
    planned_shifts_by_date: {date: [{employee_name, shift_start, shift_end}, ...]}
    반환: 위반 메시지 리스트 (빈 리스트 = OK)
    """
    rules_all = _erp_staffing_rules_cached(db_filename)
    rules_by_dow = {}
    for r in rules_all:
        rules_by_dow.setdefault(int(r.get("day_of_week") or 0), []).append(r)
    violations = []
    for d, shifts in sorted(planned_shifts_by_date.items()):
        dow = d.weekday()
        rules = rules_by_dow.get(dow, [])
        if not rules:
            continue
        for rule in rules:
            slot_s = _erp_parse_time(rule.get("slot_start"))
            slot_e = _erp_parse_time(rule.get("slot_end"))
            min_n = int(rule.get("min_staff") or 1)
            if not slot_s or not slot_e:
                continue
            cnt = _erp_count_active_at(shifts, slot_s, slot_e)
            if cnt < min_n:
                violations.append(
                    f"{d.isoformat()}({_ERP_DOW_LABELS[dow]}) {rule.get('slot_start')}~{rule.get('slot_end')} "
                    f"구간 {min_n - cnt}명 부족 (배정 {cnt}명 / 최소 {min_n}명)"
                )
    return violations


@st.cache_data(ttl=60, show_spinner=False)
def _erp_compute_remaining_comptime(home_db: str, employee_name: str) -> int:
    """잔여 시차(분) = SUM(시차적립.diff_minutes) - SUM(시차사용.diff_minutes). approved 만 집계.
    60초 캐시. 쓰기 직후엔 _erp_insert/update/delete_row에서 자동 무효화."""
    client, err = get_supabase_client()
    if err or not client:
        return 0
    try:
        r = client.table("app_attendance_logs").select("work_type, diff_minutes, status").eq(
            "home_db_filename", home_db).eq("employee_name", employee_name).execute()
        rows = (r.data or []) if hasattr(r, "data") else []
        earn = sum(int(x.get("diff_minutes") or 0) for x in rows if x.get("work_type") == "시차적립" and (x.get("status") or "approved") == "approved")
        use = sum(int(x.get("diff_minutes") or 0) for x in rows if x.get("work_type") == "시차사용" and (x.get("status") or "approved") == "approved")
        return earn - use
    except Exception:
        return 0


def _erp_calc_legal_leave(hire_date: date, year: int) -> dict:
    """한국 근로기준법(제60조) 기준 연차 일수 상세 계산.

    반환 dict:
      total_days          : 최종 연차 일수 (대시보드·부여 기본값)
      base_days           : 기본 연차 (15일 또는 입사연도 비례)
      long_service_extra  : 장기근속 가산 일수
      years_of_service    : 근속연수 (해당 연도 1월 1일 기준)
      note                : 계산 근거 설명 문자열

    근로기준법 공식:
      - 입사 연도(1년 미만): 15일 × 재직 개월 / 12 (0.5 단위 반올림)
      - 1년 이상: 기본 15일
      - 3년 이상: 15일 + floor((근속연수 − 1) / 2) — 최대 25일
    """
    year_start = date(int(year), 1, 1)

    # 근속연수 계산 (해당 연도 1월 1일 기준)
    if hire_date >= year_start:
        # 해당 연도 입사 → 입사월 기준 비례 배분
        months_remaining = 13 - hire_date.month
        base = round(15.0 * months_remaining / 12 * 2) / 2
        return {
            "total_days": max(0.0, base),
            "base_days": max(0.0, base),
            "long_service_extra": 0,
            "years_of_service": 0,
            "note": f"입사 연도 비례 ({months_remaining}개월 / 12 × 15일 = {base:g}일)",
        }

    # 기준일(해당 연도 1월 1일)까지의 근속연수 (정수)
    yos_raw = (year_start.year - hire_date.year) * 12 + (year_start.month - hire_date.month)
    if year_start.day < hire_date.day:
        yos_raw -= 1
    years_of_service = yos_raw // 12   # 연 단위 정수

    base = 15.0
    extra = int(min(10, max(0, (years_of_service - 1) // 2)))  # max extra = 10 → 총 25일
    total = min(25.0, base + extra)

    if years_of_service < 1:
        note = f"근속 {years_of_service}년 → 비례 (기본 15일 적용)"
    elif extra == 0:
        note = f"근속 {years_of_service}년 → 기본 15일"
    else:
        note = (
            f"근속 {years_of_service}년 → 기본 15일 + 장기근속 {extra}일 "
            f"(floor(({years_of_service}-1)/2)) = {total:g}일"
        )

    return {
        "total_days": total,
        "base_days": base,
        "long_service_extra": extra,
        "years_of_service": years_of_service,
        "note": note,
    }


def _erp_compute_annual_days_for_hire(hire_date: date, year: int, full_days: float = 15.0) -> float:
    """하위호환 래퍼 — 내부는 _erp_calc_legal_leave 사용."""
    return _erp_calc_legal_leave(hire_date, year)["total_days"]


def _erp_compute_monthly_accrued(hire_date_str: str | None, as_of: date) -> int:
    """입사일 기반 월차 적립분: min(경과 개월, 11). hire_date가 없거나 미래면 0."""
    if not hire_date_str:
        return 0
    try:
        hd = datetime.fromisoformat(str(hire_date_str)[:10]).date()
    except Exception:
        return 0
    if hd > as_of:
        return 0
    months = (as_of.year - hd.year) * 12 + (as_of.month - hd.month)
    if as_of.day < hd.day:
        months -= 1
    return max(0, min(months, 11))


def _erp_calc_shift_hours(start_t: dt_time, end_t: dt_time) -> float:
    """근무 시작/종료 시각으로 순근무 시간(시간) 계산.
    _erp_break_min 과 동일한 근로기준법 휴게시간 룰 사용:
      - 8시간(480분) 이상 → 60분 차감
      - 4시간(240분) 이상 ~ 8시간 미만 → 30분 차감
      - 4시간 미만 → 차감 없음
    """
    if not start_t or not end_t:
        return 0.0
    s_min = start_t.hour * 60 + start_t.minute
    e_min = end_t.hour * 60 + end_t.minute
    raw_min = max(0, e_min - s_min)
    net_min = max(0, raw_min - _erp_break_min(raw_min))
    return round(net_min / 60.0, 2)


def _erp_compute_leave_status(current_db: str, employee_name: str, as_of: date) -> dict:
    """직원의 연차/월차 잔여·소진 위험도 계산.
    반환: {annual_total, annual_used, annual_remain, days_until_year_end, soak_risk}
    """
    year = as_of.year
    grants = _erp_fetch_table("app_leave_grants", {
        "home_db_filename": current_db,
        "employee_name": employee_name,
        "year": int(year),
    })
    grant = grants[0] if grants else {}
    annual_total = float(grant.get("annual_days") or 0)
    year_start = date(year, 1, 1)
    year_end = date(year, 12, 31)
    logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", current_db,
                            "log_date", year_start, year_end,
                            extra_eq={"employee_name": employee_name})
    annual_used = sum(float(l.get("leave_deduction") or 0)
                      for l in logs if l.get("work_type") == "연차")
    annual_remain = max(0.0, annual_total - annual_used)
    days_until_year_end = max(0, (year_end - as_of).days)
    # 소멸 위험: 잔여 연차 > 연말까지 남은 평일 수의 절반
    risk = annual_remain > 0 and days_until_year_end < (annual_remain * 14)
    return {
        "annual_total": annual_total,
        "annual_used": annual_used,
        "annual_remain": annual_remain,
        "days_until_year_end": days_until_year_end,
        "soak_risk": risk,
    }


_ERP_CACHED_TABLES = {
    "app_attendance_logs", "app_shift_schedules", "app_overtime_requests",
    "app_overtime_claims", "app_leave_grants", "app_staffing_rules",
    "app_store_events", "app_store_hours", "app_employee_settings",
    "app_work_adjustments", "app_monthly_work_targets", "app_yearly_work_targets",
    "app_period_work_targets",
}


def _erp_invalidate_fetch_caches(table: str) -> None:
    """ERP 테이블 쓰기 후 관련 캐시 자동 무효화. 정확한 무효화보다 안전 우선."""
    if table not in _ERP_CACHED_TABLES:
        return
    try:
        _erp_fetch_table_cached.clear()
    except Exception:
        pass
    try:
        _erp_fetch_range_cached.clear()
    except Exception:
        pass
    # 배치(.in_) 캐시도 함께 무효화 (쓰기 후 캘린더 stale 방지)
    for _fn in (_erp_fetch_range_multi_cached, _erp_fetch_table_multi_cached,
                _erp_store_events_multi_cached):
        try:
            _fn.clear()
        except Exception:
            pass
    if table == "app_attendance_logs":
        try:
            _erp_compute_remaining_comptime.clear()
        except Exception:
            pass
    # 근태 집계 함수 캐시도 관련 테이블 변경 시 무효화 (P0-3)
    if table in ("app_attendance_logs", "app_shift_schedules", "app_work_adjustments",
                 "app_leave_grants", "app_employee_settings",
                 "app_period_work_targets", "app_yearly_work_targets"):
        for _fn in (_erp_compute_monthly_planned_minutes,
                    _erp_compute_monthly_remaining,
                    _erp_compute_yearly_breakdown):
            try:
                _fn.clear()
            except Exception:
                pass
        try:
            _erp_list_period_targets.clear()
        except Exception:
            pass
        try:
            _erp_get_yearly_target_row.clear()
            _erp_list_yearly_targets.clear()
        except Exception:
            pass


def _erp_insert_row(table: str, row: dict) -> tuple[bool, str]:
    """단일 행 insert. (성공, 에러문) 반환. 성공 시 관련 캐시 자동 무효화."""
    client, err = get_supabase_client()
    if err or not client:
        return False, err or "Supabase 클라이언트 없음"
    try:
        client.table(table).insert(row).execute()
        _erp_invalidate_fetch_caches(table)
        return True, ""
    except Exception as e:
        return False, str(e)


def _erp_update_row(table: str, row_id: int, patch: dict) -> tuple[bool, str]:
    client, err = get_supabase_client()
    if err or not client:
        return False, err or "Supabase 클라이언트 없음"
    try:
        client.table(table).update(patch).eq("id", row_id).execute()
        _erp_invalidate_fetch_caches(table)
        return True, ""
    except Exception as e:
        return False, str(e)


def _erp_delete_row(table: str, row_id: int) -> tuple[bool, str]:
    client, err = get_supabase_client()
    if err or not client:
        return False, err or "Supabase 클라이언트 없음"
    try:
        client.table(table).delete().eq("id", row_id).execute()
        _erp_invalidate_fetch_caches(table)
        return True, ""
    except Exception as e:
        return False, str(e)


