def _erp_ym_add(ym: str, months: int) -> str:
    """'YYYY-MM' 에 months 더한 'YYYY-MM' 반환."""
    y, m = (int(x) for x in ym.split("-"))
    total = (y * 12 + (m - 1)) + months
    return f"{total // 12:04d}-{total % 12 + 1:02d}"


def _erp_ym_range_bounds(start_ym: str, end_ym: str) -> tuple[date, date]:
    """start_ym 1일 ~ end_ym 말일 의 date 경계 반환."""
    sy, sm = (int(x) for x in start_ym.split("-"))
    ey, em = (int(x) for x in end_ym.split("-"))
    start = date(sy, sm, 1)
    end = date(ey, em, calendar.monthrange(ey, em)[1])
    return start, end


def _erp_find_active_period_target(db_filename: str, employee_name: str,
                                   ref: date) -> dict | None:
    """ref 날짜가 속한 기간 목표를 반환. 여러 개면 가장 먼저 시작하는 것.
    속한 게 없으면 ref 이후 가장 가까운(다가오는) 기간을 반환, 그것도 없으면 None."""
    rows = _erp_list_period_targets(db_filename, employee_name)
    if not rows:
        return None
    ref_ym = f"{ref.year:04d}-{ref.month:02d}"
    covering = [r for r in rows if (r.get("start_ym") or "") <= ref_ym <= (r.get("end_ym") or "")]
    if covering:
        return sorted(covering, key=lambda r: r.get("start_ym") or "")[0]
    upcoming = [r for r in rows if (r.get("start_ym") or "") > ref_ym]
    if upcoming:
        return sorted(upcoming, key=lambda r: r.get("start_ym") or "")[0]
    return sorted(rows, key=lambda r: r.get("end_ym") or "")[-1]


def _erp_resolve_period_target_for_year(
    db_filename: str, employee_name: str, year: int, as_of: date
) -> dict | None:
    """조회 연도와 겹치는 기간 목표(근무시간 설정) 1건.
    as_of 월을 덮는 행 우선, 없으면 겹치는 행 중 시작월이 빠른 것.
    required_minutes > 0 인 행만 후보."""
    rows = _erp_list_period_targets(db_filename, employee_name)
    if not rows:
        return None
    year_start = f"{int(year):04d}-01"
    year_end = f"{int(year):04d}-12"
    overlapping = [
        r for r in rows
        if (r.get("start_ym") or "") <= year_end
        and (r.get("end_ym") or "") >= year_start
        and int(r.get("required_minutes") or 0) > 0
    ]
    if not overlapping:
        return None
    ref_ym = f"{as_of.year:04d}-{as_of.month:02d}"
    covering = [
        r for r in overlapping
        if (r.get("start_ym") or "") <= ref_ym <= (r.get("end_ym") or "")
    ]
    pool = covering or overlapping
    return sorted(pool, key=lambda r: r.get("start_ym") or "")[0]


@st.cache_data(ttl=180, show_spinner=False)
def _erp_compute_yearly_breakdown(db_filename: str, employee_name: str,
                                  year: int, as_of: date) -> dict:
    """연도별 대시보드용 근무 breakdown (통합 카테고리).
    180s 캐시 (근태/신청 변경 시 _erp_invalidate_fetch_caches 로 무효화).

    ⚠️ 단일 소스 원칙 (v2.1 리팩터):
      - 카테고리 총합(normal/overtime/short/leave)은 **app_attendance_logs 만** 참조한다.
      - app_work_adjustments 의 승인 건은 승인 시 자동으로 log 를 생성하므로 log 에 이미 반영됨.
      - 과거 log 미생성 승인 건은 '기존 승인 내역 캘린더 재동기화' 도구로 log 를 만들 것.
      - additions/deductions 딕셔너리는 kind 별 상세 breakdown 을 위해서만 사용 (합산에는 미포함).
        → 두 번 카운트되는 문제(early_leave 조퇴 log + adjustment) 해결.

    집계 정책: **캘린더에 표시된 시간 그대로, 전 매장 합산** (db_filename 무관)
      - attendance_logs / shift_schedules 모두 employee_name 기준
      - 같은 날 전일 대체 유형(정상·지각·조퇴·연차·반차) logs가 있으면 logs 우선,
        보조 유형(추가근무·회의·행사·시차·포상시간)만 있는 날은 shift 가산 + 보조 log 가산
        (캘린더에 시프트·보조 배지가 함께 표시되는 것과 동일)

    반환 dict (단위: 분):
      - required_min      : 공통 필요근무시간
      - required_source   : 'period' | 'yearly' | 'none' (기간 목표 1순위)
      - deductions / additions : 상세 분류 (kind_label → minutes) — UI 상세보기용 (합산 미포함)
      - normal_min        : 정상근무 (logs 정상/지각/조퇴 actual + shifts logs-없는-날짜)
      - overtime_min      : 연장근무 (logs 추가근무·회의·행사·시차사용·포상시간)
      - short_min         : 단축근무 (logs 지각·조퇴 diff_minutes) — 디버그·표시용
      - leave_min         : 연차 480×n + 반차 240×n (logs)
      - actual_total_min  : 실제 근무시간 = normal + overtime + leave
                            (사용자 수식 '실근무 + 연장 - 단축 + 연차' 와 동치.
                             실근무=정상+단축 → (normal+short) + overtime - short + leave = normal + overtime + leave)
    """
    period_end = date(int(year), 12, 31)

    # ── 공통 필요근무시간 + 집계 시작일 ──────────────────────────
    # 1순위: 근무시간 설정(기간 목표) / 2순위: app_yearly_work_targets
    row_period = _erp_resolve_period_target_for_year(
        db_filename, employee_name, int(year), as_of
    )
    row_y = _erp_get_yearly_target_row(db_filename, employee_name, int(year))
    if row_period is not None:
        required_min = int(row_period.get("required_minutes") or 0)
        required_source = "period"
    elif row_y and row_y.get("required_minutes") is not None and int(row_y["required_minutes"]) > 0:
        required_min = int(row_y["required_minutes"])
        required_source = "yearly"
    else:
        required_min = 0
        required_source = "none"

    # 집계 시작일: 연간 테이블 period_start_date → 기간 목표 start_ym 1일 → 연도 1/1
    _raw_psd = row_y.get("period_start_date") if row_y else None
    if _raw_psd:
        try:
            period_start = date.fromisoformat(str(_raw_psd)[:10])
        except Exception:
            period_start = date(int(year), 1, 1)
    elif row_period and row_period.get("start_ym"):
        try:
            _sy, _sm = str(row_period["start_ym"]).split("-")[:2]
            period_start = date(int(_sy), int(_sm), 1)
        except Exception:
            period_start = date(int(year), 1, 1)
    else:
        period_start = date(int(year), 1, 1)

    today_cap = min(period_end, as_of)

    # ── 조정 항목 breakdown (app_work_adjustments) — UI 상세 표시용 ──
    # 총합에는 미포함 (log 를 단일 소스로 사용). kind 별 라벨→분 매핑만 채운다.
    # deductions 의미 = '필요근무시간 자체를 줄이는 항목' (여름휴가/포상/장기근속/특이사항(-)).
    # early_leave 는 필요시간을 줄이지 않고 실근무시간만 깎으므로 여기서 제외 (logs 조퇴 로 반영).
    deductions: dict[str, int] = {}
    additions: dict[str, int] = {}
    try:
        client, err = get_supabase_client()
        if not err and client:
            r = client.table("app_work_adjustments").select("kind,sign,minutes,target_date")\
                .eq("employee_name", employee_name)\
                .eq("status", "approved")\
                .gte("target_date", period_start.isoformat())\
                .lte("target_date", period_end.isoformat())\
                .execute()
            for r_ in (r.data or []):
                kind = (r_.get("kind") or "etc").strip()
                sign = (r_.get("sign") or _ERP_ADJ_KIND_DEFAULT_SIGN.get(kind, "+")).strip()
                m = abs(int(r_.get("minutes") or 0))
                label = _ERP_ADJ_KIND_LABEL.get(kind, kind)
                if sign == "-":
                    if kind == "early_leave":
                        continue  # logs 조퇴 로만 카운트, 필요근무시간 감산 대상 아님
                    deductions[label] = deductions.get(label, 0) + m
                else:
                    additions[label] = additions.get(label, 0) + m
    except Exception:
        pass

    # ── 캘린더 출퇴근 로그 (app_attendance_logs) ────────────────
    # 정책: 캘린더에 표시되는 그대로 — 전 매장 합산 (db_filename 필터 없음)
    logs = []
    try:
        _cli_logs, _e_logs = get_supabase_client()
        if not _e_logs and _cli_logs:
            _r_logs = _cli_logs.table("app_attendance_logs").select("*")\
                .eq("employee_name", employee_name)\
                .gte("log_date", period_start.isoformat())\
                .lte("log_date", today_cap.isoformat())\
                .execute()
            logs = list(_r_logs.data or [])
    except Exception:
        logs = []
    normal_min_logs = 0
    # 디버그용: 날짜별 정상근무 내역
    _debug_normal_logs: list = []
    _debug_normal_shifts: list = []
    overtime_min_logs = 0
    short_min_logs = 0      # 지각/조퇴 차감
    leave_min = 0
    log_dates: set[str] = set()
    for l in logs:
        if (l.get("status") or "approved") != "approved":
            continue
        _ld_raw = l.get("log_date")
        _ld_str = str(_ld_raw)[:10] if _ld_raw else ""
        wt = l.get("work_type") or ""
        ss = _erp_parse_time(l.get("start_time"))
        ee = _erp_parse_time(l.get("end_time"))
        actual_min = 0
        if ss and ee:
            raw_min = max(0, (ee.hour * 60 + ee.minute) - (ss.hour * 60 + ss.minute))
            actual_min = max(0, raw_min - _erp_break_min(raw_min))

        # ── NULL 시각 보정 ─────────────────────────────────────────────
        # start_time/end_time이 없으면 standard_start/end + diff_minutes로 추정
        if actual_min == 0 and wt in ("정상", "추가근무", "회의", "행사", "지각", "조퇴"):
            _std_s_log = _erp_parse_time(l.get("standard_start"))
            _std_e_log = _erp_parse_time(l.get("standard_end"))
            if _std_s_log and _std_e_log:
                _log_std_raw = max(0, (_std_e_log.hour * 60 + _std_e_log.minute)
                                   - (_std_s_log.hour * 60 + _std_s_log.minute))
                _diff_stored = int(l.get("diff_minutes") or 0)
                # 지각/조퇴: 표준 시간에서 단축 분만큼 차감
                _act_raw = max(0, _log_std_raw - (_diff_stored if wt in ("지각", "조퇴") else 0))
                actual_min = max(0, _act_raw - _erp_break_min(_act_raw))

        # ── log_dates 등록: 전일 대체 유형(정상·지각·조퇴·연차·반차)만 ──
        # 보조 유형(추가근무·회의·행사·시차·포상시간)은 같은 날 시프트에 가산 (캘린더와 일치)
        if _ld_str and wt in ("정상", "지각", "조퇴", "연차", "반차"):
            log_dates.add(_ld_str)

        if wt == "정상":
            normal_min_logs += actual_min
            _debug_normal_logs.append({
                "date": _ld_str, "type": "log:정상", "h": round(actual_min / 60, 2),
                "store": l.get("home_db_filename") or "",
            })
        elif wt in ("추가근무", "회의", "행사"):
            overtime_min_logs += actual_min
        elif wt in ("지각", "조퇴"):
            # normal_min_logs: 실제 근무한 분(actual_min) 만 정상근무로 인정.
            # short_min_logs: 표준 대비 부족분(단축시간) — 디버그·집계 카드 표시용.
            _diff_min_log = int(l.get("diff_minutes") or 0)
            if _diff_min_log > 0:
                short_min_logs += _diff_min_log
            else:
                try:
                    _ld_d = date.fromisoformat(_ld_str) if _ld_str else as_of
                    std_s, std_e = _erp_default_times_for_date(db_filename, _ld_d)
                    _std_raw = max(0, (std_e.hour * 60 + std_e.minute)
                                   - (std_s.hour * 60 + std_s.minute))
                    std_min = max(0, _std_raw - _erp_break_min(_std_raw))
                    if std_min > 0 and actual_min > 0 and actual_min < std_min:
                        short_min_logs += (std_min - actual_min)
                except Exception:
                    pass
            normal_min_logs += actual_min
            _debug_normal_logs.append({
                "date": _ld_str, "type": f"log:{wt}", "h": round(actual_min / 60, 2),
                "store": l.get("home_db_filename") or "",
            })
        elif wt == "연차":
            leave_min += 480
        elif wt == "반차":
            leave_min += 240
        elif wt in ("시차사용", "포상시간"):
            overtime_min_logs += int(l.get("diff_minutes") or 0)  # 통합: 연장으로 카운트

    # ── 시프트 자동 가산 (app_shift_schedules, 오늘 포함 과거) ──
    # 복수 매장 지원: db_filename 필터 제거 → 모든 매장 시프트 합산
    # 전일 대체 logs(정상·지각·조퇴·연차·반차)가 있는 날짜만 logs 우선 (중복 방지)
    shift_normal_min = 0
    _debug_null_shifts: list[str] = []   # 시간 미입력 시프트 날짜 목록 (경고용)
    try:
        client2, err2 = get_supabase_client()
        if not err2 and client2:
            r2 = client2.table("app_shift_schedules")\
                .select("shift_date,shift_start,shift_end,db_filename")\
                .eq("employee_name", employee_name)\
                .gte("shift_date", period_start.isoformat())\
                .lte("shift_date", today_cap.isoformat())\
                .execute()
            for sh in (r2.data or []):
                sd = str(sh.get("shift_date") or "")[:10]
                if not sd or sd in log_dates:
                    continue  # logs 우선
                ss = _erp_parse_time(sh.get("shift_start"))
                ee = _erp_parse_time(sh.get("shift_end"))

                # ── NULL 시간 폴백: 매장 기본 출퇴근 시각 사용 ──────
                if not ss or not ee:
                    _sh_db = str(sh.get("db_filename") or db_filename)
                    try:
                        _sd_date = date.fromisoformat(sd)
                        ss, ee = _erp_default_times_for_date(_sh_db, _sd_date)
                        _debug_null_shifts.append(sd)
                    except Exception:
                        pass

                if ss and ee:
                    raw_m = (ee.hour * 60 + ee.minute) - (ss.hour * 60 + ss.minute)
                    # 근로기준법: 4h~8h → 30분, 8h 이상 → 60분
                    m = max(0, raw_m - _erp_break_min(raw_m))
                    if m > 0:
                        shift_normal_min += m
                        _time_note = "shift(기본시간)" if sd in _debug_null_shifts else "shift"
                        _debug_normal_shifts.append({
                            "date": sd,
                            "type": _time_note,
                            "h": round(m / 60, 2),
                        })
    except Exception:
        pass

    # ── 통합 합산 (단일 소스: logs) ──────────────────────────────
    # ⚠️ v2.1 리팩터: overtime_adj_min / short_adj_min 을 총합에 더하지 않음.
    #  - 승인된 adjustment 는 auto-sync 로 log 를 생성하므로 logs 에 이미 포함.
    #  - 과거 미동기화 승인 건은 '기존 승인 내역 재동기화' 도구로 log 생성 필요.
    #
    # 수식(사용자 지정): 실제근무 = 실근무(예정) + 연장 - 단축 + 연차
    #  - 여기서 실근무(예정) = normal + short (실제 근무 + 단축분 = 예정 표준시간).
    #  - 정리하면 actual = normal + overtime + leave 로 동일.
    #  - normal_min 은 로그 기반 실제 근무한 분(조퇴/지각 log 도 partial 로 인정).
    #  - short_min 은 표시·검증용 (수식 검증 시 short = std - normal 로 계산 후 확인).
    normal_min   = normal_min_logs + shift_normal_min
    overtime_min = overtime_min_logs
    short_min    = short_min_logs
    actual_total_min = normal_min + overtime_min + leave_min

    return {
        "required_min": required_min,
        "required_source": required_source,
        "deductions": deductions,
        "additions": additions,
        "normal_min": normal_min,
        "overtime_min": overtime_min,
        "short_min": short_min,
        "leave_min": leave_min,
        "hour_swap_min": 0,  # overtime_min에 통합
        "actual_total_min": actual_total_min,
        "shift_normal_min": shift_normal_min,  # 디버그·표시용 (시프트 자동 가산분)
        "normal_min_logs": normal_min_logs,    # 디버그용 (logs 기반 정상근무)
        "period_start": period_start.isoformat(),
        "today_cap": today_cap.isoformat(),
        "debug_normal_logs": _debug_normal_logs,
        "debug_normal_shifts": _debug_normal_shifts,
        "debug_null_shifts": _debug_null_shifts,
    }


def _erp_fmt_hm(total_min: int) -> str:
    """분 → 'Xh Ym' 또는 'Xh' 표시."""
    total_min = int(total_min or 0)
    sign = "-" if total_min < 0 else ""
    total_min = abs(total_min)
    h = total_min // 60
    m = total_min % 60
    if m == 0:
        return f"{sign}{h:,}h"
    return f"{sign}{h:,}h {m}m"


# =====================================================================
# 정기근무·캘린더 ↔ 자동 연장/단축 보정 (app_work_adjustments)
# =====================================================================
_ERP_AUTO_ADJ_TAGS = ("[자동-정기근무]", "[자동-캘린더]")  # reason prefix 식별


def _erp_compute_shift_overage(db_filename: str, shift_date: date,
                               shift_start_t: dt_time, shift_end_t: dt_time) -> tuple[int, int, int]:
    """매장 표준 대비 차이(분) 계산.

    반환: (diff_minutes, std_minutes, actual_minutes) — 모두 근로기준법 휴게시간 차감 후 순근무분.
      - diff > 0 → 연장 / diff < 0 → 단축 / diff == 0 → 동일
      - 매장 표준은 _erp_default_times_for_date 기준 (평일/주말 자동 분기)
    """
    if not (shift_start_t and shift_end_t):
        return 0, 0, 0
    _actual_raw = max(0, (shift_end_t.hour * 60 + shift_end_t.minute)
                      - (shift_start_t.hour * 60 + shift_start_t.minute))
    actual_min = max(0, _actual_raw - _erp_break_min(_actual_raw))
    try:
        std_s, std_e = _erp_default_times_for_date(db_filename, shift_date)
        _std_raw = max(0, (std_e.hour * 60 + std_e.minute) - (std_s.hour * 60 + std_s.minute))
        std_min = max(0, _std_raw - _erp_break_min(_std_raw))
    except Exception:
        std_min = 0
    if std_min <= 0:
        return 0, 0, actual_min
    return (actual_min - std_min), std_min, actual_min


def _erp_delete_existing_auto_adjustment(db_filename: str, employee_name: str,
                                         target_date: str, source_tag: str) -> None:
    """동일 날짜·직원의 기존 [자동] 신청 행을 삭제 (덮어쓰기 보장)."""
    if not (db_filename and employee_name and target_date):
        return
    client, err = get_supabase_client()
    if err or not client:
        return
    try:
        r = client.table("app_work_adjustments").select("id,reason,status")\
            .eq("db_filename", db_filename)\
            .eq("employee_name", employee_name)\
            .eq("target_date", target_date).execute()
        for row in (r.data or []):
            rsn = (row.get("reason") or "")
            if rsn.startswith(source_tag) and (row.get("status") or "pending") != "approved":
                try:
                    client.table("app_work_adjustments").delete().eq("id", int(row["id"])).execute()
                except Exception:
                    pass
        _erp_invalidate_fetch_caches("app_work_adjustments")
    except Exception:
        pass


def _erp_upsert_auto_adjustment(*, db_filename: str, employee_name: str,
                                target_date: str, diff_min: int,
                                std_start_str: str, std_end_str: str,
                                actual_start_str: str, actual_end_str: str,
                                source_tag: str, created_by: str,
                                work_db_filename: str | None = None,
                                work_location_name: str | None = None,
                                user_note: str | None = None) -> tuple[bool, str]:
    """자동 연장(+) 신청 행을 pending 으로 insert. 기존 [자동] 행은 사전 정리.

    - diff > 0: kind='overtime', sign='+' (연장근무)
    - diff <= 0: no-op (단축근무 자동 신청 모드는 v2.1 에서 폐지 — 기존 자동 행만 정리)
    - user_note: 사용자가 직접 입력한 비고 (reason 끝에 ' | 비고: ...' 형식으로 결합)
    """
    diff_min = int(diff_min or 0)
    if diff_min <= 0:
        _erp_delete_existing_auto_adjustment(db_filename, employee_name, target_date, source_tag)
        return True, ""

    _erp_delete_existing_auto_adjustment(db_filename, employee_name, target_date, source_tag)

    minutes_abs = diff_min
    kind = "overtime"
    sign = "+"
    reason = (
        f"{source_tag} 연장 {_erp_fmt_hm(minutes_abs)} "
        f"(표준 {std_start_str}~{std_end_str} → 실제 {actual_start_str}~{actual_end_str})"
    )
    _note_clean = (user_note or "").strip()
    if _note_clean:
        reason = f"{reason} | 비고: {_note_clean}"

    payload = {
        "db_filename": db_filename,
        "employee_name": employee_name,
        "target_date": target_date,
        "kind": kind,
        "sign": sign,
        "minutes": minutes_abs,
        "reason": reason,
        "status": "pending",
        "created_by": created_by,
        "shift_start": actual_start_str + ":00" if len(actual_start_str) == 5 else actual_start_str,
        "shift_end": actual_end_str + ":00" if len(actual_end_str) == 5 else actual_end_str,
        "work_db_filename": work_db_filename,
        "work_location_name": work_location_name,
    }
    ok, e = _erp_insert_row("app_work_adjustments", payload)
    if not ok and ("shift_start" in str(e) or "work_db_filename" in str(e) or "PGRST204" in str(e)):
        # 구 스키마(shift_start/work_db_filename 컬럼 없음) 호환
        payload2 = {k: v for k, v in payload.items()
                    if k not in ("shift_start", "shift_end", "work_db_filename", "work_location_name")}
        ok, e = _erp_insert_row("app_work_adjustments", payload2)
    return ok, e


def _erp_collect_auto_adjustments(*, db_filename: str, employee_name: str,
                                  shifts: list, source_tag: str, created_by: str,
                                  work_db_filename: str | None = None,
                                  work_location_name: str | None = None) -> dict:
    """여러 시프트에 대해 매장 표준 대비 연장(diff>0) 차이를 후보 풀에 적재.

    shifts: [{"shift_date":"YYYY-MM-DD", "shift_start":"HH:MM" or "HH:MM:SS",
              "shift_end":"...", "work_location_name": str | None}]
    연장(diff>0)만 후보 추가. 단축(diff<0)은 기존 자동 행 정리만 하고 건너뜀 (단축근무 신청 모드 폐지).
    반환: {candidates_added:int, errors:list[str]}
    """
    candidates_added = 0
    errors: list[str] = []
    pool = st.session_state.setdefault("_erp_overtime_candidates", [])

    for sh in shifts:
        try:
            d_str = str(sh.get("shift_date") or "")[:10]
            if not d_str:
                continue
            d = date.fromisoformat(d_str)
            ss = _erp_parse_time(sh.get("shift_start"))
            ee = _erp_parse_time(sh.get("shift_end"))
            if not (ss and ee):
                continue
            diff_min, std_min, actual_min = _erp_compute_shift_overage(db_filename, d, ss, ee)
            if std_min == 0:
                continue  # 매장 표준 미설정
            std_s, std_e = _erp_default_times_for_date(db_filename, d)
            std_ss = std_s.strftime("%H:%M")
            std_ee = std_e.strftime("%H:%M")
            act_ss = ss.strftime("%H:%M")
            act_ee = ee.strftime("%H:%M")
            wloc = (sh.get("work_location_name") or work_location_name) or None
            wdb = work_db_filename or db_filename

            # 차이 0이면 기존 자동 행만 정리하고 후보 추가 X
            if diff_min == 0:
                _erp_delete_existing_auto_adjustment(db_filename, employee_name, d_str, source_tag)
                # 기존 후보 중 동일한 항목도 제거
                pool[:] = [c for c in pool
                           if not (c.get("employee_name") == employee_name
                                   and c.get("target_date") == d_str
                                   and c.get("source_tag") == source_tag)]
                continue

            # 단축(diff<0)은 신청 모드를 사용하지 않음: 기존 자동 행만 정리하고 후보 추가 X
            if diff_min < 0:
                _erp_delete_existing_auto_adjustment(db_filename, employee_name, d_str, source_tag)
                pool[:] = [c for c in pool
                           if not (c.get("employee_name") == employee_name
                                   and c.get("target_date") == d_str
                                   and c.get("source_tag") == source_tag)]
                continue

            # 동일 후보 중복 방지 (같은 emp+date+source 만 유지)
            pool[:] = [c for c in pool
                       if not (c.get("employee_name") == employee_name
                               and c.get("target_date") == d_str
                               and c.get("source_tag") == source_tag)]
            pool.append({
                "db_filename": db_filename,
                "employee_name": employee_name,
                "target_date": d_str,
                "diff_min": diff_min,
                "std_start": std_ss, "std_end": std_ee,
                "actual_start": act_ss, "actual_end": act_ee,
                "source_tag": source_tag,
                "created_by": created_by,
                "work_db_filename": wdb,
                "work_location_name": wloc,
            })
            candidates_added += 1
        except Exception as ex:
            errors.append(f"{sh.get('shift_date')}: {ex}")

    return {
        "candidates_added": candidates_added,
        "errors": errors,
    }


def _erp_render_overtime_candidates_ui(*, scope_employee: str | None = None) -> None:
    """저장 후 화면 상단에 표시되는 '연장근무 신청 대기' UI.

    연장(+)만 표시. 사용자가 [✅ 신청]/[❌ 취소] 선택 시 pending 등록
    → 관리자 승인 후 대시보드에 반영.
    scope_employee 지정 시 해당 직원의 후보만 렌더링.
    """
    pool = st.session_state.get("_erp_overtime_candidates") or []
    # 단축근무 신청 모드 폐지: 혹시 세션에 남아있는 음수 후보는 노출하지 않음
    pool = [c for c in pool if int(c.get("diff_min") or 0) > 0]
    if scope_employee:
        pool = [c for c in pool if c.get("employee_name") == scope_employee]
    if not pool:
        return

    st.markdown(
        "<div style='background:#FFF8E1; border-left:4px solid #FB8C00; "
        "padding:12px 16px; border-radius:8px; margin:10px 0;'>"
        f"<b>🔔 연장근무 신청 대기 ({len(pool)}건)</b><br>"
        "<span style='font-size:0.86rem; color:#555;'>다음 일정은 매장 표준 시간보다 길게 근무한 일정입니다. "
        "신청 후 관리자 승인을 거쳐 실제 근무시간에 가산(+) 반영됩니다.</span>"
        "</div>",
        unsafe_allow_html=True,
    )

    _color = "#E65100"

    for idx, cand in enumerate(list(pool)):
        diff_min = int(cand.get("diff_min") or 0)
        _cand_key = f"{cand['employee_name']}_{cand['target_date']}_{cand['source_tag']}"

        cols = st.columns([1.6, 1.3, 2.5, 0.9, 0.9])
        with cols[0]:
            st.markdown(
                f"**{cand['target_date']}** · {cand['employee_name']}<br>"
                f"<span style='color:{_color}; font-weight:600;'>연장근무</span> "
                f"<span style='color:#888; font-size:0.78rem;'>"
                f"표준 {cand['std_start']}~{cand['std_end']} → 실제 {cand['actual_start']}~{cand['actual_end']}"
                f"</span>",
                unsafe_allow_html=True,
            )
        with cols[1]:
            _wloc = cand.get("work_location_name") or "—"
            st.markdown(
                f"<span style='color:{_color}; font-weight:700; font-size:1.15rem;'>"
                f"+{_erp_fmt_hm(abs(diff_min))}</span>"
                f"<br><span style='color:#607D8B; font-size:0.78rem;'>{_wloc}</span>",
                unsafe_allow_html=True,
            )
        with cols[2]:
            _note_key = f"adj_note_{idx}_{_cand_key}"
            user_note = st.text_input(
                "비고",
                value=st.session_state.get(_note_key, ""),
                key=_note_key,
                placeholder="비고 (선택) — 예: 고객 응대 연장 / 본사 회의",
                label_visibility="collapsed",
            )
        with cols[3]:
            if st.button("✅ 신청", key=f"adj_apply_{idx}_{_cand_key}", type="primary"):
                _user_note = (st.session_state.get(_note_key) or "").strip()
                ok, e = _erp_upsert_auto_adjustment(
                    db_filename=cand["db_filename"], employee_name=cand["employee_name"],
                    target_date=cand["target_date"], diff_min=diff_min,
                    std_start_str=cand["std_start"], std_end_str=cand["std_end"],
                    actual_start_str=cand["actual_start"], actual_end_str=cand["actual_end"],
                    source_tag=cand["source_tag"], created_by=cand["created_by"],
                    work_db_filename=cand.get("work_db_filename"),
                    work_location_name=cand.get("work_location_name"),
                    user_note=_user_note,
                )
                if ok:
                    st.session_state["_erp_overtime_candidates"] = [
                        c for c in st.session_state.get("_erp_overtime_candidates", [])
                        if not (c.get("employee_name") == cand["employee_name"]
                                and c.get("target_date") == cand["target_date"]
                                and c.get("source_tag") == cand["source_tag"])
                    ]
                    st.session_state.pop(_note_key, None)
                    flash(f"{cand['target_date']} 연장근무 +{_erp_fmt_hm(abs(diff_min))} 신청 완료 (승인 대기)", "success")
                    st.rerun()
                else:
                    st.error(f"신청 실패: {e}")
        with cols[4]:
            if st.button("❌ 취소", key=f"adj_skip_{idx}_{_cand_key}"):
                st.session_state["_erp_overtime_candidates"] = [
                    c for c in st.session_state.get("_erp_overtime_candidates", [])
                    if not (c.get("employee_name") == cand["employee_name"]
                            and c.get("target_date") == cand["target_date"]
                            and c.get("source_tag") == cand["source_tag"])
                ]
                st.session_state.pop(_note_key, None)
                st.rerun()

    # 일괄 액션
    _ab1, _ab2, _ = st.columns([1.2, 1.2, 5])
    with _ab1:
        if st.button("✅ 모두 신청", key="adj_apply_all", type="primary"):
            _all = list(st.session_state.get("_erp_overtime_candidates") or [])
            ok_n, fail_n = 0, 0
            for _i, c in enumerate(_all):
                if scope_employee and c.get("employee_name") != scope_employee:
                    continue
                _ckey = f"{c['employee_name']}_{c['target_date']}_{c['source_tag']}"
                _note_val = (st.session_state.get(f"adj_note_{_i}_{_ckey}") or "").strip()
                ok, _ = _erp_upsert_auto_adjustment(
                    db_filename=c["db_filename"], employee_name=c["employee_name"],
                    target_date=c["target_date"], diff_min=int(c["diff_min"]),
                    std_start_str=c["std_start"], std_end_str=c["std_end"],
                    actual_start_str=c["actual_start"], actual_end_str=c["actual_end"],
                    source_tag=c["source_tag"], created_by=c["created_by"],
                    work_db_filename=c.get("work_db_filename"),
                    work_location_name=c.get("work_location_name"),
                    user_note=_note_val,
                )
                if ok:
                    ok_n += 1
                else:
                    fail_n += 1
            st.session_state["_erp_overtime_candidates"] = [
                c for c in st.session_state.get("_erp_overtime_candidates", [])
                if scope_employee and c.get("employee_name") != scope_employee
            ]
            flash(f"근무시간 조정 일괄 신청 완료 — 성공 {ok_n}건 / 실패 {fail_n}건 (승인 대기)", "success")
            st.rerun()
    with _ab2:
        if st.button("❌ 모두 취소", key="adj_skip_all"):
            st.session_state["_erp_overtime_candidates"] = [
                c for c in st.session_state.get("_erp_overtime_candidates", [])
                if scope_employee and c.get("employee_name") != scope_employee
            ]
            st.rerun()
    st.markdown("---")


@st.cache_data(ttl=30)
def _erp_list_my_adjustments(db_filename: str, employee_name: str, ym: str) -> list:
    """내 신청 내역 (해당 ym, 최신순)."""
    if not (db_filename and employee_name and ym):
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        y, m = ym.split("-")
        last_day = calendar.monthrange(int(y), int(m))[1]
        start = f"{ym}-01"
        end = f"{ym}-{last_day:02d}"
        r = client.table("app_work_adjustments").select("*")\
            .eq("db_filename", db_filename)\
            .eq("employee_name", employee_name)\
            .gte("target_date", start).lte("target_date", end)\
            .order("target_date", desc=True).execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception:
        return []


@st.cache_data(ttl=30)
def _erp_list_pending_adjustments(db_filename: str) -> list:
    """매장 전체 pending 신청 (관리자 승인 큐)."""
    if not db_filename:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        r = client.table("app_work_adjustments").select("*")\
            .eq("db_filename", db_filename)\
            .eq("status", "pending")\
            .order("created_at", desc=False).execute()
        return (r.data or []) if hasattr(r, "data") else []
    except Exception:
        return []


@st.cache_data(ttl=600)
def _erp_store_admin_names(db_filename: str) -> list:
    """해당 매장 store_admin 직원의 표시명 목록.
    store_admin 본인의 근태 신청은 매장 자가 승인이 아니라 superadmin 승인 대상으로 분기하기 위해 사용."""
    if not db_filename:
        return []
    store_id = _get_supabase_store_by_db_filename(db_filename)
    if not store_id:
        return []
    client, err = get_supabase_client()
    if err or not client:
        return []
    try:
        user_ids = set()
        us = client.table("app_user_stores").select("user_id").eq("store_id", store_id).execute()
        for x in (us.data or []):
            user_ids.add(x["user_id"])
        u = client.table("app_users").select("id").eq("store_id", store_id).execute()
        for x in (u.data or []):
            user_ids.add(x["id"])
        if not user_ids:
            return []
        r = client.table("app_users").select("name, username, role").in_("id", list(user_ids)).execute()
        out = []
        for ud in (r.data or []):
            if str(ud.get("role") or "").strip() != "store_admin":
                continue
            nm = str(ud.get("name") or "").strip()
            un = str(ud.get("username") or "").strip()
            display = nm or _email_local_part(un) or un or None
            if display and display not in out:
                out.append(display)
        return out
    except Exception:
        return []


def _erp_v2_clear_caches():
    """v2 관련 모든 캐시 클리어 — 저장/승인/반려 직후 호출."""
    try:
        _erp_get_monthly_target_row.clear()
        _erp_get_yearly_target_row.clear()
        _erp_list_monthly_targets.clear()
        _erp_list_yearly_targets.clear()
        _erp_list_my_adjustments.clear()
        _erp_list_pending_adjustments.clear()
        _erp_store_admin_names.clear()
    except Exception:
        pass


def render_erp_attendance():
    """ERP 근태 관리: 사전 일정·최소인원·캘린더·근태·시차·연차·월말요약 통합 화면."""
    user = st.session_state.get("current_user") or {}
    role = user.get("role") or "user"
    me_name = _get_current_user_display_name() or (user.get("username") or "")
    current_db = st.session_state.get("current_db")
    today = _today_kst()

    st.markdown('<div class="sticky-header">', unsafe_allow_html=True)
    st.header("🗓️ 근태 관리 (ERP)")

    st.markdown("</div>", unsafe_allow_html=True)

    if role == "superadmin":
        _erp_render_superadmin_view(today)
        return

    if not current_db:
        st.warning("매장 정보를 확인할 수 없습니다. 사이드바에서 매장을 선택해 주세요.")
        return

    # v2 메뉴 (2026-07-03 캘린더 대시보드 통합, 2026-07-04 관리자 메뉴 분리):
    #   store_admin: 7탭 (대시보드[+캘린더] / 정기근무일정 / 추가근무·휴무 신청 / 근무시간 설정 / 신청 승인 / 월말 요약 / 관리자 메뉴)
    #   user:        3탭 (대시보드[+캘린더] / 정기근무일정 / 추가근무·휴무 신청)
    # st.tabs 대신 segmented_control 사용: st.rerun() 호출 후에도 활성 탭 유지
    # (st.tabs는 stateless라 rerun 시 항상 첫 번째 탭으로 리셋되어 저장/수정 후 화면 이탈)
    if role == "store_admin":
        tab_labels = ["대시보드", "정기근무일정", "추가근무·휴무 신청", "근무시간 설정", "신청 승인", "월말 요약", "관리자 메뉴"]
    else:
        tab_labels = ["대시보드", "정기근무일정", "추가근무·휴무 신청"]

    _tab_key = "erp_main_tab_label"
    if _tab_key not in st.session_state or st.session_state[_tab_key] not in tab_labels:
        st.session_state[_tab_key] = tab_labels[0]
    selected_tab = st.segmented_control(
        "메뉴", tab_labels, key=_tab_key, label_visibility="collapsed",
    )
    if not selected_tab:
        selected_tab = tab_labels[0]
    st.markdown("---")

    if selected_tab == "대시보드":
        # 1️⃣ 근태 현황 → 2️⃣ 월별 근무 캘린더 → 3️⃣ 내 신청 내역 순으로 표시
        _erp_tab_dashboard(current_db, role, me_name, today)
        st.divider()
        _erp_tab_calendar(current_db, role, me_name, today)
        if me_name:
            st.divider()
            st.markdown("### 3️⃣ 내 신청 내역")
            _erp_render_my_adj_history(current_db, me_name, today)
    elif role == "store_admin":
        if selected_tab == "정기근무일정":
            _erp_tab_shift_plan(current_db, me_name)
        elif selected_tab == "추가근무·휴무 신청":
            _erp_tab_my_attendance(current_db, role, me_name)
        elif selected_tab == "근무시간 설정":
            _erp_tab_period_targets(current_db, me_name)
        elif selected_tab == "신청 승인":
            _erp_tab_adjustment_approvals(current_db, me_name)
        elif selected_tab == "월말 요약":
            _erp_tab_monthly_summary(current_db, today)
        elif selected_tab == "관리자 메뉴":
            _erp_tab_admin_settings(current_db, me_name, today)
    else:
        if selected_tab == "정기근무일정":
            _erp_tab_shift_plan(current_db, me_name)
        elif selected_tab == "추가근무·휴무 신청":
            _erp_tab_my_attendance(current_db, role, me_name)


# ---------- 대시보드 ----------

def _erp_tab_dashboard(current_db: str, role: str, me_name: str, today: date):
    """근태 관리 첫 화면 대시보드 (연간 breakdown 8카드 + 잔여 연차).

    상단: 공통 필요근무 / (-)휴가류 차감 / (-)포상 차감 / 잔여 필요근무
    하단: (+)정상근무 / (+)연장근무 / (+)단축근무(차감) / 실제 근무시간
    오른쪽: 잔여 연차"""

    # ── 연도 선택기 (디폴트: 올해) ──────────────────────────────
    _year_opts = list(range(today.year - 1, today.year + 2))  # 작년·올해·내년
    _yr_col1, _yr_col2 = st.columns([2, 5])
    with _yr_col1:
        sel_year = st.selectbox(
            "📅 조회 연도",
            _year_opts,
            index=_year_opts.index(today.year),
            key="erp_dash_year",
        )
    with _yr_col2:
        st.markdown(
            f"<div style='padding-top:30px; color:#666; font-size:0.9rem;'>"
            f"📌 <b>{sel_year}년</b> 누계 — 기준일 {today.isoformat()}"
            f"</div>",
            unsafe_allow_html=True,
        )

    st.markdown("### 1️⃣ 근태 현황")

    # ── 데이터 수집 (breakdown) ─────────────────────────────────
    _as_of = today if sel_year == today.year else date(sel_year, 12, 31)
    bd = _erp_compute_yearly_breakdown(current_db, me_name, sel_year, _as_of)

    required_min = int(bd["required_min"])
    required_source = bd.get("required_source") or ("none" if required_min <= 0 else "yearly")
    deductions = bd["deductions"] or {}
    additions  = bd["additions"] or {}
    total_short_adj_min = sum(int(v) for v in deductions.values())  # work_adjustments sign='-' 합

    normal_min   = int(bd["normal_min"])
    overtime_min = int(bd["overtime_min"])
    short_min    = int(bd["short_min"])         # 통합: 지각·조퇴 + 모든 sign='-' 차감
    leave_min    = int(bd["leave_min"])
    shift_normal_min = int(bd.get("shift_normal_min", 0))
    actual_total_min = int(bd["actual_total_min"])

    # 잔여 필요근무 = 공통 − 단축근무 누계 − 실제 근무시간 (캘린더·시프트 반영)
    remaining_required_min = required_min - total_short_adj_min - actual_total_min

    _req_sub = {
        "period": "(근무시간 설정 · 기간 목표)",
        "yearly": "(연간 목표)",
        "none": "⚠️ 미설정",
    }.get(required_source, "⚠️ 미설정")

    # 잔여 연차 + 장기근속 정보
    _leave = _erp_compute_leave_status(current_db, me_name, _as_of)
    _annual_remain_days = _leave["annual_remain"]

    # 장기근속 정보: app_leave_grants에서 hire_date 읽어 근로기준법 계산
    _leave_grant_rows = _erp_fetch_table("app_leave_grants", {
        "home_db_filename": current_db,
        "employee_name": me_name,
        "year": int(sel_year),
    })
    _leave_grant = _leave_grant_rows[0] if _leave_grant_rows else {}
    _hire_date_str = _leave_grant.get("hire_date")
    _legal_info: dict = {}
    if _hire_date_str:
        try:
            _hd = date.fromisoformat(str(_hire_date_str)[:10])
            _legal_info = _erp_calc_legal_leave(_hd, int(sel_year))
        except Exception:
            pass

    # ── 컬럼 요약: 필요 / 실제 / 잔여 / 차감 / 연차 (파스텔) ───
    gap_min = remaining_required_min
    _days_left = int(_leave.get("days_until_year_end") or 0)
    if required_min <= 0:
        _status_txt = "필요근무 미설정"
    elif gap_min > 0:
        _status_txt = f"목표 미달 · 연말 {_days_left}일"
    elif gap_min < 0:
        _status_txt = f"목표 초과 {_erp_fmt_hm(-gap_min)}"
    else:
        _status_txt = "목표 달성"

    _leave_total = _leave["annual_total"]
    _leave_used = _leave["annual_used"]

    def _kpi_card(bg: str, border: str, label: str, value: str, value_color: str) -> str:
        return (
            f"<div style='background:{bg}; border:1px solid {border}; border-radius:14px; "
            f"padding:16px 10px; text-align:center; min-height:108px; "
            f"display:flex; flex-direction:column; align-items:center; justify-content:center;'>"
            f"<div style='font-size:0.78rem; color:#6B7280; font-weight:600; margin-bottom:8px;'>"
            f"{label}</div>"
            f"<div style='font-size:1.85rem; font-weight:800; color:{value_color}; "
            f"line-height:1.1; letter-spacing:-0.02em;'>{value}</div>"
            f"</div>"
        )

    st.markdown("##### 🎯 연간 근무시간 요약")
    c1, c2, c3, c4, c5 = st.columns(5)
    with c1:
        st.markdown(
            _kpi_card("#EAF3FB", "#D0E4F5", "연간 전체 필요근무",
                      _erp_fmt_hm(required_min), "#3B6FA0"),
            unsafe_allow_html=True,
        )
    with c2:
        st.markdown(
            _kpi_card("#EAF7EF", "#C9E8D4", "실제 근무시간",
                      _erp_fmt_hm(actual_total_min), "#3D8B5E"),
            unsafe_allow_html=True,
        )
    with c3:
        st.markdown(
            _kpi_card("#FDECEC", "#F5D0D0", "연간 잔여 필요근무",
                      _erp_fmt_hm(gap_min), "#C45C5C"),
            unsafe_allow_html=True,
        )
    with c4:
        st.markdown(
            _kpi_card("#FFF4E8", "#F0DCC0", "필요근무 차감",
                      _erp_fmt_hm(total_short_adj_min), "#C4843A"),
            unsafe_allow_html=True,
        )
    with c5:
        st.markdown(
            _kpi_card("#F3EEF8", "#DDD0EC", "잔여 연차",
                      f"{_annual_remain_days:g}일", "#8B6BAE"),
            unsafe_allow_html=True,
        )

    # 수식·설명은 박스 밖 작은 글씨
    st.markdown(
        f"<div style='margin:6px 2px 0; color:#8A93A0; font-size:0.78rem; line-height:1.55;'>"
        f"<div>잔여 수식: 필요 {_erp_fmt_hm(required_min)}"
        f" − 차감 {_erp_fmt_hm(total_short_adj_min)}"
        f" − 실제 {_erp_fmt_hm(actual_total_min)}"
        f" = {_erp_fmt_hm(gap_min)}"
        f"{' · ' + _status_txt if _status_txt else ''}</div>"
        f"<div>실제 내역: 정상 {_erp_fmt_hm(normal_min)} · 연장 {_erp_fmt_hm(overtime_min)}"
        f" &nbsp;|&nbsp; 필요 출처: {_req_sub.strip('() ')}"
        f" &nbsp;|&nbsp; 차감: 포상·여름휴가 등"
        f" &nbsp;|&nbsp; 연차: 총 {_leave_total:g}일 중 {_leave_used:g}일 사용</div>"
        f"</div>",
        unsafe_allow_html=True,
    )

    if required_min <= 0:
        st.caption("관리자 [근무시간 설정]에서 기간 목표를 등록해 주세요.")

    if deductions:
        with st.expander("ℹ️ 필요근무 차감 상세 (kind별 분류)", expanded=False):
            for k, v in sorted(deductions.items(), key=lambda x: -x[1]):
                st.markdown(f"- **{k}**: {_erp_fmt_hm(v)}")

    # ── 정상근무 진단 (디버그) ────────────────────────────────────
    with st.expander("🔍 정상근무 내역 상세 (디버그)", expanded=False):
        _dbg_logs       = bd.get("debug_normal_logs") or []
        _dbg_shifts     = bd.get("debug_normal_shifts") or []
        _dbg_null_shift = bd.get("debug_null_shifts") or []
        st.caption(
            f"집계 기간: **{bd.get('period_start')}** ~ **{bd.get('today_cap')}** | "
            f"logs 정상근무 {_erp_fmt_hm(bd.get('normal_min_logs', 0))} + "
            f"시프트 자동 {_erp_fmt_hm(bd.get('shift_normal_min', 0))} = "
            f"**정상근무 {_erp_fmt_hm(normal_min)}** | "
            f"휴게시간: 4h~8h → 30분, 8h 이상 → 60분 차감"
        )
        if _dbg_null_shift:
            st.warning(
                f"⚠️ 시프트 시간 미입력 날짜 {len(_dbg_null_shift)}건 — **매장 기본시간으로 자동 대체** 적용됨: "
                + ", ".join(_dbg_null_shift)
                + "\n\n> 시프트 등록 시 출퇴근 시각을 직접 입력하면 더 정확합니다."
            )
        import pandas as _pd_dbg
        if _dbg_logs or _dbg_shifts:
            _dbg_rows = []
            for _r in _dbg_logs:
                _h_val = float(_r.get("h") or 0)
                _m_total = int(round(_h_val * 60))
                _dbg_rows.append({
                    "날짜": _r.get("date", ""),
                    "유형": _r.get("type", ""),
                    "근무시간": f"{_m_total // 60}h {_m_total % 60:02d}m",
                    "_min": _m_total,
                    "매장": _r.get("store", ""),
                })
            for _r in _dbg_shifts:
                _h_val = float(_r.get("h") or 0)
                _m_total = int(round(_h_val * 60))
                _dbg_rows.append({
                    "날짜": _r.get("date", ""),
                    "유형": _r.get("type", ""),
                    "근무시간": f"{_m_total // 60}h {_m_total % 60:02d}m",
                    "_min": _m_total,
                    "매장": "",
                })
            _dbg_df = _pd_dbg.DataFrame(_dbg_rows).sort_values("날짜")
            _total_min_sum = int(_dbg_df["_min"].sum())
            _total_fmt = f"{_total_min_sum // 60}h {_total_min_sum % 60:02d}m"
            st.markdown(f"**총 {len(_dbg_df)}건 / 합계 {_total_fmt}**")
            # 날짜별 중복 체크
            _dup = _dbg_df.groupby("날짜")["_min"].agg(["count", "sum"]).reset_index()
            _dup_multi = _dup[_dup["count"] > 1]
            if len(_dup_multi) > 0:
                st.warning(f"⚠️ 같은 날짜에 여러 건이 합산된 날: {len(_dup_multi)}일 — 아래 표 확인")
                _dup_multi["합산"] = _dup_multi["sum"].apply(
                    lambda x: f"{int(x) // 60}h {int(x) % 60:02d}m"
                )
                st.dataframe(_dup_multi.rename(columns={"count": "건수"})[["날짜", "건수", "합산"]],
                             width="stretch", hide_index=True)
            st.dataframe(_dbg_df.drop(columns=["_min"]), width="stretch", hide_index=True)
        else:
            st.info("정상근무 내역이 없습니다.")

    if _leave["soak_risk"]:
        st.error(f"🔴 연차 소멸 위험 — 잔여 {_annual_remain_days:g}일 / 연말까지 {_days_left}일 남음. 연차 사용을 서둘러 주세요.")

    if role in ("store_admin", "superadmin"):
        # 관리자 설정(집계 시작일 · 월 목표 근무시간 · 직원 현황)은 상단 '관리자 메뉴' 탭으로 이동함.
        st.info("⚙️ 연간 집계 시작일 · 직원별 월 목표 근무시간 설정 및 직원 현황은 상단 [관리자 메뉴] 탭에서 관리하세요.")

    # ── 대시보드 하단 ─────────────────────────────────────────
    # 내 신청 내역은 캘린더 아래(3번)로 이동 — 아래 render_erp_attendance 에서 렌더


# ---------- 탭: 관리자 메뉴 (설정 모음) ----------

def _erp_tab_admin_settings(current_db: str, me_name: str, today: date):
    """매장 관리자 전용 설정 모음: 연간 집계 시작일 + 직원별 월 목표 근무시간.

    원래 대시보드 하단에 함께 있었지만, 첫 화면 시야를 KPI/캘린더 중심으로 정리하기 위해
    별도 관리자 메뉴 탭으로 이동. 대시보드와 독립된 연도 선택기를 제공한다."""
    role = (st.session_state.get("current_user") or {}).get("role") or "user"
    if role not in ("store_admin", "superadmin"):
        st.warning("매장 관리자 이상만 접근할 수 있습니다.")
        return

    st.subheader("⚙️ 관리자 메뉴")
    st.caption("매장 관리자 전용 설정 화면입니다. 저장 시 대시보드 · 잔여 근무시간 카드에 즉시 반영됩니다.")

    # 연도 선택기 (대시보드와 독립: 관리자가 이번 해와 내년 목표를 함께 관리할 수 있게 함)
    _year_opts = list(range(today.year - 1, today.year + 2))
    _yc1, _yc2 = st.columns([2, 5])
    with _yc1:
        _ytarget_year = st.selectbox(
            "📅 대상 연도",
            _year_opts,
            index=_year_opts.index(today.year),
            key="erp_admin_settings_year",
        )
    with _yc2:
        st.markdown(
            f"<div style='padding-top:30px; color:#666; font-size:0.9rem;'>"
            f"📌 <b>{_ytarget_year}년</b> 설정 대상"
            f"</div>",
            unsafe_allow_html=True,
        )

    # ── 연간 집계 시작일 설정 ─────────────────────────────────────
    st.divider()
    st.markdown("##### 📅 연간 집계 시작일 설정")
    st.caption(
        "집계 시작일을 설정하면 해당 날짜부터 연말(12/31)까지의 근무만 집계됩니다. "
        "예) 2026년 = 2026-06-01 → 6월~12월만 집계. "
        "미설정 시 1월 1일부터 집계됩니다."
    )
    _ytargets_all = _erp_list_yearly_targets(current_db, _ytarget_year)
    _ytarget_map = {r.get("employee_name"): r for r in _ytargets_all}
    _employees_yt = _erp_get_employee_names_for_store(current_db)

    if _employees_yt:
        with st.form("erp_period_start_form"):
            _psd_hdr = st.columns([2, 2, 2])
            _psd_hdr[0].markdown("**직원명**")
            _psd_hdr[1].markdown("**집계 시작일**")
            _psd_hdr[2].markdown("**현재 설정값**")
            _psd_edits: dict[str, date | None] = {}
            for _emp_yt in _employees_yt:
                _yt_row = _ytarget_map.get(_emp_yt) or {}
                _raw = _yt_row.get("period_start_date")
                _cur_psd = None
                if _raw:
                    try:
                        _cur_psd = date.fromisoformat(str(_raw)[:10])
                    except Exception:
                        pass
                _def_psd = _cur_psd or date(_ytarget_year, 1, 1)
                _pc = st.columns([2, 2, 2])
                with _pc[0]:
                    st.markdown(f"**{_emp_yt}**")
                with _pc[1]:
                    _psd_val = st.date_input(
                        "시작일", value=_def_psd,
                        min_value=date(_ytarget_year, 1, 1),
                        max_value=date(_ytarget_year, 12, 31),
                        key=f"psd_{_ytarget_year}_{_emp_yt}",
                        label_visibility="collapsed",
                    )
                with _pc[2]:
                    _disp = _cur_psd.isoformat() if _cur_psd else f"{_ytarget_year}-01-01 (기본값)"
                    st.markdown(f"<span style='color:#666; font-size:0.85rem;'>{_disp}</span>",
                                unsafe_allow_html=True)
                _psd_edits[_emp_yt] = _psd_val

            if st.form_submit_button("💾 집계 시작일 저장", type="primary"):
                _psd_ok, _psd_fail = 0, 0
                for _emp_yt, _psd_v in _psd_edits.items():
                    _yt_row = _ytarget_map.get(_emp_yt)
                    _payload_psd = {"period_start_date": _psd_v.isoformat() if _psd_v else None}
                    if _yt_row and _yt_row.get("id"):
                        _ok_p, _e_p = _erp_update_row(
                            "app_yearly_work_targets", int(_yt_row["id"]), _payload_psd
                        )
                    else:
                        _ok_p, _e_p = _erp_insert_row("app_yearly_work_targets", {
                            "db_filename": current_db,
                            "employee_name": _emp_yt,
                            "year": _ytarget_year,
                            "required_minutes": 0,
                            **_payload_psd,
                        })
                    if _ok_p:
                        _psd_ok += 1
                    else:
                        _psd_fail += 1
                        if "period_start_date" in str(_e_p) or "PGRST204" in str(_e_p):
                            st.error(
                                "⚠️ period_start_date 컬럼이 DB에 없습니다. "
                                "**SUPABASE_YEARLY_TARGET_PERIOD_START.sql** 을 "
                                "Supabase 대시보드 → SQL Editor에서 실행 후 다시 시도해 주세요."
                            )
                            break
                _erp_get_yearly_target_row.clear()
                _erp_list_yearly_targets.clear()
                if _psd_ok and not _psd_fail:
                    flash(f"집계 시작일 저장 완료 ({_psd_ok}명)")
                    st.rerun()
                elif _psd_ok:
                    flash(f"저장 완료 {_psd_ok}명 / 실패 {_psd_fail}명", level="warning")
    else:
        st.info("배정된 직원이 없습니다.")

    # ── 직원별 월 목표 근무시간 설정 ─────────────────────────────
    st.divider()
    st.markdown("##### ⚙️ 직원별 월 목표 근무시간 설정 (연간 기준 자동 계산)")
    st.caption("월 목표를 설정하면 연간 목표(×12)가 자동으로 계산됩니다. 잔여 근무시간 카드에 즉시 반영됩니다.")
    _emp_settings_all = _erp_employee_settings_cached(current_db)
    _emp_map_all = {r.get("employee_name"): r for r in _emp_settings_all}
    _employees_for_setting = _erp_get_employee_names_for_store(current_db)
    if _employees_for_setting:
        _preset_map = {
            "정규직 (월 173h)": 173.0, "단시간 (월 152h)": 152.0,
            "파트타임 (월 130h)": 130.0, "파트타임 (월 108h)": 108.0,
            "파트타임 (월 87h)": 87.0, "파트타임 (월 65h)": 65.0,
            "직접 입력": None,
        }
        _preset_types = list(_preset_map.keys())
        _hdr = st.columns([1.5, 2, 1.5, 1.5, 1.5])
        _hdr[0].markdown("**직원명**")
        _hdr[1].markdown("**유형**")
        _hdr[2].markdown("**월 목표(h)**")
        _hdr[3].markdown("**주 환산**")
        _hdr[4].markdown("**연간 목표**")
        _edits: dict[str, float] = {}
        for _emp in _employees_for_setting:
            _saved = _emp_map_all.get(_emp, {})
            _saved_monthly = _saved.get("monthly_target_hours")
            if _saved_monthly:
                _sh = float(_saved_monthly)
            elif _saved.get("weekly_target_hours"):
                _sh = round(float(_saved["weekly_target_hours"]) * 4.33, 1)
            else:
                _sh = 173.0
            _matched = next(
                (t for t, h in _preset_map.items() if h is not None and abs(h - _sh) < 0.5),
                "직접 입력",
            )
            _rc = st.columns([1.5, 2, 1.5, 1.5, 1.5])
            with _rc[0]:
                st.markdown(f"**{_emp}**")
            with _rc[1]:
                _sel = st.selectbox("유형", _preset_types,
                                    index=_preset_types.index(_matched),
                                    key=f"admin_emp_type_{_emp}",
                                    label_visibility="collapsed")
            with _rc[2]:
                _preset_h = _preset_map.get(_sel)
                _default_h = _preset_h if _preset_h is not None else _sh
                _hval = st.number_input("월 목표(h)", min_value=10.0, max_value=300.0,
                                        value=float(_default_h), step=1.0,
                                        key=f"admin_emp_h_{_emp}",
                                        label_visibility="collapsed",
                                        disabled=(_preset_h is not None))
            with _rc[3]:
                st.markdown(f"<span style='color:#666;'>주 {round(float(_hval)/4.33,1):g}h</span>",
                            unsafe_allow_html=True)
            with _rc[4]:
                st.markdown(f"<span style='color:#1565C0; font-weight:600;'>연 {float(_hval)*12:.0f}h</span>",
                            unsafe_allow_html=True)
            _edits[_emp] = _hval

        if st.button("💾 목표 근무시간 저장", type="primary", key="admin_emp_save"):
            _ok, _fail, _warn_monthly = 0, 0, False
            for _emp, _h in _edits.items():
                _saved = _emp_map_all.get(_emp)
                _row = {
                    "db_filename": current_db,
                    "employee_name": _emp,
                    "monthly_target_hours": float(_h),
                    "weekly_target_hours": round(float(_h) / 4.33, 2),
                    "updated_by": me_name,
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                }
                if _saved and _saved.get("id"):
                    ok, e = _erp_update_row("app_employee_settings", int(_saved["id"]), _row)
                else:
                    ok, e = _erp_insert_row("app_employee_settings", _row)
                if not ok and ("monthly_target_hours" in str(e) or "PGRST204" in str(e)):
                    _row2 = {k: v for k, v in _row.items() if k != "monthly_target_hours"}
                    if _saved and _saved.get("id"):
                        ok, e = _erp_update_row("app_employee_settings", int(_saved["id"]), _row2)
                    else:
                        ok, e = _erp_insert_row("app_employee_settings", _row2)
                    if ok:
                        _warn_monthly = True
                if ok:
                    _ok += 1
                else:
                    _fail += 1
            _erp_employee_settings_cached.clear()
            if _fail == 0:
                if _warn_monthly:
                    flash("저장 완료. monthly_target_hours 컬럼이 없어 주 단위만 저장되었습니다. SUPABASE_APP_ATTENDANCE_COUNTER.sql 을 실행해 주세요.", level="warning")
                else:
                    flash(f"{_ok}명의 목표 근무시간이 저장되었습니다.")
                st.rerun()
            else:
                st.error(f"저장 완료 {_ok}명 / 실패 {_fail}명.")
    else:
        st.info("배정된 직원이 없습니다.")

    # ── 매장 전체 직원 현황 (이번달 시프트 + 연간 누계) ─────────────
    st.divider()
    st.markdown(f"##### 👥 {_ytarget_year}년 매장 전체 직원 현황 (이번달 시프트 + 연간 누계)")
    st.caption("'이번달 근무일·근무(h)·휴무'는 이번달 시프트 기준, '공통 필요·차감·실제·잔여'는 선택한 연도 전체 누계입니다.")
    _adm_today = today
    _adm_last_day = calendar.monthrange(_adm_today.year, _adm_today.month)[1]
    _adm_m_start = date(_adm_today.year, _adm_today.month, 1)
    _adm_m_end   = date(_adm_today.year, _adm_today.month, _adm_last_day)
    _adm_weekdays = sum(
        1 for i in range(1, _adm_last_day + 1)
        if not _erp_is_weekend_or_holiday(date(_adm_today.year, _adm_today.month, i))
    )
    _adm_name_map = _get_app_user_display_name_map()
    def _adm_resolve(raw: str) -> str:
        k = str(raw or "").strip()
        return _adm_name_map.get(k) or _adm_name_map.get(k.lower()) or _email_local_part(k) or k

    _adm_as_of = min(_adm_today, date(int(_ytarget_year), 12, 31))
    _adm_employees = _erp_get_employee_names_for_store(current_db)
    if not _adm_employees:
        st.info("배정된 직원이 없습니다.")
    else:
        _adm_all_shifts: list = []
        try:
            _adm_cli, _adm_e = get_supabase_client()
            if not _adm_e and _adm_cli:
                _adm_r = _adm_cli.table("app_shift_schedules").select(
                    "employee_name, shift_date, shift_start, shift_end, db_filename, work_location_name"
                ).gte("shift_date", _adm_m_start.isoformat()).lte(
                    "shift_date", _adm_m_end.isoformat()
                ).execute()
                _adm_all_shifts = list(_adm_r.data or [])
        except Exception:
            _adm_all_shifts = []

        _adm_rows = []
        for _adm_emp in _adm_employees:
            _adm_emp_shifts = [
                s for s in _adm_all_shifts
                if _adm_resolve(s.get("employee_name") or "") == _adm_emp
            ]
            _adm_date_seen: dict[str, float] = {}
            for _s in _adm_emp_shifts:
                _sd = str(_s.get("shift_date") or "")[:10]
                _sh = _erp_calc_shift_hours(
                    _erp_parse_time(_s.get("shift_start")),
                    _erp_parse_time(_s.get("shift_end")),
                )
                _adm_date_seen[_sd] = _adm_date_seen.get(_sd, 0) + _sh
            _adm_work_days = len(_adm_date_seen)
            _adm_work_h = sum(_adm_date_seen.values())
            _adm_off = max(0, _adm_weekdays - _adm_work_days)
            _adm_bd = _erp_compute_yearly_breakdown(current_db, _adm_emp, _ytarget_year, _adm_as_of)
            _adm_req_min = int(_adm_bd["required_min"])
            _adm_short_min = sum(int(v) for v in (_adm_bd["deductions"] or {}).values())
            _adm_actual_min = int(_adm_bd["actual_total_min"])
            _adm_remain_min = (_adm_req_min - _adm_short_min) - _adm_actual_min
            _adm_leave = _erp_compute_leave_status(current_db, _adm_emp, _adm_as_of)
            _adm_eg_rows = _erp_fetch_table("app_leave_grants", {
                "home_db_filename": current_db, "employee_name": _adm_emp, "year": int(_ytarget_year),
            })
            _adm_eg = _adm_eg_rows[0] if _adm_eg_rows else {}
            _adm_eg_hire = _adm_eg.get("hire_date")
            _adm_eg_legal: dict = {}
            if _adm_eg_hire:
                try:
                    _adm_eg_legal = _erp_calc_legal_leave(date.fromisoformat(str(_adm_eg_hire)[:10]), int(_ytarget_year))
                except Exception:
                    pass
            _adm_rows.append({
                "직원명": _adm_emp,
                "이번달 근무일": _adm_work_days,
                "이번달 근무(h)": round(_adm_work_h, 1),
                "휴무 예정(일)": _adm_off,
                "공통 필요(h)": round(_adm_req_min / 60, 1) if _adm_req_min else "-",
                "단축근무 누계(h)": round(_adm_short_min / 60, 1),
                "실제 근무(h)": round(_adm_actual_min / 60, 1),
                "잔여 필요(h)": _erp_fmt_hm(_adm_remain_min) if _adm_req_min else "미설정",
                "근속연수": f"{_adm_eg_legal.get('years_of_service', '-')}년" if _adm_eg_hire else "미등록",
                "장기근속+": f"+{_adm_eg_legal.get('long_service_extra', 0)}일" if _adm_eg_legal.get("long_service_extra", 0) > 0 else "-",
                "잔여 연차(일)": f"{_adm_leave['annual_remain']:g}",
            })
        import pandas as pd
        st.dataframe(pd.DataFrame(_adm_rows), hide_index=True, width="stretch")


# ---------- 탭 1: 근무 일정 계획 (store_admin) ----------

def _erp_tab_shift_plan(current_db: str, me_name: str):
    st.subheader("📅 정기근무일정 (본인 일정 등록)")
    st.caption("출근일은 ✅ 체크하고, 휴무일은 체크 해제하세요. 시간은 매장 기본값이 자동 입력되며, 필요 시 수정 가능합니다.")
    st.caption("ⓘ 매장 표준 시간보다 길게 근무한 경우 저장 후 '연장근무 신청' 확인 박스가 표시됩니다. (짧게 근무한 경우 별도 신청 절차 없음)")
    role = (st.session_state.get("current_user") or {}).get("role") or "user"

    # 직전 저장에서 발생한 연장근무 후보 확인 UI (본인 한정)
    _erp_render_overtime_candidates_ui(scope_employee=me_name)

    today = _today_kst()

    # ── 기간 선택 ────────────────────────────────────────────────
    import calendar as _cal
    col_a, col_b = st.columns([1, 2])
    with col_a:
        period_mode = st.radio("기간", ["1주", "2주", "1개월"], horizontal=True, index=2, key="erp_shift_period")
    with col_b:
        if period_mode == "1개월":
            # 월 단위: 기본값은 이번 달 1일, 선택한 날짜의 해당 월 전체를 표시
            month_first = today.replace(day=1)
            base_date = st.date_input("시작일", value=month_first, key="erp_shift_base_month")
            _last_day = _cal.monthrange(base_date.year, base_date.month)[1]
            period_start = base_date.replace(day=1)
            period_end   = base_date.replace(day=_last_day)
            date_list = [period_start + timedelta(days=i) for i in range((period_end - period_start).days + 1)]
        else:
            base_date = st.date_input("시작일", value=today, key="erp_shift_base_date")
            days_n = 7 if period_mode == "1주" else 14
            date_list = [base_date + timedelta(days=i) for i in range(days_n)]

    employees = _erp_get_employee_names_for_store(current_db)
    if not employees:
        st.info("이 매장에 배정된 직원이 없습니다. 먼저 [직원 관리]에서 직원을 등록·배정해 주세요.")
        return

    existing = _erp_fetch_range("app_shift_schedules", "db_filename", current_db,
                                "shift_date", date_list[0], date_list[-1])
    existing_by_key = {}
    for row in existing:
        key = (str(row.get("employee_name") or ""), str(row.get("shift_date") or "")[:10])
        existing_by_key[key] = row
    # 같은 날짜에 중복 저장된 과거 행까지 모두 모아 둔다(별칭 기준). 저장 시 overwrite + 중복 정리에 사용.
    _my_aliases = set(_get_current_user_employee_aliases(me_name))
    existing_rows_by_date: dict[str, list] = {}
    for row in existing:
        if str(row.get("employee_name") or "").strip() in _my_aliases:
            existing_rows_by_date.setdefault(str(row.get("shift_date") or "")[:10], []).append(row)

    # ── 입력 영역 ────────────────────────────────────────────────
    st.markdown(f"##### ✏️ 내 근무 일정 — **{me_name}**")

    # 매장 선택 (폼 외부)
    _sp_stores_df = get_supabase_stores_dataframe_cached()
    _sp_store_opts: list = []
    if _sp_stores_df is not None and len(_sp_stores_df) > 0:
        for _, _sr in _sp_stores_df.iterrows():
            _sp_store_opts.append((_sr["store_name"], _sr["db_filename"]))
    _sp_store_opts.append(("기타 (외부/행사)", None))
    _sp_store_labels = [s[0] for s in _sp_store_opts]
    _sp_home_idx = next((i for i, s in enumerate(_sp_store_opts) if s[1] == current_db), 0)

    msc1, msc2 = st.columns([1, 2])
    with msc1:
        _sp_sel_label = st.selectbox(
            "📍 근무매장",
            _sp_store_labels,
            index=_sp_home_idx,
            key="erp_shift_work_store",
            help="실제로 근무한 매장을 선택. 소속과 다를 수 있으며, 외부 행사는 '기타 (외부/행사)' 선택.",
        )
    with msc2:
        loc_input = st.text_input(
            "근무 장소 상세 (선택)", value="",
            key="erp_shift_loc",
            placeholder="예: 롯데백화점 행사장 / 3층 팝업스토어",
        )
    _sp_sel_idx = _sp_store_labels.index(_sp_sel_label)
    _sp_work_db = _sp_store_opts[_sp_sel_idx][1]

    # 매장이 변경되면 위젯 키만 비워서 다음 렌더링에서 해당 매장 기존 데이터로 재채움
    # (False로 강제 설정하면 has_existing=True인 날짜의 기존 데이터를 무시하게 됨)
    _sp_prev_store_key = "erp_shift_work_store_prev"
    if st.session_state.get(_sp_prev_store_key) != _sp_sel_label:
        for _d in date_list:
            st.session_state.pop(f"sp_chk_{_d.isoformat()}", None)
            st.session_state.pop(f"sp_start_{_d.isoformat()}", None)
            st.session_state.pop(f"sp_end_{_d.isoformat()}", None)
        st.session_state[_sp_prev_store_key] = _sp_sel_label

    # 선택한 근무매장에 해당하는 기존 일정만 existing_by_key/existing_rows_by_date 에 담는다
    # (입력 모드와 수정 모드의 표시 일관성 확보 — 근무매장 기준으로 보여줌)
    _known_store_names_sp = set(_sp_store_labels) - {"기타 (외부/행사)"}
    _filtered_existing: list = []
    for _row in existing:
        _wloc = (_row.get("work_location_name") or "").strip()
        if _sp_work_db is None:
            # 기타 (외부/행사): work_location_name 이 등록 매장명 목록에 없는 것
            if _wloc and _wloc not in _known_store_names_sp:
                _filtered_existing.append(_row)
        elif _sp_work_db == current_db:
            # 소속 매장: work_location_name 이 비어있거나 == 소속매장명
            if not _wloc or _wloc == _sp_sel_label:
                _filtered_existing.append(_row)
        else:
            # 타 매장 지원 근무: work_location_name == 선택 매장명
            if _wloc == _sp_sel_label:
                _filtered_existing.append(_row)
    existing_by_key = {}
    for _row in _filtered_existing:
        _k = (str(_row.get("employee_name") or ""), str(_row.get("shift_date") or "")[:10])
        existing_by_key[_k] = _row
    existing_rows_by_date = {}
    for _row in _filtered_existing:
        if str(_row.get("employee_name") or "").strip() in _my_aliases:
            existing_rows_by_date.setdefault(str(_row.get("shift_date") or "")[:10], []).append(_row)

    # 일별 체크박스 + 시간 입력 (테이블 형태)
    with st.container(border=True):
        hdr = st.columns([1.2, 0.6, 1.2, 1.2, 1.4])
        with hdr[0]:
            st.markdown("**날짜**")
        with hdr[1]:
            st.markdown("**출근**")
        with hdr[2]:
            st.markdown("**출근시각**")
        with hdr[3]:
            st.markdown("**퇴근시각**")
        with hdr[4]:
            st.markdown("**근무시간**")
        st.markdown("<hr style='margin:4px 0;'/>", unsafe_allow_html=True)

        edits = {}
        for d in date_list:
            existing_row = _erp_lookup_existing_shift(existing_by_key, me_name, d.isoformat())
            has_existing = bool(existing_row and existing_row.get("shift_start") and existing_row.get("shift_end"))
            d_std_s, d_std_e = _erp_default_times_for_date(current_db, d)

            ex_start = _erp_parse_time(existing_row.get("shift_start")) if existing_row else None
            ex_end = _erp_parse_time(existing_row.get("shift_end")) if existing_row else None
            init_start = ex_start or d_std_s
            init_end = ex_end or d_std_e

            row = st.columns([1.2, 0.6, 1.2, 1.2, 1.4])
            is_we = _erp_is_weekend_or_holiday(d)
            is_holiday_weekday = (d in _ERP_KR_HOLIDAYS and d.weekday() < 5)
            label_color = "color:#E53935;" if (d.weekday() == 6 or d in _ERP_KR_HOLIDAYS) else \
                          ("color:#1565C0;" if d.weekday() == 5 else "")
            hol_mark = " 🔴" if is_holiday_weekday else ("🟥" if is_we else "")
            with row[0]:
                st.markdown(
                    f"<span style='{label_color} font-weight:600;'>"
                    f"{d.month}/{d.day} ({_ERP_DOW_LABELS[d.weekday()]}){hol_mark}</span>",
                    unsafe_allow_html=True,
                )
            with row[1]:
                checked = st.checkbox(
                    "출근", value=has_existing,
                    key=f"sp_chk_{d.isoformat()}",
                    label_visibility="collapsed",
                )
            with row[2]:
                if checked:
                    t_s = _erp_time_input_30min(
                        "출근시각", value=init_start,
                        key=f"sp_start_{d.isoformat()}",
                        label_visibility="collapsed",
                    )
                else:
                    st.markdown("<span style='color:#999;'>— 휴무 —</span>", unsafe_allow_html=True)
                    t_s = None
            with row[3]:
                if checked:
                    t_e = _erp_time_input_30min(
                        "퇴근시각", value=init_end,
                        key=f"sp_end_{d.isoformat()}",
                        label_visibility="collapsed",
                    )
                else:
                    t_e = None
            with row[4]:
                if checked and t_s and t_e:
                    _raw_h = ((t_e.hour * 60 + t_e.minute)
                              - (t_s.hour * 60 + t_s.minute)) / 60.0
                    _net_h = _erp_calc_shift_hours(t_s, t_e)
                    _brk = max(0.0, _raw_h - _net_h)
                    st.markdown(
                        f"<span style='color:#2E7D32;'>{_net_h:.1f}h</span>"
                        f" <span style='color:#888;font-size:0.85em;'>(휴게 -{_brk:.1f}h)</span>",
                        unsafe_allow_html=True,
                    )
                else:
                    st.markdown("<span style='color:#bbb;'>-</span>", unsafe_allow_html=True)
            edits[d.isoformat()] = (checked, t_s, t_e)

    # 저장 버튼
    sbtn_c1, sbtn_c2 = st.columns([1, 4])
    with sbtn_c1:
        submitted = st.button("💾 내 일정 저장", type="primary", key="erp_shift_save")
    with sbtn_c2:
        st.caption("체크된 날짜는 등록·덮어쓰기되고, 체크 해제된 날짜의 기존 일정은 삭제됩니다. 저장 후 완료 알림이 표시됩니다.")

    if submitted:
        # 타 매장 중복 시간대 사전 검사
        _cross_conflicts = _erp_check_cross_store_conflicts(me_name, current_db, edits)
        if _cross_conflicts:
            st.error("⛔ 타 매장 일정과 시간이 겹쳐 저장할 수 없습니다:\n\n" + "\n\n".join(_cross_conflicts))
            return

        planned_by_date: dict[date, list] = {}
        # (existing_id|None, new_row) 튜플 + 중복정리 대상 id 목록
        new_rows: list = []          # 신규 INSERT
        updates: list = []           # (id, patch) — 같은 날짜 기존행 overwrite
        delete_ids: list = []        # 체크 해제(휴무)된 날짜 삭제
        dedup_ids: list = []         # 같은 날짜에 2건 이상 있던 중복행 정리
        for d_str, (chk, t1, t2) in edits.items():
            d = datetime.fromisoformat(d_str).date()
            _ex_rows = existing_rows_by_date.get(d_str, [])
            if not chk:
                # 휴무: 해당 날짜 내 모든 기존행 삭제
                for _er in _ex_rows:
                    delete_ids.append(int(_er["id"]))
                continue
            if not t1 or not t2:
                st.error(f"⛔ {d_str}: 출근/퇴근 시각이 비어 있습니다.")
                return
            if (t1.hour * 60 + t1.minute) >= (t2.hour * 60 + t2.minute):
                st.error(f"⛔ {d_str}: 퇴근 시각이 출근 시각보다 빠를 수 없습니다.")
                return
            planned_by_date.setdefault(d, []).append({
                "employee_name": me_name,
                "shift_start": t1.strftime("%H:%M:%S"),
                "shift_end": t2.strftime("%H:%M:%S"),
            })
            _loc_val = (loc_input or "").strip()
            if not _loc_val:
                if _sp_work_db is None:
                    _loc_val = "기타 (외부/행사)"
                elif _sp_work_db != current_db:
                    _loc_val = _sp_sel_label
                else:
                    _loc_val = (_ex_rows[0].get("work_location_name") if _ex_rows else None) or ""
            new_row = {
                "db_filename": current_db,
                "employee_name": me_name,
                "shift_date": d_str,
                "shift_start": t1.strftime("%H:%M:%S"),
                "shift_end": t2.strftime("%H:%M:%S"),
                "work_location_name": _loc_val or None,
                "created_by": me_name,
            }
            if _ex_rows:
                # 같은 날짜 기존행이 있으면 첫 행은 overwrite, 나머지(중복)는 삭제
                updates.append((int(_ex_rows[0]["id"]), new_row))
                for _dup in _ex_rows[1:]:
                    dedup_ids.append(int(_dup["id"]))
            else:
                new_rows.append(new_row)

        violations = _erp_validate_shifts_against_rules(current_db, planned_by_date)
        violation_note = ""
        if violations:
            violation_note = f" ⚠️ 최소 인원 미달 {len(violations)}건(저장됨, 캘린더에 경고 표시)."

        ok_n, ow_n, err_n, del_n = 0, 0, 0, 0
        err_msgs = []
        for row in new_rows:
            ok, e = _erp_insert_row("app_shift_schedules", row)
            if ok:
                ok_n += 1
            else:
                err_n += 1
                err_msgs.append(f"추가 실패 ({row['shift_date']}): {e}")
        for rid, patch in updates:
            ok, e = _erp_update_row("app_shift_schedules", rid, patch)
            if ok:
                ow_n += 1
            else:
                err_n += 1
                err_msgs.append(f"덮어쓰기 실패 ({patch['shift_date']}): {e}")
        for rid in delete_ids:
            _erp_delete_row("app_shift_schedules", rid)
            del_n += 1
        # 같은 날짜 중복행 정리(overwrite 외 잔여분 제거)
        for rid in dedup_ids:
            _erp_delete_row("app_shift_schedules", rid)

        if err_n == 0:
            _dup_note = f" 중복 {len(dedup_ids)}건 정리." if dedup_ids else ""
            flash(
                f"근무 일정 저장 완료 — 신규 {ok_n}건 · 덮어쓰기 {ow_n}건 · 휴무 삭제 {del_n}건."
                f"{_dup_note}{violation_note}",
                level="success",
            )
        else:
            flash(
                f"일부 저장 실패 — 성공 {ok_n + ow_n}건 / 실패 {err_n}건 / 삭제 {del_n}건. "
                + " / ".join(err_msgs[:3]),
                level="error",
            )

        # ── 매장 표준 대비 차이 자동 보정 처리 ─────────────────────
        # 저장된 모든 시프트(신규+덮어쓰기)를 모아 표준과 비교
        _all_saved_shifts: list = []
        for r in new_rows:
            _all_saved_shifts.append(r)
        for _rid, _patch in updates:
            _all_saved_shifts.append(_patch)

        _adj_db = _sp_work_db or current_db
        if _all_saved_shifts and _adj_db:
            _result = _erp_collect_auto_adjustments(
                db_filename=_adj_db,
                employee_name=me_name,
                shifts=_all_saved_shifts,
                source_tag="[자동-정기근무]",
                created_by=me_name,
                work_db_filename=_adj_db,
                work_location_name=(loc_input or None),
            )
            if _result["candidates_added"]:
                flash(
                    f"⏱️ 매장 표준 시간보다 길게 근무한 일정 {_result['candidates_added']}건 — 상단의 [연장근무 신청 대기]에서 확인 후 신청해 주세요.",
                    level="warning",
                )
            if _result["errors"]:
                flash("일부 자동 보정 등록 실패: " + " / ".join(_result["errors"][:3]), level="error")
        st.rerun()



# ---------- 탭 2: 최소 근무 인원 규칙 설정 (store_admin) ----------

def _erp_tab_staffing_rules(current_db: str, me_name: str):
    st.subheader("👥 매장 근무 기준 설정")

    _store_display_name = _get_store_name_by_db(current_db) if current_db else "기타"
    _is_gita_store = not current_db or "기타" in _store_display_name
    # 매장별 호출 시 위젯 키 충돌 방지용 접두어
    _kp = (current_db or "none").replace(".", "_").replace("/", "_")

    # ── 기본 근무시간 (주중 / 주말·공휴일) ─────────────────────
    st.markdown("##### 🕘 기본 근무시간 설정")
    st.caption("매장 표준 출퇴근 시각을 주중 / 주말·공휴일로 나누어 설정합니다. 근태 입력 폼에 자동 적용됩니다.")
    cur_hours = _erp_get_store_hours(current_db)
    existing_hours = _erp_store_hours_cached(current_db)
    with st.form(f"erp_store_hours_form_{_kp}", clear_on_submit=False):
        hc = st.columns(4)
        with hc[0]:
            wd_s = _erp_time_input_30min("주중 출근", value=cur_hours["weekday_start"], key=f"erp_sh_wd_s_{_kp}")
        with hc[1]:
            wd_e = _erp_time_input_30min("주중 퇴근", value=cur_hours["weekday_end"], key=f"erp_sh_wd_e_{_kp}")
        with hc[2]:
            we_s = _erp_time_input_30min("주말/공휴일 출근", value=cur_hours["weekend_start"], key=f"erp_sh_we_s_{_kp}")
        with hc[3]:
            we_e = _erp_time_input_30min("주말/공휴일 퇴근", value=cur_hours["weekend_end"], key=f"erp_sh_we_e_{_kp}")
        sh_submit = st.form_submit_button("💾 기본 근무시간 저장", type="primary")
    if sh_submit:
        if wd_e <= wd_s or we_e <= we_s:
            st.error("퇴근 시각이 출근 시각보다 늦어야 합니다.")
        else:
            row = {
                "db_filename": current_db,
                "weekday_start": wd_s.strftime("%H:%M:%S"),
                "weekday_end": wd_e.strftime("%H:%M:%S"),
                "weekend_start": we_s.strftime("%H:%M:%S"),
                "weekend_end": we_e.strftime("%H:%M:%S"),
                "updated_by": me_name,
                "updated_at": datetime.now(timezone.utc).isoformat(),
            }
            if existing_hours:
                ok, err = _erp_update_row("app_store_hours", int(existing_hours[0]["id"]), row)
            else:
                ok, err = _erp_insert_row("app_store_hours", row)
            if ok:
                _erp_store_hours_cached.clear()
                notify("기본 근무시간이 저장되었습니다.")
            else:
                notify(f"저장 실패: {err}", level="error")

    st.divider()
    if _is_gita_store:
        st.info("기타(외부/행사) 매장은 최소 근무 인원 규칙을 설정하지 않습니다.")
    else:
        st.markdown("##### 🧑‍🤝‍🧑 시간대별 최소 근무 인원 (요일별)")
        st.caption("주중(월~금)과 주말·공휴일(토·일)로 나누어 시간대별 최소·적정 근무 인원을 설정합니다. 근무 일정 저장 시 자동으로 검증됩니다.")

        # 캐시된 조회 사용 (매 위젯 조작마다 Supabase 호출 방지)
        rules = _erp_staffing_rules_cached(current_db)

        # (slot_start, slot_end) 기준 그룹핑: 동일 슬롯은 대표 rule 1개 + 관련 id 전체 수집
        def _group_slots(rule_list: list) -> list:
            slot_map: dict = {}
            for r in sorted(rule_list, key=lambda x: str(x.get("slot_start") or "")):
                key = (str(r.get("slot_start") or "")[:5], str(r.get("slot_end") or "")[:5])
                if key not in slot_map:
                    slot_map[key] = {"rule": r, "ids": [int(r["id"])]}
                else:
                    slot_map[key]["ids"].append(int(r["id"]))
            return list(slot_map.values())

        _wd_rules = [r for r in rules if int(r.get("day_of_week") or 0) <= 4]
        _we_rules = [r for r in rules if int(r.get("day_of_week") or 0) >= 5]
        wd_slots = _group_slots(_wd_rules)
        we_slots = _group_slots(_we_rules)

        def _render_slot_section(slots, form_key, dow_targets, label):
            """slots: _group_slots 결과, dow_targets: 저장 대상 day_of_week 리스트"""
            _edit_key = f"erp_rule_edit_{form_key}"  # session_state: 현재 수정 중인 rule['id']
            if slots:
                hdr = st.columns([2, 2, 2, 1])
                hdr[0].markdown("**시간대**")
                hdr[1].markdown("**최소 인원**")
                hdr[2].markdown("**적정 인원**")
                for slot_info in slots:
                    rule = slot_info["rule"]
                    all_ids = slot_info["ids"]
                    rid = rule["id"]
                    _slot_label = f"{str(rule.get('slot_start') or '')[:5]} ~ {str(rule.get('slot_end') or '')[:5]}"
                    _cur_min = int(rule.get("min_staff") or 1)
                    _cur_opt = int(rule.get("optimal_staff") or 0)

                    if st.session_state.get(_edit_key) == rid:
                        # ── 인라인 수정 폼
                        with st.container(border=True):
                            st.markdown(f"**✏️ {_slot_label} 수정**")
                            _ea, _eb, _ec, _ed = st.columns([2, 2, 1, 1])
                            with _ea:
                                st.text(_slot_label)
                            with _eb:
                                _new_min = st.number_input(
                                    "최소 인원", min_value=0, max_value=20,
                                    value=_cur_min, step=1,
                                    key=f"erp_rule_edit_min_{rid}",
                                )
                            with _ec:
                                _new_opt = st.number_input(
                                    "적정 인원", min_value=0, max_value=20,
                                    value=_cur_opt, step=1,
                                    help="0이면 미설정",
                                    key=f"erp_rule_edit_opt_{rid}",
                                )
                            with _ed:
                                _sa, _sb = st.columns(2)
                                with _sa:
                                    if st.button("저장", key=f"erp_rule_save_{rid}",
                                                 type="primary", width="stretch"):
                                        patch = {
                                            "min_staff": int(_new_min),
                                            "optimal_staff": int(_new_opt) if _new_opt else None,
                                        }
                                        all_ok = True
                                        for _uid in all_ids:
                                            ok, err = _erp_update_row("app_staffing_rules", _uid, patch)
                                            if not ok:
                                                st.error(f"저장 실패: {err}")
                                                all_ok = False
                                                break
                                        if all_ok:
                                            st.session_state.pop(_edit_key, None)
                                            _erp_staffing_rules_cached.clear()
                                            notify(f"{label} {_slot_label} 규칙이 수정되었습니다.")
                                            st.rerun()
                                with _sb:
                                    if st.button("취소", key=f"erp_rule_cancel_{rid}",
                                                 width="stretch"):
                                        st.session_state.pop(_edit_key, None)
                                        st.rerun()
                    else:
                        # ── 일반 표시 행 (버튼을 HTML로 렌더링해 한 줄 유지)
                        rc = st.columns([2, 2, 2, 1])
                        with rc[0]:
                            st.text(_slot_label)
                        with rc[1]:
                            st.text(f"최소 {_cur_min}명" if _cur_min else "제한 없음")
                        with rc[2]:
                            st.text(f"적정 {_cur_opt}명" if _cur_opt else "미설정")
                        with rc[3]:
                            _btn_col_a, _btn_col_b = st.columns(2)
                            with _btn_col_a:
                                if st.button("수정", key=f"erp_rule_edit_btn_{form_key}_{rid}",
                                             width="stretch"):
                                    st.session_state[_edit_key] = rid
                                    st.rerun()
                            with _btn_col_b:
                                if st.button("삭제", key=f"erp_rule_del_{form_key}_{rid}",
                                             width="stretch"):
                                    for _did in all_ids:
                                        _erp_delete_row("app_staffing_rules", _did)
                                    st.session_state.pop(_edit_key, None)
                                    _erp_staffing_rules_cached.clear()
                                    notify(f"{label} 규칙이 삭제되었습니다.")
                                    st.rerun()
            else:
                st.info(f"설정된 {label} 규칙이 없습니다.")

            with st.form(f"erp_rule_add_{form_key}", clear_on_submit=False):
                fc = st.columns([1.2, 1.2, 1, 1, 1])
                with fc[0]:
                    s_t = _erp_time_input_30min("시작", value=dt_time(9, 0), key=f"erp_rule_s_{form_key}")
                with fc[1]:
                    e_t = _erp_time_input_30min("종료", value=dt_time(18, 0), key=f"erp_rule_e_{form_key}")
                with fc[2]:
                    n = st.number_input("최소 인원", min_value=0, max_value=20, value=1, step=1, key=f"erp_rule_n_{form_key}")
                with fc[3]:
                    opt_n = st.number_input("적정 인원", min_value=0, max_value=20, value=0, step=1,
                                            help="0이면 미설정", key=f"erp_rule_opt_{form_key}")
                with fc[4]:
                    add = st.form_submit_button("➕ 추가")
                if add:
                    if e_t <= s_t:
                        st.error("종료 시각이 시작 시각보다 늦어야 합니다.")
                    else:
                        all_ok = True
                        for _dow in dow_targets:
                            ok, err = _erp_insert_row("app_staffing_rules", {
                                "db_filename": current_db,
                                "day_of_week": _dow,
                                "slot_start": s_t.strftime("%H:%M:%S"),
                                "slot_end": e_t.strftime("%H:%M:%S"),
                                "min_staff": int(n),
                                "optimal_staff": int(opt_n) if opt_n else None,
                                "created_by": me_name,
                            })
                            if not ok:
                                st.error(f"추가 실패: {err}")
                                all_ok = False
                                break
                        if all_ok:
                            _erp_staffing_rules_cached.clear()
                            notify(f"{label} 규칙이 추가되었습니다.")
                            st.rerun()

        wd_col, we_col = st.columns(2)
        with wd_col:
            st.markdown("**🗓️ 주중 (월 ~ 금)**")
            _render_slot_section(wd_slots, f"wd_{_kp}", list(range(5)), "주중")
        with we_col:
            st.markdown("**🏖️ 주말·공휴일 (토·일)**")
            _render_slot_section(we_slots, f"we_{_kp}", [5, 6], "주말·공휴일")

    # ── 매장 공용 일정 (메모/표시 전용) ───────────────────────────
    st.divider()
    st.markdown("##### 📌 매장 공용 일정 (회의·이벤트 등 메모)")
    st.caption("매장 전체에 적용되는 일정을 등록합니다. 캘린더 상단에 배지로 표시되며, 개인 근무시간 계산에는 영향이 없습니다.")

    _today = _today_kst()
    _se_ym_sk = f"erp_se_ym_{_kp}"
    se_ym = st.session_state.get(_se_ym_sk, _today.strftime("%Y-%m"))
    sec_y, sec_m = (int(x) for x in se_ym.split("-"))
    cy1, cy2 = st.columns([1, 4])
    with cy1:
        _new_ym = st.text_input("조회 월(YYYY-MM)", value=se_ym, key=f"erp_se_ym_input_{_kp}")
        if _new_ym != se_ym:
            try:
                _y, _m = (int(x) for x in _new_ym.split("-"))
                st.session_state[_se_ym_sk] = _new_ym
                sec_y, sec_m = _y, _m
                se_ym = _new_ym
            except Exception:
                st.warning("YYYY-MM 형식으로 입력해 주세요.")
    _events = _erp_store_events_cached(current_db, se_ym)
    _editing_id = st.session_state.get("se_editing_id")

    def _render_store_event_edit_form(ev: dict) -> None:
        """매장 공용 일정 수정 팝업 UI. 저장/취소 시 se_editing_id 초기화 후 rerun."""
        _ev_id = int(ev["id"])
        _ev_start = str(ev.get("event_date") or "")[:10]
        _ev_end = str(ev.get("end_date") or "")[:10] if ev.get("end_date") else ""
        try:
            _cur_start = date.fromisoformat(_ev_start)
        except Exception:
            _cur_start = _today
        try:
            _cur_end = date.fromisoformat(_ev_end) if _ev_end else _cur_start
        except Exception:
            _cur_end = _cur_start
        _cur_st_s = str(ev.get("start_time") or "")[:5]
        _cur_et_s = str(ev.get("end_time") or "")[:5]
        _is_multi_cur = bool(_ev_end) and (_ev_end != _ev_start)
        _has_time_cur = bool(_cur_st_s and _cur_et_s)

        _rc1, _rc2 = st.columns([1, 1])
        with _rc1:
            _edit_span = st.radio(
                "기간 유형", ["하루", "여러 날"],
                index=1 if _is_multi_cur else 0,
                horizontal=True, key=f"se_edit_span_{_ev_id}",
            )
        with _rc2:
            _edit_time_mode = st.radio(
                "시간 유형", ["종일", "시간대 지정"],
                index=1 if _has_time_cur else 0,
                horizontal=True, key=f"se_edit_time_mode_{_ev_id}",
            )

        with st.form(f"se_edit_form_{_ev_id}", clear_on_submit=False):
            if _edit_span == "하루":
                _new_start = st.date_input("날짜", value=_cur_start, key=f"se_edit_dt_{_ev_id}")
                _new_title = st.text_input("제목", value=ev.get("title") or "", key=f"se_edit_title_{_ev_id}")
                _new_end = _new_start
            else:
                _ec1a, _ec1b = st.columns(2)
                with _ec1a:
                    _new_start = st.date_input("시작일", value=_cur_start, key=f"se_edit_dt_s_{_ev_id}")
                with _ec1b:
                    _new_end = st.date_input(
                        "종료일",
                        value=_cur_end if _cur_end >= _cur_start else _cur_start,
                        key=f"se_edit_dt_e_{_ev_id}",
                    )
                _new_title = st.text_input("제목", value=ev.get("title") or "", key=f"se_edit_title_m_{_ev_id}")

            if _edit_time_mode == "시간대 지정":
                try:
                    _st_default = dt_time(int(_cur_st_s.split(":")[0]), int(_cur_st_s.split(":")[1])) if _cur_st_s else dt_time(18, 0)
                except Exception:
                    _st_default = dt_time(18, 0)
                try:
                    _et_default = dt_time(int(_cur_et_s.split(":")[0]), int(_cur_et_s.split(":")[1])) if _cur_et_s else dt_time(20, 0)
                except Exception:
                    _et_default = dt_time(20, 0)
                _ec4, _ec5 = st.columns(2)
                with _ec4:
                    _new_st_t = _erp_time_input_30min("시작 시각", value=_st_default, key=f"se_edit_st_{_ev_id}")
                with _ec5:
                    _new_et_t = _erp_time_input_30min("종료 시각", value=_et_default, key=f"se_edit_et_{_ev_id}")
                _new_has_time = True
            else:
                _new_st_t = None
                _new_et_t = None
                _new_has_time = False

            _new_note = st.text_input("메모 (선택)", value=ev.get("note") or "", key=f"se_edit_note_{_ev_id}")

            _bc1, _bc2 = st.columns([1, 1])
            with _bc1:
                _save_btn = st.form_submit_button("💾 저장", type="primary", width="stretch")
            with _bc2:
                _cancel_btn = st.form_submit_button("취소", width="stretch")

        if _cancel_btn:
            st.session_state.pop("se_editing_id", None)
            st.rerun()
        if _save_btn:
            if not (_new_title or "").strip():
                st.error("제목을 입력해 주세요.")
            elif _new_end < _new_start:
                st.error("종료일이 시작일보다 빠를 수 없습니다.")
            elif _new_has_time and (_new_et_t.hour * 60 + _new_et_t.minute) <= (_new_st_t.hour * 60 + _new_st_t.minute):
                st.error("종료 시각이 시작 시각보다 늦어야 합니다.")
            else:
                _is_multi_new = (_new_end != _new_start)
                _patch = {
                    "event_date": _new_start.isoformat(),
                    "end_date": _new_end.isoformat() if _is_multi_new else None,
                    "title": _new_title.strip(),
                    "start_time": _new_st_t.strftime("%H:%M:%S") if _new_has_time else None,
                    "end_time": _new_et_t.strftime("%H:%M:%S") if _new_has_time else None,
                    "note": (_new_note or "").strip() or None,
                }
                ok, e = _erp_update_row("app_store_events", _ev_id, _patch)
                if not ok and ("end_date" in str(e) or "PGRST204" in str(e) or "schema cache" in str(e).lower()):
                    _patch_legacy = {k: v for k, v in _patch.items() if k != "end_date"}
                    ok, e = _erp_update_row("app_store_events", _ev_id, _patch_legacy)
                if ok:
                    _erp_store_events_cached.clear()
                    st.session_state.pop("se_editing_id", None)
                    flash("매장 공용 일정이 수정되었습니다.")
                    st.rerun()
                else:
                    st.error(f"수정 실패: {e}")

    if _events:
        st.caption(f"등록된 일정 {len(_events)}건")
        for _ev in _events:
            _ev_id = int(_ev["id"])
            _ev_start = str(_ev.get("event_date") or "")[:10]
            _ev_end = str(_ev.get("end_date") or "")[:10] if _ev.get("end_date") else ""
            _ec = st.columns([2, 2, 1.5, 3, 0.6, 0.6])
            with _ec[0]:
                if _ev_end and _ev_end != _ev_start:
                    st.markdown(f"**{_ev_start} ~ {_ev_end}**")
                else:
                    st.markdown(f"**{_ev_start}**")
            with _ec[1]:
                st.markdown(_ev.get("title") or "-")
            with _ec[2]:
                _ss = str(_ev.get("start_time") or "")[:5]
                _ee = str(_ev.get("end_time") or "")[:5]
                st.markdown(f"{_ss}~{_ee}" if _ss and _ee else "종일")
            with _ec[3]:
                st.caption(_ev.get("note") or "")
            with _ec[4]:
                if st.button("✏️", key=f"se_edit_{_ev_id}", help="수정"):
                    st.session_state["se_editing_id"] = _ev_id
                    st.rerun()
            with _ec[5]:
                if st.button("🗑️", key=f"se_del_{_ev_id}", help="삭제"):
                    ok, e = _erp_delete_row("app_store_events", _ev_id)
                    if ok:
                        _erp_store_events_cached.clear()
                        if st.session_state.get("se_editing_id") == _ev_id:
                            st.session_state.pop("se_editing_id", None)
                        flash("매장 공용 일정이 삭제되었습니다.")
                        st.rerun()
                    else:
                        st.error(f"삭제 실패: {e}")
    else:
        st.info(f"{se_ym} 등록된 매장 공용 일정이 없습니다.")

    # ── 팝업(모달): 편집 대상이 지정되어 있으면 열기 ──
    if _editing_id:
        _ev_target = next((e for e in (_events or []) if int(e["id"]) == _editing_id), None)
        if _ev_target:
            from ui_dialogs import open_dialog as _open_dialog  # noqa: WPS433
            _open_dialog(
                f"✏️ 일정 수정 #{_editing_id}",
                lambda ev=_ev_target: _render_store_event_edit_form(ev),
                width="medium",
            )
        else:
            st.session_state.pop("se_editing_id", None)

    # 기간/시간 유형은 폼 외부에서 라디오 선택 → 폼 내부 입력이 즉시 반응
    sec_outer = st.columns([1, 1])
    with sec_outer[0]:
        se_span_mode = st.radio(
            "기간 유형", ["하루", "여러 날"], horizontal=True, key=f"se_span_mode_{_kp}",
            help="여러 날 선택 시 시작일~종료일 사이의 모든 날짜에 표시됩니다.",
        )
    with sec_outer[1]:
        se_time_mode = st.radio(
            "시간 유형", ["종일", "시간대 지정"], horizontal=True, key=f"se_time_mode_{_kp}",
        )

    with st.form(f"erp_store_event_form_{_kp}", clear_on_submit=True):
        st.markdown("**신규 일정 등록**")
        if se_span_mode == "하루":
            sec1, sec2 = st.columns([1, 3])
            with sec1:
                se_date_start = st.date_input("날짜", value=_today, key=f"se_date_start_{_kp}")
            with sec2:
                se_title = st.text_input("제목", placeholder="예: 매장 정기 회의 / 본사 점검 / 행사 준비", key=f"se_title_{_kp}")
            se_date_end = se_date_start
        else:
            sec1a, sec1b, sec2 = st.columns([1, 1, 3])
            with sec1a:
                se_date_start = st.date_input("시작일", value=_today, key=f"se_date_start_multi_{_kp}")
            with sec1b:
                se_date_end = st.date_input("종료일", value=_today + timedelta(days=1), key=f"se_date_end_multi_{_kp}")
            with sec2:
                se_title = st.text_input("제목", placeholder="예: 본사 점검 (3일간) / 신상품 전시 / 휴가", key=f"se_title_m_{_kp}")

        if se_time_mode == "시간대 지정":
            sec4, sec5 = st.columns(2)
            with sec4:
                se_start = _erp_time_input_30min("시작 시각", value=dt_time(18, 0), key=f"se_start_{_kp}")
            with sec5:
                se_end = _erp_time_input_30min("종료 시각", value=dt_time(20, 0), key=f"se_end_{_kp}")
            se_has_time = True
        else:
            se_start = None
            se_end = None
            se_has_time = False

        se_note = st.text_input("메모 (선택)", placeholder="추가 설명", key=f"se_note_{_kp}")
        if st.form_submit_button("📌 매장 공용 일정 등록", type="primary"):
            if not (se_title or "").strip():
                st.error("제목을 입력해 주세요.")
            elif se_date_end < se_date_start:
                st.error("종료일이 시작일보다 빠를 수 없습니다.")
            elif se_has_time and (se_end.hour * 60 + se_end.minute) <= (se_start.hour * 60 + se_start.minute):
                st.error("종료 시각이 시작 시각보다 늦어야 합니다.")
            else:
                _is_multi = (se_date_end != se_date_start)
                _row = {
                    "db_filename": current_db,
                    "event_date": se_date_start.isoformat(),
                    "end_date": se_date_end.isoformat() if _is_multi else None,
                    "title": se_title.strip(),
                    "start_time": se_start.strftime("%H:%M:%S") if se_has_time else None,
                    "end_time": se_end.strftime("%H:%M:%S") if se_has_time else None,
                    "note": (se_note or "").strip() or None,
                    "created_by": me_name,
                }
                ok, e = _erp_insert_row("app_store_events", _row)
                # end_date 컬럼이 없는 환경(구 스키마)이면 컬럼 빼고 재시도
                if not ok and ("end_date" in str(e) or "PGRST204" in str(e) or "schema cache" in str(e).lower()):
                    _row_legacy = {k: v for k, v in _row.items() if k != "end_date"}
                    ok, e = _erp_insert_row("app_store_events", _row_legacy)
                    if ok and _is_multi:
                        flash(
                            "일정 등록 완료. 단, app_store_events에 end_date 컬럼이 없어 시작일만 저장되었습니다. "
                            "SUPABASE_APP_ATTENDANCE_COUNTER.sql 의 ALTER TABLE 문을 실행한 뒤 다시 등록해 주세요.",
                            level="warning",
                        )
                        _erp_store_events_cached.clear()
                        st.rerun()
                if ok:
                    _erp_store_events_cached.clear()
                    if _is_multi:
                        _days = (se_date_end - se_date_start).days + 1
                        flash(f"매장 공용 일정이 등록되었습니다. ({_days}일간: {se_date_start} ~ {se_date_end})")
                    else:
                        flash("매장 공용 일정이 등록되었습니다.")
                    st.rerun()
                else:
                    st.error(f"등록 실패: {e}. `app_store_events` 테이블이 없으면 SUPABASE_APP_ATTENDANCE_COUNTER.sql 을 먼저 실행해 주세요.")


# ---------- 탭 3: 월별 캘린더 ----------

def _erp_cal_clamp_selected_day(year: int, month: int, today: date) -> date:
    """선택일이 해당 월에 없으면 오늘(같은 월) 또는 1일로 맞춘다."""
    cur = st.session_state.get("erp_cal_selected_day")
    if isinstance(cur, date) and cur.year == int(year) and cur.month == int(month):
        return cur
    if today.year == int(year) and today.month == int(month):
        d = today
    else:
        d = date(int(year), int(month), 1)
    st.session_state["erp_cal_selected_day"] = d
    return d


@st.fragment
def _erp_tab_calendar(current_db: str, role: str, me_name: str, today: date):
    """전체 공개 월별 근무 캘린더 — 모든 유저가 모든 매장 근무 일정 열람 가능.
    @st.fragment: 빠른 수정/삭제 시 이 캘린더만 부분 재실행하여 상위 탭(근무 일정 계획 등)으로 복귀하지 않게 한다."""
    import calendar as _cal

    st.markdown("### 2️⃣ 월별 근무 캘린더")
    st.caption("매장·직원을 선택해 누가 언제 어디서 일하는지 한눈에 확인할 수 있습니다.")
    # 빠른 수정/삭제 직후 부분 재실행으로 전달된 완료 알림 (전체 rerun 아님 → 탭 유지)
    _cal_flash = st.session_state.pop("_erp_cal_flash", None)
    if _cal_flash:
        st.toast(f"✅ {_cal_flash}", icon="✅")
        st.success(_cal_flash)

    # ── 전체 매장 목록 로드 ─────────────────────────────────────
    stores_df = get_supabase_stores_dataframe_cached()
    palette = ["#1565C0", "#2E7D32", "#E65100", "#6A1B9A", "#00695C", "#5D4037", "#283593", "#C62828"]
    if stores_df is not None and len(stores_df) > 0:
        all_store_names = stores_df["store_name"].tolist()
        all_dbs = stores_df["db_filename"].tolist()
        _sn_to_dbf = {row["store_name"]: row["db_filename"] for _, row in stores_df.iterrows()}
        _dbf_to_sn = {row["db_filename"]: row["store_name"] for _, row in stores_df.iterrows()}
        store_color = {dbf: palette[i % len(palette)] for i, dbf in enumerate(all_dbs)}
    else:
        all_store_names = []
        all_dbs = [current_db]
        _sn_to_dbf = {}
        _dbf_to_sn = {current_db: "내 매장"}
        store_color = {current_db: palette[0]}

    # ── 연·월만 상단. 매장·직원 필터는 캘린더 아래 ─────────────
    if "erp_cal_store" not in st.session_state:
        st.session_state["erp_cal_store"] = "전체 매장"
    if "erp_cal_emp" not in st.session_state:
        st.session_state["erp_cal_emp"] = "(전체 직원)"
    col_y, col_m = st.columns([1, 1])
    with col_y:
        year = st.number_input("연도", min_value=2020, max_value=2100,
                               value=today.year, step=1, key="erp_cal_year")
    with col_m:
        month = st.number_input("월", min_value=1, max_value=12,
                                value=today.month, step=1, key="erp_cal_month")
    sel_store = st.session_state.get("erp_cal_store") or "전체 매장"
    selected_emp = st.session_state.get("erp_cal_emp") or "(전체 직원)"
    _store_opts = ["전체 매장"] + all_store_names + ["기타 (외부/행사)"]
    if sel_store not in _store_opts:
        sel_store = "전체 매장"
        st.session_state["erp_cal_store"] = sel_store
    _sel_is_etc = (sel_store == "기타 (외부/행사)")
    target_dbs = all_dbs
    _sel_dbf = _sn_to_dbf.get(sel_store) if (sel_store not in ("전체 매장", "기타 (외부/행사)")) else None
    show_store_tag = (sel_store == "전체 매장")
    _emp_list_dbs = [_sel_dbf] if _sel_dbf else all_dbs
    all_emps: list[str] = []
    for dbf in _emp_list_dbs:
        all_emps += _erp_get_employee_names_for_store(dbf)
    all_emps = sorted(set(all_emps))
    if selected_emp not in (["(전체 직원)"] + all_emps):
        selected_emp = "(전체 직원)"
        st.session_state["erp_cal_emp"] = selected_emp
    _erp_cal_clamp_selected_day(int(year), int(month), today)

    # ── 데이터 로드 ─────────────────────────────────────────────
    last_day = _cal.monthrange(int(year), int(month))[1]
    period_start = date(int(year), int(month), 1)
    period_end   = date(int(year), int(month), last_day)

    all_shifts: list = []
    all_logs:   list = []
    all_events: list = []
    rules_by_store_dow: dict = {}
    _ym_key = f"{int(year):04d}-{int(month):02d}"
    # 매장별 순차 쿼리(4×N회) 대신 .in_() 배치 조회로 테이블당 1회만 조회.
    _target_set = set(target_dbs)
    for s in _erp_fetch_range_multi("app_shift_schedules", "db_filename", target_dbs,
                                    "shift_date", period_start, period_end):
        s["_dbf"] = s.get("db_filename")
        all_shifts.append(s)
    for l in _erp_fetch_range_multi("app_attendance_logs", "home_db_filename", target_dbs,
                                    "log_date", period_start, period_end):
        l["_dbf"] = l.get("home_db_filename")
        all_logs.append(l)
    for _ev in _erp_store_events_multi(target_dbs, _ym_key):
        _ev["_dbf"] = _ev.get("db_filename")
        all_events.append(_ev)
    for r in _erp_fetch_table_multi("app_staffing_rules", "db_filename", target_dbs):
        _rdbf = r.get("db_filename")
        if _rdbf not in _target_set:
            continue
        rules_by_store_dow.setdefault((_rdbf, int(r.get("day_of_week") or 0)), []).append(r)

    # 표시명 정규화: 기존 데이터의 employee_name이 이메일이어도 app_users.name(예: 김승찬)으로 표시
    _name_map = _get_app_user_display_name_map()
    def _resolve(emp_raw: str) -> str:
        if not emp_raw:
            return ""
        key = str(emp_raw).strip()
        return _name_map.get(key) or _name_map.get(key.lower()) or _email_local_part(key) or key
    for s in all_shifts:
        s["employee_name"] = _resolve(s.get("employee_name") or "")
    for l in all_logs:
        l["employee_name"] = _resolve(l.get("employee_name") or "")

    # ── 승인된 신청서 시간대 보강 폴백 ─────────────────────────────
    # 로그(app_attendance_logs)의 start_time/end_time 이 누락된 경우
    # 원 신청서(app_work_adjustments.shift_start/end) 에서 시각을 끌어와
    # 캘린더 배지에 '20:30~21:00' 형태로 표시되도록 한다.
    _adj_time_map: dict[tuple[str, str, str], tuple[str, str]] = {}
    try:
        _sb_cal, _ = get_supabase_client()
        if _sb_cal:
            _adj_rows = _sb_cal.table("app_work_adjustments")\
                .select("employee_name,target_date,kind,shift_start,shift_end,status")\
                .eq("status", "approved")\
                .in_("kind", ["overtime", "meeting", "early_leave", "summer_vacation", "reward", "long_service"])\
                .gte("target_date", period_start.isoformat())\
                .lte("target_date", period_end.isoformat())\
                .execute().data or []
            for _ar in _adj_rows:
                _ss_str = str(_ar.get("shift_start") or "")[:8]
                _ee_str = str(_ar.get("shift_end") or "")[:8]
                if not (_ss_str and _ee_str):
                    continue
                _wt_map = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_ar.get("kind") or "etc", "특이사항")
                _emp_res = _resolve(_ar.get("employee_name") or "")
                _dt_res = str(_ar.get("target_date") or "")[:10]
                if _emp_res and _dt_res:
                    _adj_time_map[(_emp_res, _dt_res, _wt_map)] = (_ss_str, _ee_str)
    except Exception:
        pass

    # 인원 충족 체크용 전체 데이터 (매장/직원 필터 적용 전) — 항상 전 매장·전 직원 기준으로 산출
    # ⚠️ 매장 필터 후에 스냅샷하면, 다른 매장의 룰 평가 시 0명으로 계산되어 모든 매장이 인원부족으로 잡히는 버그.
    all_shifts_for_rules = all_shifts[:]

    # 매장 필터 적용
    # - 특정 매장 선택: db_filename 일치 OR work_location_name 이 해당 매장명과 일치하는 항목
    # - 기타 선택: work_location_name 이 있고, 등록된 매장명/db 목록에 해당하지 않는 항목
    # - 전체: 필터 없음
    _known_store_names = set(all_store_names)
    _known_store_dbfs  = set(all_dbs)
    if _sel_is_etc:
        # 기타: work_location_name 이 채워져 있고, 등록된 매장명과 다른 항목
        all_shifts = [s for s in all_shifts
                      if (s.get("work_location_name") or "").strip()
                      and (s.get("work_location_name") or "").strip() not in _known_store_names]
        all_logs = []  # 근태 로그는 work_location_name 없으므로 기타 선택 시 제외
    elif _sel_dbf:
        # 특정 매장: 소속 db 이거나, work_location_name 이 해당 매장명과 일치
        _sel_store_name = sel_store
        all_shifts = [s for s in all_shifts
                      if s.get("_dbf") == _sel_dbf
                      or (s.get("work_location_name") or "").strip() == _sel_store_name]
        # 근태 로그는 소속 db 기준으로만 존재
        all_logs = [l for l in all_logs if l.get("_dbf") == _sel_dbf]

    # 직원 필터 적용 (정규화 후 비교) — 화면 표시용에만 적용
    if selected_emp and selected_emp != "(전체 직원)":
        all_shifts = [s for s in all_shifts if (s.get("employee_name") or "") == selected_emp]
        all_logs   = [l for l in all_logs   if (l.get("employee_name") or "") == selected_emp]

    # 날짜별 그룹핑 (표시용)
    shifts_by_date: dict = {}
    for s in all_shifts:
        shifts_by_date.setdefault(str(s.get("shift_date") or "")[:10], []).append(s)
    logs_by_date: dict = {}
    for l in all_logs:
        logs_by_date.setdefault(str(l.get("log_date") or "")[:10], []).append(l)

    # 인원 체크용 전체 날짜별 그룹핑 (직원 필터 무관)
    all_shifts_by_date_for_rules: dict = {}
    for s in all_shifts_for_rules:
        all_shifts_by_date_for_rules.setdefault(str(s.get("shift_date") or "")[:10], []).append(s)
    # 다일정(end_date)이 있는 경우 시작일~종료일 사이 모든 날짜에 배지 표시
    events_by_date: dict = {}
    for ev in all_events:
        _ev_start_s = str(ev.get("event_date") or "")[:10]
        _ev_end_s = str(ev.get("end_date") or "")[:10] if ev.get("end_date") else ""
        if not _ev_start_s:
            continue
        try:
            _ev_start_d = date.fromisoformat(_ev_start_s)
            _ev_end_d = date.fromisoformat(_ev_end_s) if _ev_end_s else _ev_start_d
        except Exception:
            continue
        if _ev_end_d < _ev_start_d:
            _ev_end_d = _ev_start_d
        # 현재 보고 있는 월(period_start~period_end)과 교집합 범위만 순회
        _it_start = max(_ev_start_d, period_start)
        _it_end = min(_ev_end_d, period_end)
        _cur_d = _it_start
        _total_days = (_ev_end_d - _ev_start_d).days + 1
        while _cur_d <= _it_end:
            _idx = (_cur_d - _ev_start_d).days + 1
            _ev_copy = dict(ev)
            _ev_copy["_day_idx"] = _idx
            _ev_copy["_total_days"] = _total_days
            events_by_date.setdefault(_cur_d.isoformat(), []).append(_ev_copy)
            _cur_d += timedelta(days=1)

    # 인원 부족/과다 산출 — 항상 전 직원 데이터 기준으로 판단 (직원 필터 무관)
    # ⚠️ 카운팅 기준: work_location_name (파견 근무지) 우선, 비어있으면 _dbf (소속 매장).
    #   - 배지 표시 로직과 일치시킴: 박성진 소속=A, 근무지=B면 B의 인원에 합산
    #   - 외부 행사(유에코임주박람회 등 등록 매장 아님)면 어떤 매장에도 합산 X
    def _shift_effective_dbf(s: dict):
        wloc = (s.get("work_location_name") or "").strip()
        if wloc:
            return _sn_to_dbf.get(wloc)  # 외부 행사면 None
        return s.get("_dbf")

    shortage_dates: dict[str, list[str]] = {}  # {d_iso: [부족_매장명, ...]}
    overstaff_dates: dict[str, list[str]] = {}  # {d_iso: [과다_매장명, ...]}
    overstaff_details: dict[tuple[str, str], str] = {}
    shortage_details: dict[tuple[str, str], str] = {}
    # 부족 슬롯 목록: {(d_iso, 매장명): ["10:00~12:00 (1/2명)", ...]}  — 근무자가 0명인 슬롯은 제외
    shortage_slots: dict[tuple[str, str], list[str]] = {}
    # 진단용: 각 (d_iso, 매장) 의 실제 카운트된 직원 목록
    contributing_emps: dict[tuple[str, str], list[dict]] = {}
    _DOW_LBL = ["월", "화", "수", "목", "금", "토", "일"]
    for (dbf, dow), rules in rules_by_store_dow.items():
        # 매장 필터가 활성이면 선택된 매장만 평가 (다른 매장의 부족/과다는 사용자가 보고 있지 않음)
        if _sel_is_etc:
            continue  # 외부 행사 뷰에서는 매장 인원 룰 평가 의미 없음
        if _sel_dbf and dbf != _sel_dbf:
            continue
        _sname = _dbf_to_sn.get(dbf) or dbf
        for d_iso, day_shifts in all_shifts_by_date_for_rules.items():
            try:
                d = datetime.fromisoformat(d_iso).date()
            except Exception:
                continue
            if d.weekday() != dow:
                continue
            store_day_shifts = [s for s in day_shifts if _shift_effective_dbf(s) == dbf]
            for rule in rules:
                slot_s = _erp_parse_time(rule.get("slot_start"))
                slot_e = _erp_parse_time(rule.get("slot_end"))
                if not slot_s or not slot_e:
                    continue
                actual_cnt = _erp_count_active_at(store_day_shifts, slot_s, slot_e)
                _slot_lbl = f"{str(rule.get('slot_start') or '')[:5]}~{str(rule.get('slot_end') or '')[:5]}"
                # 인원 부족 체크 (break 없이 모든 슬롯 검사)
                _min_n = int(rule.get("min_staff") or 1)
                if actual_cnt < _min_n:
                    shortage_dates.setdefault(d_iso, [])
                    if _sname not in shortage_dates[d_iso]:
                        shortage_dates[d_iso].append(_sname)
                    shortage_details[(d_iso, _sname)] = (
                        f"{_slot_lbl} 슬롯 실제 {actual_cnt}명 / 최소 {_min_n}명 "
                        f"({_DOW_LBL[dow]}요일, 근무지(work_location_name) 우선 기준)"
                    )
                    contributing_emps[(d_iso, _sname)] = store_day_shifts
                    # 근무자가 1명 이상 있는데 최소 미달인 슬롯만 시간대 표시 (0명은 미등록으로 간주)
                    if actual_cnt > 0:
                        _slot_tag = f"{_slot_lbl} ({actual_cnt}/{_min_n}명)"
                        shortage_slots.setdefault((d_iso, _sname), [])
                        if _slot_tag not in shortage_slots[(d_iso, _sname)]:
                            shortage_slots[(d_iso, _sname)].append(_slot_tag)
                    continue  # 다음 슬롯도 계속 검사
                # 과다 근무 체크 (optimal_staff 설정된 경우만)
                _opt = rule.get("optimal_staff")
                if _opt and actual_cnt > int(_opt):
                    overstaff_dates.setdefault(d_iso, [])
                    if _sname not in overstaff_dates[d_iso]:
                        overstaff_dates[d_iso].append(_sname)
                    overstaff_details[(d_iso, _sname)] = (
                        f"{_slot_lbl} 슬롯 실제 {actual_cnt}명 / 적정 {int(_opt)}명 "
                        f"({_DOW_LBL[dow]}요일, 근무지(work_location_name) 우선 기준)"
                    )
                    contributing_emps[(d_iso, _sname)] = store_day_shifts

    # ── ✏️ 빠른 근무일 편집 (셀렉트박스) ──────────────────────────
    # 캘린더 배지 클릭 UX 는 전체 페이지 리로드로 세션 컨텍스트가 초기화되는 문제가 있어
    # (auth 쿼리 파라미터 유실 시 로그아웃, 유지 시에도 사이드바 메뉴/탭 리셋)
    # Streamlit 네이티브 위젯 기반 편집 셀렉트를 대신 제공한다.
    _editable_shifts: list[dict] = []
    _me_aliases = set(_get_current_user_employee_aliases(me_name)) if me_name else set()
    for _d_iso in sorted(shifts_by_date.keys()):
        for _s in shifts_by_date[_d_iso]:
            if not bool(_s.get("id")):
                continue
            _emp_n = (_s.get("employee_name") or "").strip()
            if not _emp_n or (_me_aliases and _emp_n not in _me_aliases):
                continue
            _editable_shifts.append(_s)
    _adj_dialog = None
    if me_name and hasattr(st, "dialog"):
        try:
            _dlg_dec = st.dialog("🧑‍💼 근무시간 관리 · 신청 등록", width="large")
        except TypeError:
            _dlg_dec = st.dialog("🧑‍💼 근무시간 관리 · 신청 등록")

        @_dlg_dec
        def _adj_dialog():
            _erp_render_my_adj_form(current_db, role, me_name, today)

    # ── 캘린더 HTML 렌더링 ──────────────────────────────────────
    cal_obj = _cal.Calendar(firstweekday=6)
    weeks = cal_obj.monthdayscalendar(int(year), int(month))
    dow_labels = [("일", "#E53935"), ("월", "#37474F"), ("화", "#37474F"),
                  ("수", "#37474F"), ("목", "#37474F"), ("금", "#37474F"), ("토", "#1565C0")]

    html = ["<table class='erp-cal-wrap' style='width:100%; border-collapse:collapse; font-size:0.82rem;'>"]
    html.append("<thead><tr>")
    for lbl, lc in dow_labels:
        html.append(f"<th style='border:1px solid #ddd; padding:6px; background:#F5F5F5; color:{lc};'>{lbl}</th>")
    html.append("</tr></thead><tbody>")

    for week in weeks:
        html.append("<tr>")
        for d_num in week:
            if d_num == 0:
                html.append("<td style='border:1px solid #eee; height:115px; background:#FAFAFA;'></td>")
                continue
            d_iso = date(int(year), int(month), d_num).isoformat()
            is_today = (d_iso == today.isoformat())
            bcolor = "#E53935" if d_iso in shortage_dates else ("#FB8C00" if d_iso in overstaff_dates else ("#1976D2" if is_today else "#ddd"))
            bw = "2px" if (d_iso in shortage_dates or d_iso in overstaff_dates or is_today) else "1px"
            bg = "#E3F2FD" if is_today else ("white")
            cell = [f"<td style='border:{bw} solid {bcolor}; vertical-align:top; padding:4px; height:115px; min-width:90px; background:{bg};'>"]
            _cell_date = date(int(year), int(month), d_num)
            _is_holiday_cell = _erp_is_weekend_or_holiday(_cell_date)
            day_label_color = "#E53935" if (_cell_date.weekday() == 6 or _cell_date in _ERP_KR_HOLIDAYS) else \
                              ("#1565C0" if _cell_date.weekday() == 5 else "#37474F")
            _hol_tag = " 🔴" if (_cell_date in _ERP_KR_HOLIDAYS and _cell_date.weekday() < 5) else ""
            cell.append(f"<div style='font-weight:bold; font-size:0.88rem; color:{day_label_color};'>{d_num}{_hol_tag}</div>")
            _n_cell = (
                len(shifts_by_date.get(d_iso, []))
                + len(logs_by_date.get(d_iso, []))
                + len(events_by_date.get(d_iso, []))
            )
            if _n_cell:
                cell.append(
                    f"<div class='erp-cal-sum'><span class='erp-cal-dot'></span>{_n_cell}</div>"
                )
            else:
                cell.append("<div class='erp-cal-sum'></div>")
            cell.append("<div class='erp-cal-detail'>")
            if d_iso in shortage_dates:
                _short_stores = shortage_dates[d_iso]
                _short_label = " · ".join(_short_stores) if _short_stores else "인원부족"
                _short_tip = " | ".join(
                    f"{s}: {shortage_details.get((d_iso, s), '')}" for s in _short_stores
                ) or "인원 부족 슬롯 있음"
                cell.append(
                    f"<div title=\"{_short_tip}\" style='color:#E53935; font-size:0.62rem; font-weight:bold; cursor:help;'>⚠️ {_short_label} 인원부족</div>"
                )
                # 근무자가 일부 있는데 최소 미달인 슬롯의 시간대를 한 줄씩 표시
                for _sn in _short_stores:
                    _slots = shortage_slots.get((d_iso, _sn), [])
                    for _sl in _slots:
                        cell.append(
                            f"<div style='color:#E53935; font-size:0.58rem; padding-left:8px;'>"
                            f"└ {_sl}</div>"
                        )
            if d_iso in overstaff_dates:
                _over_stores = overstaff_dates[d_iso]
                _over_label = " · ".join(_over_stores) if _over_stores else "과다근무"
                _over_tip = " | ".join(
                    f"{s}: {overstaff_details.get((d_iso, s), '')}" for s in _over_stores
                ) or "적정 인원 초과 슬롯 있음"
                cell.append(
                    f"<div title=\"{_over_tip}\" style='color:#FB8C00; font-size:0.62rem; font-weight:bold; cursor:help;'>🔶 {_over_label} 과다근무</div>"
                )

            # 매장 공용 일정 (메모/표시 전용). 다일정은 N/M일 표시
            for ev in events_by_date.get(d_iso, []):
                _ev_title = (ev.get("title") or "").strip()
                _ev_ss = str(ev.get("start_time") or "")[:5]
                _ev_ee = str(ev.get("end_time") or "")[:5]
                _ev_time = f" {_ev_ss}~{_ev_ee}" if _ev_ss and _ev_ee else ""
                _ev_total = int(ev.get("_total_days") or 1)
                _ev_idx = int(ev.get("_day_idx") or 1)
                _ev_span = f" <span style='color:#FB8C00;'>({_ev_idx}/{_ev_total})</span>" if _ev_total > 1 else ""
                cell.append(
                    f"<div style='margin-top:2px; background:#FFF8E1; border:1px dashed #FFB300;"
                    f" padding:1px 4px; border-radius:3px; font-size:0.62rem; color:#6D4C41;'>"
                    f"📌 {_ev_title}{_ev_span}<span style='color:#999;'>{_ev_time}</span></div>"
                )

            # 근무 계획 (shift_schedules) — 실근무지(work_location_name) 기준 매장 컬러 사용
            # 외부 행사(등록 매장 아님): 별도 색 사용 (보라 계열 #7C3AED)
            _EXT_COLOR = "#7C3AED"  # 외부 행사·박람회 등 고정 색
            for sh in shifts_by_date.get(d_iso, []):
                _wloc = (sh.get("work_location_name") or "").strip()
                _eff_dbf_raw = _shift_effective_dbf(sh)  # 외부 행사면 None
                _is_external = bool(_wloc) and (_eff_dbf_raw is None)
                if _is_external:
                    sc = _EXT_COLOR
                    _eff_sn = _wloc  # 배지 라벨 = 행사명 그대로
                else:
                    _eff_dbf = _eff_dbf_raw or sh.get("_dbf") or current_db
                    _eff_sn  = _dbf_to_sn.get(_eff_dbf, "")
                    sc = store_color.get(_eff_dbf, "#607D8B")
                emp  = sh.get("employee_name") or ""
                ss   = str(sh.get("shift_start") or "")[:5]
                ee   = str(sh.get("shift_end") or "")[:5]
                time_txt = f" {ss}~{ee}" if ss and ee else ""
                # 배지 라벨: 실근무지(wloc 우선, 비면 실효 매장명)
                _badge_label = _wloc if _wloc else _eff_sn
                # 필터 뷰에서 자명한 정보(선택 매장과 같은 배지)는 생략 — 단 외부 행사는 항상 표시
                _badge_redundant = (
                    not _is_external
                    and (not show_store_tag)
                    and (not _sel_is_etc)
                    and (_badge_label == sel_store)
                )
                _show_badge = (show_store_tag or _wloc or _is_external) and not _badge_redundant and _badge_label
                sn_badge = (
                    f"<span style='background:{sc}; color:white; font-size:0.58rem;"
                    f" padding:0px 3px; border-radius:2px; margin-right:2px;'>"
                    f"{_badge_label}</span> "
                ) if _show_badge else ""
                # 비고(note): 특별근무·초과근무 사유 등 — 본문 + 툴팁
                _note_txt = str(sh.get("note") or "").strip()
                if _note_txt:
                    _note_safe = (_note_txt.replace("&", "&amp;").replace("<", "&lt;")
                                          .replace(">", "&gt;").replace('"', "&quot;"))
                    _note_html = (
                        f"<div style='margin-left:6px; font-size:0.6rem; color:#8E24AA;"
                        f" line-height:1.1; word-break:break-word;'"
                        f" title='{_note_safe}'>📝 {_note_safe}</div>"
                    )
                else:
                    _note_html = ""
                cell.append(
                    f"<div style='margin-top:2px; border-left:3px solid {sc};"
                    f" background:{sc}15; padding:1px 3px; border-radius:0 2px 2px 0;'>"
                    f"{sn_badge}<span style='color:{sc}; font-weight:600; font-size:0.7rem;'>{emp}</span>"
                    f"<span style='color:#666; font-size:0.65rem;'>{time_txt}</span>"
                    f"{_note_html}</div>"
                )

            # 근태 기록 (attendance_logs) — 실근무지 기준 컬러 (work_location_name 컬럼이 있으면 우선)
            for lg in logs_by_date.get(d_iso, []):
                _lg_wloc = (lg.get("work_location_name") or "").strip()
                _lg_eff_dbf_raw = _shift_effective_dbf(lg)  # 외부 행사면 None
                _lg_is_external = bool(_lg_wloc) and (_lg_eff_dbf_raw is None)
                if _lg_is_external:
                    _eff_dbf = None
                    sc = _EXT_COLOR
                    _eff_sn = _lg_wloc  # 배지 라벨 = 외부 근무지명 그대로
                else:
                    _eff_dbf = _lg_eff_dbf_raw or lg.get("_dbf") or current_db
                    sc = store_color.get(_eff_dbf, "#555")
                    _eff_sn = _dbf_to_sn.get(_eff_dbf, "")
                dbf = _eff_dbf  # 배지 라벨용 호환 변수 유지
                wt   = lg.get("work_type") or "정상"
                bc   = _ERP_BADGE_COLORS.get(wt, "#90A4AE")
                emp  = lg.get("employee_name") or ""
                extra = f" {lg.get('diff_minutes') or 0}분" if wt in ("시차적립", "시차사용") else ""
                # 태그 노출 조건: 전체 매장 뷰이거나, 외부 근무지인 경우
                _sn_tag_visible = show_store_tag or _lg_is_external
                sn_tag = (f" <span style='font-size:0.58rem; color:{sc};"
                          f" font-weight:bold;'>({_eff_sn})</span>") if (_sn_tag_visible and _eff_sn) else ""
                # 시간대 표시:
                #  - 추가근무/회의: start~end 범위 (연장 시간대)
                #  - 조퇴: 실제 퇴근 시각만 (start_time = 실제 퇴근 시각, end_time = 예정 종료)
                #  - 여름휴가/포상/장기근속/특이사항: 시간대가 있으면 표시, 없으면 diff_minutes(h)
                _time_txt = ""
                _st = str(lg.get("start_time") or "")[:5]
                _et = str(lg.get("end_time") or "")[:5]
                _dm = int(lg.get("diff_minutes") or 0)
                # 로그에 시간이 비어 있으면 원 신청서(app_work_adjustments)에서 폴백.
                if (not _st or not _et):
                    _fallback = _adj_time_map.get((emp, d_iso, wt))
                    if _fallback:
                        _st = _st or _fallback[0][:5]
                        _et = _et or _fallback[1][:5]
                if wt in ("추가근무", "회의"):
                    if _st and _et:
                        _time_txt = (f" <span style='font-size:0.62rem; color:#555;'>"
                                     f"{_st}~{_et}</span>")
                    elif _dm:
                        _dh, _dmm = divmod(_dm, 60)
                        _dur = f"{_dh}h{_dmm:02d}m" if _dmm else f"{_dh}h"
                        _time_txt = (f" <span style='font-size:0.62rem; color:#777;'>+{_dur}</span>")
                elif wt == "조퇴":
                    # end_time = 실제 퇴근시각. start_time = 근무 시작. '→HH:MM' 로 실제 퇴근시각 표시.
                    if _et:
                        _time_txt = (f" <span style='font-size:0.62rem; color:#555;'>"
                                     f"→{_et}</span>")
                    elif _dm:
                        _dh, _dmm = divmod(_dm, 60)
                        _dur = f"{_dh}h{_dmm:02d}m" if _dmm else f"{_dh}h"
                        _time_txt = (f" <span style='font-size:0.62rem; color:#777;'>-{_dur}</span>")
                elif wt in ("여름휴가", "포상", "장기근속", "특이사항"):
                    if _st and _et:
                        _time_txt = (f" <span style='font-size:0.62rem; color:#555;'>"
                                     f"{_st}~{_et}</span>")
                    elif _dm:
                        _dh, _dmm = divmod(_dm, 60)
                        _dur = f"{_dh}h{_dmm:02d}m" if _dmm else f"{_dh}h"
                        _time_txt = (f" <span style='font-size:0.62rem; color:#777;'>{_dur}</span>")
                # 사유(note): 승인된 신청의 사유 필드 — 본문 + 툴팁
                _lg_note = str(lg.get("note") or "").strip()
                if _lg_note:
                    _lg_note_safe = (_lg_note.replace("&", "&amp;").replace("<", "&lt;")
                                             .replace(">", "&gt;").replace('"', "&quot;"))
                    _lg_note_html = (
                        f"<div style='margin-left:6px; font-size:0.6rem; color:#8E24AA;"
                        f" line-height:1.1; word-break:break-word;'"
                        f" title='{_lg_note_safe}'>📝 {_lg_note_safe}</div>"
                    )
                else:
                    _lg_note_html = ""
                cell.append(
                    f"<div style='margin-top:1px;'>"
                    f"<span style='background:{bc}; color:white; padding:1px 4px;"
                    f" border-radius:3px; font-size:0.65rem;'>{wt}{extra}</span>"
                    f" <span style='font-size:0.68rem; color:{sc}; font-weight:600;'>{emp}</span>"
                    f"{_time_txt}{sn_tag}{_lg_note_html}</div>"
                )
            cell.append("</div></td>")
            html.append("".join(cell))
        html.append("</tr>")
    html.append("</tbody></table>")
    st.markdown("".join(html), unsafe_allow_html=True)

    # ── 당일 일정 (기본: 오늘) ────────────────────────────────
    _sel_day = st.date_input(
        "선택한 날",
        key="erp_cal_selected_day",
        min_value=date(int(year), int(month), 1),
        max_value=date(int(year), int(month), last_day),
    )
    if not isinstance(_sel_day, date):
        _sel_day = date(int(year), int(month), 1)
    _sel_iso = _sel_day.isoformat()
    _dow_names = ["월", "화", "수", "목", "금", "토", "일"]
    _sel_dow = _dow_names[_sel_day.weekday()]
    st.markdown(f"**{_sel_day.month}월 {_sel_day.day}일 ({_sel_dow}) 일정**")
    _day_shifts = list(shifts_by_date.get(_sel_iso, []))
    _day_logs = list(logs_by_date.get(_sel_iso, []))
    _day_evs = list(events_by_date.get(_sel_iso, []))
    if not (_day_shifts or _day_logs or _day_evs):
        st.caption("이 날 등록된 일정이 없습니다.")
    for _ev in _day_evs:
        st.markdown(f"📌 {( _ev.get('title') or '').strip()}")
    for _i, _sh in enumerate(_day_shifts):
        _emp = (_sh.get("employee_name") or "").strip()
        _ss = str(_sh.get("shift_start") or "")[:5]
        _ee = str(_sh.get("shift_end") or "")[:5]
        _wl = (_sh.get("work_location_name") or "").strip()
        _lbl = f"{_emp}  {_ss}~{_ee}" + (f"  · {_wl}" if _wl else "")
        _can_edit = bool(_sh.get("id")) and (not _me_aliases or _emp in _me_aliases)
        if _can_edit:
            _c_l, _c_b = st.columns([4, 1])
            _c_l.write(_lbl)
            if _c_b.button("수정", key=f"erp_cal_day_edit_{_sh.get('id')}_{_i}"):
                st.session_state["erp_shift_edit_id"] = int(_sh.get("id") or 0)
                st.rerun(scope="fragment")
        else:
            st.write(_lbl)
    for _lg in _day_logs:
        _wt = _lg.get("work_type") or "정상"
        _emp = _lg.get("employee_name") or ""
        _st = str(_lg.get("start_time") or "")[:5]
        _et = str(_lg.get("end_time") or "")[:5]
        _tm = f" {_st}~{_et}" if _st and _et else ""
        st.write(f"{_wt}  {_emp}{_tm}")

    if me_name:
        st.markdown('<div class="erp-cal-plus-bar">', unsafe_allow_html=True)
        _p1, _p2 = st.columns(2)
        with _p1:
            if st.button("➕ 추가근무·휴가", type="primary", width="stretch", key="erp_cal_plus_adj"):
                st.session_state["my_new_date"] = _sel_day
                if _adj_dialog is not None:
                    _adj_dialog()
                else:
                    st.info("팝업을 지원하지 않는 환경입니다. 아래 expander에서 등록해 주세요.")
        with _p2:
            _day_mine = [
                s for s in _day_shifts
                if s.get("id") and (not _me_aliases or (s.get("employee_name") or "").strip() in _me_aliases)
            ]
            if st.button("✏️ 정기근무 수정", width="stretch", key="erp_cal_plus_shift"):
                if len(_day_mine) == 1:
                    st.session_state["erp_shift_edit_id"] = int(_day_mine[0].get("id") or 0)
                    st.rerun(scope="fragment")
                elif len(_day_mine) > 1:
                    st.session_state["erp_cal_plus_pick"] = True
                else:
                    st.toast("이 날 수정할 본인 정기근무가 없습니다.", icon="ℹ️")
        if st.session_state.get("erp_cal_plus_pick") and len(_day_mine) > 1:
            _pick_map = {
                int(s.get("id") or 0): (
                    f"{str(s.get('shift_start') or '')[:5]}~{str(s.get('shift_end') or '')[:5]} "
                    f"{s.get('employee_name') or ''}"
                )
                for s in _day_mine if s.get("id")
            }
            _pid = st.selectbox(
                "수정할 근무",
                options=list(_pick_map.keys()),
                format_func=lambda i: _pick_map.get(i, str(i)),
                key="erp_cal_plus_shift_id",
            )
            if st.button("편집 팝업 열기", key="erp_cal_plus_shift_go", type="primary"):
                st.session_state["erp_shift_edit_id"] = int(_pid or 0)
                st.session_state.pop("erp_cal_plus_pick", None)
                st.rerun(scope="fragment")
        st.markdown("</div>", unsafe_allow_html=True)

    # ── 매장·직원 필터 + 월 카운터 (캘린더 아래) ────────────────
    col_store, col_emp = st.columns([1, 1])
    with col_store:
        st.selectbox("📍 매장 선택", _store_opts, key="erp_cal_store")
    with col_emp:
        st.selectbox("👤 직원 필터", ["(전체 직원)"] + all_emps, key="erp_cal_emp")
    _ctr_target_emp = selected_emp if (selected_emp and selected_emp != "(전체 직원)") else me_name
    _ctr_target_db = _sel_dbf if _sel_dbf else current_db
    if _ctr_target_emp:
        _cal_ctr = _erp_compute_monthly_remaining(_ctr_target_db, _ctr_target_emp, int(year), int(month))
        _ct_target_h = _cal_ctr["target_min"] / 60.0
        _ct_worked_h = _cal_ctr["worked_min"] / 60.0
        _ct_remain_h = _cal_ctr["remaining_min"] / 60.0
        _ct_pct = _cal_ctr["percent"]
        _ct_weekly = round(_ct_target_h / 4.33, 1)
        _ct_planned_min = _erp_compute_monthly_planned_minutes(
            _ctr_target_emp, int(year), int(month),
            fallback_db=_ctr_target_db,
        )
        _ct_planned_h = _ct_planned_min / 60.0
        if _ct_pct >= 100:
            _cc = "#E53935"
        elif _ct_pct >= 80:
            _cc = "#FB8C00"
        else:
            _cc = "#2E7D32"
        _plan_vs_target = ""
        if _ct_planned_h > 0 and _ct_target_h > 0:
            _plan_pct = _ct_planned_h / _ct_target_h * 100.0
            _plan_color = "#2E7D32" if _plan_pct >= 100 else "#FB8C00" if _plan_pct >= 80 else "#E53935"
            _plan_vs_target = (f" <span style='color:{_plan_color}; font-size:0.82em;'>"
                               f"(목표 대비 {_plan_pct:.0f}%)</span>")
        st.markdown(
            f"<div style='margin:6px 0 10px 0; padding:8px 12px; background:#FAFAFA;"
            f" border-left:4px solid {_cc}; border-radius:4px; font-size:0.88rem;'>"
            f"⏱️ <b>{_ctr_target_emp}</b> · {int(year)}년 {int(month)}월 카운터 &nbsp;|&nbsp; "
            f"목표 <b>{_ct_target_h:.0f}h</b> (주 {_ct_weekly:g}h) "
            f"&nbsp;|&nbsp; 계획 <b>{_ct_planned_h:.1f}h</b>{_plan_vs_target} "
            f"&nbsp;|&nbsp; 누적 <b>{_ct_worked_h:.1f}h</b> ({_ct_pct:g}%) "
            f"&nbsp;|&nbsp; 잔여 <b style='color:{_cc}; font-size:1.1rem;'>{_ct_remain_h:+.1f}h</b>"
            f"</div>",
            unsafe_allow_html=True,
        )

    if me_name:
        with st.expander("✏️ 정기 근무시간 수정 (팝업)", expanded=False):
            if not _editable_shifts:
                st.info("이번 달 등록된 본인 정기 근무일이 없습니다. "
                        "정기 근무일정은 [정기근무일정] 탭에서 먼저 등록해 주세요.")
            else:
                st.caption("아래에서 근무일을 선택하고 [편집] 버튼을 누르면 팝업 창에서 바로 수정할 수 있습니다.")
                _qe_options: list[tuple[int, str]] = []
                for _s in _editable_shifts:
                    _sid = int(_s.get("id") or 0)
                    _d = str(_s.get("shift_date") or "")[:10]
                    _emp = _s.get("employee_name") or ""
                    _ss = str(_s.get("shift_start") or "")[:5]
                    _ee = str(_s.get("shift_end") or "")[:5]
                    _wl = (_s.get("work_location_name") or "").strip()
                    _eff_dbf_q = _shift_effective_dbf(_s) or _s.get("_dbf") or current_db
                    _loc_lbl = _wl if _wl else (_dbf_to_sn.get(_eff_dbf_q, "") or "")
                    _label = f"{_d} · {_emp} · {_ss}~{_ee}" + (f" · {_loc_lbl}" if _loc_lbl else "")
                    _qe_options.append((_sid, _label))
                _qe_id_list = [_sid for _sid, _ in _qe_options]
                _qe_id_to_label = {_sid: _lbl for _sid, _lbl in _qe_options}
                _qe_pick_id = st.selectbox(
                    "근무일 선택",
                    options=_qe_id_list,
                    format_func=lambda _sid: _qe_id_to_label.get(_sid, str(_sid)),
                    key="erp_calendar_quick_edit_pick_id",
                    index=0,
                )
                _qe_pick_id = int(_qe_pick_id or 0)
                if st.button("✏️ 편집 팝업 열기", key="erp_calendar_quick_edit_open", type="primary"):
                    if _qe_pick_id:
                        st.session_state["erp_shift_edit_id"] = _qe_pick_id
                        st.rerun(scope="fragment")
        with st.expander("➕➖ 추가근무·휴가신청 (팝업)", expanded=False):
            st.caption("추가근무·휴가 등 신청을 팝업 창에서 바로 등록할 수 있습니다.")
            if st.button("📤 신청 등록 팝업 열기", key="erp_calendar_adj_btn", type="primary"):
                st.session_state["my_new_date"] = _sel_day
                if _adj_dialog is not None:
                    _adj_dialog()
                else:
                    st.info("이 Streamlit 버전은 팝업(st.dialog) 을 지원하지 않습니다. "
                            "'추가근무·휴무 신청' 탭에서 등록해 주세요.")
    _erp_render_attendance_excel_export(current_db, role, me_name, all_dbs,
                                        int(year), int(month))

    # ── ✏️ 캘린더 배지 클릭 → 즉시 편집 팝업 ─────────────────────
    def _render_shift_quick_edit(sh: dict) -> None:
        """캘린더에서 클릭한 근무일 편집 팝업.
        기존 하단 expander 인라인 편집 폼과 동일한 필드·저장 로직을 재사용한다.
        URL 조작으로 우회하는 케이스에 대비해 폼 렌더 전에 권한을 재검증한다."""
        _sid = int(sh.get("id") or 0)
        _sh_dbf = sh.get("db_filename") or current_db
        _emp_name = sh.get("employee_name") or ""

        # 권한 재검증 (URL 조작 방지)
        _is_admin_dlg = role in ("store_admin", "superadmin")
        if not (_is_admin_dlg or _emp_name == me_name):
            st.warning("본인 근무만 수정할 수 있습니다.")
            if st.button("닫기", key=f"erp_qs_close_deny_{_sid}", width="stretch"):
                st.session_state.pop("erp_shift_edit_id", None)
                st.rerun()
            return

        try:
            _sd = date.fromisoformat(str(sh.get("shift_date") or "")[:10])
        except Exception:
            st.error("잘못된 근무 일자입니다.")
            if st.button("닫기", key=f"erp_qs_close_bad_{_sid}", width="stretch"):
                st.session_state.pop("erp_shift_edit_id", None)
                st.rerun()
            return

        _cur_loc = (sh.get("work_location_name") or "").strip()
        _cur_db_sn = _dbf_to_sn.get(_sh_dbf, "")
        st.caption(
            f"**{_sd.month}/{_sd.day} ({_ERP_DOW_LABELS[_sd.weekday()]}) · {_emp_name}**"
            + (f"  |  소속: {_cur_db_sn}" if _cur_db_sn else "")
        )

        _es_def, _ee_def = _erp_default_times_for_date(_sh_dbf, _sd)
        _ec_a, _ec_b = st.columns(2)
        with _ec_a:
            _e_start = _erp_time_input_30min(
                "출근 시각",
                value=_erp_parse_time(sh.get("shift_start")) or _es_def,
                key=f"erp_qs_start_{_sid}",
            )
        with _ec_b:
            _e_end = _erp_time_input_30min(
                "퇴근 시각",
                value=_erp_parse_time(sh.get("shift_end")) or _ee_def,
                key=f"erp_qs_end_{_sid}",
            )

        # 근무 장소 (실근무지)
        _ETC_LABEL = "기타 (외부/행사) — 직접 입력"
        _loc_opts = list(all_store_names) + [_ETC_LABEL]
        if _cur_loc and _cur_loc not in all_store_names:
            _default_label = _ETC_LABEL
        elif _cur_loc in all_store_names:
            _default_label = _cur_loc
        elif _cur_db_sn in all_store_names:
            _default_label = _cur_db_sn
        else:
            _default_label = _loc_opts[0] if _loc_opts else _ETC_LABEL
        try:
            _loc_idx = _loc_opts.index(_default_label)
        except ValueError:
            _loc_idx = 0
        _e_loc_sel = st.selectbox(
            "근무 장소 (실근무지)", _loc_opts, index=_loc_idx,
            key=f"erp_qs_loc_{_sid}",
            help="이 일정의 실제 근무 매장. 직원 소속과 무관하게 이 값으로 캘린더에 합산됩니다.",
        )
        _is_etc = (_e_loc_sel == _ETC_LABEL)
        if _is_etc:
            _e_loc_etc = st.text_input(
                "외부 행사명/상세 위치",
                value=_cur_loc if _cur_loc and _cur_loc not in all_store_names else "",
                key=f"erp_qs_loc_etc_{_sid}",
                placeholder="예: 유에코임주박람회 / 롯데백화점 행사장",
            )
            _final_loc = (_e_loc_etc or "").strip()
        else:
            _final_loc = _e_loc_sel

        _e_note = st.text_input(
            "비고 (특별근무 · 초과근무 사유 등)",
            value=str(sh.get("note") or ""),
            key=f"erp_qs_note_{_sid}",
            placeholder="예: 행사 지원 / 인수인계 야근 / 명절 특근",
        )

        _bc1, _bc2 = st.columns([1, 1])
        with _bc1:
            _save = st.button("💾 저장", type="primary", key=f"erp_qs_save_{_sid}", width="stretch")
        with _bc2:
            _cancel = st.button("취소", key=f"erp_qs_cancel_{_sid}", width="stretch")

        if _cancel:
            st.session_state.pop("erp_shift_edit_id", None)
            # @st.fragment 안 st.dialog 내부에서 st.rerun(scope="fragment") 는
            # 다이얼로그를 정상적으로 닫지 못하는 Streamlit 이슈가 있어 전체 rerun 사용.
            # 활성 탭(erp_main_tab_label)은 segmented_control 이 세션 상태로 유지.
            st.rerun()

        if _save:
            if (_e_start.hour * 60 + _e_start.minute) >= (_e_end.hour * 60 + _e_end.minute):
                st.error("퇴근 시각이 출근 시각보다 늦어야 합니다.")
                return
            if _is_etc and not _final_loc:
                st.error("외부 행사명/상세 위치를 입력해 주세요.")
                return
            # 소속 매장과 같으면 wloc 비움 (정합성)
            _wloc_save: str | None = _final_loc or None
            if _wloc_save and _wloc_save == _cur_db_sn:
                _wloc_save = None
            _ok, _err = _erp_update_row("app_shift_schedules", _sid, {
                "shift_start": _e_start.strftime("%H:%M:%S"),
                "shift_end": _e_end.strftime("%H:%M:%S"),
                "work_location_name": _wloc_save,
                "note": (_e_note or "").strip() or None,
            })
            if not _ok:
                st.error(f"저장 실패: {_err}")
                return
            # 매장 표준 대비 차이 자동 보정 (기존 편집 UI 와 동일 파라미터)
            _cal_adj_db = _sh_dbf
            try:
                _erp_collect_auto_adjustments(
                    db_filename=_cal_adj_db,
                    employee_name=_emp_name,
                    shifts=[{
                        "shift_date": _sd.isoformat(),
                        "shift_start": _e_start.strftime("%H:%M:%S"),
                        "shift_end": _e_end.strftime("%H:%M:%S"),
                        "work_location_name": _wloc_save,
                    }],
                    source_tag="[자동-캘린더]",
                    created_by=me_name,
                    work_db_filename=_cal_adj_db,
                    work_location_name=_wloc_save,
                )
            except Exception:
                pass
            st.session_state.pop("erp_shift_edit_id", None)
            st.session_state["_erp_cal_flash"] = (
                f"{_sd.isoformat()} {_emp_name} 일정이 수정되었습니다. "
                f"표준 시간과 차이가 있으면 [정기근무일정] 상단에서 연장 신청을 확인하세요."
            )
            # 다이얼로그 정상 종료를 위해 전체 rerun 사용 (위 취소 버튼과 동일 사유).
            st.rerun()

    _edit_id_popup = st.session_state.get("erp_shift_edit_id")
    if _edit_id_popup:
        _target = next(
            (s for s in all_shifts_for_rules if int(s.get("id") or 0) == int(_edit_id_popup)),
            None,
        )
        if _target:
            from ui_dialogs import open_dialog as _open_dialog  # noqa: WPS433
            _tgt_date = str(_target.get("shift_date") or "")[:10]
            _tgt_emp = _target.get("employee_name") or ""
            _open_dialog(
                f"✏️ 근무일 수정 — {_tgt_date} · {_tgt_emp}",
                lambda tgt=_target: _render_shift_quick_edit(tgt),
                width="medium",
            )
        else:
            # 대상이 사라졌으면(다른 창에서 삭제 등) 세션 값 정리
            st.session_state.pop("erp_shift_edit_id", None)

    # ── 아래 진단·수정·범례 섹션은 관리자(store_admin/superadmin) 전용 ─────
    # 일반 직원 화면을 단순화하기 위해 이후 4개 섹션은 관리자에게만 노출한다.
    _is_admin = role in ("store_admin", "superadmin")
    if not _is_admin:
        return

    # ── 🔍 인력 기준 룰 진단 ────────
    if shortage_dates or overstaff_dates:
        with st.expander("🔍 인력 기준 룰 진단 — 화면 표시와 실제 DB row 비교", expanded=False):
            st.caption(
                "캘린더에 인원부족/과다근무가 표시되는데 룰 설정값과 안 맞는다면, "
                "DB에 옛 row가 남아있거나 같은 (요일·슬롯)에 row가 중복 저장됐을 수 있습니다. "
                "아래 raw row가 사이드바 룰 화면에 그대로 반영되어 있는지 비교해보세요."
            )
            _DOW_LBL_FULL = ["월(0)", "화(1)", "수(2)", "목(3)", "금(4)", "토(5)", "일(6)"]
            _diag_rows = []
            for (dbf2, dow2), rules_list in sorted(rules_by_store_dow.items()):
                sn = _dbf_to_sn.get(dbf2) or dbf2
                for r in rules_list:
                    _diag_rows.append({
                        "매장": sn,
                        "요일": _DOW_LBL_FULL[dow2] if 0 <= dow2 <= 6 else str(dow2),
                        "시작": str(r.get("slot_start") or "")[:5],
                        "종료": str(r.get("slot_end") or "")[:5],
                        "최소": r.get("min_staff"),
                        "적정": r.get("optimal_staff"),
                        "row_id": r.get("id"),
                    })
            if _diag_rows:
                df_diag = pd.DataFrame(_diag_rows).sort_values(
                    ["매장", "요일", "시작"], kind="stable"
                )
                # 중복(매장·요일·시작·종료) 표시
                dup_mask = df_diag.duplicated(
                    subset=["매장", "요일", "시작", "종료"], keep=False
                )
                df_diag["⚠ 중복"] = dup_mask.map(lambda x: "🔴" if x else "")
                st.dataframe(df_diag, width="stretch", hide_index=True)
                if dup_mask.any():
                    st.error(
                        "🔴 표시된 행은 같은 매장·요일·시간대에 row가 여러 개 존재합니다. "
                        "사이드바 ERP 룰 설정 화면은 1줄로만 보이지만 카운팅은 모든 row를 평가하므로, "
                        "그 중 적정값이 다른 옛 row가 있으면 화면과 다른 결과가 나옵니다."
                    )

                    # ── 🧹 자동 정리 도구 (각 그룹에서 가장 작은 row_id만 남기고 나머지 삭제)
                    _dup_df = df_diag[dup_mask].copy()
                    _keep_ids: set[int] = set()
                    _delete_ids: list[int] = []
                    for _key, _g in _dup_df.groupby(
                        ["매장", "요일", "시작", "종료"], dropna=False
                    ):
                        _ids_sorted = sorted(int(x) for x in _g["row_id"].tolist())
                        _keep_ids.add(_ids_sorted[0])
                        _delete_ids.extend(_ids_sorted[1:])

                    st.markdown("---")
                    st.markdown("#### 🧹 중복 룰 자동 정리")
                    st.write(
                        f"각 (매장·요일·슬롯) 그룹에서 **가장 작은 row_id를 1개씩 보존**하고 "
                        f"나머지 **{len(_delete_ids)}건**을 영구 삭제합니다."
                    )
                    st.write({
                        "보존(keep)": sorted(_keep_ids),
                        "삭제(delete)": sorted(_delete_ids),
                    })
                    _confirm = st.checkbox(
                        "위 row_id들을 영구 삭제하는 데 동의합니다. (되돌릴 수 없음)",
                        key="erp_rule_dedup_confirm",
                    )
                    if st.button(
                        "🧹 중복 룰 자동 정리 실행",
                        disabled=not _confirm,
                        key="erp_rule_dedup_run",
                        type="primary",
                    ):
                        _ok_cnt = 0
                        _fails: list[tuple[int, str]] = []
                        for _did in _delete_ids:
                            r_ok, r_err = _erp_delete_row("app_staffing_rules", int(_did))
                            if r_ok:
                                _ok_cnt += 1
                            else:
                                _fails.append((int(_did), r_err))
                        try:
                            _erp_staffing_rules_cached.clear()
                        except Exception:
                            pass
                        if _fails:
                            st.error(
                                f"{_ok_cnt}건 삭제, {len(_fails)}건 실패. 실패 상세: {_fails}"
                            )
                        else:
                            st.success(f"{_ok_cnt}건 정리 완료. 페이지를 새로고침합니다.")
                            st.rerun()
                # 시프트 중복 검증
                _shift_dup_rows = []
                for d_iso2, day_shifts2 in all_shifts_by_date_for_rules.items():
                    by_key: dict = {}
                    for s in day_shifts2:
                        k = (
                            s.get("_dbf"),
                            (s.get("employee_name") or "").strip(),
                            str(s.get("shift_start") or "")[:5],
                            str(s.get("shift_end") or "")[:5],
                        )
                        by_key.setdefault(k, []).append(s)
                    for k, lst in by_key.items():
                        if len(lst) > 1:
                            _shift_dup_rows.append({
                                "날짜": d_iso2,
                                "소속(_dbf)": _dbf_to_sn.get(k[0]) or k[0],
                                "직원": k[1],
                                "시작": k[2],
                                "종료": k[3],
                                "중복수": len(lst),
                                "row_ids": ", ".join(str(x.get("id")) for x in lst),
                            })
                if _shift_dup_rows:
                    st.warning(
                        "동일 (날짜·소속·직원·시간)에 시프트 row가 중복 저장된 항목이 있습니다. "
                        "카운트가 부풀어 과다근무로 잡힐 수 있습니다."
                    )
                    st.dataframe(
                        pd.DataFrame(_shift_dup_rows),
                        width="stretch", hide_index=True,
                    )

                # ── 🔬 부족/과다 사유 상세: 카운트에 합산된 직원 목록
                st.markdown("---")
                st.markdown("#### 🔬 부족/과다 사유 상세 — 매장별 합산된 직원")
                st.caption(
                    "카운팅은 **근무지(work_location_name) 우선** 기준입니다. "
                    "work_location_name 이 비어있으면 직원의 소속 매장(_dbf)으로 합산되고, "
                    "외부 행사(등록 매장이 아닌 곳)면 어떤 매장에도 합산되지 않습니다."
                )
                _flag_rows = []
                for (d_iso2, sn2), shifts_list in sorted(contributing_emps.items()):
                    label = "부족" if (d_iso2, sn2) in shortage_details else "과다"
                    detail = shortage_details.get((d_iso2, sn2)) or overstaff_details.get((d_iso2, sn2)) or ""
                    if shifts_list:
                        for s in shifts_list:
                            _flag_rows.append({
                                "날짜": d_iso2,
                                "유형": label,
                                "매장(카운트 대상)": sn2,
                                "사유": detail,
                                "직원": s.get("employee_name") or "",
                                "소속(_dbf)": _dbf_to_sn.get(s.get("_dbf")) or s.get("_dbf"),
                                "근무지(wloc)": (s.get("work_location_name") or "").strip() or "(=소속)",
                                "시작": str(s.get("shift_start") or "")[:5],
                                "종료": str(s.get("shift_end") or "")[:5],
                                "shift_id": s.get("id"),
                            })
                    else:
                        _flag_rows.append({
                            "날짜": d_iso2,
                            "유형": label,
                            "매장(카운트 대상)": sn2,
                            "사유": detail,
                            "직원": "(합산된 직원 없음)",
                            "소속(_dbf)": "",
                            "근무지(wloc)": "",
                            "시작": "",
                            "종료": "",
                            "shift_id": "",
                        })
                if _flag_rows:
                    df_flag = pd.DataFrame(_flag_rows).sort_values(
                        ["날짜", "매장(카운트 대상)", "직원"], kind="stable"
                    )
                    st.dataframe(df_flag, width="stretch", hide_index=True)
                    st.caption(
                        "🔎 박성진 등 특정 직원이 보이지 않는다면: 그 직원의 시프트의 "
                        "**`work_location_name`이 다른 매장 또는 외부 행사로 지정**되어 해당 매장에 합산되지 않은 것입니다. "
                        "근무지를 비우거나 올바른 매장명으로 수정하면 카운트에 포함됩니다."
                    )
            else:
                st.info("등록된 룰이 없습니다.")

    # ── ✏️ 등록된 근무일 목록 수정 / 삭제 (관리자 전용) ────────
    st.divider()
    with st.expander("✏️ 등록된 근무일 수정 / 삭제", expanded=False):
        st.caption("**근무매장**(실제 근무한 매장)을 선택하면 해당 매장에서 일한 모든 직원(소속+파견)의 이번 달 근무일이 나옵니다. 외부 행사는 '기타 (외부/행사)' 선택.")
        # 이 섹션 자체 매장 선택 (상단 필터와 독립). '기타 (외부/행사)'는 내 매장 db에 저장.
        _qe_store_opts = all_store_names + ["기타 (외부/행사)"]
        _qe_default_store = sel_store if sel_store in all_store_names else (
            _dbf_to_sn.get(current_db) or (all_store_names[0] if all_store_names else "기타 (외부/행사)")
        )
        try:
            _qe_store_idx = _qe_store_opts.index(_qe_default_store)
        except ValueError:
            _qe_store_idx = 0
        ec0, ec1 = st.columns([2, 2])
        with ec0:
            # 일반 user도 매장 변경 가능 (본인이 일한 모든 매장의 시프트를 수정·삭제할 수 있도록)
            qe_store_sel = st.selectbox("📍 근무매장", _qe_store_opts, index=_qe_store_idx, key="qe_store_calendar")
        _qe_is_etc = (qe_store_sel == "기타 (외부/행사)")
        edit_dbf = current_db if _qe_is_etc else _sn_to_dbf.get(qe_store_sel, current_db)

        # 직원 → 소속(_dbf) 역방향 인덱스 (새 시프트 추가 시 db_filename 결정용)
        _emp_home_dbf: dict[str, str] = {}
        for _dbf_x in all_dbs:
            for _emp_x in _erp_get_employee_names_for_store(_dbf_x):
                _emp_home_dbf.setdefault(_emp_x, _dbf_x)

        def _resolve_home_dbf(emp_name: str, fallback: str) -> str:
            """직원 소속 매장 dbf 추정 — 마스터 매핑 우선, 없으면 이번 달 시프트 최다 _dbf, 최후 fallback."""
            if emp_name in _emp_home_dbf:
                return _emp_home_dbf[emp_name]
            cnt: dict = {}
            for s in all_shifts_for_rules:
                if (s.get("employee_name") or "") == emp_name and s.get("_dbf"):
                    cnt[s["_dbf"]] = cnt.get(s["_dbf"], 0) + 1
            if cnt:
                return max(cnt.items(), key=lambda x: x[1])[0]
            return fallback

        # ── emp_pool: 선택한 근무 매장에서 일한 모든 직원 (소속 + 파견)
        #   소속 직원 + 이번 달 work_location_name 이 그 매장인 직원 합집합
        _pool_set: set[str] = set()
        if not _qe_is_etc:
            for _e in _erp_get_employee_names_for_store(edit_dbf) or []:
                _pool_set.add(_e)
            for _s in all_shifts_for_rules:
                _wloc = (_s.get("work_location_name") or "").strip()
                if _wloc == qe_store_sel:
                    _en = (_s.get("employee_name") or "").strip()
                    if _en:
                        _pool_set.add(_en)
            # 추가: db_filename 이 그 매장인 시프트의 직원도 포함 (마스터 매핑 누락 대비)
            for _s in all_shifts_for_rules:
                if _s.get("_dbf") == edit_dbf:
                    _en = (_s.get("employee_name") or "").strip()
                    if _en and not (_s.get("work_location_name") or "").strip():
                        _pool_set.add(_en)
        else:
            # 기타(외부행사): work_location_name 이 등록 매장과 다른 모든 시프트의 직원
            _known_names = set(all_store_names)
            for _s in all_shifts_for_rules:
                _wloc = (_s.get("work_location_name") or "").strip()
                if _wloc and _wloc not in _known_names:
                    _en = (_s.get("employee_name") or "").strip()
                    if _en:
                        _pool_set.add(_en)
        emp_pool = sorted(_pool_set) or [me_name]

        with ec1:
            if _is_admin:
                qe_emp = st.selectbox("직원", emp_pool, key="qe_emp_calendar")
            else:
                qe_emp = me_name
                st.text_input("직원", value=me_name, disabled=True, key="qe_emp_fixed_calendar")

        # 이번 달 해당 직원이 선택한 근무 매장에서 일한 시프트 (db_filename == edit_dbf OR work_location_name == 매장명)
        _my_shifts: list = []
        try:
            _client, _err = get_supabase_client()
            if not _err and _client:
                # 1) db_filename = edit_dbf (소속 매장 = 선택 매장 케이스)
                _r1 = _client.table("app_shift_schedules").select("*").eq(
                    "db_filename", edit_dbf
                ).gte("shift_date", period_start.isoformat()).lte(
                    "shift_date", period_end.isoformat()
                ).order("shift_date").execute()
                _rows = list(_r1.data or [])
                # 2) work_location_name = 선택 매장명 (파견 케이스) — 등록 매장 선택 시에만
                if not _qe_is_etc:
                    _r2 = _client.table("app_shift_schedules").select("*").eq(
                        "work_location_name", qe_store_sel
                    ).gte("shift_date", period_start.isoformat()).lte(
                        "shift_date", period_end.isoformat()
                    ).order("shift_date").execute()
                    _rows += list(_r2.data or [])
                # id 중복 제거
                _seen: set = set()
                for _row in _rows:
                    _rid = _row.get("id")
                    if _rid in _seen:
                        continue
                    _seen.add(_rid)
                    _raw = _row.get("employee_name") or ""
                    _disp = _name_map.get(str(_raw).strip()) or _name_map.get(str(_raw).strip().lower()) or _email_local_part(str(_raw).strip()) or str(_raw).strip()
                    if _disp != qe_emp:
                        continue
                    # 등록 매장 선택 시: 실근무지가 그 매장인지(또는 매장 소속·파견 비어있는지) 추가 검증
                    if not _qe_is_etc:
                        _wloc = (_row.get("work_location_name") or "").strip()
                        if _wloc and _wloc != qe_store_sel:
                            continue  # 다른 매장으로 파견된 건은 제외 (해당 매장에서 일한 게 아님)
                        # _wloc 비어있고 _dbf != edit_dbf 인 경우: 다른 매장 소속이 wloc 미지정 → 그 매장 일 아님
                        if not _wloc and _row.get("db_filename") != edit_dbf:
                            continue
                    else:
                        # 기타: work_location_name 이 등록 매장과 다른(외부) 행만
                        _wloc = (_row.get("work_location_name") or "").strip()
                        if not _wloc or _wloc in set(all_store_names):
                            continue
                    _my_shifts.append(_row)
                _my_shifts.sort(key=lambda r: str(r.get("shift_date") or ""))
        except Exception:
            _my_shifts = []

        _qe_chk_key = f"qe_bulk_chk_{qe_emp}_{int(year)}{int(month):02d}"
        st.markdown(f"**📋 {int(year)}년 {int(month)}월 · {qe_emp} 등록 근무일 ({len(_my_shifts)}건)**")
        if not _my_shifts:
            st.info("이번 달 등록된 근무일이 없습니다. 아래에서 새 날짜를 추가하세요.")
        else:
            # 일괄 삭제용 체크 상태
            _checked_ids: set = st.session_state.get(_qe_chk_key, set())
            _qe_edit_id = st.session_state.get("qe_edit_id")

            # 전체 선택 / 해제 + 일괄 삭제 버튼
            _ba, _bb, _bc = st.columns([1, 1, 4])
            with _ba:
                if st.button("☑️ 전체 선택", key="qe_sel_all"):
                    _all_ids = {int(s["id"]) for s in _my_shifts}
                    st.session_state[_qe_chk_key] = _all_ids
                    # 개별 체크박스 위젯 상태도 직접 업데이트 (Streamlit은 key가 있으면 value보다 session_state를 우선)
                    for _s in _my_shifts:
                        st.session_state[f"qe_chk_{int(_s['id'])}"] = True
                    st.rerun(scope="fragment")
            with _bb:
                if st.button("⬜ 전체 해제", key="qe_sel_none"):
                    st.session_state[_qe_chk_key] = set()
                    for _s in _my_shifts:
                        st.session_state[f"qe_chk_{int(_s['id'])}"] = False
                    st.rerun(scope="fragment")
            _checked_ids = st.session_state.get(_qe_chk_key, set())
            if _checked_ids:
                with _bc:
                    if st.button(f"🗑️ 선택 {len(_checked_ids)}건 삭제", type="primary", key="qe_bulk_del"):
                        for _did in list(_checked_ids):
                            _erp_delete_row("app_shift_schedules", _did)
                        st.session_state[_qe_chk_key] = set()
                        st.session_state.pop("qe_edit_id", None)
                        st.session_state["_erp_cal_flash"] = f"{qe_emp} 근무일 {len(_checked_ids)}건이 삭제되었습니다."
                        st.rerun(scope="fragment")

            for _sh in _my_shifts:
                _sid = int(_sh["id"])
                try:
                    _sd = date.fromisoformat(str(_sh.get("shift_date") or "")[:10])
                except Exception:
                    continue
                _ss = str(_sh.get("shift_start") or "")[:5]
                _ee = str(_sh.get("shift_end") or "")[:5]
                _loc = _sh.get("work_location_name") or ""
                if _qe_edit_id == _sid:
                    # 인라인 수정 폼
                    with st.container(border=True):
                        st.markdown(f"**✏️ {_sd.month}/{_sd.day} ({_ERP_DOW_LABELS[_sd.weekday()]}) 수정**")
                        _es_def, _ee_def = _erp_default_times_for_date(edit_dbf, _sd)
                        _ec_a, _ec_b = st.columns(2)
                        with _ec_a:
                            _e_start = _erp_time_input_30min("출근 시각", value=_erp_parse_time(_sh.get("shift_start")) or _es_def, key=f"qe_e_s_{_sid}")
                        with _ec_b:
                            _e_end = _erp_time_input_30min("퇴근 시각", value=_erp_parse_time(_sh.get("shift_end")) or _ee_def, key=f"qe_e_e_{_sid}")
                        # 근무 장소 셀렉트 (실근무지 명시 선택)
                        _ETC_E_LABEL = "기타 (외부/행사) — 직접 입력"
                        _e_loc_opts = list(all_store_names) + [_ETC_E_LABEL]
                        _cur_loc = (_loc or "").strip()
                        _cur_db_sn = _dbf_to_sn.get(_sh.get("db_filename"), "")
                        if _cur_loc and _cur_loc not in all_store_names:
                            _e_default_label = _ETC_E_LABEL
                        elif _cur_loc in all_store_names:
                            _e_default_label = _cur_loc
                        elif _cur_db_sn in all_store_names:
                            _e_default_label = _cur_db_sn  # wloc 비어있으면 소속 매장 디폴트
                        else:
                            _e_default_label = _e_loc_opts[0] if _e_loc_opts else _ETC_E_LABEL
                        try:
                            _e_loc_idx = _e_loc_opts.index(_e_default_label)
                        except ValueError:
                            _e_loc_idx = 0
                        _e_loc_sel = st.selectbox(
                            "근무 장소 (실근무지)",
                            _e_loc_opts, index=_e_loc_idx, key=f"qe_e_loc_sel_{_sid}",
                            help="이 일정의 실제 근무 매장. 직원 소속과 무관하게 이 값으로 캘린더에 합산됩니다.",
                        )
                        _e_is_etc = (_e_loc_sel == _ETC_E_LABEL)
                        if _e_is_etc:
                            _e_loc_etc = st.text_input(
                                "외부 행사명/상세 위치",
                                value=_cur_loc if _cur_loc not in all_store_names else "",
                                key=f"qe_e_loc_etc_{_sid}",
                                placeholder="예: 유에코임주박람회 / 롯데백화점 행사장",
                            )
                            _e_final_loc = (_e_loc_etc or "").strip()
                        else:
                            _e_final_loc = _e_loc_sel
                        _e_note = st.text_input(
                            "비고 (특별근무 · 초과근무 사유 등)",
                            value=str(_sh.get("note") or ""),
                            key=f"qe_e_note_{_sid}",
                            placeholder="예: 행사 지원 / 인수인계 야근 / 명절 특근",
                            help="여기에 입력한 메모는 캘린더와 월말 요약 다운로드에 함께 표기됩니다.",
                        )
                        _eb1, _eb2, _ = st.columns([1, 1, 3])
                        with _eb1:
                            if st.button("💾 저장", type="primary", key=f"qe_e_save_{_sid}"):
                                if (_e_start.hour * 60 + _e_start.minute) >= (_e_end.hour * 60 + _e_end.minute):
                                    st.error("퇴근 시각이 출근 시각보다 늦어야 합니다.")
                                elif _e_is_etc and not _e_final_loc:
                                    st.error("외부 행사명/상세 위치를 입력해 주세요.")
                                else:
                                    # 소속 매장과 같으면 wloc 비움 (정합성)
                                    _wloc_e: str | None = _e_final_loc or None
                                    if _wloc_e and _wloc_e == _cur_db_sn:
                                        _wloc_e = None
                                    ok, e = _erp_update_row("app_shift_schedules", _sid, {
                                        "shift_start": _e_start.strftime("%H:%M:%S"),
                                        "shift_end": _e_end.strftime("%H:%M:%S"),
                                        "work_location_name": _wloc_e,
                                        "note": (_e_note or "").strip() or None,
                                    })
                                    if ok:
                                        # 매장 표준 대비 차이 자동 보정
                                        _cal_adj_db = _sh.get("db_filename") or edit_dbf
                                        _erp_collect_auto_adjustments(
                                            db_filename=_cal_adj_db,
                                            employee_name=qe_emp,
                                            shifts=[{
                                                "shift_date": _sd.isoformat(),
                                                "shift_start": _e_start.strftime("%H:%M:%S"),
                                                "shift_end": _e_end.strftime("%H:%M:%S"),
                                                "work_location_name": _wloc_e,
                                            }],
                                            source_tag="[자동-캘린더]",
                                            created_by=me_name,
                                            work_db_filename=_cal_adj_db,
                                            work_location_name=_wloc_e,
                                        )
                                        st.session_state.pop("qe_edit_id", None)
                                        st.session_state["_erp_cal_flash"] = f"{_sd.isoformat()} {qe_emp} 일정이 수정되었습니다. 표준 시간과 차이가 있으면 [정기근무일정] 화면 상단에서 연장 신청을 확인하세요."
                                        st.rerun(scope="fragment")
                                    else:
                                        st.error(f"저장 실패: {e}")
                        with _eb2:
                            if st.button("취소", key=f"qe_e_cancel_{_sid}"):
                                st.session_state.pop("qe_edit_id", None)
                                st.rerun(scope="fragment")
                else:
                    _is_chk = _sid in _checked_ids
                    rc = st.columns([0.4, 1.6, 1.8, 3, 0.9, 0.9])
                    with rc[0]:
                        _new_chk = st.checkbox("", value=_is_chk, key=f"qe_chk_{_sid}", label_visibility="collapsed")
                        if _new_chk != _is_chk:
                            _cur = st.session_state.get(_qe_chk_key, set())
                            if _new_chk:
                                _cur.add(_sid)
                            else:
                                _cur.discard(_sid)
                            st.session_state[_qe_chk_key] = _cur
                            st.rerun(scope="fragment")
                    with rc[1]:
                        _dow_c = "#E53935" if _sd.weekday() == 6 else ("#1565C0" if _sd.weekday() == 5 else "#37474F")
                        st.markdown(f"<span style='color:{_dow_c}; font-weight:600;'>{_sd.month}/{_sd.day} ({_ERP_DOW_LABELS[_sd.weekday()]})</span>", unsafe_allow_html=True)
                    with rc[2]:
                        st.markdown(f"{_ss}~{_ee}" if _ss and _ee else "-")
                    with rc[3]:
                        st.markdown(f"<span style='color:#607D8B;'>{_loc}</span>" if _loc else "<span style='color:#bbb;'>-</span>", unsafe_allow_html=True)
                    with rc[4]:
                        if st.button("✏️", key=f"qe_edit_btn_{_sid}", help="수정"):
                            st.session_state["qe_edit_id"] = _sid
                            st.rerun(scope="fragment")
                    with rc[5]:
                        if st.button("🗑️", key=f"qe_del_btn_{_sid}", help="삭제"):
                            _erp_delete_row("app_shift_schedules", _sid)
                            st.session_state.pop("qe_edit_id", None)
                            _cur = st.session_state.get(_qe_chk_key, set())
                            _cur.discard(_sid)
                            st.session_state[_qe_chk_key] = _cur
                            st.session_state["_erp_cal_flash"] = f"{_sd.isoformat()} {qe_emp} 일정이 삭제되었습니다."
                            st.rerun(scope="fragment")

        # ── ➕ 새 날짜 추가 ───────────────────────────────────────
        st.divider()
        st.markdown("**➕ 새 날짜 추가**")
        _add_c1, _add_c2, _add_c3 = st.columns([2, 1.5, 1.5])
        with _add_c1:
            qe_new_date = st.date_input(
                "날짜", value=today if period_start <= today <= period_end else period_start,
                min_value=period_start, max_value=period_end, key="qe_new_date_calendar",
            )
        _add_def_s, _add_def_e = _erp_default_times_for_date(edit_dbf, qe_new_date)
        with _add_c2:
            qe_new_start = _erp_time_input_30min("출근 시각", value=_add_def_s, key="qe_new_start_calendar")
        with _add_c3:
            qe_new_end = _erp_time_input_30min("퇴근 시각", value=_add_def_e, key="qe_new_end_calendar")
        # ── 근무 장소 선택 (명시적 선택 — 자동 추론 X, 직원 소속과 무관)
        #   실근무지 기준으로 저장되어 캘린더 카운팅·표시가 일치
        _ETC_LOC_LABEL = "기타 (외부/행사) — 직접 입력"
        _loc_opts = list(all_store_names) + [_ETC_LOC_LABEL]
        _default_loc_label = _ETC_LOC_LABEL if _qe_is_etc else (
            qe_store_sel if qe_store_sel in all_store_names else (_loc_opts[0] if _loc_opts else _ETC_LOC_LABEL)
        )
        try:
            _loc_idx = _loc_opts.index(_default_loc_label)
        except ValueError:
            _loc_idx = 0
        qe_new_loc_sel = st.selectbox(
            "근무 장소 (실근무지)",
            _loc_opts, index=_loc_idx, key="qe_new_loc_sel_calendar",
            help="이 일정이 실제로 수행되는 매장을 선택하세요. 직원 소속과 무관하게 이 값으로 캘린더에 합산됩니다.",
        )
        _is_loc_etc_sel = (qe_new_loc_sel == _ETC_LOC_LABEL)
        if _is_loc_etc_sel:
            qe_new_loc_etc = st.text_input(
                "외부 행사명/상세 위치", value="",
                key="qe_new_loc_etc_calendar",
                placeholder="예: 유에코임주박람회 / 롯데백화점 행사장",
            )
            _final_loc = (qe_new_loc_etc or "").strip()
        else:
            _final_loc = qe_new_loc_sel

        qe_new_note = st.text_input(
            "비고 (특별근무 · 초과근무 사유 등)",
            value="",
            key="qe_new_note_calendar",
            placeholder="예: 행사 지원 / 인수인계 야근 / 명절 특근",
            help="여기에 입력한 메모는 캘린더와 월말 요약 다운로드에 함께 표기됩니다.",
        )

        if st.button("➕ 이 날짜 추가", type="primary", key="qe_add_calendar"):
            if (qe_new_start.hour * 60 + qe_new_start.minute) >= (qe_new_end.hour * 60 + qe_new_end.minute):
                st.error("퇴근 시각이 출근 시각보다 늦어야 합니다.")
            elif _is_loc_etc_sel and not _final_loc:
                st.error("외부 행사명/상세 위치를 입력해 주세요.")
            elif any(str(s.get("shift_date") or "")[:10] == qe_new_date.isoformat() for s in _my_shifts):
                st.warning("이미 이 날짜에 등록된 일정이 있습니다. 위 목록에서 수정해 주세요.")
            else:
                # db_filename = 직원 본래 소속 (정체성 유지), work_location_name = 사용자가 명시 선택한 실근무지
                # 단, 소속 매장과 실근무지가 같으면 wloc 은 비워둠 (정합성)
                _add_db = _resolve_home_dbf(qe_emp, edit_dbf)
                _wloc_save: str | None = _final_loc or None
                if _wloc_save and _wloc_save == _dbf_to_sn.get(_add_db, ""):
                    _wloc_save = None
                ok, e = _erp_insert_row("app_shift_schedules", {
                    "db_filename": _add_db,
                    "employee_name": qe_emp,
                    "shift_date": qe_new_date.isoformat(),
                    "shift_start": qe_new_start.strftime("%H:%M:%S"),
                    "shift_end": qe_new_end.strftime("%H:%M:%S"),
                    "work_location_name": _wloc_save,
                    "note": (qe_new_note or "").strip() or None,
                    "created_by": me_name,
                })
                if ok:
                    # 매장 표준 대비 차이 자동 보정
                    _erp_collect_auto_adjustments(
                        db_filename=_add_db,
                        employee_name=qe_emp,
                        shifts=[{
                            "shift_date": qe_new_date.isoformat(),
                            "shift_start": qe_new_start.strftime("%H:%M:%S"),
                            "shift_end": qe_new_end.strftime("%H:%M:%S"),
                            "work_location_name": _wloc_save,
                        }],
                        source_tag="[자동-캘린더]",
                        created_by=me_name,
                        work_db_filename=_add_db,
                        work_location_name=_wloc_save,
                    )
                    _flash_loc = _final_loc or _dbf_to_sn.get(_add_db, "")
                    st.session_state["_erp_cal_flash"] = (
                        f"{qe_new_date.isoformat()} {qe_emp} 일정이 [{_flash_loc}] 근무로 추가되었습니다. "
                        f"표준 시간과 차이가 있으면 [정기근무일정] 상단에서 연장 신청을 확인하세요."
                    )
                    st.rerun(scope="fragment")
                else:
                    st.error(f"추가 실패: {e}")

    # ── ✨ 추가근무·회의 로그 수정 / 삭제 ──────────────────────────────
    with st.expander("✨ 추가근무·회의 로그 검색 / 수정 / 삭제", expanded=False):
        st.caption(
            "캘린더에 표시되는 추가근무·회의 기록(app_attendance_logs)을 직접 수정·삭제합니다. "
            "여기서 수정해도 원본 신청서(app_work_adjustments)는 변경되지 않습니다."
        )
        _ot_c1, _ot_c2, _ot_c3 = st.columns([1.2, 1.2, 1.6])
        with _ot_c1:
            _ot_emp_opts = ["(전체 직원)"] + sorted(set(all_emps))
            _ot_emp_def_idx = (
                _ot_emp_opts.index(selected_emp)
                if (selected_emp and selected_emp in _ot_emp_opts) else 0
            )
            _ot_emp = st.selectbox("직원 필터", _ot_emp_opts,
                                   index=_ot_emp_def_idx, key="ot_log_emp")
        with _ot_c2:
            _ot_kind = st.selectbox("유형", ["전체", "추가근무", "회의"], key="ot_log_kind")
        with _ot_c3:
            _ot_start = st.date_input("시작일", value=period_start, key="ot_log_start")
            _ot_end = st.date_input("종료일", value=period_end, key="ot_log_end")

        try:
            _ot_client, _ot_err = get_supabase_client()
            if _ot_err or not _ot_client:
                st.error(f"DB 연결 실패: {_ot_err}")
                _ot_rows = []
            else:
                _ot_types = ["추가근무", "회의"] if _ot_kind == "전체" else [_ot_kind]
                _ot_q = _ot_client.table("app_attendance_logs").select("*")\
                    .in_("work_type", _ot_types)\
                    .gte("log_date", _ot_start.isoformat())\
                    .lte("log_date", _ot_end.isoformat())\
                    .order("log_date", desc=True)
                _ot_rows = _ot_q.execute().data or []
                # 이름 정규화 + 직원 필터
                for _r in _ot_rows:
                    _r["_display_emp"] = _resolve(_r.get("employee_name") or "")
                if _ot_emp and _ot_emp != "(전체 직원)":
                    _ot_rows = [r for r in _ot_rows if r.get("_display_emp") == _ot_emp]
        except Exception as _ot_ex:
            st.error(f"조회 오류: {_ot_ex}")
            _ot_rows = []

        st.markdown(f"**📋 검색 결과: {len(_ot_rows)}건**")
        if not _ot_rows:
            st.info("조건에 해당하는 추가근무·회의 로그가 없습니다.")
        else:
            _ot_edit_id = st.session_state.get("ot_log_edit_id")
            for _ot in _ot_rows:
                _otid = int(_ot.get("id") or 0)
                try:
                    _odt = date.fromisoformat(str(_ot.get("log_date") or "")[:10])
                except Exception:
                    continue
                _ots = str(_ot.get("start_time") or "")[:5]
                _ote = str(_ot.get("end_time") or "")[:5]
                _ow_loc = _ot.get("work_location_name") or _dbf_to_sn.get(_ot.get("work_db_filename") or _ot.get("home_db_filename"), "")
                _own_wt = _ot.get("work_type") or ""
                _own_emp = _ot.get("_display_emp") or _ot.get("employee_name") or ""

                if _ot_edit_id == _otid:
                    with st.container(border=True):
                        st.markdown(f"**✏️ {_odt} · {_own_wt} · {_own_emp}**")
                        _oe_db = _ot.get("home_db_filename") or current_db
                        _oe_def_s, _oe_def_e = _erp_default_times_for_date(_oe_db, _odt)
                        _oe_c1, _oe_c2, _oe_c3 = st.columns([1, 1, 2])
                        with _oe_c1:
                            _ot_e_s = _erp_time_input_30min(
                                "시작 시간",
                                value=_erp_parse_time(_ot.get("start_time")) or _oe_def_s,
                                key=f"ot_e_s_{_otid}",
                            )
                        with _oe_c2:
                            _ot_e_e = _erp_time_input_30min(
                                "종료 시간",
                                value=_erp_parse_time(_ot.get("end_time")) or _oe_def_e,
                                key=f"ot_e_e_{_otid}",
                            )
                        with _oe_c3:
                            _OT_ETC = "기타 (외부/행사) — 직접 입력"
                            _ot_loc_opts = list(all_store_names) + [_OT_ETC]
                            _cur_loc_v = (_ot.get("work_location_name") or "").strip()
                            if _cur_loc_v and _cur_loc_v not in all_store_names:
                                _ot_def_loc = _OT_ETC
                            elif _cur_loc_v in all_store_names:
                                _ot_def_loc = _cur_loc_v
                            else:
                                _cur_db_sn2 = _dbf_to_sn.get(_ot.get("work_db_filename") or _ot.get("home_db_filename"), "")
                                _ot_def_loc = _cur_db_sn2 if _cur_db_sn2 in all_store_names else (_ot_loc_opts[0] if _ot_loc_opts else _OT_ETC)
                            try:
                                _ot_loc_idx = _ot_loc_opts.index(_ot_def_loc)
                            except ValueError:
                                _ot_loc_idx = 0
                            _ot_loc_sel = st.selectbox(
                                "근무지", _ot_loc_opts, index=_ot_loc_idx,
                                key=f"ot_e_loc_{_otid}",
                            )
                            if _ot_loc_sel == _OT_ETC:
                                _ot_loc_etc = st.text_input(
                                    "외부 행사명",
                                    value=_cur_loc_v if _cur_loc_v not in all_store_names else "",
                                    key=f"ot_e_loc_etc_{_otid}",
                                )
                                _ot_final_loc = (_ot_loc_etc or "").strip()
                                _ot_final_db = None
                            else:
                                _ot_final_loc = _ot_loc_sel
                                _ot_final_db = _sn_to_dbf.get(_ot_loc_sel)
                        _ot_note = st.text_input(
                            "사유/메모",
                            value=_ot.get("note") or "",
                            key=f"ot_e_note_{_otid}",
                        )
                        _ot_bs, _ot_bc2, _ = st.columns([1, 1, 3])
                        with _ot_bs:
                            if st.button("💾 저장", type="primary", key=f"ot_e_save_{_otid}"):
                                if (_ot_e_s.hour * 60 + _ot_e_s.minute) >= (_ot_e_e.hour * 60 + _ot_e_e.minute):
                                    st.error("종료 시간이 시작 시간보다 늦어야 합니다.")
                                else:
                                    _ot_diff = (_ot_e_e.hour * 60 + _ot_e_e.minute) - (_ot_e_s.hour * 60 + _ot_e_s.minute)
                                    _ot_patch = {
                                        "start_time": _ot_e_s.strftime("%H:%M:%S"),
                                        "end_time": _ot_e_e.strftime("%H:%M:%S"),
                                        "diff_minutes": _ot_diff,
                                        "work_location_name": _ot_final_loc or None,
                                        "work_db_filename": _ot_final_db,
                                        "note": (_ot_note or "").strip() or None,
                                    }
                                    _ok_ot, _err_ot = _erp_update_row("app_attendance_logs", _otid, _ot_patch)
                                    if not _ok_ot:
                                        _patch_min = {k: v for k, v in _ot_patch.items()
                                                      if k not in ("work_location_name", "work_db_filename")}
                                        _ok_ot, _err_ot = _erp_update_row("app_attendance_logs", _otid, _patch_min)
                                    if _ok_ot:
                                        st.session_state.pop("ot_log_edit_id", None)
                                        st.session_state["_erp_cal_flash"] = (
                                            f"{_odt} {_own_emp} {_own_wt} 로그가 수정되었습니다."
                                        )
                                        st.rerun(scope="fragment")
                                    else:
                                        st.error(f"저장 실패: {_err_ot}")
                        with _ot_bc2:
                            if st.button("취소", key=f"ot_e_cancel_{_otid}"):
                                st.session_state.pop("ot_log_edit_id", None)
                                st.rerun(scope="fragment")
                else:
                    _orc = st.columns([1.6, 1.4, 1.4, 2.6, 0.9, 0.9])
                    with _orc[0]:
                        _dow_c = "#E53935" if _odt.weekday() == 6 else ("#1565C0" if _odt.weekday() == 5 else "#37474F")
                        st.markdown(
                            f"<span style='color:{_dow_c}; font-weight:600;'>"
                            f"{_odt.month}/{_odt.day} ({_ERP_DOW_LABELS[_odt.weekday()]})</span>",
                            unsafe_allow_html=True,
                        )
                    with _orc[1]:
                        _wt_c = _ERP_BADGE_COLORS.get(_own_wt, "#90A4AE")
                        st.markdown(
                            f"<span style='background:{_wt_c}; color:white;"
                            f" padding:2px 6px; border-radius:3px; font-size:0.78rem;'>{_own_wt}</span>"
                            f" <b>{_own_emp}</b>",
                            unsafe_allow_html=True,
                        )
                    with _orc[2]:
                        st.markdown(f"{_ots}~{_ote}" if _ots and _ote else "-")
                    with _orc[3]:
                        st.markdown(
                            f"<span style='color:#607D8B;'>{_ow_loc}</span>"
                            + (f" · <span style='color:#999; font-size:0.8rem;'>{_ot.get('note')}</span>" if _ot.get("note") else ""),
                            unsafe_allow_html=True,
                        )
                    with _orc[4]:
                        if st.button("✏️", key=f"ot_edit_btn_{_otid}", help="수정"):
                            st.session_state["ot_log_edit_id"] = _otid
                            st.rerun(scope="fragment")
                    with _orc[5]:
                        if st.button("🗑️", key=f"ot_del_btn_{_otid}", help="삭제"):
                            _erp_delete_row("app_attendance_logs", _otid)
                            st.session_state.pop("ot_log_edit_id", None)
                            st.session_state["_erp_cal_flash"] = (
                                f"{_odt} {_own_emp} {_own_wt} 로그가 삭제되었습니다."
                            )
                            st.rerun(scope="fragment")

    # ── 범례 ────────────────────────────────────────────────────
    with st.expander("🎨 색상 범례"):
        col_sc, col_wt = st.columns(2)
        with col_sc:
            st.markdown("**매장별 색상**")
            parts = []
            for dbf in all_dbs:
                sc = store_color.get(dbf, "#666")
                sn = _dbf_to_sn.get(dbf, dbf)
                parts.append(
                    f"<span style='background:{sc}20; border-left:4px solid {sc};"
                    f" padding:2px 8px; border-radius:2px; color:{sc}; font-weight:bold;'>{sn}</span>"
                )
            # 외부 행사 색 추가
            parts.append(
                f"<span style='background:#7C3AED20; border-left:4px solid #7C3AED;"
                f" padding:2px 8px; border-radius:2px; color:#7C3AED; font-weight:bold;'>외부 행사·박람회</span>"
            )
            st.markdown(" &nbsp; ".join(parts), unsafe_allow_html=True)
        with col_wt:
            st.markdown("**근태 유형 배지**")
            wt_parts = [
                f"<span style='background:{c}; color:white; padding:1px 6px;"
                f" border-radius:3px; font-size:0.75rem;'>{wt}</span>"
                for wt, c in _ERP_BADGE_COLORS.items()
            ]
            st.markdown(" ".join(wt_parts), unsafe_allow_html=True)
        st.caption("컬러 바 = 근무 계획(shift) / 보라 = 외부 행사·박람회 / 배지 = 실제 근태 기록 / 파란 테두리 = 오늘 / 빨간 테두리 = 최소 인원 미달")


# ---------- (구) 탭 4 (v2.1 리팩터에서 제거됨) ----------
# _erp_tab_attendance_input 은 호출처가 없는 고아 함수였으므로 삭제.
# 근태 입력은 '내 근태' 탭 (_erp_tab_my_attendance) 과 '근무일정' 탭 (_erp_tab_shift_plan) 으로 통합됨.


# ---------- 탭 5: 추가근무 & 시차 관리 ----------

def _erp_tab_comptime_overtime(current_db: str, role: str, me_name: str):
    st.subheader("⏱️ 추가근무 & 시차 관리")
    today = _today_kst()

    if role in ("store_admin", "superadmin"):
        st.markdown("##### 🗓️ 주말 회의 시차 일괄 등록 (관리자)")
        st.caption("주말 회의 참석 직원 전체에게 시차적립을 일괄 INSERT 합니다.")
        with st.form("erp_weekend_meeting_form", clear_on_submit=True):
            mc = st.columns([1, 1, 2])
            with mc[0]:
                m_date = st.date_input("회의 날짜", value=today, key="erp_wm_date")
            with mc[1]:
                m_min = st.number_input("적립 분수", min_value=15, max_value=480, value=60, step=15, key="erp_wm_min")
            with mc[2]:
                emp_pool = _erp_get_employee_names_for_store(current_db)
                m_emps = st.multiselect("참석 직원", emp_pool, default=emp_pool, key="erp_wm_emps")
            m_note = st.text_input("비고", value="주말 회의", key="erp_wm_note")
            m_submit = st.form_submit_button("📥 일괄 등록")
        if m_submit:
            if not m_emps:
                st.warning("참석 직원을 1명 이상 선택해 주세요.")
            else:
                ok_n, err_n = 0, 0
                for emp in m_emps:
                    row = {
                        "home_db_filename": current_db,
                        "work_db_filename": current_db,
                        "employee_name": emp,
                        "log_date": m_date.isoformat(),
                        "work_type": "시차적립",
                        "leave_deduction": 0,
                        "diff_minutes": int(m_min),
                        "status": "approved",
                        "note": m_note,
                        "created_by": me_name,
                    }
                    ok, _ = _erp_insert_row("app_attendance_logs", row)
                    if ok:
                        ok_n += 1
                    else:
                        err_n += 1
                notify(f"일괄 등록 완료: {ok_n}건 / 실패 {err_n}건",
                       level=("success" if err_n == 0 else "warning"))
        st.divider()

    st.markdown("##### 🕒 시차 사용 신청")
    remain_min = _erp_compute_remaining_comptime(current_db, me_name) if role == "user" else None
    if role == "user":
        st.caption(f"내 잔여 시차: **{remain_min}분** ({remain_min // 60}시간 {remain_min % 60}분)")
    with st.form("erp_comp_use_form", clear_on_submit=True):
        cc = st.columns(3)
        with cc[0]:
            if role in ("store_admin", "superadmin"):
                emp_opts = _erp_get_employee_names_for_store(current_db) or [me_name]
                cu_emp = st.selectbox("직원", emp_opts, key="erp_cu_emp")
            else:
                cu_emp = me_name
                st.text_input("직원", value=me_name, disabled=True, key="erp_cu_emp_fixed")
        with cc[1]:
            cu_date = st.date_input("날짜", value=today, key="erp_cu_date")
        with cc[2]:
            cu_min = st.number_input("사용 분수", min_value=15, max_value=480, value=60, step=15, key="erp_cu_min")
        cu_note = st.text_input("사유", value="", key="erp_cu_note")
        cu_submit = st.form_submit_button("➡️ 신청")
    if cu_submit:
        emp_remain = _erp_compute_remaining_comptime(current_db, cu_emp)
        status = "approved" if emp_remain >= int(cu_min) else "pending"
        row = {
            "home_db_filename": current_db,
            "work_db_filename": current_db,
            "employee_name": cu_emp,
            "log_date": cu_date.isoformat(),
            "work_type": "시차사용",
            "leave_deduction": 0,
            "diff_minutes": int(cu_min),
            "status": status,
            "note": cu_note,
            "created_by": me_name,
        }
        ok, err = _erp_insert_row("app_attendance_logs", row)
        if ok:
            if status == "approved":
                st.success(f"✅ 잔여 {emp_remain}분 → 즉시 승인 (사용 {cu_min}분)")
            else:
                st.warning(f"⚠️ 잔여 {emp_remain}분 < 사용 {cu_min}분 → 관리자 승인 대기 (pending)")
        else:
            st.error(f"저장 실패: {err}")

    st.divider()
    st.markdown("##### 📝 추가근무 보상 신청")
    st.caption("목표 근무시간 초과분에 대해 보상 방식을 선택할 수 있습니다. 시차/연차는 자동 반영, 급여 청구는 관리자 승인 필요.")

    # 본인 잔여(시차/연차) 표시 — 선택 가이드
    _me_for_balance = me_name if role == "user" else None
    if role == "user":
        _my_comp = _erp_compute_remaining_comptime(current_db, me_name)
        _my_leave = _erp_compute_leave_status(current_db, me_name, today)
        _bc1, _bc2 = st.columns(2)
        with _bc1:
            st.caption(f"💼 내 잔여 시차: **{_my_comp}분** ({_my_comp // 60}h {_my_comp % 60}m)")
        with _bc2:
            st.caption(f"🎫 내 잔여 연차: **{_my_leave['annual_remain']:g}일**")

    with st.form("erp_overtime_form", clear_on_submit=True):
        oc = st.columns(4)
        with oc[0]:
            if role in ("store_admin", "superadmin"):
                ov_emp = st.selectbox("직원", _erp_get_employee_names_for_store(current_db) or [me_name], key="erp_ov_emp")
            else:
                ov_emp = me_name
                st.text_input("직원", value=me_name, disabled=True, key="erp_ov_emp_fixed")
        with oc[1]:
            ov_date = st.date_input("날짜", value=today, key="erp_ov_date")
        with oc[2]:
            ov_start = _erp_time_input_30min("시작", value=dt_time(18, 0), key="erp_ov_start")
        with oc[3]:
            ov_end = _erp_time_input_30min("종료", value=dt_time(20, 0), key="erp_ov_end")
        ov_loc = st.text_input("근무 장소", value="", key="erp_ov_loc")
        ov_comp_type = st.selectbox(
            "💰 보상 방식 선택",
            options=["comp_time", "leave_swap", "payment"],
            format_func=lambda x: _ERP_COMP_TYPE_LABELS.get(x, x),
            key="erp_ov_comp_type",
            help="시차 적립: 잔여 시차에 즉시 추가 / 연차로 대체: 분수를 일수로 환산해 연차에 가산 / 급여 청구: 관리자 승인 후 급여 처리",
        )
        ov_reason = st.text_input("사유", value="", key="erp_ov_reason")
        ov_submit = st.form_submit_button("➡️ 신청", type="primary")

    if ov_submit:
        mins = _erp_minutes_between(ov_start, ov_end)
        if mins <= 0:
            st.error("종료 시각이 시작 시각보다 늦어야 합니다.")
        elif not (ov_reason or "").strip():
            st.error("사유를 입력해 주세요.")
        else:
            # 1) app_overtime_requests 에 기존대로 기록 (이력/감사용)
            req_row = {
                "home_db_filename": current_db,
                "employee_name": ov_emp,
                "request_date": ov_date.isoformat(),
                "work_location_name": (ov_loc or "").strip() or None,
                "extra_start": ov_start.strftime("%H:%M:%S"),
                "extra_end": ov_end.strftime("%H:%M:%S"),
                "extra_minutes": mins,
                "reason": f"[{_ERP_COMP_TYPE_LABELS.get(ov_comp_type, ov_comp_type)}] {ov_reason}",
                "status": "approved" if ov_comp_type != "payment" else "pending",
                "created_by": me_name,
            }
            _erp_insert_row("app_overtime_requests", req_row)

            # 2) 보상 방식별 처리
            _claim_status = "pending" if ov_comp_type == "payment" else "approved"
            _claim_row = {
                "db_filename": current_db,
                "employee_name": ov_emp,
                "claim_date": ov_date.isoformat(),
                "minutes": int(mins),
                "compensation_type": ov_comp_type,
                "reason": ov_reason.strip(),
                "status": _claim_status,
                "created_by": me_name,
            }
            if _claim_status == "approved":
                _claim_row["approved_by"] = me_name
                _claim_row["approved_at"] = datetime.now(timezone.utc).isoformat()

            ok, err = _erp_insert_row("app_overtime_claims", _claim_row)
            if not ok:
                st.error(f"보상 신청 저장 실패: {err}. 'app_overtime_claims' 테이블이 없으면 SUPABASE_APP_ATTENDANCE_COUNTER.sql 을 먼저 실행해 주세요.")
            else:
                _erp_overtime_claims_cached.clear()
                # 시차 적립: attendance_logs 에 '시차적립' approved 행 추가 → 잔여 시차 즉시 증가
                if ov_comp_type == "comp_time":
                    _erp_insert_row("app_attendance_logs", {
                        "home_db_filename": current_db,
                        "work_db_filename": current_db,
                        "employee_name": ov_emp,
                        "log_date": ov_date.isoformat(),
                        "work_type": "시차적립",
                        "leave_deduction": 0,
                        "diff_minutes": int(mins),
                        "status": "approved",
                        "note": f"[추가근무 보상] {ov_reason}",
                        "created_by": me_name,
                    })
                    flash(f"✅ 시차 {mins}분 적립 완료. 잔여 시차에 즉시 반영됩니다.")
                # 연차로 대체: app_leave_grants 의 annual_days 에 (분/480) 일을 0.5 단위로 가산
                elif ov_comp_type == "leave_swap":
                    _days_add = round(mins / 480 * 2) / 2  # 0.5 단위 반올림
                    if _days_add <= 0:
                        flash(f"⚠️ 추가 분수({mins}분)가 0.25일 미만이라 연차로 반올림되지 않았습니다. 시차 적립을 권장합니다.", level="warning")
                    else:
                        _yr = ov_date.year
                        _grants = _erp_fetch_table("app_leave_grants", {
                            "home_db_filename": current_db,
                            "employee_name": ov_emp,
                            "year": _yr,
                        })
                        if _grants:
                            _gr = _grants[0]
                            _new_days = float(_gr.get("annual_days") or 0) + _days_add
                            _erp_update_row("app_leave_grants", int(_gr["id"]), {
                                "annual_days": _new_days,
                                "adjustment_note": (_gr.get("adjustment_note") or "") + f" [+{_days_add:g}일: 추가근무 대체]",
                                "updated_at": datetime.now(timezone.utc).isoformat(),
                            })
                        else:
                            _erp_insert_row("app_leave_grants", {
                                "home_db_filename": current_db,
                                "employee_name": ov_emp,
                                "hire_date": today.isoformat(),
                                "year": _yr,
                                "annual_days": _days_add,
                                "adjustment_note": f"[추가근무 대체 +{_days_add:g}일]",
                                "created_by": me_name,
                                "updated_at": datetime.now(timezone.utc).isoformat(),
                            })
                        flash(f"✅ 연차 {_days_add:g}일 가산 완료 ({mins}분 → {_days_add:g}일). 연차/월차 관리 탭에서 확인할 수 있습니다.")
                # 급여 청구: pending. 관리자가 승인해야 처리됨
                else:
                    flash(f"💸 급여 청구 {mins}분이 접수되었습니다. 관리자 승인 후 처리됩니다.")
                st.rerun()

    if role in ("store_admin", "superadmin"):
        st.divider()
        st.markdown("##### ✅ 추가근무 승인 대기 목록 (관리자)")
        pending = _erp_fetch_table("app_overtime_requests", {"home_db_filename": current_db, "status": "pending"})
        if not pending:
            st.info("대기 중인 추가근무 신청이 없습니다.")
        else:
            for req in pending:
                rc = st.columns([2, 2, 1, 1, 1, 1])
                with rc[0]:
                    st.text(f"{req.get('request_date')} {req.get('employee_name')}")
                with rc[1]:
                    st.caption(f"{str(req.get('extra_start') or '')[:5]}~{str(req.get('extra_end') or '')[:5]} "
                                f"({req.get('extra_minutes')}분) @ {req.get('work_location_name') or '-'}")
                with rc[2]:
                    st.caption(f"사유: {req.get('reason') or '-'}")
                with rc[3]:
                    if st.button("승인", key=f"erp_ov_app_{req['id']}", type="primary"):
                        ok, _ = _erp_update_row("app_overtime_requests", int(req["id"]), {
                            "status": "approved",
                            "reviewed_by": me_name,
                            "reviewed_at": datetime.now(timezone.utc).isoformat(),
                        })
                        if ok:
                            st.rerun()
                with rc[4]:
                    if st.button("반려", key=f"erp_ov_rej_{req['id']}"):
                        ok, _ = _erp_update_row("app_overtime_requests", int(req["id"]), {
                            "status": "rejected",
                            "reviewed_by": me_name,
                            "reviewed_at": datetime.now(timezone.utc).isoformat(),
                        })
                        if ok:
                            st.rerun()
                with rc[5]:
                    st.caption(f"신청: {str(req.get('created_at') or '')[:16]}")

        st.divider()
        st.markdown("##### ✅ 시차 사용 승인 대기 목록 (관리자)")
        comp_pending = _erp_fetch_table("app_attendance_logs", {"home_db_filename": current_db})
        comp_pending = [r for r in comp_pending if r.get("work_type") == "시차사용" and (r.get("status") or "approved") == "pending"]
        if not comp_pending:
            st.info("대기 중인 시차 사용이 없습니다.")
        else:
            for req in comp_pending:
                rc = st.columns([2, 2, 2, 1, 1])
                with rc[0]:
                    st.text(f"{req.get('log_date')} {req.get('employee_name')}")
                with rc[1]:
                    st.caption(f"사용: {req.get('diff_minutes')}분")
                with rc[2]:
                    cur_remain = _erp_compute_remaining_comptime(current_db, req.get('employee_name'))
                    st.caption(f"현재 잔여: {cur_remain}분 / 사유: {req.get('note') or '-'}")
                with rc[3]:
                    if st.button("승인", key=f"erp_cu_app_{req['id']}", type="primary"):
                        _erp_update_row("app_attendance_logs", int(req["id"]), {"status": "approved"})
                        st.rerun()
                with rc[4]:
                    if st.button("반려(삭제)", key=f"erp_cu_rej_{req['id']}"):
                        _erp_delete_row("app_attendance_logs", int(req["id"]))
                        st.rerun()

        st.divider()
        st.markdown("##### 🗓️ 주말·공휴일 연차/반차 승인 대기 목록 (관리자)")
        st.caption("직원이 주말·공휴일에 연차 또는 반차를 기록하면 여기에 표시됩니다. 승인하면 연차 차감이 확정됩니다.")
        all_att_logs = _erp_fetch_table("app_attendance_logs", {"home_db_filename": current_db})
        leave_pending = [
            r for r in all_att_logs
            if r.get("work_type") in ("연차", "반차") and (r.get("status") or "approved") == "pending"
        ]
        if not leave_pending:
            st.info("대기 중인 주말·공휴일 연차/반차 신청이 없습니다.")
        else:
            for req in leave_pending:
                rc = st.columns([2, 2, 1, 1, 1])
                with rc[0]:
                    log_d = req.get("log_date", "")
                    dow = ""
                    try:
                        _ld = date.fromisoformat(str(log_d)[:10])
                        dow = f"({_ERP_DOW_LABELS[_ld.weekday()]})"
                    except Exception:
                        pass
                    st.text(f"{log_d}{dow}  {req.get('employee_name')}")
                with rc[1]:
                    st.caption(f"유형: {req.get('work_type')}  |  차감: {req.get('leave_deduction')}일  |  사유: {req.get('note') or '-'}")
                with rc[2]:
                    st.caption(f"신청: {str(req.get('created_at') or '')[:10]}")
                with rc[3]:
                    if st.button("승인", key=f"erp_lv_app_{req['id']}", type="primary"):
                        _erp_update_row("app_attendance_logs", int(req["id"]), {
                            "status": "approved",
                            "note": (req.get("note") or "") + f" [승인: {me_name}]",
                        })
                        st.rerun()
                with rc[4]:
                    if st.button("반려(삭제)", key=f"erp_lv_rej_{req['id']}"):
                        _erp_delete_row("app_attendance_logs", int(req["id"]))
                        st.rerun()

        # ── 급여 청구 승인 대기 ──────────────────────────────────
        st.divider()
        st.markdown("##### 💸 급여 청구 승인 대기 목록 (관리자)")
        st.caption("직원이 추가근무 보상을 '급여 청구'로 신청한 건입니다. 승인하면 급여에 반영하실 수 있습니다.")
        _all_claims = _erp_overtime_claims_cached(current_db, status="pending")
        _pay_claims = [c for c in _all_claims if c.get("compensation_type") == "payment"]
        if not _pay_claims:
            st.info("대기 중인 급여 청구가 없습니다.")
        else:
            for cl in _pay_claims:
                rc = st.columns([2, 2, 2, 1, 1])
                _mins = int(cl.get("minutes") or 0)
                _hh, _mm = divmod(_mins, 60)
                with rc[0]:
                    st.text(f"{cl.get('claim_date')}  {cl.get('employee_name')}")
                with rc[1]:
                    st.caption(f"추가근무: {_hh}h {_mm}m ({_mins}분)")
                with rc[2]:
                    st.caption(f"사유: {cl.get('reason') or '-'}  |  신청: {str(cl.get('created_at') or '')[:16]}")
                with rc[3]:
                    if st.button("승인", key=f"erp_pay_app_{cl['id']}", type="primary"):
                        ok, e = _erp_update_row("app_overtime_claims", int(cl["id"]), {
                            "status": "approved",
                            "approved_by": me_name,
                            "approved_at": datetime.now(timezone.utc).isoformat(),
                        })
                        if ok:
                            _erp_overtime_claims_cached.clear()
                            flash(f"💸 {cl.get('employee_name')} 님의 급여 청구 {_hh}h {_mm}m 이 승인되었습니다.")
                            st.rerun()
                        else:
                            st.error(f"승인 실패: {e}")
                with rc[4]:
                    if st.button("반려", key=f"erp_pay_rej_{cl['id']}"):
                        ok, e = _erp_update_row("app_overtime_claims", int(cl["id"]), {
                            "status": "rejected",
                            "approved_by": me_name,
                            "approved_at": datetime.now(timezone.utc).isoformat(),
                        })
                        if ok:
                            _erp_overtime_claims_cached.clear()
                            flash(f"급여 청구가 반려되었습니다.", level="warning")
                            st.rerun()
                        else:
                            st.error(f"반려 실패: {e}")


# ---------- 탭 6: 연차/월차 관리 (store_admin) ----------

def _erp_tab_leave_grants(current_db: str, me_name: str):
    st.subheader("🎫 연차/월차 관리")
    today = _today_kst()

    st.markdown("##### ✏️ 직원별 입사일·연차 부여 및 수동 조정")
    employees = _erp_get_employee_names_for_store(current_db)
    if not employees:
        st.info("이 매장에 배정된 직원이 없습니다.")
        return

    # 폼 외부에서 직원·연도 먼저 선택 → 기존 데이터 즉시 로드
    _lg_col1, _lg_col2 = st.columns([2, 1])
    with _lg_col1:
        g_emp = st.selectbox("직원 선택", employees, key="erp_lg_emp")
    with _lg_col2:
        g_year = st.number_input("연도", min_value=2020, max_value=2100,
                                 value=today.year, step=1, key="erp_lg_year")

    # 기존 저장 데이터 로드
    _existing_grants = _erp_fetch_table("app_leave_grants", {
        "home_db_filename": current_db,
        "employee_name": g_emp,
        "year": int(g_year),
    })
    _existing = _existing_grants[0] if _existing_grants else {}
    _saved_hire   = _existing.get("hire_date")
    _saved_days   = float(_existing.get("annual_days") or 15.0)
    _saved_note   = _existing.get("adjustment_note") or ""

    _hire_default = date.fromisoformat(_saved_hire) if _saved_hire else today

    # 입사일 입력 → 근로기준법 자동 계산 즉시 표시 (폼 외부)
    g_hire = st.date_input("입사일", value=_hire_default, key="erp_lg_hire")
    _legal = _erp_calc_legal_leave(g_hire, int(g_year))
    _auto_days = _legal["total_days"]
    _extra = _legal["long_service_extra"]
    _yos   = _legal["years_of_service"]

    # 장기근속 산출 내역 카드
    _lc_bg = "#E8F5E9" if _extra > 0 else "#F3F4F6"
    _lc_border = "#43A047" if _extra > 0 else "#9E9E9E"
    st.markdown(
        f"<div style='background:{_lc_bg};border-left:4px solid {_lc_border};"
        f"border-radius:4px;padding:10px 14px;margin-bottom:10px;font-size:0.88rem;'>"
        f"<b>📋 근로기준법 제60조 자동 계산 결과</b><br>"
        f"근속연수: <b>{_yos}년</b> &nbsp;|&nbsp; "
        f"기본 연차: <b>15일</b> &nbsp;|&nbsp; "
        f"장기근속 가산: <b>+{_extra}일</b> &nbsp;|&nbsp; "
        f"<b style='font-size:1.05rem;'>총 {_auto_days:g}일</b><br>"
        f"<span style='color:#666;font-size:0.8rem;'>{_legal['note']}</span>"
        f"</div>",
        unsafe_allow_html=True,
    )

    # 자동 계산값 초기화 버튼 (폼 외부 — 클릭 시 session_state 통해 폼 기본값 교체)
    _init_key = "erp_lg_days_init"
    if st.button(f"⚡ 자동 계산값({_auto_days:g}일)으로 초기화", key="erp_lg_auto_fill"):
        st.session_state[_init_key] = _auto_days
        st.rerun()
    _days_init_value = st.session_state.pop(_init_key, _saved_days)

    with st.form("erp_leave_grant_form", clear_on_submit=False):
        st.markdown("**최종 연차 부여 설정** *(자동 계산값이 기본값 — 수동 조정 가능)*")
        fc1, fc2 = st.columns([1, 2])
        with fc1:
            g_days = st.number_input(
                "최종 연차 부여 일수",
                min_value=0.0, max_value=40.0,
                value=float(_days_init_value), step=0.5,
                key="erp_lg_days",
                help=(
                    f"근로기준법 자동 계산: {_auto_days:g}일 (기본 15일 + 장기근속 {_extra}일). "
                    "기존 직원 중 이미 소진된 연차가 있거나 별도 합의한 경우 직접 조정하세요."
                ),
            )
        with fc2:
            g_note = st.text_input(
                "조정 사유 (선택)",
                value=_saved_note,
                key="erp_lg_note",
                placeholder="예: 기존 장기근속 소진 반영 / 협의 조정 / 이월 포함",
            )
        _adj_delta = g_days - _auto_days
        _sign = "+" if _adj_delta >= 0 else ""
        if abs(_adj_delta) > 0:
            st.info(
                f"ℹ️ 자동 계산 대비 **{_sign}{_adj_delta:g}일** 수동 조정 "
                f"(자동 {_auto_days:g}일 → 최종 {g_days:g}일)"
            )
        else:
            st.caption(f"✅ 자동 계산값({_auto_days:g}일)과 동일하게 설정됨")
        g_submit = st.form_submit_button("💾 저장", type="primary")

    if g_submit:
        row = {
            "home_db_filename": current_db,
            "employee_name": g_emp,
            "hire_date": g_hire.isoformat(),
            "year": int(g_year),
            "annual_days": float(g_days),
            "adjustment_note": (g_note or "").strip() or None,
            "created_by": me_name,
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }
        if _existing:
            ok, err = _erp_update_row("app_leave_grants", int(_existing["id"]), row)
        else:
            ok, err = _erp_insert_row("app_leave_grants", row)
        if ok:
            flash(f"{g_emp} / {int(g_year)}년 연차 {g_days:g}일 저장이 완료되었습니다.")
            st.rerun()
        else:
            st.error(f"저장 실패: {err}")

    st.divider()
    st.markdown("##### 📊 직원별 연차/월차 현황")
    year_for_view = st.number_input("조회 연도", min_value=2020, max_value=2100, value=today.year, step=1, key="erp_lg_view_year")
    year_start = date(int(year_for_view), 1, 1)
    year_end = date(int(year_for_view), 12, 31)

    logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", current_db, "log_date", year_start, year_end)
    rows = []
    for emp in employees:
        grants = _erp_fetch_table("app_leave_grants", {
            "home_db_filename": current_db,
            "employee_name": emp,
            "year": int(year_for_view),
        })
        grant = grants[0] if grants else {}
        annual = float(grant.get("annual_days") or 0)
        hire = grant.get("hire_date")
        emp_logs = [l for l in logs if (l.get("employee_name") or "") == emp]
        annual_used = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "연차")
        half_used = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "반차")
        monthly_accrued = _erp_compute_monthly_accrued(hire, today if today.year == int(year_for_view) else date(int(year_for_view), 12, 31))
        comp_remain = _erp_compute_remaining_comptime(current_db, emp)
        # 장기근속 계산
        _emp_legal: dict = {}
        if hire:
            try:
                _emp_legal = _erp_calc_legal_leave(date.fromisoformat(str(hire)[:10]), int(year_for_view))
            except Exception:
                pass
        _emp_yos   = _emp_legal.get("years_of_service", "-")
        _emp_extra = _emp_legal.get("long_service_extra", 0)
        _emp_auto  = _emp_legal.get("total_days", "-")
        rows.append({
            "직원명": emp,
            "입사일": hire or "-",
            "근속연수": f"{_emp_yos}년" if hire else "-",
            "법정 연차(자동)": f"{_emp_auto:g}일" if _emp_legal else "-",
            "장기근속+": f"+{_emp_extra}일" if _emp_extra > 0 else "-",
            "부여 연차(최종)": annual,
            "연차사용": annual_used,
            "잔여연차": annual - annual_used,
            "월차적립": monthly_accrued,
            "월차사용(반차합)": half_used,
            "잔여월차": monthly_accrued - half_used,
            "잔여시차(분)": comp_remain,
        })
    if rows:
        df = pd.DataFrame(rows)
        st.dataframe(df, width='stretch', hide_index=True)
    else:
        st.info("표시할 데이터가 없습니다.")

    # ── 직원 포상시간 부여 (관리자) ────────────────────────────
    st.divider()
    st.markdown("##### 🏅 직원 포상시간 부여")
    st.caption("관리자가 직원에게 보상으로 주는 시간입니다. 부여 즉시 직원의 월 근무 카운터에서 자동으로 차감됩니다(일한 것처럼 인정).")

    with st.form("erp_bonus_hours_form", clear_on_submit=True):
        bc1, bc2, bc3 = st.columns([2, 1, 1])
        with bc1:
            bh_emp = st.selectbox("직원", employees, key="erp_bh_emp")
        with bc2:
            bh_date = st.date_input("부여 날짜", value=today, key="erp_bh_date")
        with bc3:
            bh_minutes = st.number_input("분수", min_value=15, max_value=2880, value=240, step=15,
                                         key="erp_bh_minutes",
                                         help="포상으로 인정할 분수. 예: 4시간=240분, 1일=480분")
        bh_note = st.text_input("사유", value="", key="erp_bh_note",
                                placeholder="예: 우수 실적 포상 / 행사 지원 보상 / 휴일 출근 대체")
        bh_submit = st.form_submit_button("🏅 포상시간 부여", type="primary")

    if bh_submit:
        if not (bh_note or "").strip():
            st.error("사유를 입력해 주세요.")
        else:
            _bh_row = {
                "home_db_filename": current_db,
                "work_db_filename": current_db,
                "employee_name": bh_emp,
                "log_date": bh_date.isoformat(),
                "work_type": "포상시간",
                "leave_deduction": 0,
                "diff_minutes": int(bh_minutes),
                "status": "approved",
                "note": bh_note.strip(),
                "created_by": me_name,
            }
            ok, e = _erp_insert_row("app_attendance_logs", _bh_row)
            if ok:
                _hh, _mm = divmod(int(bh_minutes), 60)
                flash(f"🏅 {bh_emp} 님에게 포상시간 {_hh}시간 {_mm}분이 부여되었습니다. 월 카운터에 즉시 반영됩니다.")
                st.rerun()
            else:
                st.error(f"부여 실패: {e}")

    # 부여 이력 조회
    _bh_year = today.year
    _bh_logs = _erp_fetch_range(
        "app_attendance_logs", "home_db_filename", current_db,
        "log_date", date(_bh_year, 1, 1), date(_bh_year, 12, 31),
    )
    _bh_history = [l for l in _bh_logs if l.get("work_type") == "포상시간"]
    if _bh_history:
        st.caption(f"올해 부여 이력: {len(_bh_history)}건")
        _bh_history_sorted = sorted(_bh_history, key=lambda x: str(x.get("log_date") or ""), reverse=True)
        _bh_df = pd.DataFrame([
            {
                "날짜": l.get("log_date"),
                "직원": l.get("employee_name"),
                "시간": f"{int(l.get('diff_minutes') or 0) // 60}h {int(l.get('diff_minutes') or 0) % 60}m",
                "분수": int(l.get("diff_minutes") or 0),
                "사유": l.get("note") or "",
                "부여자": l.get("created_by") or "",
            } for l in _bh_history_sorted[:30]
        ])
        st.dataframe(_bh_df, width='stretch', hide_index=True)


# =====================================================================
# 💬 Solapi 수동 메시지 발송
# =====================================================================

def render_send_message():
    """Solapi를 통해 친구톡 또는 SMS를 수동으로 발송하는 UI."""
    st.title("💬 메시지 발송")
    st.caption("Solapi를 통해 카카오 친구톡 또는 SMS를 수동으로 발송합니다.")

    try:
        from solapi_sender import send_friendtalk, send_sms, check_solapi_config  # noqa: WPS433
    except ImportError:
        st.error("solapi_sender 모듈을 불러올 수 없습니다. 파일이 존재하는지 확인해 주세요.")
        return

    # ── Solapi 설정 진단 탭 ──────────────────────────────────
    _tab_send, _tab_diag = st.tabs(["📤 발송", "⚙️ 설정 확인"])

    with _tab_diag:
        st.subheader("Solapi 연결 상태")
        _cfg = check_solapi_config()
        _rows = [
            ("api_key", "API Key (발신 인증)"),
            ("api_secret", "API Secret"),
            ("pf_id", "카카오 채널 PF ID"),
            ("sender", "발신번호"),
        ]
        for _k, _label in _rows:
            _ok = _cfg[_k]
            st.markdown(f"{'✅' if _ok else '❌'} **{_label}** — {'로드됨' if _ok else '**누락**'}")

        st.divider()
        st.markdown(f"**로드 경로:** {_cfg['source']}")
        st.markdown(f"**api_key 앞 4자리:** `{_cfg['api_key_hint']}`")
        if _cfg["all_ok"]:
            st.success("모든 키가 정상 로드되었습니다. 발송 탭에서 테스트해 주세요.")
        else:
            st.error("누락된 키가 있습니다. 아래 진단 상세를 확인해 주세요.")
            st.info(
                "**로컬:** `.streamlit/secrets.toml` 의 `[solapi]` 섹션  \n"
                "**Render:** Environment 탭에서 아래 4개 환경변수 등록  \n"
                "`SOLAPI_API_KEY` / `SOLAPI_API_SECRET` / `SOLAPI_SENDER` / `SOLAPI_PF_ID`"
            )

        # ── 단계별 진단 상세 ─────────────────────
        st.divider()
        st.subheader("🔍 소스별 진단 상세")
        st.json(_cfg.get("sources_detail", {}))

    with _tab_send:
        with st.form("manual_send_form", clear_on_submit=False):
            msg_type = st.selectbox(
                "메시지 유형",
                ["친구톡 (FriendTalk)", "SMS / LMS"],
                help="친구톡: 카카오채널 친구인 고객에게 전송. SMS: 친구 여부 무관하게 문자 전송.",
            )
            to_phone = st.text_input(
                "수신자 전화번호",
                placeholder="01012345678 (숫자만 또는 하이픈 포함)",
            )
            body = st.text_area(
                "메시지 내용",
                height=160,
                placeholder="발송할 메시지를 입력하세요.",
            )
            submitted = st.form_submit_button("📤 발송", type="primary", width="stretch")

        if submitted:
            if not to_phone.strip():
                st.warning("수신자 전화번호를 입력해 주세요.")
            elif not body.strip():
                st.warning("메시지 내용을 입력해 주세요.")
            else:
                with st.spinner("발송 중..."):
                    if msg_type.startswith("친구톡"):
                        result = send_friendtalk(to_phone.strip(), body.strip())
                    else:
                        result = send_sms(to_phone.strip(), body.strip())

                status = result.get("status", "")
                msg_id = result.get("msg_id")
                error = result.get("error")

                if status == "sent":
                    st.success(f"✅ 발송 성공! (msg_id: {msg_id or '—'})")
                elif status == "skipped" and error == "solapi_secrets_missing":
                    st.error("❌ Solapi 키 미로드 — ⚙️ 설정 확인 탭을 눌러 누락된 키를 확인하세요.")
                elif status == "skipped":
                    st.warning(f"⚠️ 발송 보류: {error}")
                elif status == "out_of_hours":
                    st.warning("🌙 야간 시간대(21:00~08:00)로 인해 발송이 거부되었습니다.")
                elif status == "not_friend":
                    st.warning("👥 카카오채널 친구가 아닙니다. SMS로 재시도해 주세요.")
                elif status == "lms_fallback":
                    st.info(f"📩 LMS로 대체 발송 완료 (msg_id: {msg_id or '—'})")
                else:
                    st.error(f"❌ 발송 실패: {error}")

                with st.expander("응답 상세 보기"):
                    st.json(result.get("raw") or {"status": status, "error": error})


# =====================================================================
# 📊 고객의 소리(VOC) 분석 대시보드
# =====================================================================

def render_voc_dashboard():
    """AI 기반 채널톡 VOC 분석 대시보드.

    실시간(webhook) 및 일괄 임포트(엑셀) 두 경로로 수집된
    app_voc_insights 데이터를 시각화한다.
    """
    import plotly.express as _px

    st.title("📊 고객의 소리(VOC) 분석")
    st.caption("채널톡 상담 종료 시 AI(Gemini 1.5 Flash)가 자동 분석한 VOC 인사이트입니다.")

    supa, _err = get_supabase_client()
    if _err or not supa:
        st.error("Supabase 연결이 필요합니다.")
        return

    # ── 기간 필터 ────────────────────────────────────────────────
    _col_period, _col_blank = st.columns([2, 5])
    with _col_period:
        _period = st.selectbox(
            "조회 기간",
            ["이번 주", "이번 달", "최근 3개월", "전체"],
            key="voc_period",
        )
    from datetime import date as _date, timedelta as _td
    _today = _date.today()
    if _period == "이번 주":
        _from = (_today - _td(days=_today.weekday())).isoformat()
    elif _period == "이번 달":
        _from = _today.replace(day=1).isoformat()
    elif _period == "최근 3개월":
        _from = (_today - _td(days=90)).isoformat()
    else:
        _from = "2000-01-01"

    # ── 데이터 로드 ──────────────────────────────────────────────
    try:
        _resp = supa.table("app_voc_insights").select("*")\
            .gte("analyzed_at", _from)\
            .order("analyzed_at", desc=True)\
            .execute()
        _rows = _resp.data or []
    except Exception as _e:
        st.error(f"데이터 조회 실패: {_e}")
        return

    # ── 데이터 없음 처리 ────────────────────────────────────────
    if not _rows:
        st.info("해당 기간에 분석된 VOC 데이터가 없습니다.")
        st.caption("채널톡에서 상담이 종료되면 자동으로 분석됩니다. 또는 아래 과거 데이터 일괄 임포트를 사용하세요.")
    else:
        import pandas as _pd_voc
        _df = _pd_voc.DataFrame(_rows)

        total   = len(_df)
        claims  = int(_df["is_claim"].fillna(False).astype(bool).sum())
        claim_r = round(claims / total * 100, 1) if total > 0 else 0.0

        # ── KPI 카드 3개 ─────────────────────────────────────────
        _kc = "display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:12px;padding:18px 12px;text-align:center;min-height:110px;"
        _lc = "font-size:0.78rem;color:#555;margin-bottom:6px;font-weight:600;"
        _vc = "font-size:2rem;font-weight:700;line-height:1.2;margin:0;"
        _sc = "font-size:0.72rem;color:#777;margin-top:4px;"

        _k1, _k2, _k3 = st.columns(3)
        with _k1:
            st.markdown(
                f"<div style='background:#E3F2FD;{_kc}'>"
                f"<div style='{_lc}'>💬 총 상담 건수</div>"
                f"<div style='{_vc} color:#0D47A1;'>{total:,}</div>"
                f"<div style='{_sc}'>분석 완료 건</div></div>",
                unsafe_allow_html=True,
            )
        with _k2:
            st.markdown(
                f"<div style='background:#FFEBEE;{_kc}'>"
                f"<div style='{_lc}'>🚨 클레임 건수</div>"
                f"<div style='{_vc} color:#C62828;'>{claims:,}</div>"
                f"<div style='{_sc}'>전체의 {claim_r:g}%</div></div>",
                unsafe_allow_html=True,
            )
        with _k3:
            _pos = int((_df["sentiment"] == "긍정").sum())
            _neg = int((_df["sentiment"] == "부정").sum())
            st.markdown(
                f"<div style='background:#E8F5E9;{_kc}'>"
                f"<div style='{_lc}'>😊 긍정 / 😞 부정</div>"
                f"<div style='{_vc} color:#1B5E20;'>{_pos:,} / {_neg:,}</div>"
                f"<div style='{_sc}'>감정 분포</div></div>",
                unsafe_allow_html=True,
            )

        st.markdown("<br>", unsafe_allow_html=True)

        # ── 차트 2개 (파이 + 막대) ───────────────────────────────
        _ch1, _ch2 = st.columns(2)

        with _ch1:
            st.markdown("##### 불만 카테고리 분포")
            _cat_data = _df["complaint_category"].fillna("없음")
            _cat_data = _cat_data[_cat_data != ""]
            if len(_cat_data) > 0:
                _cat_cnt = _cat_data.value_counts().reset_index()
                _cat_cnt.columns = ["카테고리", "건수"]
                _fig_pie = _px.pie(
                    _cat_cnt, names="카테고리", values="건수",
                    hole=0.35,
                    color_discrete_sequence=_px.colors.qualitative.Pastel,
                )
                _fig_pie.update_layout(margin=dict(t=10, b=10, l=10, r=10), height=300)
                st.plotly_chart(_fig_pie, width="stretch")
            else:
                st.info("카테고리 데이터가 없습니다.")

        with _ch2:
            st.markdown("##### 감정 분포")
            _sent_order = ["긍정", "중립", "부정"]
            _sent_cnt = _df["sentiment"].fillna("미분류").value_counts().reindex(_sent_order, fill_value=0).reset_index()
            _sent_cnt.columns = ["감정", "건수"]
            _fig_bar = _px.bar(
                _sent_cnt, x="감정", y="건수",
                color="감정",
                color_discrete_map={"긍정": "#43A047", "중립": "#78909C", "부정": "#E53935"},
                text="건수",
            )
            _fig_bar.update_layout(
                showlegend=False, margin=dict(t=10, b=10, l=10, r=10), height=300,
            )
            _fig_bar.update_traces(textposition="outside")
            st.plotly_chart(_fig_bar, width="stretch")

        # ── 신제품 아이디어 리스트 ───────────────────────────────
        _ideas = _df[_df["product_idea"].fillna("").str.strip() != ""][["analyzed_at", "product_idea", "summary"]].copy()
        if not _ideas.empty:
            st.markdown("##### 💡 AI가 추출한 신제품·개선 아이디어")
            _ideas["날짜"] = _pd_voc.to_datetime(_ideas["analyzed_at"]).dt.strftime("%Y-%m-%d")
            for _, _row in _ideas.iterrows():
                st.markdown(
                    f"<div style='background:#FFFDE7;border-left:4px solid #F9A825;"
                    f"border-radius:4px;padding:8px 12px;margin-bottom:6px;font-size:0.88rem;'>"
                    f"<b>💡 {_row['product_idea']}</b>"
                    f"<span style='color:#888;font-size:0.78rem;margin-left:8px;'>{_row['날짜']}</span><br>"
                    f"<span style='color:#666;'>요약: {_row['summary']}</span>"
                    f"</div>",
                    unsafe_allow_html=True,
                )

        # ── 전체 데이터 테이블 ──────────────────────────────────
        st.markdown("##### 📋 전체 VOC 목록")
        _display_df = _df[[
            "analyzed_at", "sentiment", "is_claim", "complaint_category",
            "summary", "handled_by", "customer_phone", "source",
        ]].copy()
        _display_df.columns = [
            "분석일시", "감정", "클레임", "카테고리",
            "요약", "담당자", "고객전화", "수집경로",
        ]
        _display_df["분석일시"] = _pd_voc.to_datetime(_display_df["분석일시"]).dt.strftime("%Y-%m-%d %H:%M")
        _display_df["클레임"] = _display_df["클레임"].map({True: "🚨 클레임", False: "정상", None: ""})
        st.dataframe(_display_df, width="stretch", hide_index=True)

    # ── 과거 데이터 일괄 임포트 (엑셀 업로드) ───────────────────
    st.divider()
    with st.expander("📂 과거 상담 데이터 일괄 분석 (채널톡 엑셀 업로드)", expanded=False):
        st.markdown(
            "**채널톡 관리자 → 통계 → 상담 통계 → 상담별 → [상담 파일 다운로드]**에서\n"
            "**[메시지 데이터 포함]** 옵션으로 다운로드한 엑셀 파일을 업로드하세요.\n\n"
            "> ✅ 소유자(Owner) 권한 계정만 다운로드 가능합니다."
        )

        _openai_key_ui = st.text_input(
            "Gemini API Key", type="password",
            placeholder="AIza... (Render 환경변수 GEMINI_API_KEY 설정 시 비워두세요)",
            key="voc_import_key",
        )
        _uploaded = st.file_uploader("엑셀 파일 업로드 (.xlsx)", type=["xlsx"], key="voc_excel_upload")

        if _uploaded:
            import pandas as _pd_imp
            try:
                _xl = _pd_imp.read_excel(_uploaded)
                st.caption(f"파일 로드 완료: {len(_xl)}행, 컬럼: {list(_xl.columns)}")
            except Exception as _xe:
                st.error(f"엑셀 읽기 실패: {_xe}")
                _xl = None

            if _xl is not None and len(_xl) > 0:
                st.markdown("**컬럼 매핑** (채널톡 엑셀의 컬럼명을 선택하세요)")
                _cols = ["(없음)"] + list(_xl.columns)
                _cm1, _cm2, _cm3, _cm4 = st.columns(4)
                with _cm1:
                    _col_chatid = st.selectbox("상담 ID", _cols, key="voc_col_chatid")
                with _cm2:
                    _col_phone  = st.selectbox("고객 전화번호", _cols, key="voc_col_phone")
                with _cm3:
                    _col_mgr    = st.selectbox("담당 매니저", _cols, key="voc_col_mgr")
                with _cm4:
                    _col_msg    = st.selectbox("메시지 내용", _cols, key="voc_col_msg")

                if st.button("🤖 AI 일괄 분석 시작", type="primary", key="voc_import_run"):
                    _key_to_use = _openai_key_ui.strip() or st.secrets.get("gemini", {}).get("api_key", "") or os.environ.get("GEMINI_API_KEY", "")
                    if not _key_to_use:
                        st.error("Gemini API Key가 필요합니다. 위 입력란에 키를 붙여넣거나 환경변수 GEMINI_API_KEY를 설정하세요.")
                    elif _col_msg == "(없음)":
                        st.error("메시지 내용 컬럼을 선택해야 합니다.")
                    else:
                        import requests as _req_imp
                        _gemini_endpoint = (
                            "https://generativelanguage.googleapis.com/v1beta/models/"
                            f"gemini-flash-latest:generateContent?key={_key_to_use}"
                        )
                        _prog = st.progress(0, text="분석 중...")
                        _ok, _skip = 0, 0
                        _total_rows = len(_xl)
                        for _ri, _xrow in _xl.iterrows():
                            _ft = str(_xrow.get(_col_msg, "") or "").strip()
                            if not _ft:
                                _skip += 1
                                continue
                            _cid = str(_xrow.get(_col_chatid, "") or "").strip() if _col_chatid != "(없음)" else None
                            _ph  = str(_xrow.get(_col_phone,  "") or "").strip() if _col_phone  != "(없음)" else None
                            _mg  = str(_xrow.get(_col_mgr,    "") or "").strip() if _col_mgr    != "(없음)" else None
                            try:
                                _pr = (
                                    "다음은 가구 쇼핑몰 고객 상담 대화입니다.\n"
                                    "아래 항목을 분석해 JSON으로만 응답하세요:\n"
                                    "- is_claim: bool\n- complaint_category: str (배송/제품불량/가격/응대/기타/없음)\n"
                                    "- product_idea: str\n- summary: str\n- sentiment: str (긍정/중립/부정)\n\n"
                                    f"대화:\n{_ft[:3000]}"
                                )
                                _gr = _req_imp.post(
                                    _gemini_endpoint,
                                    json={
                                        "contents": [{"parts": [{"text": _pr}]}],
                                        "generationConfig": {
                                            "temperature": 0,
                                            "responseMimeType": "application/json",
                                        },
                                    },
                                    timeout=20,
                                )
                                _gr.raise_for_status()
                                import json as _json_imp
                                _ad = _json_imp.loads(
                                    _gr.json()["candidates"][0]["content"]["parts"][0]["text"]
                                )
                                _voc_row = {
                                    "chat_id": _cid or None,
                                    "customer_phone": _ph,
                                    "handled_by": _mg,
                                    "is_claim": bool(_ad.get("is_claim", False)),
                                    "complaint_category": str(_ad.get("complaint_category") or "").strip(),
                                    "product_idea": str(_ad.get("product_idea") or "").strip(),
                                    "summary": str(_ad.get("summary") or "").strip(),
                                    "sentiment": str(_ad.get("sentiment") or "").strip(),
                                    "raw_json": _ad,
                                    "source": "excel_import",
                                }
                                supa.table("app_voc_insights").upsert(
                                    _voc_row,
                                    on_conflict="chat_id",
                                    ignore_duplicates=True,
                                ).execute()
                                _ok += 1
                            except Exception as _ie:
                                _skip += 1
                            _prog.progress(
                                min((_ri + 1) / _total_rows, 1.0),
                                text=f"분석 중... {_ri + 1}/{_total_rows}건",
                            )
                        _prog.empty()
                        st.success(f"완료! 분석 성공 {_ok}건 / 건너뜀(빈 내용·중복) {_skip}건")
                        st.rerun()


# =====================================================================
# 📁 자료실 — 업무 자료 게시판
# =====================================================================

def render_document_library():
    """업무 자료 게시판 — 카테고리 트리 + 리치 텍스트 + 첨부파일."""
    import re as _re, urllib.parse as _uparse, datetime as _dtmod
    import streamlit.components.v1 as _comp

    try:
        from streamlit_quill import st_quill as _st_quill
        _HAS_QUILL = True
    except ImportError:
        _HAS_QUILL = False

    def _render_html_content(html: str, height: int = 400):
        """HTML 또는 평문 콘텐츠를 스크롤 가능한 창으로 렌더링."""
        _is_html = bool(html and ("<" in html and ">" in html))
        if _is_html:
            _safe = (
                "<html><head><meta charset='utf-8'>"
                "<style>body{font-family:sans-serif;font-size:14px;margin:0;padding:12px 16px;}"
                "table{border-collapse:collapse;width:100%}"
                "td,th{border:1px solid #ccc;padding:4px 8px}"
                "img{max-width:100%}h1,h2,h3{margin-top:0.8em}</style></head>"
                f"<body>{html}</body></html>"
            )
            _comp.html(_safe, height=height, scrolling=True)
        else:
            st.markdown(
                f"<div style='height:{height}px;overflow-y:auto;padding:8px;'>{html or '*(내용 없음)*'}</div>",
                unsafe_allow_html=True,
            )

    st.header("📁 자료실")
    st.caption("업무 자료를 게시판 형태로 관리합니다.")

    client, err = get_supabase_client()
    if err or not client:
        st.error("데이터베이스 연결에 실패했습니다.")
        return

    _cu   = st.session_state.get("current_user") or {}
    _me   = _get_current_user_display_name() or (_cu.get("username") or _cu.get("email") or "").strip()
    _role = _cu.get("role", "staff")

    # ── Supabase Storage 업로드 헬퍼 ──────────────────────────────
    def _upload_file(doc_id, uploaded_file) -> tuple[str, str]:
        """파일을 Supabase Storage 'documents' 버킷에 업로드. (스토리지 경로, filename) 반환.

        보안: 버킷을 Private 으로 운영하기 위해 public URL 대신 스토리지 경로를
        file_url 컬럼에 저장하고, 표시 시점에 _doc_signed_url() 로 서명 URL 을 생성한다."""
        import mimetypes, re, unicodedata
        _fname_orig = uploaded_file.name
        _fbytes     = uploaded_file.read()
        _mime       = mimetypes.guess_type(_fname_orig)[0] or "application/octet-stream"

        # Supabase Storage key 에 한글/특수문자 불허 → ASCII-safe 파일명 생성
        # 확장자 분리 후 이름 부분을 NFD 정규화 → ASCII 변환 → 나머지는 밑줄로 치환
        if "." in _fname_orig:
            _stem, _ext = _fname_orig.rsplit(".", 1)
        else:
            _stem, _ext = _fname_orig, ""
        _safe_stem = unicodedata.normalize("NFD", _stem).encode("ascii", "ignore").decode("ascii")
        _safe_stem = re.sub(r"[^A-Za-z0-9_\-]", "_", _safe_stem).strip("_") or "file"
        _safe_fname = f"{_safe_stem}.{_ext}" if _ext else _safe_stem
        _spath      = f"{doc_id}/{_safe_fname}"

        client.storage.from_("documents").upload(
            _spath, _fbytes,
            file_options={"content-type": _mime, "upsert": "true"},
        )
        # DB에는 스토리지 경로 + 원본 파일명 저장 (URL 은 표시 시점에 서명 생성)
        return _spath, _fname_orig

    @st.cache_data(ttl=1800, show_spinner=False)
    def _doc_signed_url(raw: str) -> str:
        """file_url 값(신규: 스토리지 경로 / 구버전: public URL)을 서명 URL 로 변환.

        documents 버킷을 Private 으로 전환해도 다운로드·미리보기가 계속 동작한다.
        서명 유효 1시간, 캐시 30분 (만료 전 재발급). 실패 시 원본 값 반환."""
        if not raw:
            return ""
        _path = raw
        if raw.startswith("http"):
            _marker = "/object/public/documents/"
            if _marker in raw:
                # 구버전 public URL → 경로 추출 (한글 파일명 percent-encoding 해제)
                _path = _uparse.unquote(raw.split(_marker, 1)[1].split("?")[0])
            else:
                return raw  # documents 버킷 URL 이 아니면 그대로 사용
        try:
            _sb, _e = get_supabase_client()
            if _e or not _sb:
                return raw
            _r = _sb.storage.from_("documents").create_signed_url(_path, 3600)
            if isinstance(_r, dict):
                return _r.get("signedURL") or _r.get("signed_url") or raw
            return getattr(_r, "signedURL", None) or getattr(_r, "signed_url", None) or raw
        except Exception:
            return raw

    def _fmt_size(size: int | None) -> str:
        if not size:
            return ""
        if size < 1024:
            return f"{size} B"
        if size < 1024 ** 2:
            return f"{size/1024:.1f} KB"
        return f"{size/1024**2:.1f} MB"

    # ── 전체 자료 불러오기 ─────────────────────────────────────────
    @st.cache_data(ttl=30, show_spinner=False)
    def _fetch_docs():
        try:
            r = client.table("app_documents").select("*").order("created_at", desc=True).execute()
            return r.data or []
        except Exception:
            return []

    _docs = _fetch_docs()

    # ── 카테고리 트리 구성 ─────────────────────────────────────────
    # { 카테고리: {서브카테고리: count, ...} }
    _cat_tree: dict[str, dict[str, int]] = {}
    for _d in _docs:
        _c  = (_d.get("category") or "미분류").strip()
        _sc = (_d.get("subcategory") or "").strip()
        _cat_tree.setdefault(_c, {})
        if _sc:
            _cat_tree[_c][_sc] = _cat_tree[_c].get(_sc, 0) + 1
        else:
            _cat_tree[_c]["__root__"] = _cat_tree[_c].get("__root__", 0) + 1

    # ── 현재 선택된 카테고리/서브 (session_state) ─────────────────
    _sel_cat = st.session_state.get("doc_sel_cat", "전체")
    _sel_sub = st.session_state.get("doc_sel_sub", "")

    # ── 글쓰기 버튼 + 검색 (상단 우측) ────────────────────────────
    _top1, _top2 = st.columns([4, 1])
    with _top1:
        _search = st.text_input("", placeholder="🔍  제목, 내용, 작성자로 검색",
                                key="doc_search", label_visibility="collapsed")
    with _top2:
        if st.button("✏️ 글쓰기", type="primary", width="stretch", key="doc_add_btn"):
            st.session_state["doc_show_form"] = not st.session_state.get("doc_show_form", False)

    # ── 글쓰기 팝업(모달) ─────────────────────────────────────────
    def _render_doc_create_form() -> None:
        _fa1, _fa2 = st.columns([1, 1])
        with _fa1:
            _existing_cats = [c for c in _cat_tree if c != "미분류"] + ["미분류"]
            _f_cat_sel = st.selectbox("카테고리", ["직접 입력"] + _existing_cats, key="doc_f_cat_sel")
            if _f_cat_sel == "직접 입력":
                _f_cat = st.text_input("새 카테고리명", key="doc_f_cat_new",
                                       placeholder="예: 주간회의")
            else:
                _f_cat = _f_cat_sel
        with _fa2:
            _existing_subs = sorted(
                [s for s in _cat_tree.get(_f_cat, {}) if s != "__root__"]
            )
            _f_sub_sel = st.selectbox("하위 카테고리 (선택)", ["없음", "직접 입력"] + _existing_subs,
                                      key="doc_f_sub_sel")
            if _f_sub_sel == "직접 입력":
                _f_sub = st.text_input("새 하위 카테고리명", key="doc_f_sub_new",
                                       placeholder="예: 2026-W25")
            elif _f_sub_sel == "없음":
                _f_sub = ""
            else:
                _f_sub = _f_sub_sel

        _f_title = st.text_input("제목 *", key="doc_f_title", placeholder="자료 제목을 입력하세요")
        st.markdown("**내용**")
        if _HAS_QUILL:
            _f_content = _st_quill(
                placeholder="내용을 입력하거나, 다른 곳에서 서식 있는 텍스트를 붙여넣기 하세요.",
                html=True, key="doc_f_content",
            )
        else:
            _f_content = st.text_area("내용", key="doc_f_content", height=220)
        _f_tags = st.text_input("태그 (쉼표 구분)", key="doc_f_tags",
                                placeholder="예: 가이드, 인사, 2026")
        _f_file = st.file_uploader("첨부파일 (선택)", key="doc_f_file",
                                   help="PDF, Word, Excel, 이미지 등 모든 형식 (최대 50MB)")
        _fb1, _fb2 = st.columns([1, 1])
        with _fb1:
            if st.button("등록", type="primary", key="doc_f_submit", width="stretch"):
                if not _f_title.strip():
                    st.error("제목을 입력해 주세요.")
                elif not _f_cat.strip():
                    st.error("카테고리를 입력해 주세요.")
                else:
                    try:
                        _row = {
                            "title":       _f_title.strip(),
                            "content":     (_f_content or "").strip(),
                            "author":      _me or "unknown",
                            "tags":        _f_tags.strip(),
                            "category":    _f_cat.strip(),
                            "subcategory": _f_sub.strip(),
                        }
                        _res    = client.table("app_documents").insert(_row).execute()
                        _new_id = _res.data[0]["id"] if _res.data else None
                        if _f_file and _new_id:
                            with st.spinner("파일 업로드 중..."):
                                try:
                                    _url, _fname = _upload_file(_new_id, _f_file)
                                    client.table("app_documents").update({
                                        "file_url":  _url,
                                        "file_name": _fname,
                                        "file_size": _f_file.size,
                                    }).eq("id", _new_id).execute()
                                except Exception as _ue:
                                    st.warning(f"파일 업로드 실패 (글은 저장됨): {_ue}")
                        st.success("자료가 등록되었습니다.")
                        st.session_state["doc_show_form"] = False
                        try:
                            _fetch_docs.clear()
                        except Exception:
                            pass
                        st.rerun()
                    except Exception as _e:
                        st.error(f"등록 실패: {_e}")
        with _fb2:
            if st.button("취소", key="doc_f_cancel", width="stretch"):
                st.session_state["doc_show_form"] = False
                st.rerun()

    if st.session_state.get("doc_show_form"):
        from ui_dialogs import open_dialog as _open_dialog  # noqa: WPS433
        _open_dialog("📝 새 자료 등록", _render_doc_create_form, width="large")

    # ── 2단 레이아웃: 카테고리 트리(좌) + 문서 목록(우) ─────────
    _lc, _rc = st.columns([1, 3], gap="medium")

    with _lc:
        st.markdown("**📂 카테고리**")
        # 전체 버튼
        _all_count = len(_docs)
        _all_style = "background:#4a6cf7;color:#fff;" if _sel_cat == "전체" else "background:#f0f4ff;color:#4a6cf7;"
        if st.button(f"전체  ({_all_count})", key="doc_cat_all",
                     width="stretch"):
            st.session_state.update({"doc_sel_cat": "전체", "doc_sel_sub": ""})
            st.rerun()
        # 카테고리별 버튼
        for _cat in sorted(_cat_tree.keys()):
            _cat_total = sum(_cat_tree[_cat].values())
            _is_active = (_sel_cat == _cat)
            if st.button(f"📁 {_cat}  ({_cat_total})", key=f"doc_cat_{_cat}",
                         width="stretch",
                         type="primary" if _is_active else "secondary"):
                _new_sub = "" if _sel_cat != _cat else _sel_sub
                st.session_state.update({"doc_sel_cat": _cat, "doc_sel_sub": _new_sub})
                st.rerun()
            # 하위 카테고리 (선택된 카테고리만 펼침)
            if _is_active:
                for _sub in sorted(s for s in _cat_tree[_cat] if s != "__root__"):
                    _sub_cnt = _cat_tree[_cat][_sub]
                    _is_sub_active = (_sel_sub == _sub)
                    if st.button(
                        f"  └ {_sub}  ({_sub_cnt})",
                        key=f"doc_sub_{_cat}_{_sub}",
                        width="stretch",
                        type="primary" if _is_sub_active else "secondary",
                    ):
                        st.session_state.update({"doc_sel_cat": _cat, "doc_sel_sub": _sub})
                        st.rerun()

        st.markdown("<br>", unsafe_allow_html=True)
        # 뷰어 높이 슬라이더
        st.markdown("**📐 뷰어 높이**")
        _viewer_h = st.slider("", min_value=200, max_value=1200, value=500, step=50,
                              key="doc_viewer_height", label_visibility="collapsed")

    with _rc:
        # 카테고리 필터
        _filtered = []
        for _d in _docs:
            _dc  = (_d.get("category") or "미분류").strip()
            _dsc = (_d.get("subcategory") or "").strip()
            if _sel_cat != "전체" and _dc != _sel_cat:
                continue
            if _sel_sub and _dsc != _sel_sub:
                continue
            if _search.strip() and not any(
                _search.lower() in (_d.get(f) or "").lower()
                for f in ("title", "content", "author", "tags", "category", "subcategory")
            ):
                continue
            _filtered.append(_d)

        if not _filtered:
            st.info("등록된 자료가 없습니다." if not _search else "검색 결과가 없습니다.")

        for _doc in _filtered:
            _doc_id      = _doc.get("id")
            _doc_title   = _doc.get("title", "")
            _doc_content = _doc.get("content", "")
            _doc_author  = _doc.get("author", "")
            _doc_tags    = _doc.get("tags", "")
            _doc_cat     = (_doc.get("category") or "미분류").strip()
            _doc_sub     = (_doc.get("subcategory") or "").strip()
            _doc_date    = str(_doc.get("created_at", ""))[:16].replace("T", " ")
            _doc_furl    = _doc_signed_url(_doc.get("file_url") or "")
            _doc_fname   = _doc.get("file_name") or ""
            _doc_fsize   = _doc.get("file_size")

            # 태그 배지
            _tag_badges = ""
            if _doc_tags:
                _tag_badges = " ".join(
                    f"<span style='background:#f0f4ff;border-radius:4px;padding:1px 7px;"
                    f"font-size:0.72rem;color:#4a6cf7;margin-right:3px;'>{t.strip()}</span>"
                    for t in _doc_tags.split(",") if t.strip()
                )
            # 첨부파일 배지
            _file_badge = ""
            if _doc_furl and _doc_fname:
                _sz = f" ({_fmt_size(_doc_fsize)})" if _doc_fsize else ""
                _file_badge = (
                    f"<a href='{_doc_furl}' target='_blank' style='display:inline-flex;"
                    f"align-items:center;gap:3px;background:#f8f9fa;border:1px solid #dee2e6;"
                    f"border-radius:5px;padding:2px 8px;font-size:0.75rem;color:#495057;"
                    f"text-decoration:none;'>📎 {_doc_fname}{_sz}</a>"
                )
            # 카테고리 경로 표시
            _cat_path = _doc_cat + (f" › {_doc_sub}" if _doc_sub else "")
            _is_open  = st.session_state.get(f"doc_expanded_{_doc_id}", False)

            with st.container(border=True):
                # 헤더 행: 제목 + 카테고리경로 + 날짜/작성자
                st.markdown(
                    f"<div style='margin:-4px 0 4px;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;'>"
                    f"<span style='font-size:0.95rem;font-weight:600;color:#1a1a1a;'>{_doc_title}</span>"
                    f"<span style='font-size:0.72rem;color:#888;background:#f5f5f5;border-radius:4px;"
                    f"padding:1px 6px;'>{_cat_path}</span>"
                    f"{_tag_badges}"
                    f"<span style='margin-left:auto;font-size:0.72rem;color:#aaa;white-space:nowrap;'>"
                    f"{_doc_date} · {_doc_author}</span></div>"
                    f"<div style='margin-top:3px;'>{_file_badge}</div>",
                    unsafe_allow_html=True,
                )
                if st.button("▲ 닫기" if _is_open else "▼ 본문 보기",
                             key=f"doc_open_{_doc_id}"):
                    st.session_state[f"doc_expanded_{_doc_id}"] = not _is_open
                    st.rerun()

                # ── 본문 상세 (미리보기 텍스트 없음, 바로 전체 본문) ──
                if _is_open:
                    st.markdown("---")
                    _render_html_content(_doc_content or "", height=_viewer_h)

                    # 첨부파일 미리보기 + 다운로드
                    if _doc_furl and _doc_fname:
                        _sz2  = f" · {_fmt_size(_doc_fsize)}" if _doc_fsize else ""
                        _fext = _doc_fname.rsplit(".", 1)[-1].lower() if "." in _doc_fname else ""
                        _IMG_EXTS    = {"jpg", "jpeg", "png", "gif", "webp", "bmp", "svg"}
                        _PDF_EXTS    = {"pdf"}
                        _OFFICE_EXTS = {"doc", "docx", "xls", "xlsx", "ppt", "pptx", "hwp"}
                        if _fext in _IMG_EXTS:
                            _ftype = "image"
                        elif _fext in _PDF_EXTS:
                            _ftype = "pdf"
                        elif _fext in _OFFICE_EXTS:
                            _ftype = "office"
                        else:
                            _ftype = "download"

                        _prev_key   = f"doc_preview_{_doc_id}"
                        _is_preview = st.session_state.get(_prev_key, False)
                        _pa1, _pa2  = st.columns([2, 5])
                        with _pa1:
                            _prev_icon = {"image": "🖼️", "pdf": "📄", "office": "📊"}.get(_ftype, "")
                            if _ftype != "download":
                                if st.button(
                                    "▲ 미리보기 닫기" if _is_preview else f"{_prev_icon} 미리보기",
                                    key=f"doc_prev_btn_{_doc_id}",
                                ):
                                    st.session_state[_prev_key] = not _is_preview
                                    st.rerun()
                        with _pa2:
                            st.markdown(
                                f"<a href='{_doc_furl}' target='_blank' download style='"
                                f"display:inline-flex;align-items:center;gap:6px;"
                                f"background:#1a73e8;color:#fff;border-radius:8px;"
                                f"padding:6px 14px;font-size:0.82rem;text-decoration:none;'>"
                                f"⬇️ {_doc_fname}{_sz2} 다운로드</a>",
                                unsafe_allow_html=True,
                            )
                        if _is_preview:
                            if _ftype == "image":
                                _comp.html(
                                    f"<html><body style='margin:0;background:#f5f5f5;text-align:center;padding:8px;'>"
                                    f"<img src='{_doc_furl}' style='max-width:100%;max-height:600px;"
                                    f"object-fit:contain;border-radius:6px;'/></body></html>",
                                    height=400, scrolling=False,
                                )
                            elif _ftype == "pdf":
                                _comp.html(
                                    f"<iframe src='{_doc_furl}' width='100%' height='{_viewer_h}px'"
                                    f" style='border:none;'></iframe>",
                                    height=_viewer_h + 20, scrolling=False,
                                )
                            elif _ftype == "office":
                                _enc_url = _uparse.quote(_doc_furl, safe="")
                                _comp.html(
                                    f"<iframe src='https://view.officeapps.live.com/op/embed.aspx?src={_enc_url}'"
                                    f" width='100%' height='{_viewer_h}px' style='border:none;'></iframe>",
                                    height=_viewer_h + 20, scrolling=False,
                                )

                    st.markdown("<br>", unsafe_allow_html=True)
                    _can_edit = (_doc_author == _me) or (_role in ("store_admin", "superadmin"))
                    if _can_edit:
                        _ec1, _ec2 = st.columns([1, 1])
                        with _ec1:
                            if st.button("✏️ 수정", key=f"doc_edit_btn_{_doc_id}"):
                                st.session_state[f"doc_editing_{_doc_id}"] = True
                        with _ec2:
                            if st.button("🗑️ 삭제", key=f"doc_del_btn_{_doc_id}"):
                                st.session_state[f"doc_del_confirm_{_doc_id}"] = True

                    if st.session_state.get(f"doc_del_confirm_{_doc_id}"):
                        st.warning("정말 삭제하시겠습니까?")
                        _dcc1, _dcc2 = st.columns([1, 5])
                        with _dcc1:
                            if st.button("확인 삭제", type="primary", key=f"doc_del_ok_{_doc_id}"):
                                try:
                                    client.table("app_documents").delete().eq("id", _doc_id).execute()
                                    for _k in (f"doc_del_confirm_{_doc_id}", f"doc_expanded_{_doc_id}"):
                                        st.session_state.pop(_k, None)
                                    try:
                                        _fetch_docs.clear()
                                    except Exception:
                                        pass
                                    st.rerun()
                                except Exception as _e:
                                    st.error(f"삭제 실패: {_e}")
                        with _dcc2:
                            if st.button("취소", key=f"doc_del_cancel_{_doc_id}"):
                                st.session_state.pop(f"doc_del_confirm_{_doc_id}", None)
                                st.rerun()

                    if st.session_state.get(f"doc_editing_{_doc_id}"):
                        def _render_doc_edit_form(
                            doc_id=_doc_id, doc_title=_doc_title, doc_content=_doc_content,
                            doc_tags=_doc_tags, doc_cat=_doc_cat, doc_sub=_doc_sub,
                            doc_fname=_doc_fname,
                        ) -> None:
                            _ea1, _ea2 = st.columns([1, 1])
                            with _ea1:
                                _et_cat_sel = st.selectbox(
                                    "카테고리", ["직접 입력"] + sorted(_cat_tree.keys()),
                                    index=(["직접 입력"] + sorted(_cat_tree.keys())).index(doc_cat)
                                    if doc_cat in _cat_tree else 0,
                                    key=f"doc_et_cat_{doc_id}",
                                )
                                _et_cat = (
                                    st.text_input("새 카테고리명", value=doc_cat, key=f"doc_et_catn_{doc_id}")
                                    if _et_cat_sel == "직접 입력" else _et_cat_sel
                                )
                            with _ea2:
                                _subs_for_edit = sorted(
                                    s for s in _cat_tree.get(_et_cat, {}) if s != "__root__"
                                )
                                _et_sub_sel = st.selectbox(
                                    "하위 카테고리", ["없음", "직접 입력"] + _subs_for_edit,
                                    index=(["없음", "직접 입력"] + _subs_for_edit).index(doc_sub)
                                    if doc_sub in _subs_for_edit else 0,
                                    key=f"doc_et_sub_{doc_id}",
                                )
                                if _et_sub_sel == "직접 입력":
                                    _et_sub = st.text_input("새 하위 카테고리명", value=doc_sub,
                                                            key=f"doc_et_subn_{doc_id}")
                                elif _et_sub_sel == "없음":
                                    _et_sub = ""
                                else:
                                    _et_sub = _et_sub_sel

                            _et  = st.text_input("제목", value=doc_title, key=f"doc_et_{doc_id}")
                            st.markdown("**내용**")
                            if _HAS_QUILL:
                                _ec = _st_quill(value=doc_content or "", html=True, key=f"doc_ec_{doc_id}")
                            else:
                                _ec = st.text_area("내용", value=doc_content, height=200, key=f"doc_ec_{doc_id}")
                            _eg = st.text_input("태그", value=doc_tags, key=f"doc_eg_{doc_id}")
                            _ef = st.file_uploader("첨부파일 교체 (선택)", key=f"doc_ef_{doc_id}",
                                                   help="새 파일을 올리면 기존 파일이 교체됩니다.")
                            if doc_fname:
                                st.caption(f"현재 첨부파일: 📎 {doc_fname}")
                            _es1, _es2 = st.columns([1, 1])
                            with _es1:
                                if st.button("저장", type="primary", key=f"doc_save_{doc_id}", width="stretch"):
                                    try:
                                        _upd = {
                                            "title":       _et.strip(),
                                            "content":     (_ec or "").strip(),
                                            "tags":        _eg.strip(),
                                            "category":    _et_cat.strip(),
                                            "subcategory": _et_sub.strip(),
                                            "updated_at":  _dtmod.datetime.utcnow().isoformat(),
                                        }
                                        if _ef:
                                            with st.spinner("파일 업로드 중..."):
                                                _nurl, _nfname = _upload_file(doc_id, _ef)
                                            _upd["file_url"]  = _nurl
                                            _upd["file_name"] = _nfname
                                            _upd["file_size"] = _ef.size
                                        client.table("app_documents").update(_upd).eq("id", doc_id).execute()
                                        st.success("수정되었습니다.")
                                        st.session_state.pop(f"doc_editing_{doc_id}", None)
                                        try:
                                            _fetch_docs.clear()
                                        except Exception:
                                            pass
                                        st.rerun()
                                    except Exception as _e:
                                        st.error(f"수정 실패: {_e}")
                            with _es2:
                                if st.button("취소", key=f"doc_edit_cancel_{doc_id}", width="stretch"):
                                    st.session_state.pop(f"doc_editing_{doc_id}", None)
                                    st.rerun()

                        from ui_dialogs import open_dialog as _open_dialog  # noqa: WPS433
                        _open_dialog(
                            f"✏️ 문서 수정: {_doc_title[:40]}",
                            _render_doc_edit_form,
                            width="large",
                        )


# =====================================================================
# 📧 메일관리 (Gmail 연동) — ERP 사이드바 별도 페이지
# =====================================================================

def render_gmail_manager():
    """Gmail IMAP/SMTP 연동 — Gmail 스타일 UI."""
    import gmail_manager as _gm  # noqa: WPS433
    import html as _html

    # ── Gmail 스타일 CSS ──────────────────────────────────────────
    st.markdown("""
<style>
.gm-wrap {
    background:#fff; border:1px solid #e0e0e0; border-radius:8px;
    overflow:hidden; margin-top:0.5rem;
}
.gm-toolbar {
    display:flex; align-items:center; gap:0.5rem;
    padding:0.5rem 1rem; border-bottom:1px solid #e0e0e0;
    background:#f6f8fc;
}
.gm-toolbar input[type=text] { flex:1; border:1px solid #dfe1e5; border-radius:24px;
    padding:0.35rem 1rem; font-size:0.9rem; outline:none; }
.gm-row {
    display:flex; align-items:center; padding:0.55rem 1rem;
    border-bottom:1px solid #f0f0f0; gap:0.8rem; cursor:pointer;
    transition:background 0.12s;
}
.gm-row:hover { background:#f2f6fc; }
.gm-row.unread { background:#fff; }
.gm-row.read   { background:#fafafa; }
.gm-dot { width:10px; height:10px; border-radius:50%;
          background:#1a73e8; flex-shrink:0; }
.gm-dot.read { background:transparent; }
.gm-sender {
    width:170px; flex-shrink:0; font-size:0.88rem;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
.gm-row.unread .gm-sender { font-weight:700; color:#202124; }
.gm-row.read   .gm-sender { font-weight:400; color:#5f6368; }
.gm-content { flex:1; min-width:0; font-size:0.88rem;
              white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.gm-row.unread .gm-subject { font-weight:700; color:#202124; }
.gm-row.read   .gm-subject { font-weight:400; color:#5f6368; }
.gm-preview { color:#9aa0a6; }
.gm-date { width:72px; flex-shrink:0; text-align:right;
           font-size:0.8rem; color:#5f6368; white-space:nowrap; }
.gm-row.unread .gm-date { font-weight:600; color:#202124; }
.gm-body-wrap {
    background:#fff; border-bottom:1px solid #e8e8e8;
    padding:1rem 1.5rem;
}
.gm-body-header { margin-bottom:0.6rem; }
.gm-body-subject { font-size:1.1rem; font-weight:600; color:#202124; }
.gm-body-meta    { font-size:0.82rem; color:#5f6368; margin-top:0.2rem; }
.gm-body-text    { font-size:0.9rem; color:#202124; white-space:pre-wrap;
                   line-height:1.6; max-height:400px; overflow-y:auto;
                   background:#f9f9f9; border-radius:6px; padding:1rem;
                   border:1px solid #e8e8e8; margin-top:0.6rem; }
.gm-cust-badge {
    display:inline-block; background:#e8f5e9; color:#2e7d32;
    border-radius:4px; padding:2px 8px; font-size:0.78rem; margin-top:0.3rem;
}
.gm-compose-wrap {
    background:#fff; border-radius:8px; border:1px solid #e0e0e0;
    padding:1.5rem; margin-top:0.5rem;
}
.gm-compose-from { font-size:0.82rem; color:#5f6368; margin-bottom:1rem;
                   padding-bottom:0.5rem; border-bottom:1px solid #e0e0e0; }
</style>
""", unsafe_allow_html=True)

    _cu = st.session_state.get("current_user") or {}
    _me = (_cu.get("username") or _cu.get("email") or "").strip()

    _connected = _me and _gm.is_user_connected(_me)
    _creds     = _gm.load_user_credentials(_me) if _connected else None
    _gaddr     = (_creds or {}).get("gmail_address", "")
    _gpwd      = (_creds or {}).get("app_password", "")

    # ── 미연결: 로그인 카드 ────────────────────────────────────────
    if not _connected:
        st.markdown("<br>", unsafe_allow_html=True)
        _mid = st.columns([1, 2, 1])[1]
        with _mid:
            st.markdown(
                "<div style='text-align:center;padding:2rem 1rem 1rem;'>"
                "<img src='https://ssl.gstatic.com/ui/v1/icons/mail/rfr/gmail.ico' width=40><br><br>"
                "<h3 style='margin:0.2rem 0;'>내 Gmail 연결</h3>"
                "<p style='color:#5f6368;font-size:0.88rem;'>Gmail 주소와 앱 비밀번호로 연결합니다</p>"
                "</div>",
                unsafe_allow_html=True,
            )
            st.markdown("<br>", unsafe_allow_html=True)
            _inp_addr = st.text_input("Gmail 주소", placeholder="example@gmail.com", key="gm_inp_addr")
            _inp_pwd  = st.text_input("앱 비밀번호", placeholder="xxxx xxxx xxxx xxxx",
                                      type="password", key="gm_inp_pwd")
            if st.button("연결", type="primary", width="stretch", key="gm_connect_btn"):
                _a = _inp_addr.strip()
                _p = _inp_pwd.replace(" ", "").strip()
                if not _a or "@" not in _a:
                    st.error("올바른 Gmail 주소를 입력해 주세요.")
                elif len(_p) < 16:
                    st.error("앱 비밀번호는 16자리입니다.")
                else:
                    with st.spinner("연결 확인 중..."):
                        _ok, _emsg = _gm.test_connection(_a, _p)
                    if _ok:
                        _gm.save_user_credentials(_me, _a, _p)
                        st.success(f"✅ {_a} 연결 완료!")
                        st.rerun()
                    else:
                        st.error(f"연결 실패: {_emsg}")
            st.markdown("<br>", unsafe_allow_html=True)
            with st.expander("❓ 앱 비밀번호 발급 방법"):
                st.markdown(
                    "1. [myaccount.google.com/apppasswords](https://myaccount.google.com/apppasswords) 접속  \n"
                    "2. 앱 이름 입력 (예: `이몬스ERP`) → **만들기**  \n"
                    "3. 표시된 **16자리 코드**를 위 입력창에 붙여넣기"
                )
        return

    # ── 연결 완료: 헤더 ────────────────────────────────────────────
    _top1, _top2, _top3 = st.columns([4, 1, 1])
    with _top1:
        st.markdown(
            f"<div style='display:flex;align-items:center;gap:0.5rem;padding:0.3rem 0;'>"
            f"<img src='https://ssl.gstatic.com/ui/v1/icons/mail/rfr/gmail.ico' width=20>"
            f"<span style='font-size:1.1rem;font-weight:600;color:#202124;'>Gmail</span>"
            f"<span style='font-size:0.82rem;color:#5f6368;margin-left:0.3rem;'>— {_gaddr}</span>"
            f"</div>",
            unsafe_allow_html=True,
        )
    with _top2:
        if st.button("🔄 새로고침", key="gm_refresh", width="stretch"):
            st.session_state.pop("gm_inbox_cache", None)
            st.rerun()
    with _top3:
        if st.button("연결 해제", key="gm_disconnect", width="stretch"):
            _gm.delete_user_credentials(_me)
            st.session_state.pop("gm_inbox_cache", None)
            st.rerun()

    gmail_tabs = st.tabs(["받은편지함", "검색", "메일 쓰기"])

    # ── 탭 1: 받은편지함 ──────────────────────────────────────────
    with gmail_tabs[0]:
        _tf1, _tf2 = st.columns([3, 1])
        with _tf2:
            _unread_only = st.checkbox("읽지 않은 메일만", value=False, key="gm_unread_only")

        if "gm_inbox_cache" not in st.session_state:
            with st.spinner("받은편지함 로딩 중..."):
                try:
                    _search = "UNSEEN" if _unread_only else "ALL"
                    st.session_state["gm_inbox_cache"] = _gm.list_messages(
                        _gaddr, _gpwd, search=_search, max_results=30)
                except Exception as _e:
                    st.error(f"메일 로드 실패: {_e}")
                    st.session_state["gm_inbox_cache"] = []

        _msgs = st.session_state.get("gm_inbox_cache", [])
        _disp = [m for m in _msgs if not _unread_only or m["is_unread"]]

        if not _disp:
            st.markdown(
                "<div style='text-align:center;padding:3rem;color:#5f6368;'>"
                "<div style='font-size:2.5rem;'>📭</div>"
                "<p>메일이 없습니다.</p></div>",
                unsafe_allow_html=True,
            )

        st.markdown("<div class='gm-wrap'>", unsafe_allow_html=True)
        for _msg in _disp:
            _uid    = _msg["uid"]
            _rdcls  = "unread" if _msg["is_unread"] else "read"
            _sender = _html.escape(re.sub(r"<[^>]+>", "", _msg["from_"])[:28])
            _subj   = _html.escape(_msg["subject"][:55])
            _date   = _msg["date"][:6]

            st.markdown(
                f"<div class='gm-row {_rdcls}'>"
                f"  <div class='gm-dot {_rdcls}'></div>"
                f"  <div class='gm-sender'>{_sender}</div>"
                f"  <div class='gm-content'>"
                f"    <span class='gm-subject'>{_subj}</span>"
                f"  </div>"
                f"  <div class='gm-date'>{_date}</div>"
                f"</div>",
                unsafe_allow_html=True,
            )
            _bc1, _bc2, _bc3 = st.columns([2, 1, 1])
            with _bc1:
                pass
            with _bc2:
                if st.button("열기", key=f"gm_open_{_uid}", width="stretch"):
                    _k = f"gm_body_{_uid}"
                    if _k in st.session_state:
                        st.session_state.pop(_k)
                    else:
                        with st.spinner(""):
                            st.session_state[_k] = _gm.get_message_body(_gaddr, _gpwd, _uid)
            with _bc3:
                if st.button("🗑️ 삭제", key=f"gm_del_{_uid}", width="stretch"):
                    st.session_state[f"gm_del_confirm_{_uid}"] = True

            if st.session_state.get(f"gm_del_confirm_{_uid}"):
                _dcc1, _dcc2, _dcc3 = st.columns([1, 1, 4])
                with _dcc1:
                    if st.button("삭제 확인", type="primary", key=f"gm_del_ok_{_uid}"):
                        _gm.delete_message(_gaddr, _gpwd, _uid)
                        for _kk in (f"gm_del_confirm_{_uid}", f"gm_body_{_uid}"):
                            st.session_state.pop(_kk, None)
                        st.session_state.pop("gm_inbox_cache", None)
                        st.toast("삭제되었습니다.", icon="🗑️")
                        st.rerun()
                with _dcc2:
                    if st.button("취소", key=f"gm_del_cancel_{_uid}"):
                        st.session_state.pop(f"gm_del_confirm_{_uid}", None)
                        st.rerun()

            if st.session_state.get(f"gm_body_{_uid}"):
                _body_txt = st.session_state[f"gm_body_{_uid}"]
                _cust = _gm.match_sender_to_customer(_msg["from_"])
                _cust_html = ""
                if _cust:
                    _cust_html = (
                        f"<div class='gm-cust-badge'>👤 고객 매칭: {_html.escape(_cust['name'])} "
                        f"({_cust.get('phone1','')}) — {_html.escape(_cust.get('store_name',''))}</div>"
                    )
                st.markdown(
                    f"<div class='gm-body-wrap'>"
                    f"  <div class='gm-body-header'>"
                    f"    <div class='gm-body-subject'>{_html.escape(_msg['subject'])}</div>"
                    f"    <div class='gm-body-meta'>발신: {_html.escape(_msg['from_'])} &nbsp;|&nbsp; {_msg['date'][:25]}</div>"
                    f"    {_cust_html}"
                    f"  </div>"
                    f"  <div class='gm-body-text'>{_html.escape(_body_txt)}</div>"
                    f"</div>",
                    unsafe_allow_html=True,
                )

        st.markdown("</div>", unsafe_allow_html=True)

    # ── 탭 2: 검색 ────────────────────────────────────────────────
    with gmail_tabs[1]:
        _sq1c, _sq2c = st.columns([5, 1])
        with _sq1c:
            _sq = st.text_input("검색어", placeholder="보낸사람, 제목, 내용으로 검색  예) SUBJECT 견적",
                                key="gm_search_q", label_visibility="collapsed")
        with _sq2c:
            _do_search = st.button("검색", type="primary", key="gm_search_btn", width="stretch")

        if _do_search and _sq.strip():
            with st.spinner("검색 중..."):
                try:
                    st.session_state["gm_search_results"] = _gm.list_messages(
                        _gaddr, _gpwd, search=_sq.strip(), max_results=20)
                except Exception as _se:
                    st.error(f"검색 실패: {_se}")
                    st.session_state["gm_search_results"] = []

        _sr = st.session_state.get("gm_search_results", [])
        if _sr:
            st.caption(f"검색 결과 {len(_sr)}건")
            st.markdown("<div class='gm-wrap'>", unsafe_allow_html=True)
            for _sm in _sr:
                _suid   = _sm["uid"]
                _rdcls2 = "unread" if _sm["is_unread"] else "read"
                _ssend  = _html.escape(re.sub(r"<[^>]+>", "", _sm["from_"])[:28])
                _ssubj  = _html.escape(_sm["subject"][:55])
                st.markdown(
                    f"<div class='gm-row {_rdcls2}'>"
                    f"  <div class='gm-dot {_rdcls2}'></div>"
                    f"  <div class='gm-sender'>{_ssend}</div>"
                    f"  <div class='gm-content'><span class='gm-subject'>{_ssubj}</span></div>"
                    f"  <div class='gm-date'>{_sm['date'][:6]}</div>"
                    f"</div>",
                    unsafe_allow_html=True,
                )
                _soc1, _soc2 = st.columns([5, 1])
                with _soc2:
                    if st.button("열기", key=f"gm_sr_open_{_suid}", width="stretch"):
                        _sk = f"gm_sr_body_{_suid}"
                        if _sk in st.session_state:
                            st.session_state.pop(_sk)
                        else:
                            with st.spinner(""):
                                st.session_state[_sk] = _gm.get_message_body(_gaddr, _gpwd, _suid)
                if st.session_state.get(f"gm_sr_body_{_suid}"):
                    st.markdown(
                        f"<div class='gm-body-wrap'>"
                        f"  <div class='gm-body-subject'>{_html.escape(_sm['subject'])}</div>"
                        f"  <div class='gm-body-meta'>발신: {_html.escape(_sm['from_'])}</div>"
                        f"  <div class='gm-body-text'>{_html.escape(st.session_state[f'gm_sr_body_{_suid}'])}</div>"
                        f"</div>",
                        unsafe_allow_html=True,
                    )
            st.markdown("</div>", unsafe_allow_html=True)

    # ── 탭 3: 메일 쓰기 ───────────────────────────────────────────
    with gmail_tabs[2]:
        st.markdown(
            f"<div class='gm-compose-from'>보내는 사람: <b>{_gaddr}</b></div>",
            unsafe_allow_html=True,
        )
        _to   = st.text_input("받는 사람", placeholder="받는 사람 이메일 주소", key="gm_send_to",
                               label_visibility="collapsed")
        _subj = st.text_input("제목", placeholder="제목", key="gm_send_subj",
                               label_visibility="collapsed")
        _body = st.text_area("내용", height=260, placeholder="내용을 입력하세요.",
                              key="gm_send_body", label_visibility="collapsed")
        _pc1, _pc2 = st.columns([1, 5])
        with _pc1:
            if st.button("📤 보내기", type="primary", key="gm_send_btn", width="stretch"):
                if not _to.strip():
                    st.error("받는 사람을 입력해 주세요.")
                elif not _subj.strip():
                    st.error("제목을 입력해 주세요.")
                elif not _body.strip():
                    st.error("내용을 입력해 주세요.")
                else:
                    with st.spinner("발송 중..."):
                        _res = _gm.send_message(_gaddr, _gpwd, _to.strip(), _subj.strip(), _body.strip())
                    if _res["status"] == "sent":
                        st.success("✅ 발송 완료!")
                        for _k in ("gm_send_to", "gm_send_subj", "gm_send_body"):
                            st.session_state.pop(_k, None)
                        st.rerun()
                    else:
                        st.error(f"발송 실패: {_res['error']}")


# ---------- 탭 7: 월말 급여 요약 (store_admin) ----------

def _erp_tab_monthly_summary(current_db: str, today: date):
    st.subheader("📊 월말 급여 요약")
    import calendar as _cal
    col_y, col_m = st.columns(2)
    with col_y:
        s_year = st.number_input("연도", min_value=2020, max_value=2100, value=today.year, step=1, key="erp_sum_year")
    with col_m:
        s_month = st.number_input("월", min_value=1, max_value=12, value=today.month, step=1, key="erp_sum_month")
    last_day = _cal.monthrange(int(s_year), int(s_month))[1]
    p_start = date(int(s_year), int(s_month), 1)
    p_end = date(int(s_year), int(s_month), last_day)

    employees = _erp_get_employee_names_for_store(current_db)
    if not employees:
        st.info("매장에 배정된 직원이 없습니다.")
        return

    # 전 매장 목록 (db_filename → 매장명 매핑)
    all_stores = _get_supabase_stores_list()
    dbf_to_name = {s["db_filename"]: (s.get("store_name") or s["db_filename"]) for s in all_stores}
    home_store_name = dbf_to_name.get(current_db, current_db)

    # 직원별 기본 매장 매핑 (app_users.store_id 기준)
    _all_emp_data = _get_supabase_employee_list_with_stores()
    _emp_home_store: dict[str, str] = {}
    _emp_all_stores: dict[str, str] = {}
    for _eu in _all_emp_data:
        _key = (_eu.get("name") or _eu.get("username") or "").strip()
        if _key:
            _emp_home_store[_key] = _eu.get("기본매장") or home_store_name
            _emp_all_stores[_key] = _eu.get("배정매장") or home_store_name

    # 매장별로 근태 로그와 근무 계획을 가져와서 현재 매장 직원에 해당하는 건만 수집
    # 정상근무일: app_shift_schedules(근무계획) 우선 집계
    # 연차/반차/조퇴 등 예외항목: app_attendance_logs에서 집계
    emp_set = set(employees)
    detail_rows = []  # {"직원명", "근무매장", 각 집계 컬럼들}
    shift_detail_rows = []  # 일별 근무 상세 (비고 포함)
    for store in all_stores:
        dbf = store["db_filename"]
        sn = store.get("store_name") or dbf
        shifts = _erp_fetch_range("app_shift_schedules", "db_filename", dbf, "shift_date", p_start, p_end)
        logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", dbf, "log_date", p_start, p_end)
        for emp in employees:
            emp_shifts = [s for s in shifts if (s.get("employee_name") or "") == emp]
            emp_logs = [l for l in logs if (l.get("employee_name") or "") == emp
                        and (l.get("status") or "approved") == "approved"]
            if not emp_shifts and not emp_logs:
                continue
            for _es in emp_shifts:
                _ss = str(_es.get("shift_start") or "")[:5]
                _ee = str(_es.get("shift_end") or "")[:5]
                _ss_t = _erp_parse_time(_es.get("shift_start"))
                _ee_t = _erp_parse_time(_es.get("shift_end"))
                _hours = round(_erp_calc_shift_hours(_ss_t, _ee_t), 2) if (_ss_t and _ee_t) else 0
                _wloc = (_es.get("work_location_name") or "").strip()
                shift_detail_rows.append({
                    "직원명": emp,
                    "소속매장": sn,
                    "근무일": str(_es.get("shift_date") or "")[:10],
                    "출근": _ss,
                    "퇴근": _ee,
                    "근무시간(h)": _hours,
                    "실근무지": _wloc or sn,
                    "비고": str(_es.get("note") or "").strip(),
                })
            # 정상근무일: 근무계획(shift_schedules) 건수 기준
            normal_days = len(emp_shifts)
            annual_used = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "연차")
            half_used = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "반차")
            early_late_min = sum(int(l.get("diff_minutes") or 0) for l in emp_logs if l.get("work_type") in ("조퇴", "지각"))
            comp_use_min = sum(int(l.get("diff_minutes") or 0) for l in emp_logs if l.get("work_type") == "시차사용")
            # 추가근무·회의: app_attendance_logs work_type 기준 (승인 후 자동 삽입된 레코드)
            ot_min = 0
            for _ol in emp_logs:
                if _ol.get("work_type") not in ("추가근무", "회의"):
                    continue
                _ols = _erp_parse_time(_ol.get("start_time"))
                _ole = _erp_parse_time(_ol.get("end_time"))
                if _ols and _ole:
                    _od = (_ole.hour * 60 + _ole.minute) - (_ols.hour * 60 + _ols.minute)
                    if _od > 0:
                        ot_min += _od
                else:
                    ot_min += int(_ol.get("diff_minutes") or 0)
            detail_rows.append({
                "직원명": emp,
                "근무매장": sn,
                "정상근무일": normal_days,
                "연차": annual_used,
                "반차": half_used,
                "조퇴/지각(분)": early_late_min,
                "시차사용(분)": comp_use_min,
                "추가근무(분)": ot_min,
            })

    # leave_grants: 매장당 1쿼리로 일괄 조회 후 직원별 dict화 (N+1 쿼리 제거)
    _grants_rows = _erp_fetch_table("app_leave_grants", {
        "home_db_filename": current_db, "year": int(s_year)
    })
    _grants_by_emp = {(r.get("employee_name") or ""): r for r in _grants_rows}

    # 직원별 합계 (화면 표시용)
    summary_rows = []
    for emp in employees:
        emp_details = [r for r in detail_rows if r["직원명"] == emp]
        stores_worked = sorted({r["근무매장"] for r in emp_details})
        _gr = _grants_by_emp.get(emp)
        annual = float(_gr.get("annual_days") or 0) if _gr else 0
        comp_remain = _erp_compute_remaining_comptime(current_db, emp)
        total_annual_used = sum(r["연차"] for r in emp_details)
        _emp_home = _emp_home_store.get(emp) or home_store_name
        summary_rows.append({
            "직원명": emp,
            "소속매장": _emp_home,
            "근무매장": ", ".join(stores_worked) if stores_worked else "-",
            "정상근무일": sum(r["정상근무일"] for r in emp_details),
            "연차": total_annual_used,
            "반차": sum(r["반차"] for r in emp_details),
            "조퇴/지각(분)": sum(r["조퇴/지각(분)"] for r in emp_details),
            "시차사용(분)": sum(r["시차사용(분)"] for r in emp_details),
            "추가근무(분)": sum(r["추가근무(분)"] for r in emp_details),
            "추가근무(h)": round(sum(r["추가근무(분)"] for r in emp_details) / 60, 2),
            "잔여연차": annual - total_annual_used,
            "잔여시차(분)": comp_remain,
        })

    df_summary = pd.DataFrame(summary_rows)
    st.caption("화면에는 직원별 전체 근무 합계가 표시됩니다. 매장별 세부 내역은 엑셀 다운로드에서 확인하세요.")
    st.dataframe(df_summary, width="stretch", hide_index=True)

    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as writer:
        df_summary.to_excel(writer, sheet_name="합계", index=False)
        if detail_rows:
            df_detail = pd.DataFrame(detail_rows).sort_values(["직원명", "근무매장"], ignore_index=True)
            df_detail.to_excel(writer, sheet_name="매장별세부내역", index=False)
        if shift_detail_rows:
            df_shift = (pd.DataFrame(shift_detail_rows)
                        .sort_values(["직원명", "근무일"], ignore_index=True))
            df_shift.to_excel(writer, sheet_name="일별근무상세", index=False)
    buf.seek(0)
    st.download_button(
        "📥 엑셀 다운로드",
        data=buf.getvalue(),
        file_name=f"근태_월말요약_{home_store_name}_{s_year}-{int(s_month):02d}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        key="erp_sum_dl",
    )


# ---------- user 전용: 내 연차 현황 ----------

def _erp_tab_my_leave_status(current_db: str, me_name: str):
    st.subheader("🎫 내 연차 현황")
    today = _today_kst()
    year = today.year
    grants = _erp_fetch_table("app_leave_grants", {
        "home_db_filename": current_db, "employee_name": me_name, "year": int(year)
    })
    grant = grants[0] if grants else {}
    annual = float(grant.get("annual_days") or 0)
    hire = grant.get("hire_date")
    year_start = date(year, 1, 1)
    year_end = date(year, 12, 31)
    logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", current_db, "log_date", year_start, year_end, extra_eq={"employee_name": me_name})
    annual_used = sum(float(l.get("leave_deduction") or 0) for l in logs if l.get("work_type") == "연차")
    half_used = sum(float(l.get("leave_deduction") or 0) for l in logs if l.get("work_type") == "반차")
    monthly_accrued = _erp_compute_monthly_accrued(hire, today)
    comp_remain = _erp_compute_remaining_comptime(current_db, me_name)

    m1, m2, m3, m4 = st.columns(4)
    with m1:
        st.metric("연차 부여", f"{annual:g}일")
    with m2:
        st.metric("연차 사용", f"{annual_used:g}일", delta=f"잔여 {annual - annual_used:g}일")
    with m3:
        st.metric("월차 적립 / 사용", f"{monthly_accrued} / {half_used:g}일", delta=f"잔여 {monthly_accrued - half_used:g}일")
    with m4:
        st.metric("잔여 시차", f"{comp_remain}분", delta=f"{comp_remain//60}h {comp_remain%60}m")
    st.caption(f"입사일: {hire or '-'} (월차 적립은 입사일 기준 자동 계산, 최대 11일)")


# =====================================================================
# v2 화면 함수 ─ 매장관리자 2종 + 직원 1종
# (메뉴 단순화: admin 7탭→4탭, user 5탭→1~2탭)
# =====================================================================

def _erp_period_target_editor(current_db: str, me_name: str, emp_names: list, today: date,
                               all_dbs: list | None = None):
    """기간 목표 등록/수정/삭제 UI. 직원별 임의 기간(YYYY-MM~YYYY-MM) + 총 시간."""
    st.markdown("##### 🎯 기간 목표 관리")
    st.caption("직원과 기간(시작월~종료월), 기간 총 필수시간을 입력합니다. "
               "예: 김승찬 2026-06 ~ 2026-07, 200시간. "
               "직원당 기간 목표는 1개만 유지되며, 다시 입력하면 기존 값을 덮어씁니다(추가되지 않음).")

    _ym_opts = [_erp_ym_add(f"{today.year:04d}-01", i) for i in range(0, 36)]  # 올해 1월부터 3년치
    _def_start = f"{today.year:04d}-{today.month:02d}"
    _def_start_idx = _ym_opts.index(_def_start) if _def_start in _ym_opts else 0

    # ── 신규 등록 ──────────────────────────────────────────────
    with st.form("pt_period_add", clear_on_submit=True):
        pc = st.columns([2, 1.3, 1.3, 1.2])
        with pc[0]:
            p_emp = st.selectbox("직원", emp_names, key="pt_period_emp")
        with pc[1]:
            p_start = st.selectbox("시작월", _ym_opts, index=_def_start_idx, key="pt_period_start")
        with pc[2]:
            p_end = st.selectbox("종료월", _ym_opts, index=_def_start_idx, key="pt_period_end")
        with pc[3]:
            p_hours = st.number_input("총 시간(h)", min_value=0.0, max_value=20000.0,
                                      value=0.0, step=10.0, key="pt_period_hours")
        p_note = st.text_input("메모 (선택)", key="pt_period_note")
        if st.form_submit_button("💾 기간 목표 저장 (덮어쓰기)", type="primary"):
            if p_start > p_end:
                st.error("종료월이 시작월보다 빠를 수 없습니다.")
            elif p_hours <= 0:
                st.error("총 시간은 0보다 커야 합니다.")
            else:
                # 직원당 1개만 유지: 기존 행이 있으면 첫 행 update, 나머지 삭제. 없으면 insert.
                _existing = _erp_list_period_targets(current_db, p_emp)
                _payload = {
                    "start_ym": p_start,
                    "end_ym": p_end,
                    "required_minutes": int(round(p_hours * 60)),
                    "note": (p_note or "").strip() or None,
                    "updated_by": me_name,
                    "updated_at": datetime.now(timezone.utc).isoformat(),
                }
                if _existing:
                    ok, e = _erp_update_row("app_period_work_targets", int(_existing[0]["id"]), _payload)
                    for _dup in _existing[1:]:
                        _erp_delete_row("app_period_work_targets", int(_dup["id"]))
                    _verb = "덮어쓰기"
                else:
                    ok, e = _erp_insert_row("app_period_work_targets", {
                        "db_filename": current_db,
                        "employee_name": p_emp,
                        "created_by": me_name,
                        **_payload,
                    })
                    _verb = "저장"
                if ok:
                    _erp_list_period_targets.clear()
                    flash(f"기간 목표 {_verb} 완료 — {p_emp} {p_start}~{p_end} {p_hours:g}h")
                    st.rerun()
                else:
                    st.error(f"저장 실패: {e}")

    st.divider()

    # ── 등록된 기간 목표 목록 (수정/삭제) ──────────────────────
    if all_dbs:
        # 전체 매장: 모든 db에서 조회 후 합산
        rows = []
        _seen_ids: set = set()
        for _dbf in all_dbs:
            for _r in _erp_list_period_targets(_dbf):
                if _r.get("id") not in _seen_ids:
                    _seen_ids.add(_r.get("id"))
                    rows.append(_r)
        if rows:
            st.caption(f"📋 전체 매장 등록 기간 목표 ({len(rows)}건)")
    else:
        rows = _erp_list_period_targets(current_db)

    if not rows:
        st.info("등록된 기간 목표가 없습니다.")
        return

    st.markdown("**등록된 기간 목표**")
    _edit_id = st.session_state.get("pt_period_edit_id")
    for r in sorted(rows, key=lambda x: (x.get("employee_name") or "", x.get("start_ym") or "")):
        rid = int(r["id"])
        _hours = round(int(r.get("required_minutes") or 0) / 60, 1)
        if _edit_id == rid:
            with st.container(border=True):
                st.markdown(f"**✏️ 수정 (#{rid}) — {r.get('employee_name')}**")
                with st.form(f"pt_period_edit_{rid}", clear_on_submit=False):
                    ec = st.columns([1.3, 1.3, 1.2])
                    _si = _ym_opts.index(r["start_ym"]) if r.get("start_ym") in _ym_opts else 0
                    _ei = _ym_opts.index(r["end_ym"]) if r.get("end_ym") in _ym_opts else 0
                    with ec[0]:
                        e_start = st.selectbox("시작월", _ym_opts, index=_si, key=f"pt_pe_s_{rid}")
                    with ec[1]:
                        e_end = st.selectbox("종료월", _ym_opts, index=_ei, key=f"pt_pe_e_{rid}")
                    with ec[2]:
                        e_hours = st.number_input("총 시간(h)", min_value=0.0, max_value=20000.0,
                                                  value=float(_hours), step=10.0, key=f"pt_pe_h_{rid}")
                    e_note = st.text_input("메모", value=r.get("note") or "", key=f"pt_pe_n_{rid}")
                    bc = st.columns([1, 1, 4])
                    with bc[0]:
                        _save = st.form_submit_button("💾 저장", type="primary")
                    with bc[1]:
                        _cancel = st.form_submit_button("취소")
                if _cancel:
                    st.session_state.pop("pt_period_edit_id", None)
                    st.rerun()
                if _save:
                    if e_start > e_end:
                        st.error("종료월이 시작월보다 빠를 수 없습니다.")
                    elif e_hours <= 0:
                        st.error("총 시간은 0보다 커야 합니다.")
                    else:
                        ok, e = _erp_update_row("app_period_work_targets", rid, {
                            "start_ym": e_start,
                            "end_ym": e_end,
                            "required_minutes": int(round(e_hours * 60)),
                            "note": (e_note or "").strip() or None,
                            "updated_by": me_name,
                            "updated_at": datetime.now(timezone.utc).isoformat(),
                        })
                        if ok:
                            _erp_list_period_targets.clear()
                            st.session_state.pop("pt_period_edit_id", None)
                            flash("기간 목표가 수정되었습니다.")
                            st.rerun()
                        else:
                            st.error(f"수정 실패: {e}")
        else:
            lc = st.columns([2, 2.4, 1.3, 2.5, 0.7, 0.7])
            with lc[0]:
                st.markdown(f"**{r.get('employee_name')}**")
            with lc[1]:
                st.text(f"{r.get('start_ym')} ~ {r.get('end_ym')}")
            with lc[2]:
                st.text(f"{_hours:g}h")
            with lc[3]:
                st.caption(r.get("note") or "")
            with lc[4]:
                if st.button("✏️", key=f"pt_pedit_{rid}", help="수정"):
                    st.session_state["pt_period_edit_id"] = rid
                    st.rerun()
            with lc[5]:
                if st.button("🗑️", key=f"pt_pdel_{rid}", help="삭제"):
                    ok, e = _erp_delete_row("app_period_work_targets", rid)
                    if ok:
                        _erp_list_period_targets.clear()
                        flash("기간 목표가 삭제되었습니다.")
                        st.rerun()
                    else:
                        st.error(f"삭제 실패: {e}")


def _erp_tab_period_targets(current_db: str, me_name: str):
    """매장관리자: 근무시간 설정 (기간 목표 입력)."""
    role = (st.session_state.get("current_user") or {}).get("role") or "user"
    if role not in ("store_admin", "superadmin"):
        st.warning("매장 관리자 이상만 접근할 수 있습니다.")
        return

    st.subheader("⏰ 근무시간 설정")
    st.caption(
        "직원별로 임의 기간(예: 2026-06~2026-12, 1275h)의 필수 근무시간 목표를 입력합니다. "
        "대시보드 「공통 필요근무시간」에 1순위로 반영됩니다."
    )

    today = _today_kst()

    # ── 매장 선택 드롭다운 ──────────────────────────────────────
    _all_stores = _get_supabase_stores_list() or []
    _store_opts = [("전체 매장", None)] + [(s["store_name"], s["db_filename"]) for s in _all_stores]
    _store_labels = [s[0] for s in _store_opts]
    _default_store_idx = next(
        (i for i, s in enumerate(_store_opts) if s[1] == current_db), 0
    )
    _sel_store_label = st.selectbox(
        "📍 매장 선택", _store_labels, index=_default_store_idx, key="pt_store_filter"
    )
    _sel_store_dbf = next((s[1] for s in _store_opts if s[0] == _sel_store_label), None)

    # ── 선택 매장 기준 직원 목록 ───────────────────────────────
    if _sel_store_dbf is None:
        # 전체 매장: 모든 매장 직원 합집합
        _emp_set: set[str] = set()
        _all_dbfs = [s["db_filename"] for s in _all_stores]
        for _s in _all_stores:
            for _e in (_erp_get_employee_names_for_store(_s["db_filename"]) or []):
                _emp_set.add(_e)
        emp_names = sorted(_emp_set)
        _target_db = current_db  # 신규 등록은 현재 관리자 home db에 저장
    else:
        emp_names = _erp_get_employee_names_for_store(_sel_store_dbf) or []
        _target_db = _sel_store_dbf
        _all_dbfs = None

    if not emp_names:
        st.info("선택한 매장에 배정된 직원이 없습니다. 직원 관리에서 매장을 배정해 주세요.")
        return

    _erp_period_target_editor(_target_db, me_name, emp_names, today, all_dbs=_all_dbfs)


def _erp_tab_adjustment_approvals(current_db: str, me_name: str):
    """매장관리자: 직원 신청 승인/반려 큐 (본인 신청 자가 승인 포함)."""
    st.subheader("📥 신청 승인")
    st.caption("직원이 올린 +(추가근무·회의)/-(휴무·포상·여름휴가) 신청을 검토합니다. 승인 시 해당 직원의 월·연 잔여 시간에 즉시 반영됩니다.")
    st.caption("ⓘ 매장 관리자 본인이 올린 신청도 이 큐에서 직접 승인/반려할 수 있습니다.")

    pending = _erp_list_pending_adjustments(current_db)
    # 근무지 표기용 매장 → 이름 매핑 (한 번만 조회)
    _appr_stores_all = _get_supabase_stores_list(include_inactive=True) or []
    _dbf_to_store = {s.get("db_filename"): s.get("store_name") or s.get("db_filename")
                     for s in _appr_stores_all}

    def _resolve_worksite(adj_row: dict) -> str:
        """work_location_name(외부) 우선 → work_db_filename → db_filename 순으로 매장명 반환."""
        _wl = (adj_row.get("work_location_name") or "").strip()
        if _wl:
            return _wl
        _wdb = adj_row.get("work_db_filename")
        if _wdb and _dbf_to_store.get(_wdb):
            return _dbf_to_store[_wdb]
        _hdb = adj_row.get("db_filename")
        if _hdb and _dbf_to_store.get(_hdb):
            return _dbf_to_store[_hdb]
        return "-"

    if not pending:
        st.info("대기 중인 신청이 없습니다.")
    else:
        st.caption(f"대기 중 {len(pending)}건")
    for adj in pending:
        adj_id = int(adj["id"])
        kind = adj.get("kind") or "etc"
        sign = adj.get("sign") or "+"
        minutes = int(adj.get("minutes") or 0)
        hours_display = f"{minutes//60}h {minutes%60}m" if minutes % 60 else f"{minutes//60}h"
        _pv_ss = str(adj.get("shift_start") or "")[:5]
        _pv_ee = str(adj.get("shift_end") or "")[:5]
        _dur_txt = f"{_pv_ss}~{_pv_ee} ({hours_display})" if (_pv_ss and _pv_ee) else hours_display
        _worksite = _resolve_worksite(adj)
        with st.container(border=True):
            c = st.columns([1.3, 1, 0.4, 1.6, 1.2, 2.0, 1, 1])
            with c[0]:
                st.markdown(f"**{adj.get('employee_name') or '-'}**")
                st.caption(str(adj.get("created_at") or "")[:16])
            with c[1]:
                st.markdown(f"{str(adj.get('target_date') or '')[:10]}")
            with c[2]:
                st.markdown(f"### {sign}")
            with c[3]:
                st.markdown(f"{_ERP_ADJ_KIND_LABEL.get(kind, kind)} · {_dur_txt}")
            with c[4]:
                st.markdown(f"📍 {_worksite}")
            with c[5]:
                st.caption(adj.get("reason") or "")
            with c[6]:
                if st.button("✅ 승인", key=f"adj_ok_{adj_id}"):
                    ok, e = _erp_update_row("app_work_adjustments", adj_id, {
                        "status": "approved",
                        "approved_by": me_name,
                        "approved_at": datetime.now(timezone.utc).isoformat(),
                    })
                    if ok:
                        _erp_v2_clear_caches()
                        # 캘린더(app_attendance_logs) 자동 upsert — 중복 방지 로직 포함
                        _log_ok, _log_err = _erp_upsert_log_from_adjustment(
                            adj, sign=sign, kind=kind, minutes=minutes,
                            fallback_home_db=current_db, created_by=me_name,
                        )
                        _wt_show = _ERP_ADJ_KIND_TO_WORK_TYPE.get(kind, kind)
                        _td_show = str(adj.get("target_date") or "")[:10]
                        if _log_ok:
                            st.toast(
                                f"📅 캘린더 반영: {adj.get('employee_name')} {_td_show} ({sign}{_wt_show})",
                                icon="📅",
                            )
                        elif _log_err:
                            st.error(f"❌ 캘린더 반영 실패: {_log_err}")
                        flash(f"승인: {adj.get('employee_name')} {sign}{hours_display}")
                        st.rerun()
                    else:
                        st.error(f"승인 실패: {e}")
            with c[7]:
                with st.popover("❌ 반려"):
                    reject_reason = st.text_input("반려 사유", key=f"adj_rj_reason_{adj_id}")
                    if st.button("반려 확정", key=f"adj_rj_btn_{adj_id}", type="primary"):
                        ok, e = _erp_update_row("app_work_adjustments", adj_id, {
                            "status": "rejected",
                            "approved_by": me_name,
                            "approved_at": datetime.now(timezone.utc).isoformat(),
                            "reject_reason": (reject_reason or "").strip() or None,
                        })
                        if ok:
                            _erp_v2_clear_caches()
                            flash(f"반려: {adj.get('employee_name')}")
                            st.rerun()
                        else:
                            st.error(f"반려 실패: {e}")

    # ── 승인 완료 내역 (취소 가능) ─────────────────────────────────────
    st.divider()
    with st.expander("✅ 승인 완료 내역 확인 및 취소", expanded=False):
        st.caption(
            "승인된 내역을 취소하면 신청 상태가 '대기'로 돌아가고, "
            "캘린더(app_attendance_logs)에 자동 반영된 근무 기록도 함께 삭제됩니다."
        )
        try:
            _appr_client, _appr_err = get_supabase_client()
            if _appr_err or not _appr_client:
                st.error(f"DB 연결 실패: {_appr_err}")
            else:
                _appr_rows = _appr_client.table("app_work_adjustments").select("*")\
                    .eq("db_filename", current_db)\
                    .eq("status", "approved")\
                    .order("target_date", desc=True)\
                    .limit(50).execute().data or []
                if not _appr_rows:
                    st.info("승인 완료된 신청이 없습니다.")
                else:
                    st.caption(f"최근 50건 표시")
                    for _ar in _appr_rows:
                        _arid = int(_ar.get("id") or 0)
                        _ar_kind = _ar.get("kind") or "etc"
                        _ar_sign = _ar.get("sign") or "+"
                        _ar_min = int(_ar.get("minutes") or 0)
                        _ar_h = f"{_ar_min//60}h {_ar_min%60}m" if _ar_min % 60 else f"{_ar_min//60}h"
                        _arc = st.columns([1.2, 1, 0.4, 1.5, 2.5, 1.3])
                        with _arc[0]:
                            st.markdown(f"**{_ar.get('employee_name') or '-'}**")
                        with _arc[1]:
                            st.markdown(str(_ar.get("target_date") or "")[:10])
                        with _arc[2]:
                            st.markdown(f"### {_ar_sign}")
                        with _arc[3]:
                            st.markdown(f"{_ERP_ADJ_KIND_LABEL.get(_ar_kind, _ar_kind)} · {_ar_h}")
                        with _arc[4]:
                            st.caption((_ar.get("reason") or "") + (f" | 승인: {_ar.get('approved_by') or ''}" if _ar.get("approved_by") else ""))
                        with _arc[5]:
                            with st.popover("↩️ 승인 취소"):
                                st.warning("승인을 취소하면 캘린더 기록도 삭제됩니다.")
                                if st.button("취소 확정", key=f"appr_cancel_{_arid}", type="primary"):
                                    # 1) app_work_adjustments → pending 복원
                                    _ok_rev, _err_rev = _erp_update_row("app_work_adjustments", _arid, {
                                        "status": "pending",
                                        "approved_by": None,
                                        "approved_at": None,
                                    })
                                    if _ok_rev:
                                        # 2) app_attendance_logs 에서 동일 직원·날짜·유형 레코드 삭제
                                        # kind 별 매핑을 사용해 모든 kind 의 승인 취소 시 log 정리.
                                        _wt_del = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_ar_kind)
                                        if _wt_del:
                                            try:
                                                _del_logs = _appr_client.table("app_attendance_logs").select("id")\
                                                    .eq("employee_name", _ar.get("employee_name"))\
                                                    .eq("log_date", str(_ar.get("target_date") or "")[:10])\
                                                    .eq("work_type", _wt_del)\
                                                    .execute().data or []
                                                for _dl in _del_logs:
                                                    _erp_delete_row("app_attendance_logs", int(_dl["id"]))
                                            except Exception as _del_ex:
                                                st.warning(f"캘린더 기록 삭제 중 오류: {_del_ex}")
                                        _erp_v2_clear_caches()
                                        flash(f"승인 취소: {_ar.get('employee_name')} {str(_ar.get('target_date') or '')[:10]}")
                                        st.rerun()
                                    else:
                                        st.error(f"취소 실패: {_err_rev}")
        except Exception as _appr_ex:
            st.error(f"조회 오류: {_appr_ex}")

    # ── 기존 승인 내역 캘린더 재동기화 ────────────────────────────────
    st.divider()
    with st.expander("🔄 기존 승인 내역 캘린더 재동기화", expanded=False):
        st.caption(
            "과거에 승인된 신청(추가근무·회의·조기퇴근·여름휴가·포상·장기근속·특이사항) 중 "
            "캘린더(app_attendance_logs)에 반영되지 않았거나 시간대가 비어 있는 항목을 일괄 동기화·보강합니다."
        )
        _sync_year = st.number_input("대상 연도", min_value=2020, max_value=2100,
                                     value=_today_kst().year, step=1, key="sync_year")
        if st.button("🔄 동기화 실행", key="sync_approved_btn"):
            try:
                _sb2 = get_supabase_client_or_warn()
                if _sb2 is None:
                    st.stop()
                # 해당 연도 전체 kind 승인 내역 조회 (조기퇴근·여름휴가·포상·장기근속·특이사항 포함)
                _sync_rows = _sb2.table("app_work_adjustments").select("*")\
                    .eq("status", "approved")\
                    .in_("kind", list(_ERP_ADJ_KIND_TO_WORK_TYPE.keys()))\
                    .execute().data or []
                _sync_rows = [r for r in _sync_rows
                              if str(r.get("target_date") or "").startswith(str(int(_sync_year)))]

                # 이미 app_attendance_logs 에 있는 항목 파악 (id 포함, home_db_filename 검증용)
                _existing_logs = _sb2.table("app_attendance_logs")\
                    .select("id,employee_name,log_date,work_type,home_db_filename,diff_minutes,start_time,end_time")\
                    .in_("work_type", list(_ERP_ADJ_KIND_TO_WORK_TYPE.values()))\
                    .execute().data or []
                _existing_map = {
                    (r.get("employee_name"), str(r.get("log_date") or "")[:10], r.get("work_type")): r
                    for r in _existing_logs
                }

                _synced = 0
                _repaired = 0
                _skipped = 0
                _failed = []
                for _r in _sync_rows:
                    _kind = _r.get("kind") or "etc"
                    _sign_r = _r.get("sign") or "+"
                    _wt = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_kind, "특이사항")
                    _emp = _r.get("employee_name") or ""
                    _dt = str(_r.get("target_date") or "")[:10]
                    _r_db = _r.get("db_filename") or current_db
                    _existing = _existing_map.get((_emp, _dt, _wt))
                    _existing_id = None
                    if _existing:
                        try:
                            _existing_id = int(_existing.get("id") or 0) or None
                        except Exception:
                            _existing_id = None
                    if _existing and _existing_id:
                        # 이미 존재하는 로그를 신청서(app_work_adjustments) 와 일치하도록 정정.
                        #  - home_db_filename: 승인자 current_db 로 잘못 저장된 케이스
                        #  - start_time/end_time: 시간대 컬럼 도입 이전에 승인된 케이스
                        #  - diff_minutes: 음수·0 등 신청 분과 불일치인 케이스
                        _cur_hdb = _existing.get("home_db_filename")
                        _r_shift_s = str(_r.get("shift_start") or "")[:8] or None
                        _r_shift_e = str(_r.get("shift_end") or "")[:8] or None
                        _r_min = int(_r.get("minutes") or 0)
                        _cur_st = str(_existing.get("start_time") or "")[:8] or None
                        _cur_et = str(_existing.get("end_time") or "")[:8] or None
                        _cur_dm = int(_existing.get("diff_minutes") or 0)
                        _patch = {}
                        if _r_db and _cur_hdb != _r_db:
                            _patch["home_db_filename"] = _r_db
                        if _r_shift_s and _r_shift_s[:5] != (_cur_st or "")[:5]:
                            _patch["start_time"] = _r_shift_s
                        if _r_shift_e and _r_shift_e[:5] != (_cur_et or "")[:5]:
                            _patch["end_time"] = _r_shift_e
                        # + kind 는 항상 양수 diff, - kind 는 절대값 저장 규약.
                        # 불일치 (예: 음수·0) 이면 신청서 값으로 정정.
                        if _r_min and _cur_dm != _r_min:
                            _patch["diff_minutes"] = _r_min
                        if _patch:
                            try:
                                _uok, _uerr = _erp_update_row("app_attendance_logs",
                                                              _existing_id, _patch)
                            except Exception as _uex:
                                _uok, _uerr = False, str(_uex)
                            if _uok:
                                _repaired += 1
                            else:
                                _failed.append(f"{_emp}/{_dt} 정정 실패: {_uerr}")
                        else:
                            _skipped += 1
                        continue
                    if _existing and not _existing_id:
                        # 같은 반복 안에서 이전 iteration 이 신규 삽입한 placeholder → 중복 인식용, 스킵.
                        _skipped += 1
                        continue
                    # 신규 로그 생성: 헬퍼로 위임 (동일 upsert 로직 재사용)
                    try:
                        _lok, _lerr = _erp_upsert_log_from_adjustment(
                            _r, sign=_sign_r, kind=_kind, minutes=int(_r.get("minutes") or 0),
                            fallback_home_db=current_db, created_by=me_name,
                        )
                    except Exception as _lex:
                        _lok, _lerr = False, str(_lex)
                    if _lok:
                        _synced += 1
                        _existing_map[(_emp, _dt, _wt)] = {
                            "employee_name": _emp, "log_date": _dt,
                            "work_type": _wt, "home_db_filename": _r_db,
                        }
                    else:
                        _failed.append(f"{_emp}/{_dt}: {_lerr}")

                _parts = []
                if _synced:
                    _parts.append(f"신규 반영 {_synced}건")
                if _repaired:
                    _parts.append(f"소속 매장 정정 {_repaired}건")
                if _skipped:
                    _parts.append(f"이미 존재 {_skipped}건")
                if _parts:
                    st.success("✅ 동기화 완료 — " + ", ".join(_parts))
                else:
                    st.info(f"{int(_sync_year)}년 동기화할 항목이 없습니다.")
                if _failed:
                    st.warning("일부 실패:\n" + "\n".join(_failed))
            except Exception as _se:
                import traceback as _tb
                st.error(f"동기화 오류: {type(_se).__name__}: {_se}")
                with st.expander("스택 트레이스 (디버그용)", expanded=False):
                    st.code(_tb.format_exc(), language="text")

    # ── 시간대 누락 승인건 시작·종료 시각 보강 (캘린더 배지에 실제 시각 표시) ──
    with st.expander("🩹 시간대 누락 승인건 보강 (추가근무·회의 시각 입력)", expanded=False):
        st.caption(
            "구버전에서 시간대 컬럼 없이 승인된 추가근무·회의 신청은 캘린더에서 "
            "'+Xh' 형태로만 표시됩니다. 각 행의 시작 시각만 확인·수정하면 종료 시각은 "
            "'시작 + 신청분' 으로 자동 계산됩니다. **[일괄 저장]** 으로 한 번에 처리할 수 있습니다."
        )

        def _bf_hhmm_to_s(v: str) -> str | None:
            v = (v or "").strip()
            if not v:
                return None
            try:
                # HH:MM / HHMM / H:M 등 유연 파싱
                _p = _erp_parse_time_loose(v)
                if _p is None:
                    return None
                return f"{_p[0]:02d}:{_p[1]:02d}:00"
            except Exception:
                return None

        def _bf_add_minutes(hhmm_s: str, add_min: int) -> str:
            """'HH:MM:SS' + add_min → 'HH:MM:SS' (24h wrap 없이 안전 clip)."""
            try:
                _h, _m, _ = hhmm_s.split(":")
                _total = int(_h) * 60 + int(_m) + int(add_min)
                _total = max(0, min(_total, 23 * 60 + 59))
                return f"{_total // 60:02d}:{_total % 60:02d}:00"
            except Exception:
                return hhmm_s

        try:
            _sb_bf = get_supabase_client_or_warn()
            if _sb_bf is None:
                st.stop()
            _bf_rows_raw = _sb_bf.table("app_work_adjustments").select("*")\
                .eq("status", "approved")\
                .in_("kind", ["overtime", "meeting"])\
                .execute().data or []
            _bf_rows = [
                r for r in _bf_rows_raw
                if not str(r.get("shift_start") or "").strip()
                or not str(r.get("shift_end") or "").strip()
            ]
            _bf_rows.sort(key=lambda r: str(r.get("target_date") or ""), reverse=True)

            if not _bf_rows:
                st.success("✅ 시간대가 비어 있는 승인 건이 없습니다. 새 신청은 자동으로 시각이 표시됩니다.")
            else:
                st.warning(f"⚠️ 시간대 미입력 승인 건: {len(_bf_rows)}건 (한 화면에 최대 50건)")
                _bf_visible = _bf_rows[:50]

                # 스마트 기본값 계산: 정기근무 종료시각 이후로 배치 (없으면 18:00)
                _bf_default_starts: dict[int, str] = {}
                for _bf in _bf_visible:
                    _bfid = int(_bf.get("id") or 0)
                    _emp_bf = _bf.get("employee_name") or ""
                    _dt_bf = str(_bf.get("target_date") or "")[:10]
                    _db_bf = _bf.get("db_filename") or current_db
                    _default = "18:00"
                    try:
                        _dt_obj = date.fromisoformat(_dt_bf)
                        _sh_s, _sh_e = _erp_shift_bounds_for_date(_db_bf, _emp_bf, _dt_obj)
                        if _sh_e and (_sh_e.hour or _sh_e.minute):
                            _default = _sh_e.strftime("%H:%M")
                    except Exception:
                        pass
                    _bf_default_starts[_bfid] = _default

                for _bf in _bf_visible:
                    _bfid = int(_bf.get("id") or 0)
                    _bf_emp = _bf.get("employee_name") or "-"
                    _bf_dt = str(_bf.get("target_date") or "")[:10]
                    _bf_kind = _bf.get("kind") or "overtime"
                    _bf_min = int(_bf.get("minutes") or 0)
                    _bf_hm = f"{_bf_min//60}h {_bf_min%60}m" if _bf_min % 60 else f"{_bf_min//60}h"
                    _bf_label = "추가근무" if _bf_kind == "overtime" else "회의"
                    _bf_reason = (_bf.get("reason") or "").strip()
                    with st.container(border=True):
                        _bfc = st.columns([2.2, 1.1, 1.2, 1.2, 0.9])
                        _bfc[0].markdown(
                            f"**{_bf_emp}** · {_bf_label} · **{_bf_hm}**"
                            + (f"  \n<span style='font-size:0.75rem;color:#666'>{_bf_reason}</span>"
                               if _bf_reason else ""),
                            unsafe_allow_html=True,
                        )
                        _bfc[1].markdown(_bf_dt)
                        _bf_start_val = _bfc[2].text_input(
                            "시작 (HH:MM)",
                            value=_bf_default_starts.get(_bfid, "18:00"),
                            key=f"bf_start_{_bfid}",
                            placeholder="예: 18:00 · 1800",
                        )
                        _bf_end_default = ""
                        _bf_start_parsed = _bf_hhmm_to_s(_bf_start_val)
                        if _bf_start_parsed and _bf_min > 0:
                            _bf_end_default = _bf_add_minutes(_bf_start_parsed, _bf_min)[:5]
                        _bf_end_val = _bfc[3].text_input(
                            "종료 (HH:MM)",
                            value=_bf_end_default,
                            key=f"bf_end_{_bfid}",
                            placeholder=f"자동: 시작+{_bf_min}분",
                        )
                        with _bfc[4]:
                            _save_one = st.button("💾", key=f"bf_save_{_bfid}",
                                                   help="이 건만 저장")

                        # 개별 저장 처리
                        if _save_one:
                            _s_str = _bf_hhmm_to_s(_bf_start_val)
                            _e_str = _bf_hhmm_to_s(_bf_end_val)
                            if _s_str and not _e_str and _bf_min > 0:
                                _e_str = _bf_add_minutes(_s_str, _bf_min)
                            if not _s_str or not _e_str:
                                st.error("시작·종료 시각을 HH:MM 형식으로 입력하세요.")
                            elif _e_str <= _s_str:
                                st.error("종료 시각이 시작보다 늦어야 합니다.")
                            else:
                                _u1_ok, _u1_err = _erp_update_row(
                                    "app_work_adjustments", _bfid,
                                    {"shift_start": _s_str, "shift_end": _e_str},
                                )
                                _wt_bf = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_bf_kind, "특이사항")
                                _log_existing = _sb_bf.table("app_attendance_logs")\
                                    .select("id")\
                                    .eq("employee_name", _bf_emp)\
                                    .eq("log_date", _bf_dt)\
                                    .eq("work_type", _wt_bf)\
                                    .execute().data or []
                                if _log_existing:
                                    _u2_ok, _u2_err = _erp_update_row(
                                        "app_attendance_logs",
                                        int(_log_existing[0]["id"]),
                                        {"start_time": _s_str, "end_time": _e_str},
                                    )
                                else:
                                    _bf_refetch = dict(_bf)
                                    _bf_refetch["shift_start"] = _s_str
                                    _bf_refetch["shift_end"] = _e_str
                                    _u2_ok, _u2_err = _erp_upsert_log_from_adjustment(
                                        _bf_refetch, sign="+", kind=_bf_kind,
                                        minutes=_bf_min, fallback_home_db=current_db,
                                        created_by=me_name,
                                    )
                                if _u1_ok and _u2_ok:
                                    _erp_v2_clear_caches()
                                    st.success(f"✅ {_bf_emp} {_bf_dt} {_s_str[:5]}~{_e_str[:5]}")
                                    st.rerun()
                                else:
                                    _msgs = []
                                    if not _u1_ok:
                                        _msgs.append(f"신청서: {_u1_err}")
                                    if not _u2_ok:
                                        _msgs.append(f"로그: {_u2_err}")
                                    st.error("일부 실패: " + " / ".join(_msgs))

                # ── 일괄 저장 ─────────────────────────────────
                st.divider()
                _batch_col1, _batch_col2 = st.columns([1, 4])
                with _batch_col1:
                    _batch_btn = st.button("🗂️ 일괄 저장 (표시된 건 모두)", type="primary",
                                           key="bf_batch_save")
                with _batch_col2:
                    st.caption("각 행의 시작 시각과 자동/수동 종료 시각으로 신청서·로그를 일괄 정정합니다.")

                if _batch_btn:
                    _bok, _bfail = 0, []
                    for _bf in _bf_visible:
                        _bfid = int(_bf.get("id") or 0)
                        _s_raw = st.session_state.get(f"bf_start_{_bfid}", "")
                        _e_raw = st.session_state.get(f"bf_end_{_bfid}", "")
                        _bf_kind = _bf.get("kind") or "overtime"
                        _bf_min = int(_bf.get("minutes") or 0)
                        _bf_emp = _bf.get("employee_name") or "-"
                        _bf_dt = str(_bf.get("target_date") or "")[:10]
                        _s_str = _bf_hhmm_to_s(_s_raw)
                        _e_str = _bf_hhmm_to_s(_e_raw)
                        if _s_str and not _e_str and _bf_min > 0:
                            _e_str = _bf_add_minutes(_s_str, _bf_min)
                        if not _s_str or not _e_str or _e_str <= _s_str:
                            _bfail.append(f"{_bf_emp}/{_bf_dt}: 시각 형식 오류")
                            continue
                        _u1_ok, _u1_err = _erp_update_row(
                            "app_work_adjustments", _bfid,
                            {"shift_start": _s_str, "shift_end": _e_str},
                        )
                        _wt_bf = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_bf_kind, "특이사항")
                        _log_existing = _sb_bf.table("app_attendance_logs")\
                            .select("id")\
                            .eq("employee_name", _bf_emp)\
                            .eq("log_date", _bf_dt)\
                            .eq("work_type", _wt_bf)\
                            .execute().data or []
                        if _log_existing:
                            _u2_ok, _u2_err = _erp_update_row(
                                "app_attendance_logs",
                                int(_log_existing[0]["id"]),
                                {"start_time": _s_str, "end_time": _e_str},
                            )
                        else:
                            _bf_refetch = dict(_bf)
                            _bf_refetch["shift_start"] = _s_str
                            _bf_refetch["shift_end"] = _e_str
                            _u2_ok, _u2_err = _erp_upsert_log_from_adjustment(
                                _bf_refetch, sign="+", kind=_bf_kind,
                                minutes=_bf_min, fallback_home_db=current_db,
                                created_by=me_name,
                            )
                        if _u1_ok and _u2_ok:
                            _bok += 1
                        else:
                            _errs = []
                            if not _u1_ok:
                                _errs.append(f"신청서:{_u1_err}")
                            if not _u2_ok:
                                _errs.append(f"로그:{_u2_err}")
                            _bfail.append(f"{_bf_emp}/{_bf_dt}: " + " · ".join(_errs))
                    _erp_v2_clear_caches()
                    if _bok:
                        st.success(f"✅ 일괄 저장 완료 {_bok}건")
                    if _bfail:
                        st.warning("일부 실패:\n- " + "\n- ".join(_bfail))
                    if _bok:
                        st.rerun()

                if len(_bf_rows) > 50:
                    st.caption(f"…이 외 {len(_bf_rows) - 50}건 더 있습니다. 위 건을 처리하면 이어서 표시됩니다.")
        except Exception as _bf_ex:
            import traceback as _tb2
            st.error(f"보강 목록 조회 오류: {type(_bf_ex).__name__}: {_bf_ex}")
            with st.expander("스택 트레이스", expanded=False):
                st.code(_tb2.format_exc(), language="text")

    # ── 진단: 특정 날짜·직원의 로그·신청 상태 확인 ─────────────────────
    with st.expander("🔎 캘린더 반영 진단 (특정 날짜·직원)", expanded=False):
        st.caption(
            "캘린더에 추가근무·회의가 안 나올 때, 실제 DB 에 어떻게 저장되어 있는지 확인합니다."
        )
        _diag_c1, _diag_c2 = st.columns([2, 2])
        with _diag_c1:
            _diag_stores = _get_supabase_stores_list() or []               # 활성 매장 (캘린더 표시 기준)
            _diag_stores_all = _get_supabase_stores_list(include_inactive=True) or []  # 폐점 포함
            _diag_all_emps: list[str] = []
            for _s in _diag_stores_all:
                _diag_all_emps += _erp_get_employee_names_for_store(_s.get("db_filename"))
            _diag_all_emps = sorted(set([e for e in _diag_all_emps if e]))
            _diag_emp = st.selectbox("직원", options=_diag_all_emps or [""],
                                     key="diag_emp_pick")
        with _diag_c2:
            _diag_date = st.date_input("날짜", value=_today_kst(), key="diag_date_pick")

        if st.button("🔎 조회", key="diag_run"):
            try:
                _sb_d = get_supabase_client_or_warn()
                if _sb_d is None:
                    st.stop()
                _diag_iso = _diag_date.isoformat()
                _adj = _sb_d.table("app_work_adjustments").select("*")\
                    .eq("employee_name", _diag_emp)\
                    .eq("target_date", _diag_iso)\
                    .execute().data or []
                _lgs = _sb_d.table("app_attendance_logs").select("*")\
                    .eq("employee_name", _diag_emp)\
                    .eq("log_date", _diag_iso)\
                    .execute().data or []

                st.markdown(f"**📋 app_work_adjustments** ({len(_adj)}건)")
                if _adj:
                    _adj_view = [{
                        "id": a.get("id"),
                        "kind": a.get("kind"),
                        "sign": a.get("sign"),
                        "minutes": a.get("minutes"),
                        "status": a.get("status"),
                        "db_filename": a.get("db_filename"),
                        "shift_start": str(a.get("shift_start") or "")[:5],
                        "shift_end": str(a.get("shift_end") or "")[:5],
                        "work_db_filename": a.get("work_db_filename") or "",
                        "work_location_name": a.get("work_location_name") or "",
                        "reason": a.get("reason"),
                    } for a in _adj]
                    st.dataframe(pd.DataFrame(_adj_view), width="stretch",
                                 hide_index=True)
                else:
                    st.info("해당 날짜·직원의 신청 내역이 없습니다.")

                st.markdown(f"**📅 app_attendance_logs** ({len(_lgs)}건)")
                if _lgs:
                    _lg_view = [{
                        "id": l.get("id"),
                        "work_type": l.get("work_type"),
                        "diff_minutes": l.get("diff_minutes"),
                        "home_db_filename": l.get("home_db_filename"),
                        "work_db_filename": l.get("work_db_filename"),
                        "work_location_name": l.get("work_location_name"),
                        "start_time": str(l.get("start_time") or "")[:5],
                        "end_time": str(l.get("end_time") or "")[:5],
                        "status": l.get("status"),
                    } for l in _lgs]
                    st.dataframe(pd.DataFrame(_lg_view), width="stretch",
                                 hide_index=True)

                    # 캘린더가 실제 조회하는 매장 목록 (활성 매장만)
                    _active_dbs = {s.get("db_filename") for s in _diag_stores}
                    _all_known_dbs = {s.get("db_filename") for s in _diag_stores_all}
                    _inactive_dbs = _all_known_dbs - _active_dbs
                    _bad_inactive = [l for l in _lgs
                                     if l.get("home_db_filename") and l.get("home_db_filename") in _inactive_dbs]
                    _bad_unknown = [l for l in _lgs
                                    if l.get("home_db_filename") and l.get("home_db_filename") not in _all_known_dbs]
                    if _bad_inactive:
                        st.error(
                            f"⛔ {len(_bad_inactive)}건의 로그가 **폐점(비활성) 매장 DB** "
                            f"({', '.join(sorted({l.get('home_db_filename') for l in _bad_inactive}))}) "
                            f"로 저장되어 캘린더에 표시되지 않습니다. "
                            f"슈퍼관리자 → 매장 관리에서 해당 매장을 다시 활성화하거나, "
                            f"Supabase 에서 로그의 `home_db_filename` 을 활성 매장으로 이관해야 합니다."
                        )
                    if _bad_unknown:
                        st.error(
                            f"⚠️ {len(_bad_unknown)}건의 로그가 등록되지 않은 매장 DB "
                            f"({', '.join(sorted({l.get('home_db_filename') for l in _bad_unknown}))}) "
                            f"로 저장되어 있어 캘린더에 표시되지 않습니다. "
                            f"'기존 승인 내역 캘린더 재동기화' 를 실행하세요."
                        )

                    # 신청서 ↔ 로그 시간·분 불일치 검증
                    _approved_adjs = [a for a in _adj if (a.get("status") == "approved")]
                    if _approved_adjs:
                        _mismatches: list[str] = []
                        for _a in _approved_adjs:
                            _wt_map = _ERP_ADJ_KIND_TO_WORK_TYPE.get(_a.get("kind") or "etc", "특이사항")
                            _matched = next((l for l in _lgs if l.get("work_type") == _wt_map), None)
                            if not _matched:
                                _mismatches.append(
                                    f"'{_wt_map}' 로그 없음 (kind={_a.get('kind')}, minutes={_a.get('minutes')})"
                                )
                                continue
                            _a_ss = str(_a.get("shift_start") or "")[:5]
                            _a_ee = str(_a.get("shift_end") or "")[:5]
                            _l_ss = str(_matched.get("start_time") or "")[:5]
                            _l_ee = str(_matched.get("end_time") or "")[:5]
                            _a_min = int(_a.get("minutes") or 0)
                            _l_min = int(_matched.get("diff_minutes") or 0)
                            _detail_parts = []
                            if _a_ss and _a_ss != _l_ss:
                                _detail_parts.append(f"시작 신청={_a_ss} vs 로그={_l_ss or '(비어있음)'}")
                            if _a_ee and _a_ee != _l_ee:
                                _detail_parts.append(f"종료 신청={_a_ee} vs 로그={_l_ee or '(비어있음)'}")
                            if _a_min and _a_min != _l_min:
                                _detail_parts.append(f"분 신청={_a_min} vs 로그={_l_min}")
                            if _detail_parts:
                                _mismatches.append(f"'{_wt_map}' — " + " · ".join(_detail_parts))
                        if _mismatches:
                            st.warning(
                                "⚠️ 신청서와 로그 데이터가 어긋납니다 — '기존 승인 내역 재동기화' 로 정정하세요:\n\n- "
                                + "\n- ".join(_mismatches)
                            )
                else:
                    st.warning(
                        "⚠️ 캘린더 로그가 없습니다. 신청 내역이 있는데도 로그가 없다면, "
                        "'기존 승인 내역 캘린더 재동기화' 버튼으로 반영해 주세요."
                    )
            except Exception as _diag_ex:
                st.error(f"진단 오류: {_diag_ex}")

    # ── 전체 신청 내역 엑셀 내보내기 ──────────────────────────────────
    with st.expander("📊 전체 신청 내역 엑셀 다운로드", expanded=True):
        st.caption("추가근무·휴무·포상·회의·여름휴가 등 모든 신청 내역을 직원/기간/유형/상태별로 필터링해 내보냅니다.")

        # 직원 목록 (전체 매장)
        _xls_stores = _get_supabase_stores_list() or []
        _xls_all_emps: list[str] = []
        for _s in _xls_stores:
            _xls_all_emps += _erp_get_employee_names_for_store(_s.get("db_filename"))
        _xls_all_emps = sorted(set([e for e in _xls_all_emps if e]))

        _xls_r1, _xls_r2 = st.columns([2, 2])
        with _xls_r1:
            _xls_emp = st.selectbox(
                "직원 선택",
                options=["(전체 직원)"] + _xls_all_emps,
                key="xls_emp",
            )
        with _xls_r2:
            _xls_status_opts = {"전체": None, "승인": "approved", "대기": "pending", "반려": "rejected"}
            _xls_status_label = st.selectbox(
                "상태",
                options=list(_xls_status_opts.keys()),
                index=1,
                key="xls_status",
            )
            _xls_status = _xls_status_opts[_xls_status_label]
        _xls_kind_filter = st.multiselect(
            "유형 필터 (비어 있으면 전체)",
            options=list(_ERP_ADJ_KINDS),
            format_func=lambda k: _ERP_ADJ_KIND_LABEL.get(k, k),
            key="xls_kind_filter",
        )
        _xls_dcol1, _xls_dcol2 = st.columns([1, 1])
        _today_d = _today_kst()
        _xls_default_start = _today_d.replace(day=1)
        with _xls_dcol1:
            _xls_start = st.date_input("시작일", value=_xls_default_start, key="xls_start")
        with _xls_dcol2:
            _xls_end = st.date_input("종료일", value=_today_d, key="xls_end")

        if st.button("📥 엑셀 생성", key="xls_approved_btn"):
            try:
                if _xls_end < _xls_start:
                    st.error("종료일은 시작일 이후여야 합니다.")
                    st.stop()
                _sb = get_supabase_client_or_warn()
                if _sb is None:
                    st.stop()
                _xls_q = _sb.table("app_work_adjustments").select("*")\
                    .gte("target_date", _xls_start.isoformat())\
                    .lte("target_date", _xls_end.isoformat())
                if _xls_status:
                    _xls_q = _xls_q.eq("status", _xls_status)
                if _xls_kind_filter:
                    _xls_q = _xls_q.in_("kind", _xls_kind_filter)
                if _xls_emp and _xls_emp != "(전체 직원)":
                    _xls_q = _xls_q.eq("employee_name", _xls_emp)
                _xls_rows = _xls_q.order("target_date", desc=False).execute().data or []
                if not _xls_rows:
                    st.info("해당 조건의 신청 내역이 없습니다.")
                else:
                    import io
                    _STATUS_KR = {"approved": "승인", "pending": "대기", "rejected": "반려"}
                    _xls_records = []
                    for r in _xls_rows:
                        _kn = r.get("kind") or "etc"
                        _mn = int(r.get("minutes") or 0)
                        _xls_records.append({
                            "직원명": r.get("employee_name") or "",
                            "날짜": str(r.get("target_date") or "")[:10],
                            "부호": r.get("sign") or "",
                            "유형": _ERP_ADJ_KIND_LABEL.get(_kn, _kn),
                            "상태": _STATUS_KR.get(r.get("status") or "", r.get("status") or ""),
                            "시간(분)": _mn,
                            "시간(h)": round(_mn / 60, 2),
                            "시작시간": str(r.get("shift_start") or "")[:5] or "",
                            "종료시간": str(r.get("shift_end") or "")[:5] or "",
                            "근무지": r.get("work_location_name") or "",
                            "신청사유": r.get("reason") or "",
                            "승인자": r.get("approved_by") or "",
                            "승인/처리일시": str(r.get("approved_at") or "")[:19],
                        })
                    _xls_df = pd.DataFrame(_xls_records)
                    _xls_df = _xls_df.sort_values(["날짜", "직원명"], kind="stable")
                    # 합계 행 추가
                    _total_min = int(_xls_df["시간(분)"].sum())
                    _total_h = round(_total_min / 60, 2)
                    _summary = pd.DataFrame([{
                        "직원명": "─ 합계 ─", "날짜": "", "부호": "",
                        "유형": f"총 {len(_xls_df)}건", "상태": "",
                        "시간(분)": _total_min, "시간(h)": _total_h,
                        "시작시간": "", "종료시간": "", "근무지": "",
                        "신청사유": "", "승인자": "", "승인/처리일시": "",
                    }])
                    _xls_df = pd.concat([_xls_df, _summary], ignore_index=True)

                    _buf = io.BytesIO()
                    _xls_df.to_excel(_buf, index=False, sheet_name="신청내역")
                    _buf.seek(0)
                    _emp_tag = "전체직원" if _xls_emp == "(전체 직원)" else _xls_emp
                    _st_tag = _xls_status_label
                    _xls_fname = f"adjustments_{_emp_tag}_{_st_tag}_{_xls_start.isoformat()}_{_xls_end.isoformat()}.xlsx"
                    st.success(
                        f"✅ {len(_xls_records)}건 · 총 {_total_h}h ({_total_min}분) — 아래 버튼으로 다운로드"
                    )
                    st.dataframe(_xls_df, width="stretch", hide_index=True)
                    st.download_button(
                        label=f"⬇️ 엑셀 다운로드 ({_emp_tag} · {_st_tag} · {_xls_start} ~ {_xls_end})",
                        data=_buf,
                        file_name=_xls_fname,
                        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                        key="xls_approved_download",
                    )
            except Exception as _xls_ex:
                st.error(f"엑셀 생성 오류: {_xls_ex}")


def _erp_render_my_adj_form(current_db: str, role: str, me_name: str, today: date,
                            on_success=None) -> None:
    """+/- 신청 등록 폼 (팝업/탭 공용). 캘린더 팝업과 근무시간 관리 탭 양쪽에서 재사용.
    on_success: 저장 성공 후 `st.rerun()` 직전 호출되는 콜백 (팝업 플래그 정리용).
    """
    year = today.year
    month = today.month

    st.markdown("##### ➕➖ 신청 등록")

    # 근무지 목록
    _adj_stores = _get_supabase_stores_list() or []
    _adj_store_opts = [(s["store_name"], s["db_filename"]) for s in _adj_stores]
    if not any(s[1] == current_db for s in _adj_store_opts):
        _adj_store_opts.insert(0, ("현재 매장", current_db))
    _adj_store_opts.append(("기타 (외부/행사)", None))
    _adj_store_labels = [s[0] for s in _adj_store_opts]
    _adj_home_idx = next((i for i, s in enumerate(_adj_store_opts) if s[1] == current_db), 0)

    fc1, fc2 = st.columns([1, 1])
    with fc1:
        new_kind = st.selectbox(
            "유형",
            options=list(_ERP_ADJ_KINDS),
            format_func=lambda k: f"{_ERP_ADJ_KIND_LABEL[k]} ({_ERP_ADJ_KIND_DEFAULT_SIGN[k]})" if k != "etc" else "특이사항 결재 (±)",
            key="my_new_kind",
        )
    with fc2:
        if new_kind == "etc":
            new_sign = st.radio("부호", ["+", "-"], horizontal=True, key="my_new_sign")
        else:
            new_sign = _ERP_ADJ_KIND_DEFAULT_SIGN[new_kind]
            st.markdown(f"**부호: {new_sign}** (고정)")

    # 시간대 입력 여부:
    #  - overtime/meeting (+): 시작·종료 시간 입력 → 시프트 밖 시간대에 등록
    #  - early_leave (-): 실제 퇴근 시각만 입력 → shift.end 와의 차이를 자동 계산
    _needs_timeslot = new_kind in ("overtime", "meeting") and new_sign == "+"
    _is_early_leave = new_kind == "early_leave"
    _sel_cal = st.session_state.get("erp_cal_selected_day")
    _adj_date_default = _sel_cal if isinstance(_sel_cal, date) else today

    with st.form("my_new_adj_form", clear_on_submit=True):
        if _needs_timeslot:
            st.caption("📌 추가근무·회의는 실제 시간대를 입력하면 캘린더에 자동 반영됩니다.")
            ts1, ts2, ts3, ts4 = st.columns([1.2, 1, 1, 2])
            with ts1:
                new_date = st.date_input("날짜", value=_adj_date_default, key="my_new_date")
            with ts2:
                new_start = _erp_time_input_30min("시작 시간", value=dt_time(18, 0), key="my_new_start")
            with ts3:
                new_end = _erp_time_input_30min("종료 시간", value=dt_time(20, 0), key="my_new_end")
            with ts4:
                new_store_label = st.selectbox("근무지", _adj_store_labels,
                                               index=_adj_home_idx, key="my_new_store")
            # 기타(외부/행사) 선택 시 실제 외부 근무지명 텍스트 입력
            new_ext_loc = st.text_input(
                "외부 근무지명 (기타 선택 시 필수)",
                key="my_new_ext_loc",
                placeholder="예: 메종동부산, 롯데백화점 행사장, 유에코임주박람회",
                help="근무지를 '기타 (외부/행사)'로 선택한 경우에만 사용됩니다. 이 값이 캘린더에 표시됩니다.",
            )
            new_reason = st.text_input("사유", placeholder="사유를 입력해 주세요 (선택)", key="my_new_reason")
        elif _is_early_leave:
            st.caption("📌 조기퇴근은 실제 퇴근 시각만 입력하면 근무일정 종료시각과의 차이가 자동으로 계산됩니다.")
            el1, el2 = st.columns([1.2, 1])
            with el1:
                new_date = st.date_input("퇴근일", value=_adj_date_default, key="my_new_date")
            with el2:
                new_end = _erp_time_input_30min("실제 퇴근 시각", value=dt_time(15, 0), key="my_new_end")
            _peek_ss, _peek_ee = _erp_shift_bounds_for_date(current_db, me_name, new_date)
            _peek_end_min = _peek_ee.hour * 60 + _peek_ee.minute
            _peek_actual_min = new_end.hour * 60 + new_end.minute
            _peek_diff = _peek_end_min - _peek_actual_min
            if _peek_diff > 0:
                st.caption(f"➡️ 예정 종료 {_peek_ee.strftime('%H:%M')} - 실제 퇴근 {new_end.strftime('%H:%M')}"
                           f" = **-{_peek_diff//60}h {_peek_diff%60}m** (조기퇴근)")
            else:
                st.caption(f"⚠️ 예정 종료({_peek_ee.strftime('%H:%M')})보다 늦게 퇴근하면 조기퇴근 신청 대상이 아닙니다.")
            new_reason = st.text_input("사유", placeholder="예: 병원 진료, 개인 사정",
                                       key="my_new_reason")
            new_start = None  # 폼 저장 시 shift_bounds 로 재계산
        else:
            gc1, gc2, gc3 = st.columns([1, 1, 3])
            with gc1:
                new_date = st.date_input("대상 일자", value=_adj_date_default, key="my_new_date")
            with gc2:
                new_hours = st.number_input("시간(h)", min_value=0.25, max_value=744.0, step=0.5,
                                            value=1.0, key="my_new_h")
            with gc3:
                _reason_ph = "사유 (특이사항은 필수 · 예: 휴게시간 미사용, 야근 식대)" if new_kind == "etc" else "사유"
                new_reason = st.text_input("사유", placeholder=_reason_ph, key="my_new_reason")

        if st.form_submit_button("📤 신청 등록", type="primary"):
            _err_msg = None
            if new_kind == "etc" and not (new_reason or "").strip():
                _err_msg = "특이사항 결재는 사유를 반드시 입력해 주세요."
            elif _needs_timeslot:
                _s_min = new_start.hour * 60 + new_start.minute
                _e_min = new_end.hour * 60 + new_end.minute
                if _e_min <= _s_min:
                    _err_msg = "종료 시간이 시작 시간보다 늦어야 합니다."
                else:
                    _err_msg = _erp_validate_adjustment_time(
                        db_filename=current_db, employee_name=me_name,
                        target_date=new_date, start_min=_s_min, end_min=_e_min,
                    )
                # 기타(외부/행사) 선택 시 외부 근무지명 필수
                _sel_store_check = next((s for s in _adj_store_opts if s[0] == new_store_label), None)
                if _sel_store_check and _sel_store_check[1] is None and not (new_ext_loc or "").strip():
                    _err_msg = "근무지를 '기타 (외부/행사)'로 선택한 경우 외부 근무지명을 입력해 주세요."
            elif _is_early_leave:
                _shift_s, _shift_e = _erp_shift_bounds_for_date(current_db, me_name, new_date)
                _end_min_shift = _shift_e.hour * 60 + _shift_e.minute
                _actual_end_min = new_end.hour * 60 + new_end.minute
                if _actual_end_min >= _end_min_shift:
                    _err_msg = (f"실제 퇴근 시각이 예정 종료({_shift_e.strftime('%H:%M')})보다"
                                f" 이르지 않아 조기퇴근 신청 대상이 아닙니다.")
            if _err_msg:
                st.error(_err_msg)
            else:
                if _needs_timeslot:
                    _s_min = new_start.hour * 60 + new_start.minute
                    _e_min = new_end.hour * 60 + new_end.minute
                    _total_min = _e_min - _s_min
                    _sel_store = next((s for s in _adj_store_opts if s[0] == new_store_label), _adj_store_opts[_adj_home_idx])
                    _work_db = _sel_store[1]
                    # _work_db is None → 기타(외부/행사): 사용자가 입력한 외부 근무지명 사용
                    _work_loc = (new_ext_loc or "").strip() if _work_db is None else None
                elif _is_early_leave:
                    _shift_s, _shift_e = _erp_shift_bounds_for_date(current_db, me_name, new_date)
                    _actual_end = new_end
                    _total_min = ((_shift_e.hour * 60 + _shift_e.minute)
                                  - (_actual_end.hour * 60 + _actual_end.minute))
                    # 로그 컨벤션에 맞춰 shift_start = 근무 시작, shift_end = 실제 퇴근시각.
                    # 이렇게 저장하면 승인 시 auto-sync log 의 start_time/end_time 이
                    # '실제 근무한 구간' 을 표현해 다른 조퇴 log 와 동일한 방식으로 집계된다.
                    new_start = _shift_s
                    _new_end_final = _actual_end
                    _work_db = current_db
                    _work_loc = None
                else:
                    _total_min = int(round(float(new_hours) * 60))
                    _work_db = current_db
                    _work_loc = None

                payload = {
                    "db_filename": current_db,
                    "employee_name": me_name,
                    "target_date": new_date.isoformat(),
                    "kind": new_kind,
                    "sign": new_sign,
                    "minutes": _total_min,
                    "reason": (new_reason or "").strip() or None,
                    "status": "pending",
                    "created_by": me_name,
                }
                if _needs_timeslot:
                    payload["shift_start"] = new_start.strftime("%H:%M:%S")
                    payload["shift_end"] = new_end.strftime("%H:%M:%S")
                    payload["work_db_filename"] = _work_db
                    payload["work_location_name"] = _work_loc
                elif _is_early_leave:
                    payload["shift_start"] = new_start.strftime("%H:%M:%S")
                    payload["shift_end"] = _new_end_final.strftime("%H:%M:%S")
                    payload["work_db_filename"] = _work_db
                    payload["work_location_name"] = _work_loc

                _stripped_timeslot = False
                ok, e = _erp_insert_row("app_work_adjustments", payload)
                if not ok and (_needs_timeslot or _is_early_leave) and "PGRST204" in str(e):
                    # 컬럼 미존재 시 시간대 필드 제외하고 재시도
                    _p2 = {k: v for k, v in payload.items()
                           if k not in ("shift_start", "shift_end", "work_db_filename", "work_location_name")}
                    ok, e = _erp_insert_row("app_work_adjustments", _p2)
                    if ok:
                        _stripped_timeslot = True
                        st.error(
                            "❗ **시간대 컬럼(`shift_start`/`shift_end`)이 저장되지 못했습니다.** "
                            "Supabase 스키마에 컬럼이 없거나 PostgREST 스키마 캐시가 오래된 상태입니다. "
                            "슈퍼관리자에게 다음 SQL을 실행해달라고 요청하세요:\n\n"
                            "```sql\n"
                            "-- 1) 컬럼 추가 (이미 있으면 무시됨)\n"
                            "ALTER TABLE app_work_adjustments\n"
                            "    ADD COLUMN IF NOT EXISTS shift_start TIME,\n"
                            "    ADD COLUMN IF NOT EXISTS shift_end   TIME,\n"
                            "    ADD COLUMN IF NOT EXISTS work_db_filename TEXT,\n"
                            "    ADD COLUMN IF NOT EXISTS work_location_name TEXT;\n"
                            "-- 2) PostgREST 스키마 캐시 강제 리로드\n"
                            "NOTIFY pgrst, 'reload schema';\n"
                            "```"
                        )
                if ok:
                    _erp_v2_clear_caches()
                    if _stripped_timeslot:
                        flash(f"⚠️ 신청 저장됨 (단, 시간대는 저장되지 않음). SQL 실행 후 재신청해야 캘린더에 시각이 표시됩니다.", "warning")
                    elif _needs_timeslot or _is_early_leave:
                        # 저장된 근무지도 함께 표기 + DB 실제 저장값 재조회로 검증
                        _saved_dbf_to_store = {s["db_filename"]: s["store_name"]
                                               for s in (_get_supabase_stores_list(include_inactive=True) or [])}
                        # 방금 저장한 레코드를 DB 에서 재조회 (검증)
                        _verified_wdb = payload.get("work_db_filename")
                        _verified_wloc = payload.get("work_location_name")
                        _mismatch = False
                        try:
                            _vclient, _verr = get_supabase_client()
                            if _vclient and not _verr:
                                _vres = _vclient.table("app_work_adjustments")\
                                    .select("id, work_db_filename, work_location_name")\
                                    .eq("db_filename", current_db)\
                                    .eq("employee_name", me_name)\
                                    .eq("target_date", new_date.isoformat())\
                                    .order("id", desc=True).limit(1).execute()
                                _vrow = ((_vres.data or []) if hasattr(_vres, "data") else [])
                                if _vrow:
                                    _verified_wdb = _vrow[0].get("work_db_filename")
                                    _verified_wloc = _vrow[0].get("work_location_name")
                                    if _verified_wdb != payload.get("work_db_filename") \
                                       or _verified_wloc != payload.get("work_location_name"):
                                        _mismatch = True
                        except Exception:
                            pass
                        if _verified_wloc:
                            _saved_ws = _verified_wloc
                        elif _verified_wdb and _saved_dbf_to_store.get(_verified_wdb):
                            _saved_ws = _saved_dbf_to_store[_verified_wdb]
                        elif _verified_wdb:
                            _saved_ws = _verified_wdb
                        else:
                            _saved_ws = "(근무지 저장 실패)"
                        _msg = (
                            f"✅ 신청 완료 · {new_date.isoformat()} "
                            f"{payload.get('shift_start', '')[:5]}~{payload.get('shift_end', '')[:5]} · "
                            f"📍 {_saved_ws} 저장됨. 승인 후 캘린더에 표시됩니다."
                        )
                        if _mismatch:
                            _msg += (
                                f" ⚠️ (요청: {payload.get('work_db_filename') or payload.get('work_location_name') or '-'}, "
                                f"실제 저장: {_verified_wdb or _verified_wloc or '-'})"
                            )
                        flash(_msg, "warning" if _mismatch else "success")
                    else:
                        flash("신청이 등록되었습니다. 매장관리자 승인 대기 중.")
                    if on_success:
                        try:
                            on_success()
                        except Exception:
                            pass
                    st.rerun()
                else:
                    st.error(f"등록 실패: {e}")


def _erp_render_my_adj_history(current_db: str, me_name: str, today: date) -> None:
    """내 신청 내역 (연·월 선택 + 리스트 + 수정 팝업). 대시보드 하단과 근무시간 관리 탭 양쪽에서 재사용."""
    year = today.year
    month = today.month

    # ── 내 신청 내역 ──────────────────────────────────────────────
    _mh_col1, _mh_col2 = st.columns([1, 1])
    with _mh_col1:
        _mh_year = st.selectbox(
            "연도", options=list(range(year - 4, year + 2)),
            index=4, key="my_adj_hist_year",
        )
    with _mh_col2:
        _mh_month = st.selectbox(
            "월", options=list(range(1, 13)),
            index=month - 1, key="my_adj_hist_month",
            format_func=lambda m: f"{m}월",
        )
    _hist_ym = f"{int(_mh_year):04d}-{int(_mh_month):02d}"

    my_list = _erp_list_my_adjustments(current_db, me_name, _hist_ym)
    if not my_list:
        st.info(f"{_hist_ym} 에 등록한 신청이 없습니다.")
        return

    editing_id = st.session_state.get("my_adj_editing_id")

    def _render_my_adj_edit_form(adj: dict) -> None:
        """내 신청 수정 팝업 UI. 저장/취소 시 세션 키 정리 후 rerun 으로 닫힘."""
        adj_id = int(adj["id"])
        kind = adj.get("kind") or "etc"
        sign = adj.get("sign") or "+"
        minutes = int(adj.get("minutes") or 0)
        ec_kind = st.selectbox(
            "유형",
            options=list(_ERP_ADJ_KINDS),
            index=list(_ERP_ADJ_KINDS).index(kind) if kind in _ERP_ADJ_KINDS else list(_ERP_ADJ_KINDS).index("etc"),
            format_func=lambda k: f"{_ERP_ADJ_KIND_LABEL[k]} ({_ERP_ADJ_KIND_DEFAULT_SIGN[k]})" if k != "etc" else "특이사항 결재 (±)",
            key=f"my_edit_kind_{adj_id}",
        )
        if ec_kind == "etc":
            ec_sign = st.radio("부호", ["+", "-"], horizontal=True,
                               index=0 if sign == "+" else 1, key=f"my_edit_sign_{adj_id}")
        else:
            ec_sign = _ERP_ADJ_KIND_DEFAULT_SIGN[ec_kind]
            st.markdown(f"**부호: {ec_sign}** (유형 고정)")

        with st.form(f"my_edit_form_{adj_id}", clear_on_submit=False):
            e1, e2 = st.columns([1, 1])
            with e1:
                try:
                    cur_date = date.fromisoformat(str(adj.get("target_date") or "")[:10])
                except Exception:
                    cur_date = today
                ec_date = st.date_input("대상 일자", value=cur_date, key=f"my_edit_date_{adj_id}")
            with e2:
                ec_hours = st.number_input("시간(h)", min_value=0.25, max_value=744.0, step=0.5,
                                           value=round(minutes / 60, 2), key=f"my_edit_h_{adj_id}")
            ec_reason = st.text_input("사유", value=adj.get("reason") or "", key=f"my_edit_reason_{adj_id}")
            bc1, bc2 = st.columns([1, 1])
            with bc1:
                save_btn = st.form_submit_button("💾 저장", type="primary", width="stretch")
            with bc2:
                cancel_btn = st.form_submit_button("취소", width="stretch")
        if cancel_btn:
            st.session_state.pop("my_adj_editing_id", None)
            st.rerun()
        if save_btn:
            if ec_kind == "etc" and not (ec_reason or "").strip():
                st.error("특이사항 결재는 사유를 반드시 입력해 주세요.")
            else:
                patch = {
                    "target_date": ec_date.isoformat(),
                    "kind": ec_kind,
                    "sign": ec_sign,
                    "minutes": int(round(float(ec_hours) * 60)),
                    "reason": (ec_reason or "").strip() or None,
                }
                ok, e = _erp_update_row("app_work_adjustments", adj_id, patch)
                if ok:
                    _erp_v2_clear_caches()
                    st.session_state.pop("my_adj_editing_id", None)
                    flash("신청이 수정되었습니다.")
                    st.rerun()
                else:
                    st.error(f"수정 실패: {e}")

    for adj in my_list:
        adj_id = int(adj["id"])
        kind = adj.get("kind") or "etc"
        sign = adj.get("sign") or "+"
        status = adj.get("status") or "pending"
        minutes = int(adj.get("minutes") or 0)
        hours_display = f"{minutes//60}h {minutes%60}m" if minutes % 60 else f"{minutes//60}h"
        _mv_ss = str(adj.get("shift_start") or "")[:5]
        _mv_ee = str(adj.get("shift_end") or "")[:5]
        _dur_disp = f"{_mv_ss}~{_mv_ee} ({hours_display})" if (_mv_ss and _mv_ee) else hours_display
        _mv_worksite = (adj.get("work_location_name") or "").strip()
        if not _mv_worksite:
            _mv_stores_all = _get_supabase_stores_list(include_inactive=True) or []
            _mv_dbf_to_store = {s.get("db_filename"): s.get("store_name") for s in _mv_stores_all}
            _mv_worksite = (_mv_dbf_to_store.get(adj.get("work_db_filename"))
                            or _mv_dbf_to_store.get(adj.get("db_filename"))
                            or "-")
        status_label = {"pending": "🟡 대기", "approved": "🟢 승인", "rejected": "🔴 반려"}.get(status, status)

        cols = st.columns([1, 1.3, 0.4, 1.6, 1.2, 2.2, 1, 0.5, 0.5])
        with cols[0]:
            st.markdown(str(adj.get("target_date") or "")[:10])
        with cols[1]:
            st.markdown(_ERP_ADJ_KIND_LABEL.get(kind, kind))
        with cols[2]:
            st.markdown(f"**{sign}**")
        with cols[3]:
            st.markdown(_dur_disp)
        with cols[4]:
            st.markdown(f"📍 {_mv_worksite}")
        with cols[5]:
            msg = adj.get("reason") or ""
            if status == "rejected" and adj.get("reject_reason"):
                msg += f"  ▸ 반려 사유: {adj['reject_reason']}"
            st.caption(msg)
        with cols[6]:
            st.markdown(status_label)
        with cols[7]:
            if status == "pending":
                if st.button("✏️", key=f"my_adj_edit_{adj_id}", help="수정"):
                    st.session_state["my_adj_editing_id"] = adj_id
                    st.rerun()
        with cols[8]:
            if status == "pending":
                if st.button("🗑️", key=f"my_adj_del_{adj_id}", help="취소(삭제)"):
                    ok, e = _erp_delete_row("app_work_adjustments", adj_id)
                    if ok:
                        _erp_v2_clear_caches()
                        if st.session_state.get("my_adj_editing_id") == adj_id:
                            st.session_state.pop("my_adj_editing_id", None)
                        flash("신청이 취소되었습니다.")
                        st.rerun()
                    else:
                        st.error(f"취소 실패: {e}")

    # ── 팝업(모달): 수정 대상이 지정되어 있고 status=pending 인 경우만 열기 ──
    if editing_id:
        _target = next((a for a in my_list if int(a["id"]) == editing_id), None)
        if _target and (_target.get("status") or "pending") == "pending":
            from ui_dialogs import open_dialog as _open_dialog  # noqa: WPS433
            _open_dialog(
                f"✏️ 신청 수정 #{editing_id}",
                lambda adj=_target: _render_my_adj_edit_form(adj),
                width="medium",
            )
        else:
            st.session_state.pop("my_adj_editing_id", None)


def _erp_render_attendance_log_admin(current_db: str, me_name: str, today: date) -> None:
    """관리자 전용: 근태 기록 검색 / 삭제 UI."""
    with st.expander("🗑️ 근태 기록 검색 / 삭제 (관리자 전용)", expanded=False):
        st.caption("특정 직원·기간의 근태 기록을 조회하고 잘못 입력된 기록을 삭제할 수 있습니다.")
        _del_emp_opts = _erp_get_employee_names_for_store(current_db) or [me_name]
        _dc1, _dc2, _dc3 = st.columns([2, 1, 1])
        with _dc1:
            _del_emp = st.selectbox("직원", _del_emp_opts, key="erp_attdel_emp")
        with _dc2:
            _del_from = st.date_input("시작일", value=today.replace(day=1), key="erp_attdel_from")
        with _dc3:
            _del_to = st.date_input("종료일", value=today, key="erp_attdel_to")
        if st.button("🔍 조회", key="erp_attdel_search"):
            _fetched = _erp_fetch_range(
                "app_attendance_logs", "home_db_filename", current_db,
                "log_date", _del_from, _del_to
            )
            st.session_state["erp_attdel_rows"] = [
                r for r in _fetched if (r.get("employee_name") or "") == _del_emp
            ]
        _del_rows = st.session_state.get("erp_attdel_rows", [])
        if _del_rows:
            st.caption(f"{len(_del_rows)}건 조회됨")
            for _dr in _del_rows:
                _dr_id = int(_dr["id"])
                _dr_cols = st.columns([1.5, 1.2, 1.5, 2, 3, 1])
                with _dr_cols[0]:
                    st.markdown(f"**{str(_dr.get('log_date') or '')[:10]}**")
                with _dr_cols[1]:
                    st.caption(_dr.get("work_type") or "-")
                with _dr_cols[2]:
                    _ts = str(_dr.get("start_time") or "")[:5]
                    _te = str(_dr.get("end_time") or "")[:5]
                    st.caption(f"{_ts}~{_te}" if _ts else "-")
                with _dr_cols[3]:
                    st.caption(_dr.get("work_location_name") or "-")
                with _dr_cols[4]:
                    st.caption(_dr.get("note") or "-")
                with _dr_cols[5]:
                    if st.button("🗑️", key=f"erp_attdel_btn_{_dr_id}", help="이 기록 삭제"):
                        ok, e = _erp_delete_row("app_attendance_logs", _dr_id)
                        if ok:
                            st.session_state["erp_attdel_rows"] = [
                                r for r in _del_rows if int(r["id"]) != _dr_id
                            ]
                            st.toast(f"근태 기록 삭제 완료 ({str(_dr.get('log_date') or '')[:10]})", icon="✅")
                            st.rerun()
                        else:
                            st.error(f"삭제 실패: {e}")
        elif "erp_attdel_rows" in st.session_state:
            st.info("조회된 기록이 없습니다.")


def _erp_tab_my_attendance(current_db: str, role: str, me_name: str):
    """직원·관리자 공용: 근무시간 관리 탭 = 신청 등록 폼 + 내 신청 내역 + (관리자) 근태 기록 삭제."""
    st.subheader("🧑‍💼 근무시간 관리")
    today = _today_kst()
    st.divider()
    _erp_render_my_adj_form(current_db, role, me_name, today)
    st.divider()
    _erp_render_my_adj_history(current_db, me_name, today)
    if role in ("store_admin", "superadmin"):
        st.divider()
        _erp_render_attendance_log_admin(current_db, me_name, today)


# ---------- superadmin: 통합 캘린더 & 매장별 현황 ----------

def _erp_render_superadmin_view(today: date):
    """superadmin: 매장 통합 캘린더, 매장별 현황, 추가근무 승인, 월말 요약."""
    import calendar as _cal

    stores_df = get_supabase_stores_dataframe_cached()
    if stores_df is None or len(stores_df) == 0:
        st.warning("등록된 매장이 없습니다.")
        return
    store_names = stores_df["store_name"].tolist()

    sa_tabs = st.tabs(["통합 캘린더", "매장별 현황", "최소 인원 설정", "추가근무 승인", "월말 요약"])

    with sa_tabs[0]:
        # 통합 캘린더 = 전체 공개 캘린더 함수 재사용 (superadmin current_db는 비워도 무관)
        _first_db = stores_df["db_filename"].iloc[0] if len(stores_df) > 0 else ""
        _erp_tab_calendar(_first_db, "superadmin", "", today)

    with sa_tabs[2]:
        st.markdown("#### ⚙️ 매장별 최소 인원 설정")
        _sa_sr_store = st.selectbox(
            "📍 설정할 매장 선택",
            store_names,
            key="erp_sa_staffing_store",
            help="매장을 선택하면 해당 매장의 기본 근무시간 및 시간대별 최소 인원을 설정할 수 있습니다.",
        )
        _sa_sr_df = stores_df[stores_df["store_name"] == _sa_sr_store]
        if not _sa_sr_df.empty:
            _sa_sr_db = _sa_sr_df["db_filename"].iloc[0]
            _sa_me = st.session_state.get("current_user", {}).get("username", "superadmin")
            _erp_tab_staffing_rules(_sa_sr_db, _sa_me)
        else:
            st.warning("매장 정보를 찾을 수 없습니다.")

    with sa_tabs[1]:
        st.markdown("##### 📊 매장별 월별 근무 현황")
        col_y2, col_m2 = st.columns(2)
        with col_y2:
            sy2 = st.number_input("연도 ", min_value=2020, max_value=2100, value=today.year, step=1, key="erp_sa_sb_y")
        with col_m2:
            sm2 = st.number_input("월 ", min_value=1, max_value=12, value=today.month, step=1, key="erp_sa_sb_m")
        last_d2 = _cal.monthrange(int(sy2), int(sm2))[1]
        p_s2, p_e2 = date(int(sy2), int(sm2), 1), date(int(sy2), int(sm2), last_d2)

        rows = []
        for _, sr in stores_df.iterrows():
            dbf = sr["db_filename"]
            sn = sr["store_name"]
            emps = _erp_get_employee_names_for_store(dbf)
            logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", dbf, "log_date", p_s2, p_e2)
            ot = _erp_fetch_range("app_overtime_requests", "home_db_filename", dbf, "request_date", p_s2, p_e2, extra_eq={"status": "approved"})
            for emp in emps:
                emp_logs = [l for l in logs if (l.get("employee_name") or "") == emp]
                normal_days = sum(1 for l in emp_logs if (l.get("work_type") or "") in ("정상", "행사"))
                annual_u = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "연차")
                comp_u = sum(int(l.get("diff_minutes") or 0) for l in emp_logs if l.get("work_type") == "시차사용" and (l.get("status") or "approved") == "approved")
                ot_m = sum(int(o.get("extra_minutes") or 0) for o in ot if (o.get("employee_name") or "") == emp)
                comp_remain = _erp_compute_remaining_comptime(dbf, emp)
                rows.append({
                    "매장명": sn,
                    "직원명": emp,
                    "근무일수": normal_days,
                    "연차사용": annual_u,
                    "시차사용(분)": comp_u,
                    "잔여시차(분)": comp_remain,
                    "추가근무(분)": ot_m,
                })
        if rows:
            df = pd.DataFrame(rows).sort_values(["매장명", "직원명"])
            st.dataframe(df, width='stretch', hide_index=True)
            buf = io.BytesIO()
            with pd.ExcelWriter(buf, engine="openpyxl") as writer:
                df.to_excel(writer, sheet_name="매장별근무현황", index=False)
            buf.seek(0)
            st.download_button("📥 엑셀 다운로드", data=buf.getvalue(),
                               file_name=f"매장별근무현황_{sy2}-{int(sm2):02d}.xlsx",
                               mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                               key="erp_sa_sb_dl")
        else:
            st.info("표시할 데이터가 없습니다.")

    with sa_tabs[3]:
        st.markdown("##### 🧑‍💼 전 매장 매장관리자 근태 신청 승인 (superadmin 백업)")
        st.caption(
            "매장 관리자 본인이 올린 +(추가근무·회의)/-(휴무·포상·여름휴가) 신청입니다. "
            "매장 관리자는 [신청 승인] 큐에서 본인 신청도 직접 승인 가능하며, "
            "여기서는 superadmin 이 대신 승인·반려할 수 있는 백업 경로입니다. "
            "승인 시 캘린더(app_attendance_logs)에 자동 반영됩니다."
        )
        sa_adj_pending = []
        for _, sr in stores_df.iterrows():
            dbf = sr["db_filename"]
            _admin_names = set(_erp_store_admin_names(dbf))
            if not _admin_names:
                continue
            for adj in _erp_list_pending_adjustments(dbf):
                if str(adj.get("employee_name") or "").strip() in _admin_names:
                    adj["_store_name"] = sr["store_name"]
                    sa_adj_pending.append(adj)
        if not sa_adj_pending:
            st.info("대기 중인 매장관리자 신청이 없습니다.")
        else:
            st.caption(f"대기 중 {len(sa_adj_pending)}건")
            # 근무지 매핑 (한 번만 조회)
            _sa_stores_all = _get_supabase_stores_list(include_inactive=True) or []
            _sa_dbf_to_store = {s.get("db_filename"): s.get("store_name") or s.get("db_filename")
                                for s in _sa_stores_all}
            for adj in sa_adj_pending:
                adj_id = int(adj["id"])
                kind = adj.get("kind") or "etc"
                sign = adj.get("sign") or "+"
                minutes = int(adj.get("minutes") or 0)
                hours_display = f"{minutes//60}h {minutes%60}m" if minutes % 60 else f"{minutes//60}h"
                _sv_ss = str(adj.get("shift_start") or "")[:5]
                _sv_ee = str(adj.get("shift_end") or "")[:5]
                _sv_dur = f"{_sv_ss}~{_sv_ee} ({hours_display})" if (_sv_ss and _sv_ee) else hours_display
                _sv_worksite = (adj.get("work_location_name") or "").strip()
                if not _sv_worksite:
                    _sv_worksite = (_sa_dbf_to_store.get(adj.get("work_db_filename"))
                                    or _sa_dbf_to_store.get(adj.get("db_filename"))
                                    or "-")
                with st.container(border=True):
                    c = st.columns([1.6, 1.2, 0.4, 1.8, 1.2, 1.8, 1, 1])
                    with c[0]:
                        st.markdown(f"**{adj.get('_store_name') or '-'}**")
                        st.caption(adj.get("employee_name") or "-")
                    with c[1]:
                        st.markdown(f"{str(adj.get('target_date') or '')[:10]}")
                    with c[2]:
                        st.markdown(f"### {sign}")
                    with c[3]:
                        st.markdown(f"{_ERP_ADJ_KIND_LABEL.get(kind, kind)} · {_sv_dur}")
                    with c[4]:
                        st.markdown(f"📍 {_sv_worksite}")
                    with c[5]:
                        st.caption(adj.get("reason") or "")
                    with c[6]:
                        if st.button("✅ 승인", key=f"sa_adj_ok_{adj_id}", type="primary"):
                            ok, e = _erp_update_row("app_work_adjustments", adj_id, {
                                "status": "approved",
                                "approved_by": _get_current_user_display_name() or "superadmin",
                                "approved_at": datetime.now(timezone.utc).isoformat(),
                            })
                            if ok:
                                _erp_v2_clear_caches()
                                # 캘린더(app_attendance_logs) 자동 반영 — 매장관리자 승인 경로와 동일 로직
                                _log_sync_ok, _log_sync_err = _erp_upsert_log_from_adjustment(
                                    adj, sign=sign, kind=kind, minutes=minutes,
                                    fallback_home_db=current_db,
                                    created_by=_get_current_user_display_name() or "superadmin",
                                )
                                if _log_sync_ok:
                                    st.toast(
                                        f"📅 캘린더 반영: {adj.get('employee_name')} "
                                        f"{str(adj.get('target_date') or '')[:10]} "
                                        f"({sign}{_ERP_ADJ_KIND_TO_WORK_TYPE.get(kind, kind)})",
                                        icon="📅",
                                    )
                                elif _log_sync_err:
                                    st.error(f"❌ 캘린더 반영 실패: {_log_sync_err}")
                                flash(f"승인: {adj.get('employee_name')} {sign}{hours_display}")
                                st.rerun()
                            else:
                                st.error(f"승인 실패: {e}")
                    with c[7]:
                        with st.popover("❌ 반려"):
                            sa_rej_reason = st.text_input("반려 사유", key=f"sa_adj_rj_reason_{adj_id}")
                            if st.button("반려 확정", key=f"sa_adj_rj_btn_{adj_id}", type="primary"):
                                ok, e = _erp_update_row("app_work_adjustments", adj_id, {
                                    "status": "rejected",
                                    "approved_by": _get_current_user_display_name() or "superadmin",
                                    "approved_at": datetime.now(timezone.utc).isoformat(),
                                    "reject_reason": (sa_rej_reason or "").strip() or None,
                                })
                                if ok:
                                    _erp_v2_clear_caches()
                                    flash(f"반려: {adj.get('employee_name')}")
                                    st.rerun()
                                else:
                                    st.error(f"반려 실패: {e}")

        st.divider()
        st.markdown("##### ✅ 전 매장 추가근무 승인 대기 (관리자 전용)")
        all_pending = []
        for _, sr in stores_df.iterrows():
            dbf = sr["db_filename"]
            rows = _erp_fetch_table("app_overtime_requests", {"home_db_filename": dbf, "status": "pending"})
            for r in rows:
                r["_store_name"] = sr["store_name"]
                all_pending.append(r)
        if not all_pending:
            st.info("대기 중인 신청이 없습니다.")
        else:
            for req in all_pending:
                rc = st.columns([2, 3, 1, 1])
                with rc[0]:
                    st.text(f"{req.get('_store_name')} / {req.get('request_date')} {req.get('employee_name')}")
                with rc[1]:
                    st.caption(f"{str(req.get('extra_start') or '')[:5]}~{str(req.get('extra_end') or '')[:5]} "
                                f"({req.get('extra_minutes')}분) @ {req.get('work_location_name') or '-'} / 사유: {req.get('reason') or '-'}")
                with rc[2]:
                    if st.button("승인", key=f"erp_sa_ov_app_{req['id']}", type="primary"):
                        _erp_update_row("app_overtime_requests", int(req["id"]), {
                            "status": "approved",
                            "reviewed_by": _get_current_user_display_name() or "superadmin",
                            "reviewed_at": datetime.now(timezone.utc).isoformat(),
                        })
                        st.rerun()
                with rc[3]:
                    if st.button("반려", key=f"erp_sa_ov_rej_{req['id']}"):
                        _erp_update_row("app_overtime_requests", int(req["id"]), {
                            "status": "rejected",
                            "reviewed_by": _get_current_user_display_name() or "superadmin",
                            "reviewed_at": datetime.now(timezone.utc).isoformat(),
                        })
                        st.rerun()

    with sa_tabs[4]:
        st.markdown("##### 📊 전 매장 월말 급여 요약")
        col_y3, col_m3 = st.columns(2)
        with col_y3:
            sy3 = st.number_input("연도  ", min_value=2020, max_value=2100, value=today.year, step=1, key="erp_sa_sum_y")
        with col_m3:
            sm3 = st.number_input("월  ", min_value=1, max_value=12, value=today.month, step=1, key="erp_sa_sum_m")
        last_d3 = _cal.monthrange(int(sy3), int(sm3))[1]
        p_s3, p_e3 = date(int(sy3), int(sm3), 1), date(int(sy3), int(sm3), last_d3)
        all_rows = []
        for _, sr in stores_df.iterrows():
            dbf = sr["db_filename"]
            sn = sr["store_name"]
            emps = _erp_get_employee_names_for_store(dbf)
            shifts = _erp_fetch_range("app_shift_schedules", "db_filename", dbf, "shift_date", p_s3, p_e3)
            logs = _erp_fetch_range("app_attendance_logs", "home_db_filename", dbf, "log_date", p_s3, p_e3)
            ot = _erp_fetch_range("app_overtime_requests", "home_db_filename", dbf, "request_date", p_s3, p_e3, extra_eq={"status": "approved"})
            # leave_grants: 매장당 1쿼리로 일괄 조회 (N+1 쿼리 제거)
            _grants_rows = _erp_fetch_table("app_leave_grants", {"home_db_filename": dbf, "year": int(sy3)})
            _grants_by_emp = {(r.get("employee_name") or ""): r for r in _grants_rows}
            for emp in emps:
                emp_shifts = [s for s in shifts if (s.get("employee_name") or "") == emp]
                emp_logs = [l for l in logs if (l.get("employee_name") or "") == emp]
                normal_days = len(emp_shifts)
                annual_u = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "연차")
                half_u = sum(float(l.get("leave_deduction") or 0) for l in emp_logs if l.get("work_type") == "반차")
                el_m = sum(int(l.get("diff_minutes") or 0) for l in emp_logs if l.get("work_type") in ("조퇴", "지각"))
                comp_u = sum(int(l.get("diff_minutes") or 0) for l in emp_logs if l.get("work_type") == "시차사용" and (l.get("status") or "approved") == "approved")
                ot_m = sum(int(o.get("extra_minutes") or 0) for o in ot if (o.get("employee_name") or "") == emp)
                _gr = _grants_by_emp.get(emp)
                annual = float(_gr.get("annual_days") or 0) if _gr else 0
                comp_remain = _erp_compute_remaining_comptime(dbf, emp)
                all_rows.append({
                    "직원명": emp,
                    "소속매장": sn,
                    "정상근무일": normal_days,
                    "연차": annual_u,
                    "반차": half_u,
                    "조퇴/지각(분)": el_m,
                    "시차사용(분)": comp_u,
                    "추가근무(분)": ot_m,
                    "잔여연차": annual - annual_u,
                    "잔여시차(분)": comp_remain,
                })
        if all_rows:
            df = pd.DataFrame(all_rows).sort_values(["소속매장", "직원명"])
            st.dataframe(df, width='stretch', hide_index=True)
            buf = io.BytesIO()
            with pd.ExcelWriter(buf, engine="openpyxl") as writer:
                df.to_excel(writer, sheet_name="전매장월말요약", index=False)
            buf.seek(0)
            st.download_button("📥 엑셀 다운로드", data=buf.getvalue(),
                               file_name=f"전매장근태요약_{sy3}-{int(sm3):02d}.xlsx",
                               mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                               key="erp_sa_sum_dl")
        else:
            st.info("표시할 데이터가 없습니다.")


# ═══════════════════════════════════════════════════════════════════
#  인력 효율 분석 모듈  (store_admin / superadmin 전용)
