def _render_address_section_fragment():
    _address_section_impl()


def _render_special_order_form(db_filename: str, employees: pd.DataFrame):
    """위약금 / 직원구매 전용 간편 등록 폼."""
    tab_penalty, tab_emp = st.tabs(["💸 위약금 등록", "🛒 직원 구매 등록"])

    # ── 위약금 등록 ──
    with tab_penalty:
        st.caption("계약 취소 시 수령한 위약금을 별도 주문으로 등록합니다. 원가는 0원으로 처리됩니다.")
        p_col1, p_col2 = st.columns(2)
        with p_col1:
            p_cust_name = st.text_input("고객 이름 *", key="sp_penalty_name")
            p_cust_phone = st.text_input("연락처", key="sp_penalty_phone", placeholder="010-0000-0000")
        with p_col2:
            p_date = st.date_input("계약일 *", value=_today_kst(), key="sp_penalty_date")
            p_amount = st.text_input(
                "위약금 금액 *", key="sp_penalty_amount",
                on_change=lambda: st.session_state.__setitem__(
                    "sp_penalty_amount",
                    _format_number_comma(st.session_state.get("sp_penalty_amount", ""))
                )
            )
        p_method = st.selectbox("결제 수단", options=PAYMENT_METHOD_OPTIONS, key="sp_penalty_method")
        if p_method in _CARD_WITH_COMPANY:
            p_card = st.selectbox("카드사", options=CARD_COMPANY_OPTIONS, key="sp_penalty_card")
        elif p_method == "메인페이":
            p_card = st.text_input("메인페이 승인번호 4자리", key="sp_penalty_card", max_chars=4)
        elif p_method == "지역화폐":
            p_card = st.text_input("지역화폐 승인번호", key="sp_penalty_card")
        else:
            p_card = None
        p_reason = st.text_area("위약금 사유 *", key="sp_penalty_reason", placeholder="예) 계약 취소 위약금, 고객 변심으로 인한 계약 철회")
        p_emp_names = []
        if not employees.empty:
            p_emp_sel = st.multiselect("담당 직원", options=employees["name"].tolist(), key="sp_penalty_emp")
            p_emp_names = p_emp_sel
        if st.button("💸 위약금 등록", key="sp_penalty_btn", type="primary"):
            p_amt_int = _parse_comma_to_int(st.session_state.get("sp_penalty_amount", "0"))
            if not p_cust_name.strip():
                st.error("고객 이름을 입력해 주세요.")
            elif p_amt_int <= 0:
                st.error("위약금 금액을 입력해 주세요.")
            elif not p_reason.strip():
                st.error("위약금 사유를 입력해 주세요.")
            else:
                try:
                    emp_str = ",".join(p_emp_names) if p_emp_names else None
                    fee = _payment_fee_amount(p_method, p_amt_int)
                    p_date_str = p_date.isoformat()
                    if _supabase_orders_payments_available():
                        cid, cid_err = _supabase_insert_customer(db_filename, p_cust_name.strip(), p_cust_phone.strip() or "", None, None)
                        if cid is None:
                            st.error(f"고객 등록 실패: {cid_err}")
                        else:
                            oid = _insert_order_supabase(db_filename, {
                                "customer_id": cid,
                                "employee_names": emp_str,
                                "order_date": p_date_str,
                                "delivery_date": p_date_str,
                                "category": "위약금",
                                "cost_price": 0,
                                "total_amount": p_amt_int,
                                "balance_status": "미납",
                                "visit_reason": p_reason.strip(),
                                "purchase_reason": "위약금",
                            })
                            if oid:
                                _insert_payment_supabase(db_filename, {
                                    "order_id": oid,
                                    "payment_date": p_date_str,
                                    "amount": p_amt_int,
                                    "payment_method": p_method or None,
                                    "card_company": p_card,
                                    "fee_amount": fee,
                                    "created_by": _current_username(),
                                })
                                _recalc_order_actual_margin_supabase(db_filename, oid)
                                clear_data_cache()
                                flash(f"위약금 {p_amt_int:,}원 등록이 완료되었습니다. (주문 #{oid})")
                                for k in ["sp_penalty_name", "sp_penalty_phone", "sp_penalty_amount", "sp_penalty_reason", "sp_penalty_card"]:
                                    st.session_state.pop(k, None)
                                st.rerun()
                            else:
                                st.error("주문 등록에 실패했습니다.")
                    else:
                        conn = get_tenant_conn(db_filename)
                        try:
                            conn.execute(
                                "INSERT INTO Customers (name, phone1) VALUES (?, ?)",
                                (p_cust_name.strip(), p_cust_phone.strip() or ""),
                            )
                            cid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                            conn.execute(
                                "INSERT INTO Orders (customer_id, employee_names, order_date, delivery_date, category, cost_price, total_amount, visit_reason, purchase_reason, balance_status) VALUES (?,?,?,?,?,0,?,?,?,?)",
                                (cid, emp_str, p_date_str, p_date_str, "위약금", p_amt_int, p_reason.strip(), "위약금", "미납"),
                            )
                            oid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                            conn.execute(
                                "INSERT INTO Payments (order_id, payment_date, amount, payment_method, card_company, fee_amount, created_by, created_at) VALUES (?,?,?,?,?,?,?,datetime('now', '+9 hours'))",
                                (oid, p_date_str, p_amt_int, p_method or None, p_card, fee, _current_username()),
                            )
                            _recalc_order_actual_margin(conn, oid, db_filename)
                            conn.commit()
                            clear_data_cache()
                            flash(f"위약금 {p_amt_int:,}원 등록이 완료되었습니다.")
                            for k in ["sp_penalty_name", "sp_penalty_phone", "sp_penalty_amount", "sp_penalty_reason", "sp_penalty_card"]:
                                st.session_state.pop(k, None)
                            st.rerun()
                        finally:
                            conn.close()
                except Exception as e:
                    st.error(f"등록 오류: {e}")

    # ── 직원 구매 등록 ──
    with tab_emp:
        st.caption("직원 구매는 매출로 계상되지 않습니다. 판매가 = 원가로 등록되어 마진 0원으로 기록됩니다.")
        e_col1, e_col2 = st.columns(2)
        with e_col1:
            e_emp_sel = None
            if not employees.empty:
                e_emp_sel = st.selectbox("구매 직원 *", options=employees["name"].tolist(), key="sp_emp_buyer")
            e_date = st.date_input("구매일 *", value=_today_kst(), key="sp_emp_date")
        with e_col2:
            e_category = st.selectbox("품목", options=["옷장", "식탁", "자녀방", "침대", "SSDS침대", "서재_학생", "소파", "소품", "전시품", "기타"], key="sp_emp_category")
            e_cost = st.text_input(
                "원가(구매가) *", key="sp_emp_cost",
                on_change=lambda: st.session_state.__setitem__(
                    "sp_emp_cost",
                    _format_number_comma(st.session_state.get("sp_emp_cost", ""))
                )
            )
        e_method = st.selectbox("결제 수단", options=PAYMENT_METHOD_OPTIONS, key="sp_emp_method")
        if e_method in _CARD_WITH_COMPANY:
            e_card = st.selectbox("카드사", options=CARD_COMPANY_OPTIONS, key="sp_emp_card")
        elif e_method == "메인페이":
            e_card = st.text_input("메인페이 승인번호 4자리", key="sp_emp_card", max_chars=4)
        elif e_method == "지역화폐":
            e_card = st.text_input("지역화폐 승인번호", key="sp_emp_card")
        else:
            e_card = None
        if st.button("🛒 직원 구매 등록", key="sp_emp_btn", type="primary"):
            e_cost_int = _parse_comma_to_int(st.session_state.get("sp_emp_cost", "0"))
            if not e_emp_sel:
                st.error("구매 직원을 선택해 주세요.")
            elif e_cost_int <= 0:
                st.error("원가(구매가)를 입력해 주세요.")
            else:
                try:
                    e_date_str = e_date.isoformat()
                    fee = _payment_fee_amount(e_method, e_cost_int)
                    if _supabase_orders_payments_available():
                        cid, cid_err = _supabase_insert_customer(db_filename, f"[직원]{e_emp_sel}", "", None, None)
                        if cid is None:
                            st.error(f"등록 실패: {cid_err}")
                        else:
                            oid = _insert_order_supabase(db_filename, {
                                "customer_id": cid,
                                "employee_names": e_emp_sel,
                                "order_date": e_date_str,
                                "delivery_date": e_date_str,
                                "category": f"직원구매_{e_category}",
                                "cost_price": e_cost_int,
                                "total_amount": e_cost_int,
                                "balance_status": "미납",
                                "visit_reason": "직원구매",
                                "purchase_reason": "직원구매",
                            })
                            if oid:
                                _insert_payment_supabase(db_filename, {
                                    "order_id": oid,
                                    "payment_date": e_date_str,
                                    "amount": e_cost_int,
                                    "payment_method": e_method or None,
                                    "card_company": e_card,
                                    "fee_amount": fee,
                                    "created_by": _current_username(),
                                })
                                _recalc_order_actual_margin_supabase(db_filename, oid)
                                clear_data_cache()
                                flash(f"직원 구매 {e_cost_int:,}원 등록이 완료되었습니다. (주문 #{oid})")
                                for k in ["sp_emp_cost", "sp_emp_card"]:
                                    st.session_state.pop(k, None)
                                st.rerun()
                            else:
                                st.error("주문 등록에 실패했습니다.")
                    else:
                        conn = get_tenant_conn(db_filename)
                        try:
                            conn.execute(
                                "INSERT INTO Customers (name, phone1) VALUES (?, ?)",
                                (f"[직원]{e_emp_sel}", ""),
                            )
                            cid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                            conn.execute(
                                "INSERT INTO Orders (customer_id, employee_names, order_date, delivery_date, category, cost_price, total_amount, visit_reason, purchase_reason, balance_status) VALUES (?,?,?,?,?,?,?,?,?,?)",
                                (cid, e_emp_sel, e_date_str, e_date_str, f"직원구매_{e_category}", e_cost_int, e_cost_int, "직원구매", "직원구매", "미납"),
                            )
                            oid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                            conn.execute(
                                "INSERT INTO Payments (order_id, payment_date, amount, payment_method, card_company, fee_amount, created_by, created_at) VALUES (?,?,?,?,?,?,?,datetime('now', '+9 hours'))",
                                (oid, e_date_str, e_cost_int, e_method or None, e_card, fee, _current_username()),
                            )
                            _recalc_order_actual_margin(conn, oid, db_filename)
                            conn.commit()
                            clear_data_cache()
                            flash(f"직원 구매 {e_cost_int:,}원 등록이 완료되었습니다.")
                            for k in ["sp_emp_cost", "sp_emp_card"]:
                                st.session_state.pop(k, None)
                            st.rerun()
                        finally:
                            conn.close()
                except Exception as e:
                    st.error(f"등록 오류: {e}")


@st.fragment
def render_new_sales():
    db_filename = st.session_state.get("current_db")
    if not db_filename:
        st.warning("매장에 로그인한 후 이용하세요.")
        return
    # 신규 주문 INSERT 직후에만 설정된 성과 축하 컨텍스트 표시 (UPDATE/수정 시에는 절대 설정되지 않음)
    if "_gamification_ctx" in st.session_state:
        _render_gamification_feedback(st.session_state["_gamification_ctx"])
        del st.session_state["_gamification_ctx"]
    # 매출 등록 완료 배너 (st.rerun() 후에도 유지되도록 세션 상태 활용)
    if "_sales_complete_banner" in st.session_state:
        _b = st.session_state.pop("_sales_complete_banner")
        st.success(f"✅ 입력 완료! {_b['cust_name']}님 {_b['amount']:,}원 매출 등록이 완료되었습니다.")
    # sales 테이블 INSERT 실패 경고 배너 (주문·결제는 저장되었으나 매출 집계·KPI 반영 실패)
    if "_sales_insert_error_banner" in st.session_state:
        _se = st.session_state.pop("_sales_insert_error_banner")
        _oid = _se.get("order_id")
        _amt = _se.get("amount") or 0
        _td = _se.get("transaction_date", "")
        _reason = _se.get("reason", "원인 미상")
        st.error(
            f"⚠️ **매출 집계(sales) 기록 실패** — 주문 #{_oid} ({_td}, {_amt:,.0f}원)\n\n"
            f"- 오류: `{_reason}`\n"
            f"- 주문·결제는 정상 저장되었으나 **sales 테이블 INSERT가 실패**하여 "
            f"월 매출·KPI 대시보드에 반영되지 않습니다.\n"
            f"- 관리자에게 해당 order_id({_oid})로 sales 레코드 수동 복구를 요청하세요."
        )
    st.header("새로운 매출 등록")
    # 직원 목록: Supabase app_users/app_user_stores 우선 사용, 없으면 레거시 SQLite Employees 사용
    employees = pd.DataFrame(columns=["id", "name"])
    if _supabase_app_tables_available():
        store_id = _get_supabase_store_by_db_filename(db_filename)
        users = _get_supabase_users_list()
        rows = []
        for u in users:
            uid = u.get("id")
            role = u.get("role")
            if role not in ("store_admin", "user"):
                continue
            store_ids = _get_supabase_user_store_ids(uid)
            if store_id and store_id not in store_ids and u.get("store_id") != store_id:
                continue
            name = (u.get("name") or u.get("username") or "").strip()
            if not name:
                continue
            rows.append({"id": uid, "name": name})
        if rows:
            employees = pd.DataFrame(rows)
    else:
        conn = get_tenant_conn(db_filename)
        if conn:
            try:
                employees = pd.read_sql("SELECT id, name FROM Employees WHERE is_active = 1", conn)
            except Exception:
                employees = pd.DataFrame(columns=["id", "name"])
                st.warning("직원 목록을 불러오지 못했습니다. ⚙️ 관리자 설정 → 1. 직원 마스터에서 직원을 먼저 등록해 주세요.")
            finally:
                conn.close()
    # ── 특수 등록 (위약금 / 직원구매) ──
    with st.expander("⚡ 특수 등록 (위약금 / 직원 구매)", expanded=False):
        _render_special_order_form(db_filename, employees)

    with st.expander("💳 기존 주문 잔금 빠른 등록", expanded=False):
        st.caption("기존 주문의 잔금을 이 화면에서 바로 등록합니다. 결제 날짜 기본값은 계약일이며, 필요 시 변경할 수 있습니다.")
        quick_q = st.text_input(
            "고객 검색 (이름/전화번호)",
            key="new_sales_quick_balance_query",
            placeholder="예: 홍길동 또는 01012345678",
        )
        quick_customers = pd.DataFrame()
        if quick_q and quick_q.strip():
            try:
                if _supabase_orders_payments_available():
                    sc_q, _ = get_supabase_client()
                    store_name_q = _get_current_store_name_for_customers(db_filename)
                    if sc_q and store_name_q:
                        q_safe = re.sub(r"[*,]", "", quick_q.strip())
                        or_filter = f"name.ilike.*{q_safe}*,phone1.ilike.*{q_safe}*,phone2.ilike.*{q_safe}*"
                        r_q = sc_q.table("app_customers").select("id, name, phone1, phone2").eq("store_name", store_name_q).or_(or_filter).order("id", desc=True).limit(50).execute()
                        quick_customers = pd.DataFrame(r_q.data) if r_q.data else pd.DataFrame()
                else:
                    conn_q = get_tenant_conn(db_filename)
                    if conn_q:
                        try:
                            pattern = f"%{quick_q.strip()}%"
                            quick_customers = pd.read_sql(
                                "SELECT id, name, phone1, phone2 FROM Customers WHERE name LIKE ? OR phone1 LIKE ? OR phone2 LIKE ? ORDER BY id DESC LIMIT 50",
                                conn_q,
                                params=(pattern, pattern, pattern),
                            )
                        finally:
                            conn_q.close()
            except Exception:
                quick_customers = pd.DataFrame()

        if quick_q and quick_q.strip() and quick_customers.empty:
            st.info("검색된 고객이 없습니다.")

        if not quick_customers.empty:
            quick_customers = quick_customers.drop_duplicates(subset=["name", "phone1"], keep="first").reset_index(drop=True)
            quick_cids = quick_customers["id"].tolist()

            def _fmt_quick_cust(cid):
                row = quick_customers[quick_customers["id"] == cid]
                if row.empty:
                    return str(cid)
                r0 = row.iloc[0]
                return f"{r0.get('name') or '-'} ({r0.get('phone1') or '-'})"

            quick_cid = st.selectbox("고객 선택", quick_cids, format_func=_fmt_quick_cust, key="new_sales_quick_balance_customer")
            if quick_cid:
                qrow = quick_customers[quick_customers["id"] == quick_cid].iloc[0]
                q_name = str(qrow.get("name") or "")
                q_phone = str(qrow.get("phone1") or "")
                all_cids = quick_customers[
                    (quick_customers["name"].fillna("") == q_name) &
                    (quick_customers["phone1"].fillna("") == q_phone)
                ]["id"].tolist() or [quick_cid]

                if _supabase_orders_payments_available():
                    all_orders_q = _load_orders_supabase(db_filename, "id, customer_id, order_date, total_amount, import_source", limit=None)
                    q_orders = all_orders_q[all_orders_q["customer_id"].isin(all_cids)].copy() if (not all_orders_q.empty and "customer_id" in all_orders_q.columns) else pd.DataFrame()
                    q_payments = _load_payments_supabase(db_filename)
                else:
                    conn_qo = get_tenant_conn(db_filename)
                    if conn_qo:
                        try:
                            placeholders = ",".join("?" * len(all_cids))
                            q_orders = pd.read_sql(
                                f"SELECT id, customer_id, order_date, total_amount FROM Orders WHERE customer_id IN ({placeholders})",
                                conn_qo,
                                params=tuple(all_cids),
                            )
                            q_payments = pd.read_sql("SELECT order_id, amount FROM Payments", conn_qo)
                        finally:
                            conn_qo.close()
                    else:
                        q_orders = pd.DataFrame()
                        q_payments = pd.DataFrame()

                if not q_orders.empty and "id" in q_orders.columns:
                    pay_sum_q = q_payments.groupby("order_id")["amount"].sum() if (not q_payments.empty and "order_id" in q_payments.columns and "amount" in q_payments.columns) else pd.Series(dtype=float)
                    q_orders["paid"] = q_orders["id"].map(pay_sum_q).fillna(0)
                    q_orders["balance"] = q_orders["total_amount"].fillna(0) - q_orders["paid"]
                    q_orders = _zero_pre_april_2026_import_balance(q_orders, "balance")
                    q_orders = q_orders[q_orders["balance"] > 0].copy()
                    q_orders["order_date"] = pd.to_datetime(q_orders["order_date"], errors="coerce")
                    q_orders = q_orders.sort_values(["order_date", "id"], ascending=[False, False]).reset_index(drop=True)

                    if q_orders.empty:
                        st.info("선택한 고객의 미수 주문이 없습니다.")
                    else:
                        q_oids = q_orders["id"].tolist()

                        def _fmt_quick_order(oid):
                            orow = q_orders[q_orders["id"] == oid].iloc[0]
                            od = orow.get("order_date")
                            od_str = od.strftime("%Y-%m-%d") if hasattr(od, "strftime") else str(od or "-")[:10]
                            bal = float(orow.get("balance") or 0)
                            return f"주문 #{oid} | 계약일 {od_str} | 잔금 {bal:,.0f}원"

                        quick_oid = st.selectbox("잔금 등록 주문 선택", q_oids, format_func=_fmt_quick_order, key="new_sales_quick_balance_order")
                        if quick_oid:
                            sel = q_orders[q_orders["id"] == quick_oid].iloc[0]
                            sel_balance = float(sel.get("balance") or 0)
                            sel_order_date = sel.get("order_date")
                            default_pay_date = sel_order_date.date() if hasattr(sel_order_date, "date") else _today_kst()
                            _customer_balance_payment_ui(
                                db_filename,
                                int(quick_oid),
                                sel_balance,
                                key_prefix=f"quick_bal_{int(quick_oid)}",
                                default_payment_date=default_pay_date,
                            )
                else:
                    st.info("선택한 고객의 주문 데이터가 없습니다.")

    st.divider()

    # 고객 선택: 기본 모드 = 신규 고객 등록, [기존 고객 검색] 버튼으로 검색 패널 열기
    if "_cust_search_panel_open" not in st.session_state:
        st.session_state["_cust_search_panel_open"] = False

    _panel_open = st.session_state["_cust_search_panel_open"]
    _col_new, _col_search = st.columns(2)
    with _col_new:
        if st.button(
            "✏️ 신규 고객으로 등록",
            key="btn_new_cust_mode",
            type="secondary" if _panel_open else "primary",
            width='stretch',
        ):
            st.session_state["_cust_search_panel_open"] = False
            for _k in ["_new_sales_selected_customer", "_cust_search_results",
                       "new_sales_cust_name", "new_sales_cust_search", "new_sales_cust_select"]:
                st.session_state.pop(_k, None)
            st.rerun()
    with _col_search:
        if st.button(
            "🔍 기존 고객 검색",
            key="btn_open_cust_search",
            type="primary" if _panel_open else "secondary",
            width='stretch',
        ):
            st.session_state["_cust_search_panel_open"] = True
            st.rerun()

    if st.session_state.get("_cust_search_panel_open"):
        _customer_search_fragment(db_filename)

    selected_customer_row = st.session_state.get("_new_sales_selected_customer")
    is_new_customer = selected_customer_row is None

    if selected_customer_row and st.session_state.get("_cust_search_panel_open"):
        _sel_name = selected_customer_row.get("name") or ""
        _sel_phone = selected_customer_row.get("phone1") or "-"
        st.success(f"✅ 선택된 고객: **{_sel_name}** ({_sel_phone})")
        if st.button("❌ 선택 해제 (신규 고객으로 전환)", key="btn_clear_cust_sel"):
            for _k in ["_new_sales_selected_customer", "_cust_search_results",
                       "new_sales_cust_name", "new_sales_cust_search", "new_sales_cust_select"]:
                st.session_state.pop(_k, None)
            st.session_state["_cust_search_panel_open"] = False
            st.rerun()

    default_name = (selected_customer_row.get("name") or "") if selected_customer_row else ""
    default_phone1 = (selected_customer_row.get("phone1") or "") if selected_customer_row else ""
    default_phone2 = (selected_customer_row.get("phone2") or "") if selected_customer_row else ""
    default_addr = (selected_customer_row.get("address") or st.session_state.get("address_manual", "")) if selected_customer_row else st.session_state.get("address_manual", "")
    cust_name_key = "new_sales_cust_name"
    if cust_name_key not in st.session_state:
        st.session_state[cust_name_key] = default_name
    if selected_customer_row is not None and default_name:
        st.session_state[cust_name_key] = default_name
    cust_name = st.text_input("고객명 *", key=cust_name_key)
    # 전화번호: 세션 초기화 후 위젯에서 on_change로 010-1234-5678 형식 하이픈 포맷
    if "phone1" not in st.session_state:
        st.session_state["phone1"] = _format_phone_hyphen(default_phone1) if default_phone1 else ""
    if "phone2" not in st.session_state:
        st.session_state["phone2"] = _format_phone_hyphen(default_phone2) if default_phone2 else ""
    if not is_new_customer:
        st.session_state["phone1"] = _format_phone_hyphen(default_phone1) if default_phone1 else ""
        st.session_state["phone2"] = _format_phone_hyphen(default_phone2) if default_phone2 else ""

    def _on_phone1():
        st.session_state["phone1"] = _format_phone_hyphen(st.session_state.get("phone1", ""))

    def _on_phone2():
        st.session_state["phone2"] = _format_phone_hyphen(st.session_state.get("phone2", ""))

    st.text_input("Phone 1 *", key="phone1", on_change=_on_phone1)
    st.text_input("Phone 2", key="phone2", on_change=_on_phone2)
    phone1 = st.session_state.get("phone1", "")
    phone2 = st.session_state.get("phone2", "")

    # ----- 주소: [주소 검색] 버튼 → 다이얼로그 팝업, @st.fragment로 입력 시 부분만 렌더링 -----
    if "address_manual" not in st.session_state:
        st.session_state["address_manual"] = default_addr
    if "address_detail" not in st.session_state:
        st.session_state["address_detail"] = ""
    _render_address_section_fragment()
    address_base = st.session_state.get("address_manual", "")
    address_detail = st.session_state.get("address_detail", "")
    address_full = " ".join(filter(None, [address_base.strip(), address_detail.strip()])) or None

    # 담당 직원: 직원 명부(현재 매장 배정 사용자) 우선 사용, 없으면 매장별 직원 마스터(Employees) 사용
    store_emp_names = get_store_assigned_employee_names(db_filename)
    if store_emp_names:
        emp_names = store_emp_names
    else:
        emp_names = employees["name"].tolist() if not employees.empty and "name" in employees.columns else []
    if not emp_names:
        st.warning("이 매장에 배정된 직원이 없습니다. **직원 계정 관리**에서 해당 매장을 배정해 주세요. (또는 ⚙️ 관리자 설정 → 1. 직원 마스터에서 등록)")
    # key에 폼 리셋 카운터를 붙여 등록 완료 시 새 위젯으로 초기화
    _form_reset = st.session_state.get("_new_sales_form_reset", 0)
    selected_employees = st.multiselect(
        "담당 직원 (복수 선택, 1/n 실적 분배 대상) *",
        options=emp_names,
        default=[],
        key=f"new_sales_employee_multiselect_{_form_reset}",
    )
    employee_names_str = ",".join(selected_employees) if selected_employees else ""
    if "order_date" not in st.session_state:
        st.session_state["order_date"] = _today_kst()
    order_date = st.date_input("계약일 *", key="order_date")
    if "delivery_date" not in st.session_state:
        st.session_state["delivery_date"] = _today_kst()
    delivery_date = st.date_input("배송일 *", key="delivery_date")
    CATEGORY_OPTIONS = ["옷장", "식탁", "자녀방", "침대", "SSDS침대", "서재_학생", "소파", "소품", "전시품"]
    selected_categories = st.multiselect("품목/카테고리 (복수 선택) *", options=CATEGORY_OPTIONS, key=f"category_multiselect_{_form_reset}")
    category = ",".join(selected_categories) if selected_categories else None
    has_display = selected_categories and "전시품" in selected_categories
    # 금액: text_input + on_change 콤마 포맷 (포커스 아웃 시에만 rerun → number_input 대비 가볍거나 동일)
    if "cost_price" not in st.session_state:
        st.session_state["cost_price"] = "0"
    if "total_amount" not in st.session_state:
        st.session_state["total_amount"] = "0"

    st.text_input(
        "일반제품 판매가(Selling Price) *", key="total_amount",
        on_change=lambda: st.session_state.__setitem__(
            "total_amount", _format_number_comma(st.session_state.get("total_amount", ""))
        ),
    )
    st.text_input(
        "일반제품 원가(Cost) *", key="cost_price",
        on_change=lambda: st.session_state.__setitem__(
            "cost_price", _format_number_comma(st.session_state.get("cost_price", ""))
        ),
    )
    if has_display:
        if "display_sales_amount" not in st.session_state:
            st.session_state["display_sales_amount"] = "0"
        if "display_cost_amount" not in st.session_state:
            st.session_state["display_cost_amount"] = "0"
        st.text_input(
            "전시품 판매가 *", key="display_sales_amount",
            on_change=lambda: st.session_state.__setitem__(
                "display_sales_amount", _format_number_comma(st.session_state.get("display_sales_amount", ""))
            ),
        )
        st.text_input(
            "전시품 원가 *", key="display_cost_amount",
            on_change=lambda: st.session_state.__setitem__(
                "display_cost_amount", _format_number_comma(st.session_state.get("display_cost_amount", ""))
            ),
        )
    # 실시간 합산: 최종 총 판매금액, 최종 총 원가, 기본 총 마진
    general_sales = _parse_comma_to_int(st.session_state.get("total_amount", "0"))
    general_cost = _parse_comma_to_int(st.session_state.get("cost_price", "0"))
    display_sales_val = _parse_comma_to_int(st.session_state.get("display_sales_amount", "0")) if has_display else 0
    display_cost_val = _parse_comma_to_int(st.session_state.get("display_cost_amount", "0")) if has_display else 0
    final_sales = general_sales + display_sales_val
    final_cost = general_cost + display_cost_val
    basic_margin = final_sales - final_cost
    basic_margin_rate = (basic_margin / final_sales * 100) if final_sales else 0.0
    st.subheader("합산 금액 (실시간)")
    c1, c2, c3, c4 = st.columns(4)
    with c1:
        st.metric("최종 총 판매금액", f"{final_sales:,}원", help="일반제품 판매가 + 전시품 판매가")
    with c2:
        st.metric("최종 총 원가", f"{final_cost:,}원", help="일반제품 원가 + 전시품 원가")
    with c3:
        st.metric("기본 총 마진", f"{basic_margin:,}원", help="최종 총 판매금액 - 최종 총 원가")
    with c4:
        _rate_icon = "🟢" if basic_margin_rate >= 20 else ("🟡" if basic_margin_rate >= 15 else "🔴")
        st.metric(
            f"1차 마진율 {_rate_icon}",
            f"{basic_margin_rate:.1f}%",
            help="(판매가 − 원가) / 판매가 × 100 (카드 수수료 미반영 기본 마진율)",
        )

    VISIT_REASON_OPTIONS = [
        "온라인검색",
        "광고 및 홍보",
        "매장외관(지나가다)",
        "지인/업체소개",
        "기존고객(재구매 AS)",
        "박람회 및 제휴업체",
        "기타(메모필수)",
    ]
    PURCHASE_REASON_OPTIONS = [
        "신혼/혼수",
        "신규 입주",
        "일반 이사",
        "단순 교체/추가",
        "기타(사무용 등)",
    ]
    visit_reason_sel = st.radio(
        "방문 이유 * (필수, 1개 선택)",
        options=VISIT_REASON_OPTIONS,
        key="visit_reason_radio",
        horizontal=True,
        index=None,
    )
    visit_reason_memo = ""
    if visit_reason_sel == "기타(메모필수)":
        visit_reason_memo = st.text_input(
            "기타 방문 이유 메모 (필수) *",
            key="visit_reason_memo",
            placeholder="예: 유튜브 영상 시청 후 방문",
        )
        visit_reason = f"기타: {visit_reason_memo.strip()}" if visit_reason_memo.strip() else ""
    else:
        st.session_state.pop("visit_reason_memo", None)
        visit_reason = visit_reason_sel or ""
    purchase_reason_sel = st.radio(
        "구매 이유 * (필수, 1개 선택)",
        options=PURCHASE_REASON_OPTIONS,
        key="purchase_reason_radio",
        horizontal=True,
        index=None,
    )
    purchase_reason = purchase_reason_sel or ""

    # ----- 다중(복합) 결제 수단: 기본 4개, 최대 20개 (플러스 버튼으로 추가) -----
    MAX_PAYMENT_SLOTS = 20
    DEFAULT_PAYMENT_SLOTS = 4
    st.subheader("결제 내역 (복수 결제 가능)")
    # 현재 사용 중인 슬롯 개수 (세션에 저장)
    if "payment_slot_count" not in st.session_state:
        st.session_state["payment_slot_count"] = DEFAULT_PAYMENT_SLOTS
    slot_count = st.session_state["payment_slot_count"]
    # 내부적으로는 최대 슬롯 수만큼 키를 준비해 둠
    if "payment_rows" not in st.session_state:
        st.session_state["payment_rows"] = [
            {"method": "", "card_company": "", "amount": "0"} for _ in range(MAX_PAYMENT_SLOTS)
        ]
    # 슬롯 추가 버튼
    add_col1, add_col2 = st.columns([3, 1])
    with add_col2:
        disabled_add = slot_count >= MAX_PAYMENT_SLOTS
        if st.button("➕ 결제 수단 추가", disabled=disabled_add, key="add_payment_slot"):
            # 버튼 클릭 시 상태만 변경하면, Streamlit이 자체적으로 전체 앱을 1회 rerun합니다.
            if slot_count < MAX_PAYMENT_SLOTS:
                st.session_state["payment_slot_count"] = slot_count + 1
    total_payment_int = 0
    for i in range(slot_count):
        row_key = f"pay_method_{i}"
        card_key = f"pay_card_{i}"
        amt_key = f"pay_amt_{i}"
        if amt_key not in st.session_state:
            st.session_state[amt_key] = "0"
        c1, c2, c3 = st.columns([2, 2, 2])
        with c1:
            method = st.selectbox(f"결제 수단 #{i+1} *", options=PAYMENT_METHOD_OPTIONS, key=row_key, index=0 if i == 0 else 0)
        with c2:
            if method in _CARD_WITH_COMPANY:
                card_company = st.selectbox(f"카드사 #{i+1} *", options=CARD_COMPANY_OPTIONS, key=card_key)
            elif method == "메인페이":
                st.text_input(f"메인페이 승인번호 4자리 #{i+1} *", key=card_key, max_chars=4)
                card_company = st.session_state.get(card_key)
            elif method == "지역화폐":
                st.text_input(f"지역화폐 승인번호 6자리 #{i+1} *", key=card_key, max_chars=6)
                card_company = st.session_state.get(card_key)
            else:
                card_company = None
        with c3:
            _ak = amt_key
            st.text_input(f"금액 #{i+1} *", key=_ak, on_change=lambda k=_ak: st.session_state.__setitem__(k, _format_number_comma(st.session_state.get(k, ""))))
        total_payment_int += _parse_comma_to_int(st.session_state.get(amt_key, "0"))
        # 온누리(전자) 식별자: 검증파일 구매자전화번호 뒤 4자리. 온누리지류는 불필요.
        is_onnuri = method and ("온누리" in str(method)) and ("지류" not in str(method))
        last4_key = f"pay_onnuri_last4_{i}"
        receipt_key = f"pay_onnuri_receipt_{i}"
        if is_onnuri:
            st.text_input(
                f"온누리 전화번호 뒤 4자리 #{i+1} *",
                key=last4_key,
                max_chars=4,
                help="검증파일의 구매자전화번호(예: 010****2414) 뒤 4자리와 동일하게 입력하세요.",
            )
            _ns_last4 = re.sub(r"\D", "", str(st.session_state.get(last4_key, "") or ""))
            _ns_amt = _parse_comma_to_int(st.session_state.get(amt_key, "0"))
            _ns_date = order_date.isoformat() if hasattr(order_date, "isoformat") else str(order_date)
            _ns_form_hit = _onnuri_same_form_collides(
                this_index=i, last4=_ns_last4, amount=_ns_amt, slot_count=slot_count,
                last4_key_fn=lambda j: f"pay_onnuri_last4_{j}",
                amt_key_fn=lambda j: f"pay_amt_{j}",
                method_key_fn=lambda j: f"pay_method_{j}",
            )
            _onnuri_time_input(
                f"pay_onnuri_time_{i}",
                visible=_onnuri_should_ask_time(
                    db_filename, _ns_last4, _ns_amt, _ns_date, form_collides=_ns_form_hit,
                ),
                label=f"온누리 거래시간 #{i+1} *",
            )
            _file_input_with_paste(
                "온누리상품권 영수증 사진(선택)",
                type=["png", "jpg", "jpeg", "webp"],
                accept_multiple_files=False,
                key=receipt_key,
            )
    balance = final_sales - total_payment_int
    st.metric("잔금 (미수금)", f"{balance:,}원", help="최종 총 판매금액 - 누적 결제금액")

    # 예상 수수료·최종 실질 마진율 (결제 수단별 수수료 반영, 실시간)
    total_fee_est = sum(
        _payment_fee_amount(st.session_state.get(f"pay_method_{i}", ""), _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0")))
        for i in range(slot_count)
    )
    net_margin_rate_est = _compute_net_margin_rate(float(final_sales), float(final_cost), total_fee_est)
    fee_delta = net_margin_rate_est - basic_margin_rate
    fee_col, margin_col = st.columns(2)
    with fee_col:
        st.metric("예상 수수료", f"{int(total_fee_est):,}원", help="신용카드·메인페이 2.5%, 체크카드 1.5%, 그 외 0%")
    with margin_col:
        _net_icon = "🟢" if net_margin_rate_est >= 20 else ("🟡" if net_margin_rate_est >= 15 else "🔴")
        st.metric(
            f"최종 실질 마진율 {_net_icon}",
            f"{net_margin_rate_est:.1f}%",
            delta=f"{fee_delta:+.1f}%",
            delta_color="normal",
            help="(판매가 − 원가 − 수수료) / 판매가 × 100 (카드·메인페이 등 수수료 반영 후 최종 마진율)",
        )

    # 이상 마진율 사유 입력 (실질 마진율 10% 이하 또는 30% 이상이면 필수)
    # 표시 기준과 저장 검증 기준 모두 net_margin_rate(수수료 반영)으로 통일하여 데드락 방지
    _MARGIN_REASON_LOW = 10.0
    _MARGIN_REASON_HIGH = 30.0
    _margin_reason_required = final_sales > 0 and (net_margin_rate_est < _MARGIN_REASON_LOW or net_margin_rate_est > _MARGIN_REASON_HIGH)
    if _margin_reason_required:
        _margin_direction = "낮습니다 (10% 미만)" if net_margin_rate_est < _MARGIN_REASON_LOW else "높습니다 (30% 초과)"
        st.warning(
            f"⚠️ 현재 **실질 마진율**이 **{net_margin_rate_est:.1f}%** 로 정상 범위(10%~30%)보다 **{_margin_direction}**. "
            "등록하려면 아래에 사유를 반드시 입력하세요."
        )
        st.text_input(
            "이상 마진율 사유 (필수, 5자 이상) *",
            key="margin_anomaly_reason",
            placeholder="예: 현대임직원할인, 전시품 처분 할인, 소품 고마진 등",
        )
    else:
        st.session_state.pop("margin_anomaly_reason", None)

    # 결제 합계가 0원이면 사유 필수 입력 (계약금 0원 등록 방지·근거 확보)
    if total_payment_int <= 0:
        st.warning(
            "⚠️ 결제 합계가 **0원**입니다. 등록하려면 아래에 사유(5자 이상)를 반드시 입력하세요."
        )
        st.text_input(
            "결제 0원 사유 (필수, 5자 이상) *",
            key="zero_payment_reason",
            placeholder="예: 전액 어음 처리, 인수금 추후 수령 예정, 계약만 선접수 등",
        )
    else:
        st.session_state.pop("zero_payment_reason", None)

    if st.button("매출 등록"):
        cust_name_ok = cust_name and cust_name.strip()
        phone1_ok = phone1 and phone1.strip()
        delivery_ok = delivery_date is not None
        if not cust_name_ok:
            st.error("고객명(필수)을 입력하세요.")
            st.stop()
        if not phone1_ok:
            st.error("Phone 1(필수)을 입력하세요.")
            st.stop()
        if not delivery_ok:
            st.error("배송일(필수)을 선택하세요.")
            st.stop()
        if not selected_categories:
            st.error("품목/카테고리(필수)를 1개 이상 선택하세요.")
            st.stop()
        # 방문 이유 필수
        if not visit_reason_sel:
            st.error("방문 이유(필수)를 선택하세요.")
            st.stop()
        if visit_reason_sel == "기타(메모필수)":
            _memo_val = (st.session_state.get("visit_reason_memo") or "").strip()
            if not _memo_val:
                st.error("방문 이유 '기타' 선택 시 메모를 반드시 입력해야 합니다.")
                st.stop()
        # 구매 이유 필수
        if not purchase_reason_sel:
            st.error("구매 이유(필수)를 선택하세요.")
            st.stop()
        # 담당 직원 필수 — 미선택 시 KPI/직원평가에서 영구 누락되므로 저장 차단
        if not selected_employees:
            st.error("담당 직원(필수)을 1명 이상 선택하세요. KPI·실적 분배에 필요합니다.")
            st.stop()
        cost_price_int = _parse_comma_to_int(st.session_state.get("cost_price", "0"))
        general_sales_int = _parse_comma_to_int(st.session_state.get("total_amount", "0"))
        display_sales_int = _parse_comma_to_int(st.session_state.get("display_sales_amount", "0")) if has_display else 0
        display_cost_int = _parse_comma_to_int(st.session_state.get("display_cost_amount", "0")) if has_display else 0
        final_sales_save = general_sales_int + display_sales_int
        final_cost_save = cost_price_int + display_cost_int
        basic_margin_save = final_sales_save - final_cost_save
        # 판매가/원가 0원 등록 차단 — 0원 매출은 KPI·마진율 계산을 왜곡시킴
        if final_sales_save <= 0:
            st.error("판매가(필수)를 입력하세요. 일반/전시품 합계가 0원보다 커야 합니다.")
            st.stop()
        if general_sales_int > 0 and cost_price_int <= 0:
            st.error("일반제품 원가(필수)를 입력하세요.")
            st.stop()
        if has_display:
            if display_sales_int <= 0:
                st.error("전시품 판매가(필수)를 입력하세요.")
                st.stop()
            if display_cost_int <= 0:
                st.error("전시품 원가(필수)를 입력하세요.")
                st.stop()
        # 결제 합계 및 미수금(잔금) 계산 — 완불이 아니어도 저장 가능(계약금만 받고 저장 가능)
        total_payment_slots = sum(_parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0")) for i in range(slot_count))
        unpaid_balance = final_sales_save - total_payment_slots  # 판매가 - 수납액 = 미수금
        # 결제 합계 0원이면 사유 5자 이상 필수 — 근거 없는 0원 등록 차단
        if total_payment_slots <= 0:
            _zero_pay_reason_val = (st.session_state.get("zero_payment_reason") or "").strip()
            if len(_zero_pay_reason_val) < 5:
                st.error("결제 합계가 0원입니다. 등록하려면 **결제 0원 사유(5자 이상)** 를 입력하세요.")
                st.stop()
        # 수수료 합계 및 실질 마진율 (신용카드·메인페이 2.5% 반영)
        total_fees_save = 0.0
        for i in range(slot_count):
            amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
            method = st.session_state.get(f"pay_method_{i}", "")
            total_fees_save += _payment_fee_amount(method, amt)
        net_margin_rate_save = _compute_net_margin_rate(float(final_sales_save), float(final_cost_save), total_fees_save)
        margin_out_of_range = net_margin_rate_save < 15 or net_margin_rate_save > 25
        if margin_out_of_range:
            st.warning(f"⚠️ 주의: 실질 마진율이 {net_margin_rate_save:.1f}%입니다. 적정 범위(15%~25%)를 벗어났습니다.")
        # 이상 마진율 사유 필수 검증: 10% 미만 또는 30% 초과 시 사유 5자 이상 필수
        if final_sales_save > 0 and (net_margin_rate_save < 10.0 or net_margin_rate_save > 30.0):
            _margin_reason_val = (st.session_state.get("margin_anomaly_reason") or "").strip()
            if len(_margin_reason_val) < 5:
                _direction_msg = "낮습니다 (10% 미만)" if net_margin_rate_save < 10.0 else "높습니다 (30% 초과)"
                st.error(
                    f"⚠️ 마진율이 **{net_margin_rate_save:.1f}%** 로 정상 범위(10%~30%)보다 {_direction_msg}. "
                    "이상 마진율 사유를 5자 이상 입력해야 등록할 수 있습니다."
                )
                st.stop()
        # 카드사·승인번호 필수 검증
        for i in range(slot_count):
            method = st.session_state.get(f"pay_method_{i}", "")
            amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
            if amt <= 0:
                continue
            if method in _CARD_WITH_COMPANY:
                _cc = (st.session_state.get(f"pay_card_{i}", "") or "").strip()
                if not _cc:
                    st.error(f"결제 #{i+1} {method} 카드사를 선택하세요.")
                    st.stop()
            elif method == "메인페이":
                _appr = re.sub(r"\D", "", (st.session_state.get(f"pay_card_{i}", "") or "").strip())
                if len(_appr) != 4:
                    st.error(f"결제 #{i+1} 메인페이 승인번호 4자리를 정확히 입력하세요.")
                    st.stop()
            elif method == "지역화폐":
                _appr = re.sub(r"\D", "", (st.session_state.get(f"pay_card_{i}", "") or "").strip())
                if len(_appr) != 6:
                    st.error(f"결제 #{i+1} 지역화폐 승인번호 6자리를 정확히 입력하세요.")
                    st.stop()
        # 온누리(전자): 검증파일 구매자전화번호 뒤 4자리 필수. 겹치면 거래시간 필수.
        _pay_date_dup = order_date.isoformat() if hasattr(order_date, "isoformat") else str(order_date)
        _new_onnuri_codes: dict[int, str] = {}
        for i in range(slot_count):
            method = st.session_state.get(f"pay_method_{i}", "")
            amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
            if amt <= 0:
                continue
            if not method or "온누리" not in str(method) or "지류" in str(method):
                continue
            last4_raw = (st.session_state.get(f"pay_onnuri_last4_{i}", "") or "").strip()
            last4_digits = re.sub(r"\D", "", last4_raw)
            _form_hit = _onnuri_same_form_collides(
                this_index=i, last4=last4_digits, amount=amt, slot_count=slot_count,
                last4_key_fn=lambda j: f"pay_onnuri_last4_{j}",
                amt_key_fn=lambda j: f"pay_amt_{j}",
                method_key_fn=lambda j: f"pay_method_{j}",
            )
            _need_t = _onnuri_should_ask_time(
                db_filename, last4_digits, amt, _pay_date_dup, form_collides=_form_hit,
            )
            _code, _err = _onnuri_compose_ident(
                last4_raw, st.session_state.get(f"pay_onnuri_time_{i}", ""), require_time=_need_t,
            )
            if _err:
                st.error(f"결제 #{i+1}: {_err}")
                st.stop()
            _new_onnuri_codes[i] = _code or last4_digits
        # 같은 폼·기존 DB 의 지역화폐 승인번호 / 온누리 식별자 중복 차단
        _seen_ulsan: set[str] = set()
        _seen_onnuri: set[tuple[str, int, str]] = set()
        for i in range(slot_count):
            method = st.session_state.get(f"pay_method_{i}", "")
            amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
            if amt <= 0 or not method:
                continue
            if method == "지역화폐":
                _appr = re.sub(r"\D", "", (st.session_state.get(f"pay_card_{i}", "") or "").strip())
                if _appr in _seen_ulsan:
                    st.error(f"결제 #{i+1}: 같은 등록 화면에 지역화폐 승인번호 {_appr} 가 중복됩니다.")
                    st.stop()
                _ulsan_at = _ulsan_approval_already_used(db_filename, _appr)
                if _ulsan_at:
                    st.error(
                        f"결제 #{i+1}: 지역화폐 승인번호 {_appr} 는 이미 등록된 결제입니다. "
                        f"(매장: {_ulsan_at}) 전 매장에서 같은 승인번호를 다시 입력할 수 없습니다."
                    )
                    st.stop()
                _seen_ulsan.add(_appr)
            elif "온누리" in str(method) and "지류" not in str(method):
                _code = _new_onnuri_codes.get(i) or ""
                _last4 = _onnuri_last4_from_code(_code)
                _tx_t = _onnuri_time_from_code(_code) or ""
                _okey = (_last4, int(amt), _tx_t)
                if _okey in _seen_onnuri:
                    st.error(
                        f"결제 #{i+1}: 같은 등록 화면에 온누리 뒤 4자리 {_last4} / 금액 {amt:,}원"
                        + (f" / 거래시간 {_onnuri_format_time_display(_tx_t)}" if _tx_t else "")
                        + " 이 중복됩니다."
                    )
                    st.stop()
                if _onnuri_ident_already_used(db_filename, _last4, amt, _pay_date_dup, tx_time=_tx_t or None):
                    st.error(
                        f"결제 #{i+1}: 온누리 전화번호 뒤 4자리 {_last4} · {amt:,}원 · {_pay_date_dup}"
                        + (f" · {_onnuri_format_time_display(_tx_t)}" if _tx_t else "")
                        + " 결제가 이미 있습니다. 같은 건을 다시 입력할 수 없습니다."
                    )
                    st.stop()
                _seen_onnuri.add(_okey)
        use_supabase_op = _supabase_orders_payments_available()
        # 성과 축하는 신규 INSERT 시에만 1회 트리거 (UPDATE/수정 시 미설정). INSERT 전 메타데이터 수집.
        today_iso = order_date.isoformat() if hasattr(order_date, "isoformat") else str(_today_kst())
        _count_today_before = _count_orders_on_date(db_filename, today_iso)
        is_today_first = _count_today_before == 0
        _year = order_date.year if hasattr(order_date, "year") else _today_kst().year
        _month = order_date.month if hasattr(order_date, "month") else _today_kst().month
        monthly_max_before = _cached_employee_monthly_max(db_filename, employee_names_str, _year, _month)

        _saving_msg = st.empty()
        _saving_msg.info("⏳ 저장하는 중입니다... 잠시 기다려 주세요.")

        if use_supabase_op:
            if is_new_customer:
                customer_id, ins_err = _supabase_insert_customer(db_filename, cust_name, phone1, phone2, address_full)
                if customer_id is None:
                    st.error("고객 등록에 실패했습니다. " + (ins_err or "Supabase app_customers 테이블·스키마(store_name, name, phone1 등)를 확인해 주세요."))
                    st.stop()
            else:
                customer_id = int(selected_customer_row["id"])
            _ensure_customer_admin_dong(db_filename, customer_id, address_full)
            order_payload = {
                "customer_id": customer_id,
                "employee_names": employee_names_str or None,
                "order_date": order_date.isoformat(),
                "delivery_date": delivery_date.isoformat() if delivery_date else None,
                "category": category,
                "cost_price": cost_price_int,
                "total_amount": final_sales_save,
                "visit_reason": visit_reason or None,
                "purchase_reason": purchase_reason or None,
                "display_sales_amount": display_sales_int,
                "display_cost_amount": display_cost_int,
                "balance_status": "미납",
            }
            if is_new_customer:
                order_payload["entry_source"] = "new_customer_sale"
            order_id = _insert_order_supabase(db_filename, order_payload)
            if order_id is None:
                st.error("주문 등록에 실패했습니다. Supabase를 확인해 주세요.")
                st.stop()
            total_fees = 0.0
            total_paid_initial = 0
            for i in range(slot_count):
                amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
                if amt <= 0:
                    continue
                method = st.session_state.get(f"pay_method_{i}", "")
                card_company = st.session_state.get(f"pay_card_{i}", None) if method in (*_CARD_WITH_COMPANY, "메인페이", "지역화폐") else None
                fee = _payment_fee_amount(method, amt)
                total_fees += fee
                total_paid_initial += amt
                onnuri_code = _new_onnuri_codes.get(i)
                _insert_payment_supabase(db_filename, {
                    "order_id": order_id,
                    "payment_date": order_date.isoformat(),
                    "amount": amt,
                    "payment_method": method or None,
                    "card_company": card_company,
                    "fee_amount": fee,
                    "onnuri_approval_code": onnuri_code,
                    "created_by": _current_username(),
                })
            actual_margin = basic_margin_save - total_fees  # 실질 마진 = 판매가 - 원가 - 수수료
            remaining = final_sales_save - total_paid_initial
            balance_status = _balance_status_from_remaining(remaining)
            _update_order_supabase(db_filename, order_id, {"actual_margin": actual_margin, "balance_status": balance_status})
            _margin_reason_saved = (st.session_state.get("margin_anomaly_reason") or "").strip()
            _zero_pay_reason_saved = (st.session_state.get("zero_payment_reason") or "").strip() if total_payment_slots <= 0 else ""
            _sales_note = "신규 주문"
            if _margin_reason_saved:
                _sales_note += f" | 이상마진 사유: {_margin_reason_saved}"
            if _zero_pay_reason_saved:
                _sales_note += f" | 결제0 사유: {_zero_pay_reason_saved}"
            _insert_sales_transaction(db_filename, order_id, order_date.isoformat(), float(final_sales_save), _sales_note, unpaid_balance=unpaid_balance, employee_names=employee_names_str or None)
            clear_data_cache()
            _saving_msg.empty()
            st.success("매출등록이 완료되었습니다.")
            # 카카오 채널 구매 알림 자동 발송 (백그라운드 — 실패해도 주문 등록에 영향 없음)
            try:
                from customer_channel import send_purchase_notification as _send_kakao_notif
                _kakao_res = _send_kakao_notif(
                    customer_id=int(customer_id),
                    phone=str(phone1 or ""),
                    customer_name=str(cust_name or ""),
                    order_info={
                        "category": category,
                        "total_amount": int(final_sales_save),
                        "delivery_date": delivery_date.isoformat() if delivery_date else "",
                    },
                    store_name=store_name or db_filename or "",
                    order_id=order_id,
                    sent_by=_current_username(),
                )
                if _kakao_res.get("status") == "sent":
                    st.toast("카카오 알림 발송 완료", icon="💬")
                elif _kakao_res.get("status") == "skipped":
                    pass  # 키 미설정 환경에서는 조용히 스킵
            except Exception:
                pass  # 알림 실패가 주문 등록 화면을 깨지 않도록
            # 리드 자동 클로즈: 동일 전화번호의 활성 리드가 있으면 4_계약완료로 업데이트
            try:
                from lead_manager import auto_close_lead as _auto_close_lead
                _auto_close_lead(
                    phone=str(phone1 or ""),
                    order_id=order_id,
                    revenue=float(final_sales_save),
                    employee_names=str(employee_names_str or ""),
                )
            except Exception:
                pass  # 리드 클로즈 실패가 매출 등록 화면을 깨지 않도록
            net_margin_rate_ctx = _compute_net_margin_rate(float(final_sales_save), float(final_cost_save), total_fees)
            st.session_state["_gamification_ctx"] = {
                "amount": final_sales_save,
                "cost": final_cost_save,
                "margin_pct": net_margin_rate_ctx,
                "employee_names": employee_names_str,
                "db_filename": db_filename,
                "order_date": order_date,
                "is_today_first": is_today_first,
                "monthly_max_before": monthly_max_before,
            }
            st.toast("등록이 완료되었습니다.", icon="✅")
            st.session_state["_new_sales_form_reset"] = st.session_state.get("_new_sales_form_reset", 0) + 1
            st.session_state["_cust_search_panel_open"] = False
            # 반복 등록 시 금액이 이전 건과 동일하게 남는 현상 방지: 비위젯 상태 초기화 후 위젯 키는 삭제
            st.session_state["payment_slot_count"] = DEFAULT_PAYMENT_SLOTS
            st.session_state["payment_rows"] = [{"method": "", "card_company": "", "amount": "0"} for _ in range(MAX_PAYMENT_SLOTS)]
            for key in list(st.session_state.keys()):
                if key in (
                    "phone1", "phone2", "address_manual", "address_detail",
                    "address_search_results", "address_search_error", "addr_keyword", "address_selection",
                    "order_date", "delivery_date",
                    "_show_address_dialog", "_dialog_addr_results", "_dialog_addr_error",
                    "_new_sales_selected_customer", "_cust_search_results",
                    "new_sales_cust_name", "new_sales_cust_search", "new_sales_cust_select",
                    "cost_price", "total_amount", "display_sales_amount", "display_cost_amount",
                    "visit_reason", "purchase_reason",
                    "payment_rows",
                    "margin_anomaly_reason",
                    "zero_payment_reason",
                ) or key.startswith(("pay_", "pay_onnuri_", "gen_pay", "d10_", "over_", "new_sales_employee_multiselect", "category_multiselect")):
                    try:
                        del st.session_state[key]
                    except Exception:
                        pass
            st.session_state["_sales_complete_banner"] = {"amount": final_sales_save, "cust_name": cust_name}
            st.rerun()
        else:
            conn = get_tenant_conn(db_filename)
            try:
                if is_new_customer:
                    customer_id, ins_err = _supabase_insert_customer(db_filename, cust_name, phone1, phone2, address_full)
                    if customer_id is None:
                        st.error("고객 등록에 실패했습니다. " + (ins_err or "Supabase app_customers 테이블·스키마(store_name, name, phone1 등)를 확인해 주세요."))
                        st.stop()
                else:
                    customer_id = int(selected_customer_row["id"])
                _ensure_customer_admin_dong(db_filename, customer_id, address_full)
                conn.execute("""
                    INSERT INTO Orders (customer_id, employee_names, order_date, delivery_date, category, cost_price, total_amount, visit_reason, purchase_reason, display_sales_amount, display_cost_amount, balance_status)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """, (
                    customer_id,
                    employee_names_str or None,
                    order_date.isoformat(),
                    delivery_date.isoformat(),
                    category,
                    cost_price_int,
                    final_sales_save,
                    visit_reason or None,
                    purchase_reason or None,
                    display_sales_int,
                    display_cost_int,
                    "미납",
                ))
                order_id = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
                total_fees = 0.0
                total_paid_initial = 0
                for i in range(slot_count):
                    amt = _parse_comma_to_int(st.session_state.get(f"pay_amt_{i}", "0"))
                    if amt <= 0:
                        continue
                    method = st.session_state.get(f"pay_method_{i}", "")
                    card_company = st.session_state.get(f"pay_card_{i}", None) if method in ("신용카드", "메인페이") else None
                    fee = _payment_fee_amount(method, amt)
                    total_fees += fee
                    total_paid_initial += amt
                    onnuri_code = _new_onnuri_codes.get(i)
                    conn.execute("""
                        INSERT INTO Payments (order_id, payment_date, amount, payment_method, card_company, fee_amount, onnuri_approval_code, created_by, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now', '+9 hours'))
                    """, (order_id, order_date.isoformat(), amt, method or None, card_company, fee, onnuri_code, _current_username()))
                actual_margin = basic_margin_save - total_fees
                conn.execute("UPDATE Orders SET actual_margin = ? WHERE id = ?", (actual_margin, order_id))
                remaining = final_sales_save - total_paid_initial
                balance_status = _balance_status_from_remaining(remaining)
                conn.execute("UPDATE Orders SET balance_status = ? WHERE id = ?", (balance_status, order_id))
                _margin_reason_saved = (st.session_state.get("margin_anomaly_reason") or "").strip()
                _zero_pay_reason_saved = (st.session_state.get("zero_payment_reason") or "").strip() if total_payment_slots <= 0 else ""
                _sales_note = "신규 주문"
                if _margin_reason_saved:
                    _sales_note += f" | 이상마진 사유: {_margin_reason_saved}"
                if _zero_pay_reason_saved:
                    _sales_note += f" | 결제0 사유: {_zero_pay_reason_saved}"
                _insert_sales_transaction(db_filename, order_id, order_date.isoformat(), float(final_sales_save), _sales_note, unpaid_balance=unpaid_balance, employee_names=employee_names_str or None)
                conn.commit()
                clear_data_cache()
                net_margin_rate_ctx = _compute_net_margin_rate(float(final_sales_save), float(final_cost_save), total_fees)
            finally:
                conn.close()
            _saving_msg.empty()
            st.session_state["_gamification_ctx"] = {
                "amount": final_sales_save,
                "cost": final_cost_save,
                "margin_pct": net_margin_rate_ctx,
                "employee_names": employee_names_str,
                "db_filename": db_filename,
                "order_date": order_date,
                "is_today_first": is_today_first,
                "monthly_max_before": monthly_max_before,
            }
            st.success("매출등록이 완료되었습니다.")
            # 마진율 이상 시 Superadmin/매장관리자 알림
            if margin_out_of_range:
                store_name = _get_store_name_by_db(db_filename)
                _insert_admin_alert(store_name, "margin", f"{store_name}에서 실질 마진율 {net_margin_rate_save:.1f}% 건이 등록되었습니다.")
            st.toast("등록이 완료되었습니다.", icon="✅")
            st.session_state["_new_sales_form_reset"] = st.session_state.get("_new_sales_form_reset", 0) + 1
            st.session_state["_cust_search_panel_open"] = False
            # 반복 등록 시 금액이 이전 건과 동일하게 남는 현상 방지: 비위젯 상태 초기화 후 위젯 키는 삭제
            st.session_state["payment_slot_count"] = DEFAULT_PAYMENT_SLOTS
            st.session_state["payment_rows"] = [{"method": "", "card_company": "", "amount": "0"} for _ in range(MAX_PAYMENT_SLOTS)]
            # 신규 매출 등록 관련 상태 초기화
            for key in list(st.session_state.keys()):
                if key in (
                    "phone1", "phone2", "address_manual", "address_detail",
                    "address_search_results", "address_search_error", "addr_keyword", "address_selection",
                    "order_date", "delivery_date",
                    "_show_address_dialog", "_dialog_addr_results", "_dialog_addr_error",
                    "_new_sales_selected_customer", "_cust_search_results",
                    "new_sales_cust_name", "new_sales_cust_search", "new_sales_cust_select",
                    "cost_price", "total_amount", "display_sales_amount", "display_cost_amount",
                    "visit_reason", "purchase_reason",
                    "payment_rows",
                    "margin_anomaly_reason",
                    "zero_payment_reason",
                ) or key.startswith(("pay_", "pay_onnuri_", "gen_pay", "d10_", "over_", "new_sales_employee_multiselect", "category_multiselect")):
                    try:
                        del st.session_state[key]
                    except Exception:
                        pass
            st.session_state["_sales_complete_banner"] = {"amount": final_sales_save, "cust_name": cust_name}
            st.rerun()


# ========== 탭 3: 고객 및 잔금 관리 (3개 하위 탭) ==========

def _recalc_order_actual_margin(conn, order_id: int, db_filename: str | None = None):
    """해당 주문의 Payments 수수료 합계 및 잔금 상태(balance_status)를 Orders에 반영. Supabase 사용 시 db_filename 필요."""
    if _supabase_orders_payments_available() and db_filename:
        _recalc_order_actual_margin_supabase(db_filename, order_id)
        return
    row = conn.execute(
        "SELECT total_amount, cost_price, COALESCE(display_cost_amount,0) FROM Orders WHERE id = ?",
        (order_id,),
    ).fetchone()
    if not row:
        return
    total_amt, cost_general, cost_display = row[0] or 0, row[1] or 0, row[2] or 0
    total_fees = conn.execute(
        "SELECT COALESCE(SUM(fee_amount),0) FROM Payments WHERE order_id = ?",
        (order_id,),
    ).fetchone()[0]
    basic_m = total_amt - (cost_general + cost_display)
    conn.execute(
        "UPDATE Orders SET actual_margin = ? WHERE id = ?",
        (basic_m - total_fees, order_id),
    )
    paid = conn.execute(
        "SELECT COALESCE(SUM(amount),0) FROM Payments WHERE order_id = ?",
        (order_id,),
    ).fetchone()[0]
    remaining = (total_amt or 0) - (paid or 0)
    balance_status = _balance_status_from_remaining(remaining)
    conn.execute(
        "UPDATE Orders SET balance_status = ? WHERE id = ?",
        (balance_status, order_id),
    )


def _multi_order_split_payment_ui(db_filename: str, orders_df: pd.DataFrame, key_prefix: str = "split"):
    """동일 고객의 복수 주문에 단일 결제 금액을 분배 등록하는 UI.
    orders_df: 잔금이 있는 주문들의 DataFrame (columns: id, balance, order_date, category, total_amount).
    한 번의 결제 수단/금액 입력으로 여러 주문에 자동 분배 저장."""
    if orders_df is None or len(orders_df) < 2:
        return

    st.markdown("#### 💳 복수 주문 분배 결제")
    st.caption("한 번의 결제(카드·온누리 등)로 여러 주문에 금액을 나누어 등록합니다.")

    # 총 잔금 표시
    total_balance = float(orders_df["balance"].sum())
    st.metric("전체 주문 합산 잔금", f"{total_balance:,.0f}원")

    # 실제 입금액 입력 (배분 합계와 반드시 일치해야 등록 가능)
    _actual_paid_key = f"{key_prefix}_actual_paid"
    if _actual_paid_key not in st.session_state:
        st.session_state[_actual_paid_key] = ""
    st.text_input(
        "실제 입금액 ★ (고객이 실제 납부한 총 금액)",
        key=_actual_paid_key,
        placeholder="예: 1,000,000",
        help="각 주문 배분 금액의 합계와 반드시 일치해야 등록됩니다.",
        on_change=lambda: st.session_state.__setitem__(_actual_paid_key, _format_number_comma(st.session_state.get(_actual_paid_key, ""))),
    )

    # 결제 수단 / 날짜
    _split_date_key = f"{key_prefix}_date"
    if _split_date_key not in st.session_state:
        st.session_state[_split_date_key] = _today_kst()
    col_m, col_d = st.columns(2)
    with col_m:
        split_method = st.selectbox("결제 수단", options=PAYMENT_METHOD_OPTIONS, key=f"{key_prefix}_method")
    with col_d:
        split_date = st.date_input("결제 날짜 *", key=_split_date_key)

    # 카드사 / 메인페이
    _CARD_WITH_COMPANY_SPLIT = ("신용카드", "체크카드")
    if split_method in _CARD_WITH_COMPANY_SPLIT:
        split_card = st.selectbox("카드사", options=CARD_COMPANY_OPTIONS, key=f"{key_prefix}_card")
    elif split_method == "메인페이":
        split_card = st.text_input("메인페이 승인번호 4자리", key=f"{key_prefix}_card", max_chars=4)
    elif split_method == "지역화폐":
        split_card = st.text_input("지역화폐 승인번호", key=f"{key_prefix}_card")
    else:
        split_card = None
        st.session_state.pop(f"{key_prefix}_card", None)

    # 온누리(전자) 식별자: 검증파일 구매자전화번호 뒤 4자리
    is_onnuri_split = split_method and "온누리" in str(split_method) and "지류" not in str(split_method)
    _onnuri_last4_key = f"{key_prefix}_onnuri_last4"
    if is_onnuri_split:
        st.text_input(
            "온누리 전화번호 뒤 4자리",
            key=_onnuri_last4_key,
            max_chars=4,
            help="검증파일의 구매자전화번호 뒤 4자리",
        )
        _sp_last4 = re.sub(r"\D", "", str(st.session_state.get(_onnuri_last4_key, "") or ""))
        _sp_amt = _parse_comma_to_int(st.session_state.get(_actual_paid_key, "0"))
        _sp_date = split_date.isoformat() if hasattr(split_date, "isoformat") else _today_kst().isoformat()
        _onnuri_time_input(
            f"{key_prefix}_onnuri_time",
            visible=_onnuri_should_ask_time(db_filename, _sp_last4, _sp_amt, _sp_date),
            label="온누리 거래시간 *",
        )
    else:
        st.session_state.pop(_onnuri_last4_key, None)
        st.session_state.pop(f"{key_prefix}_onnuri", None)

    st.markdown("**주문별 배분 금액 입력**")
    st.caption("각 주문에 배분할 금액을 입력하세요. 합계가 실제 수령 금액과 일치해야 합니다.")

    alloc_keys = {}
    for _, orow in orders_df.iterrows():
        oid = int(orow["id"])
        bal = float(orow.get("balance") or 0)
        cat = str(orow.get("category") or "-")
        od = orow.get("order_date", "")
        od_str = str(od)[:10] if od else "-"
        ak = f"{key_prefix}_alloc_{oid}"
        if ak not in st.session_state:
            st.session_state[ak] = _format_number_comma(str(int(bal)))
        alloc_keys[oid] = ak
        col_info, col_input = st.columns([2, 1])
        with col_info:
            st.write(f"주문 #{oid} | {cat} | {od_str} | 잔금 **{bal:,.0f}원**")
        with col_input:
            st.text_input(
                f"배분 금액",
                key=ak,
                label_visibility="collapsed",
                on_change=lambda k=ak: st.session_state.__setitem__(k, _format_number_comma(st.session_state.get(k, ""))),
            )

    # 배분 합계 ↔ 실입금액 일치 검증 (실시간 표시)
    alloc_total = sum(_parse_comma_to_int(st.session_state.get(ak, "0")) for ak in alloc_keys.values())
    actual_paid_int = _parse_comma_to_int(st.session_state.get(_actual_paid_key, "0"))

    if alloc_total > 0:
        if actual_paid_int > 0:
            _diff = alloc_total - actual_paid_int
            if _diff == 0:
                st.success(f"✅ 배분 합계 **{alloc_total:,.0f}원** = 실입금액 **{actual_paid_int:,.0f}원** (일치)")
            elif _diff > 0:
                st.error(f"❌ 배분 합계({alloc_total:,}원)가 실입금액({actual_paid_int:,}원)보다 **{_diff:,}원 초과**합니다.")
            else:
                st.error(f"❌ 배분 합계({alloc_total:,}원)가 실입금액({actual_paid_int:,}원)보다 **{-_diff:,}원 부족**합니다.")
        else:
            st.info(f"배분 합계: **{alloc_total:,.0f}원** | ← 위의 실제 입금액을 입력하세요.")

    # 주문별 잔금 초과 배분 경고
    for _, _orow_chk in orders_df.iterrows():
        _oid_chk = int(_orow_chk["id"])
        _bal_chk = float(_orow_chk.get("balance") or 0)
        _ak_chk = alloc_keys.get(_oid_chk)
        if _ak_chk:
            _alloc_chk = _parse_comma_to_int(st.session_state.get(_ak_chk, "0"))
            if _alloc_chk > 0 and _alloc_chk > _bal_chk:
                _over_chk = _alloc_chk - _bal_chk
                st.warning(f"⚠️ 주문 #{_oid_chk}: 배분 금액({_alloc_chk:,}원)이 잔금({_bal_chk:,.0f}원)보다 **{_over_chk:,}원 초과**합니다.")

    split_reason = st.text_area("처리 사유 (필수, 5자 이상)", key=f"{key_prefix}_reason", placeholder="예: 온누리상품권 100만원 단일 결제 — 70만/30만 분배")

    if st.button("분배 결제 일괄 등록", key=f"{key_prefix}_btn", type="primary"):
        if not split_reason or len(split_reason.strip()) < 5:
            st.warning("사유를 5자 이상 입력하세요.")
            return
        if alloc_total <= 0:
            st.warning("배분 금액을 1원 이상 입력하세요.")
            return
        if actual_paid_int <= 0:
            st.error("실제 입금액을 입력하세요.")
            return
        if alloc_total != actual_paid_int:
            st.error(f"배분 합계({alloc_total:,}원)와 실제 입금액({actual_paid_int:,}원)이 일치하지 않습니다. 각 주문 배분 금액 또는 실제 입금액을 수정하세요.")
            return

        onnuri_code = None
        pay_date_str = split_date.isoformat() if hasattr(split_date, "isoformat") else _today_kst().isoformat()
        if is_onnuri_split:
            last4_raw = (st.session_state.get(_onnuri_last4_key, "") or "").strip()
            last4_digits = re.sub(r"\D", "", last4_raw)
            _need_t = _onnuri_should_ask_time(db_filename, last4_digits, actual_paid_int, pay_date_str)
            onnuri_code, _on_err = _onnuri_compose_ident(
                last4_raw, st.session_state.get(f"{key_prefix}_onnuri_time", ""), require_time=_need_t,
            )
            if _on_err:
                st.error(_on_err)
                return
            _tx_t = _onnuri_time_from_code(onnuri_code)
            if _onnuri_ident_already_used(db_filename, last4_digits, actual_paid_int, pay_date_str, tx_time=_tx_t):
                st.error(
                    f"온누리 {last4_digits} · {actual_paid_int:,}원 · {pay_date_str}"
                    + (f" · {_onnuri_format_time_display(_tx_t)}" if _tx_t else "")
                    + " 결제가 이미 있습니다."
                )
                return
        if split_method == "지역화폐":
            _appr = re.sub(r"\D", "", str(split_card or ""))
            _ulsan_at = _ulsan_approval_already_used(db_filename, _appr)
            if _ulsan_at:
                st.error(
                    f"지역화폐 승인번호 {_appr} 는 이미 등록된 결제입니다. "
                    f"(매장: {_ulsan_at}) 전 매장에서 같은 승인번호를 다시 입력할 수 없습니다."
                )
                return

        errors = []
        success_count = 0

        for oid, ak in alloc_keys.items():
            alloc_amt = _parse_comma_to_int(st.session_state.get(ak, "0"))
            if alloc_amt <= 0:
                continue
            orow_match = orders_df[orders_df["id"] == oid]
            if orow_match.empty:
                continue
            bal = float(orow_match.iloc[0].get("balance") or 0)
            fee = _payment_fee_amount(split_method, alloc_amt)
            try:
                if _supabase_orders_payments_available():
                    old_paid, _ = _sum_payments_by_order_supabase(db_filename, oid)
                    _insert_payment_supabase(db_filename, {
                        "order_id": oid,
                        "payment_date": pay_date_str,
                        "amount": alloc_amt,
                        "payment_method": split_method or None,
                        "card_company": split_card,
                        "fee_amount": fee,
                        "onnuri_approval_code": onnuri_code,
                        "created_by": _current_username(),
                    })
                    _recalc_order_actual_margin_supabase(db_filename, oid)
                    new_paid = old_paid + alloc_amt
                    cid_ph = _get_order_customer_id_supabase(db_filename, oid)
                    cname_ph = _get_customer_name_supabase(db_filename, cid_ph) if cid_ph else ""
                    _insert_payment_history(
                        None, oid, cname_ph, "분배결제(복수주문)",
                        {"order_id": oid, "balance_before": bal, "paid_total_before": old_paid},
                        {"order_id": oid, "added_amount": alloc_amt, "method": split_method, "balance_after": bal - alloc_amt, "paid_total_after": new_paid},
                        split_reason, db_filename=db_filename,
                    )
                else:
                    conn = get_tenant_conn(db_filename)
                    old_paid = conn.execute("SELECT COALESCE(SUM(amount),0) FROM Payments WHERE order_id=?", (oid,)).fetchone()[0] or 0
                    conn.execute(
                        "INSERT INTO Payments (order_id, payment_date, amount, payment_method, card_company, fee_amount, onnuri_approval_code, created_by, created_at) VALUES (?,?,?,?,?,?,?,?,datetime('now', '+9 hours'))",
                        (oid, pay_date_str, alloc_amt, split_method or None, split_card, fee, onnuri_code, _current_username()),
                    )
                    _recalc_order_actual_margin(conn, oid, db_filename)
                    conn.commit()
                    conn.close()
                success_count += 1
            except Exception as e:
                errors.append(f"주문 #{oid}: {e}")

        clear_data_cache()
        if errors:
            for err in errors:
                st.error(err)
        if success_count > 0:
            st.toast(f"✅ {success_count}건 분배 결제 등록 완료!", icon="✅")
            st.rerun()


@st.fragment
def _customer_balance_payment_ui(
    db_filename: str,
    order_id: int,
    balance: float,
    key_prefix: str = "pay",
    default_payment_date: date | None = None,
):
    """잔금 완납 처리(결제 추가) 공통 UI — 신규 매출 등록과 동일한 복수 결제 슬롯.

    한 주문에 여러 결제 수단을 한 번에 등록할 수 있다 (예: 신용카드 + 현금).
    금액이 0보다 큰 슬롯만 `app_payments` 에 INSERT 되고, 이후 잔금·마진을 1회 재계산한다.
    모든 변경은 PaymentHistory에 합산(payments 배열 포함) 형태로 기록한다.
    """
    _BAL_MAX_SLOTS = 20
    _BAL_DEFAULT_SLOTS = 1

    _pay_done_key = f"_pay_done_{key_prefix}"
    if _pay_done_key in st.session_state:
        _pd = st.session_state.pop(_pay_done_key)
        st.success(f"✅ 결제 입력 완료! {_pd['amount']:,}원이 등록되었습니다.")

    _pay_date_key = f"{key_prefix}_pay_date"
    if _pay_date_key not in st.session_state:
        st.session_state[_pay_date_key] = default_payment_date or _today_kst()
    _slot_count_key = f"{key_prefix}_slot_count"
    if _slot_count_key not in st.session_state:
        st.session_state[_slot_count_key] = _BAL_DEFAULT_SLOTS

    def _slot_key(name: str, i: int) -> str:
        return f"{key_prefix}_{name}_{i}"

    # 슬롯 1 금액 기본값 = 잔금 (남은 슬롯은 0). 최초 진입 시 1회만 세팅.
    _slot0_amt_key = _slot_key("amt", 0)
    if _slot0_amt_key not in st.session_state:
        st.session_state[_slot0_amt_key] = _format_number_comma(str(int(balance))) if balance and balance > 0 else "0"

    st.caption("잔금 완납 처리 (결제 추가 · 복수 결제 가능)")
    st.date_input("결제 날짜 *", key=_pay_date_key)

    _add_col1, _add_col2 = st.columns([3, 1])
    with _add_col2:
        _disabled_add = st.session_state[_slot_count_key] >= _BAL_MAX_SLOTS
        if st.button("➕ 결제 수단 추가", disabled=_disabled_add, key=f"{key_prefix}_add_slot"):
            if st.session_state[_slot_count_key] < _BAL_MAX_SLOTS:
                st.session_state[_slot_count_key] += 1

    slot_count = int(st.session_state[_slot_count_key])
    slot_infos: list[dict] = []
    total_amt_int = 0
    for i in range(slot_count):
        m_key = _slot_key("method", i)
        c_key = _slot_key("card", i)
        a_key = _slot_key("amt", i)
        if a_key not in st.session_state:
            st.session_state[a_key] = "0"

        _r1, _r2, _r3 = st.columns([2, 2, 2])
        with _r1:
            method = st.selectbox(
                f"결제 수단 #{i+1}",
                options=PAYMENT_METHOD_OPTIONS,
                key=m_key,
            )
        with _r2:
            if method in _CARD_WITH_COMPANY:
                card_company = st.selectbox(f"카드사 #{i+1} *", options=CARD_COMPANY_OPTIONS, key=c_key)
            elif method == "메인페이":
                st.text_input(f"메인페이 승인번호 4자리 #{i+1} *", key=c_key, max_chars=4)
                card_company = st.session_state.get(c_key)
            elif method == "지역화폐":
                st.text_input(f"지역화폐 승인번호 #{i+1} *", key=c_key)
                card_company = st.session_state.get(c_key)
            else:
                card_company = None
        with _r3:
            st.text_input(
                f"결제 금액 #{i+1} *",
                key=a_key,
                on_change=lambda _k=a_key: st.session_state.__setitem__(
                    _k, _format_number_comma(st.session_state.get(_k, ""))
                ),
            )
        amt_int = _parse_comma_to_int(st.session_state.get(a_key, "0"))
        total_amt_int += amt_int

        # 온누리(전자) 식별자: 검증파일 구매자전화번호 뒤 4자리
        is_onnuri = method and ("온누리" in str(method)) and ("지류" not in str(method))
        last4_key = _slot_key("onnuri_last4", i)
        receipt_key = _slot_key("onnuri_receipt", i)
        if is_onnuri:
            st.text_input(
                f"온누리 전화번호 뒤 4자리 #{i+1} *",
                key=last4_key,
                max_chars=4,
                help="검증파일의 구매자전화번호 뒤 4자리",
            )
            _bal_last4 = re.sub(r"\D", "", str(st.session_state.get(last4_key, "") or ""))
            _bal_date = (
                st.session_state.get(_pay_date_key).isoformat()
                if hasattr(st.session_state.get(_pay_date_key), "isoformat")
                else _today_kst().isoformat()
            )
            _bal_form_hit = _onnuri_same_form_collides(
                this_index=i, last4=_bal_last4, amount=amt_int, slot_count=slot_count,
                last4_key_fn=lambda j, _sk=_slot_key: _sk("onnuri_last4", j),
                amt_key_fn=lambda j, _sk=_slot_key: _sk("amt", j),
                method_key_fn=lambda j, _sk=_slot_key: _sk("method", j),
            )
            _onnuri_time_input(
                _slot_key("onnuri_time", i),
                visible=_onnuri_should_ask_time(
                    db_filename, _bal_last4, amt_int, _bal_date, form_collides=_bal_form_hit,
                ),
                label=f"온누리 거래시간 #{i+1} *",
            )
            _file_input_with_paste(
                f"온누리상품권 영수증 사진(선택) #{i+1}",
                type=["png", "jpg", "jpeg", "webp"],
                accept_multiple_files=False,
                key=receipt_key,
            )

        slot_infos.append({
            "index": i,
            "method": method,
            "card_company": card_company,
            "amount": amt_int,
            "is_onnuri": bool(is_onnuri),
            "last4_key": last4_key,
        })

    _bal_after = float(balance) - float(total_amt_int)
    _mc1, _mc2 = st.columns(2)
    with _mc1:
        st.metric("이번 결제 합계", f"{total_amt_int:,}원")
    with _mc2:
        st.metric("등록 후 예상 잔금", f"{_bal_after:,.0f}원",
                  help="현재 잔금 - 이번 결제 합계. 음수면 초과결제로 등록됩니다.")

    if total_amt_int > 0 and total_amt_int > balance:
        _over = total_amt_int - max(balance, 0)
        st.warning(
            f"⚠️ 이번 결제 합계({total_amt_int:,}원)가 잔금({max(balance,0):,.0f}원)보다 "
            f"**{_over:,}원 초과**합니다. 결변·카드취소 처리 목적이면 그대로 등록하세요. "
            "초과 금액은 '초과결제 항목' 탭에 표시됩니다."
        )

    reason_key = f"{key_prefix}_reason"
    edit_reason = st.text_area("결제 메모(선택)", key=reason_key)

    if not st.button("결제 등록", key=f"{key_prefix}_btn"):
        return

    add_pay_date = st.session_state.get(_pay_date_key) or _today_kst()
    pay_date_str = add_pay_date.isoformat() if hasattr(add_pay_date, "isoformat") else _today_kst().isoformat()

    # 결제 금액이 있는 슬롯만 대상
    active = [s for s in slot_infos if int(s["amount"]) > 0]
    if not active:
        st.warning("금액을 입력하세요.")
        return

    # 슬롯별 필수값 검증 (매출 등록과 동일 수준)
    for s in active:
        method = s["method"] or ""
        idx1 = s["index"] + 1
        if method in _CARD_WITH_COMPANY:
            if not (str(s["card_company"] or "").strip()):
                st.error(f"결제 #{idx1} {method} 카드사를 선택하세요.")
                return
        elif method == "메인페이":
            _digits = re.sub(r"\D", "", str(s["card_company"] or ""))
            if len(_digits) != 4:
                st.error(f"결제 #{idx1} 메인페이 승인번호 4자리를 정확히 입력하세요.")
                return
        elif method == "지역화폐":
            _digits = re.sub(r"\D", "", str(s["card_company"] or ""))
            if len(_digits) == 0:
                st.error(f"결제 #{idx1} 지역화폐 승인번호를 입력하세요.")
                return

    onnuri_codes: dict[int, str | None] = {}
    for s in active:
        if not s["is_onnuri"]:
            onnuri_codes[s["index"]] = None
            continue
        idx1 = s["index"] + 1
        last4_raw = (st.session_state.get(s["last4_key"], "") or "").strip()
        last4_digits = re.sub(r"\D", "", last4_raw)
        _form_hit = _onnuri_same_form_collides(
            this_index=s["index"], last4=last4_digits, amount=int(s["amount"]),
            slot_count=slot_count,
            last4_key_fn=lambda j, _sk=_slot_key: _sk("onnuri_last4", j),
            amt_key_fn=lambda j, _sk=_slot_key: _sk("amt", j),
            method_key_fn=lambda j, _sk=_slot_key: _sk("method", j),
        )
        _need_t = _onnuri_should_ask_time(
            db_filename, last4_digits, int(s["amount"]), pay_date_str, form_collides=_form_hit,
        )
        _code, _err = _onnuri_compose_ident(
            last4_raw, st.session_state.get(_slot_key("onnuri_time", s["index"]), ""),
            require_time=_need_t,
        )
        if _err:
            st.error(f"결제 #{idx1}: {_err}")
            return
        onnuri_codes[s["index"]] = _code

    _seen_ulsan_add: set[str] = set()
    _seen_onnuri_add: set[tuple[str, int, str]] = set()
    for s in active:
        idx1 = s["index"] + 1
        method = s["method"] or ""
        amt = int(s["amount"])
        if method == "지역화폐":
            _appr = re.sub(r"\D", "", str(s.get("card_company") or ""))
            if _appr in _seen_ulsan_add:
                st.error(f"결제 #{idx1}: 같은 화면에 지역화폐 승인번호 {_appr} 가 중복됩니다.")
                return
            _ulsan_at = _ulsan_approval_already_used(db_filename, _appr)
            if _ulsan_at:
                st.error(
                    f"결제 #{idx1}: 지역화폐 승인번호 {_appr} 는 이미 등록된 결제입니다. "
                    f"(매장: {_ulsan_at}) 전 매장에서 같은 승인번호를 다시 입력할 수 없습니다."
                )
                return
            _seen_ulsan_add.add(_appr)
        elif s.get("is_onnuri"):
            _code = onnuri_codes.get(s["index"]) or ""
            _last4 = _onnuri_last4_from_code(_code)
            _tx_t = _onnuri_time_from_code(_code) or ""
            _okey = (_last4, amt, _tx_t)
            if _okey in _seen_onnuri_add:
                st.error(f"결제 #{idx1}: 같은 화면에 온누리 식별자 {_last4} / {amt:,}원이 중복됩니다.")
                return
            if _onnuri_ident_already_used(db_filename, _last4, amt, pay_date_str, tx_time=_tx_t or None):
                st.error(f"결제 #{idx1}: 온누리 {_last4} · {amt:,}원 · {pay_date_str} 결제가 이미 있습니다.")
                return
            _seen_onnuri_add.add(_okey)

    added_total = int(sum(int(s["amount"]) for s in active))
    slot_snapshots = [
        {"method": s["method"], "card_company": s["card_company"], "amount": int(s["amount"])}
        for s in active
    ]
    use_supabase_op = _supabase_orders_payments_available()

    if use_supabase_op:
        paid_total, _ = _sum_payments_by_order_supabase(db_filename, order_id)
        old_paid_total = paid_total
        new_paid_total = old_paid_total + added_total
        old_balance = balance
        new_balance = balance - added_total
        for s in active:
            fee = _payment_fee_amount(s["method"], int(s["amount"]))
            _insert_payment_supabase(db_filename, {
                "order_id": order_id,
                "payment_date": pay_date_str,
                "amount": int(s["amount"]),
                "payment_method": s["method"] or None,
                "card_company": s["card_company"],
                "fee_amount": fee,
                "onnuri_approval_code": onnuri_codes.get(s["index"]),
                "created_by": _current_username(),
            })
        _recalc_order_actual_margin_supabase(db_filename, order_id)
        customer_id_for_ph = _get_order_customer_id_supabase(db_filename, order_id)
        customer_name = _get_customer_name_supabase(db_filename, customer_id_for_ph) if customer_id_for_ph else ""
        _ph_err = _insert_payment_history(
            None, order_id, customer_name, "잔금결제",
            {"order_id": order_id, "balance_before": old_balance, "paid_total_before": old_paid_total},
            {
                "order_id": order_id,
                "added_amount": added_total,
                "payments": slot_snapshots,
                "balance_after": new_balance,
                "paid_total_after": new_paid_total,
            },
            edit_reason, db_filename=db_filename,
        )
        if _ph_err:
            st.warning(f"⚠️ 이력 저장 오류 (기능은 정상): {_ph_err}")
        conn = get_tenant_conn(db_filename)
        if conn:
            try:
                _insert_audit_log(conn, "Order", order_id, "payment_total", old_paid_total, new_paid_total, edit_reason)
                _insert_audit_log(conn, "Order", order_id, "balance_amount", old_balance, new_balance, edit_reason)
                conn.commit()
            finally:
                conn.close()
    else:
        conn = get_tenant_conn(db_filename)
        cur = conn.execute("SELECT COALESCE(SUM(amount),0) FROM Payments WHERE order_id = ?", (order_id,))
        old_paid_total = cur.fetchone()[0] or 0
        new_paid_total = old_paid_total + added_total
        old_balance = balance
        new_balance = balance - added_total
        for s in active:
            fee = _payment_fee_amount(s["method"], int(s["amount"]))
            conn.execute(
                """
                INSERT INTO Payments (order_id, payment_date, amount, payment_method, card_company, fee_amount, onnuri_approval_code, created_by, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, datetime('now', '+9 hours'))
                """,
                (
                    order_id, pay_date_str, int(s["amount"]),
                    s["method"] or None, s["card_company"], fee,
                    onnuri_codes.get(s["index"]), _current_username(),
                ),
            )
        _recalc_order_actual_margin(conn, order_id, db_filename)
        _insert_audit_log(conn, "Order", order_id, "payment_total", old_paid_total, new_paid_total, edit_reason)
        _insert_audit_log(conn, "Order", order_id, "balance_amount", old_balance, new_balance, edit_reason)
        cur_cid = conn.execute("SELECT customer_id FROM Orders WHERE id = ?", (order_id,)).fetchone()
        customer_id_for_ph = cur_cid[0] if cur_cid else None
        customer_name = _get_customer_name_supabase(db_filename, customer_id_for_ph) if customer_id_for_ph else ""
        _insert_payment_history(
            conn, order_id, customer_name, "잔금결제",
            {"order_id": order_id, "balance_before": old_balance, "paid_total_before": old_paid_total},
            {
                "order_id": order_id,
                "added_amount": added_total,
                "payments": slot_snapshots,
                "balance_after": new_balance,
                "paid_total_after": new_paid_total,
            },
            edit_reason, db_filename=db_filename,
        )
        conn.commit()
        conn.close()

    clear_data_cache()
    st.toast("등록되었습니다. 잔금이 0원이면 리스트에서 사라집니다.", icon="✅")
    st.session_state[_pay_done_key] = {"amount": added_total}
    # 다음 입력을 위해 이 프리픽스의 위젯 키를 정리
    _prefix_ = f"{key_prefix}_"
    for _k in list(st.session_state.keys()):
        if not isinstance(_k, str):
            continue
        if _k.startswith(_prefix_) and _k != _pay_done_key:
            try:
                del st.session_state[_k]
            except Exception:
                pass
    st.rerun()


def render_sales_kpi_dashboard() -> None:
    """9. 세일즈 퍼포먼스 KPI 대시보드."""
    st.title("세일즈 퍼포먼스 KPI")
    st.caption("리드 전환율, 매출 기여액, 사후관리 성실도 등 5대 KPI 지표를 추적합니다.")

    user = st.session_state.get("current_user") or {}
    role = user.get("role", "")
    employee_id = user.get("id")

    supa, supa_err = get_supabase_client()
    if supa_err or not supa:
        st.error("Supabase 연결이 필요합니다.")
        return

    # 보기 모드 선택
    col_view, col_period = st.columns(2)
    with col_view:
        view_mode = st.radio("보기", ["내 성과", "매장 전체"], horizontal=True)
    with col_period:
        period = st.selectbox("기간", ["이번 달", "최근 3개월", "전체"])

    # 기간 필터 계산
    from datetime import date, timedelta
    today = date.today()
    if period == "이번 달":
        date_from = today.replace(day=1).isoformat()
    elif period == "최근 3개월":
        date_from = (today - timedelta(days=90)).isoformat()
    else:
        date_from = "2000-01-01"

    try:
        query = supa.table("app_leads").select(
            "id,lead_source,lead_stage,assigned_employee_id,next_contact_date,"
            "followup_done,contact_memo,converted_at,revenue_amount,created_at"
        ).gte("created_at", date_from)

        if view_mode == "내 성과" and employee_id:
            query = query.eq("assigned_employee_id", employee_id)

        resp = query.execute()
        leads = resp.data or []
    except Exception as e:
        st.error(f"데이터 조회 실패: {e}")
        return

    if not leads:
        st.info("해당 기간에 등록된 리드가 없습니다.")
        return

    import pandas as pd

    df = pd.DataFrame(leads)
    total = len(df)

    # KPI 1: 리드 전환율
    converted = len(df[df["lead_stage"] == "4_계약완료"])
    conversion_rate = (converted / total * 100) if total > 0 else 0

    # KPI 2: 리드 매출 기여액
    revenue_total = df[df["lead_stage"] == "4_계약완료"]["revenue_amount"].fillna(0).sum()

    # KPI 3: 평균 클로징 기간
    converted_df = df[df["converted_at"].notna()].copy()
    avg_close_days = None
    if not converted_df.empty:
        try:
            converted_df["created_at_dt"] = pd.to_datetime(converted_df["created_at"], utc=True)
            converted_df["converted_at_dt"] = pd.to_datetime(converted_df["converted_at"], utc=True)
            converted_df["close_days"] = (
                converted_df["converted_at_dt"] - converted_df["created_at_dt"]
            ).dt.days
            avg_close_days = converted_df["close_days"].mean()
        except Exception:
            pass

    # KPI 4: 사후관리 성실도
    needs_followup = len(df[df["next_contact_date"].notna()])
    done_followup = len(df[(df["followup_done"] == True) & (df["contact_memo"].notna())])
    followup_rate = (done_followup / needs_followup * 100) if needs_followup > 0 else 0

    # KPI 5: DB 획득률 (오프라인 전용)
    offline_count = len(df[df["lead_source"] == "오프라인_방문"])

    # 지표 카드 표시
    st.divider()
    k1, k2, k3 = st.columns(3)
    with k1:
        st.metric("리드 전환율", f"{conversion_rate:.1f}%", help=f"계약완료 {converted}건 / 전체 {total}건")
    with k2:
        st.metric("리드 매출 기여액", f"{int(revenue_total):,}원", help="담당 리드 중 계약완료된 건의 합계")
    with k3:
        st.metric(
            "평균 클로징 기간",
            f"{avg_close_days:.1f}일" if avg_close_days is not None else "-",
            help="첫 접촉 → 계약 완료까지 평균 일수",
        )

    k4, k5, k6 = st.columns(3)
    with k4:
        st.metric("사후관리 성실도", f"{followup_rate:.1f}%", help=f"기한 내 Follow-up 완료 {done_followup}건 / 필요 {needs_followup}건")
    with k5:
        st.metric("오프라인 리드 등록", f"{offline_count}건", help="오프라인 방문으로 등록된 리드 수")
    with k6:
        st.metric("전체 리드", f"{total}건")

    # 진행 바 (목표 대비)
    st.divider()
    st.subheader("목표 달성률")
    target_conversion = 40.0
    target_followup = 80.0

    prog1, prog2 = st.columns(2)
    with prog1:
        st.write(f"**전환율** {conversion_rate:.1f}% / 목표 {target_conversion}%")
        st.progress(min(conversion_rate / target_conversion, 1.0))
    with prog2:
        st.write(f"**사후관리** {followup_rate:.1f}% / 목표 {target_followup}%")
        st.progress(min(followup_rate / target_followup, 1.0))

    # 리드 목록
    st.divider()
    st.subheader("리드 목록")

    stage_filter = st.multiselect(
        "단계 필터",
        ["1_신규", "2_상담중", "3_견적발송", "4_계약완료", "5_실패", "6_보류"],
        default=["1_신규", "2_상담중", "3_견적발송"],
    )
    if stage_filter:
        display_df = df[df["lead_stage"].isin(stage_filter)].copy()
    else:
        display_df = df.copy()

    rename_map = {
        "lead_source": "유입 경로", "lead_stage": "단계",
        "next_contact_date": "다음 연락", "followup_done": "사후관리",
        "revenue_amount": "계약금액", "created_at": "등록일",
    }
    display_df = display_df.rename(columns={k: v for k, v in rename_map.items() if k in display_df.columns})
    show_cols = [c for c in ["등록일", "유입 경로", "단계", "계약금액", "다음 연락", "사후관리"] if c in display_df.columns]
    if "등록일" in display_df.columns:
        display_df["등록일"] = display_df["등록일"].str[:10]
    st.dataframe(display_df[show_cols] if show_cols else display_df, width="stretch", hide_index=True)


def _render_chat_history_section(customer_id: int, phone: str, customer_name: str) -> None:
    """
    고객 상세 화면 내 상담 이력 섹션.
    app_chat_history(모든 채널 이력)와 app_leads(리드 정보)를 통합 표시.
    직원이 전화 통화/오프라인 메모를 직접 추가할 수도 있다.
    """
    try:
        from lead_manager import get_chat_history, get_leads_by_phone, save_chat_history
    except ImportError:
        st.warning("lead_manager 모듈을 찾을 수 없습니다.")
        return

    CHANNEL_ICONS = {
        "채널톡_웹챗": "🔵",
        "카카오톡": "🟡",
        "오프라인_메모": "🟢",
        "전화_통화": "⚪",
    }

    # 상담 이력 로드
    histories = get_chat_history(phone, limit=20)
    leads = get_leads_by_phone(phone)

    # 리드 단계 표시
    if leads:
        lead = leads[0]
        stage_colors = {
            "4_계약완료": "🟢", "5_실패": "🔴",
            "3_견적발송": "🔵", "2_상담중": "🟡", "1_신규": "⚪", "6_보류": "⚫",
        }
        _stage_labels = {
            "1_신규": "신규", "2_상담중": "상담중", "3_견적발송": "견적발송",
            "4_계약완료": "계약완료", "5_실패": "실패", "6_보류": "보류",
        }
        icon = stage_colors.get(lead.get("lead_stage", ""), "⚪")
        st.info(
            f"{icon} **리드 단계:** {_stage_labels.get(lead.get('lead_stage', ''), lead.get('lead_stage', '-'))} | "
            f"**유입:** {lead.get('lead_source', '-')} | "
            f"**다음 연락:** {lead.get('next_contact_date') or '-'}"
        )

    col_left, col_right = st.columns([3, 1])
    with col_right:
        st.caption(f"총 {len(histories)}건")

    if not histories:
        st.caption("상담 이력이 없습니다.")
    else:
        for i, rec in enumerate(histories):
            channel = rec.get("channel", "")
            icon = CHANNEL_ICONS.get(channel, "📋")
            date_str = str(rec.get("created_at", ""))[:10]
            handled = rec.get("handled_by") or "시스템"
            summary = rec.get("summary") or "(내용 없음)"
            full_text = rec.get("full_text") or ""

            with st.container():
                st.markdown(
                    f"{icon} **{date_str}** &nbsp; `{channel}` &nbsp; 담당: {handled}"
                )
                st.write(summary[:100] + ("..." if len(summary) > 100 else ""))
                if full_text and len(full_text) > len(summary):
                    with st.expander("전체 대화 보기"):
                        st.text(full_text)
            if i < len(histories) - 1:
                st.divider()

    # 메모 직접 추가
    st.markdown("---")
    with st.expander("+ 상담 메모 추가 (전화 통화 / 오프라인 메모)"):
        _user = st.session_state.get("current_user") or {}
        col_ch, col_memo = st.columns([1, 3])
        with col_ch:
            add_channel = st.selectbox(
                "채널",
                ["전화_통화", "오프라인_메모", "카카오톡"],
                key=f"chat_hist_ch_{customer_id}",
            )
        with col_memo:
            add_memo = st.text_area(
                "상담 내용",
                key=f"chat_hist_memo_{customer_id}",
                height=80,
                placeholder="예: 가격 재문의, 이번 주 방문 예정",
            )
        if st.button("메모 저장", key=f"chat_hist_save_{customer_id}", type="primary"):
            if not add_memo.strip():
                st.error("내용을 입력해 주세요.")
            else:
                ok = save_chat_history(
                    phone=phone,
                    channel=add_channel,
                    summary=add_memo.strip(),
                    handled_by=str(_user.get("username") or ""),
                )
                if ok:
                    st.success("저장되었습니다.")
                    st.rerun()
                else:
                    st.error("저장에 실패했습니다. Supabase 연결을 확인하세요.")


def _render_legacy_purchase_bulk_import(db_filename: str) -> None:
    """매입 원장(엑셀) 통합 임포트 UI.

    - 매입 원장 = 주문 헤더(고객·계약일·판매자) + 라인 아이템(품명·품번·수량·출고가) 통합 문서.
    - 그룹핑 키: (phone1_digits, 등록일, 출고번호) 3튜플 = 1개 매출 주문.
    - 앱에 이미 등록된 주문과 (고객, 등록일) 로 자동 매칭. 후보 다수면 사용자가 수동 선택.
    - 회수 라인은 스킵, 매장분은 일반 주문과 동일 처리.
    - `import_source='엑셀_매입원장'` 태그 및 새 `app_order_items` 테이블에 라인 저장.
    """
    try:
        import legacy_purchase_import_service as lps
    except Exception:
        return

    with st.expander("📦 매입 원장 통합 임포트 (주문 + 라인 아이템)"):
        st.caption(
            "매입 원장 엑셀 하나로 **고객 · 매출 주문 · 라인 아이템** 을 한 번에 저장합니다. "
            "\n\n**필수 컬럼**: 등록일 · 고객명 · 전화1 · 품명 · 출고가"
            "\n\n**옵션 컬럼**: 출고번호 · 배송일 · 판매자(대) · 전화2 · 주소1 · 주소2 · 주문구분 · 수량 · 부가세 · 합계 · 품번 · 품목비고"
            "\n\n**식별 규칙**: 전화1 이 있으면 전화 기반으로 매칭·통합, "
            "전화1 이 비어있으면 **고객명 기반** (예: 매장 전시 라인, 고객명이 매장명으로 표기) 으로 별도 신규 고객이 생성됩니다."
            "\n\n**그룹핑 규칙**: `출고번호` 컬럼이 있으면 `(식별, 등록일, 출고번호)` 3튜플, "
            "없으면 `(식별, 등록일)` 2튜플로 하나의 매출 주문을 묶습니다. "
            "\n\n**매칭 규칙**: 앱에 이미 등록된 주문은 `(고객, 등록일)` 후보가 "
            "**1건이면 자동 매칭**, 2건 이상이면 아래에서 **수동 선택** 합니다. "
            "**회수** 주문구분 라인은 자동 스킵됩니다. "
            "\n\n**잔금 처리**: 신규 주문(모모에 없던 건)은 **판매가 전액 완납 결제**로 저장되어 미수 목록에 잡히지 않습니다. "
            "**2026년 4월 이전** 매입원장 임포트 매출은 전부 **입금완료**로 간주하며 미수금에 포함하지 않습니다. "
            "이미 앱에 등록된 주문에 매칭될 때는 **판매금액·원가·잔금·기존 결제**를 절대 덮어쓰지 않고 **라인 아이템만 추가**합니다."
            "\n\n**사전 준비**: `app_order_items` 테이블이 필요합니다 — `SUPABASE_APP_ORDER_ITEMS.sql` 을 먼저 실행하세요."
        )
        _store_name = _get_current_store_name_for_customers(db_filename)
        if not _store_name:
            st.error("현재 매장 정보를 확인할 수 없습니다. 사이드바에서 매장을 먼저 선택해 주세요.")
            return
        st.info(f"저장 대상 매장: **{_store_name}** (`{db_filename}`)")

        st.markdown("##### 2026년 4월 이전 임포트 매출 → 입금완료 보정")
        st.caption(
            "이미 임포트된 주문 중 `엑셀_매입원장` 이고 계약일이 **2026-04-01 이전**인 건은 "
            "결제가 없어도 미수로 잡지 않습니다. 아래 버튼은 누락된 완납 결제를 채워 "
            "미수금 레포트·대시보드 숫자가 일치하게 합니다. 일반(모모) 주문은 변경하지 않습니다."
        )
        if st.button("💳 2026년 4월 이전 임포트 매출 입금완료 처리", key=f"legacy_import_paid_backfill::{db_filename}"):
            client, _err = get_supabase_client()
            if not client:
                st.error(f"Supabase 연결 실패: {_err}")
            else:
                _pbar = st.progress(0.0, text="보정 중…")
                def _paid_cb(_label: str, _frac: float) -> None:
                    _pbar.progress(min(1.0, float(_frac)), text=_label)
                _created_by = (
                    (st.session_state.get("current_user") or {}).get("name")
                    or (st.session_state.get("current_user") or {}).get("username")
                    or "legacy_import_paid_backfill"
                )
                _bres = lps.backfill_legacy_import_paid(
                    client, db_filename=db_filename, created_by=_created_by, progress_cb=_paid_cb,
                )
                _pbar.progress(1.0, text="완료")
                clear_data_cache()
                st.success(
                    f"대상 {_bres.scanned:,}건 조회 · 완납 결제 {_bres.payments_inserted:,}건 추가 · "
                    f"완납 상태 {_bres.status_updated:,}건 갱신 · 이미 완납 {_bres.skipped_already_paid:,}건"
                )
                for _em in _bres.errors[:10]:
                    st.warning(_em)

        excel_upload = st.file_uploader(
            "매입 원장 엑셀 (.xlsx)", type=["xlsx"], key="legacy_purchase_excel_upload",
            help="첫번째 시트가 사용됩니다. 헤더는 2행, 3행 TOTAL 요약행은 자동 제거됩니다.",
        )
        if excel_upload is None:
            return

        _cache_key = f"legacy_purchase_df::{excel_upload.name}::{excel_upload.size}"
        if _cache_key not in st.session_state:
            try:
                st.session_state[_cache_key] = lps.parse_excel(excel_upload.getvalue())
            except Exception as _e:
                st.error(f"엑셀 파일을 읽을 수 없습니다: {_e}")
                return
        df_raw = st.session_state[_cache_key]
        if df_raw is None or df_raw.empty:
            st.warning("엑셀에 데이터 행이 없습니다.")
            return

        st.markdown(f"**총 {len(df_raw):,}행** · 컬럼 {len(df_raw.columns)}개")
        with st.expander("원본 미리보기 (앞 10행)", expanded=False):
            st.dataframe(df_raw.head(10), width="stretch", hide_index=True)

        st.markdown("#### 1. 컬럼 매핑")
        st.caption("자동 제안값을 확인하고 필요 시 수정하세요. `-` 는 해당 필드를 비웁니다.")
        _cols_options = ["-"] + list(df_raw.columns)
        _suggested = lps.auto_suggest_mapping(list(df_raw.columns))
        mapping: dict[str, str] = {}
        _map_cols = st.columns(3)
        for _idx, (fkey, flabel, freq) in enumerate(lps.PURCHASE_TARGET_FIELDS):
            with _map_cols[_idx % 3]:
                default = _suggested.get(fkey, "-")
                sel = st.selectbox(
                    f"{flabel}" + (" *" if freq else ""),
                    _cols_options,
                    index=_cols_options.index(default) if default in _cols_options else 0,
                    key=f"legacy_purchase_map::{fkey}::{excel_upload.name}",
                )
                if sel != "-":
                    mapping[fkey] = sel

        st.markdown("#### 2. 임포트 옵션")
        _c1, _c2 = st.columns([1, 2])
        with _c1:
            margin_pct = st.number_input(
                "마진율 (%) — 판매가 기준",
                min_value=0.0, max_value=95.0, value=20.0, step=1.0,
                help="판매가 = 출고가 / (1 - 마진율). 기본 20% → 출고가/0.8 = 출고가×1.25",
                key=f"legacy_purchase_margin::{excel_upload.name}",
            )
        with _c2:
            st.caption("**주문구분 필터**: 회수 라인은 자동 스킵됩니다. 그 외(주문·매장분·기타) 는 모두 포함됩니다.")

        _missing_required = [flabel for fkey, flabel, freq in lps.PURCHASE_TARGET_FIELDS if freq and fkey not in mapping]
        if _missing_required:
            st.error(f"필수 매핑 누락: {', '.join(_missing_required)}")
            return

        st.markdown("#### 2-1. 주소만 보완 (선택 · 이미 임포트된 고객용)")
        st.caption(
            "**이미 앱에 등록된 고객 중 주소가 비어있는 경우만** 이 엑셀의 주소로 채웁니다. "
            "주문·결제·라인 아이템은 전혀 조회·수정하지 않으며, 이미 주소가 있으면 절대 덮어쓰지 않습니다. "
            "'이미 임포트됨' 으로 스킵되는 데이터에도 동일하게 적용되므로, 과거에 주소 없이 임포트된 엑셀을 "
            "그대로 재업로드해서 주소만 보완할 수 있습니다."
        )
        if st.button("🏠 주소만 보완 실행", key=f"legacy_purchase_addr_backfill_btn::{excel_upload.name}"):
            client, err = get_supabase_client()
            if err or not client:
                st.error(f"Supabase 연결 실패: {err}")
            else:
                with st.spinner(f"주소 보완 중… ({len(df_raw):,}행)"):
                    _addr_groups, _ = lps.group_orders(df_raw, mapping)
                    addr_result = lps.backfill_customer_addresses(
                        client, _addr_groups, store_name=_store_name,
                    )
                clear_data_cache()
                _a1, _a2, _a3, _a4 = st.columns(4)
                _a1.metric("엑셀 고유 고객수", f"{addr_result.scanned_customers:,}")
                _a2.metric("기존 고객 매칭", f"{addr_result.matched_existing:,}")
                _a3.metric("주소 보완됨", f"{addr_result.address_filled:,}")
                _a4.metric("이미 주소 있음", f"{addr_result.already_had_address:,}")
                if addr_result.errors:
                    for _e in addr_result.errors[:5]:
                        st.warning(_e)
                else:
                    st.success(
                        f"주소 보완 완료 · {addr_result.address_filled}건 채움 "
                        f"(기존 값 있던 {addr_result.already_had_address}건 보존 · "
                        f"매칭 안 됨 {addr_result.not_matched}건 · 엑셀에 주소 없음 {addr_result.no_address_in_excel}건)."
                    )

        st.markdown("#### 3. 미리보기 (dry-run)")
        if st.button("🔍 미리보기 생성", key=f"legacy_purchase_preview_btn::{excel_upload.name}", type="primary"):
            client, err = get_supabase_client()
            if err or not client:
                st.error(f"Supabase 연결 실패: {err}")
                return
            with st.spinner(f"그룹핑 및 매칭 계산 중… ({len(df_raw):,}행)"):
                groups, gstats = lps.group_orders(df_raw, mapping, margin_rate=margin_pct / 100.0)
                preview = lps.build_preview(
                    client, groups,
                    store_name=_store_name,
                    db_filename=db_filename,
                )
                preview.skipped_return = gstats["skipped_return"]
                preview.skipped_invalid = gstats["skipped_invalid"]
                preview.total_lines = gstats["total_lines"]
            # 채널톡 스캔 (읽기 전용)
            phones_set = {g.phone1_digits for g in groups if g.phone1_digits}
            with st.spinner("채널톡_자동가입 매장 스캔 중…"):
                ct_scan = lps.migrate_channeltalk_phones(client, _store_name, phones_set, dry_run=True)
            st.session_state[f"legacy_purchase_preview::{excel_upload.name}"] = preview
            st.session_state[f"legacy_purchase_ct_scan::{excel_upload.name}"] = ct_scan
            st.session_state[f"legacy_purchase_margin_pct::{excel_upload.name}"] = margin_pct

        preview = st.session_state.get(f"legacy_purchase_preview::{excel_upload.name}")
        if not preview:
            st.info("'미리보기 생성' 을 눌러 임포트 결과를 먼저 확인해 주세요.")
            return

        _s1, _s2, _s3, _s4 = st.columns(4)
        _s1.metric("총 라인 수", f"{preview.total_lines:,}")
        _s2.metric("주문 그룹 (headers)", f"{preview.group_count:,}")
        _s3.metric("회수 스킵 (라인)", f"{preview.skipped_return:,}")
        _s4.metric("파싱 오류 (라인)", f"{preview.skipped_invalid:,}")

        _s5, _s6, _s7, _s8 = st.columns(4)
        _s5.metric("신규 고객", f"{preview.new_customer_count:,}")
        _s6.metric("기존 고객 매칭", f"{preview.matched_customer_count:,}")
        _s7.metric("총 매입금액 합", f"{preview.total_cost_amount:,}원")
        _s8.metric("총 판매가(역산) 합", f"{preview.total_sale_amount:,}원")

        _r1, _r2, _r3, _r4 = st.columns(4)
        _r1.metric("신규 주문 생성", f"{preview.to_create_count:,}")
        _r2.metric("자동 매칭 (attach)", f"{preview.to_attach_count:,}")
        _r3.metric("수동 선택 필요", f"{preview.unresolved_count:,}")
        _r4.metric("이미 임포트 (스킵)", f"{preview.invalid_count:,}")

        if preview.yearly_stats:
            st.caption("연도별 분포")
            _y_df = pd.DataFrame(preview.yearly_stats)
            _y_df["sales"] = _y_df["sales"].map(lambda v: f"{int(v):,}원")
            _y_df["cost"] = _y_df["cost"].map(lambda v: f"{int(v):,}원")
            _y_df = _y_df.rename(columns={"year": "연도", "count": "주문건수", "sales": "판매가 합", "cost": "매입금액 합"})
            st.dataframe(_y_df, width="content", hide_index=True)

        ct_scan = st.session_state.get(f"legacy_purchase_ct_scan::{excel_upload.name}")
        if ct_scan and (ct_scan.scanned > 0 or ct_scan.errors):
            _would_migrate = max(0, ct_scan.scanned - ct_scan.already_in_target)
            st.markdown("#### 3-1. 채널톡_자동가입 매장 phone 이관")
            _cc1, _cc2, _cc3 = st.columns(3)
            _cc1.metric("스캔한 채널톡 phone", f"{ct_scan.scanned:,}")
            _cc2.metric("대상 매장에 이미 존재", f"{ct_scan.already_in_target:,}")
            _cc3.metric("이관 예정 (dry-run)", f"{_would_migrate:,}")
            if _would_migrate > 0:
                st.caption(
                    f"채널톡 매장에서 대상 매장으로 {_would_migrate}건을 이관하면 매칭율이 개선될 수 있습니다. "
                    "임포트 확정 시 자동 이관을 원하면 아래 체크박스를 켜세요."
                )
            if ct_scan.errors:
                for _e in ct_scan.errors[:3]:
                    st.warning(_e)

        with st.expander(f"주문 그룹 미리보기 (최대 500건, 총 {preview.group_count:,}건)", expanded=False):
            st.dataframe(lps.preview_to_dataframe(preview, max_rows=500), width="stretch", hide_index=True)

        st.markdown("#### 3-0. 입력원가 vs 본사원가")
        st.caption("이미 입력된 판매가는 역산하지 않습니다. 헤더 원가·판매가는 바꾸지 않습니다.")
        try:
            import import_cost_reconcile as _icr
            _rec = _icr.build_reconcile_from_preview(preview, getattr(preview, "orders_by_cid", {}) or {})
            st.session_state[f"legacy_purchase_reconcile::{excel_upload.name}"] = _rec
            _b1, _b2, _b3, _b4 = st.columns(4)
            _b1.metric("원가 불일치", f"{_rec.mismatch:,}건")
            _b2.metric("원가 미입력", f"{_rec.blank:,}건")
            _b3.metric("본사만 있음", f"{_rec.hq_only:,}건")
            _b4.metric("앱만 있음", f"{_rec.app_only:,}건")
            _rec_df = _icr.reconcile_dataframe(_rec)
            if not _rec_df.empty:
                st.dataframe(
                    _rec_df,
                    width="stretch",
                    hide_index=True,
                    key=f"legacy_purchase_rec_df::{excel_upload.name}",
                    column_config={
                        "입력원가": st.column_config.NumberColumn("입력원가", format="%,.0f"),
                        "본사원가": st.column_config.NumberColumn("본사원가", format="%,.0f"),
                        "원가차이": st.column_config.NumberColumn("원가차이", format="%,.0f"),
                        "입력판매가": st.column_config.NumberColumn("입력판매가", format="%,.0f"),
                    },
                )
            _role = (st.session_state.get("current_user") or {}).get("role", "")
            _gkey = ""
            try:
                _gkey = str((st.secrets.get("gemini") or {}).get("api_key") or "") or os.environ.get("GEMINI_API_KEY", "")
            except Exception:
                _gkey = os.environ.get("GEMINI_API_KEY", "")
            if _role in ("store_admin", "superadmin"):
                _g_disabled = not bool(_gkey.strip())
                if st.button(
                    "Gemini 분할·이상 제안",
                    key=f"legacy_purchase_gemini::{excel_upload.name}",
                    disabled=_g_disabled,
                    help="확인한 묶음만 합산합니다. 키가 없으면 비활성.",
                ):
                    sc_g, _ = get_supabase_client()
                    _fb = _icr.load_ai_feedback(sc_g, db_filename) if sc_g else []
                    with st.spinner("Gemini 제안 생성 중..."):
                        _sug = _icr.suggest_with_gemini(
                            api_key=_gkey,
                            reconcile=_rec,
                            preview_groups=preview.groups,
                            feedback=_fb,
                        )
                    st.session_state[f"legacy_purchase_gemini_sug::{excel_upload.name}"] = _sug
                _sug = st.session_state.get(f"legacy_purchase_gemini_sug::{excel_upload.name}")
                if _sug:
                    if _sug.get("error"):
                        st.warning(f"Gemini: {_sug.get('error')}")
                    _merges = _sug.get("merges") or []
                    _flags = _sug.get("fraud_flags") or []
                    if _merges:
                        st.caption("분할 주문 묶음 제안 (확인 시에만 합산 비교)")
                        for _mi, _mg in enumerate(_merges[:20]):
                            _oids = _mg.get("order_ids") or []
                            _lab = f"주문 { _oids } · {_mg.get('reason') or ''} (신뢰 {_mg.get('confidence')})"
                            _c1, _c2 = st.columns([3, 1])
                            with _c1:
                                st.write(_lab)
                            with _c2:
                                if st.button("확인", key=f"ai_merge_ok::{excel_upload.name}::{_mi}"):
                                    sc_g, _ = get_supabase_client()
                                    _who = (st.session_state.get("current_user") or {}).get("username") or ""
                                    if sc_g:
                                        _icr.save_ai_feedback(sc_g, db_filename, "merge", _mg, "accepted", _who)
                                    _acc = st.session_state.setdefault(
                                        f"legacy_purchase_ai_merges::{excel_upload.name}", []
                                    )
                                    _acc.append(_mg)
                                    st.rerun()
                                if st.button("거절", key=f"ai_merge_no::{excel_upload.name}::{_mi}"):
                                    sc_g, _ = get_supabase_client()
                                    _who = (st.session_state.get("current_user") or {}).get("username") or ""
                                    if sc_g:
                                        _icr.save_ai_feedback(sc_g, db_filename, "merge", _mg, "rejected", _who)
                                    st.rerun()
                    if _flags:
                        st.caption("부정·이상 의심 (검토용, 확정 아님)")
                        for _fi, _fl in enumerate(_flags[:20]):
                            st.write(f"- {_fl.get('type')} · 주문 {_fl.get('order_id')} · {_fl.get('reason')}")
                            _fc1, _fc2 = st.columns(2)
                            with _fc1:
                                if st.button("확인(검토)", key=f"ai_fr_ok::{excel_upload.name}::{_fi}"):
                                    sc_g, _ = get_supabase_client()
                                    _who = (st.session_state.get("current_user") or {}).get("username") or ""
                                    if sc_g:
                                        _icr.save_ai_feedback(sc_g, db_filename, "fraud", _fl, "accepted", _who)
                                    st.rerun()
                            with _fc2:
                                if st.button("거절", key=f"ai_fr_no::{excel_upload.name}::{_fi}"):
                                    sc_g, _ = get_supabase_client()
                                    _who = (st.session_state.get("current_user") or {}).get("username") or ""
                                    if sc_g:
                                        _icr.save_ai_feedback(sc_g, db_filename, "fraud", _fl, "rejected", _who)
                                    st.rerun()
                    _acc_m = st.session_state.get(f"legacy_purchase_ai_merges::{excel_upload.name}") or []
                    if _acc_m:
                        _merged_rows = _icr.apply_confirmed_merges(_rec.rows, _acc_m)
                        st.caption("확인된 AI 묶음 반영 비교")
                        st.dataframe(
                            _icr.reconcile_dataframe(_icr.ReconcileResult(rows=_merged_rows)),
                            width="stretch",
                            hide_index=True,
                            key=f"legacy_purchase_ai_merged_df::{excel_upload.name}",
                        )
        except Exception as _rec_e:
            st.caption(f"원가 대사 표를 만들지 못했습니다: {_rec_e}")

        # ── unresolved 그룹 수동 매핑 ──
        if preview.unresolved_count > 0:
            st.markdown("#### 3-2. 수동 매칭 필요 그룹")
            st.caption(
                f"동일 (고객, 등록일) 에 앱 주문이 2건 이상 존재하는 그룹입니다 ({preview.unresolved_count}건). "
                "각 그룹에 대해 후보 중 하나를 선택하거나, '신규 주문으로 등록'을 선택할 수 있습니다."
            )
            _unresolved = [g for g in preview.groups if g.match_status == "unresolved"]
            _decisions_key = f"legacy_purchase_decisions::{excel_upload.name}"
            _decisions: dict[str, str] = st.session_state.get(_decisions_key, {})
            for _ug in _unresolved[:100]:  # UI 부하 방지: 최대 100건 노출
                gk = f"{_ug.phone1_digits}::{_ug.order_date}::{_ug.ship_number}"
                _label_hdr = f"{_ug.customer_name} · {_ug.order_date} · 출고#{_ug.ship_number} · {len(_ug.items)}라인 · 매입 {_ug.total_line_cost:,}원"
                _options = ["(신규 주문으로 등록)"]
                _option_ids = [None]
                for meta in _ug.candidate_orders_meta:
                    _dd = str(meta.get("delivery_date") or "-")[:10]
                    _tot = int(meta.get("total_amount") or 0)
                    _cat = str(meta.get("category") or "-")
                    _options.append(f"#{meta.get('id')} · {_cat[:20]} · 배송 {_dd} · 판매 {_tot:,}원")
                    _option_ids.append(meta.get("id"))
                _prev = _decisions.get(gk)
                _default_idx = 0
                if _prev is not None:
                    try:
                        _default_idx = _option_ids.index(int(_prev)) if _prev != "new" else 0
                    except ValueError:
                        _default_idx = 0
                _sel_idx = st.selectbox(
                    _label_hdr, list(range(len(_options))),
                    format_func=lambda i, _opts=_options: _opts[i],
                    index=_default_idx,
                    key=f"legacy_purchase_decision::{gk}::{excel_upload.name}",
                )
                _chosen = _option_ids[_sel_idx]
                _decisions[gk] = "new" if _chosen is None else str(_chosen)
            st.session_state[_decisions_key] = _decisions
            if len(_unresolved) > 100:
                st.warning(f"목록이 길어 앞 100건만 UI에 노출됩니다. 나머지 {len(_unresolved) - 100}건은 임포트 시 자동으로 '신규 주문' 처리됩니다.")

        st.markdown("#### 4. 임포트 확정")
        _total_committable = preview.to_create_count + preview.to_attach_count
        if preview.unresolved_count > 0:
            _decisions = st.session_state.get(f"legacy_purchase_decisions::{excel_upload.name}", {})
            _resolved = sum(1 for _v in _decisions.values() if _v)
            _total_committable += _resolved
        if _total_committable == 0:
            st.warning(
                "임포트할 유효 그룹이 없습니다. "
                "이미 같은 전화·등록일로 임포트된 경우 **아래 '매입 원장 임포트 롤백'** 에서 "
                "해당 연도를 삭제한 뒤 다시 올려 주세요."
            )
            return

        _ct_do_migrate = False
        if ct_scan and (ct_scan.scanned - ct_scan.already_in_target) > 0:
            _ct_do_migrate = st.checkbox(
                f"채널톡_자동가입 매장의 phone1 을 [{_store_name}] 매장으로 자동 이관 (이관 예정 최대 {ct_scan.scanned - ct_scan.already_in_target}건)",
                value=True,
                key=f"legacy_purchase_ct_migrate::{excel_upload.name}",
            )

        _confirm = st.checkbox(
            f"위 결과대로 매장 [{_store_name}] 에 저장하겠습니다.",
            key=f"legacy_purchase_confirm::{excel_upload.name}",
        )
        if _confirm and st.button("✅ 임포트 실행", key=f"legacy_purchase_commit_btn::{excel_upload.name}", type="primary"):
            client, err = get_supabase_client()
            if err or not client:
                st.error(f"Supabase 연결 실패: {err}")
                return

            # unresolved 결정 반영
            _decisions = st.session_state.get(f"legacy_purchase_decisions::{excel_upload.name}", {})
            for g in preview.groups:
                if g.match_status != "unresolved":
                    continue
                gk = f"{g.phone1_digits}::{g.order_date}::{g.ship_number}"
                dec = _decisions.get(gk)
                if dec and dec != "new":
                    try:
                        _cid = int(dec)
                        if _cid in g.candidate_order_ids:
                            g.match_status = "to_attach"
                            g.chosen_order_id = _cid
                            continue
                    except ValueError:
                        pass
                # 기본값: 신규 주문
                g.match_status = "to_create"

            # 카운터 재계산 (표시용, 실제로는 commit_import 이 다시 계산)
            preview.to_create_count = sum(1 for g in preview.groups if g.match_status == "to_create")
            preview.to_attach_count = sum(1 for g in preview.groups if g.match_status == "to_attach")
            preview.unresolved_count = 0

            _current_user = st.session_state.get("current_user") or {}
            _created_by = _current_user.get("name") or _current_user.get("username") or "legacy_purchase_import"
            _progress = st.progress(0.0, text="시작 중…")
            def _cb(stage: str, pct: float) -> None:
                try:
                    _progress.progress(min(1.0, max(0.0, pct)), text=f"{stage} {int(pct * 100)}%")
                except Exception:
                    pass

            # (선택) 채널톡 이관 먼저 실행
            if _ct_do_migrate:
                phones_set = {g.phone1_digits for g in preview.groups if g.phone1_digits and g.match_status in ("to_create", "to_attach")}
                with st.spinner("채널톡_자동가입 매장 phone 이관 중…"):
                    mg = lps.migrate_channeltalk_phones(client, _store_name, phones_set, dry_run=False)
                st.caption(f"채널톡 이관 완료: {mg.migrated}건 이관 / {mg.already_in_target}건 이미 존재.")
                if mg.errors:
                    for _e in mg.errors[:3]:
                        st.warning(_e)
                # 이관 후 identity map 재로드 → to_create 그룹의 existing_customer_id 재매핑
                if mg.migrated > 0:
                    _refreshed = lps.load_existing_customer_identity_map(client, _store_name)
                    for g in preview.groups:
                        if g.match_status in ("to_create",) and (g.existing_customer_id is None or g.existing_customer_id < 0):
                            _cid = _refreshed.get(g.identity_key)
                            if _cid is not None:
                                g.existing_customer_id = int(_cid)

            with st.spinner("DB 저장 중…"):
                result = lps.commit_import(
                    client, preview,
                    store_name=_store_name,
                    db_filename=db_filename,
                    created_by=_created_by,
                    progress_cb=_cb,
                )
            _progress.progress(1.0, text="완료")
            clear_data_cache()

            _rr1, _rr2, _rr3, _rr4, _rr5 = st.columns(5)
            _rr1.metric("신규 고객 등록", f"{result.customers_inserted:,}")
            _rr2.metric("신규 주문 등록", f"{result.orders_inserted:,}")
            _rr3.metric("완납 결제 저장", f"{result.payments_inserted:,}")
            _rr4.metric("라인 아이템 저장", f"{result.items_inserted:,}")
            _rr5.metric("기존고객 주소 보완", f"{result.customers_address_filled:,}")
            if result.failed_orders or result.failed_payments or result.failed_items or result.errors:
                st.warning(
                    f"실패: 주문 {result.failed_orders}건 / 결제 {result.failed_payments}건 / 라인 {result.failed_items}건. "
                    f"스킵: 수동미결정 {result.groups_unresolved_skipped}건 / 무효 {result.groups_invalid_skipped}건."
                )
                for _msg in result.errors[:10]:
                    st.error(_msg)
            else:
                st.success(
                    f"임포트 완료 · 고객 {result.customers_inserted}건 · 신규주문 {result.orders_inserted}건 · "
                    f"라인 {result.items_inserted}건 (기존주문 attach {result.items_attached_existing}건 포함) · "
                    f"기존고객 주소 보완 {result.customers_address_filled}건."
                )
            _rec_done = st.session_state.get(f"legacy_purchase_reconcile::{excel_upload.name}")
            if _rec_done and getattr(_rec_done, "rows", None):
                _actor = (
                    (st.session_state.get("current_user") or {}).get("username")
                    or (st.session_state.get("current_user") or {}).get("name")
                    or "legacy_purchase_import"
                )
                for _rr in _rec_done.rows:
                    _code = _rr.get("_code") or ""
                    if _code not in ("cost_mismatch", "cost_blank", "hq_only", "app_only"):
                        continue
                    try:
                        _oid = int(_rr.get("주문ID") or 0)
                    except (TypeError, ValueError):
                        _oid = 0
                    _lvl = _rr.get("_level") or "warning"
                    _atype = {
                        "cost_mismatch": "import_cost_mismatch",
                        "cost_blank": "import_cost_blank",
                        "hq_only": "import_hq_only",
                        "app_only": "import_app_only",
                    }.get(_code, "import_cost_mismatch")
                    _msg = (
                        f"{_rr.get('고객명') or ''} {_rr.get('전화') or ''} — "
                        f"입력원가 {_rr.get('입력원가')}원 vs 본사원가 {_rr.get('본사원가')}원 "
                        f"(차이 {_rr.get('원가차이')}) · 배송 {_rr.get('배송일') or ''} · {_rr.get('결과')}"
                    )
                    try:
                        _insert_fraud_alert_to_admins(
                            db_filename, _oid, _actor, _lvl, _atype, _msg.strip(),
                            reason="매입 원장 원가 대사",
                        )
                    except Exception:
                        pass
            for _k in list(st.session_state.keys()):
                if isinstance(_k, str) and (
                    _k.startswith(f"legacy_purchase_preview::{excel_upload.name}")
                    or _k.startswith(f"legacy_purchase_confirm::{excel_upload.name}")
                    or _k.startswith(f"legacy_purchase_ct_scan::{excel_upload.name}")
                    or _k.startswith(f"legacy_purchase_decisions::{excel_upload.name}")
                    or _k.startswith(f"legacy_purchase_decision::")
                    or _k.startswith(f"legacy_purchase_reconcile::{excel_upload.name}")
                    or _k.startswith(f"legacy_purchase_gemini")
                    or _k.startswith(f"legacy_purchase_ai_merges")
                    or _k == _cache_key
                ):
                    st.session_state.pop(_k, None)


def _render_legacy_purchase_rollback(db_filename: str) -> None:
    """매입 원장 임포트 롤백 UI.

    잘못된 고객명/판매자명으로 임포트된 뒤 '이미 임포트(스킵)' 때문에 재입력이 막힐 때,
    해당 매장·연도의 `import_source=엑셀_매입원장` 주문(및 attach 라인)을 삭제한다.
    """
    try:
        import legacy_purchase_import_service as lps
    except Exception:
        return

    with st.expander("🗑️ 매입 원장 임포트 롤백 (재입력용)"):
        st.caption(
            "잘못 임포트된 데이터를 삭제한 뒤 엑셀을 다시 올릴 수 있습니다. "
            "\n\n**삭제 대상**"
            "\n- `import_source=엑셀_매입원장` 주문 (선택 연도) + 해당 라인 아이템"
            "\n- 기존 앱 주문에만 붙였던(attach) 매입 원장 라인"
            "\n- (옵션) 주문이 더 이상 없는 `source=엑셀_매입원장` 고객"
            "\n\n**삭제하지 않음**: 모모에 직접 입력한 주문, 다른 연도 임포트, 결제/매출 전표"
        )
        _store_name = _get_current_store_name_for_customers(db_filename)
        if not _store_name:
            st.error("현재 매장 정보를 확인할 수 없습니다. 사이드바에서 매장을 먼저 선택해 주세요.")
            return
        st.info(f"롤백 대상 매장: **{_store_name}** (`{db_filename}`)")

        _y_now = int((_today_kst()).year)
        _year_opts = list(range(_y_now, 2015, -1))
        _col_y, _col_opt = st.columns([1, 2])
        with _col_y:
            _year = st.selectbox("롤백 연도", _year_opts, index=_year_opts.index(2025) if 2025 in _year_opts else 0, key="purchase_rollback_year")
        with _col_opt:
            _del_orphans = st.checkbox(
                "임포트로만 생성된 고객도 삭제 (주문이 0건이 되는 경우)",
                value=True,
                key="purchase_rollback_del_orphans",
                help="source=엑셀_매입원장 이고, 롤백 후 남은 주문이 없는 고객만 삭제합니다. 모모 직접등록 고객은 건드리지 않습니다.",
            )

        _start = f"{int(_year)}-01-01"
        _end = f"{int(_year) + 1}-01-01"

        if st.button("🔍 롤백 대상 미리보기", key="purchase_rollback_preview_btn", type="primary"):
            client, err = get_supabase_client()
            if err or not client:
                st.error(f"Supabase 연결 실패: {err}")
                return
            with st.spinner("롤백 대상 집계 중…"):
                _rb_prev = lps.preview_rollback(
                    client,
                    db_filename=db_filename,
                    store_name=_store_name,
                    start_date=_start,
                    end_date=_end,
                )
            st.session_state["purchase_rollback_preview"] = _rb_prev
            st.session_state["purchase_rollback_preview_meta"] = {
                "year": int(_year), "start": _start, "end": _end, "store": _store_name, "db": db_filename,
            }

        _rb_prev = st.session_state.get("purchase_rollback_preview")
        _rb_meta = st.session_state.get("purchase_rollback_preview_meta") or {}
        if not _rb_prev:
            st.info("'롤백 대상 미리보기'를 눌러 삭제될 건수를 먼저 확인하세요.")
            return
        if _rb_meta.get("year") != int(_year) or _rb_meta.get("db") != db_filename:
            st.warning("연도 또는 매장이 변경되었습니다. 미리보기를 다시 실행해 주세요.")
            return

        if _rb_prev.errors:
            for _e in _rb_prev.errors[:5]:
                st.warning(_e)

        _m1, _m2, _m3, _m4, _m5 = st.columns(5)
        _m1.metric("삭제 예정 주문", f"{_rb_prev.order_count:,}")
        _m2.metric("주문 결제 선삭제", f"{_rb_prev.payment_count_on_orders:,}")
        _m3.metric("주문 라인 (CASCADE)", f"{_rb_prev.item_count_on_orders:,}")
        _m4.metric("attach 라인만 삭제", f"{_rb_prev.attached_item_count:,}")
        _m5.metric("orphan 고객 후보", f"{_rb_prev.orphan_customer_count:,}")

        _total = _rb_prev.order_count + _rb_prev.attached_item_count
        if _total == 0:
            st.success(f"{_year}년 매입 원장 임포트 데이터가 없습니다. 바로 재임포트할 수 있습니다.")
            return

        if _rb_prev.sample_orders:
            with st.expander(f"삭제 예정 주문 샘플 (최대 30건 / 전체 {_rb_prev.order_count:,}건)", expanded=True):
                st.dataframe(pd.DataFrame(_rb_prev.sample_orders), width="stretch", hide_index=True)

        st.markdown("#### 롤백 실행")
        _confirm_txt = st.text_input(
            f"확인을 위해 매장명 `{_store_name}` 을 그대로 입력하세요.",
            key="purchase_rollback_confirm_name",
            placeholder=_store_name,
        )
        _confirm_chk = st.checkbox(
            f"{_year}년 매입 원장 임포트 데이터 {_rb_prev.order_count:,}건 주문"
            + (f" + attach 라인 {_rb_prev.attached_item_count:,}건" if _rb_prev.attached_item_count else "")
            + (" + orphan 고객" if _del_orphans else "")
            + " 을 삭제합니다. 이 작업은 되돌릴 수 없습니다.",
            key="purchase_rollback_confirm_chk",
        )
        if _confirm_chk and _confirm_txt.strip() == _store_name:
            if st.button("🗑️ 롤백 실행 (삭제)", key="purchase_rollback_commit_btn", type="primary"):
                client, err = get_supabase_client()
                if err or not client:
                    st.error(f"Supabase 연결 실패: {err}")
                    return
                _progress = st.progress(0.0, text="시작 중…")

                def _cb(stage: str, pct: float) -> None:
                    try:
                        _progress.progress(min(1.0, max(0.0, pct)), text=f"{stage} {int(pct * 100)}%")
                    except Exception:
                        pass

                with st.spinner("롤백 삭제 중…"):
                    _rb_res = lps.commit_rollback(
                        client,
                        db_filename=db_filename,
                        store_name=_store_name,
                        start_date=_start,
                        end_date=_end,
                        delete_orphan_customers=_del_orphans,
                        progress_cb=_cb,
                    )
                _progress.progress(1.0, text="완료")
                clear_data_cache()
                # 임포트 미리보기 캐시도 무효화
                for _k in list(st.session_state.keys()):
                    if isinstance(_k, str) and (
                        _k.startswith("legacy_purchase_preview::")
                        or _k.startswith("legacy_purchase_ct_scan::")
                        or _k.startswith("legacy_purchase_decisions::")
                        or _k == "purchase_rollback_preview"
                    ):
                        st.session_state.pop(_k, None)

                _r1, _r2, _r3, _r4 = st.columns(4)
                _r1.metric("삭제된 주문", f"{_rb_res.orders_deleted:,}")
                _r2.metric("삭제된 결제", f"{_rb_res.payments_deleted:,}")
                _r3.metric("삭제된 attach 라인", f"{_rb_res.attached_items_deleted:,}")
                _r4.metric("삭제된 orphan 고객", f"{_rb_res.customers_deleted:,}")
                if _rb_res.errors:
                    for _msg in _rb_res.errors[:10]:
                        st.error(_msg)
                else:
                    st.success(
                        f"롤백 완료. 이제 위에서 매입 원장 엑셀을 다시 업로드할 수 있습니다. "
                        f"(주문 {_rb_res.orders_deleted:,} · 결제 {_rb_res.payments_deleted:,} · attach 라인 {_rb_res.attached_items_deleted:,} · 고객 {_rb_res.customers_deleted:,})"
                    )
        elif _confirm_chk and _confirm_txt.strip() and _confirm_txt.strip() != _store_name:
            st.error(f"매장명이 일치하지 않습니다. `{_store_name}` 을 정확히 입력해 주세요.")


# ---------------------------------------------------------------------------
# 품목 분류 관리 (Gemini 배치 · 관리자 전용)
# ---------------------------------------------------------------------------

@st.cache_data(ttl=180, show_spinner=False)
def _cached_taxonomy_map() -> dict[str, str]:
    """load_taxonomy_map 캐시 래퍼 (전 사용자 공유)."""
    import product_taxonomy_service as pts
    client, _ = get_supabase_client()
    if client is None:
        return {}
    return pts.load_taxonomy_map(client)


@st.cache_data(ttl=120, show_spinner=False)
def _cached_unclassified_df(db_filename: str | None, limit: int = 2000) -> pd.DataFrame:
    """미분류 product_name DataFrame (관리자 UI 캐시)."""
    import product_taxonomy_service as pts
    client, _ = get_supabase_client()
    if client is None:
        return pd.DataFrame(columns=["product_name", "빈도", "최근등장"])
    return pts.find_unclassified_product_names(client, db_filename=db_filename, limit=limit)


def _invalidate_taxonomy_caches() -> None:
    try:
        _cached_taxonomy_map.clear()
    except Exception:
        pass
    try:
        _cached_unclassified_df.clear()
    except Exception:
        pass


def render_product_taxonomy_admin() -> None:
    """품목 분류 관리 — Gemini 배치 + 수동 편집.

    - store_admin / superadmin 전용.
    - 대상 매장: 현재 세션의 current_db (없으면 '전체').
    """
    import product_taxonomy_service as pts

    current_user = st.session_state.get("current_user") or {}
    role = current_user.get("role", "user")
    if role not in ("store_admin", "superadmin"):
        st.warning("관리자만 접근할 수 있습니다.")
        return

    st.header("품목 분류 관리 (Gemini 자동 분류)")
    st.caption(
        "매입 원장에서 임포트된 라인 아이템의 품목명(product_name)을 대분류 카테고리 1개로 매핑합니다. "
        "다면분석 · 마케팅 인사이트 · AI 리포트가 이 매핑을 참조합니다."
    )

    client, err = get_supabase_client()
    if err or client is None:
        st.error(f"Supabase 연결 실패: {err}")
        return

    db_filename = st.session_state.get("current_db")
    _all_dbs = (role == "superadmin") and st.toggle("전체 매장 대상으로 조회", value=False, key="pta_all_dbs")
    scope_db = None if _all_dbs else db_filename
    if not scope_db and not _all_dbs:
        st.info("매장을 먼저 선택하거나 상단에서 '전체 매장 대상' 을 켜세요.")
        return

    # ---- 통계 ----
    with st.spinner("현황 조회 중…"):
        total_names = pts.count_all_product_names(client, db_filename=scope_db)
        tax_map = _cached_taxonomy_map()
        unclassified_df = _cached_unclassified_df(scope_db)
    classified_ct = int(pd.Series(list(tax_map.keys())).isin(pd.Series([n for n in tax_map.keys()])).sum()) if tax_map else 0
    unclassified_ct = int(len(unclassified_df))

    _c1, _c2, _c3 = st.columns(3)
    _c1.metric("등장한 품목명(고유)", f"{total_names:,}")
    _c2.metric("분류 완료", f"{len(tax_map):,}")
    _c3.metric("미분류", f"{unclassified_ct:,}")

    st.markdown("---")
    tab_new, tab_rules, tab_all = st.tabs(["미분류 · Gemini 배치", "브랜드/키워드 사전", "분류 결과 · 재분류"])

    # ======================== 미분류 · 배치 ========================
    with tab_new:
        st.subheader("미분류 목록")
        if unclassified_df.empty:
            st.success("모든 품목이 분류되었습니다. 새 임포트가 발생하면 여기에 목록이 다시 채워집니다.")
        else:
            st.caption(f"빈도(라인 등장 횟수) 내림차순 상위 {len(unclassified_df):,}건. 카테고리 열을 편집 후 [저장] 또는 [Gemini 자동 분류] 를 눌러주세요.")

            _sel_ver = st.session_state.setdefault("pta_uncls_select_version", 0)
            _sc1, _sc2, _sc3 = st.columns([1, 1, 3])
            with _sc1:
                if st.button("☑️ 전체 선택", key="pta_select_all_btn"):
                    st.session_state["pta_uncls_select_default"] = True
                    st.session_state["pta_uncls_select_version"] = _sel_ver + 1
                    st.rerun()
            with _sc2:
                if st.button("⬜ 전체 해제", key="pta_deselect_all_btn"):
                    st.session_state["pta_uncls_select_default"] = False
                    st.session_state["pta_uncls_select_version"] = _sel_ver + 1
                    st.rerun()

            edit_df = unclassified_df.copy()
            edit_df["category"] = "(미분류)"  # 편집 가능한 컬럼. 빈 문자열은 Streamlit 표시가 "None" 으로 깨져 대체 placeholder 사용
            edit_df["선택"] = bool(st.session_state.get("pta_uncls_select_default", False))

            edited = st.data_editor(
                edit_df[["선택", "product_name", "빈도", "category"]],
                column_config={
                    "선택": st.column_config.CheckboxColumn("선택"),
                    "product_name": st.column_config.TextColumn("품목명", disabled=True),
                    "빈도": st.column_config.NumberColumn("빈도", disabled=True, format="%d"),
                    "category": st.column_config.SelectboxColumn(
                        "대분류",
                        options=["(미분류)"] + pts.CATEGORIES,
                        required=True,
                    ),
                },
                hide_index=True,
                width="stretch",
                key=f"pta_uncls_editor_{st.session_state['pta_uncls_select_version']}",
            )

            _ac1, _ac2, _ac3 = st.columns([1, 1, 2])
            with _ac1:
                gemini_btn = st.button("🤖 Gemini 자동 분류 (선택 항목)", type="primary", key="pta_gemini_btn")
            with _ac2:
                save_btn = st.button("💾 저장 (수동/편집)", key="pta_manual_save")
            with _ac3:
                if st.button("🔄 목록 새로고침", key="pta_refresh"):
                    _invalidate_taxonomy_caches()
                    st.rerun()

            if gemini_btn:
                selected = edited[edited["선택"] == True]  # noqa: E712
                names = [str(n) for n in selected["product_name"].tolist() if str(n).strip()]
                if not names:
                    st.warning("먼저 [선택] 열의 체크박스로 대상을 지정하세요.")
                else:
                    api_key = (
                        os.environ.get("GEMINI_API_KEY", "")
                        or (st.secrets.get("gemini", {}).get("api_key", "") if hasattr(st, "secrets") else "")
                        or (st.secrets.get("GEMINI_API_KEY", "") if hasattr(st, "secrets") else "")
                    )
                    if not api_key:
                        st.error("GEMINI_API_KEY 가 설정되어 있지 않습니다. .streamlit/secrets.toml 의 [gemini] api_key 또는 환경변수 GEMINI_API_KEY 를 확인해 주세요.")
                    else:
                        with st.spinner(f"Gemini 분류 중… ({len(names):,}건)"):
                            _kw_rules = pts.load_keyword_rules(client)
                            gemini_out = pts.classify_with_gemini(names, api_key=api_key, extra_rules=_kw_rules)
                        # 결과 병합해 저장 페이지 세션에 보관 → 사용자가 확인 후 [저장]
                        st.session_state["pta_gemini_result"] = {
                            k: {"category": v[0], "confidence": v[1]} for k, v in gemini_out.items()
                        }
                        st.success(f"Gemini 응답 수신: {len(gemini_out):,}건. 아래 결과 표에서 확인·수정 후 [저장] 을 눌러주세요.")

            _g_res = st.session_state.get("pta_gemini_result") or {}
            if _g_res:
                st.markdown("#### Gemini 결과 (확인 후 저장)")
                st.caption("잘못 분류된 항목은 **대분류** 셀을 클릭하면 나오는 드롭다운에서 직접 수정한 뒤 [Gemini 결과 저장] 을 누르면 수정한 값이 저장됩니다.")
                res_df = pd.DataFrame([
                    {"product_name": k, "category": v["category"], "confidence": v.get("confidence")}
                    for k, v in _g_res.items()
                ])
                res_edited = st.data_editor(
                    res_df,
                    column_config={
                        "product_name": st.column_config.TextColumn("품목명", disabled=True),
                        "category": st.column_config.SelectboxColumn(
                            "대분류", options=pts.CATEGORIES, required=True,
                            help="잘못 분류된 경우 클릭해서 올바른 카테고리로 변경하세요.",
                        ),
                        "confidence": st.column_config.NumberColumn("확신도", disabled=True, format="%.2f"),
                    },
                    hide_index=True,
                    width="stretch",
                    key="pta_gemini_editor",
                )
                _sc1, _sc2 = st.columns([1, 1])
                with _sc1:
                    if st.button("💾 Gemini 결과 저장", type="primary", key="pta_gemini_save"):
                        mapping = {
                            r["product_name"]: (r["category"], r.get("confidence") or 0.9)
                            for _, r in res_edited.iterrows()
                            if r["product_name"] and r["category"] in pts.CATEGORIES
                        }
                        upserted, errors = pts.upsert_classifications(
                            client, mapping,
                            source="gemini", updated_by=current_user.get("username", ""),
                        )
                        for _msg in errors[:5]:
                            st.warning(_msg)
                        st.success(f"{upserted:,}건 저장 완료.")
                        st.session_state.pop("pta_gemini_result", None)
                        _invalidate_taxonomy_caches()
                        st.rerun()
                with _sc2:
                    if st.button("결과 폐기", key="pta_gemini_discard"):
                        st.session_state.pop("pta_gemini_result", None)
                        st.rerun()

            if save_btn:
                # data_editor 의 category 컬럼에 값이 입력된 항목을 수동 저장
                manual = edited[edited["category"].isin(pts.CATEGORIES)]
                if manual.empty:
                    st.warning("저장할 항목이 없습니다. [카테고리] 를 직접 선택하거나 [Gemini 자동 분류] 를 먼저 실행하세요.")
                else:
                    mapping = {
                        str(r["product_name"]): (str(r["category"]), None)
                        for _, r in manual.iterrows()
                    }
                    upserted, errors = pts.upsert_classifications(
                        client, mapping,
                        source="manual", updated_by=current_user.get("username", ""),
                    )
                    for _msg in errors[:5]:
                        st.warning(_msg)
                    st.success(f"수동 분류 {upserted:,}건 저장 완료.")
                    _invalidate_taxonomy_caches()
                    st.rerun()

    # ======================== 브랜드/키워드 사전 ========================
    with tab_rules:
        st.subheader("브랜드/키워드 사전")
        st.caption(
            "품목명에 **키워드가 포함되면 Gemini 호출 없이 즉시 해당 카테고리로 확정**하는 규칙입니다. "
            "'디망스'처럼 가구 종류 단어가 없는 브랜드/모델명을 등록해 두면, 사이즈·색상 코드가 붙어 "
            "문자열이 조금씩 달라도 부분일치로 전부 자동 분류됩니다. 우선순위 숫자가 작을수록 먼저 검사됩니다. "
            "\n\n**우선순위 500 기준**: 500 미만 규칙은 내장 종류 키워드(소파·식탁 등)보다 **먼저**, "
            "500 이상 규칙은 내장 규칙 **뒤에** 검사됩니다. 여러 카테고리에 걸치는 브랜드는 "
            "포괄 규칙을 900 으로 등록하세요 — 예: `디망스` → 침대 (900) 만 등록해도 "
            "'디망스소파' 는 내장 '소파' 규칙으로 올바르게 분류되고, 종류 단어가 없는 '디망스Q-1500' 만 침대로 갑니다. "
            "\n\n**AND 조합**: 키워드에 `+` 를 쓰면 모든 단어가 포함될 때만 매칭됩니다. "
            "예: `노블앙+1100` → SSDS침대 (우선순위 10), `노블앙` → 침대 (우선순위 900) 로 등록하면 "
            "'노블앙 매트리스(1100)' 은 SSDS침대, '노블앙Q-1500' 은 침대로 분류됩니다. "
            "\n\n**사전 준비**: `SUPABASE_APP_PRODUCT_KEYWORD_RULES.sql` 을 Supabase SQL Editor 에서 먼저 실행하세요."
        )

        with st.form(key="pta_kw_add_form", clear_on_submit=True):
            _kf1, _kf2, _kf3 = st.columns([2, 1, 1])
            with _kf1:
                _kw_new = st.text_input("키워드 (브랜드/모델명 · `+` AND 조합 가능)", placeholder="예: 디망스 또는 노블앙+1100")
            with _kf2:
                _kw_cat = st.selectbox("카테고리", pts.CATEGORIES)
            with _kf3:
                _kw_prio = st.number_input("우선순위", min_value=1, max_value=999, value=100, step=1)
            _kw_note = st.text_input("메모 (선택)", placeholder="예: 디망스 침대 라인업")
            _kw_reapply = st.checkbox(
                "이미 자동 분류된 기존 품목에도 즉시 적용 (관리자가 수동 확정한 분류는 보존)",
                value=True,
            )
            _kw_submit = st.form_submit_button("➕ 키워드 등록", type="primary")

        if _kw_submit:
            if not (_kw_new or "").strip():
                st.error("키워드를 입력해 주세요.")
            else:
                ok, msg = pts.save_keyword_rule(
                    client, _kw_new, _kw_cat,
                    priority=int(_kw_prio), note=_kw_note,
                    updated_by=current_user.get("username", ""),
                )
                if not ok:
                    st.error(msg)
                else:
                    _applied_msg = ""
                    if _kw_reapply:
                        _n_fixed, _re_errors = pts.reapply_keyword_rule_to_existing(
                            client, _kw_new, _kw_cat,
                            updated_by=current_user.get("username", ""),
                        )
                        for _msg in _re_errors[:5]:
                            st.warning(_msg)
                        _applied_msg = f" · 기존 분류 {_n_fixed:,}건 소급 수정"
                    _invalidate_taxonomy_caches()
                    st.success(f"키워드 '{_kw_new.strip()}' → {_kw_cat} 등록 완료{_applied_msg}.")

        rules_df = pts.load_keyword_rules_full(client)
        if rules_df.empty:
            st.info("등록된 키워드 규칙이 없습니다. 위에서 첫 키워드를 등록해 보세요.")
        else:
            st.markdown(f"##### 등록된 키워드 규칙 ({len(rules_df):,}건)")
            rules_edited = st.data_editor(
                rules_df[["keyword", "category", "priority", "note", "is_active"]].reset_index(drop=True),
                column_config={
                    "keyword": st.column_config.TextColumn("키워드", disabled=True),
                    "category": st.column_config.SelectboxColumn("카테고리", options=pts.CATEGORIES),
                    "priority": st.column_config.NumberColumn("우선순위", min_value=1, max_value=999, step=1),
                    "note": st.column_config.TextColumn("메모"),
                    "is_active": st.column_config.CheckboxColumn("활성"),
                },
                hide_index=True,
                width="stretch",
                key="pta_kw_editor",
            )
            if st.button("💾 변경사항 저장", key="pta_kw_save"):
                before = rules_df.set_index("keyword")[["category", "priority", "note", "is_active"]].to_dict("index")
                n_saved, has_err = 0, False
                for _, r in rules_edited.iterrows():
                    kw = str(r["keyword"])
                    b = before.get(kw)
                    if b is None:
                        continue
                    changed = (
                        str(b.get("category")) != str(r["category"])
                        or int(b.get("priority") or 100) != int(r["priority"] or 100)
                        or str(b.get("note") or "") != str(r["note"] or "")
                        or bool(b.get("is_active")) != bool(r["is_active"])
                    )
                    if not changed:
                        continue
                    ok, msg = pts.save_keyword_rule(
                        client, kw, str(r["category"]),
                        priority=int(r["priority"] or 100),
                        note=str(r["note"] or ""),
                        is_active=bool(r["is_active"]),
                        updated_by=current_user.get("username", ""),
                    )
                    if ok:
                        n_saved += 1
                    else:
                        has_err = True
                        st.warning(msg)
                if n_saved:
                    _invalidate_taxonomy_caches()
                    st.success(f"{n_saved:,}건 저장 완료.")
                    st.rerun()
                elif not has_err:
                    st.info("변경된 항목이 없습니다.")

            _kb1, _kb2 = st.columns(2)
            with _kb1:
                _del_kw = st.selectbox(
                    "삭제할 키워드", ["(선택)"] + rules_df["keyword"].astype(str).tolist(),
                    key="pta_kw_del_sel",
                )
                if st.button("🗑️ 키워드 삭제", key="pta_kw_del_btn") and _del_kw != "(선택)":
                    if pts.delete_keyword_rule(client, _del_kw):
                        _invalidate_taxonomy_caches()
                        st.success(f"'{_del_kw}' 삭제 완료.")
                        st.rerun()
                    else:
                        st.error("삭제 실패.")
            with _kb2:
                _re_kw = st.selectbox(
                    "기존 분류에 소급 적용할 키워드", ["(선택)"] + rules_df["keyword"].astype(str).tolist(),
                    key="pta_kw_reapply_sel",
                )
                if st.button("🔁 기존 분류에 적용", key="pta_kw_reapply_btn") and _re_kw != "(선택)":
                    _row = rules_df[rules_df["keyword"].astype(str) == _re_kw].iloc[0]
                    _n_fixed, _re_errors = pts.reapply_keyword_rule_to_existing(
                        client, _re_kw, str(_row["category"]),
                        updated_by=current_user.get("username", ""),
                    )
                    for _msg in _re_errors[:5]:
                        st.warning(_msg)
                    _invalidate_taxonomy_caches()
                    st.success(f"'{_re_kw}' → {_row['category']} 소급 적용: {_n_fixed:,}건 수정.")

    # ======================== 분류 결과 · 재분류 ========================
    with tab_all:
        st.subheader("분류 결과")
        full = pts.load_taxonomy_full(client)
        if full.empty:
            st.info("아직 분류 결과가 없습니다.")
            return

        _fc1, _fc2 = st.columns([2, 2])
        with _fc1:
            _q = st.text_input("품목명 검색 (부분일치)", key="pta_full_q")
        with _fc2:
            _cat_sel = st.multiselect("카테고리 필터", pts.CATEGORIES, key="pta_full_cat")

        view = full.copy()
        if _q.strip():
            view = view[view["product_name"].astype(str).str.contains(_q.strip(), case=False, na=False)]
        if _cat_sel:
            view = view[view["category"].isin(_cat_sel)]

        st.caption(f"표시 {len(view):,}건 / 전체 {len(full):,}건. 카테고리 열을 변경 후 [재분류 저장] 을 누르세요.")
        view_edited = st.data_editor(
            view[["product_name", "category", "source", "confidence", "updated_by", "updated_at"]].reset_index(drop=True),
            column_config={
                "product_name": st.column_config.TextColumn("품목명", disabled=True),
                "category": st.column_config.SelectboxColumn("대분류", options=pts.CATEGORIES),
                "source": st.column_config.TextColumn("출처", disabled=True),
                "confidence": st.column_config.NumberColumn("확신도", disabled=True, format="%.2f"),
                "updated_by": st.column_config.TextColumn("수정자", disabled=True),
                "updated_at": st.column_config.TextColumn("수정시각", disabled=True),
            },
            hide_index=True,
            width="stretch",
            key="pta_full_editor",
        )

        if st.button("💾 재분류 저장 (변경된 항목만)", type="primary", key="pta_override_save"):
            # 변경 diff: 원본 view 와 view_edited 의 category 비교
            before = view.set_index("product_name")["category"].to_dict()
            changed = {
                str(r["product_name"]): (str(r["category"]), None)
                for _, r in view_edited.iterrows()
                if r["product_name"] and r["category"] in pts.CATEGORIES
                and before.get(str(r["product_name"])) != str(r["category"])
            }
            if not changed:
                st.info("변경된 항목이 없습니다.")
            else:
                upserted, errors = pts.upsert_classifications(
                    client, changed,
                    source="override", updated_by=current_user.get("username", ""),
                )
                for _msg in errors[:5]:
                    st.warning(_msg)
                st.success(f"재분류 {upserted:,}건 저장 완료.")
                _invalidate_taxonomy_caches()
                st.rerun()


def render_customer_balance():
    db_filename = st.session_state.get("current_db")
    if not db_filename:
        st.warning("매장에 로그인한 후 이용하세요.")
        return
    st.header("고객 및 잔금 관리")
    current_user = st.session_state.get("current_user") or {}
    role = current_user.get("role", "user")
    tab_gen, tab_d10, tab_overdue, tab_anomaly = st.tabs([
        "1. 일반 고객 및 데이터 수정 (General)",
        "2. 미수금 (배송일 D-10 이내)",
        "3. 🚨 배송일 후 미결금액",
        "4. 🔴 초과결제 항목"
    ])
    today = _today_kst()

    # ---------- 탭 1: 일반 고객 및 데이터 수정 ----------
    with tab_gen:
        # 매입 원장 통합 임포트 — 주문 + 라인 아이템 동시 생성/attach
        _render_legacy_purchase_bulk_import(db_filename)
        # 잘못된 임포트 롤백 (엑셀 업로드 없이도 항상 표시)
        _render_legacy_purchase_rollback(db_filename)

        st.subheader("고객 검색 (이름 또는 전화번호)")
        search_query = st.text_input("이름 또는 전화번호로 검색", key="gen_search")
        if not search_query or not search_query.strip():
            st.info("고객 이름 또는 전화번호를 입력하여 검색하세요.")
            customers = pd.DataFrame()
        else:
            q = search_query.strip()
            try:
                if _supabase_orders_payments_available():
                    sc, _ = get_supabase_client()
                    if sc:
                        store_name = _get_current_store_name_for_customers(db_filename)
                        if store_name:
                            q_safe = re.sub(r"[*,]", "", q.strip())
                            or_filter = f"name.ilike.*{q_safe}*,phone1.ilike.*{q_safe}*,phone2.ilike.*{q_safe}*" if q_safe else "id.eq.-1"
                            qcq = sc.table("app_customers").select("id, name, phone1, phone2, address").eq("store_name", store_name).or_(or_filter)
                            r = qcq.order("id", desc=True).limit(50).execute()
                            customers = pd.DataFrame(r.data) if r.data else pd.DataFrame()
                        else:
                            customers = pd.DataFrame()
                    else:
                        customers = pd.DataFrame()
                else:
                    conn = get_tenant_conn(db_filename)
                    if conn:
                        try:
                            pattern = f"%{q}%"
                            cur = conn.execute(
                                "SELECT id, name, phone1, phone2, address FROM Customers WHERE name LIKE ? OR phone1 LIKE ? OR phone2 LIKE ? ORDER BY id DESC LIMIT 50",
                                (pattern, pattern, pattern),
                            )
                            customers = pd.DataFrame(cur.fetchall(), columns=["id", "name", "phone1", "phone2", "address"])
                        finally:
                            conn.close()
                    else:
                        customers = pd.DataFrame()
            except Exception:
                customers = pd.DataFrame()

        if len(customers) == 0:
            if search_query and search_query.strip():
                st.info("검색 결과가 없습니다.")
        else:
            # 동일 고객(이름+전화번호) 중복 제거 → 한 명만 표시
            customers_unique = customers.drop_duplicates(subset=["name", "phone1"], keep="first").reset_index(drop=True)
            cust_options = customers_unique["id"].tolist()

            def _fmt_cust(cid):
                row = customers_unique[customers_unique["id"] == cid]
                if len(row) == 0:
                    return str(cid)
                r0 = row.iloc[0]
                return f"{r0.get('name') or '-'} ({r0.get('phone1') or '-'})"

            selected_cid = st.selectbox(
                "고객 선택",
                cust_options,
                format_func=_fmt_cust,
                key="gen_customer_select"
            )
            if selected_cid:
                cid = selected_cid
                # 선택된 고객과 동일한 전화번호를 가진 모든 customer_id 수집.
                # (이름 접두어/오타로 같은 사람이 다중 등록된 케이스 대응 → 주문 통합 조회)
                sel_row = customers_unique[customers_unique["id"] == cid].iloc[0]
                _sel_name = str(sel_row.get("name") or "")
                _sel_phone = str(sel_row.get("phone1") or "").strip()
                if _sel_phone:
                    all_cids = customers[
                        customers["phone1"].fillna("").astype(str).str.strip() == _sel_phone
                    ]["id"].tolist()
                else:
                    # phone1 이 비어 있으면 이름 완전 일치로만 병합 (오작동 방지)
                    all_cids = customers[
                        customers["name"].fillna("") == _sel_name
                    ]["id"].tolist()
                if not all_cids:
                    all_cids = [cid]
                # 병합된 별칭 customer_id 를 UI 에 안내 (다른 이름으로 저장된 케이스 감지)
                if len(all_cids) > 1:
                    _alias_names = customers[customers["id"].isin(all_cids)]["name"].fillna("").unique().tolist()
                    if len(_alias_names) > 1:
                        st.info(
                            f"ℹ️ 동일 전화번호({_sel_phone})로 이름이 다르게 저장된 고객 {len(all_cids)}건을 통합 조회했습니다: "
                            + ", ".join(f"'{n}'" for n in _alias_names)
                        )

                # ── 카카오 채널 상태 배지 및 발송 UI ──────────────────
                try:
                    from customer_channel import (
                        get_customer_kakao_status,
                        send_channel_invite_sms,
                        send_manual_friendtalk,
                    )
                    _kk = get_customer_kakao_status(int(cid))
                    _kk_friend = _kk.get("kakao_friend_added", False)
                    _kk_at = str(_kk.get("kakao_friend_added_at") or "")[:16].replace("T", " ")
                    _kk_store = _get_current_store_name_for_customers(db_filename) or db_filename or ""
                    _kk_actor = _current_username()

                    _kk_col1, _kk_col2 = st.columns([2, 3])
                    with _kk_col1:
                        if _kk_friend:
                            st.success(f"💬 카카오채널 친구 ✅  ({_kk_at})" if _kk_at else "💬 카카오채널 친구 ✅")
                        else:
                            st.warning("💬 카카오채널 미연결 ⚠️")
                    with _kk_col2:
                        _kk_btn_cols = st.columns(2)
                        with _kk_btn_cols[0]:
                            if st.button("📨 채널 초대 문자 발송", key=f"kakao_invite_{cid}", width="stretch"):
                                _inv_res = send_channel_invite_sms(
                                    customer_id=int(cid),
                                    phone=_sel_phone,
                                    customer_name=_sel_name,
                                    store_name=_kk_store,
                                    sent_by=_kk_actor,
                                )
                                if _inv_res.get("status") == "sent":
                                    st.toast("채널 초대 문자가 발송되었습니다.", icon="✅")
                                elif _inv_res.get("status") == "skipped":
                                    st.warning("Solapi 설정이 없어 발송이 건너뛰어졌습니다.")
                                else:
                                    st.error(f"발송 실패: {_inv_res.get('error')}")
                        with _kk_btn_cols[1]:
                            with st.popover("💬 친구톡 직접 발송", width="stretch"):
                                _ft_body = st.text_area(
                                    "메시지 내용",
                                    placeholder=f"{_sel_name}님, 안녕하세요. 이몬스입니다.",
                                    key=f"kakao_ft_body_{cid}",
                                    height=100,
                                )
                                if st.button("발송", key=f"kakao_ft_send_{cid}", type="primary"):
                                    if not _ft_body.strip():
                                        st.error("메시지 내용을 입력하세요.")
                                    else:
                                        _ft_res = send_manual_friendtalk(
                                            customer_id=int(cid),
                                            phone=_sel_phone,
                                            customer_name=_sel_name,
                                            message_body=_ft_body.strip(),
                                            store_name=_kk_store,
                                            sent_by=_kk_actor,
                                        )
                                        if _ft_res.get("status") == "sent":
                                            st.toast("친구톡이 발송되었습니다.", icon="✅")
                                        elif _ft_res.get("status") == "not_friend":
                                            st.warning("해당 고객은 채널 친구가 아니어서 발송되지 않았습니다.")
                                        else:
                                            st.error(f"발송 실패: {_ft_res.get('error')}")
                except Exception:
                    pass  # customer_channel 미설치 환경에서도 UI가 깨지지 않도록

                if _supabase_orders_payments_available():
                    all_orders = _load_orders_supabase(
                        db_filename,
                        "id, customer_id, order_date, delivery_date, category, cost_price, total_amount, actual_margin, display_sales_amount, display_cost_amount, visit_reason, purchase_reason, employee_names, import_source",
                        limit=None,
                    )
                    orders = all_orders[all_orders["customer_id"].isin(all_cids)].copy() if not all_orders.empty and "customer_id" in all_orders.columns else pd.DataFrame()
                    payments = _load_payments_supabase(db_filename)
                else:
                    conn = get_tenant_conn(db_filename)
                    try:
                        placeholders = ",".join("?" * len(all_cids))
                        orders = pd.read_sql(
                            f"SELECT id, order_date, delivery_date, category, cost_price, total_amount, COALESCE(actual_margin,0) AS actual_margin, display_sales_amount, display_cost_amount, visit_reason, purchase_reason, employee_names FROM Orders WHERE customer_id IN ({placeholders})",
                            conn, params=tuple(all_cids)
                        )
                        payments = pd.read_sql("SELECT order_id, amount, fee_amount FROM Payments", conn)
                    finally:
                        conn.close()
                pay_sum = payments.groupby("order_id")["amount"].sum() if not payments.empty and "order_id" in payments.columns else pd.Series(dtype=float)
                if orders.empty or "id" not in orders.columns:
                    st.info("아직 등록된 주문 데이터가 없습니다.")
                else:
                    orders = orders.copy()
                    orders["paid"] = orders["id"].map(pay_sum).fillna(0)
                    orders["balance"] = orders["total_amount"] - orders["paid"]
                    orders = _zero_pre_april_2026_import_balance(orders, "balance")
                    orders["delivery_date"] = pd.to_datetime(orders["delivery_date"], errors="coerce")
                    # 일반판매가 = total_amount - display_sales_amount
                    if "display_sales_amount" in orders.columns:
                        orders["일반판매가"] = (orders["total_amount"].fillna(0) - orders["display_sales_amount"].fillna(0)).clip(lower=0)
                        orders["전시판매가"] = orders["display_sales_amount"].fillna(0)
                        disp_cols = ["id", "order_date", "delivery_date", "category", "일반판매가", "전시판매가", "total_amount", "cost_price", "paid", "balance"]
                        show_cols = [c for c in disp_cols if c in orders.columns]
                        num_cols = [c for c in ["일반판매가", "전시판매가", "total_amount", "cost_price", "paid", "balance"] if c in orders.columns]
                        disp_df = orders[show_cols].copy()
                        disp_df = disp_df.rename(columns={"id": "주문ID", "order_date": "계약일", "delivery_date": "배송일"})
                        st.dataframe(_format_df_display(disp_df, num_cols), width='stretch')
                    else:
                        num_cols = [c for c in ["cost_price", "total_amount", "paid", "balance"] if c in orders.columns]
                        disp_df = orders.copy().rename(columns={"id": "주문ID", "order_date": "계약일", "delivery_date": "배송일"})
                        st.dataframe(_format_df_display(disp_df, num_cols), width='stretch')
                    # ── 상담 이력 (app_chat_history + app_leads) ──────────────
                    with st.expander("💬 상담 이력", expanded=False):
                        _render_chat_history_section(cid, _sel_phone, _sel_name)

                    # 선택된 주문의 변경 이력 보기
                    with st.expander("선택 주문 변경 이력 보기"):
                        def _fmt_order_hist(oid):
                            r = orders[orders["id"] == oid].iloc[0]
                            od = r.get("order_date") or ""
                            dlv = r.get("delivery_date") or ""
                            od_str = od.strftime("%Y-%m-%d") if hasattr(od, "strftime") else str(od)[:10]
                            dlv_str = dlv.strftime("%Y-%m-%d") if hasattr(dlv, "strftime") else str(dlv)[:10]
                            return f"주문 #{oid} | 계약일 {od_str} | 배송일 {dlv_str}"
                        hist_oid = st.selectbox("주문 선택 (변경 이력 조회용)", orders["id"].tolist(), format_func=_fmt_order_hist, key="gen_order_history_sel")
                        if hist_oid:
                            _render_order_audit_trail(db_filename, int(hist_oid))

                    with st.expander("📝 주문 수정 & 결제 관리", expanded=False):
                        cust_row = customers_unique[customers_unique["id"] == cid].iloc[0]
                        edit_prefix = f"edit_c{cid}"
                        _db_name = str(cust_row.get("name") or "")
                        _db_phone1 = str(cust_row.get("phone1") or "")
                        _db_phone2 = str(cust_row.get("phone2") or "")
                        _db_addr = str(cust_row.get("address") or "")
                        if not st.session_state.get(f"{edit_prefix}_name"):
                            st.session_state[f"{edit_prefix}_name"] = _db_name
                        if not st.session_state.get(f"{edit_prefix}_phone1"):
                            st.session_state[f"{edit_prefix}_phone1"] = _db_phone1
                        if f"{edit_prefix}_phone2" not in st.session_state:
                            st.session_state[f"{edit_prefix}_phone2"] = _db_phone2
                        if f"{edit_prefix}_address" not in st.session_state:
                            st.session_state[f"{edit_prefix}_address"] = _db_addr
                        def _fmt_order_sel(oid):
                            r = orders[orders["id"] == oid]
                            if r.empty:
                                return f"주문 #{oid}"
                            row = r.iloc[0]
                            od = row.get("order_date", "")
                            dlv = row.get("delivery_date", "")
                            od_str = od.strftime("%Y-%m-%d") if hasattr(od, "strftime") else str(od or "-")[:10]
                            dlv_str = dlv.strftime("%Y-%m-%d") if hasattr(dlv, "strftime") else str(dlv or "-")[:10]
                            return f"주문 #{oid} | 계약일 {od_str} | 배송일 {dlv_str}"
                        order_options = orders["id"].tolist()
                        sel_oid = st.selectbox("수정할 주문 선택", order_options, format_func=_fmt_order_sel, key=f"{edit_prefix}_order_sel")
                        if sel_oid:
                            orow = orders[orders["id"] == sel_oid].iloc[0]
                            # 재초기화 조건: OID 변경, 키 미존재, 또는 DB에 금액이 있는데 세션 상태가 0/빈값인 경우
                            # 0원 입력(주문 취소 정리)을 허용하기 위해 값이 0인지로 초기화 여부를 판단하지 않는다.
                            _need_order_init = (
                                st.session_state.get(f"{edit_prefix}_oid") != sel_oid
                                or f"{edit_prefix}_general_sales" not in st.session_state
                                or f"{edit_prefix}_cost" not in st.session_state
                                or f"{edit_prefix}_display_sales" not in st.session_state
                                or f"{edit_prefix}_display_cost" not in st.session_state
                            )
                            if _need_order_init:
                                # NaN/None/pd.NA 안전 변환 헬퍼
                                def _safe_float(v):
                                    try:
                                        f = float(v)
                                        return f if (f == f) else 0.0  # NaN 체크 (NaN != NaN)
                                    except Exception:
                                        return 0.0

                                dval = orow["delivery_date"]
                                if pd.notna(dval) and hasattr(dval, "date"):
                                    st.session_state[f"{edit_prefix}_delivery"] = dval.date()
                                else:
                                    st.session_state[f"{edit_prefix}_delivery"] = today
                                _disp_sales_val = _safe_float(orow.get("display_sales_amount"))
                                _disp_cost_val = _safe_float(orow.get("display_cost_amount"))
                                _total_val = _safe_float(orow.get("total_amount"))
                                _cost_val = _safe_float(orow.get("cost_price"))
                                _general_sales_val = max(0.0, _total_val - _disp_sales_val)
                                st.session_state[f"{edit_prefix}_general_sales"] = _format_number_comma(str(int(_general_sales_val)))
                                st.session_state[f"{edit_prefix}_cost"] = _format_number_comma(str(int(_cost_val)))
                                st.session_state[f"{edit_prefix}_display_sales"] = _format_number_comma(str(int(_disp_sales_val)))
                                st.session_state[f"{edit_prefix}_display_cost"] = _format_number_comma(str(int(_disp_cost_val)))
                                st.session_state[f"{edit_prefix}_has_display"] = _disp_sales_val > 0
                                st.session_state[f"{edit_prefix}_visit"] = str(orow.get("visit_reason") or "")
                                st.session_state[f"{edit_prefix}_purchase"] = str(orow.get("purchase_reason") or "")
                                _existing_emps = [e.strip() for e in str(orow.get("employee_names") or "").split(",") if e.strip()]
                                st.session_state[f"{edit_prefix}_employees"] = _existing_emps
                                # 카테고리 multiselect도 선택 주문 기준으로 초기화
                                CATEGORY_OPTIONS_EDIT_INIT = ["옷장", "식탁", "자녀방", "침대", "SSDS침대", "서재_학생", "소파", "소품", "전시품"]
                                _init_cats = [x.strip() for x in str(orow.get("category") or "").split(",") if x.strip() and x.strip() in CATEGORY_OPTIONS_EDIT_INIT]
                                st.session_state[f"{edit_prefix}_category_multiselect"] = _init_cats
                                # 초기화 완료 후 _oid 설정 (중간 실패 시 다음 렌더에서 재시도되도록)
                                st.session_state[f"{edit_prefix}_oid"] = sel_oid

                            # ── 섹션 1: 주문 정보 수정 ──
                            st.markdown("#### 📋 주문 정보 수정")
                            st.text_input("고객명", key=f"{edit_prefix}_name")
                            st.text_input("Phone 1", key=f"{edit_prefix}_phone1")
                            st.text_input("Phone 2", key=f"{edit_prefix}_phone2")
                            st.text_area("주소", key=f"{edit_prefix}_address")
                            st.date_input("배송일 *", key=f"{edit_prefix}_delivery")
                            CATEGORY_OPTIONS_EDIT = ["옷장", "식탁", "자녀방", "침대", "SSDS침대", "서재_학생", "소파", "소품", "전시품"]
                            # 세션 상태(_need_order_init 블록)에서 이미 초기화되므로 default= 사용 안 함
                            selected_categories_edit = st.multiselect(
                                "품목/카테고리 (복수 선택)",
                                options=CATEGORY_OPTIONS_EDIT,
                                key=f"{edit_prefix}_category_multiselect",
                            )
                            category_edit_val = ",".join(selected_categories_edit) if selected_categories_edit else None

                            # ── 금액 정보 (새 판매 등록폼과 동일 구조) ──
                            st.markdown("#### 💰 금액 정보")
                            def _fmt_general_sales():
                                st.session_state[f"{edit_prefix}_general_sales"] = _format_number_comma(st.session_state.get(f"{edit_prefix}_general_sales", ""))
                            def _fmt_edit_cost():
                                st.session_state[f"{edit_prefix}_cost"] = _format_number_comma(st.session_state.get(f"{edit_prefix}_cost", ""))
                            def _fmt_display_sales():
                                st.session_state[f"{edit_prefix}_display_sales"] = _format_number_comma(st.session_state.get(f"{edit_prefix}_display_sales", ""))
                            def _fmt_display_cost():
                                st.session_state[f"{edit_prefix}_display_cost"] = _format_number_comma(st.session_state.get(f"{edit_prefix}_display_cost", ""))
                            st.text_input("일반제품 판매가(Selling Price)", key=f"{edit_prefix}_general_sales", on_change=_fmt_general_sales)
                            st.text_input("일반제품 원가(Cost)", key=f"{edit_prefix}_cost", on_change=_fmt_edit_cost)
                            has_display_edit = st.checkbox(
                                "전시품 포함",
                                value=st.session_state.get(f"{edit_prefix}_has_display", False),
                                key=f"{edit_prefix}_has_display_chk",
                            )
                            if has_display_edit:
                                st.text_input("전시품 판매가", key=f"{edit_prefix}_display_sales", on_change=_fmt_display_sales)
                                st.text_input("전시품 원가", key=f"{edit_prefix}_display_cost", on_change=_fmt_display_cost)

                            # 실시간 합산 표시
                            _edit_general_sales = _parse_comma_to_int(st.session_state.get(f"{edit_prefix}_general_sales", "0"))
                            _edit_cost = _parse_comma_to_int(st.session_state.get(f"{edit_prefix}_cost", "0"))
                            _edit_display_sales = _parse_comma_to_int(st.session_state.get(f"{edit_prefix}_display_sales", "0")) if has_display_edit else 0
                            _edit_display_cost = _parse_comma_to_int(st.session_state.get(f"{edit_prefix}_display_cost", "0")) if has_display_edit else 0
                            _edit_total = _edit_general_sales + _edit_display_sales
                            _edit_total_cost = _edit_cost + _edit_display_cost
                            _edit_basic_margin = _edit_total - _edit_total_cost
                            _edit_basic_margin_rate = (_edit_basic_margin / _edit_total * 100) if _edit_total else 0.0
                            st.markdown("**합산 금액 (실시간)**")
